local P = LoreForeverPacks.Begin("LoreForever_Lang_svSE")
P.entries["item:99-year-old-port"] = {n="99-Year-Old Port",s="99-Year-Old Port är en synnerligen sällsynt flaska årgångssprit som skickades från Booty Bay som personlig gåva till Gazlowe. Efter en lastolycka vid Ratchets kajer rycktes den åt sig av en galning vid namn Mad Magglish, som flydde in i de slingrande tunnlarna utanför Wailing Caverns.",h="99-Year-Old Port är en synnerligen sällsynt flaska årgångssprit som skickades från Booty Bay som personlig...",kw={"99-year-old port","bigglefuzz","gazlowe","mad magglish","porter","ratchet","revilgaz","wailing caverns"},ang={["class:Rogue"]="Mad Magglish förlitar sig på amatörmässig smygteknik för att smyga omkring i mörkret utanför Wailing Caverns, men en skicklig skurk kan lätt locka fram honom ur skuggorna."},sec={{t="En värdefull last går förlorad",b="Att frakta dyrbar last över Great Sea innebär alltid risker, men Crane Operator Bigglefuzz gjorde situationen mycket värre under en vanlig morgonlossning i Ratchet. När han försökte få undan en överväldigande leverans från Booty Bay överbelastade goblinen sin kran och lät ett berg av lådor störta ner över kajerna. I kaoset ryckte stadens särling, en besvärlig figur känd som Mad Magglish, åt sig en ovanligt gammal flaska 99-Year-Old Port och rusade mot kullarna i riktning mot Wailing Caverns."},{t="Diplomatisk årgångssprit",b="Den stulna portern var ingen vanlig spritdryck. Den hade skickats av Baron Revilgaz från Blackwater Raiders som en hedersam diplomatisk gåva till Gazlowe, Ratchets chefsingenjör och härskare. Förlusten av en så värdefull försändelse hotade Bigglefuzzs försörjning och ökade spänningarna med hamnmästaren. Den svårfångade tjuven har spårats till grottornas mörka yttre hålor och lurar i skuggorna med den oöppnade dyrgripen. Det tvingar hamnarbetarna att anlita legosoldater utifrån för att hämta den innan Gazlowe upptäcker misstaget."}},faq={{q="Vem var 99-Year-Old Port ursprungligen avsedd för?",a="Flaskan skickades av Baron Revilgaz, Booty Bays herre, som en värdefull personlig gåva till Gazlowe, Ratchets boss.",al={"vem är portern till","vem får portern","gazlowes gåva"}},{q="Hur fick Mad Magglish tag på portern?",a="Crane Operator Bigglefuzz försökte lossa mer last än hans utrustning klarade av och välte lådor över Ratchets kajer. Mad Magglish utnyttjade kaoset, snodde årgångsflaskan och sprang.",al={"hur stals den","vem stal portern","olycka vid kajen"}},{q="Vart tog Mad Magglish flaskan?",a="Magglish flydde inåt land genom The Barrens och gömde sig i de klippiga förkamrarna och yttre tunnlarna som leder in i Wailing Caverns.",al={"var är mad magglish","var är portern gömd","porterns plats"}},{q="Varför hämtade inte Bigglefuzz portern själv?",a="Bigglefuzz följde efter tjuven fram till ingången till Wailing Caverns, men han var så rädd för bestarna och de korrumperade druiderna i grottorna att han vägrade gå in.",al={"varför följde bigglefuzz inte efter","kranföraren är en fegis"}}},fx={["5b0242c9"]={q="Vad är 99-Year-Old Port?",a="Det är en exceptionellt sällsynt och lagrad flaska starkvin, skeppad hela vägen från Booty Bay. Den skickades som en prestigefylld personlig gåva från Baron Revilgaz till Gazlowe, Ratchets chefsingenjör och ledare, och årgången är ett ovärderligt tecken på aktning mellan mäktiga handelsbaroner bland gobliner.",al={"vad är 99-year-old port","99-year-old port","flaska starkvin"}}},fp="16,288,24.521.0,18.522.1,50.122.0,42.205.0,39.130.0,48.164.0"}
P.entries["item:a-bloodstained-journal-page"] = {n="A Bloodstained Journal Page",s="Ett sönderrivet, blodfläckat pergament som undersöks i utredningen av Stalvan Mistmantle. Några ord går fortfarande att läsa genom det tjocka blodet, och Commander Althea Ebonlocke ber att handstilen kontrolleras.",h="Ett sönderrivet, blodfläckat pergament som undersöks i utredningen av Stalvan Mistmantle.",kw={"blodfläckad","daltry","darkshire","duskwood","ebonlocke","handstil","journal","stalvan"},ang={["faction:Alliance"]="För rikets beskyddare är det här dystra dokumentet ett bevis som Darkshires Night Watch undersöker under utredningen."},sec={{t="Ett dystert bevis",b="Commander Althea Ebonlocke håller vaksam uppsikt över Darkshire och ber att handstilen på den här sönderrivna, blodstänkta sidan undersöks. Trots det tjocka blodet går några ord fortfarande att läsa, så Clerk Daltry kan jämföra dem med stadsregistret."},{t="Handstil och skuld",b="För att undanröja varje tvivel innan rättvisan skipas förlitar sig Commander Ebonlocke på Clerk Daltry, som ansvarar för Darkshires stadsregister i rådhuset. Många år av arkivering av kommunala namnteckningar har gjort Daltry till en auktoritet på lokal handstil. När han granskar det blodfläckade bladet mot de kommunala handlingarna bekräftar Daltry slutgiltigt att handstilen är Stalvans och beseglar därmed lärarens skuld."}},faq={{q="Vad är den här blodfläckade journalsidan?",a="Det är ett sönderrivet, blodfläckat blad med koppling till utredningen av Stalvan Mistmantle. Commander Althea Ebonlocke ber Clerk Daltry att undersöka handstilen.",al={"blodfläckad journalsida","stalvans journalsida","blodig sida"}},{q="Vem kan bekräfta vem som skrev den här sidan?",a="Clerk Daltry i Darkshires rådhus. Som ansvarig för stadsregistret jämför han skriften på sidan med gamla namnteckningar i arkivet för att bekräfta Stalvans handstil.",al={"vem läser sidan","clerk daltry journal","vem identifierar handstil"}},{q="Varför behöver Althea Ebonlocke få den här sidan undersökt?",a="Commander Althea har hållit ögonen på Stalvan en tid och vill att Clerk Daltry jämför sidan med stadsregistret. Hon behöver fastställa om båda skrevs av samma hand.",al={"varför althea behöver sidan","varför kontrollera handstil"}},{q="Vart leder den här sidan i utredningen?",a="Sidan tas till Clerk Daltry i Darkshire så att han kan jämföra handstilen med registret. Efter undersökningen fortsätter utredningen tillsammans med Commander Ebonlocke.",al={"vad händer efter sidan","nästa del av stalvans uppdrag"}}},fx={e0fa872a={q="Var kommer Bloodstained Journal Page ifrån, och vem skrev den?",a="Sidan är en avriven del av Stalvan Mistmantles personliga dagbok. De ord som finns kvar beskriver hans förtvivlan och hans avsikt att spilla blod.",al={"vem skrev bloodstained journal page","varifrån kommer stalvans dagbokssida","var kommer den blodiga dagbokssidan ifrån"}}},fp="27,228,24.230.0,21.239.1,39.161.0,36.173.0,50.190.0,47.173.1"}
P.entries["item:a-clue-to-sanders-treasure"] = {n="A Clue to Sanders' Treasure",s="I Westfall bär en väderbiten pergamentbit spåren efter den ökände piratkaptenen Captain Sanders. Den visar det andra steget i en skattjakt bland klippor och längs kusten.",h="I Westfall bär en väderbiten pergamentbit spåren efter den ökände piratkaptenen Captain Sanders.",kw={"tunna","skorsten","ledtråd","pirat","sanders","skatt","westfall"},sec={{t="En pirats gåta",b="När du följer Captain Sanders första skattkarta hittar du ett pergament som pekar längre inåt land i Westfall. Den klottrade anteckningen leder dig österut från kusten, uppför klipporna mot huvudvägen. Nära förfallna stenruiner och en övergiven skorsten visar en gammal tunna var Sanders gömde nästa ledtråd och lockar skattsökare djupare in i de oroliga jordbruksmarkerna."}},faq={{q="Vad är den här ledtråden?",a="Captain Sanders lämnade en handskriven anteckning som vägleder alla som är kloka nog att följa hans spår till ännu en gömd behållare i Westfall.",al={"sanders ledtråd","ledtråd till sanders skatt","vad är en ledtråd till sanders skatt"}},{q="Vart leder ledtråden?",a="Ledtråden leder dig österut från kusten och uppför klipporna mot vägen i Westfall. En gammal tunna står nära en ruinerad skorsten.",al={"vart ska jag gå","ledtrådens mål","skorstenens plats"}},{q="Vem var Captain Sanders?",a="Captain Sanders var en pirat. Hans arv lever kvar i skattgömmorna och gåtorna han gömde längs Westfalls stränder och landsbygd.",al={"vem är captain sanders","sanders historia","captain sanders"}}},fx={e66b6229={q="Var kommer den här ledtråden ifrån, och vem skrev den?",a="Den här skrivna lappen lämnades av Captain Sanders, en ökänd sjörövare som begravde sitt olagliga byte runt om i Westfall. I stället för att lämna en direkt karta till skatten skrev den listige sjökaptenen en kedja av gåtor och anvisningar och gömde varje meddelande vid landmärken längs kusten för att pröva alla som var djärva eller kloka nog att följa hans spår.",al={"vem skrev sanders ledtråd","var kommer ledtråden ifrån","ledtrådens ursprung"}},["4dc920ed"]={q="Varför är den här ledtråden värdefull för skattjägare?",a="För sig själv är pergamentet bara ett gåtfullt rim, men för den som hoppas på en förmögenhet är det ett viktigt steg mot Captain Sanders mytomspunna gömda skatt. Följer du anvisningarna hittar du nästa ledtråd i hans invecklade skattjakt och kan till sist göra anspråk på de rikedomar som piratkaptenen gömde undan.",al={"varför vill någon ha sanders ledtråd","varför är ledtråden viktig","vad är sanders ledtråd bra för"}}},fp="27,167,17.361.0,18.134.0,26.124.0,24.133.0"}
P.entries["item:a-dusty-unsent-letter"] = {n="A Dusty Unsent Letter",s="A Dusty Unsent Letter är ett bortglömt pergament som hittats i en gammal fotkista i Westfall. Det ger viktiga bevis för att den svårfunne Stalvan Mistmantle bodde i Moonbrook innan han försvann.",h="A Dusty Unsent Letter är ett bortglömt pergament som hittats i en gammal fotkista i Westfall.",kw={"clerk daltry","darkshire","a dusty unsent letter","forlorn spirit","moonbrook","stalvan mistmantle","stalvans legend"},ang={["faction:Alliance"]="Genom att lägga pusslet kring Stalvans väg kan Darkshire föra korrekta register över resande och utstötta som vandrar mellan mänskliga bosättningar från Westfall till Duskwood."},sec={{t="En ledtråd i dammet",b="När de letar efter den mystiske Stalvan Mistmantles förflutna hittar utredare detta oskickade brev undanstoppat i en gammal fotkista i Moonbrook. I Darkshires stadsregister stod Moonbrook Schoolhouse fortfarande som hans senaste adress, och Clerk Daltry ville veta om han verkligen hade bott där. Denna obesvarade korrespondens är den saknade länken och bekräftar att Stalvan bodde en tid i Westfall. Men fyndet väcker också olycksbådande frågor, eftersom det stör en hämndlysten Forlorn Spirit som med bitter illvilja vaktar resterna av Stalvans förflutna."},{t="Uppdatera registret",b="När brevet överlämnas till Clerk Daltry i stadshuset i Darkshire blir det konkreta bevis som kan uppdatera stadens register. Daltry påpekar hur märkligt det är att brevet aldrig skickades, vilket antyder de plötsliga avfärder och den hemlighetsfulla väg Stalvan lämnade efter sig genom Alliansens södra kungariken."}},faq={{q="Var hittar man brevet?",a="Brevet hittas i en övergiven fotkista i Moonbrook i Westfall, gömt bland de förfallna hus som nu tagits över av Defias Brotherhood.",al={"brevets plats","var man hittar det dammiga oskickade brevet","brevet i moonbrook"}},{q="Varför skickades brevet aldrig?",a="De exakta skälen är fortfarande oklara, men Clerk Daltry tycker att det är mycket misstänkt. Det tyder på att Stalvan Mistmantle kan ha flytt Moonbrook i hast eller lämnat sin korrespondens bakom sig innan han drog vidare.",al={"varför det aldrig skickades","stalvans oskickade brev","vem brevet var till"}},{q="Vem behöver se brevet?",a="Brevet måste lämnas till Clerk Daltry, som sköter stadens register i stadshuset i Darkshire.",al={"vem jag ska lämna brevet till","clerk daltrys brev","lämna in brevet"}},{q="Varför anfaller en ande när man hittar det?",a="När fotkistan störs kallas en Forlorn Spirit, förbunden med Stalvans hemsökande arv, fram. Den går till angrepp mot alla som rotar i hans bortglömda liv och drabbar inkräktare med den försvagande Curse of Stalvan.",al={"forlorn spirit","varför anden dyker upp","curse of stalvan"}}},fx={f7d2f799={q="Vad är A Dusty Unsent Letter?",a="Det här slitna pergamentet är ett osänt brev som ligger undangömt i en gammal kista i Moonbrook. Det är ett påtagligt bevis på att den svårfångade Stalvan Mistmantle en gång bodde i bosättningen i Westfall, innan han försvann ur lokalhistorien.",al={"a dusty unsent letter","vad är a dusty unsent letter","osänt brev i moonbrook"}},["9d1bfc16"]={q="Var kommer A Dusty Unsent Letter ifrån, och vem skrev det?",a="Brevet lämnades i Moonbrook och förvarades i en kista i den övergivna staden. Stalvan Mistmantle skrev det under sin tid i Westfall för att hålla kontakt med personer utanför byn, men av okänd anledning övergavs det innan det hann skickas.",al={"vem skrev det dammiga osända brevet","var kommer brevet ifrån","det dammiga brevets ursprung"}},ab0e7a8a={q="Varför vill någon ha A Dusty Unsent Letter?",a="Clerk Daltry i Darkshire behöver officiella bevis för att uppdatera stadens register om Stalvan Mistmantle. Eftersom det finns luckor i stadens arkiv bekräftar brevet att Stalvan bodde i Moonbrook, så att Daltry kan dokumentera hans tidigare förehavanden ordentligt.",al={"vem vill ha det dammiga osända brevet","varför spara det dammiga brevet","varför lämna brevet till daltry"}}},fp="21,195,18.451.0,21.235.1,27.130.0,30.189.0,29.98.0,41.199.0"}
P.entries["item:a-faded-journal-page"] = {n="A Faded Journal Page",s="A Faded Journal Page är ett gammalt pergament som hämtats ur en kista på övervåningen i Marshal Haggards avskilda hem i Elwynn Forest. Det är en viktig ledtråd när man nystar upp den mörka historien kring Stalvan Mistmantle.",h="A Faded Journal Page är ett gammalt pergament som hämtats ur en kista på övervåningen i Marshal Haggards...",kw={"darkshire","elwynn forest","faded journal page","marshal haggard","smitts","stalvan"},ang={["faction:Alliance"]="Den här bortglömda anteckningen hjälper till att lösa ett gammalt mysterium som har oroat invånarna på båda sidor av floden mellan Elwynn och Duskwood."},sec={{t="Pergamentet i kistan",b="Det här väderbitna pergamentet lämnades kvar i en gammal kista när den pensionerade Marshal Haggard bosatte sig nära Elwynn Forests östra gräns. Där låg det orört i åratal. Eftersom Haggards försämrade syn hindrade honom från att tyda texten blev sidan liggande utan tillsyn, tills äventyrare som undersökte legenden om Stalvan Mistmantle hittade den."},{t="Spåret till Darkshire",b="Trots att Haggard inte kunde läsa den sköra texten hänvisade han utredarna över floden till Scarlet Raven Tavern i Duskwood. Krögaren Tavernkeep Smitts kände genast igen den säregna handstilen när han undersökte sidan och knöt journalanteckningen direkt till den dystra saga som hemsöker trakten."}},faq={{q="Var hittar man A Faded Journal Page?",a="Sidan hittas i en kista på övervåningen i huset nära Marshal Haggard, i östra Elwynn Forest vid flodgränsen mot Duskwood.",al={"sidans plats","var finns faded journal page","kistans plats"}},{q="Varför kunde Marshal Haggard inte läsa sidan själv?",a="Marshal Haggard är en åldrad veteran vars syn har försämrats betydligt. Han är nästan blind och kan inte tyda den bleknade skriften på pergamentet.",al={"varför läste inte haggard den","marshal haggards blindhet"}},{q="Vem känner igen handstilen på journalbladet?",a="Tavernkeep Smitts, krögaren på Scarlet Raven Tavern i Darkshire, känner genast igen handstilen när han får se sidan.",al={"vem känner igen handstilen","vem läser sidan"}},{q="Vad vaktar kistan som innehåller sidan?",a="När man öppnar kistan på övervåningen störs en fientlig Forlorn Spirit, som angriper utredarna innan sidan kan undersökas säkert.",al={"spöke i kistan","vad anfaller vid kistan"}}},fx={["6378278c"]={q="Vad är Faded Journal Page?",a="Det är ett åldrat, väderbitet pergament som hittats i en kista i Marshal Haggards hem. Texten har bleknat med tiden, men bevarar en autentisk anteckning med detaljer om Stalvan Mistmantles privata tankar och förehavanden. Den är en konkret ledtråd som hjälper till att nysta upp hans mörka historia.",al={"vad är faded journal page","faded journal page","information om faded journal page"}},["0f9a7ce9"]={q="Var kommer Faded Journal Page ifrån?",a="Sidan skrevs av Stalvan Mistmantle själv som en del av hans personliga dagbok. Den hamnade bland en bunt övergivna pergament i en kista på övervåningen i huset där Marshal Haggard senare slog sig ned, nära gränsen mellan Elwynn Forest och Duskwood.",al={"faded journal pages ursprung","vem skrev faded journal page","var kommer faded journal page ifrån"}},["200aee1d"]={q="Varför vill någon ha Faded Journal Page?",a="De som söker sanningen om den gåtfulla gestalten Stalvan Mistmantle behöver sidan för att pussla ihop hans förflutna. Handskriften är tydlig och att visa den för kunniga lokalbor som Tavernkeep Smitts i Darkshire kan ge viktiga ledtrådar om Stalvans historia och vistelseort.",al={"varför vill någon ha faded journal page","varför behöver man faded journal page","syftet med faded journal page"}}},fp="20,79,22.317.0,22.277.1,38.133.0,51.103.0,51.122.0,44.109.0"}
P.entries["item:a-letter-to-grelin-whitebeard"] = {n="A Letter to Grelin Whitebeard",s="Det här förseglade brevet är adresserat till Grelin Whitebeard, en erfaren dvärg som är stationerad ute i Coldridge Valleys snötäckta vildmark. Det har skickats från bergshuvudstaden Ironforge och är en sällsynt rapport med nyheter och instruktioner till den avlägsna gränsposten.",h="Det här förseglade brevet är adresserat till Grelin Whitebeard, en erfaren dvärg som är stationerad ute i...",kw={"coldridge valley","dun morogh","grelin whitebeard","ironforge","brev","postleverans"},ang={["race:Dwarf"]="Att föra rapporter över Dun Moroghs iskalla bergspass är en grundläggande uppgift för unga dvärgiska bergsbestigare och rekryter som vill göra sig ett namn."},sec={{t="En rapport från berget",b="Livet i Coldridge Valleys snötäckta dal kan vara isolerat, särskilt för dem som är stationerade bortom tryggheten i Anvilmar. Brev som detta är den viktiga länken mellan spejare och lärda ute i fält och Ironforges salar. Brevet har förts söderut längs bergsstigarna och bär med sig nyheter från huvudstaden till Grelin Whitebeards läger i vildmarken."}},faq={{q="Vem är Grelin Whitebeard?",a="Grelin Whitebeard är en dvärgisk spejare och upptäcktsresande som slagit läger i de sydöstra delarna av Coldridge Valley. Han förlitar sig på budbärare från Anvilmar för att hålla sig informerad om angelägenheter och instruktioner från Ironforge.",al={"grelin whitebeard","vem är grelin","mottagare"}},{q="Varifrån kommer brevet?",a="Brevet kommer från dvärgarnas huvudstad Ironforge och har skickats vidare genom Coldridge Valleys lokala postbud för att föras ut till fältet.",al={"brevets ursprung","vem skickade brevet","varifrån kommer det"}},{q="Vad står det i brevet?",a="Det är en kort hälsning från King Magni Bronzebeard, som inte har tid att spilla och ger Grelin tillåtelse att använda hans auktoritet för att ta itu med trollen som han finner lämpligt, särskilt om han kan hitta en snabb lösning. Grelin tar tacksamt emot den, eftersom det var ett tag sedan han fick nyheter från Ironforge.",al={"brevets innehåll","vad står det","brevtext"}}},fx={["163f292d"]={q="Vad är A Letter to Grelin Whitebeard?",a="Det är ett förseglat brev från Ironforge, som förts genom Coldridge Valley för att levereras till Grelin Whitebeard i hans läger vid vägen.",al={"vad är brevet till grelin whitebeard","brev till grelin whitebeard","vad är det här för brev"}},b0fcb20c={q="Varför vill Grelin Whitebeard ha brevet?",a="Grelin har varit stationerad i sitt läger i Coldridge Valley ett tag utan att få några nyheter från huvudstaden. Han längtar efter besked från Ironforge.",al={"varför lämna brevet till grelin","varför vill grelin ha brevet","vem vill ha brevet till grelin"}}},fp="29,173,28.297.0,25.163.0,32.134.0,26.278.0"}
P.entries["item:a-mysterious-message"] = {n="A Mysterious Message",s="Ett avlyssnat meddelande från en kurir ger Folkets milis bevis för vem som leder Defias Brotherhood i Westfall.",h="Ett avlyssnat meddelande från en kurir ger Folkets milis bevis för vem som leder Defias Brotherhood i...",kw={"blacknails","defias messenger","edwin vancleef","gryan stoutmantle","moonbrook","mystiskt meddelande","westfall"},ang={["class:Rogue"]="Det avlyssnade meddelandet ger skurkar en inblick i Defias undre världs operativa säkerhet, kurirvägar och kodade kommunikation.",["faction:Alliance"]="För Alliansens hjältar som hjälper till i Westfall bevisar det avlyssnade dokumentet att oron bland rikets jordbruk är ett beräknat uppror lett av Edwin VanCleef, inte slumpmässiga banditdåd."},sec={{t="Viskningar om Blacknails",b="Meddelandet pekar ut VanCleef som brödraskapets ledare och nämner en medhjälpare vid namn ”Blacknails”. Det större nätverket förblir dolt. När dokumentet dechiffreras får Folkets milis ett övertag att använda mot tillfångatagna ficktjuvar och hitta brödraskapets verkliga fäste."},{t="Avlyssnade order",b="En kurir som färdas mellan Defias verksamheter i Moonbrook, Gold Coast Quarry och Jangolode Mine bär meddelandet. Avlyssningen blir ett genombrott i Gryan Stoutmantles utredning. I veckor har Folkets milis misstänkt att någon styr banditupproret, men saknat säkra bevis. Meddelandet bekräftar att Edwin VanCleef leder brödraskapets verksamhet i hela Westfall genom kodade grader och mellanhänder."}},faq={{q="Vad avslöjar meddelandet för Folkets milis?",a="Meddelandet ger Gryan Stoutmantle definitiva bevis för att Edwin VanCleef leder Defias Brotherhoods verksamhet i hela Westfall och bekräftar milisens misstankar om vem som styr laglösa.",al={"vad står det i meddelandet","mystiskt meddelande historia","vad innehåller meddelandet"}},{q="Vem är Blacknails?",a="I den avlyssnade texten nämns Blacknails som en medhjälpare eller agent. Lite mer är känt om personens identitet eller vistelseort, så Blacknails hör till de skuggfigurer som verkar djupt inne i Defias nätverk.",al={"vem är blacknails","blacknails historia","defias blacknails"}},{q="Vem bär meddelandet?",a="En Defias Messenger bär meddelandet medan hen färdas längs Westfalls vägar mellan Moonbrook, Gold Coast Quarry och Jangolode Mine för att samordna banditverksamheten.",al={"vem har meddelandet","vem släpper mystiskt meddelande","defias-kurir"}},{q="Vad händer när Gryan Stoutmantle har läst det?",a="När VanCleefs roll har bekräftats börjar milisen leta efter Defias högkvarter. En tillfångatagen tjuv går med på att leda spejare till det hemliga gömstället i utbyte mot sitt liv.",al={"what comes next","stoutmantles reaktion","efter mystiskt meddelande"}}},fx={["9bec86bb"]={q="Vad är A Mysterious Message?",a="Det är ett förseglat brev som en Defias Messenger för genom Westfall. Det är adresserat till en agent vid namn Blacknails och innehåller viktig korrespondens mellan konspiratörerna som verkar i området.",al={"a mysterious message","vad är det här för meddelande","defias-lapp"}},ea5b5889={q="Var kommer A Mysterious Message ifrån, och vem skrev det?",a="Meddelandet kommer från Defias Brotherhoods högsta skikt. Det skrevs som instruktioner till deras agent Blacknails och transporterades längs kurirrutten mellan Moonbrook, Gold Coast Quarry och Jangolode Mine.",al={"vem skrev det mystiska meddelandet","vem skickade det mystiska meddelandet","det mystiska meddelandets ursprung"}},f3ab4b79={q="Varför vill Gryan Stoutmantle ha A Mysterious Message?",a="Gryan Stoutmantle och People's Militia är desperata efter att hitta Defias Brotherhoods hemliga gömställe och förstå deras befälsordning. Genom att lägga beslag på brevet får de konkreta skriftliga bevis för att Edwin VanCleef direkt leder Brotherhoods uppror.",al={"varför vill någon ha det mystiska meddelandet","varför vill stoutmantle ha meddelandet","varför hämta det mystiska meddelandet"}}},fp="20,115,22.270.1,18.436.1,54.201.1,18.205.0,25.169.0,46.173.1"}
P.entries["item:a-simple-compass"] = {n="A Simple Compass",s="Vid det nedbrända Alexston Farmstead i Westfall väntar A Simple Compass i en liten kista. Den tillhörde Baros Alexston innan han blev stadsarkitekt i Stormwind.",h="Vid det nedbrända Alexston Farmstead i Westfall väntar A Simple Compass i en liten kista.",kw={"alexston","baros","ursprung","kista","kompass","gård","stormwind","westfall"},ang={["faction:Alliance"]="När du hjälper Baros Alexston att återfå sitt minne ser du hur Defias-upproret drabbade vanliga människor. Till och med framstående ledare i Stormwind har förlorat sina familjehem i oroligheterna i Westfall.",["race:Human"]="Som människa i kungariket ser du i kompassen kontrasten mellan Stormwind Citys trygga, förgyllda gårdar och Westfalls övergivna, laglösa gränsland."},sec={{t="Ett minne från barndomen",b="Baros Alexston växte upp med att arbeta på familjens gård i Westfall. Hans enkla kompass var hans första navigationsinstrument och kan ha väckt hans intresse för geometri, ritningar och upptäcktsfärder. Defias Brotherhood plundrade och brände gården. Kompassen blev kvar i en stadig kista bland ruinerna när banditerna tog över jordbruksmarken."},{t="Känslomässigt värde",b="Baros far undkom förödelsen, men kunde inte föra familjens ägodelar i säkerhet. Kompassen är till liten nytta för en mästerbyggare bakom Stormwind Citys stenmurar, men den betyder mycket för Baros. Om den återlämnas får han tillbaka en sällsynt, orörd länk till sin enkla uppväxt och barndomens fridfulla landsbygd."}},faq={{q="Vad är A Simple Compass?",a="A Simple Compass är en enkel, icke-magisk fickkompass som Baros Alexston ägde som pojke på familjens gård i Westfall.",al={"enkel kompass","alexston-kompass","baros-kompass"}},{q="Var finns kompassen?",a="Kompassen ligger i Alexston's Chest bland de nedbrända ruinerna av Alexston Farmstead, strax väster om Sentinel Hill i Westfall.",al={"var hittar man kompassen","kompassens plats","var finns alexston-kistan"}},{q="Vem vill ha tillbaka kompassen?",a="Baros Alexston, Stormwinds stadsarkitekt, vill ha tillbaka kompassen. Han finns nära stadshuset i Cathedral Square.",al={"vem behöver kompassen","lämna in kompassen","vem äger kompassen"}},{q="Varför lämnades kompassen kvar på gården?",a="Defias fredlösa plundrade och brände Alexston-gården. Baros far flydde för sitt liv och kunde inte bära med sig familjens tyngre ägodelar, så kistan blev kvar i ruinerna.",al={"varför lämnade de kompassen","vad hände med gården"}}},fp="16,161,18.336.0,17.336.0,25.117.0,29.129.0,32.127.0,44.177.0"}
P.entries["item:a-stack-of-letters"] = {n="A Stack of Letters",s="A Stack of Letters är en liten bunt brev som förts genom bergspasset in i Coldridge Valley. Först trodde man att alla breven var till Talin Keeneye, men bunten innehåller meddelanden till flera spejare som är utposterade i den iskalla vildmarken.",h="A Stack of Letters är en liten bunt brev som förts genom bergspasset in i Coldridge Valley.",kw={"anvilmar","coldridge valley","postutdelning i coldridge valley","grelin whitebeard","bunt med brev","talin keeneye"},ang={["race:Dwarf"]="För unga bergsklättrare som ger sig ut på sina första färder i Coldridge Valley blir postutdelning mellan snötäckta läger en tidig introduktion till de hårda vägarna och de utspridda väktare som skyddar Dun Morogh."},sec={{t="Genom passet",b="Det är ett hårt arbete att nå avlägsna läger i Dun Moroghs karga berg, och postbud tar ofta hjälp av resande för att få ut post från Anvilmar. Den här bunten brev kom genom passet och var avsedd för spejare som var utposterade längre in i Coldridge Valley. Man trodde att breven bara var till Talin Keeneye vid hans läger vid sjön, men när man går igenom försändelsen hittar man meddelanden till andra utposter bland snövidderna, däribland bergsklättraren Grelin Whitebeard."}},faq={{q="Vad finns i bunten med brev?",a="Bunten innehåller personliga brev och rapporter till dvärgar som är utposterade i Coldridge Valley. Man trodde att alla breven var till Talin Keeneye nära den frusna sjön, men när man går igenom dem hittar man minst ett brev adresserat till Grelin Whitebeard.",al={"vad finns i breven","innehållet i bunten med brev","vem breven är till"}},{q="Vem skickar breven till Coldridge Valley?",a="Breven kom genom passet som leder in i Coldridge Valley och anlände till Anvilmar innan de lämnades över till en resande som var villig att ta dem vidare längs vägen.",al={"var breven kom ifrån","vem som skickade breven"}},{q="Vem får breven?",a="Först lämnas försändelsen direkt till dvärgspejaren Talin Keeneye vid hans läger intill den frusna sjön. När han går igenom bunten upptäcker han ett brev som tillhör Grelin Whitebeard.",al={"vem som får breven","mottagare av breven"}}},fx={["6f17116a"]={q="Vad är A Stack of Letters?",a="Det är en bunt brev som kom till Coldridge Valley genom bergspasset. Buntens brev anförtroddes åt dig i Anvilmar och är avsedda för lokala bergsbestigare som är utposterade i den snöiga vildmarken.",al={"vad är a stack of letters","föremålet a stack of letters","vad är det för brev"}},["9fce371d"]={q="Varför vill någon ha A Stack of Letters?",a="Bergsbestigarna som bor och patrullerar ute i kylan är beroende av regelbunden post för att hålla sig informerade. Talin Keeneye har väntat vid den frusna sjön på breven ganska länge, men vid närmare granskning visar det sig att inte alla brev i bunten enbart är till honom.",al={"varför leverera breven","varför vill talin ha breven","syftet med a stack of letters"}}},fp="18,142,16.438.0,36.227.0,44.154.0,25.149.0"}
P.entries["item:a-torn-journal-page"] = {n="A Torn Journal Page",s="A Torn Journal Page är en trasig bit pergament som hittats i en gammal fraktlåda vid kanalerna i Stormwind City. Den är en viktig fysisk ledtråd till Stalvan Mistmantles identitet och mörka historia, och knyter de dystra händelserna i Duskwood till uppgifter bevarade i Elwynn Forest.",h="A Torn Journal Page är en trasig bit pergament som hittats i en gammal fraktlåda vid kanalerna i Stormwind...",kw={"kanaler","duskwood","legenden om stalvan","marshal haggard","sealed crate","stalvan mistmantle","stormwind","trasig dagbokssida"},ang={["faction:Alliance"]="Dagbokssidan visar hur olösta brott och bortglömda dokument i Stormwind och Elwynn når ut och hemsöker Duskwoods kämpande gränstrakter."},sec={{t="En ledtråd i kanalerna",b="Detta fragment hittades gömt nära botten av en förseglad förvaringslåda vid kanalerna i Stormwind City, under gamla böcker, familjeklenoder och en keramikvas. Det låg kvar bland bortglömda personliga tillhörigheter. Handstilen på den skadade och slitna sidan har ett tydligt särdrag som pekar direkt mot Stalvan Mistmantles förflutna och får utredare att söka upp dem som fortfarande kan känna igen den som skrev den."},{t="I Mistmantles spår",b="Eftersom texten är väderbiten och svår att tyda måste sidan visas för någon som känner till rikets äldre dokument. Fyndet leder en utredare från Stormwind till Marshal Haggard, en åldrande officer som bor i Elwynn Forest. Hans syn håller på att svikta, men han minns fortfarande den säregna handstilen från ett tidigare kapitel i den tragiska Mistmantle-sagan."}},faq={{q="Var hittas den trasiga dagbokssidan?",a="Sidan hittas i en förseglad förvaringslåda som lämnats vid kanalerna i Stormwind City, begravd under bortglömda hushållsföremål, jakttroféer och en gammal keramikvas.",al={"plats för trasig dagbokssida","var hittar man trasig dagbokssida","förseglad låda stormwind"}},{q="Vems dagbok kommer sidan från?",a="Sidan ingår i Stalvan Mistmantles personliga anteckningar. Han var en tidigare lärare vars mörka förflutna och plötsliga försvinnande blev föremål för en utredning i Duskwood och Elwynn Forest.",al={"vem skrev dagbokssidan","författaren till trasig sida","vem är stalvan"}},{q="Vem kan läsa handstilen på den trasiga sidan?",a="Marshal Haggard, en äldre, nästan blind pensionerad officer som bor nära Eastvale Logging Camp i östra Elwynn Forest, känner igen handstilen från något han såg innan synen svek honom.",al={"vem ska jag ta den trasiga sidan till","vem läser den trasiga dagbokssidan","marshal haggards dagbok"}},{q="Varför spelar det någon roll för Duskwood att sidan hittas?",a="Stadsrådet i Darkshire pusslar ihop Stalvan Mistmantles historia för att avslöja sanningen bakom oroande händelser och sedan länge begravda brott knutna till hans namn.",al={"varför bryr sig duskwood om dagboken","stalvans koppling till duskwood"}}},fx={["8b619691"]={q="Vad är Torn Journal Page?",a="Torn Journal Page är ett trasigt blad som hittades gömt under gamla släktklenoder, böcker och jakttroféer i en förseglad förvaringslåda i Stormwind City. Det är ett viktigt skriftligt bevis om Stalvan Mistmantle. Den särskiljande handstilen knyter hans stillsamma liv förr till de mörka mysterier som hemsöker Duskwood.",al={"lore om torn journal page","vad är torn journal page","vad är det här för dagbokssida"}}},fp="19,143,20.357.0,28.289.1,37.164.0,38.175.0,46.202.0,45.198.0"}
P.entries["item:abercrombie-s-crate"] = {n="Abercrombie's Crate",s="Abercrombie's Crate är en försvunnen låda med ömtåliga verktyg och insamlade örter som tillhör eremiten Abercrombie. Den står övergiven nära ingången till Vul'Gol Ogre Mound i södra Duskwood, efter att den gamle mannen jagats bort av rövande ogres.",h="Abercrombie's Crate är en försvunnen låda med ömtåliga verktyg och insamlade örter som tillhör eremiten...",kw={"abercrombie","abercrombie's crate","duskwood","ogrehögen","ogretjuvar","vul'gol"},ang={["faction:Alliance"]="Att ge sig rakt in i hjärtat av Vul'Gol Ogre Mound för att hämta förlorade föremål visar hur monsterhotet mot södra Duskwood växer.",["profession:Herbalism"]="Abercrombie ger sig uppenbarligen ut i skogens mörkaste delar efter sällsynta växter, så att hämta hans botanistutrustning är välbekant arbete för traktens örtakunniga."},sec={{t="Förlorad till ogres",b="När Abercrombie vandrade långt från sin koja i västra Duskwood för att samla växter, stötte han på ett fientligt gäng ogres. Den gamle eremiten flydde för sitt liv och tappade sin låda med dyrbara instrument och insamlade växter. Ogres släpade hans tillhörigheter tillbaka till sitt fäste vid Vul'Gol Ogre Mound och lämnade den tunga kistan vårdslöst nära grottmynningen."},{t="Egendomligt innehåll",b="Abercrombie hävdar att lådan bara innehåller oskyldiga verktyg och insamlade växter, men hans hänförda och misstänksamma reaktion när den återfås antyder att något mycket mörkare döljer sig där. När han försäger sig håller eremiten nästan på att tacka ”Nec-” innan han hejdar sig, vilket väcker oroande frågor om vilken sorts hantverk de stulna verktygen egentligen var tänkta att hjälpa till med."}},faq={{q="Var ligger lådan?",a="Lådan ligger övergiven utomhus, alldeles intill grottmynningen vid Vul'Gol Ogre Mound, ett läger fullt av ogres i Duskwoods södra kullar.",al={"lådans plats","var ligger abercrombie's crate","vul'gol-lådan"}},{q="Varför förlorade Abercrombie den?",a="Abercrombie var ute och samlade örter långt från sitt hem när en grupp ogres överföll honom. Obeväpnad och vettskrämd flydde han till fots och övergav sina förnödenheter, som ogres bar tillbaka till sitt näste.",al={"hur fick ogres tag på lådan","varför ligger lådan hos ogres"}},{q="Vad finns i lådan?",a="Abercrombie beskriver innehållet som sällsynta örter och särskilda redskap för att samla in dem. Men hans egendomliga upphetsning och felsägning när han får tillbaka den antyder att den kan innehålla verktyg som är betydligt mer illavarslande än vanliga trädgårdssaxar.",al={"låtans innehåll","vad förlorade abercrombie"}},{q="Varför håller Abercrombie på att tacka ”Nec-”?",a="När Abercrombie får tillbaka sin låda slinker det ur honom: ”Tacka Nec-...” Sedan rättar han sig hastigt och tackar äventyraren. Han säger aldrig vem eller vad han nästan tackade.",al={"abercrombies nec-felsägning","vad betyder tacka nec"}}},fx={["7a42047e"]={q="Vad är Abercrombie's Crate?",a="Det är en trälåda med förnödenheter som tillhör Abercrombie, eremiten som bor i en förfallen stuga längs Duskwoods norra väg. Abercrombie hävdar att lådan innehåller sällsynta insamlade örter och ömtåliga verktyg som är oumbärliga för hans ensamma hantverk, men hans excentriska beteende och förflugna ord antyder att innehållet har betydligt mörkare användningsområden.",al={"abercrombie's crate","vad är det för låda","abercrombies låda"}},c6e454ed={q="Varför vill Abercrombie få tillbaka sin låda?",a="Abercrombie överfölls av ogres från de södra kullarna medan han samlade växter och tvingades överge sina förnödenheter för att fly. Han saknar sin utrustning och hävdar att han inte kan återuppta sin örtstudie utan den. Han lovar att om lådan återfås väntar glada och produktiva arbetsnätter.",al={"varför hämta abercrombies låda","varför vill abercrombie ha lådan","varför vill någon ha lådan"}}},fp="19,181,17.296.0,17.224.1,27.107.0,28.162.0,25.181.1,45.170.1"}
P.entries["item:admiral-proudmoore-s-orders"] = {n="Admiral Proudmoore's Orders",s="Kul Tiras styrkor håller sina kustpositioner i Durotar, och Admiral Proudmoore's Orders beskriver deras planer. Dokumenten skrevs innan Daelin Proudmoore föll vid Theramore och beskriver ett fälttåg mot horden.",h="Kul Tiras styrkor håller sina kustpositioner i Durotar, och Admiral Proudmoore's Orders beskriver deras...",kw={"benedict","durotar","kul tiras","nazgrel","order","orgrimmar","proudmoore","tiragarde"},ang={["faction:Horde"]="För horden stöder dessa dokument dem som hävdade att vapenvilor med människor inte skulle hålla. De visar att Kul Tiras styrkor avsåg att föra ett utrotningskrig från det ögonblick de landsteg.",["race:Troll"]="Som en troll från Darkspear visar dessa order att människornas närvaro längs kusten där ditt folk har sitt hem fortfarande är ett omedelbart hot."},sec={{t="Ett arv av hat",b="Admiral Proudmoore's Orders visar att Kul Tiras styrkor vid Tiragarde Keep fortfarande tänker strida. Lieutenant Benedicts garnison förvarar pappren, som beskriver långsiktiga manövrer och befästningar mot horden. Planerna visar att Daelin Proudmoores offensiv i Durotar var ett organiserat fälttåg, utformat för att fortsätta efter hans död. För horden avslöjar dokumenten Kul Tiras operationer och möjliga förstärkningar som hotar dess gränser."},{t="Överlämning till Grommash Hold",b="Hordens spejare skickar de återfunna orderna till Grommash Hold i Orgrimmar. De överlämnar dem till Nazgrel i Thralls kammare, där planerna stöder Nazgrels varning om att människor inte går att lita på och fortfarande utgör en aktiv fara. Hordens ledare har nu anledning att förbereda sig på fler angrepp längs kusten."}},faq={{q="Vad är Admiral Proudmoore's Orders?",a="Admiral Proudmoore's Orders är militära direktiv som Daelin Proudmoore utarbetade innan han föll vid Theramore. De instruerar de kvarvarande soldaterna från Kul Tiras i Durotar att befästa kustpositionerna och föra krig mot horden.",al={"proudmoores order","vad är orderna","admiralens order föremål"}},{q="Var återfanns orderna?",a="Orderna återfanns vid Tiragarde Keep i Durotar under striden mot Kul Tiras styrkor nära sydöstra kusten.",al={"var hittar jag orderna","ordrarnas plats","vem släpper orderna"}},{q="Vem behöver se orderna?",a="Nazgrel måste få se orderna. Han ger råd till krigshövding Thrall inne i Grommash Hold, i Orgrimmars Visdomens dal.",al={"vem lämnar jag in detta till","vem vill ha orderna","lämna in orderna"}},{q="Varför strider soldater från Kul Tiras fortfarande i Durotar?",a="Kul Tiras soldater stannar kvar i Durotar eftersom Lieutenant Benedict och andra förblev hängivna Admiral Proudmoores uppdrag att utrota orcherna. Hans order gav garnisonen planer på att fortsätta trakassera Durotar utan hans direkta tillsyn.",al={"varför är människor i durotar","varför är tiragarde keep fientligt","daelin är död, varför slåss de"}}},fp="27,223,18.450.0,25.295.1,37.223.0,34.129.0,30.114.0,53.238.0"}
P.entries["item:ados-fragment"] = {n="Ados Fragment",s="Ados Fragment är en inskriven stenbit som hittades vid Whelgar's Excavation i Wetlands. Tillsammans med tre andra skärvor bildar den Goaz Stone, en uråldrig relik med gåtfulla Titan-inskrifter.",h="Ados Fragment är en inskriven stenbit som hittades vid Whelgar's Excavation i Wetlands.",kw={"ados fragment","utgrävning","goaz stone","old gods","relik","titans","wetlands","whelgar"},ang={["race:Dwarf"]="För Explorer's League är det avgörande att hitta Titan-reliker som Ados Fragment för att avslöja dvärgarnas sanna ursprung och deras uråldriga skapare."},sec={{t="En bit av Goaz Stone",b="Ados Fragment grävdes fram ur de leriga dikena vid Whelgar's Excavation och är en av fyra saknade bitar som behövs för att återskapa Goaz Stone. Innan rovfåglarna tog över utgrävningsplatsen började Prospector Whelgar översätta den huvudsakliga tavlan, men upptäckte att inskrifterna tog slut vid avgörande ögonblick. De utspridda bitarna, med namnen Ados, Modr, Golm och Neru, försvann bland ruinerna och gömdes i uråldriga behållare och jordhögar bland kringströvande bestar."},{t="Titanernas skrift",b="När Ados Fragment sätts ihop med de tre andra bitarna kan Prospector Whelgar tyda hela Titan-inskriften på Goaz Stone. Den sammansatta texten nämner en storslagen gudomlig plan och en profetia om undergång, och avslöjar till sist en illavarslande förkunnelse: ”Old Gods... Chained Beneath the Land.” Detta tyder på att Titans fängslade uråldriga väsen under Azeroth för länge sedan."}},faq={{q="Vad är Ados Fragment?",a="Det är en trasig del av en uråldrig tavla som kallas Goaz Stone, upptäckt vid Whelgar's Excavation i Wetlands. Den bär inristad skrift från Titans, som formade världen.",al={"ados fragment","vad är ados","ados-fragment av goaz stone"}},{q="Var finns fragmentet?",a="Det ligger begravt på utgrävningsplatsen öster om Menethil Harbor i Wetlands, oftast inuti uråldriga reliker eller i lösa jordfläckar omgivna av territoriella rovfåglar.",al={"var finns ados fragment","ados plats","hitta ados"}},{q="Vad står det på fragmentet?",a="Fragmentet är ofullständigt på egen hand. Prospector Whelgar behöver också fragmenten Modr, Golm och Neru innan han kan fortsätta att översätta tavlan.",al={"text på ados fragment","vad står det på ados","översättning av goaz stone"}},{q="Vem vill ha fragmentet?",a="Prospector Whelgar, en dvärg från Explorer's League som leder den förstörda utgrävningsplatsen, söker efter fragmentet för att slutföra översättningen av Goaz Stone.",al={"vem behöver ados fragment","lämna in ados fragment","whelgar ados"}}},fx={f3ac27ac={q="Varifrån kommer Ados Fragment, och vem skapade det?",a="Ados Fragment är en bit av Goaz Stone som gått sönder, en uråldrig relik som grävdes fram vid utgrävningsplatsen i Wetlands. Titanerna ristade in sin gåtfulla skrift på den innan den splittrades i fyra delar bland ruinerna.",al={"ados fragments ursprung","vem skapade ados fragment","varifrån kommer ados fragment"}}},fp="13,182,25.391.0,16.352.1,26.162.0,28.179.0,27.149.1,24.148.0"}
P.entries["item:agamand-family-axe"] = {n="Agamand Family Axe",s="Agamand Family Axe är ett släktarv som bevarats i familjen Agamands krypta i norra Tirisfal Glades. Den var en gång en krigisk symbol för den välbärgade kvarnägarsläkten och eftertraktas av Coleman Farthing, som vill beröva den odöda familjen dess sista värdighet.",h="Agamand Family Axe är ett släktarv som bevarats i familjen Agamands krypta i norra Tirisfal Glades.",kw={"agamand","agamand crypt","agamand family axe","agamand mills","coleman farthing","släktklenod","tirisfal glades"},ang={["class:Warrior"]="Släktvapnen som bevarats i kryptan visar att Agamand-släkten hade krigiska traditioner vid sidan av sin rikedom och sina spannmålsförråd.",["race:Undead"]="För Forsaken är plundringen av Agamandarnas släktklenoder ett påtagligt sätt att göra upp med Lordaerons forna aristokrati, som föll lika lätt för pesten."},sec={{t="Agamandarnas vapen",b="Före det tredje kriget härskade Agamand-släkten som välbärgade jordägare över Tirisfal Glades norra kullar, med väldiga kvarnar och en privat familjekrypta. Agamand Family Axe låg bland de släktvapen som begravts med avlidna familjeöverhuvuden och krigare. Den förvarades intakt på vapenställ under jord, även när Scourge översvämmade godset och slaktade dess invånare."},{t="En hämndlysten återgäldning",b="När Scourge återuppväckte de fallna Agamandarna som viljelösa tjänare åt Lich King överlevde deras tidigare tjänare Coleman Farthing, nu som odöd, med ett bittert hat mot sina forna herrar. Farthing ger familjen skulden för sin egen död och anlitar kringvandrande Forsaken för att ta sig in i kryptan, plundra vapenställen på yxa, svärd, klubba och dolk och utplåna de sista spåren av Agamand-arvet."}},faq={{q="Var finns Agamand Family Axe?",a="Yxan ligger på ett vapenställ inne i Agamand Family Crypt, som ligger vid norra kanten av Agamand Mills i norra Tirisfal Glades.",al={"yxans plats","var finns yxan","agamand-yxans plats"}},{q="Vem vill ha Agamand Family Axe?",a="Coleman Farthing, en Forsaken som bor i Brill, vill ha vapnet och familjens dolk, klubba och svärd för att beröva sina forna herrar deras heder.",al={"vem behöver yxan","coleman farthing-uppdrag","vem vill ha agamandarnas släktklenoder"}},{q="Varför hatar Coleman Farthing familjen Agamand?",a="Agamandarna anställde Farthing medan han levde och orsakade enligt honom direkt hans död. Han hämnas genom att plundra deras krypta medan de vandrar omkring på godset som odöda tjänare.",al={"varför vill farthing ha släktklenoderna","coleman farthings bakgrund","farthings agg"}},{q="Går Agamand Family Axe att använda som vapen?",a="Nej. Yxan är en släktrelik som hämtas enbart som uppdragsmål för att bevisa att familjens gravvalv har skändats.",al={"kan jag utrusta yxan","yxans egenskaper"}}},fx={e4f67fe3={q="Vad är Agamand Family Axe?",a="Agamand Family Axe är ett arvegods och vapen som tillhör den framstående Agamand-dynastin i Tirisfal Glades. Den förvaras i familjens gravkrypta tillsammans med andra högt skattade vapen och står för släktens krigiska arv från tiden innan Scourge svepte över Lordaeron och förvandlade den levande familjen till viljelösa odöda tjänare.",al={"agamand-yxa","vad är agamand family axe","agamands arvegodsyxa"}}},fp="18,223,24.340.0,20.369.0,40.130.0,33.154.0,50.162.0,42.92.0"}
P.entries["item:agamand-family-dagger"] = {n="Agamand Family Dagger",s="Agamand Family Dagger är ett ärvt släktklenod från den fallna Agamanddynastin och vilar på vapenställningar i familjens gravkrypta i norra Tirisfal Glades. Coleman Farthing söker efter dolken och resten av familjens vapen för att beröva sina forna herrar deras sista arv och ära.",h="Agamand Family Dagger är ett ärvt släktklenod från den fallna Agamanddynastin och vilar på vapenställningar i...",kw={"agamand","agamand mills","coleman farthing","krypta","dolk","arvegods","scourge","tirisfal glades"},ang={["class:Rogue"]="Att smyga förbi de återuppståndna döda i kryptan och stjäla familjens dyrbara klingor från vapenställningar är klassisk undre världens inbrottsliga, förvandlad till en kall hämndakt.",["race:Undead"]="Agamands arvegods speglar den bittra klyftan mellan Lordaerons överlevande Forsaken och deras forna herrar, som dukade under och blev tanklösa tjänare åt Scourge."},sec={{t="Ett arv i kryptan",b="Före det tredje kriget ägde familjen Agamand vidsträckta gods och kvarnar över Tirisfal Glades böljande ängar. Liksom resten av släktens vapen överlevde Agamand Family Dagger förödelsen som Scourge orsakade, inlåst i familjens krypta norr om Agamand Mills. Dolken vaktas av rastlösa, odöda rester av hushållet och Lich Kings tanklösa undersåtar. Den står för den prestige och krigiska tradition som en gång höjde familjen över dess tjänare och arrendatorer."},{t="En hämndlysten rekvisition",b="För Coleman Farthing, en Forsaken som bor i Brill och dog i familjen Agamands tjänst, står dolken för bitter harm snarare än ädel börd. Han håller familjen direkt ansvarig för sin död och skickar äventyrare till Agamand Family Crypt för att hämta dolken tillsammans med familjens svärd, yxa och spikklubba. Genom att röva dessa ärvda vapen från graven vill Farthing beröva de nu Scourge-styrda familjeöverhuvudena deras sista rester av värdighet och utplåna minnet av Agamand helt."}},faq={{q="Vad är Agamand Family Dagger?",a="Det är ett ärvt vapen som tillhör den rika familjen Agamand i Tirisfal Glades. Det begravdes tillsammans med andra vapen i familjens krypta, som sedan dess har fallit under Scourges kontroll.",al={"agamanddolk","vad är agamanddolken","familjedolk tirisfal"}},{q="Var hittar man Agamand Family Dagger?",a="Den ligger på ett Agamand Weapon Rack djupt inne i Agamand Family Crypt, som ligger vid den norra änden av Agamand Mills i Tirisfal Glades.",al={"var hittar man agamanddolken","agamanddolkens plats","vapenställningens plats"}},{q="Varför vill Coleman Farthing ha dolken?",a="Coleman Farthing arbetade för familjen Agamand i livet och ger dem skulden för sin död. Han kräver dolken och andra arvegods för att beröva sina forna herrar deras ära och fullborda deras undergång.",al={"varför vill farthing ha dolken","farthing agamand uppdrag","varför plundra agamandkryptan"}},{q="Vilka andra vapen ingår i den här uppsättningen arvegods?",a="Förutom dolken innehåller uppsättningen Agamand Family Sword, Agamand Family Axe och Agamand Family Mace. Alla ligger utspridda på vapenställningar i familjens krypta.",al={"andra agamand-arvegods","lista över agamandvapen","vad mer finns i kryptan"}}},fp="21,203,21.427.0,22.399.0,34.160.0,41.132.0,43.185.0,47.148.0"}
P.entries["item:agamand-family-mace"] = {n="Agamand Family Mace",s="Agamand Family Mace är ett arvegods från förfäderna som förvaras i Agamand Family Crypt i norra Tirisfal Glades. Den var en gång en symbol för en förmögen dynastis stolthet i norra Lordaeron, men har blivit ett föremål för hämndlysten vedergällning som deras tidigare tjänare Coleman Farthing söker.",h="Agamand Family Mace är ett arvegods från förfäderna som förvaras i Agamand Family Crypt i norra Tirisfal...",kw={"agamand family crypt","agamand family mace","agamandarnas arvegods","agamand mills","coleman farthing","tirisfal glades"},ang={["race:Undead"]="Skändningen av Agamand-kryptorna visar hur Forsaken ofta drivs av kvarlevande oförrätter och agg från livet till att göra upp gamla räkningar."},sec={{t="Ett arv i ruiner",b="Före det tredje kriget ägde familjen Agamand vidsträckta jordbruksmarker och väderkvarnar i de norra delarna av Tirisfal Glades. Liksom den övriga regionala aristokratin föll de offer för de odödas farsot. Agamandarna återuppväcktes som viljelösa slavar i Lich Kings tjänst och vandrade genom sitt förstörda gods, medan familjens uråldriga skatter låg inlåsta i familjekryptans djup. Agamand Family Mace förvaras bland dessa vapen, ett tecken på en bortglömd ätt som nu reducerats till stapplande Scourge."},{t="En tjänares hämnd",b="Mace är ett av fyra stridsarvegods som Coleman Farthing, en tidigare anställd som anklagar familjen för sin död, är ute efter. Farthing återuppväcktes bland Forsaken och vill beröva de viljelösa Agamandarna varje spår av värdighet och ära. Genom att hämta mace tillsammans med förfädernas svärd, yxa och dolk hoppas Farthing utplåna minnet av och stoltheten över sina forna herrar från de länder de en gång styrde."}},faq={{q="Var finns Agamand Family Mace?",a="Mace förvaras på ett vapenställ inne i Agamand Family Crypt, längst i norr i Agamand Mills i Tirisfal Glades.",al={"var finns mace","agamand mace plats","hitta agamand mace"}},{q="Vem vill ha Agamand Family Mace?",a="Coleman Farthing, en Forsaken som bor i Brill, kräver mace tillsammans med familjens övriga arvegods för att göra upp med sina forna herrar.",al={"vem vill ha mace","vem tar agamand mace","coleman farthing arvegods"}},{q="Varför vill Coleman Farthing stjäla arvegodsen?",a="Farthing tjänade Agamandarna i livet och anklagar dem direkt för sin död. Att ta deras dyrbara vapen ur kryptan är hans sätt att utplåna de sista spåren av familjens heder.",al={"varför stjäla arvegodsen","coleman farthings motiv","varför hata agamandarna"}},{q="Vad hände med familjen Agamand?",a="Familjen Agamand styrde det välmående Agamand Mills i norra Lordaeron tills farsoten drabbade dem. Nu strövar deras återuppväckta lik genom godset och kryptorna som viljelösa slavar under Scourge.",al={"vilka var agamandarna","vad hände med agamandarna","agamand-lore"}}},fx={["0ef93592"]={q="Vad är Agamand Family Mace?",a="Agamand Family Mace är ett förfädersarvegods som tillhör den en gång välbärgade familjen Agamand i Tirisfal Glades. Vapnet förvaras i familjens gravkrypta tillsammans med deras andra krigiska skatter och är en kvarleva av släktens forna anseende och ära innan familjen föll för Scourge.",al={"agamand-stridsklubba","vad är agamand family mace","agamands arvegodsstridsklubba"}}},fp="19,182,16.441.0,21.402.1,41.125.0,34.141.0,52.171.0,36.194.0"}
P.entries["item:agamand-family-sword"] = {n="Agamand Family Sword",s="Agamand Family Sword är ett fläckat arvegods som förvaras i Agamand Family Crypt i norra Tirisfal Glades. Svärdet var en gång en stolt symbol för den välbärgade kvarnägarsläkten. Nu söker den Fördärvade Coleman Farthing det för att utplåna de sista spåren av sina forna herrars arv.",h="Agamand Family Sword är ett fläckat arvegods som förvaras i Agamand Family Crypt i norra Tirisfal Glades.",kw={"agamand","krypta","farthing","arvegods","kvarnar","scourge","svärd","tirisfal"},ang={["class:Warrior"]="Klingan var en gång ett polerat emblem för Lordaerons aristokrati. Nu ligger den bortglömd i en ohelgad grav, en kvarleva av förlorad krigisk stolthet.",["race:Undead"]="För de Fördärvade innebär återtagandet av föremål från Tirisfals forna adel att göra upp med ett levande förflutet som inte lyckades skydda dem."},sec={{t="Ett arv i graven",b="Före det tredje kriget hade Agamand-släkten enorma rikedomar och stort inflytande över de böljande kvarnarna i norra Tirisfal Glades. När Scourge svepte genom Lordaeron mötte familjen ett fasansfullt slut, och deras kroppar väcktes till liv som Lich Kings tanklösa trälar. Deras förfäders vapen, däribland familjens ceremoniella svärd, förseglades i Agamand Family Crypt vid kvarnarnas norra utkant. Att slita loss dessa klingor från gravställen är inte bara plundring. Det är en avsiktlig handling för att krossa varje minne och spår av den fallna familjens adelstitel."},{t="Hämnd från andra sidan graven",b="Coleman Farthing, en Fördärvad som bor i Brill, åtrår svärdet. I livet arbetade han för Agamand-familjen. Farthing hyser ett bittert agg mot sina forna herrar och lägger skulden för sin död på dem. Genom att skicka äventyrare för att hämta svärdet tillsammans med släktens förfädersyxa, dolk och stridsklubba försöker Farthing beröva de hasande Agamand-medlemmarna deras sista smula heder. Han vill se till att blodsläktens värdighet utplånas helt."}},faq={{q="Vad är Agamand Family Sword?",a="Det är ett förfädersvapen som tillhör Agamand-familjen, en framstående adelsfamilj som drev de väldiga spannmålskvarnarna i norra Tirisfal Glades innan Lordaeron föll.",al={"agamand-svärdets historia","vad är agamand family sword"}},{q="Var finns svärdet?",a="Svärdet ligger på ett vapenställ i Agamand Family Crypt, vid den norra utkanten av Agamand Mills i Tirisfal Glades. Graven vaktas av Scourge-trälar och återuppväckta medlemmar av Agamand-blodsläkten.",al={"var finns agamand-svärdet","agamand-svärdets plats"}},{q="Varför vill Coleman Farthing ha svärdet?",a="Coleman Farthing arbetade för Agamand-familjen i livet och lägger skulden för sin alltför tidiga död på dem. Han söker familjens arvegodsvapen för att beröva dem deras återstående heder och utplåna minnet av deras släkt.",al={"vem vill ha svärdet","varför vill farthing ha arvegods"}},{q="Vad hände med Agamand-familjen?",a="Agamand-familjen slaktades under Scourges invasion av Lordaeron. Till skillnad från de viljestarka Fördärvade är de avlidna familjemedlemmarna fortfarande fångna i tanklös tjänst under Lich King. De hemsöker sin förfäders egendom och krypta.",al={"vilka är agamand-familjen","agamand mills historia"}}},fp="20,216,20.491.0,31.353.1,33.165.0,27.200.0,42.188.0,36.178.0"}
P.entries["item:ahanu-s-leather-goods"] = {n="Ahanu's Leather Goods",s="Ahanu's Leather Goods är en samlad försändelse med färdig läderrustning och förnödenheter, tillverkade uppe på Thunder Bluffs mesas. Läderarbetaren Ahanu har förberett paketet, som ska till Crossroads i The Barrens för att förse kringvandrande jägare och äventyrare.",h="Ahanu's Leather Goods är en samlad försändelse med färdig läderrustning och förnödenheter, tillverkade uppe...",kw={"ahanu","crossroads","devrak","jahan hawkwing","lädervaror","tal","thunder bluff","vindryttare"},ang={["race:Tauren"]="Leveransen visar hur ett växande handelsnätverk knyter samman Mulgore, taurenfolkets förfädershem, med Hordens större områden i The Barrens."},sec={{t="Handel mellan mesas",b="Hordens försörjningslinjer är beroende av praktisk handel mellan etablerade fästen och utposterna i gränslandet. I Thunder Bluff förvandlar hantverkaren Ahanu råa hudar till färdiga kläder och utrustning och förbereder försändelsen särskilt för handel utanför Mulgore. Paketet är avsett för Jahan Hawkwing, en köpman verksam i The Barrens livliga centrum vid Crossroads. Eftersom det tar lång tid att färdas över slätterna till lands, introducerar transporten av paketet budbärare till taurenfolkets nätverk av flygande kurirer, där Tals och Devraks tränade vindryttare snabbt fraktar varor långa sträckor."}},faq={{q="Vad innehåller Ahanu's Leather Goods?",a="Paketet innehåller färdiga lädervaror som Ahanu har tillverkat av råa hudar i Thunder Bluff. De är praktisk rustning och utrustning, redo att säljas till resenärer.",al={"vad lädervarorna är","innehållet i ahanus paket","vad paketet innehåller"}},{q="Vem tar emot paketet?",a="Paketet levereras till Jahan Hawkwing vid Crossroads. Han säljer färdiga varor till strömmen av jägare, krigare och äventyrare som passerar genom centrala The Barrens.",al={"vem som får lädervarorna","vart det ska","jahan läderleverans"}},{q="Varför flygs paketet med en vindryttare?",a="Det tar tid att bära tunga handelsvaror till fots nerför hissarna och genom The Barrens. Ahanu hänvisar kurirer till Thunder Bluffs vindryttarmästare, Tal, för att visa hur bevingade kurirer snabbt kan transportera last till avlägsna utposter som Crossroads.",al={"varför paketet flygs","vindryttarleverans thunder bluff","flygmästarens paket"}}},fx={["32785653"]={q="Vad är Ahanu's Leather Goods?",a="Det är ett knippe färdiga lädervaror tillverkade i Thunder Bluff. Paketet ska till bosättningen The Crossroads i The Barrens och är avsett att försörja handeln bland de allt fler resenärer som samlas där.",al={"vad är ahanu's leather goods","föremålet ahanu's leather goods"}},["962e36b1"]={q="Varifrån kommer Ahanu's Leather Goods, och vem tillverkade dem?",a="Varorna tillverkades av Ahanu, en läderarbetare som utövar sitt hantverk högt uppe på Thunder Bluffs platåer. Han satte ihop de färdiga varorna av råhudar som skickats till honom från The Barrens.",al={"vem tillverkade ahanu's leather goods","ahanu's leather goods ursprung"}},["6d92aaf6"]={q="Varför vill någon ha Ahanu's Leather Goods?",a="Jahan Hawkwing beställde paketet för att sälja det till besökare som passerar genom The Barrens. The Crossroads har blivit ett livligt nav där vandrare, jägare och äventyrare samlas, vilket skapar stor efterfrågan på läderutrustning av god kvalitet och nytillverkad.",al={"varför leverera ahanu's leather goods","vem vill ha ahanu's leather goods"}}},fp="21,160,22.358.0,37.148.0,25.156.0,41.282.0"}
P.entries["item:alaric-s-remains"] = {n="Alaric's Remains",s="Alaric's Remains är de återfunna benen efter någon som en gång begravdes i en grund grav i Silverpine Forest. Hans rastlösa ande ber resande att bära det som återstår av honom förbi Rot Hide-gnollerna och in i tornen i Fenris Keep.",h="Alaric's Remains är de återfunna benen efter någon som en gång begravdes i en grund grav i Silverpine Forest.",kw={"alaric","alaric's remains","fenris keep","rot hide","grund grav","silverpine forest","den dolda nischen","thule ravenclaw"},ang={["class:Mage"]="Det gömda förråd som Alaric avslöjar innehåller reliker med koppling till Thule Ravenclaw och de Dalaran-utbildade arkanisterna som en gång studerade och smidde planer i Fenris Keep.",["race:Undead"]="De Forsaken resenärerna känner ofta med andar vars vila i graven har störts, men Alaric söker en fridfull avskildhet snarare än tjänst under den Mörka Damen."},sec={{t="En sista önskan",b="Kvarlevorna hittades i en anspråkslös, grund grav i Silverpine Forest och tillhör Alaric, en tidigare invånare på Fenris Isle. I stället för att ligga kvar i en oskyddad grop längtar hans ande efter platsen han höll kär i livet. Han ber den som gräver upp hans ben att lämna de illa sittande stövlarna och bära hans kvarlevor direkt in i borgen, där han söker en stilla fristad långt från asätarna som stryker omkring på fastlandet."},{t="Nischen i borgen",b="Alaric leder den som bär kvarlevorna till det sydvästra tornet i Fenris Keep, förbi de angripna nedre delarna och in i en stilla kammare. Bakom en dammig hylla finns en dold nisch med en artefakt som en gång värderades av Thule Ravenclaw och hans magikerkollegor. Som tack för en ostörd viloplats, förseglad och skyddad från de glupska Rot Hide-gnollerna, överlåter Alaric de gömda smyckena till dem som bar hans ben hem."}},faq={{q="Vem var Alaric?",a="Alaric bodde i Fenris Keep innan borgen lades i ruiner och tillbringade där det han ansåg vara sitt livs bästa dagar. Efter sin död begravdes han hastigt i en grund grav i Silverpine Forest, tills hans ande fick en förbipasserande att bära hans ben hem.",al={"vem är alaric","alarics historia","vem var den här mannen"}},{q="Vart ska Alarics kvarlevor föras?",a="Kvarlevorna ska placeras i en dold nisch bakom en dammig hylla i det sydvästra tornet i Fenris Keep, som ligger på Fenris Isle.",al={"vart ska jag föra alaric","platsen med den dammiga hyllan","var finns nischen"}},{q="Varför vill Alaric att kvarlevorna ska förseglas bakom en hylla?",a="Fenris Keep gav honom stor tröst i livet, och han vill vila innanför borgens stenväggar i stället för i ett dike. Om den dolda nischen förseglas ordentligt skyddas hans skelett också från att slukas eller skändas av Rot Hide-gnollerna som stryker omkring i borgen.",al={"varför fenris keep","varför nischen","varför gömma kroppen"}},{q="Varför sa han att stövlarna skulle lämnas kvar?",a="När Alaric bad någon hämta hans ben ur den grunda graven nämnde han i förbifarten att stövlarna ändå aldrig hade passat honom i livet, så han lät dem ligga kvar som oanvändbart skräp.",al={"lämna stövlarna","alarics stövlar","stövlarna passade aldrig"}},{q="Vad finns i den dolda nischen förutom en viloplats?",a="Den hemliga nischen innehåller ett föremål som en gång var kärt för Thule Ravenclaw och hans tidigare medarbetare, samt magiska ägodelar som Alaric gärna testamenterar till den som är villig att bära hans kvarlevor till deras viloplats.",al={"skatten i den dolda nischen","vad finns bakom hyllan","thules föremål"}}},fx={["7c652925"]={q="Vad är Alaric's Remains?",a="Det är de fysiska benen och kvarlevorna efter Alaric, en tidigare invånare i Fenris Keep som dog och begravdes hastigt i Silverpine Forest. Hans ande behåller sitt medvetande i benen och uppmanar resenärer att gräva upp honom ur jorden så att han kan få en sista, fridfull viloplats.",al={"vad är alaric's remains","alarics lik","föremålet alaric's remains"}},["6447c1c8"]={q="Varifrån kommer Alaric's Remains?",a="Du gräver upp dem ur en grov, grund grav i Silverpine Forests vildmark, utan de illa passande stövlar han begravdes i. Alaric dog ute i vildmarken, långt från sitt tidigare hem, och hans ovigda kvarlevor blev kvar i jorden tills någon grävde upp honom.",al={"var dog alaric","alarics grunda grav","vem skapade alaric's remains"}},["5f3dd52d"]={q="Varför vill Alaric få sina kvarlevor återfunna?",a="Alaric tillbringade sitt livs lyckligaste år i Fenris Keep, och han finner ingen ro i att vila i vildmarken. Han vill att hans kvarlevor förs tillbaka till borgen och placeras tryggt i en dold nisch bakom en dammig bokhylla, skyddade från de asätande Rot Hide-gnollerna som hemsöker området.",al={"varför ta alaric's remains","varför vill alaric flytta sin kropp","varför flytta alaric"}}},fp="16,177,15.334.0,22.368.1,15.228.0,42.123.0,55.211.0,41.133.0,57.177.0"}
P.entries["item:alien-egg"] = {n="Alien Egg",s="Alien Egg är en ovanlig och mystisk äggsamling som lokala vindormar vaktar i ravinerna i Thousand Needles. Trots sitt främmande utseende skyddar de inhemska ormarna äggen ursinnigt, som om de vore deras egna. Förekomsten har väckt nyfikenhet och oro hos tauren-spejarna på Freewind Post.",h="Alien Egg är en ovanlig och mystisk äggsamling som lokala vindormar vaktar i ravinerna i Thousand Needles.",kw={"alien egg","freewind post","hagar lightninghoof","thousand needles","vindorm"},ang={["class:Hunter"]="Vindormar är bland de mest vördade bestarna i Kalimdors ödemarker. Att spåra upp en av deras sällsyntaste och bäst bevakade äggsamlingar prövar jägarens alla instinkter.",["race:Tauren"]="Tauren vid Freewind Post vakar ständigt över ravinen nedanför. De ser okända varelser som ett omen eller ett direkt hot mot sin utsatta bosättning vid klippkanten."},sec={{t="En ormkull",b="Alien Egg upptäcktes vid foten av de höga spirorna söder och nordöst om Freewind Post och skiljer sig tydligt från den vanliga faunan på ravinens botten. I stället för att överge eller förstöra den märkliga äggsamlingen vaktar nålens inhemska ormar den ursinnigt, sida vid sida med sina egna bon. Hagar Lightninghoof, en modig tauren som håller vakt från höjderna vid Freewind Post, ville hämta exemplaret för att avgöra om det utgjorde ett hot mot bosättningarna på platåerna eller bara var en ovanlig variant av traktens reptilliv."},{t="Arikaras avkomma",b="När ägget förs till Freewind Post och undersöks närmare spricker det mystiska skalet genast upp. Där finns ingen utomjordisk inkräktare: ur det kommer Arikara, den röda vindormen ur taurenlegenden, som tros vara en hämndens ande. Den unga ormen lyfter snabbt och en skakad Hagar förklarar att själva hämnden har kommit till Thousand Needles. Därmed inleds en kedja händelser som får traktens försvarare att konfrontera henne."}},faq={{q="Varför kallas ägget ”alien”?",a="Ordet ”alien” används i sin traditionella betydelse, något helt främmande och obekant för de lokala tauren-spejarna, och innebär inte att ägget kom från yttre rymden. Dess färger och teckningar skiljer sig helt från vanliga vindormsäggsamlingar i Thousand Needles.",al={"namnet alien egg","varför alien","kommer det från rymden"}},{q="Var finns Alien Egg?",a="Ägget ligger på ravinens botten nära foten av mesaväggarna, både söder och nordöst om Freewind Post i Thousand Needles. Fientliga vindormar omger och vaktar det alltid.",al={"äggplats","var finns alien egg","hitta alien egg"}},{q="Varför vaktar de lokala ormarna ägget?",a="Ingen vet säkert. Ormarna vaktar ägget som om det vore ett av deras egna, och de som berättar att de har sett det har inte ens lyckats komma tillräckligt nära för att undersöka det.",al={"varför skyddar ormarna det","ormar vaktar ägget"}},{q="Vad händer när du tar ägget till Hagar Lightninghoof?",a="När du lämnar ägget till Hagar Lightninghoof vid Freewind Post kläcks det inför hans ögon. Det som flyger ut skakar Hagar så illa att han genast ber Motega Firemane om råd.",al={"lämna ägget till hagar","vad kläcks"}}},fx={["9259de71"]={q="Vad är Alien Egg?",a="Alien Egg är en ovanlig och gåtfull äggsamling som hittats bland de vilda vindormarna i Thousand Needles. Det märkliga utseendet skiljer det från vanliga ormägg i området och har väckt intresse hos spejare och schamaner vid Freewind Post. Trots att det verkar främmande skyddar de lokala ormarna det häftigt, som om det vore deras egen avkomma.",al={"vad är alien egg","information om alien egg","om alien egg"}},e10e9f00={q="Varför vill Hagar Lightninghoof ha Alien Egg?",a="Hagar Lightninghoof vid Freewind Post har hört rykten om ett märkligt ägg som vaktas av lokala ormar och som ingen av hans spejare kunnat komma nära nog för att undersöka. Av nyfikenhet och försiktighet ber han modiga äventyrare hämta ägget, så att han kan granska det själv och ta reda på vilken sorts varelse som kan kläckas ur det.",al={"varför vill någon ha alien egg","varför vill hagar ha ägget","alien eggs syfte"}}},fp="9,333,17.548.0,20.462.1,30.274.0,33.201.0,40.167.1,59.188.1"}
P.entries["item:alterac-granite"] = {n="Alterac Granite",s="Alterac Granite är en uppskattad och hållbar sten som bryts i de bergiga trakterna i norra Lordaeron, särskilt kring Darrow Hill i Hillsbrad Foothills. Mästerliga stenhuggare vördar dess enastående tålighet och ådring, och King Magni Bronzebeards kungliga stenhuggare väljer den för att hugga ett bestående minnesmärke över stupade soldater.",h="Alterac Granite är en uppskattad och hållbar sten som bryts i de bergiga trakterna i norra Lordaeron...",kw={"alterac granite","darrow hill","hillsbrad","ironforge","marblesten","sully balloo","thandol span"},ang={["profession:Mining"]="Gruvarbetare och prospektörer uppskattar Alterac Granite för dess rena brott och enastående täthet, egenskaper som skiljer den från vanlig klippsten.",["race:Dwarf"]="Dvärgiska stenhuggare sätter materialets kvalitet främst, vilket gör den här robusta bergstenen oumbärlig när en av Ironforges egna ska hedras."},sec={{t="Minnesmärkenas sten",b="När King Magni Bronzebeard beordrade ett monument till minne av Sully Balloo, en modig dvärgisk försvarare som omkom i tragedin vid Thandol Span, dög inte vanlig sten från stenbrottet. Grand Mason Marblesten, som fick i uppdrag att skulptera minnesmärket i Ironforge, insisterade på att få tag i Alterac Granite. Den är känd som en av de finaste stenarna i Eastern Kingdoms, och dess legendariska hållbarhet gör att en fallen hjältes avbild och minne kan bestå oförändrade i generationer."},{t="Bruten i farlig mark",b="Att bryta Alterac Granite är långt ifrån ett enkelt ärende. Stenen finns kring Darrow Hill i de norra delarna av Hillsbrad Foothills, nära Alteracs ruinerade områden. Regionen vimlar av fientliga vilda djur, lurande banditer från syndikatet och kvarvarande stridigheter, så det krävs djärva äventyrare som vågar sig djupt in i omstridda marker för att hämta felfria block av den rena stenen åt Ironforges hantverkare."}},faq={{q="Vad används Alterac Granite till?",a="Grand Mason Marblesten beställer Alterac Granite i Ironforge för att hugga ett kungligt minnesmärke över Sully Balloo, en dvärgisk soldat som stupade när han försvarade Thandol Span.",al={"användning av alterac granite","varför alterac granite","marblestens sten"}},{q="Var finns Alterac Granite?",a="Den hämtas från stenfyndigheter vid Darrow Hill, i den norra delen av Hillsbrad Foothills nära gränsen till Alterac.",al={"alterac granite plats","var får man tag på alterac granite","granit vid darrow hill"}},{q="Varför ville Grand Mason Marblesten ha just den här stenen?",a="Grand Mason Marblesten anser att Alterac Granite är en av de finaste och mest tåliga stenarna för stenhuggning, och att den är det enda material som duger till ett bestående kungligt monument beställt av King Magni.",al={"varför marblesten vill ha granit","varför alterac granite"}},{q="Vem var Sully Balloo?",a="Sully Balloo var en dvärgisk soldat som dog under striderna vid Thandol Span. King Magni Bronzebeard beställde ett monument till hans ära för att uppmärksamma hans uppoffring för Alliansen.",al={"sully balloo","vem dog vid thandol span"}}},fx={["9814170d"]={q="Vad är Alterac Granite?",a="Alterac Granite är en uppskattad sten av hög kvalitet från stenbrotten i de norra kullarna. Bland mästersnidare är den känd som en av de bästa stenarna för uthuggning. Den är slitstark och har en fin, jämn ådring som behövs för att skapa storslagna, beständiga monument värdiga kungliga beställningar.",al={"vad är alterac granite","föremålet alterac granite","information om alterac granite"}},["842d3593"]={q="Varifrån kommer Alterac Granite, och vem tillverkade den?",a="Alterac Granite är en natursten som bryts i Darrow Hill, vid foten av Hillsbrads kullar intill Alteracs karga berg. Den tillverkas inte av någon hantverkare utan huggs direkt ur kullarnas uråldriga berg, där den väntar på skickliga murare som kan forma den till beständiga verk.",al={"alterac granites ursprung","var bryts alterac granite","vem skapade alterac granite"}}},fp="15,256,18.420.0,17.314.0,33.156.0,35.121.0,60.174.0,21.172.0"}
P.entries["item:altered-snapjaw-shell"] = {n="Altered Snapjaw Shell",s="Vid Lushwater och The Stagnant Oasis har snapjaw-sköldpaddor förändrade skal som väcker en druids uppmärksamhet. Deras ryggsköldar kan avslöja vad sprickorna under The Barrens gör med det lokala djurlivet.",h="Vid Lushwater och The Stagnant Oasis har snapjaw-sköldpaddor förändrade skal som väcker en druids...",kw={"förändrade varelser","altered snapjaw shell","the barrens","lushwater oasis","oas-snapjaw","the stagnant oasis","tonga runetotem"},ang={["class:Druid"]="Som druid kan du studera de förvridna ryggsköldarna hos oasernas djur för att hjälpa till att identifiera den dolda obalans som stör vattnet i The Barrens."},sec={{t="Tecken på fördärv",b="Snapjaw-sköldpaddorna vid oaserna har förändrats på sätt som oroar dem som studerar landet. Man tror att sötvattenssköldpaddorna vid Lushwater och The Stagnant Oasis dricker från källor som får vatten från mystiska underjordiska sprickor. Deras förändrade ryggsköldar har fångat forskarnas uppmärksamhet vid The Crossroads. Tonga Runetotem, en tauren-druid, samlar skalen medan han försöker förstå hur landet mår. Han vill ta reda på om energier som stiger upp från djupet är en onaturlig plåga eller något märkligare."}},faq={{q="Vad har förändrat sköldpaddornas skal?",a="Snapjaw-sköldpaddorna lever i källor vid Lushwater och The Stagnant Oasis, som får vatten från djupa underjordiska sprickor. Märkliga energier som stiger upp i vattnet har förändrat varelserna som dricker där och lämnat deras ryggsköldar synligt deformerade.",al={"varför är skalen förändrade","vad är altered snapjaw shell","snapjaw-skalmutation"}},{q="Vem vill ha skalen och varför?",a="Tonga Runetotem, en druid vid The Crossroads, ber jägare samla in skalen. Han tror att förändringar hos de inhemska djuren kan avslöja vilken kraft eller fördärv som påverkar The Barrens vattenförsörjning.",al={"vem behöver altered snapjaw shells","tonga runetotem skal","lämna in uppdraget altered beings"}},{q="Var finns dessa snapjaws?",a="Snapjaw-sköldpaddor lever i vattnen och på de leriga stränderna vid Lushwater Oasis och Stagnant Oasis, söder och sydost om The Crossroads.",al={"oas-snapjaw plats","var får man tag på förändrade skal","snapjaw-skal platser"}}},fx={["1549c45f"]={q="Varifrån kommer förändrade snapjaw-skal?",a="Skalen kommer från oasernas snapjaw-sköldpaddor som lever kring The Barrens sötvattenkällor, särskilt vid Lushwater Oasis och Stagnant Oasis. Deras märkliga tillstånd beror inte på vanliga sköldpaddsskal, utan på att de druckit vatten som förorenats eller påverkats av mystiska sprickor under oaserna. Det har förändrat varelserna rent fysiskt.",al={"varifrån kommer förändrade snapjaw-skal","källa till förändrade snapjaw-skal","vem skapade förändrade snapjaw-skal"}}},fp="21,192,19.492.0,39.224.0,31.198.0,31.128.0"}
P.entries["item:ambercorn"] = {n="Ambercorn",s="Ambercorn är en helig nöt som faller från de höga, urgamla träd som står utspridda över Mulgore. Den är genomsyrad av naturmagi och är en viktig ingrediens i tauren-schamaners brygder, framför allt för att framkalla andliga syner under ungdomsriter.",h="Ambercorn är en helig nöt som faller från de höga, urgamla träd som står utspridda över Mulgore.",kw={"ambercorn","bloodhoof village","mulgore","rite of vision","taurenprövning","water of the seers","zarlman two-moons"},ang={["class:Shaman"]="Schamanistisk tradition vördar naturliga katalysatorer som ambercorn och erkänner att Jordmodern bäddar in andlig magi i den fysiska skörden från sina träd och sin jord.",["race:Tauren"]="Alla unga tauren som genomgår Jordmoderns traditionella riter lär sig känna igen ambercorn som en viktig ingrediens i synresan som visar deras andliga väg."},sec={{t="Gåvor från trädkronorna",b="Ambercorns samlas under Mulgore mäktiga träds stadiga grenar och är mer än vanliga nötter för tauren. De är rika på landets andliga livskraft och bär på slumrande magiska egenskaper som taurenmystiker har förstått och använt i generationer. Unga jägare och vandrare lär sig tidigt att hålla ögonen på gräset under trädkronorna och hedra Jordmoderns gåvor som faller fritt ovanifrån."},{t="Siarens brygd",b="I Bloodhoof Village förlitar sig siaren Zarlman Two-Moons på ambercorn när han förbereder unga tauren för Rite of Vision. Tillsammans med stenar från slätternas rena vattenkällor får ambercorn dra i den kraftfulla Water of the Seers. När en novis dricker denna ceremoniella dryck framför förfädernas lågor skärps sinnena, och ett vägledande andedjur visar sig för att leda novisen mot nästa mål."}},faq={{q="Vad är ambercorn?",a="Ambercorn är en frökapsel eller nöt som faller från Mulgore stora, urgamla träd. Den bär på medfödd naturmagi som är knuten till landets andar.",al={"ambercorn","vad är ambercorn"}},{q="Var hittar man ambercorn?",a="De ligger utspridda på marken under trädkronorna på de mäktiga träd som står spridda över Mulgore gräsmarker, särskilt i områdena kring Bloodhoof Village.",al={"ambercorn plats","var hittar man ambercorn","hur får man ambercorn"}},{q="Vad används ambercorn till?",a="Taurensiaren blandar ambercorn med brunnsstenar för att brygga Water of the Seers, en ceremoniell dryck som dricks under Rite of Vision för att uppenbara andliga vägvisare.",al={"ambercorn användning","vad gör ambercorn"}},{q="Vem ber om ambercorn i Bloodhoof Village?",a="Zarlman Two-Moons, en respekterad siare som bor i Bloodhoof Village, ger noviser i uppgift att samla ambercorn som en del av prövningarna som krävs för att bevisa ens band till Jordmodern.",al={"vem behöver ambercorn","ambercorn uppdragsgivare"}}},fx={af22a474={q="Varifrån kommer Ambercorn, och vem skapade den?",a="Ambercorn tillverkas inte av dödliga händer. Det är en naturlig nöt eller kotte som faller från de väldiga träden över Mulgore-slätterna. Tauren vördar dessa frön som gåvor från den heliga jorden, med magiska egenskaper som är tätt vävda in i landet.",al={"varifrån kommer ambercorn","ambercorns ursprung","vem skapade ambercorn","var hittar man ambercorns bakgrund"}},c9693aa2={q="Varför vill någon ha Ambercorn?",a="Taurenschamaner som Zarlman Two-Moons söker Ambercorn för dess dolda magiska egenskaper. När det blandas med heliga brunnsstenar och bryggs till det kraftfulla Water of the Seers framkallar det en andlig trans framför stammens eld. Då får unga taurer de syner de behöver för att fullborda den heliga Synens rit.",al={"varför behövs ambercorn","varför samla ambercorn","vem vill ha ambercorn","vad används ambercorn till"}}},fp="9,138,19.342.0,15.367.0,21.129.0,29.113.0,27.152.0,44.150.0"}
P.entries["item:amethyst-phial"] = {n="Amethyst Phial",s="Amethyst Phial är ett skört ceremoniellt kärl som Corithras Moonrage anförtror åt unga Night Elf-äventyrare i Dolanaar. Det har tillverkats särskilt för att samla in och bevara heliga vatten från den främsta månkällan under The Oracle Tree.",h="Amethyst Phial är ett skört ceremoniellt kärl som Corithras Moonrage anförtror åt unga Night Elf-äventyrare i...",kw={"amethyst phial","corithras moonrage","crown of the earth","dolanaar","månkällan","the oracle glade","oracle tree","teldrassil"},ang={["class:Druid"]="Druider ser kärlet som ett viktigt redskap för att övervaka livsenergierna och den krypande korrumperingen som hotar Världsträdets ekosystem.",["race:NightElf"]="För kaldorei är det en högtidlig plikt att fylla kärlet och därmed direkt konfrontera de oroande bristerna i Teldrassils obevälsignade skapelse."},sec={{t="Kärl för heliga vatten",b="Amethyst Phial anförtros åt de invigda på Teldrassil och är det sista kärlet som används under pilgrimsfärden Crown of the Earth. Corithras Moonrage ger resenärer i uppdrag att bära det till bougharnas avlägsna nordvästra delar, inbäddat i The Oracle Glade. Där, under The Oracle Trees uråldriga trädkrona, ligger öns första och kraftfullaste månkällan. Kärlet doppas försiktigt i det strålande vattnet för att fånga essensen av Elunes nåd, så att druider och prästinnor kan studera och vårda Världsträdets oberäkneliga tillväxt."},{t="En börda av obevälsignad tillväxt",b="Att samla in det här provet är mer än en vanlig hängivenhetsrit. Teldrassil restes under ledning av Arch Druid Fandral Staghelm utan drak aspekternas välsignelser, eftersom de vägrade godkänna det de såg som en arrogant handling. Därför lider grenarna av en oroande korrumpering, och kaldorei förblir dödliga. Att fylla Amethyst Phial är både en andlig ritual och en fortlöpande undersökning som låter forskare i Dolanaar granska renheten i Teldrassils heliga vatten."}},faq={{q="Vad används Amethyst Phial till?",a="Corithras Moonrage ger äventyrare kärlet så att de kan samla vatten från den första och kraftfullaste månkällan på Teldrassil, som ligger i The Oracle Glade under det väldiga The Oracle Tree.",al={"amethyst phials syfte","vad gör jag med amethyst phial","använda amethyst phial"}},{q="Var fyller jag Amethyst Phial?",a="Den måste doppas i månkällan långt nordväst om Dolanaar, norr om ingången till Darnassus, i den avskilda lund som kallas The Oracle Glade.",al={"var fyller man amethyst phial","amethyst phials plats","månkällan i oracle glade"}},{q="Varför är vattnet från The Oracle Glade så viktigt?",a="Månkällan under The Oracle Tree anses vara den första och kraftfullaste källan som anlades på Världsträdet. Vattnet är genomsyrat av Elunes essens och är därför avgörande för att övervaka Teldrassils andliga och fysiska hälsa.",al={"varför vatten från oracle glade","oracle trees månkällas kraft","oracle-källans betydelse"}},{q="Vem skickar dig att använda kärlet?",a="Corithras Moonrage, en Night Elf-druid stationerad i Dolanaar, ger dig kärlet som en del av ritualuppgifterna för att förstå Teldrassils problematiska tillväxt.",al={"vem ger amethyst phial","corithras moonrages kärl","vem vill ha amethyst phial"}}},fx={f821d918={q="Vad är Amethyst Phial?",a="Amethyst Phial är ett tomt ceremoniellt kärl som ges till resenärer i Teldrassil. Det har tillverkats särskilt för att rymma ren, förtrollad vätska och ska användas för att hämta och bevara vatten från månbrunnen under det uråldriga Oracle Tree.",al={"amethyst phial","vad är den här ampullen","ametistflaska"}},af37ef60={q="Varför vill Corithras Moonrage att Amethyst Phial fylls?",a="Corithras Moonrage vill hämta vatten från den främsta månbrunnen i The Oracle Glade för att studera Teldrassils märkliga tillstånd. Eftersom det stora världsträdet saknar drakgestalternas välsignelser växer det bristfälligt och oförutsägbart, vilket får druiderna att granska dess allra heligaste vatten.",al={"varför fylla amethyst phial","varför vill corithras ha ampullen","amethyst phials syfte"}}},fp="14,165,23.493.0,28.433.1,36.160.0,35.107.0,52.213.0,32.135.0"}
P.entries["item:an-undelivered-letter"] = {n="An Undelivered Letter",s="An Undelivered Letter är ett sedan länge bortglömt brev som lämnats kvar på Lion's Pride Inn i Goldshire. Det skrevs för flera år sedan av den svårfångade Stalvan Mistmantle och är en viktig ledtråd när man nystar upp den mörka berättelsen om hans förflutna.",h="An Undelivered Letter är ett sedan länge bortglömt brev som lämnats kvar på Lion's Pride Inn i Goldshire.",kw={"canal district","kurir","folsom","goldshire","lion's pride inn","budbärare","mistmantle","stalvan"},ang={["faction:Alliance"]="När utredarna följer kurirens bortglömda väg går de från Goldshires lantliga hjärta till de förnäma kvarteren i Stormwind City."},sec={{t="En flykt i nattens mörker",b="För flera år sedan drev en storm en resande kurir till Lion's Pride Inn på jakt efter torrt logi. Nära midnatt flydde den skräckslagna budbäraren nerför trappan i sovkläder och försvann ut i det ösande regnet, för att aldrig återvända. På andra våningen lämnade han en kista full av tillhörigheter, däribland ett brev från Stalvan Mistmantle adresserat till ett gods i Canal District i Stormwind City."},{t="Spåren efter lärde mannen",b="Det oöppnade brevet låg orört i värdshusets rum på övervåningen tills nutida utredare började följa Stalvans spår genom Elwynn Forest. När det sedan länge förlorade pergamentet överlämnas till Caretaker Folsom i huvudstaden, leder mysteriet från värdshusets stillsamma salar rakt in i hjärtat av Stormwind."}},faq={{q="Var hittar man det olevererade brevet?",a="Det ligger i en förvaringskista på andra våningen i Lion's Pride Inn i Goldshire, precis vid fotänden av sängen i ett av gästrummen.",al={"var finns brevet","förvaringskistans plats","kistan på lion's pride"}},{q="Varför blev brevet aldrig levererat?",a="Kuriren som bar brevet sökte skydd från en regnstorm på Lion's Pride Inn. Omkring midnatt fick han plötsligt panik, rusade nerför trappan i nattkläder och sprang ut i stormen, så att kistan och dess innehåll blev kvar.",al={"varför olevererat","vad hände med budbäraren","kuriren flydde"}},{q="Vem skrev brevet?",a="Brevet skickades av Stalvan Mistmantle, som hade tillbringat flera nätter på värdshuset ungefär samtidigt som den skräckslagna kuriren bodde där.",al={"vem skickade brevet","stalvan skrev brevet","avsändare"}},{q="Vart skulle brevet skickas?",a="Det är adresserat till Canal District i Stormwind City, där det kan lämnas till Caretaker Folsom nära parken.",al={"vem tar emot brevet","destination stormwind","brev till canal district"}}},fx={["72dbe9c7"]={q="Vad är An Undelivered Letter?",a="Det är ett gammalt, bortglömt brev som Stalvan Mistmantle skrev för många år sedan. En kurir som bar det sökte skydd på Lion's Pride Inn i Goldshire en stormig natt, men flydde ut i mörkret i ren skräck nära midnatt. Brevet lämnades kvar i budbärarens förvaringskista och är fortfarande förseglat och oläst, med ledtrådar till Stalvans förflutna.",al={"vad är ett obeställbart brev","föremålet an undelivered letter","stalvans brev"}},e9e7c880={q="Varför vill någon ha An Undelivered Letter?",a="Du behöver det för att avslöja Stalvan Mistmantles mörka historia. Spåret efter honom har kallnat genom Duskwood och Elwynn Forest. Det här bortglömda brevet, adresserat till någon i Stormwinds kanaldistrikt, är nästa viktiga ledtråd till vem han var och vad som hände med honom.",al={"varför behöver jag an undelivered letter","vem vill ha an undelivered letter","an undelivered letters syfte"}}},fp="21,112,17.367.0,19.275.1,38.136.0,35.226.0,22.123.0,35.117.0"}
P.entries["item:anaya-s-pendant"] = {n="Anaya's Pendant",s="Anaya's Pendant är ett minne som bärs av Anaya Dawnrunners rastlösa spöke bland ruinerna i Ameth'Aran. Det är en sorglig påminnelse om hennes älskade Cerellean Whiteclaw, som överlevde Sunderingen men fann hennes ande fortfarande plågad årtusenden senare.",h="Anaya's Pendant är ett minne som bärs av Anaya Dawnrunners rastlösa spöke bland ruinerna i Ameth'Aran.",kw={"ameth'aran","anaya dawnrunner","auberdine","cerellean whiteclaw","darkshore","for love eternal","hänge","well of eternity"},ang={["class:Druid"]="Precis som många druider som följde Shan'do Stormrage in i The Emerald Dream sov Cerellean i årtusenden i hopp om att slippa sin sorg, men vaknade till kvarvarande spöken i den vakna världen.",["race:NightElf"]="Hänget är en gripande påminnelse om de djupa ärr som War of the Ancients lämnade efter sig, då oräkneliga liv och kärlekar slets isär under den stora Sunderingen."},sec={{t="Ett minne genom årtusenden",b="För tiotusen år sedan, under den katastrofala förstörelsen av Well of Eternity, lades den forntida kaldorei-staden Ameth'Aran i ruiner. Cerellean Whiteclaw trodde att hans älskade Anaya hade omkommit och bar sin djupa sorg med sig in i den långa slummern tillsammans med Shan'do Malfurion Stormrage. När han till slut vaknade vandrade han omkring i Darkshore och upptäckte att Anayas plågade vålnad fortfarande drev genom Ameth'Aran med just det här hänget. Cerellean klarar inte av att själv lyfta handen mot henne och ber därför förbipasserande resenärer att befria hennes ande och återbörda arvegodset."},{t="Avsked och frid",b="När hänget återlämnas till Cerellean i Auberdine kan Anaya Dawnrunners kvarvarande ande visa sig för honom en sista gång. Befriad från plågan som bundit henne till Ameth'Arans hemsökta ruiner bleknar hennes spöke fridfullt bort i natten och lämnar Cerellean ensam med hänget och det bestående minnet av deras urgamla kärlek."}},faq={{q="Var kommer Anaya's Pendant ifrån?",a="Hänget tas från Anaya Dawnrunners spöke, som vandrar omkring bland de forntida kaldorei-ruinerna i södra Darkshore.",al={"var hittar man anayas pendant","hur får jag tag på anaya pendant","vem släpper anaya pendant"}},{q="Vem vill ha Anaya's Pendant?",a="Det tillhör Cerellean Whiteclaw, en sörjande night elf som bor i kuststaden Auberdine i Darkshore.",al={"vem ska jag ge anayas pendant till","cerellean whiteclaw uppdrag","lämna in anayas pendant"}},{q="Varför kunde Cerellean inte hämta hänget själv?",a="Cerellean upptäckte att hans förlorade kärleks ande strövade omkring i Ameth'Arans ruiner, men trots tiotusen år av sorg stod han inte ut med hjärtesorgen av att själv lyfta handen mot henne.",al={"varför dödade cerellean inte anaya","varför behöver cerellean hjälp"}},{q="Vad händer när du återlämnar hänget till Cerellean?",a="När hänget återförs till Cerellean i Auberdine visar sig Anayas ande kort inför honom för att ta farväl, innan hon fridfullt bleknar bort. Då kan Cerellean äntligen sörja minnet av henne.",al={"vad händer med anaya","cerelleans reaktion"}}},fx={["2379a09f"]={q="Vad är Anaya's Pendant?",a="Anaya's Pendant är ett forntida minne som tillhörde Anaya Dawnrunner, en kaldorei som dog för tusentals år sedan när Ameth'Aran förstördes. Hennes rastlösa ande bär smycket bland ruinerna. Det är ett gripande, fysiskt minne av hennes bestående kärlek och livet hon delade med Cerellean Whiteclaw innan Sundering slet deras värld i stycken.",al={"vad är anaya's pendant","anaya pendant bakgrund","vem tillhör smycket"}}},fp="15,184,27.504.0,17.305.1,37.133.0,26.124.0,52.153.0,54.165.1"}
P.entries["item:ancient-moonstone-seal"] = {n="Ancient Moonstone Seal",s="Ancient Moonstone Seal är en mäktig relik från Highbornes trolldomskonst, smidd långt före Sundringen. Den var laddad med kraftfull bindningsmagi från de arkaniska krafterna och höll Asterions ande fången bland ruinerna i Bashal'Aran.",h="Ancient Moonstone Seal är en mäktig relik från Highbornes trolldomskonst, smidd långt före Sundringen.",kw={"ameth'aran","ancient moonstone seal","asterion","athrikus","bashal'aran","darkshore","deth'ryll","highborne","månsten"},ang={["class:Mage"]="Månstenen visar hur uråldrig alvisk skyddsmagi behåller sin kraft och har hållit sitt bindande fält obrutet i över tiotusen år.",["race:NightElf"]="Sigillet är en hemsökande relik från tiden före den stora Sundringen, ett minne av Highbornes otyglade arkaniska förmåga och grymma förslavning."},sec={{t="Ett fängelse av Highbornes trolldomskonst",b="Ancient Moonstone Seal smiddes av Asterions tidigare mästare, den mäktige Highborne-trollkarlen Athrikus Narassin, som skapade den till ett obrytligt metafysiskt ankare. Medan Evighetens källa ännu stod och drottning Azshara regerade använde Athrikus artefakten för att binda Asterions själ till pelarna i Bashal'Aran. Över tiotusen år senare var Asterion fortfarande en okroppslig fånge under dess magi och kunde inte bryta förtrollningen med någon kraft eller besvärjelse han förfogade över."},{t="Förstörelsen i Ameth'Aran",b="Efter den stora Sundringens förödelse hamnade sigillet så småningom i klorna på Deth'ryll-satyrerna, som härjar i Darkshores omgivande vildmark. Eftersom vanlig kraft inte kan skada förtrollad sten från Highborne krävs den uråldriga blå lågan som brinner i tvillingruinerna i Ameth'Aran söderut för att förstöra artefakten. När sigillet förtärs av denna arkaniska eld krossas Athrikus bindande förtrollning för gott, och Asterions ande släpps äntligen fri i de dödligas värld."}},faq={{q="Vad är Ancient Moonstone Seal?",a="Det är en uråldrig magisk relik skapad av Highborne-trollkarlen Athrikus Narassin. Den fungerar som en arkanisk nyckel som binder Asterions spöke till hans helgedom bland ruinerna i Bashal'Aran.",al={"vad är moonstone seal","asterions sigill","bashal'arans sigill"}},{q="Vem har sigillet innan det återfinns?",a="Sigillet hamnade i händerna på Deth'ryll-satyren som håller till i ruinerna kring Bashal'Aran i Darkshore. Den använde sigillets närvaro för att befalla mindre grell-underhuggare.",al={"vem har sigillet","var hittar man moonstone seal","vem släpper moonstone seal"}},{q="Hur kan sigillet förstöras?",a="Vanliga vapen och nutida magi kan inte skada reliken. Den måste kastas i den uråldriga, evigt brinnande lågan som fortfarande brinner i tvillingruinerna i Ameth'Aran söderut.",al={"hur bryter man sigillet","förstör moonstone seal","var förstör jag sigillet"}},{q="Vad händer när sigillet förstörs?",a="När sigillet förbränns i Ameth'Arans låga bryts de uråldriga bindande förtrollningarna som håller Asterion fången, och hans ande blir fri att ströva omkring i världen efter tusentals år i fångenskap.",al={"vad händer när sigillet bryts","asterion fri"}}},fx={bc236585={q="Varifrån kommer Ancient Moonstone Seal, och vem skapade det?",a="Ancient Moonstone Seal tillverkades för årtusenden sedan, under kaldoreirikets storhetstid och före Great Sundering. Det smiddes med magi av en av de mäktigaste Highborne-herrarna, Athrikus Narassin, som en mystisk förseglingsmekanism.",al={"vem skapade ancient moonstone seal","ancient moonstone seal ursprung","skaparen av ancient moonstone seal"}},a13d6402={q="Varför vill Asterion ha Ancient Moonstone Seal?",a="Asterion söker efter sigillet eftersom det är själva ankaret som håller hans ande bunden i Bashal'Arans förstörda helgedom. Så länge det är helt sitter han fången bakom osynliga galler, oförmögen att lämna sitt forntida fängelse eller finna ro. Genom att återfinna sigillet hoppas han kunna förstöra det i Ameth'Arans uråldriga lågor och äntligen bli fri.",al={"varför vill asterion ha sigillet","varför hitta ancient moonstone seal","vem vill ha ancient moonstone seal"}}},fp="22,168,29.371.0,25.385.1,35.130.0,46.152.0,30.154.0,40.164.1"}
P.entries["item:ancient-statuette"] = {n="Ancient Statuette",s="Ancient Statuette är en sjunken relik som bärgats från stränderna vid The Zoram Strand i nordvästra Ashenvale. Night Elf Talen söker efter den lilla avbildningen, som kommer från den forntida staden Zorams översvämmade ruiner.",h="Ancient Statuette är en sjunken relik som bärgats från stränderna vid The Zoram Strand i nordvästra Ashenvale.",kw={"ancient statuette","ashenvale","naga","zorams ruiner","statuett","talen","zoram","the zoram strand"},ang={["faction:Alliance"]="Att återfinna artefakten hjälper Talen att dokumentera och återta Night Elf-arvet från naga som tränger fram längs Ashenvales kust.",["race:NightElf"]="Statuetten är en sällsynt kvarleva från den forntida Kaldorei-civilisationen före den stora Sunderingen, bevarad i årtusenden under havet."},sec={{t="En relik i det grunda vattnet",b="Vattnen utanför nordvästra Ashenvale döljer de sjunkna resterna av Zoram, en stad för Night Elf före Sunderingen som försvann under vågorna för tiotusen år sedan. På senare tid undersökte utforskaren Talen de översvämmade ruinerna från en liten farkost i jakt på förlorade historiska reliker. När ett våldsamt angrepp från naga drev honom i land lämnade Talen kvar det mesta av sina ägodelar under flykten och tappade den forntida statuetten han hade bärgat i tidvattensanden nära sitt sänkta skepp."},{t="Zorams hemligheter",b="Talen betraktar statuetten som sin mest värdefulla ägodel och hela anledningen till att han vågade sig ut på den monsterhärjade kusten. Han tror att avbildningen inte bara är ett dekorativt stenföremål, utan en oumbärlig nyckel till att tyda arkitekturen, historien och de magiska hemligheter som ligger gömda under Zoram Strands vågor."}},faq={{q="Vad är Ancient Statuette?",a="Det är en artefakt som hämtats från de sjunkna ruinerna av den forntida Night Elf-staden Zoram, utanför Ashenvales nordvästra kust.",al={"vad är statuetten","berättelsen om ancient statuette","vad är det här för föremål"}},{q="Vem letar efter statuetten?",a="Night Elf-lärde Talen söker efter den. Han gled fram över de översvämmade ruinerna i en båt när naga överföll honom, och han tappade reliken på stranden medan han flydde för sitt liv.",al={"vem vill ha statuetten","talen och statuetten","vem tappade statuetten"}},{q="Varför är statuetten viktig?",a="Talen tror att statuetten rymmer den forntida staden Zorams hemligheter och kan vara nyckeln till att avslöja historien som ligger begravd i ruinerna under vågorna.",al={"varför vill talen ha den","statuettens syfte"}},{q="Varför stryker naga omkring där den hittades?",a="Naga har invaderat kustvattnen och ruinerna vid The Zoram Strand och angriper aggressivt alla landlevande varelser som närmar sig de sjunkna resterna av deras översvämmade territorium.",al={"varför naga på stranden","naga vid zoram strand"}}},fp="17,173,23.439.0,16.242.0,30.122.0,33.160.0,31.116.0,48.159.0"}
P.entries["item:andron-s-ledger"] = {n="Andron's Ledger",s="Andron's Ledger är ett underrättelsedokument som fås från Andron Gant i Undercity. Deathstalkers vill ha det som en del av en agents första uppdrag att samla information åt Forsaken.",h="Andron's Ledger är ett underrättelsedokument som fås från Andron Gant i Undercity.",kw={"alterac","andron gant","andron's ledger","deathstalkers","mennet carkad","rogues' quarter","syndikatet","varimathras"},ang={["class:Rogue"]="När du hämtar och tyder Andron's Ledger sätts du på prov. Mennet Carkad inviger dig formellt i Deathstalkers, och du får Varimathras personliga erkännande.",["race:Undead"]="Liggaren visar hur Forsaken samlar underrättelser om hoten kring sitt nya rike."},sec={{t="Syndikatet avslöjas",b="Den här liggaren, som hämtas från Andron Gants bokhylla i Undercity, innehåller långt mer information än Deathstalkers först väntade sig. Innehållet visar att Syndicate, resterna av Alteracs fallna mänskliga adel, aktivt manövrerar i regionen. När Deathstalker Mennet Carkad går igenom anteckningarna inser han genast dokumentets strategiska värde och förstår att Alteracs ruinerade herrar återigen smider planer. Liggaren ger Forsakens ledning konkreta bevis på Syndicates verksamhet och förvandlar ett rutinärende till en stor underrättelsekupp."},{t="En fråga för skräckfursten",b="Eftersom avslöjandet gäller hot mot Forsakens rike i regionen skickar Mennet Carkad budbäraren med liggaren direkt till Varimathras i Royal Quarter. Som Sylvanas Windrunners skräckfurstlige majordomo övervakar Varimathras den inre säkerheten och spionaget genom Deathstalkers. Liggaren ger Varimathras beröm och bevisar både Deathstalkers-nätverkets kompetens och tillförlitligheten hos agenten som avslöjade informationen."}},faq={{q="Vad är Andron's Ledger?",a="Det är en liggare som hämtas från Andron Gants bokhylla i Undercity och innehåller information som Deathstalkers söker.",al={"androns liggare","vad är den här boken","andron liggare"}},{q="Vem är Andron Gant?",a="Andron Gant är en Forsaken som driver en butik nära Apothecarium i Undercity. Lord Varimathras misstänkte att han i hemlighet hjälpte en utomstående grupp, så Deathstalkers skickade en agent som utgav sig för att vara hans väntade budbärare för att få tag på liggaren.",al={"vem är andron","andron gant"}},{q="Varför vill Deathstalkers ha liggaren?",a="Mennet Carkad vill granska Androns information för att hitta underrättelser som kan vara användbara för Forsaken.",al={"varför liggaren är viktig","varför deathstalkers vill ha liggaren"}},{q="Vem får liggaren?",a="Den lämnas först till Mennet Carkad i Rogues' Quarter. Han bedömer innehållet och ger sedan order om att den ska levereras direkt till Lord Varimathras i Hall of the Dark Lady.",al={"vem får androns liggare","vem ska jag lämna liggaren till"}},{q="Vad uppnår en skurk genom att leverera liggaren?",a="När agenten levererar liggaren fullbordar hen sin invigning i Deathstalkers och blir formellt upptagen i Forsakens hemlighetsfulla lönnmördarkult.",al={"invigning i deathstalkers","gå med i deathstalkers"}}},fx={["83ea0415"]={q="Varifrån kommer Andron's Ledger?",a="Boken tillhör Andron Gant, en informatör som bor i Undercity och för noggranna anteckningar över sina hemliga affärer. Den ligger på en bokhylla i hans kvarter tills en agent hämtar den på Deathstalkers vägnar.",al={"vem skapade andron's ledger","andron's ledger ursprung","varifrån kommer boken"}},["45ae6031"]={q="Varför vill Deathstalkers ha Andron's Ledger?",a="Mennet Carkad och Deathstalkers vill ha boken för att få underrättelser om hot mot Forsaken. Mennet granskar innehållet innan han skickar den till Lord Varimathras.",al={"varför vill man ha andron's ledger","vem vill ha andron's ledger","varför vill mennet carkad ha boken"}}},fp="15,141,24.418.1,26.401.1,24.121.0,19.245.0,41.92.0,24.188.0,52.123.0"}
P.entries["item:another-clue-to-sanders-treasure"] = {n="Another Clue to Sanders' Treasure",s="I Westfall visar en bit av Captain Sanders pergament vägen till hans nästa gömda markör.",h="I Westfall visar en bit av Captain Sanders pergament vägen till hans nästa gömda markör.",kw={"branter","captain sanders","ledtråd","pergament","sanders skatt","westfall","väderkvarn"},ang={["class:Rogue"]="Som Rogue vet du hur man tyder kryptiska vägbeskrivningar och söker igenom bortglömda gömmor vid havet efter gömda skatter."},sec={{t="En stig längs kustbranterna",b="Captain Sanders gömde sina stulna rikedomar runt om i Westfall och använde gåtor och nedgrävda markörer i stället för en enda karta som kunde beslagtas. Den här biten fortsätter stigen från det förra gömstället. Den säger åt upphittaren att vända sig norrut och leta efter en bortkastad kruka nära en ensam väderkvarn ovanför havsklipporna."}},faq={{q="Vad står det på ledtråden?",a="På pergamentet står det att du ska vända dig norrut från den gömda tunnan och gå rakt fram tills du hittar en tom kruka bredvid en ensam väderkvarn på havsbranterna.",al={"vad står det på ledtråden","sanders ledtrådstext","vägbeskrivning på ledtråden"}},{q="Vem var Captain Sanders?",a="Captain Sanders var en pirat som lämnade gömmor med stöldgods längs Westfalls stränder och branter. Han gömde markörer runt om i regionen i stället för att lämna en komplett karta.",al={"vem är sanders","captain sanders bakgrund","piraten captain sanders i westfall"}},{q="Vart leder ledtråden härnäst?",a="Ledtråden pekar norrut längs Westfalls kustklippor mot en ensam väderkvarn på branterna, där en tom kruka markerar nästa steg på Sanders stig.",al={"vart gå härnäst","sanders väderkvarnsledtråd","var finns krukan"}}},fx={b0e51eff={q="Vad är Another Clue to Sanders' Treasure?",a="Det är en handskriven bit pergament som hittades gömd i en gammal tunna längs Westfalls kust. På pergamentet finns ytterligare en uppsättning sjövägsanvisningar, skrivna av Captain Sanders. De leder den som vågar följa spåren vidare till nästa gömda del av hans ledtråd.",al={"vad är another clue to sanders' treasure","sanders ledtråd på pergament","vad är den här pergamentledtråden"}},["37a7a825"]={q="Varifrån kommer den här ledtråden, och vem skapade den?",a="Ledtråden skrevs och gömdes av Captain Sanders, en gammal sjöfarare som lämnade ledtrådar utspridda längs kusten och ute på landsbygden i Westfall. Du hittar just den här pergamentbiten i en övergiven tunna där han gömde den för länge sedan.",al={"vem skrev another clue to sanders' treasure","vem skapade sanders ledtråd","varifrån kommer den här ledtråden"}},["632540c2"]={q="Varför vill någon ha Another Clue to Sanders' Treasure?",a="Att följa Sanders spår är det enda sättet att hitta hans nedgrävda kista. Varje ledtråd bygger direkt på den föregående och ger de exakta landmärken som behövs för att följa kaptenens steg genom Westfall till skatten han gömde.",al={"varför hitta sanders ledtråd","varför vill jag ha sanders skattledtråd","vad är poängen med sanders ledtråd"}}},fp="33,92,29.299.0,29.143.0,24.163.0,31.145.0"}
P.entries["item:arikara-serpent-skin"] = {n="Arikara Serpent Skin",s="Arikara Serpent Skin är det fjälliga skinnet från den mytomspunna vindormen Arikara, som togs på Darkcloud Pinnacle. När det förs tillbaka till Whitereach Post blir det ett konkret bevis på att det hämndlystna odjuret kallades fram och dödades.",h="Arikara Serpent Skin är det fjälliga skinnet från den mytomspunna vindormen Arikara, som togs på Darkcloud...",kw={"arikara","cairne bloodhoof","darkcloud pinnacle","incendia powder","motega firemane","ormskinn","whitereach post"},ang={["class:Shaman"]="Ritualen där förtrollat pulver används på en helig eld för att tvinga fram en förfäders andeodjur visar den kraftfulla, om än manipulativa, ritualkonst som utövas i Thunder Bluff.",["race:Tauren"]="Skinnet står för en konflikt mellan forntida myter och dagens ledarskap, och Magatha Grimtotems påståenden om Cairne Bloodhoof väcker oro bland stammarna."},sec={{t="Trofé efter en framkallad vrede",b="Arikara är en mäktig vindorm med kopplingar till taurenfolkets forntida legender. Det sägs att hon söker hämnd på Cairne Bloodhoof när kulturen förändras. Med förtrollat Incendia Powder, tillrett under äldste Magatha Grimtotems ledning, tänder mästarna den heliga elden på gravbranterna vid Darkcloud Pinnacle för att tvinga andeodjuret in i den fysiska världen. När ormens skinn flås av blir det Arikara Serpent Skin, ett omisskännligt minne av odjurets död."},{t="En oroande insikt",b="När skinnet förs till Motega Firemane vid Whitereach Post bevisar det att ormen är död, men väcker obekväma frågor. Magatha Grimtotem hävdade att Arikara specifikt jagade Cairne Bloodhoof av vrede över förfädernas traditioner, men när Motega undersöker den dödade varelsen kan han inte förstå varför en sådan ande verkligen skulle hota deras överhövding. Skinnet undanröjer den omedelbara faran, men lämnar en gnagande misstanke om Magathas egentliga tolkningar."}},faq={{q="Vad är Arikara Serpent Skin?",a="Det är det fjälliga skinnet från Arikara, en legendarisk vindorm som kallades fram och besegrades på Darkcloud Pinnacle i Thousand Needles.",al={"ormskinn","arikaras skinn","vad är det här för skinn"}},{q="Vem vill ha Arikara Serpent Skin?",a="Motega Firemane vid Whitereach Post behöver skinnet och resten av Incendia Powder som bevis på att ormen inte längre utgör ett hot.",al={"vem hämtar skinnet","vem lämnar man in det till","vem vill ha arikaras skinn"}},{q="Varför kallades Arikara fram från början?",a="Magatha Grimtotem hävdade att förändringar i taurenfolkets traditioner hade gjort den uråldriga ormen Arikara vred, så att hon började förfölja överhövding Cairne Bloodhoof. Hon instruerade att odjuret skulle lockas fram och dödas innan Cairne kunde komma till skada.",al={"varför kalla fram arikara","varför döda arikara"}},{q="Var får man tag på skinnet?",a="Det plundras direkt från Arikara efter att hon kallats fram genom att kasta förtrollat Incendia Powder på livets heliga eld, som finns på en gravnål vid Darkcloud Pinnacle.",al={"var får man tag på arikara serpent skin","arikara plats"}}},fx={d099bc06={q="Varifrån kommer Arikara Serpent Skin?",a="Skinnet tas direkt från liket efter Arikara, en våldsam vindormsande som åkallas vid Darkcloud Pinnacle i Thousand Needles. Magatha Grimtotem förtrollar Incendia Powder. När det kastas på livets heliga eldplats, där de döda begravs, kallar det fram Arikara så att hon kan dödas och flås.",al={"arikara skin ursprung","varifrån kommer arikara serpent skin","vem skapade arikara skin"}}},fp="20,158,26.432.0,22.370.1,33.154.0,35.140.0,44.213.0,31.161.0"}
P.entries["item:arnak-s-hoof"] = {n="Arnak's Hoof",s="Arnak's Hoof är det makabra beviset på att brottslingen Arnak Grimtotem har dödats. Arnak jagades upp på klipporna vid Darkcloud Pinnacle och dömdes till döden av Freewind Posts försvarare efter att ha mördat en annan tauren och kidnappat hans syster.",h="Arnak's Hoof är det makabra beviset på att brottslingen Arnak Grimtotem har dödats.",kw={"arnak","arnak grimtotem","arnak's hoof","cliffwatcher longhorn","darkcloud pinnacle","freewind post","lakota windsong","thousand needles"},ang={["faction:Horde"]="När Arnak elimineras stärks Freewind Posts auktoritet i Thousand Needles och Grimtotems förrädiska inflytande, som hotar Hordens försörjningsvägar, försvagas.",["race:Tauren"]="För slättens tauren är det en handling av stamrättvisa att ta Arnaks hov från en avfälling vars mordiska gärningar har dragit vanära och blodsutgjutelse över Thousand Needles."},sec={{t="Pris på en utstött",b="Arnak Grimtotem blev ökänd i hela Thousand Needles som en fredlös vars brutalitet överskred även de omstridda gränserna för taurenklanernas politik. Efter att ha mördat en annan tauren och kidnappat offrets syster, Lakota Windsong, utfästes en formell belöning för hans död. Arnak tog sin tillflykt till höjderna vid Darkcloud Pinnacle, omgiven av Grimtotem-vakter. Att döda honom och ta hans avhuggna hov ger Cliffwatcher Longhorn vid Freewind Post ett obestridligt bevis på att mördaren äntligen har fått sona sina brott."}},faq={{q="Vad används Arnak's Hoof till?",a="Arnak's Hoof är ett fysiskt bevis på att den fredlöse Arnak Grimtotem har dödats. Den lämnas till Cliffwatcher Longhorn vid Freewind Post för att slutföra prisjakten och hämta den utlovade belöningen.",al={"lämna in arnak's hoof","vad gör jag med arnak's hoof","vem vill ha arnak's hoof"}},{q="Vem var Arnak Grimtotem?",a="Arnak var en avfälling från Grimtotem som var efterlyst för mord och kidnappning. Han dödade en tauren ur stammen och höll offrets syster, Lakota Windsong, fången på klipporna vid Darkcloud Pinnacle.",al={"vem är arnak","arnak grimtotem bakgrund","varför är arnak efterlyst"}},{q="Var hittar man Arnak Grimtotem?",a="Arnak finns på klipporna vid Darkcloud Pinnacle i norra Thousand Needles. Dit kommer du via repbroar nära klipporna på vägen mot Razorfen Downs. Han håller sin fånge, Lakota Windsong, på samma klippa.",al={"arnak grimtotem plats","var finns arnak","hur hittar jag arnak"}}},fx={["8804d903"]={q="Vad är Arnak's Hoof?",a="Den avhuggna hoven är ett otvetydigt bevis på att den fredlösa tauren Arnak Grimtotem har dödats. Den tas direkt från hans kropp på Thousand Needles vindpinade platåer och förs tillbaka till Freewind Post för att bekräfta att rättvisan till slut hunnit ikapp den utstötta skurken.",al={"arnak hoof","vad är den här hoven","arnak's hoof"}},a4f2e55c={q="Varifrån kommer Arnak's Hoof?",a="Den tas från Arnak Grimtotem, en renegat-tauren som lurar på klipporna nära Darkcloud Pinnacle. Den är varken smidd eller tillverkad, utan ett fysiskt troféföremål som tas efter att du konfronterat och dödat honom i hans gömställe med utsikt över ravinerna.",al={"var får man tag på arnak's hoof","vem skapade arnak's hoof","arnak hoof ursprung"}},ffececdb={q="Varför vill någon ha Arnak's Hoof?",a="Cliffwatcher Longhorn i Freewind Post utlyste en belöning och kräver bevis på att Arnak är död. Arnak begick avskyvärda brott: han dödade en oskyldig tauren och kidnappade hans syster, Lakota Windsong. Lämna in hoven för att uppfylla belöningen och få Freewind Posts beskyddares tacksamhet och betalning.",al={"vem vill ha arnak's hoof","varför lämna in arnak hoof","varför vill man ha arnak hoof"}}},fp="12,256,20.533.0,30.200.0,24.183.0,31.211.0"}
P.entries["item:astor-s-letter-of-introduction"] = {n="Astor's Letter of Introduction",s="Astor's Letter of Introduction är ett dokument som Astor Hadren, en kurir som reser mellan Silverpine Forest och Undercity, bär med sig. Aspirerande Deathstalkers tar brevet för att dölja sin identitet när de infiltrerar en misstänkt konspiration kring butiksinnehavaren Andron Gant.",h="Astor's Letter of Introduction är ett dokument som Astor Hadren, en kurir som reser mellan Silverpine Forest...",kw={"andron gant","apothecarium","astor hadren","deathstalkers","mennet carkad","silverpine forest","undercity","varimathras"},ang={["class:Rogue"]="Att skaffa och använda Astors brev är en grundläggande fältövning för Forsaken-skurkar som vill ansluta sig till Deathstalkers. Den prövar deras färdigheter i lönnmord, stöld och förklädnad.",["race:Undead"]="Planen kring brevet visar den interna paranoian i Undercity, där Lord Varimathras använder Deathstalkers för att spåra upp omstörtande verksamhet bland Forsaken."},sec={{t="En kurirs intyg",b="Astor Hadren tjänstgjorde som diskret kurir mellan Silverpine Forest och huvudstaden. Hans personliga introduktionsbrev intygar bärarens trovärdighet inför stadens olagliga kontakter. När Deathstalker-agenten Mennet Carkad behövde utreda misstänkta läckor inom Undercity blev Astors resor genast ett mål. Genom att döda Hadren eller stjäla hans papper kan en agent anta hans identitet och fånga upp hemlig kommunikation som bara Astor skulle få läsa."},{t="Fällan vid Apothecarium",b="Mennet Carkad använder det återfunna brevet för att lura Andron Gant, en butiksinnehavare nära Apothecarium. Lord Varimathras misstänker Gant för att läcka Forsaken-underrättelser till en okänd tredje part. Med Astors brev i hand utger sig en infiltratör för att vara den väntade kontakten. På så vis utnyttjar hen Gants godtrogna tillit för att avslöja hans medkonspiratörers identiteter och säkra bevis på hans förräderi."}},faq={{q="Vad används Astor's Letter of Introduction till?",a="Det fungerar som identitetsbevis för att lura handelsmannen Andron Gant. Genom att visa upp brevet låtsas en agent vara kuriren Astor Hadren för att avslöja Gants hemliga affärer.",al={"brevets syfte","vad gör brevet","användning av astors brev"}},{q="Vem var Astor Hadren?",a="Astor Hadren var ett sändebud och en budbärare som färdades längs vägarna mellan Silverpine Forest och Undercity. Han bar korrespondens åt privata uppdragsgivare innan Deathstalker-agenter hann upp honom.",al={"vem är astor","astor hadrens bakgrund","vem hade brevet"}},{q="Varför vill Mennet Carkad ha brevet?",a="Mennet Carkad behöver brevet för att pröva rekryter som vill ansluta sig till Deathstalkers och genomföra en fälla mot Andron Gant, som Lord Varimathras misstänker för förräderi.",al={"varför behöver mennet brevet","carkads plan"}},{q="Misstänker Andron Gant att brevet är stulet?",a="Nej. Mennet påpekar att Gant saknar vett nog att misstänka något skumt, och Gant accepterar utan vidare brevets bärare som den vanliga budbäraren från hans medkonspiratörer.",al={"märker gant något","blir andron lurad"}}},fx={da9b0b54={q="Vad är Astor's Letter of Introduction?",a="Det är en legitimation som bärs av Astor Hadren, en kurir som reser mellan Silverpine Forest och Undercity. Dokumentet identifierar bäraren som en väntad mellanhand åt Andron Gant, en köpman i Undercity som misstänks samarbeta med en okänd yttre fraktion.",al={"vad är astor's letter","astor letter of introduction","vad är det här brevet"}}},fp="30,204,23.427.0,29.378.1,48.145.0,21.175.0,40.164.0,46.135.1"}
P.entries["item:ataeric-s-staff"] = {n="Ataeric's Staff",s="Ataeric's Staff är en kraftfull magisk kanalstav som Archmage Ataeric, en högt uppsatt magiker från Dalaran i Silverpine Forest, använder. Den fungerar både som fokus för att påverka lokala ley-linjer och som ett fysiskt bevis för Forsaken på ärkemagikerns nederlag vid The Sepulcher.",h="Ataeric's Staff är en kraftfull magisk kanalstav som Archmage Ataeric, en högt uppsatt magiker från Dalaran i...",kw={"archmage ataeric","ataeric's staff","dalaran","ley-knut","the sepulcher","shadow priest allister","silverpine forest","vävaren"},ang={["class:Mage"]="Staven är ett exempel på de fokuserade redskap som Dalarans ärkemagiker använder för att nå fram till och väcka slumrande ley-knutar.",["race:Undead"]="När staven återtas hejdas Dalarans växande grepp om Silverpines magiska reserver, vilket säkrar Forsakens västra gränser."},sec={{t="Trofé från The Sepulcher",b="Oroad över Dalarans magiska expansion beordrade Shadow Priest Allister mordet på Ataeric och krävde att staven skulle återtas. När Ataeric hade dödats och staven återtagits föll de koncentrerade ley-energierna tillbaka i dvala. Att föra staven till The Sepulcher innebar en avgörande seger över Dalarans ambitioner, även om Forsaken fortfarande vakar över den slumrande kraften i jorden."},{t="En kanal för ley-magi",b="Den här staven bars av Archmage Ataeric och användes för att styra och utnyttja ley-energier i södra Silverpine Forest. På uppdrag av Dalaran försökte Ataeric återaktivera en uråldrig ley-energiknut nära gränsen till magokratins territorium. Staven var ett oumbärligt redskap för att väva samman dessa väldiga omgivande strömmar, vilket gjorde ärkemagikern till ett allvarligt hot mot närliggande bosättningar tillhörande Forsaken."}},faq={{q="Vem tillhör Ataeric's Staff?",a="Staven tillhör Archmage Ataeric, en högt uppsatt magiker från Dalaran som är stationerad i Silverpine Forest för att övervaka återaktiveringen av en kraftfull ley-knut.",al={"vem äger ataeric's staff","ataerics ägare","vem släppte den här staven"}},{q="Varför vill Shadow Priest Allister ha Ataeric's Staff?",a="Shadow Priest Allister i The Sepulcher vill ha staven som bekräftelse på att Archmage Ataeric är död och för att se till att Dalarans försök att påverka regionens ley-linjer bryts helt.",al={"varför vill allister ha staven","stavens syfte i the sepulcher","vem tar staven"}},{q="Vad händer när staven tas från Archmage Ataeric?",a="När Ataeric har dödats och staven tagits bort skingras de ley-energier som Dalaran vävde samman och återgår till dvala, vilket gör att det omedelbara magiska hotet mot Forsaken upphör.",al={"vad händer med ley-linjen","efter att ha besegrat ataeric"}},{q="Var hittar man Ataeric's Staff?",a="Den tas direkt från Archmage Ataerics kropp. Han hittas bland andra magiker och väktare från Dalaran, nära Dalarans närvaro i södra Silverpine Forest.",al={"var hittar man ataeric's staff","ataerics plats"}}},fp="15,165,23.382.0,22.294.1,35.152.1,53.171.0,59.162.1,31.164.0"}
P.entries["item:athrikus-narassin-s-head"] = {n="Athrikus Narassin's Head",s="Det här avhuggna huvudet visas som bevis på att Athrikus Narassin, en uråldrig häxmästare som ledde mörka ritualer i norra Darkshore, har dödats. Det togs från toppen av den förfallna spiran och bekräftar att den demoniska verksamheten kring Tower of Althalaxx har störts.",h="Det här avhuggna huvudet visas som bevis på att Athrikus Narassin, en uråldrig häxmästare som ledde mörka...",kw={"althalaxx","athrikus narassin","kultister","darkshore","felmagi","avhugget huvud","häxmästare"},ang={["class:Warlock"]="Athrikus mästerskap över felkrafterna gjorde honom till en formidabel utövare, men hans vårdslösa synlighet i Althalaxx blev hans fall.",["race:NightElf"]="När du renar bort Athrikus Narassin avlägsnar du en ruttnande demonisk plåga från uråldriga kaldorei-ruiner längs Kalimdors norra kust."},sec={{t="Plågan över Althalaxx",b="Högst upp i Tower of Althalaxx ledde Athrikus Narassin en krets mörka trollkarlar som utövade felmagi längs Darkshores kust. Narassin var uråldrig och djupt rotad i området och samordnade demoniska åkallelser som hotade den omgivande vildmarken. Genom att ta hans huvud krossar du kretsens ledarskap och driver tillbaka dess omedelbara fäste i regionen, även om den kvardröjande korruptionen innebär att fortsatt vaksamhet kommer att krävas."}},faq={{q="Vem var Athrikus Narassin?",a="Athrikus Narassin var en uråldrig och mäktig häxmästare som styrde över kultisterna i Tower of Althalaxx i norra Darkshore. Han ledde kretsens demoniska ritualer från själva toppen av spiran.",al={"vem är athrikus","athrikus bakgrund","vem är häxmästaren"}},{q="Varför behövs hans huvud?",a="Alliansens spejare som bevakar Tower of Althalaxx behöver obestridliga bevis på att mästarhäxmästaren har dödats. När du visar upp hans avhuggna huvud bekräftar du hans död och visar att angreppet mot de demoniska styrkorna lyckades.",al={"varför ta huvudet","syftet med athrikus huvud","vad ska huvudet användas till"}},{q="Var finns Athrikus Narassin?",a="Han håller till allra högst upp i Tower of Althalaxx, i norra Darkshore, tungt bevakad av sina hängivna kultister och åkallade demoner.",al={"var hittar man athrikus","athrikus plats","toppen av tower of althalaxx"}},{q="Utplånas det demoniska hotet helt när han dödas?",a="Athrikus död blir ett hårt slag mot de mörka ritualisterna och skingrar deras nuvarande verksamhet, men spejarna tror att de demoniska styrkorna så småningom kommer att samlas igen, vilket kräver fortsatt försvar av Darkshore.",al={"är demonerna borta","är tornet renat","besegrade vi kulten"}}},fx={["5ecacf9e"]={q="Vad är Athrikus Narassin's Head?",a="Det är det avhuggna huvudet från Athrikus Narassin, en forntida nattalvstrollkarl som leder de mörka styrkorna i Tower of Althalaxx. Du tar det som obestridligt bevis på att den lokala kultens ledare har dödats.",al={"vad är athrikus huvud","athrikus narassin huvud"}},["639f8902"]={q="Varifrån kommer Athrikus Narassin's Head?",a="Det tas direkt från toppen av Tower of Althalaxx i norra Darkshore. Athrikus Narassin håller till högst upp i den förstörda byggnaden, omgiven av sina farligaste trollkarlar och åkallade demoniska hantlangare, tills han besegras.",al={"varifrån kommer athrikus huvud","var får man tag på athrikus huvud","vem skapade athrikus huvud"}}},fp="24,158,21.380.1,26.185.1,23.171.0,35.136.1,57.171.0"}
P.entries["item:bag-of-empty-ooze-containers"] = {n="Bag of Empty Ooze Containers",s="Bag of Empty Ooze Containers är en uppsättning sterila glasbehållare som tillhandahålls av gnomforskaren Laris Geardawdle i Ironforge. De är förberedda för varsam insamling i fält och innehåller tomma provburkar avsedda för att fånga orörda, oförvridna slemspecimen från hela Azeroth.",h="Bag of Empty Ooze Containers är en uppsättning sterila glasbehållare som tillhandahålls av gnomforskaren...",kw={"bag of empty ooze containers","empty pure sample jar","ironforge","laris geardawdle","slemburkar","pure sample jar","slem"},ang={["faction:Alliance"]="Laris Geardawdle samordnar sin ekologiska forskning från Ironforge och skickar alliansäventyrare djupt in i otämjda områden som Un'Goro Crater för att hämta viktiga fältprover.",["race:Gnome"]="De tåliga, kemikaliebeständiga burkarna i väskan visar prov på gnomisk uppfinningsrikedom och gör det möjligt för fältforskare att transportera farliga, frätande prov från vilda varelser på ett säkert sätt."},sec={{t="Forskningsutrustning för fältarbete",b="När Laris Geardawdle undersökte Azeroths märkliga slems biologi insåg han att slemmiga varelser snabbt suger upp och speglar omgivningens förvridning. Efter att ha studerat förorenade rester från platser som Felwood beställde gnomforskaren dessa tåliga provburkar, som klarar frätande specimen och samtidigt bevarar deras naturliga tillstånd. Väskan rymmer tillräckligt med burkar för att en upptäcktsresande ska kunna samla rent, oförorenat slem från vilda, orörda områden, framför allt den ursprungliga vildmarken i Un'Goro Crater, där uråldriga slemmiga klumpar frodas fria från demonisk besmittelse."}},faq={{q="Vad finns i Bag of Empty Ooze Containers?",a="Väskan innehåller tio Empty Pure Sample Jars, specialtillverkade glaskärl som säkert kan förvara frätande slemspecimen utan att kärlet bryts ned eller provet förorenas.",al={"vad finns i väskan","väskans innehåll","innehåll i slemburken"}},{q="Vem tillhandahåller behållarna?",a="De tillhandahålls av Laris Geardawdle, en excentrisk gnomforskare som arbetar från Hall of Explorers i Ironforge och studerar slemmets anpassning till miljön.",al={"vem ger slempåsen","laris geardawdles väska","vem ger bag of empty ooze containers"}},{q="Vilken sorts slem är burkarna avsedda för?",a="Burkarna är avsedda för rena, oförvridna slemprov. Till skillnad från de förpestade specimen som finns i Felwood kan orört slem samlas från de slemmiga klumparna i Un'Goro Crater.",al={"vilket slem ska i burkarna","mål för rent prov","var fyller man burkarna"}},{q="Varför behöver Laris rena slemprov?",a="Laris insåg att slemmiga varelser suger upp egenskaper från sin miljö, ungefär som en biologisk svamp. För att förstå hur den anpassningen fungerar behöver han ett oförvridet grundprov att jämföra med förorenat slem från förpestade områden.",al={"varför samla rent slem","geardawdles forskningsmål","varför rena slemmiga varelser"}}},fx={["9a2213f5"]={q="Vad är Bag of Empty Ooze Containers?",a="Den här säcken innehåller specialutrustning för fältarbete som Laris Geardawdle ger dig i Ironforge. I säcken finns tio tomma provburkar som är gjorda för att förvara och säkert transportera flyktiga slemprover till hans verkstad utan läckage eller kontaminering.",al={"bag of empty ooze containers","vad är ooze containers","laris ooze bag"}}},fp="28,154,24.455.0,48.128.0,30.154.0,51.164.0,38.173.0"}
P.entries["item:balnir-snapdragons"] = {n="Balnir Snapdragons",s="Balnir Snapdragons är färgstarka blommor som odlas vid Balnir Farmstead i östra Tirisfal Glades. De tar naturligt upp magiska strömmar och fungerar som känsliga indikatorer för Forsaken, som använder dem för att upptäcka hur Scourge-korruptionen sprider sig från de angränsande Plaguelands.",h="Balnir Snapdragons är färgstarka blommor som odlas vid Balnir Farmstead i östra Tirisfal Glades.",kw={"anastasia hartwell","balnir farmstead","balnir snapdragons","mage quarter","plaguelands","tirisfal glades"},ang={["class:Mage"]="Forsakens magiker studerar Balnir Snapdragons som råa magiska ledare och använder deras naturliga känslighet för att mäta hur magiska plågor förvränger de omgivande ley-linjerna.",["race:Undead"]="För Forsaken ger blommorna praktisk övervakning av den östra gränsen och varnar forskare i Undercity om Lich Kings korruption håller på att ta över Tirisfals jord."},sec={{t="Blomning bland ruiner",b="De färgstarka blommorna växer fortfarande i trädgården vid Balnir Farmstead, en gård i östra Tirisfal Glades som ligger i ruiner efter Lordaerons fall och Scourges uppkomst. Trädgården ligger så nära Plaguelands i öster, precis där Lich Kings pest tränger mot Tirisfal, att blommorna avslöjar hur korruptionen sprider sig."},{t="Magiska barometrar",b="Eftersom snapdragons är ovanligt känsliga för magi i atmosfären fungerar de som levande barometrar för magiska plågor. Anastasia Hartwell och Forsakens magiker i Undercity söker efter färska exemplar i gårdens blomlådor. Genom att överlämna växterna till Royal Apothecary Society hoppas Undercity kunna analysera floran och mäta hur långt Lich Kings pest har trängt över gränsen och ner i Tirisfals jord."}},faq={{q="Var hittar man Balnir Snapdragons?",a="De växer i blomlådor och rabatter kring den förfallna gården Balnir Farmstead, i östra delen av Tirisfal Glades nära gränsen till Western Plaguelands.",al={"balnir snapdragons plats","var finns blommorna","balnirblommornas plats"}},{q="Varför vill Anastasia Hartwell ha dessa snapdragons?",a="Snapdragons absorberar lätt vilande magiska energier. Anastasia Hartwell vill att färska exemplar levereras till apotekarna i Undercity för att mäta om den magiska smittan från Plaguelands aktivt sprider sig till Tirisfal Glades.",al={"varför samla snapdragons","målet med uppdraget vid balnir farmstead","anastasia hartwell snapdragons"}},{q="Vem odlade blommorna från början?",a="De växer i trädgården vid Balnir Farmstead, familjens gård som gett dem deras namn. Gården ödelades tillsammans med resten av Lordaerons landsbygd när Scourge drog fram.",al={"vem planterade balnir snapdragons","balnirfamiljens snapdragons"}},{q="Förstörde Scourge Balnir-blommorna?",a="Nej. Snapdragons växer fortfarande i gårdens trädgård, och det är just därför Anastasia Hartwell ber om dem. När de undersöks så nära Plaguelands kan de visa om pesten har nått Tirisfal Glades.",al={"dödade pesten snapdragons"}}},fx={ebe2752a={q="Vad är Balnir Snapdragons?",a="Balnir Snapdragons är en särskild sorts blomma som odlas i odlingslådorna vid Balnir Farmstead i östra Tirisfal Glades. De är naturligt känsliga och ovanligt mottagliga för magiska energier. De absorberar vilande magiska strömmar från omgivningen och är därför utmärkta indikatorer på förorening i närheten.",al={"vad är balnir snapdragons","balnir snapdragon-blomma","balnir snapdragons bakgrund"}}},fp="18,193,15.380.0,18.392.0,38.148.0,51.202.0,34.183.0,43.194.0"}
P.entries["item:baron-longshore-s-head"] = {n="Baron Longshore's Head",s="Längs The Merchant Coast bevisar Baron Longshore's Head att piratkaptenen är död. Gazlowe utlyste en offentlig belöning för Longshores identifierbara kvarlevor för att skydda Ratchets handelssjöfart.",h="Längs The Merchant Coast bevisar Baron Longshore's Head att piratkaptenen är död.",kw={"baron longshore","belöning","gazlowe","gilneas","heedless","the merchant coast","ratchet","southsea freebooters"},ang={["race:Human"]="Som människa kan du spåra Baron Longshores ursprung till Gilneas, den isolationistiska nation han lämnade innan han anslöt sig till Southsea Freebooters."},sec={{t="Ett pris på en sjörövare",b="Baron Longshore ledde Southsea Freebooter-räder från läger längs The Merchant Coast söder om Ratchet. Hans flaggskepp, the Heedless, hotade goblinernas handelsleder mellan Kalimdor och Eastern Kingdoms. Gazlowe, Ratchets chefsingenjör, utlovade en belöning för bevis som kunde identifiera Longshores död. Hamnmyndigheten betalar ut en penningsumma när piratens huvud lämnas in."}},faq={{q="Vem var Baron Longshore?",a="Baron Longshore var en piratkapten från människoriket Gilneas. Han ledde Southsea Freebooters från läger längs The Merchant Coast söder om Ratchet och terroriserade sjöfarten ombord på the Heedless.",al={"baron longshore","vem är longshore","kapten longshore"}},{q="Vem vill ha Baron Longshores huvud?",a="Gazlowe, Ratchets goblinledare, utlyste en offentlig belöning för Baron Longshores identifierbara kvarlevor. Southsea Freebooters angrep Ratchets handelsfartyg, och Gazlowe ville att hamnens handel skulle fortsätta utan avbrott.",al={"vem vill ha huvudet","vem lämnade in","gazlowes belöning"}},{q="Var finns Baron Longshore?",a="Baron Longshore patrullerar tre sydhavspiratläger längs kusten söder om Ratchet, strax norr om Northwatch Hold längs The Merchant Coast.",al={"var finns longshore","longshores plats","baron longshores plats"}},{q="Vilket fartyg förde Baron Longshore befäl över?",a="Baron Longshore var kapten på the Heedless, som plundrade handelsfartyg på Great Sea utanför The Barrens kust.",al={"longshores fartyg","heedless","heedless fartyg"}}},fx={["0986c9c0"]={q="Vad är Baron Longshore's Head?",a="Det är det makabra, avhuggna huvudet från Baron Longshore, en ökänd piratkapten från Gilneas som för befäl över fartyg åt Southsea Freebooters. Du tar det som obestridligt bevis på hans död för att uppfylla belöningen som utlysts på honom i Ratchet. Då vet Steamwheedle Cartel att den beryktade rövaren inte längre kommer att störa deras handelsrutter till sjöss.",al={"baron longshore head föremål","vad är det här huvudet","longshore head bakgrund"}}},fp="22,193,22.376.0,24.203.0,33.226.0,31.148.0,38.107.0"}
P.entries["item:barrel-of-barleybrew-scalder"] = {n="Barrel of Barleybrew Scalder",s="Barrel of Barleybrew Scalder är ett fat med starköl som Barleybrew-familjen bryggt för att bevisa sin bryggskicklighet mot sina främsta konkurrenter. Det anförtros åt hemliga kurirer som ska infiltrera Thunderbrew Distillery i Kharanos och iscensätta ett listigt sabotage under en smakprovning.",h="Barrel of Barleybrew Scalder är ett fat med starköl som Barleybrew-familjen bryggt för att bevisa sin...",kw={"öl","barleybrew","destilleri","dun morogh","kharanos","marleth","scalder","thunderbrew"},ang={["class:Rogue"]="Att distrahera en källarvakt och smuggla in tungt smuggelgods i ett bevakat förråd är en underhållande övning i klassisk dvärgliga.",["race:Dwarf"]="För dvärgar är ölbryggning både en konst och en blodsport. Att delta i källarintriger om vems recept som är bäst hör nästan till vardagen i Dun Morogh."},sec={{t="En bitter fejd i Dun Morogh",b="Bland dvärgarna i Dun Morogh är ölbryggning en allvarlig sak, och få rivaliteter brinner hetare än fejden mellan Thunderbrew-familjen och Barleybrew-familjen. Thunderbrew-familjen är vida känd och stoltserar med sin välbesökta destillerianläggning i Kharanos, men Marleth Barleybrew vägrar att hamna i deras skugga. I stället för att enbart förlita sig på öppna värdshus brygger Marleth den eldiga ”Scalder” för att bevisa att hans recept inte har någon överman. Han hoppas att ovetande gäster som smakar den ska inse att Thunderbrew-familjen inte har monopol på förstklassiga dvärgdrycker."},{t="List i källaren",b="Tanken är att smuggla fatet direkt ner i källaren under Thunderbrew Distillery och byta ut ett fat av den lokala favoriten Thunder Ale. Avsikten är inte att förgifta eller förstöra, utan att spela ett fräckt dvärgstreck som svider i stoltheten: nästa sats som serveras där uppe ska i hemlighet vara Barleybrew-familjens kraftiga Scalder."}},faq={{q="Vad finns i Barrel of Barleybrew Scalder?",a="Det innehåller Marleth Barleybrews egen Scalder, en kraftig dvärgdryck som bryggts för att mäta sig med Thunderbrew-familjens berömda recept.",al={"innehållet i barleybrew scalder","vilken sorts öl","vad är scalder"}},{q="Varför vill Marleth att fatet ska bytas ut?",a="Marleth medger att Thunderbrew-familjen brygger goda drycker, men vill lära dem ödmjukhet genom att låta källargäster av misstag smaka hans egen brygd och upptäcka att Barleybrew-familjens hantverk är minst lika bra, om inte bättre.",al={"varför byta fat","orsaken till rivaliteten","varför smugglar marleth in brygden"}},{q="Vart ska fatet?",a="Det förs ner i källaren under Thunderbrew Distillery i Kharanos och ställs bland faten där ett fat Thunder Ale snart ska tappas upp.",al={"var ska jag ställa fatet","var finns scalderfatet","destilleriets källare"}},{q="Är brygden tänkt att skada någon?",a="Nej. Det är helt enkelt ett kraftigt dvärgärl som konkurrerar med de andras. Rivaliteten mellan familjerna är intensiv, men handlar om yrkesstolthet snarare än illvilja.",al={"är scalder förgiftad","är det gift","kommer den att skada någon"}}},fx={["9f414f7e"]={q="Vad är Barrel of Barleybrew Scalder?",a="Det är en tunna starkt öl som Marleth Barleybrew har bryggt. Den här tunnan säljs inte som vanligt, utan används i en bryggartävlan. Den ska i hemlighet bytas ut mot en konkurrents lager för att vinna över ovetande öldrickare.",al={"vad är barleybrew scalder","barleybrew scalder barrel","barrel of barleybrew scalder"}},["00d1bcdd"]={q="Varifrån kommer Barrel of Barleybrew Scalder, och vem har bryggt det?",a="Ölet bryggdes och tillhandahölls av Marleth Barleybrew. Marleth är stolt över sin familjs hantverk och tog fram receptet för att bevisa att Barleybrew-familjen kan mäta sig med eller överträffa ryktet hos den konkurrerande Thunderbrew-familjen.",al={"vem bryggde barleybrew scalder","varifrån kommer barleybrew scalder","barleybrew scalder ursprung"}}},fp="28,176,27.359.0,24.300.1,48.132.0,42.209.0,26.157.0,33.132.0"}
P.entries["item:barrel-of-shimmer-stout"] = {n="Barrel of Shimmer Stout",s="Ett nybryggt fat med Rejold Barleybrews experimentella dvärgöl, tillverkat i de kalla trakterna av Dun Morogh. Den är känd för att ge den som dricker den en kraftig kick som sägs göra synen klarare, och är tänkt som gåva till vakter som håller utkik vid de höga bergspassen.",h="Ett nybryggt fat med Rejold Barleybrews experimentella dvärgöl, tillverkat i de kalla trakterna av Dun Morogh.",kw={"barrel of shimmer stout","dun morogh","dvärgöl","loch modan","mountaineer barleybrew","rejold barleybrew","shimmer stout"},ang={["profession:Cooking"]="Dvärgöl tänjer ofta på gränserna för kulinariska experiment och förenar kraftig jäsning med tåliga bergsingredienser för att stå emot den bitande kylan.",["race:Dwarf"]="Ölbryggning är en kulturell grundpelare i Ironforge, och att leverera en nyfärdigad stout till en släkting på vakt är en hedervärd bergstradition."},sec={{t="En bryggares stolthet",b="Efter att ha samlat sällsynta ingredienser i Dun Morogh bryggde Rejold Barleybrew Shimmer Stout, den senaste triumfen för den anrika familjen Barleybrew. Dvärgbryggare tar sitt hantverk på blodigt allvar och tävlar ständigt om att skapa mustiga brygder som kan stå emot den iskalla bergsluften. Rejolds senaste recept är utformat för att inte bara värma magen, utan också skärpa sinnena hos dem som är utstationerade i den isande vinden."},{t="Förnödenheter till vakten",b="Det här fatet är avsett för bergsvakten Wellart Barleybrew, som står vakt vid det södra tornet längs passet mot Loch Modan. På den ödsliga gränsen uthärdar bergsvakterna bitande kyla och långa vaktskift mellan skärmytslingar med troggar och vilda djur. Ett färskt fat familjeöl är både en välkommen smak av hemmet och en uppiggande brygd som är stark nog att få en trött vaktpost att svära på att han ser klart genom mörkret."}},faq={{q="Vad finns i Barrel of Shimmer Stout?",a="Det innehåller Shimmer Stout, ett helt nytt dvärgrecept som Rejold Barleybrew har hittat på. Drycken är känd för sin ovanligt kraftiga kick, som får alla som smakar den att känna sig fulla av energi och få ett bokstavligt skimmer i ögonen.",al={"vad är shimmer stout","vilken sorts öl är det här","drycken shimmer stout"}},{q="Vem gjorde det här stoutfatet?",a="Ölet bryggdes av Rejold Barleybrew, en medlem av den välkända Barleybrew-klanen i Dun Morogh, som ägnade tid åt att finslipa ett recept för att imponera på sin släkt.",al={"vem bryggde shimmer stout","bryggare av shimmer stout","rejold barleybrew"}},{q="Vem är fatet avsett för?",a="Det är avsett för Rejolds bror, bergsvakten Wellart Barleybrew, som är stationerad i det södra vakttornet längs vägen mot Loch Modan.",al={"vem får fatet","vart ska ölet","wellart barleybrew"}},{q="Vilken effekt har Shimmer Stout på den som dricker den?",a="Förutom att ge ett kraftigt rus ger ölet den som dricker det en intensiv kick som får ögonen att glittra och det att kännas som om man kan se i beckmörker, vilket gör det populärt bland vaksamma bergsvakter.",al={"effekten av shimmer stout","gör den att man ser i mörker","vad gör shimmer stout"}}},fp="23,192,16.309.0,22.323.0,39.141.0,30.142.0,29.136.0,61.153.0"}
P.entries["item:barrel-of-thunder-ale"] = {n="Barrel of Thunder Ale",s="Barrel of Thunder Ale är en eftersökt tunna med Kharanos signaturbrygd, smugglad rakt ut ur Thunderbrew Distillerys källare. Den byttes ut mot en tunna Marleths Barleybrew Scalder och utgör ett obestridligt bevis på fult spel i en bryggarfejd som trappas upp.",h="Barrel of Thunder Ale är en eftersökt tunna med Kharanos signaturbrygd, smugglad rakt ut ur Thunderbrew...",kw={"barrel of thunder ale","brewnall village","dun morogh","kharanos","marleth barleybrew","thunder ale","thunderbrew"},ang={["class:Rogue"]="Att smyga sig in i en bevakad källare och byta ut tunga öltunnor utan att väcka larm är ett klassiskt och praktiskt prov på smygförmåga och finess.",["race:Dwarf"]="För dvärgar är ölbryggning allvar och storpolitik. Att byta ut en rivaliserande klans dyrbara tunna i deras egen källare är en djärv förolämpning."},sec={{t="En bitter byteshandel",b="I Dun Morogh är konkurrensen mellan rivaliserande mästerbryggare stenhård, och få tvister är hätskare än fejden mellan Thunderbrews i Kharanos och Barleybrews i Brewnall Village. Marleth Barleybrew försökte smuggla in en tunna av sin egen Barleybrew Scalder i rivalernas källare, så att Thunderbrews gäster skulle få smaka hans brygd i stället för deras. Den här tunga tunnan Thunder Ale beslagtogs i bytet och släpades ut mitt framför näsan på de lokala vakterna som fysiskt bevis på att bytet lyckades."}},faq={{q="Vad finns i den här tunnan?",a="Den innehåller Thunder Ale, det berömda mörka ölet som bryggs av familjen Thunderbrew nere i Kharanos. Ölet är känt i hela Dun Morogh som en stark, kraftfull dvärgöl.",al={"innehåll i thunder ale","vad är thunder ale"}},{q="Var kommer den här tunnan ifrån?",a="Den hämtades direkt från källarförrådet i Kharanos Distillery, under den hemliga leveransen av Marleths rivalbrygd.",al={"var får man tag på det","thunder ale plats"}},{q="Vem vill ha den här tunnan?",a="Marleth Barleybrew, som finns i Brewnall Village i väster. Han väntar sig att få tunnan som bevis på att hans Scalder framgångsrikt smugglades in bland Thunderbrews tunnor.",al={"vem ska jag lämna thunder ale till","marleth barleybrew uppdrag"}},{q="Varför togs tunnan?",a="Marleth ville ha ett konkret bevis på att någon lyckats smyga sig in i Thunderbrew-källaren, ta sig förbi destilleriets vakt och sabotera konkurrenternas förråd.",al={"varför stjäla thunder ale","berättelse om bittra rivaler"}}},fp="21,194,14.342.0,27.148.0,32.132.0,22.160.0,25.134.0"}
P.entries["item:barrow-key"] = {n="Barrow Key",s="Barrow Key är en av tre druidiska nycklar som gömts i The Talon Den, högst upp på Stonetalon Peak. Den förvaras låst i en gravkammargömma för att skydda de uråldriga skatter som förseglats i hålan.",h="Barrow Key är en av tre druidiska nycklar som gömts i The Talon Den, högst upp på Stonetalon Peak.",kw={"barrow key","claw key","gatekeeper's key","sleepers' key","stonetalon peak","talon den","talon den hoard","the den"},ang={["class:Druid"]="Nyckeln är en del av en uråldrig säkerhetsritual som druiderna i The Talon Den utformade för att skydda heliga ägodelar i sin underjordiska fristad.",["faction:Horde"]="Hordens agenter i Stonetalon Mountains pressar tillfångatagna nattalver på information för att hitta nyckeln och plundra druidernas privata skattkammare."},sec={{t="En väktarens säkerhet",b="I de underjordiska gravkamrarna i The Talon Den anlade nattalvsdruider avancerade skydd för att värna sina reliker från inkräktare. Barrow Key är en del av detta flerskiktade lås och döljs i en särskild gömma bland de underjordiska gångarna. För att komma åt den krävs Gatekeeper's Key, så bara de som känner till druidernas försvarssystem kan hoppas på att få tag i den."},{t="Låsa upp skatten",b="Tillsammans med Claw Key och Sleepers' Key passar Barrow Key i tre sirligt utskurna nyckelhål i ett stenaltare djupt inne i The Talon Den. När alla tre vrids samtidigt skingras skyddsförtrollningarna och den gömda samlingen av druidiska reliker avslöjas för den som lyckas bryta igenom skyddet."}},faq={{q="Vad används Barrow Key till?",a="Barrow Key används tillsammans med Claw Key och Sleepers' Key för att låsa upp The Talon Den Hoard, en stenkista med skyddade druidiska reliker djupt inne i Stonetalon Peak.",al={"syftet med barrow key","vad öppnar barrow key","användning av barrow key"}},{q="Var är Barrow Key gömd?",a="Den är inlåst i en gravkammargömma som liknar en dold väggfackla, djupt inne i de slingrande tunnlarna i The Talon Den på Stonetalon Peak.",al={"barrow key plats","var finns barrow key","hitta barrow key"}},{q="Hur öppnar du gömman med Barrow Key?",a="Först måste du hämta Gatekeeper's Key, som druiderna gömt i en liten lykta nära huvudingången till The Talon Den.",al={"öppna gravkammargömma","låsa upp med barrow key","gatekeeper key och barrow key"}},{q="Vem gömde Barrow Key i The Talon Den?",a="Nattalvsdruiderna som bodde på Stonetalon Peak utformade det avancerade säkerhetssystemet för att hålla sina mäktiga artefakter utom räckhåll för fiender. De gömde nycklarna på olika platser i hålan.",al={"vem skapade barrow key","vem gömde nycklarna i talon den"}}},fx={["6b9fc30c"]={q="Vad är Barrow Key?",a="Barrow Key är en av tre förtrollade nycklar som nattalvernas druider skapade i The Talon Den, högt uppe på Stonetalon Peak. Den ingår i ett intrikat skydd som ska hindra fiender från att lägga beslag på deras mest värdefulla och mäktiga reliker.",al={"vad är barrow key","information om barrow key","barrow key i talon den"}},["17616df0"]={q="Varför vill någon ha Barrow Key?",a="Hordens styrkor i Stonetalon Mountains söker efter Barrow Key och dess systernycklar, Claw Key och Sleepers' Key. Tillsammans bryter de tre nycklarna igenom druidernas skydd som förseglar Talon Den Hoard och öppnar förrådet med mäktiga föremål som förvaras djupt inne i gravhögen.",al={"varför hitta barrow key","varför vill man ha barrow key","vem vill ha barrow key"}}},fp="10,168,22.310.0,19.242.1,32.160.0,31.150.0,52.121.0,43.187.0"}
P.entries["item:bartleby-s-mug"] = {n="Bartleby's Mug",s="I Stormwind håller en envis slagskämpe Bartleby's Mug nära. En krigare måste vinna den i ett krogs slagsmål och sedan se Bartleby tömma sin dryck innan han lämnar ifrån sig muggen.",h="I Stormwind håller en envis slagskämpe Bartleby's Mug nära.",kw={"bartleby","bartleby's mug","burlguard","stormwind","krogslagsmål","krigarträning"},ang={["class:Warrior"]="Som krigare i Alliansen får du Bartleby's Mug genom att slita den ur händerna på Bartleby. Kampen kräver mod och styrka när ord inte räcker."},sec={{t="En slagskämpes pris",b="Bartleby håller sin mugg nära, och en ung krigare i Stormwind måste slita den ur händerna på honom. Den envisa slagskämpen ger ifrån sig den först efter en kamp där han blir besegrad. Även då tömmer Bartleby varenda droppe innan han lämnar över muggen som bevis på segern."}},faq={{q="Vad används Bartleby's Mug till?",a="En krigare tar Bartleby's Mug som bevis på segern i ett träningsprov. När krigaren lämnar den till övningsinstruktören visar det att krigaren kunde besegra en envis slagskämpe på krogen och få honom att lämna ifrån sig den.",al={"bartleby mug användning","varför behöver jag bartlebys mug","vad gör muggen"}},{q="Vem äger muggen från början?",a="Bartleby äger muggen. Den stridslystne fyllbulten ägnar sin tid åt att dricka och slåss och ger ifrån sig den först efter att en blivande krigare besegrat honom i ett knytnävsslagsmål. Han dricker upp först.",al={"vem är bartleby","bartlebys ägare","vem har muggen"}},{q="Vem ber om Bartleby's Mug?",a="Burlguard ber om Bartleby's Mug. Krigartränaren i Stormwind bevittnar slagsmålet och kräver muggen som bevis innan krigarens kampträning kan fortsätta.",al={"vem vill ha muggen","vem ska jag ge bartlebys mug till","lämna in bartlebys mug"}}},fx={["481c5411"]={q="Vad är Bartleby's Mug?",a="Bartleby's Mug är Bartlebys personliga dryckeskärl. Han är en slagskämpe som brukar hålla till på en krog i Stormwind. Muggen är ett konkret bevis på en ung krigares skicklighet. Bartleby lämnar ifrån sig den först efter att ha blivit grundligt besegrad i strid och tömt varenda droppe ur den.",al={"vad är bartleby's mug","bartleby's mug","bartlebys mugg"}},a3659338={q="Varför vill Burlguard ha Bartleby's Mug?",a="Burlguard kräver muggen som ett fysiskt bevis på att du stod på dig och besegrade Bartleby i ett kro slagsmål. Det är ingen liten bedrift att ta en hängiven drinkares älskade mugg. När han lämnar ifrån sig den visar det att du övertygade Bartleby med knytnävarna och är redo att fortsätta din krigarträning.",al={"varför vill man ha bartleby's mug","varför vill burlguard ha muggen"}}},fp="14,162,17.249.0,32.191.0,28.185.0,28.166.0"}
P.entries["item:bathran-s-hair"] = {n="Bathran's Hair",s="Bathran's Hair är en sällsynt, ömtålig ört som växer bland ruinerna i Bathran's Haunt i nordvästra Ashenvale. I Night Elf-folktron prisas den för sina kraftfulla läkande egenskaper, och växten tros hela både själen och kroppen.",h="Bathran's Hair är en sällsynt, ömtålig ört som växer bland ruinerna i Bathran's Haunt i nordvästra Ashenvale.",kw={"ashenvale","bathran's hair","bathran's haunt","maestra's post","orendil broadleaf","växtknippe"},ang={["profession:Herbalism"]="Utbildade örtkännare har en tydlig fördel när de letar efter Bathran's Hair, eftersom deras skarpa blick för vilda växter hjälper dem att upptäcka de gömda växtknippena bland bråten.",["race:NightElf"]="För Kaldorei är det ett oroande tecken för bevarandet av deras forntida hemland när Forsaken dyker upp bland ruinerna där läkande växter som Bathran's Hair fortfarande växer."},sec={{t="Ett botemedel för själen",b="Bathran's Hair växer i skuggan av de gamla ruinerna norr om Maestra's Post och har länge värderats av Night Elf-läkare. Till skillnad från vanliga medicinalväxter, som lindrar enklare kroppsskador, sägs örten kunna bota djupa själsliga åkommor. När en ung Night Elf i Astranaar drabbas av en lömsk, obeveklig sjukdom söker örtkännaren Orendil Broadleaf efter strån från den sällsynta växten för att brygga ett livsviktigt botemedel."},{t="Samling bland ruinerna",b="Det har blivit farligt att hitta Bathran's Hair. Örten växer samlad i bortkastade växtknippen och under lövhögar som ligger utspridda över Bathran's Haunt, nära gränsen till Darkshore. Faran ökar ytterligare av att Forsaken har setts bland ruinerna, något som Orendil Broadleaf finner mycket oroande."}},faq={{q="Vad används Bathran's Hair till?",a="Örten används av Night Elf-läkare för att behandla svåra åkommor som går bortom vanlig sjukdom. Orendil Broadleaf blandar den särskilt i en läkande dryck som ska hela ett döende barn vars själ tynar bort.",al={"vad gör bathran's hair","bathran's hair användning","användning av bathran's hair"}},{q="Var växer Bathran's Hair?",a="Den finns endast i Bathran's Haunt, en forntida bosättning i ruiner i norra Ashenvale, öster om huvudvägen som leder norrut mot Darkshore.",al={"var hittar man bathran's hair","bathran's hair plats","var finns bathran's hair"}},{q="Varför är Forsaken intresserade av Bathran's Haunt?",a="Orendil Broadleaf får bara veta att Forsaken befinner sig i Bathran's Haunt, och han finner det mycket oroande; det förklaras aldrig vad de vill där. På andra håll i Ashenvale rapporterar Night Elves att Forsaken lurar vid deras ruiner och gravhögar, och de fruktar att de tänker sprida sjukdom genom skogen.",al={"varför är odöda vid bathran's haunt","forsaken i bathran's haunt","odöda bathran"}},{q="Vem är Orendil Broadleaf?",a="Orendil Broadleaf är en örtkännare stationerad vid Maestra's Post i västra Ashenvale. Han arbetar flitigt med att studera den lokala floran och tillreda mediciner för att läka resenärer och skadade försvarare av skogen.",al={"orendil broadleaf","vem vill ha bathran's hair"}}},fx={b940f392={q="Vad är Bathran's Hair?",a="Bathran's Hair är en sällsynt, skör ört som växer bland de forntida ruinerna vid Bathran's Haunt i norra Ashenvale. Nattalvernas örtmedicinare värdesätter växten högt. Den har kraftfulla läkande egenskaper som kan lindra både själsliga och kroppsliga åkommor.",al={"vad är bathran's hair","växten bathran's hair"}}},fp="14,176,23.337.0,24.255.1,32.188.0,31.148.0,51.270.0,25.171.0"}
P.entries["item:battleboar-flank"] = {n="Battleboar Flank",s="Battleboar Flank är rejäla köttstycken från de vildsinta battleboars som Bristleback-kobolder tränar i Mulgore. Unga jägare kring Camp Narache samlar in dem som bevis på att hot har undanröjts och som näringsrik föda åt taurenstammen.",h="Battleboar Flank är rejäla köttstycken från de vildsinta battleboars som Bristleback-kobolder tränar i...",kw={"battleboar","battleboar flank","brambleblade ravine","bristleback","camp narache","grull hawkwind","mulgore","red cloud mesa"},ang={["profession:Cooking"]="Flanken är grov och kraftig i smaken eftersom bestarna fötts upp för strid, men långkok ger gott om mustigt, mättande kött till lägrets gemensamma grytor.",["race:Tauren"]="När unga tauren jagar battleboars som tränger in på deras marker lär de sig att försvaret av hemlandet går hand i hand med den heliga plikten att respektera och ta till vara på Jordmodernas gåvor."},sec={{t="Föda från hotet från Bristleback",b="Bristleback-kobolderna som håller till i Brambleblade Ravine har tränat vildsinta battleboars att tränga in på taurenfolkets jaktmarker. De aggressiva bestarna utgör en direkt fara för de unga tauren som är på väg att bli vuxna i Camp Narache, men inget som tas från naturen går till spillo. Grull Hawkwind ger de oerfarna jägarna i uppdrag att ta vara på flankerna från de fällda bestarna, liksom deras trynen. Flankköttet är mustigt och mättande och kokas till en stadig gryta åt stammens unga. På så vis blir ett krigsvapen från kobolderna till livsviktig föda för stammen."}},faq={{q="Vad används Battleboar Flank till?",a="Unga jägare samlar in Battleboar Flank i Camp Narache på uppdrag av Grull Hawkwind. Köttet tillagas till gryta åt byns unga tauren, så att de besegrade fienderna också bidrar till att hålla stammen vid liv.",al={"användning av battleboar flank","vad är battleboar flank","varför samla in battleboar-kött"}},{q="Var hittar man Battleboar Flank?",a="De skärs ut från de aggressiva Battleboars och Bristleback Battleboars som stryker omkring nära Brambleblade Ravine, öster om Camp Narache på Red Cloud Mesa.",al={"källa till battleboar flank","var tappar battleboars flankkött","vilka tappar battleboar flank"}},{q="Varför tränger battleboars in på taurenfolkets mark?",a="Bristleback-kobolderna föder upp och tränar battleboars till att vara fientliga och illvilliga. När spänningarna mellan Bristlebacks och tauren tilltar driver kobolderna in dessa tränade bestar på stammens traditionella jaktmarker för att trakassera nykomlingarna.",al={"varför anfaller battleboars","koboldernas galtar i mulgore","battleboars i brambleblade"}}},fx={c29b6530={q="Vad är Battleboar Flank?",a="Det är en rejäl köttbit från stridsvildsvin som strövar omkring på Mulgore röda slätter och i raviner. Dessa vildsinta svin föds upp och tränas för krig snarare än som boskap, men köttet är näringsrikt och mättande nog att föda stammarna när villebrådet tryter.",al={"vad är battleboar flank","information om battleboar flank","battleboar-kött"}},["4a352cac"]={q="Var kommer Battleboar Flank ifrån?",a="Köttstyckena skärs från stridsvildsvin och Bristleback-stridsvildsvin som stryker omkring nära Brambleblade Ravine. De fientliga Bristleback-quilboarna föder upp och tränar vilddjuren till att bli aggressiva. Det som annars skulle vara vilt blir därför till argsinta, revirhävdande bestar.",al={"battleboar flank ursprung","var kommer battleboar flank ifrån","vem har battleboar-kött"}},f9e62759={q="Varför vill Grull Hawkwind ha Battleboar Flanks?",a="Grull Hawkwind samlar in köttet för att föda stammens unga i Camp Narache. När köttet kokas till en näringsrik gryta går inget från jakten till spillo. Samtidigt får Bristleback-quilboarna betala för att de driver sina aggressiva bestar in på taurenfolkets urgamla jaktmarker.",al={"varför samla battleboar flank","varför vill grull ha köttet","vem vill ha battleboar flanks"}}},fp="16,132,38.365.0,36.146.0,34.142.0,51.216.0"}
P.entries["item:battleboar-snout"] = {n="Battleboar Snout",s="Battleboar Snouts tas från de aggressiva vildsvin som Bristleback quilboar tränar i Mulgore. Unga tauren-jägare samlar in dem som bevis på att ett invasivt hot minskar och som mustiga ingredienser i stammens matlagning i Camp Narache.",h="Battleboar Snouts tas från de aggressiva vildsvin som Bristleback quilboar tränar i Mulgore.",kw={"battleboar","battleboar snout","brambleblade ravine","bristleback","camp narache","grull hawkwind","red cloud mesa"},ang={["profession:Cooking"]="Sega styckningsdelar som tryner måste sjuda länge över elden och är därför basingredienser i stammens lägereldsgrytor.",["race:Tauren"]="Genom att ta trynet tillsammans med köttet hedrar man Jordmodern och hennes balans. Ett rovdjur som tränger in hejdas samtidigt som de unga i Camp Narache får mat."},sec={{t="Troféer och proviant",b="I skuggan av Red Cloud Mesa tränar Bristleback quilboar sina illasinnade battleboars i Brambleblade Ravine för att känna av taurenfolkets jaktmarker. När Grull Hawkwind skickar ut unga krigare för att slå tillbaka intrånget, blir trynet ett otvetydigt bevis på att ett odjur har fällts. I stället för att slösa bort någon del av bytet använder taurenfolket trynena tillsammans med flankbitar för att laga mustiga, mättande grytor åt sina unga."}},faq={{q="Vad används Battleboar Snouts till?",a="Grull Hawkwind ber unga jägare i Camp Narache att samla in dem tillsammans med flankkött. De visar att de hotfulla vildsvinen har fällts, och hamnar i grytorna för att bli en gryta åt stammens unga.",al={"användning av battleboar snout","varför spara tryner","vad grull gör med tryner"}},{q="Varifrån kommer de här trynena?",a="De skärs från Battleboars och Bristleback Battleboars som finns nära utkanten av Red Cloud Mesa och i hela Brambleblade Ravine i öster.",al={"var man hittar battleboars","vem som släpper tryner","battleboars plats"}},{q="Varför tränger battleboars in på taurenfolkets mark?",a="De fientliga Bristleback quilboar har tränat battleboars att vara särskilt vildsinta, så att de tränger ut från Brambleblade Ravine och in på stammens traditionella jaktmarker.",al={"varför vildsvinen anfaller","quilboar-vildsvin","battleboars i brambleblade"}}},fx={a852a9b9={q="Vad är Battleboar Snout?",a="Det är trynet från ett stridsvildsvin som fötts upp och tränats av Bristleback-quilboarna nära Brambleblade Ravine. Grull Hawkwind och taurenfolket i Camp Narache tar till vara på dessa köttbitar och vildsvinssidor som rejäla ingredienser till en gryta för stammens unga. De är också ett fysiskt bevis på att jägarna gallrar ut de inkräktande bestarna.",al={"battleboar snout","vad är battleboar snout","vad är det här för föremål"}}},fp="16,179,23.333.0,36.209.0,32.150.0,51.171.0"}
P.entries["item:battleworn-axe"] = {n="Battleworn Axe",s="Battleworn Axe är grova vapen med hack och skåror, burna av Blackrock-orcherna som invaderar Redridge Mountains. Marshal Marris tar emot dessa återfunna klingor i Lakeshire som fysiska bevis på att inkräktare som hotat lokalbefolkningen har dödats.",h="Battleworn Axe är grova vapen med hack och skåror, burna av Blackrock-orcherna som invaderar Redridge...",kw={"battleworn axe","blackrock","lakeshire","marris","orch","redridge","stonewatch","vapen"},ang={["faction:Alliance"]="Varje yxa som förs tillbaka till Lakeshire betyder en inkräktare färre som hotar Redridges utsatta invånare medan Stormwinds huvudstyrkor befinner sig någon annanstans.",["profession:Blacksmithing"]="Trots sina ojämna kanter och naggade eggar visar dessa grova järnvapen upp den tåliga, tunga smidestradition som är typisk för Blackrocks vapen."},sec={{t="En inkräktares trofé",b="Dessa tunga, naggade yxor är standardutrustning för Blackrock-rövarna som tränger söderut från Burning Steppes in i Redridge. För Marshal Marris och den hårt pressade stadsvakten i Lakeshire fyller insamlingen två syften: att bekräfta att ännu en härjande orch har fallit och att samla fysiska bevis på hur tungt beväpnad den framryckande krigshären verkligen är."},{t="Hotet i bergen",b="Blackrock-inkräktarna har befäst Stonewatch Keep och etablerat fästen i de sydöstra delarna av Redridge, vilket i praktiken har stängt in stadsborna i Lakeshire. Att ta ifrån plundrarna deras slitna vapen minskar direkt krigshärens tillgång till vapen och röjer vägarna för Alliansens resor."}},faq={{q="Vad är en Battleworn Axe?",a="En Battleworn Axe är ett robust och välanvänt närstridsvapen som bärs av Blackrock-orcher i Redridge Mountains. Äventyrare samlar in dem som bevis på att inkräktare har dödats.",al={"information om battleworn axe","vad är det här för yxor","blackrock-yxa"}},{q="Vem vill ha dessa yxor i Lakeshire?",a="Marshal Marris, befälhavare för stadsvakten i Lakeshire, ber om dem för att bekräfta att Blackrock-hotet aktivt drivs bort från stadens marker.",al={"vem tar emot battleworn axe","uppdragsgivare för battleworn axe","marshal marris yxor"}},{q="Var kommer dessa yxor ifrån?",a="De tas från Blackrock-orcher i hela Redridge, särskilt kring Stonewatch Keep i norr och i fickorna av orchläger i sydöst.",al={"var får man battleworn axe","farma battleworn axe","vilka orcher har dem"}},{q="Varför är orcherna i Redridge från första början?",a="Blackrock-klanen marscherade söderut genom bergspassen från Burning Steppes, intog Stonewatch Keep och härjade i norra och östra Redridge för att hålla Lakeshire i schack.",al={"varför är blackrock-orcher i redridge","stonewatch-invasionen","orsaken till blackrock-hotet"}}},fp="14,178,20.278.0,23.242.0,25.150.0,34.140.0,30.138.0,48.185.0"}
P.entries["item:berard-s-journal"] = {n="Berard's Journal",s="Berard's Journal är en samling forskningsanteckningar som Apothecary Berard skrev innan han föll offer för Archmage Arugals förbannelse. Boken lämnades kvar i Pyrewood Village och dokumenterar Berards studier av en uråldrig pest som en gång utplånade allt vattenliv i Lake Lordamere, vilket gör den mycket värdefull för Royal Apothecary Society.",h="Berard's Journal är en samling forskningsanteckningar som Apothecary Berard skrev innan han föll offer för...",kw={"apothecary berard","apothecary renferrel","berard's journal","lake lordamere","master apothecary faranell","pyrewood village","royal apothecary society","silverpine forest"},ang={["faction:Horde"]="Genom att bege sig in i Pyrewood Village för att återta förlorad forskning hjälper du Forsaken att upprätta ett starkt försvarsfäste i Silverpine Forest.",["race:Undead"]="Varje fragment av giftig kunskap hjälper Royal Apothecary Society att säkra ett vapen som kan försvara Forsaken mot både Scourge och levande fiender."},sec={{t="Lake Lordameres förlorade forskning",b="Innan Archmage Arugal spred sin skuggmagi över Silverpine Forest ansågs Apothecary Berard vara ett av Royal Apothecary Societys mest lovande forskarämnen. Han var stationerad i Pyrewood Village och inriktade sitt arbete på en uråldrig, virulent farsot som hade utrotat allt vattenliv i Lake Lordamere flera århundraden tidigare. När Arugals förbannelse grep tag i bosättningen krossades Berards sinne och han blev ännu en tanklös träl. Hans detaljerade fältanteckningar blev kvar i en bokhylla i hans rum på värdshuset i Pyrewood Village."},{t="Bränsle till The New Plague",b="Även om Berard gick förlorad för sällskapet överlevde hans forskning intakt. Apothecary Renferrel vid The Sepulcher inser journalens strategiska värde och skickar Forsaken-agenter in i den fientliga byn för att hämta den. De insamlade anteckningarna om det uråldriga sjögiftet ger Master Apothecary Faranell och sällskapet i Apothecarium ett viktigt underlag för att skapa Forsakens egen nya pest."}},faq={{q="Vem var Apothecary Berard?",a="Apothecary Berard var en begåvad medlem av Royal Apothecary Society som bodde i Pyrewood Village. Han bedrev viktig forskning om historiska gifter när Archmage Arugal lade sin förbannelse över trakten, krossade Berards sinne och gjorde honom till slav.",al={"vem är berard","berards historia","apothecary berard"}},{q="Var finns Berard's Journal?",a="Journalen ligger i en bokhylla i Berards gamla arbetsrum på värdshusets övervåning i Pyrewood Village, djupt inne i södra Silverpine Forest.",al={"hitta berards journal","journalens plats","var finns boken"}},{q="Vilken forskning finns nedtecknad i journalen?",a="Journalen beskriver Berards upptäckter om en uråldrig smitta som i forna tider utplånade alla vattenlevande varelser i Lake Lordamere. Royal Apothecary Society hoppas kunna anpassa dessa giftiga egenskaper till sina egna kemiska vapen.",al={"vad finns i journalen","berards forskning","journalens innehåll"}},{q="Varför vill Apothecary Renferrel ha journalen?",a="Renferrel vill återta alla användbara vetenskapliga tillgångar innan de förstörs eller går förlorade för alltid. Berards unika insikter om smittan i Lake Lordamere ger Master Apothecary Faranell i Undercity viktiga beståndsdelar för att utveckla Forsakens nya pest.",al={"varför vill renferrel ha den","renferrels journaluppdrag"}}},fx={b3a0b77c={q="Vad är Berard's Journal?",a="Berard's Journal är en vetenskaplig forskningsdagbok sammanställd av Apothecary Berard, tidigare medlem i Royal Apothecary Society. Den innehåller hans detaljerade rön om en uråldrig smitta som för länge sedan utplånade allt vattenliv i Lake Lordamere. De Fördömda hoppas kunna studera den för sin egen alkemi.",al={"berard's journal","vad är berard's journal"}},["719e9fe0"]={q="Var kommer Berard's Journal ifrån, och vem skrev den?",a="Apothecary Berard skrev dagboken innan han förlorade förståndet till Archmage Arugals skuggmagi. Han hade sitt arbetsrum på värdshuset i Pyrewood Village. Där lämnade han boken i en bokhylla efter att ha blivit en viljelös träl.",al={"var kommer berard's journal ifrån","vem skrev berard's journal","berard's journal ursprung"}}},fp="16,172,31.448.0,23.370.1,26.208.0,32.142.0,41.209.0,47.238.0"}
P.entries["item:bernice-s-necklace"] = {n="Bernice's Necklace",s="På The Stonefield Farm i Elwynn Forest håller Bernice sin avlidne makes halsband nära sig.",h="På The Stonefield Farm i Elwynn Forest håller Bernice sin avlidne makes halsband nära sig.",kw={"auntie bernice","bernice's necklace","billy maclure","fargodeep mine","goldtooth","lyckobringande amulett","stonefield"},ang={["faction:Alliance"]="För alliansens jordbrukarfamiljer i Elwynn Forest påminner halsbandet om vilket pris Stormwinds långa militära fälttåg tar av vanliga människor."},sec={{t="En soldats förlorade amulett",b="Auntie Bernice Stonefields halsband tillhörde en gång hennes avlidne make, en veteran från Stormwinds militära fälttåg. Han bar det i strid som en lyckobringande amulett. Bernice säger att tragedin kom först under hans sista fälttåg, den enda expedition då han glömde att ta med det. Sedan hans död har minnessaken varit en av hennes käraste ägodelar på The Stonefield Farm."},{t="Stulet av asätare",b="Unge Billy Maclure utforskade området nära Fargodeep Mine när han tappade det glänsande halsbandet. Goldtooth, en framstående kobold inne i gruvan, fick syn på det och bar bort det. Liksom andra kobolder drogs han till blanka, värdefulla prydnadssaker, och han behöll halsbandet bland sina skatter från plundringar."}},faq={{q="Vem tillhörde halsbandet från början?",a="Halsbandet tillhörde Auntie Bernice Stonefields avlidne make, som bar det som en lyckobringande amulett under Stormwinds militära fälttåg.",al={"vem ägde halsbandet","bernice halsbandets ägare","makens halsband"}},{q="Hur hamnade halsbandet hos kobolderna?",a="Billy Maclure såg en stor kobold med guldtänder plocka upp halsbandet nära Fargodeep Mine och bära bort det. Auntie Bernice hoppas att det går att få tillbaka.",al={"hur tappades det bort","varför har goldtooth det","vem tog halsbandet"}},{q="Varför är halsbandet så viktigt för Auntie Bernice?",a="Halsbandet är ett kärt minne av Bernices avlidne make. Han trodde att det skyddade honom i strid, och den enda gången han stupade i krig var den dag han lämnade det hemma.",al={"varför vill bernice ha det","bernice makes historia","är halsbandet magiskt"}},{q="Vem är Goldtooth?",a="Goldtooth är en framstående koboldasätare med sitt tillhåll i Fargodeep Mine i Elwynn Forest. Han samlar på blanka prydnadssaker och tog halsbandet efter att det tappats i närheten.",al={"vad är goldtooth","goldtooths bakgrund","vem har halsbandet"}}},fp="18,85,22.376.0,20.291.1,35.138.0,45.154.0,51.165.0,17.181.0"}
P.entries["item:besseleth-s-fang"] = {n="Besseleth's Fang",s="Besseleth's Fang är den stora, giftiga tanden från den jättelika spindeln Besseleth i Sishir Canyon. Den bärs som bevis på hennes död och visar att ett dödligt hot mot stigarna i Stonetalon Mountains har undanröjts.",h="Besseleth's Fang är den stora, giftiga tanden från den jättelika spindeln Besseleth i Sishir Canyon.",kw={"spindelfobi","besseleth","besseleth's fang","maggran earthbinder","sishir canyon","stonetalon mountains","sun rock retreat","webwinder path"},ang={["class:Hunter"]="Att fälla en spindelmatriark och ta hennes två fot långa, giftiga tand är ett obestridligt bevis på en jägares skicklighet i spårning och strid.",["faction:Horde"]="När spindeln i ravinen röjs undan blir de farliga bergsstigarna mellan gränsen till The Barrens och Sun Rock Retreat tryggare."},sec={{t="Trofé från ravinens jägare",b="Sishir Canyon har länge varit hemsökt av aggressiva spindeldjur, men inget skrämmer resenärer mer än Besseleth. Hon växte till monstruös storlek, och tillsammans med sin avkomma gjorde hon ravinen till en dödsfälla för vandrare som tog sig fram längs Webwinder Path om natten. Själva tanden är nästan två fot lång och dryper av kraftigt gift, ett omisskännligt kännetecken på att spindelmamman har dödats. När försvararna i trakten, som har fått utstå hennes giftiga bett, får se denna makabra trofé kan de äntligen andas ut."}},faq={{q="Vad används Besseleth's Fang till?",a="Tanden är ett konkret bevis på att spindelmatriarken Besseleth har dödats. Maggran Earthbinder på Sun Rock Retreat satte en belöning på besten efter att nästan ha dött i ett angrepp från hennes huggtänder. Han belönar alla som tar trofén till honom.",al={"besseleths tand användning","vem vill ha besseleths tand","lämna in tanden"}},{q="Var kommer tanden ifrån?",a="Tanden tas direkt från Besseleth, en jättelik rovspindel som håller till i Sishir Canyon, väster om huvudvägen söder om Windshear Crag i Stonetalon Mountains.",al={"hur får man besseleths tand","var finns besseleth","besseleths plats"}},{q="Varför ville Maggran Earthbinder att Besseleth skulle dö?",a="Besseleth och hennes avkomma jagar regelbundet resenärer längs vägarna mot Sun Rock Retreat, särskilt när mörkret faller. Maggran Earthbinder blev själv överfallen och sårad av hennes huggtänder. Därför satte han upp en belöning för att säkra stigarna.",al={"varför döda besseleth","maggrans spindelbelöning","varför belöning på besseleth"}},{q="Vem satte upp belöningen för tanden?",a="Maggran Earthbinder godkände belöningen och satte upp den på en efterlysningsskylt längs huvudvägen söder om vägskälet vid Windshear Crag. Skylten varnar resenärer för farorna i Sishir Canyon.",al={"efterlysningsskylt spindel stonetalon","uppdragsgivare för spindelfobi"}}},fx={f0d9a9a7={q="Vad är Besseleth's Fang?",a="Besseleth's Fang är en enorm, sextio centimeter lång tand från rovdjursspindeln Besseleth. Hon och hennes avkomma jagar i Sishir Canyon och anfaller resenärer längs Webwinder Path om natten. Huggtanden är ett obestridligt fysiskt bevis på att den fruktade spindeln som terroriserat stigarna i Stonetalon äntligen har dödats.",al={"vad är besseleth's fang","besseleths tand","besseleths huggtand"}}},fp="16,77,28.326.0,34.228.0,31.177.0,48.226.0,35.165.0"}
P.entries["item:bethor-s-scroll"] = {n="Bethor's Scroll",s="Bethor's Scroll innehåller magiska besvärjelser som Bethor Iceshard skrev ned för att motverka sin tidigare kollega Thule Ravenclaws mörka trolldom. Rullen skapades för att hjälpa Apothecary Renferrel att brygga en skyddande dryck och är avgörande för att överleva Scourges nekromanti på Fenris Isle.",h="Bethor's Scroll innehåller magiska besvärjelser som Bethor Iceshard skrev ned för att motverka sin tidigare...",kw={"apothecary renferrel","bethor iceshard","bethor's scroll","fenris isle","rot hide","silverpine","the sepulcher","thule ravenclaw"},ang={["class:Mage"]="Rullen visar Kirin Tors splittrade förflutna och hur ingående kunskap om en medmagikers signaturmagi kan förvandlas till ett kraftfullt motmedel.",["race:Undead"]="Forsaken-magiker och apotekare förenar sina olika talanger genom detta pergament och blandar Dalarans gamla arkanutbildning med The Sepulchers nya alkemi."},sec={{t="Att motverka nekromantikern",b="Rullen är fylld av kraftfulla arkanformler, utformade som en bryggguide för Royal Apothecary Society, inte som ett offensivt vapen. När Apothecary Renferrel får den vid The Sepulcher ger den de exakta motbesvärjelser som krävs för att framställa en återställande dryck som kan skingra de försvagande förbannelser Thule väver runt sin fästning."},{t="En kollegas förräderi",b="När Bethor Iceshard undersökte förorenad vätska som återfunnits från Rot Hide-gnoller kände han igen Thule Ravenclaws verk. Thule var en gång en lovande ung magiker i Kirin Tor, men förrådde sina bröder för att tjäna Lich King när Scourge kom till makten. När Bethor fick veta att Thule överlevt och ledde Rot Hide-attacker i Silverpine Forest från Fenris Isle använde han sin ingående kunskap om sin tidigare kollegas magi för att skriva den här rullen."}},faq={{q="Vad står det på Bethor's Scroll?",a="Rullen beskriver särskilda arkanbesvärjelser som Bethor Iceshard har utformat. Eftersom han en gång studerade tillsammans med Thule Ravenclaw kände Bethor till nekromantikerns favoritbesvärjelser och skrev ned de exakta formler som behövs för att brygga en alkemisk motdryck.",al={"vad står det på rullen","innehållet i bethors scroll","vad finns på rullen"}},{q="Vem ska få den här rullen?",a="Rullen ska lämnas till Apothecary Renferrel, som befinner sig vid The Sepulcher i Silverpine Forest. Renferrel använder magin i den för att skapa en skyddande dryck.",al={"vem ska jag lämna rullen till","lämna in bethors scroll","vem får rullen"}},{q="Varför behöver Apothecary Renferrel magiska besvärjelser till en dryck?",a="Apothecary Renferrel är alkemist, inte traditionell magiker, och medger att han sällan väver in sådana tydliga krafter i sina brygder. Vanliga motgifter kan dock inte tränga igenom Scourges förbannelser som skyddar Thule, så Bethors arkanformler behövs för att drycken ska fungera.",al={"varför behöver en apotekare besvärjelser","renferrels magiska dryck"}},{q="Vem var Thule Ravenclaw innan han anslöt sig till Scourge?",a="Före det tredje kriget var Thule en lovande ung mänsklig magiker och en av Bethor Iceshards bekanta. När Lich King samlade sina odöda arméer övergav Thule sina medmagiker och svor trohet till Scourge.",al={"vem är thule ravenclaw","thules bakgrund","thule och bethor"}}},fx={["31160c67"]={q="Var kommer Bethor's Scroll ifrån, och vem skrev den?",a="Rullen skrevs av Bethor Iceshard, en odöd magiker som tjänar de Fördömda i Undercitys Magic Quarter. Han kände igen den magiska signaturen på den vidriga vätska som bärgats från Rot Hide-gnoller och insåg att hans tidigare kollega Thule Ravenclaw hade överlevt och anslutit sig till Scourge. Bethor använde sin ingående kunskap om Thules magiska tekniker för att skriva motbesvärjelser på pergamentet, så att hans förrädiske före detta jämlike kunde besegras.",al={"vem skrev bethor's scroll","vem skapade bethor's scroll","var kommer bethor's scroll ifrån"}},["64d2974c"]={q="Varför behövs Bethor's Scroll?",a="Apothecary Renferrel behöver de magiska besvärjelserna på rullen för att brygga ett skyddande motmedel. Thule Ravenclaw använder kraftfulla, förlamande förbannelser från sitt fäste på Fenris Isle. Genom att blanda Bethors magiska formler i en alkemisk dryck kan Royal Apothecary Society framställa en särskild brygd som skyddar dig mot Thules mörka trolldom när du möter honom.",al={"varför vill man ha bethor's scroll","varför är bethor's scroll viktig","vad används bethor's scroll till"}}},fp="15,218,26.250.1,22.417.1,35.223.0,25.141.0,69.277.0,54.231.0"}
P.entries["item:bingles-blastencapper"] = {n="Bingles' Blastencapper",s="Bingles' Blastencapper är en specialbyggd sprängladdning som konstruerats av gnompiloten Bingles Blastenheimer. Den försvann när hans gyrokopter störtade i The Loch och stals av lokala troggs, vilket hotade Bingles planer på att stödja befrielsen av Gnomeregan.",h="Bingles' Blastencapper är en specialbyggd sprängladdning som konstruerats av gnompiloten Bingles...",kw={"bingles","blastencapper","blastenheimer","sprängämnen","gnomeregan","gyrokopter","loch modan","trogg"},ang={["profession:Engineering"]="Blastencapper visar upp klassisk gnomisk ingenjörskonst: komplicerad, högexplosiv och förödande när den släpps från hög höjd.",["race:Gnome"]="Varje verktyg och varje sprängladdning räknas i kampen för att återta Gnomeregan, och om Bingles sprängladdning återtas kan gnomernas uppfinningsrikedom i luften slå tillbaka mot de invaderande troggsen."},sec={{t="En instabil uppfinning",b="Bingles' Blastencapper är höjdpunkten i pilotens Bingles Blastenheimers personliga vapenarsenal. Sprängladdningen byggdes för att leverera avgörande luftangrepp mot troggs och spetälskegnomer som tagit över Gnomeregan, och fanns ombord på hans gyrokopter när ett mekaniskt fel fick den att störta ner i The Loch. Bingles överlevde, men troggs som höll till på sjöns norra öar plundrade vraket och släpade det instabila vapnet tillbaka till sina läger."},{t="Luftunderstöd åt Gnomeregan",b="För Bingles är Blastencapper mycket mer än bara bärgat vrakgods. De förvisade gnomerna förbereder sig aktivt på att återta sitt radioaktiva hem, och Bingles anser att hans gyrokopter och signaturammunition är viktiga delar av det förestående luftangreppet. Om sprängladdningen återtas hindras Loch Modans urinvånare, troggs, från att råka utlösa en katastrof, och ett värdefullt vapen bevaras åt gnomernas motståndsrörelse."}},faq={{q="Vad är Bingles' Blastencapper?",a="Det är en specialbyggd, kraftfull sprängladdning som Bingles Blastenheimer konstruerat för luftangrepp till stöd för gnomernas kamp mot troggs och spetälskegnomer som ockuperar Gnomeregan.",al={"vad är blastencapper","blastencapper","bingles sprängladdning"}},{q="Hur hamnade Blastencapper i The Loch?",a="Bingles störtade med sin gyrokopter i The Loch. Innan han hann säkra sin utrustning plundrade troggs från de närliggande öarna hans havererade farkost och tog med sig hans verktyg och sprängladdningen.",al={"varför är den i the loch","hur förlorade bingles den","störtade"}},{q="Vem har Blastencapper nu?",a="Troggs som bor på de norra öarna i The Loch plundrade sprängladdningen från olycksplatsen och håller den bevakad i sitt primitiva läger.",al={"vem stal blastencapper","vem har den","troggs"}},{q="Varför behöver Bingles få tillbaka Blastencapper?",a="Utan sina verktyg och sin signaturammunition kan Bingles varken reparera sin gyrokopter eller inleda ett bombangrepp från luften till stöd för återerövringen av Gnomeregan.",al={"varför måste den tillbaka","varför är blastencapper viktig","för gnomeregan"}}},fp="22,159,20.394.0,26.383.0,31.121.0,45.144.0,36.110.0,49.141.0"}
P.entries["item:bingles-hammer"] = {n="Bingles' Hammer",s="Bingles' Hammer är ett ingenjörsverktyg som tillhör Bingles Blastenheimer, en excentrisk gnomisk flygare som strandat i Loch Modan. Efter att ha kraschat sin flygmaskin i The Loch plundrade fientliga trogger hammaren och hans övriga specialutrustning. Bingles behöver få tillbaka den så att han kan reparera sitt flygplan och bidra till krigsinsatsen för att befria Gnomeregan.",h="Bingles' Hammer är ett ingenjörsverktyg som tillhör Bingles Blastenheimer, en excentrisk gnomisk flygare som...",kw={"bingles","blastenheimer","gnomeregan","hammare","loch modan","verktygshink","trogg"},ang={["profession:Engineering"]="Varje hantverkare vet att en fin gnomtillverkad hammare är oersättlig, särskilt när man ska bygga upp en experimentell gyrokopter ute i vildmarken.",["race:Gnome"]="Varje återfunnet verktyg för Gnomeregans luftoffensiv ett steg närmare striden mot inkräktarna som stal ditt förfädershem."},sec={{t="En strandad flygares verktygslåda",b="När piloten Bingles Blastenheimer störtade ner i The Lochs vatten var hans överlevnad bara början på problemen. Troggerna som bodde på sötvattensöarna plundrade snabbt nedslagsplatsen och lade beslag på hans specialverktyg och högpotenta sprängämnen. Bland den stulna utrustningen fanns hans hammare, ett oumbärligt redskap för att reparera den buckliga flygkroppen och kalibrera gyrokopterns mekaniska delar. Utan detta viktiga verktyg och resten av sin utrustning är Bingles helt strandad och kan inte flyga understödsuppdrag för gnomernas befrielsestyrkor, som kämpar för att återta Gnomeregan."}},faq={{q="Var finns Bingles' Hammer?",a="Hammaren finns i en av Bingles's Toolbuckets, som ligger utspridda på de trogginfesterade öarna i de norra delarna av The Loch.",al={"hammarens plats","var finns bingles hammare","hur hittar man hammaren"}},{q="Vem tillhör hammaren?",a="Den tillhör Bingles Blastenheimer, en äventyrslysten gnomisk ingenjör och pilot som kraschade sin flygmaskin vid Loch Modans strand.",al={"vem äger hammaren","bingles hammare ägare"}},{q="Varför är verktyget så viktigt för Bingles?",a="Bingles behöver hela sin verktygsuppsättning för att bygga upp sin havererade gyrokopter, som han tänker flyga ut i strid för att stödja luftangreppet mot troggerna och de spetälska gnomerna som ockuperar Gnomeregan.",al={"varför behövs hammaren","bingles hammare användning"}},{q="Vem stal Bingles' Hammer?",a="Lokala trogger på sjöns öar överföll nedslagsplatsen och försvann med pilotens verktygshinkar och hans specialbyggda sprängkapslar.",al={"vem tog hammaren","troggtjuvar"}}},fp="15,199,28.404.0,35.120.0,31.132.0,41.156.0,26.122.0"}
P.entries["item:bingles-screwdriver"] = {n="Bingles' Screwdriver",s="Bingles' Screwdriver är ett oumbärligt ingenjörsverktyg som tillhör Bingles Blastenheimer, en gnompilot vars gyrokopter störtade i Loch Modans vatten. Efter kraschen plundrade lokala troggar vraket och spred Bingles verktygshinkar och specialutrustning över sjöns norra öar.",h="Bingles' Screwdriver är ett oumbärligt ingenjörsverktyg som tillhör Bingles Blastenheimer, en gnompilot vars...",kw={"bingles","blastenheimer","gyrokopter","loch modan","skruvmejsel","verktygshink","troggar"},ang={["profession:Engineering"]="Varje uppfinnare vet att en precisionskalibrerad skruvmejsel är oumbärlig för gyrokopterns komplicerade rotorer och känsliga avtryckarmekanismer.",["race:Gnome"]="Varje återfunnet verktyg för Bingles ett steg närmare att bygga upp farkosten igen och föra luftkrig mot troggarna och de spetälska gnomer som drev bort ditt folk från Gnomeregan."},sec={{t="En pilots livsviktiga utrustning",b="När Bingles Blastenheimer störtade ner i The Loch förlorade han mer än sin flygfarkost – han förlorade specialutrustningen som behövdes för att reparera den. Bland sakerna som spreds ut fanns hans pålitliga skruvmejsel, nedpackad i en av flera verktygshinkar som opportunistiska troggar från de närliggande öarna lade beslag på. För en ingenjör strandsatt i vildmarken är precisionsverktyg som den här skruvmejseln oersättliga, särskilt när han monterar känsliga gyrokoptermekanismer eller hanterar instabila vapen."},{t="Förberedelser inför återerövringen",b="Bingles är inte bara en nöjesflygare; han tjänar en större sak som går ut på att befria den fallna staden Gnomeregan från troggar och spetälska gnomer. Hans uppdrag bygger på att kombinera flygmekanik med hans instabila Blastencapper-ammunition för att slå till från luften mot hotet under jord. Att återfinna den här skruvmejseln tillsammans med hans skiftnyckel och hammare är avgörande för att sätta ihop gyrokoptern igen och hålla gnomernas luftburna motoffensiv vid liv."}},faq={{q="Var hittar man Bingles' Screwdriver?",a="Den återfinns i en av Bingles's Toolbuckets som ligger utspridda på öarna i norra Loch Modan, dit lokala troggar släpade pilotens tillhörigheter efter kraschen.",al={"skruvmejselns plats","hitta bingles skruvmejsel","var finns skruvmejseln"}},{q="Varför är skruvmejseln så viktig för Bingles?",a="Bingles behöver sina viktigaste ingenjörsverktyg för att bygga upp sin störtade gyrokopter igen och förbereda sina specialsprängämnen inför kampanjen för att återerövra Gnomeregan.",al={"varför behöver bingles den","vad används den till"}},{q="Vem stal skruvmejseln från början?",a="Troggar som höll till på öarna i The Loch överföll Bingles efter hans kraschlandning och tog hans verktygshinkar och Blastencapper-sprängämnen.",al={"vem tog verktygen","vem stal bingles verktyg"}},{q="Vilka andra verktyg förlorade Bingles i kraschen?",a="Förutom skruvmejseln förlorade Bingles sin skiftnyckel, sin hammare och sitt förråd av instabila Blastenheimer Blastencapper-sprängämnen.",al={"andra binglesverktyg","vad mer saknas"}}},fx={f72526b7={q="Vad är Bingles' Screwdriver?",a="Bingles' Screwdriver är ett ingenjörsverktyg som tillhör Bingles Blastenheimer, en gnomisk flygare som strandat i Loch Modan. Tillsammans med skiftnyckeln och hammaren är den ett av de viktigaste redskapen han hade med sig ombord på sitt gyrokopterplan. Med dem kunde han underhålla flygfarkosten och bygga ammunition åt det gnomiska motståndet.",al={"vad är bingles' screwdriver","information om bingles' screwdriver","om bingles' screwdriver"}}},fp="20,176,19.315.0,29.290.0,36.135.0,47.141.0,45.123.0,47.122.0"}
P.entries["item:bingles-wrench"] = {n="Bingles' Wrench",s="Bingles' Wrench är en oumbärlig del av den gnomiska ingenjörsutrustningen och tillhör piloten Bingles Blastenheimer. Den försvann när Bingles kraschade med sin flygmaskin i The Loch och fördes bort av traktens troggs tillsammans med resten av verktygslådan.",h="Bingles' Wrench är en oumbärlig del av den gnomiska ingenjörsutrustningen och tillhör piloten Bingles...",kw={"bingles","blastenheimer","gyrokopter","loch modan","verktygshink","troggs","skiftnyckel"},ang={["profession:Engineering"]="En hantverkare vet att en ingenjör utan sin specialanpassade skiftnyckel står helt stilla, särskilt när hungriga troggs är ute efter byte.",["race:Gnome"]="Varje återfunnet verktyg för den gnomiska motståndsrörelsen ett steg närmare att återta kampen i Gnomeregans bestrålade salar."},sec={{t="Bärgning på öarna",b="Efter att Bingles Blastenheimer kraschade med sin gyrokopter i The Lochs lugna vatten förvandlades överlevnaden snabbt till en prövning. Troggs på de små nordliga öarna plundrade olycksplatsen, stal hans specialutrustning och spred ut verktygen i olika hinkar i sina läger. Bingles' Wrench är ett av tre viktiga handverktyg som behövs tillsammans med hans kraftfulla Blastencapper-sprängämnen. Utan den har Bingles inget hopp om att reparera sin kraschade gyrokopter, vilket sätter stopp för hans planerade luftoffensiv till stöd för de förvisade gnomerna som kämpar för att återta Gnomeregan."}},faq={{q="Vem tillhör skiftnyckeln?",a="Skiftnyckeln tillhör Bingles Blastenheimer, en excentrisk gnompilot som kraschade med sin gyrokopter i The Loch i Loch Modan.",al={"vem är bingles","bingles ägare","skiftnyckelns ägare"}},{q="Varför är skiftnyckeln så viktig för Bingles?",a="Bingles behöver sina specialverktyg för att reparera sin skadade flygmaskin och förbereda sin sprängladdning, så att han kan inleda ett luftangrepp mot troggs och spetälskegnomer som ockuperar Gnomeregan.",al={"varför behöver bingles sin skiftnyckel","skiftnyckelns syfte","vad används skiftnyckeln till"}},{q="Vart tog skiftnyckeln vägen efter kraschen?",a="Traktens troggs lade beslag på skiftnyckeln och gömde den i en av Bingles' stulna verktygshinkar, som ligger utspridda på The Lochs nordliga öar.",al={"var finns bingles skiftnyckel","skiftnyckelns plats","hitta bingles skiftnyckel"}},{q="Vad mer stals tillsammans med skiftnyckeln?",a="Förutom skiftnyckeln tog troggs Bingles' Screwdriver, Bingles' Hammer och hans experimentella Blastenheimer Blastencapper-sprängämnen.",al={"annan utrustning","saknade verktyg","vad mer tog troggs"}}},fp="15,153,22.518.0,31.109.0,42.182.0,44.141.0,43.120.0"}
P.entries["item:black-claw-stout"] = {n="Black Claw Stout",s="Under Stormwind tillagar Zardeth of the Black Claw en dryck åt Lord Wishock. Stouten serveras som en vanlig krogbeställning.",h="Under Stormwind tillagar Zardeth of the Black Claw en dryck åt Lord Wishock.",kw={"black claw stout","hall of petitioners","lord wishock","gift","slaughtered lamb","stormwind keep","zardeth"},ang={["class:Warlock"]="För Stormwinds dolda kriglockskult är brygden ett enkelt ärende. En näsvis adelsman vill stänga deras tillhåll under Slaughtered Lamb.",["faction:Alliance"]="När brygden förs in i Stormwind Keep kommer kriglockarna som verkar under Slaughtered Lamb nära huvudstadens adelsmän."},sec={{t="En giftig dryck",b="Zardeth of the Black Claw verkar under Stormwinds stadsvakts radar, i verksamheten under Slaughtered Lambs krogsalar. Lord Wishock hotar gång på gång att stänga den, trots att han samlar på sig obetalda notor där uppe. Zardeth bestämmer sig för att kvitta skulden genom att utnyttja adelsmannens svaghet för starka drycker. Han döljer en dödlig dos i en vanlig kroguppfriskning."},{t="Tyst lönnmord",b="Lord Wishock får stouten i Stormwind Keeps Hall of Petitioners. Hans högfärdiga arrogans och törst gör att han gärna tar emot det han misstar för en tjänare som uppmärksamt bjuder honom. Adelsmannen sveper drycken på stående fot. Giftet verkar nästan omedelbart och tystar en av kultens mest ihärdiga politiska kritiker mitt framför näsan på Royal Court."}},faq={{q="Vad är Black Claw Stout?",a="Zardeth of the Black Claw brygger Black Claw Stout i katakomberna under Slaughtered Lamb i Stormwinds Mage Quarter åt Lord Wishock.",al={"vad är det här för dryck","black claw stout-lore","giftbrygd"}},{q="Vem är målet för stouten?",a="Lord Wishock är målet, en högdragen adelsman i Hall of Petitioners som försöker stänga kriglockarnas tillhåll samtidigt som han dricker där på kredit.",al={"vem dricker den","vem dör av black claw stout","wishock som mål"}},{q="Vem skapade brygden?",a="Zardeth of the Black Claw brygger stouten i kryptorna under Slaughtered Lamb.",al={"skaparen av black claw stout","vem gjorde den här","zardeths brygd"}},{q="Varför får Lord Wishock stouten?",a="Zardeth skickar Lord Wishock stouten i Hall of Petitioners och ber budbäraren ta reda på vad adelsmannen tycker om hans specialbrygd.",al={"dör wishock","black claw stout-effekt"}}},fx={a6b6f1b7={q="Varför vill Zardeth att du levererar Black Claw Stout till Lord Wishock?",a="Lord Wishock är en hycklande adelsman som ägnar dagarna åt att försöka stänga Slaughtered Lamb och nätterna åt att dricka där uppe och samla på sig en obetald nota. För att tysta honom för gott har Zardeth kokat ihop en dödlig specialbrygd som utnyttjar Wishocks svaghet för sprit. Den ska röja honom ur vägen under förevändningen att han får en uppfriskande drink.",al={"varför leverera black claw stout","varför ge black claw stout till wishock","varför zardeth ger stout till wishock"}}},fp="16,134,15.367.1,19.354.1,25.143.0,31.151.0,21.85.0,38.128.1"}
P.entries["item:black-feather-quill"] = {n="Black Feather Quill",s="Black Feather Quill är en helig Night Elf-relik som Druids of the Talon använder vid sina riter för att gå i dvala och vakna. Den förvaras i en särskild kista i Ban'ethil Barrow Den och är ett av flera viktiga fokus som behövs för att säkert kalla sovande druider tillbaka från The Emerald Dream.",h="Black Feather Quill är en helig Night Elf-relik som Druids of the Talon använder vid sina riter för att gå i...",kw={"athridas bearmantle","ban'ethil barrow den","black feather quill","chest of the black feather","dolanaar","druids of the talon","relics of wakening"},ang={["class:Druid"]="För druiderna står fjäderpennan för de heliga redskap som håller Talons utövare förankrade i den vakna världen medan deras andar möter The Emerald Dream.",["race:NightElf"]="Night Elves ser hur Gnarlpine furbolgs vanhelgar Ban'ethils relikkistor som ännu en smärtsam påminnelse om korruptionen som sprider sig över Teldrassil."},sec={{t="Ett uppvaknandets kärl",b="Night Elf-druidism bygger på heliga föremål med stark förankring, som hjälper druiderna att navigera gränsen mellan den vakna världen och The Emerald Dream. Black Feather Quill, tillsammans med Raven Claw Talisman, Sapphire of Sky och Rune of Nesting, utgör kärnan i den uppsättning rituella föremål som krävs för att bryta Druids of the Talons sköra dvala. Utan dessa fokus riskerar en sovande druid att bli kvar i drömmen för alltid och kan då inte återvända till sin vakna kropp."},{t="Hotet i Ban'ethil",b="När korrumperade Gnarlpine furbolgs invaderade Ban'ethil Barrow Den hotades de heliga kistorna där skatterna förvarades. Relikerna låg oskyddade i de vindlande djupen och måste snabbt återhämtas på order av Athridas Bearmantle i Dolanaar, innan de tillfångatagna druiderna förlorades för alltid i drömmen."}},faq={{q="Vad används Black Feather Quill till?",a="Fjäderpennan är en av de fyra Relics of Wakening som behövs för att säkert väcka Druids of the Talon ur deras rituella dvala i The Emerald Dream.",al={"syftet med black feather quill","varför behövs black feather quill","vad gör fjäderpennan"}},{q="Var förvaras Black Feather Quill?",a="Den förvaras i Chest of the Black Feather, djupt inne i Ban'ethil Barrow Den i centrala Teldrassil.",al={"black feather quill plats","var finns chest of black feather","fjäderpennans plats"}},{q="Varför kan druiderna inte vakna utan fjäderpennan och de andra relikerna?",a="Druidernas dvala innebär att de träder in i The Emerald Dream under sköra förtrollningar. För att bryta transen krävs särskilda heliga fokus. Utan dem kan den sovande anden inte hitta tillbaka till sin fysiska kropp.",al={"varför behöver druider reliker för att vakna","kan druider vakna på egen hand"}},{q="Vem ber om Black Feather Quill?",a="Athridas Bearmantle i Dolanaar skickar äventyrare för att hämta fjäderpennan och de andra Relics of Wakening och rädda de hotade druiderna.",al={"vem behöver fjäderpennan","uppdragsgivare för black feather quill"}}},fx={["8b872c36"]={q="Vad är Black Feather Quill?",a="Black Feather Quill är en av de fyra heliga relikerna för uppvaknande som nattalvernas druider i Talon bevarar i Ban'ethil Barrow Den på Teldrassil. Den förvaras i en särskild kista och är en viktig ceremoniell del i att fredligt väcka druider som slumrar i The Emerald Dream.",al={"vad är black feather quill","föremålet black feather quill","berättelsen om black feather quill"}}},fp="19,93,20.360.0,23.221.0,41.140.0,38.122.0,64.185.0,37.151.0"}
P.entries["item:blackened-skull"] = {n="Blackened Skull",s="En förkolnad skalle är den mörknade kranierest som blir kvar efter en Darkeye Bonecaster som rör sig i Agamand Mills. Deathguard Dillinger i Brill kräver dessa makabra troféer som bevis på att de tanklösa Scourge-styrkorna som hotar Tirisfal Glades decimeras.",h="En förkolnad skalle är den mörknade kranierest som blir kvar efter en Darkeye Bonecaster som rör sig i...",kw={"agamand mills","blackened skull","brill","darkeye bonecaster","deathguard dillinger","notched rib","scourge","kvarnarna överrumplade"},ang={["class:Mage"]="Skallarna är fysiska kvarlevor efter Darkeye Bonecasters, skelettmagikerna som jagas i Agamand Mills.",["race:Undead"]="För Forsaken handlar det om ren överlevnad att fälla Darkeye Bonecasters och hindra deras forna mästare från att etablera en uppmarschplats inpå knuten."},sec={{t="Troféer från Bonecasters",b="De här förkolnade skallarna tas till vara från Darkeye Bonecasters som hemsöker Agamand Mills. Dessa skelettmagiker riktar nekromantisk illvilja mot både levande och Forsaken och försöker befästa en framskjuten bas för Lich Kings arméer i norra Tirisfal. När deras krossade skallar överlämnas till Deathguard Dillinger blir de ett påtagligt bevis på att Scourges magiska förtrupp krossas."}},faq={{q="Var kommer förkolnade skallar ifrån?",a="De samlas in från kvarlevorna efter Darkeye Bonecasters, skelettmagiker som stryker omkring på fälten och bland byggnaderna runt Agamand Mills i norra Tirisfal Glades.",al={"källa till förkolnade skallar","vem släpper förkolnade skallar","var får man förkolnade skallar"}},{q="Varför vill Deathguard Dillinger ha förkolnade skallar?",a="Deathguard Dillinger ger Forsaken-försvarare i uppdrag att samla in förkolnade skallar och hackade revben som bevis på aktiv strid mot Scourge. Forsaken kan inte låta Lich Kings tanklösa undersåtar få fotfäste så nära Brill och Undercity.",al={"dillingers skallar","varför samla skallar","skallar från överrumplade kvarnar"}},{q="Varför är skallarna förkolnade?",a="Ingen i Brill säger vad som har förkolnat dem. Deathguard Dillinger vill bara ha dem som bevis på att Darkeye Bonecasters i Agamand Mills förstörs.",al={"varför är den förkolnad","historien om förkolnad skalle"}},{q="Vad gör Scourge i Agamand Mills?",a="Scourge försöker befästa de övergivna Agamand Mills som en framskjuten uppmarschplats och använda den för att inleda djupare attacker och räder över Tirisfal Glades.",al={"scourge i agamand mills","varför är scourge vid kvarnarna"}}},fx={d39fbd85={q="Vad är Blackened Skull?",a="Blackened Skull är en kuslig trofé som tagits från Darkeye-bensvärjare som hemsöker Agamand Mills. De mörka kvarlevorna är ett fysiskt bevis för de Fördömdas dödsvakter på att ännu en Scourge-besvärjare har oskadliggjorts innan den kunnat hjälpa till att bygga upp en fiendebas i Tirisfal Glades.",al={"vad är blackened skull","föremålet blackened skull","berättelsen om blackened skulls"}}},fp="15,178,25.348.0,36.153.0,52.236.0,29.155.0,43.141.0"}
P.entries["item:bloodfeather-belt"] = {n="Bloodfeather Belt",s="Ett Bloodfeather Belt är en grov läderrem som bärs av Bloodfeather-harpiorna som härjar i norra Teldrassil. Sentinel Arynia Cloudsbreak samlar in bältena som bevis på att de lokala nästena nära The Oracle Glade har rensats.",h="Ett Bloodfeather Belt är en grov läderrem som bärs av Bloodfeather-harpiorna som härjar i norra Teldrassil.",kw={"arynia cloudsbreak","bloodfeather","bloodfeather belt","harpia","the oracle glade","teldrassil","den förtrollade gläntan"},ang={["faction:Alliance"]="När du hjälper Sentinel Arynia Cloudsbreak kan viktiga rapporter från Teldrassils uråldriga träd nå ledarna i Darnassus utan avbrott.",["race:NightElf"]="Bloodfeather-häxkoven vanhelgar Teldrassils naturliga lövverk, och att återta The Oracle Glade från deras skrikande nästen är en viktig plikt för alla som försvarar Kaldoreis hemland."},sec={{t="Troféer från nästena",b="Bloodfeather-harpiorna har slagit sig ner aggressivt i grenarna runt The Oracle Glade och hotar The Oracle Tree samt hindrar resor genom norra Teldrassil. När flocken överföll och dödade en budbärare på väg med rapporter till Darnassus uppmanade Sentinel Arynia Cloudsbreak resande att slå tillbaka direkt mot nästena. Bälten från fallna harpior är ett konkret bevis på att deras antal minskar och att vägarna säkras så att kontakten med huvudstaden kan återupptas."}},faq={{q="Varför vill Sentinel Arynia Cloudsbreak ha de här bältena?",a="Arynia Cloudsbreak och hennes lilla grupp av Sentinels är stationerade där för att skydda det heliga The Oracle Tree från de omgivande Bloodfeather-nästena. Eftersom harpiorna nyligen dödade en budbärare på väg till Darnassus kräver Arynia bältena som fysiskt bevis på att äventyrare rensar nästena och minskar flockens antal.",al={"varför arynia vill ha bälten","bloodfeather belt syfte","varför samla bälten"}},{q="Var kommer Bloodfeather Belts ifrån?",a="De tas från Bloodfeather-harpiorna som håller till i träden och klipporna runt The Oracle Glade i norra Teldrassil. Alla sorters harpior i flocken bär dem, däribland vindhäxor, trollkvinnor, skurkar och furier.",al={"vem släpper bloodfeather belt","var får man tag på bälten","bloodfeather belt plats"}},{q="Varför är harpiorna ett problem i The Oracle Glade?",a="Harpiorna har byggt bon nära The Oracle Tree, ett uråldrigt och vördat träd som vakar över världsträdets hälsa. Deras aggressiva närvaro isolerar Sentinels som vaktar gläntan och stör våldsamt meddelanden på väg tillbaka till Darnassus.",al={"harpior i the oracle glade","varför finns harpior i teldrassil","harpiornas hot mot the oracle tree"}}},fx={["40b720b3"]={q="Vad är Bloodfeather Belt?",a="Bloodfeather Belt är ett personligt smycke som bärs av Bloodfeather-harpiorna som hemsöker The Oracle Glade i norra Teldrassil. För nattalverna som är stationerade där är de här grova bältena troféer och ett påtagligt bevis på att ännu en vildsint harpia har gallrats ut från de heliga grenarna.",al={"information om bloodfeather belt","vad är bloodfeather belts","berättelsen om bloodfeather belt"}}},fp="17,193,23.482.0,54.290.0,38.203.0,46.225.0"}
P.entries["item:bloodfury-ripper-s-remains"] = {n="Bloodfury Ripper's Remains",s="Bloodfury Ripper's Remains är de fysiska bevis som hämtats från matriarken bland harpyorna i The Charred Vale. Maggran Earthbinder vid Sun Rock Retreat vill ha dem. Trofén bekräftar att den glupska ledaren för flocken är död och ger ett avgörande slag mot harpyornas närvaro, som hotar den lokala taurenbosättningen.",h="Bloodfury Ripper's Remains är de fysiska bevis som hämtats från matriarken bland harpyorna i The Charred Vale.",kw={"bloodfury ripper","the charred vale","harpyor","maggran earthbinder","kvarlevor","stonetalon","sun rock retreat"},ang={["faction:Horde"]="När vilda faror som Bloodfury-matriarken röjs undan blir färden tryggare för Hordens karavaner och spejare mellan The Barrens och Stonetalon.",["race:Tauren"]="Bloodfury-harpyorna hotar direkt säkerheten vid Sun Rock Retreat. Att samla in deras ledares kvarlevor är därför en hängiven handling för att skydda fredliga taurenbosättningar i Stonetalon."},sec={{t="Bryta blodslinjen",b="Bloodfury-harpyorna som håller till bland de förkolnade ruinerna i The Charred Vale har länge utgjort ett vilt hot mot resenärer och schamaner i Stonetalon Mountains. Att minska deras antal dämpar den omedelbara faran, men Maggran Earthbinder från Sun Rock Retreat inser att ett verkligt andrum kräver att deras ledare röjs ur vägen. Bloodfury Ripper styr sin flock nästan som en drottning och eldar på dess territoriella aggression. Hennes kvarlevor är ett nödvändigt bevis på hennes död. De skingrar de återstående harpyorna och ger sinnesro åt taurenfolket, som kämpar för att läka och säkra sina karga marker."}},faq={{q="Vad används Bloodfury Ripper's Remains till?",a="De är obestridliga fysiska bevis på att Bloodfury Ripper är död. Maggran Earthbinder vid Sun Rock Retreat begär dem för att bekräfta att den drottninglika ledaren för de lokala harpyorna har undanröjts för gott.",al={"vad används kvarlevorna till","kvarlevornas syfte","vem vill ha kvarlevorna"}},{q="Var hittar man Bloodfury Ripper?",a="Bloodfury Ripper stryker längs kullarna i västra och nordvästra delen av The Charred Vale, i södra Stonetalon Mountains. Hennes blå fjäderdräkt skiljer henne från flocken, som är röd och vit.",al={"bloodfury ripper plats","var finns ripper","hitta bloodfury ripper"}},{q="Varför vill Maggran Earthbinder att hon ska dö?",a="Maggran tror att det aldrig räcker att bara decimera vanliga harpyor för att stoppa deras räder mot markerna runt omkring. När deras matriark dödas bryts hierarkin och deras förmåga att samla sig mot Sun Rock Retreat försvagas.",al={"varför döda bloodfury ripper","maggrans motiv","varför ripper ska dö"}}},fx={ba88af47={q="Var kommer Bloodfury Ripper's Remains ifrån?",a="De här kvarlevorna skärs ut ur Bloodfury Ripper själv efter att hon dödats bland de västra kullarna i The Charred Vale. Till skillnad från sina röda och vita fränder leder denna blåfjädrade harpyja Bloodfury-kullen från dalens ödsliga klippor och är därför ett eftertraktat mål för den som vill bryta flockens ledning.",al={"var kommer bloodfury ripper's remains ifrån","vem släpper bloodfury ripper's remains","bloodfury ripper's remains ursprung"}},["81140692"]={q="Varför vill Maggran Earthbinder ha Bloodfury Ripper's Remains?",a="Maggran Earthbinder vid Sun Rock Retreat kräver kvarlevorna som bevis på att Bloodfury-harpyjornas matriark verkligen är död. Att bara minska deras antal hade aldrig räckt. Maggran tror att om deras drottning fälls blir de överlevande harpyjorna hjälplösa och deras antal kommer att minska, så att han slipper den bittra vrede som slukat hans tankar.",al={"varför vill maggran ha bloodfury ripper's remains","varför vill man ha bloodfury ripper's remains","vem vill ha bloodfury ripper's remains"}},ff70f27b={q="Vad är Bloodfury Ripper's Remains?",a="De här makabra kvarlevorna är ett fysiskt bevis från kroppen av Bloodfury Ripper, matriarken och ledaren för Bloodfury-harpiorna som hemsöker The Charred Vale. Hon fungerar nästan som en drottning för sin flock och leder deras aggressiva spridning över Stonetalon. Hennes döda kropp är ett obestridligt bevis på att hennes blodiga välde över dalens harpior har fått ett slut.",al={"vad är bloodfury ripper's remains","vem är bloodfury ripper"}}},fp="26,181,22.586.0,45.173.0,36.183.0,43.227.0"}
P.entries["item:bloodstone-choker"] = {n="Bloodstone Choker",s="I Stormwind binder Bloodstone Choker en häxmästares ritual till tomrummet. Gakin the Darkbinder bar en gång blodstenstalismannen, tills en lärling stal den och flydde till Defias Brotherhood.",h="I Stormwind binder Bloodstone Choker en häxmästares ritual till tomrummet.",kw={"bloodstone choker","defias","gakin the darkbinder","surena caledon","bindningen","the slaughtered lamb","voidwalker","häxmästare"},ang={["class:Warlock"]="Som häxmästare i Alliance markerar återtagandet av Bloodstone Choker en övergångsrit från grundläggande besvärjelser till befälet över mäktiga demoniska hantlangare.",["faction:Alliance"]="Surena Caledons flykt till Defias Brotherhood visar att laglösa i Elwynn söker farliga ockulta reliker för att stärka sitt uppror mot Stormwind."},sec={{t="En stulen kanal",b="Bloodstone Choker tillhörde en gång Gakin the Darkbinder, en häxmästare som undervisade i kamrarna under Slaughtered Lamb i Stormwind. Hans lärling, Surena Caledon, förrådde honom och stal halsbandet. Hon flydde in i Elwynn Forests skogar och anslöt sig till Defias Brotherhood med den förtrollade talismanen. Hon finns vid Brackwell Pumpkin Patch, där halsbandet måste återtas innan banditerna kan använda dess kraft."},{t="Täjma tomrummet",b="Halsbandet är uthugget ur blodsten och kan överbrygga den dödliga världen och Twisting Nethers slingrande skuggor. Gakin använder det i katakomberna under värdshuset och kanaliserar dess magi vid åkallandecirkeln för att dra fram en fientlig Voidwalker ur tomrummet. En häxmästare måste kuva den rasande varelsen i direkt strid medan talismanen är i bruk, för att bevisa sin vilja att befalla en sådan väktare."}},faq={{q="Vad är Bloodstone Choker?",a="Bloodstone Choker är ett förtrollat halsband av blodsten som häxmästare använder som rituell kanal. Dess magi kan slita upp verkligheten och åkalla en bångstyrig Voidwalker från Nether.",al={"bloodstone choker","vad är halsbandet","vad gör halsbandet"}},{q="Vem ägde halsbandet från början?",a="Gakin the Darkbinder ägde ursprungligen halsbandet. Han tränar häxmästare i den dolda källaren under The Slaughtered Lamb i Stormwinds Mage Quarter.",al={"vem äger halsbandet","gakin halsband","varifrån kom halsbandet"}},{q="Varför stals halsbandet?",a="Surena Caledon stal halsbandet från sin mentor, Gakin, och flydde sedan för att ansluta sig till Defias Brotherhood. Hon sökte makt bland banditerna som gömde sig i Elwynn Forest.",al={"vem stal det","varför stal surena det","surena caledon halsband"}},{q="Hur används halsbandet i häxmästarträning?",a="En häxmästare aktiverar det återfunna halsbandet över åkallandecirkeln i katakomberna under The Slaughtered Lamb. Det lockar fram en Voidwalker, som den blivande häxmästaren måste besegra och kuva för att kunna befalla demonen.",al={"hur använder man halsbandet","voidwalker ritualhalsband","det bindande halsbandet"}}},fx={["9d3659ea"]={q="Varför vill man ha Bloodstone Choker?",a="Gakin the Darkbinder värdesätter Bloodstone Choker som en kraftfull magisk katalysator som behövs för att kalla fram och binda en voidwalker. Hans tidigare lärling Surena Caledon stal den för att hjälpa Defias Brotherhood. Nu vill Gakin få tillbaka den, återupprätta sin magiska auktoritet och sätta nya warlocks på prov i kryptorna under Slaughtered Lamb.",al={"varför vill de ha bloodstone choker","vem vill ha bloodstone choker","varför vill gakin ha halsbandet"}}},fp="17,196,16.422.1,15.389.0,30.180.0,32.151.0,26.157.0,43.209.0"}
P.entries["item:blueleaf-tuber"] = {n="Blueleaf Tuber",s="Blueleaf Tubers är ovanligt sällsynta rotfrukter som växer gömda under den taggiga marken i Razorfen Kraul. De uppskattas världen över som en exotisk delikatess och är nästan omöjliga att hitta med blotta ögat.",h="Blueleaf Tubers är ovanligt sällsynta rotfrukter som växer gömda under den taggiga marken i Razorfen Kraul.",kw={"the barrens","blueleaf tuber","mebok mizzyrix","ratchet","razorfen kraul","snufflenose-gopher","knöl"},ang={["profession:Cooking"]="Dessa rötter är kända som uppskattade delikatesser världen över och eftertraktas av de allra rikaste finsmakarna, trots att de växer i quilboarhålornas ogästvänliga jord."},sec={{t="En sällsynt underjordisk delikatess",b="Blueleaf Tubers hör hemma i The Barrens, men växer bara djupt under jord under Razorfen Kraul. De är gömda bland täta rotsystem och quilboarens törnbuskar och förblir oupptäckta för den som bara letar lite förstrött. Trots de svåra växtförhållandena betalar välbärgade finsmakare och handelsmän världen över hutlösa priser för deras unika smak."},{t="Skörd med hjälp av jordekorrar",b="Eftersom rötterna är svåra att upptäcka för dem som rör sig ovan jord kom den driftige goblinen Mebok Mizzyrix i Ratchet på en ovanlig skördemetod. Genom att träna inhemska snufflenose-gophers att känna lukten av knölarna på femtio stegs avstånd kan äventyrare, vägledda av särskilda kommandostavar, gräva upp rötterna innan quilboarpatrullerna anar intrånget."}},faq={{q="Vad används Blueleaf Tubers till?",a="Blueleaf Tubers säljs som sällsynta delikatesser. Välbärgade kunder och exotiska handelsmän betalar extra för deras särpräglade smak och sällsynthet.",al={"användning av knölar","varför skaffa blueleaf tubers","vad används knölar till"}},{q="Var hittar man Blueleaf Tubers?",a="De växer bara djupt under jord i södra The Barrens, bland snåren och de underjordiska hålorna i Razorfen Kraul.",al={"var växer blueleaf tubers","knölarnas plats","var finns knölar"}},{q="Varför behöver du en jordekorre för att gräva upp dem?",a="Knölarna växer gömda under matjorden och kan inte ses av människor eller gobliner. Snufflenose-gophers tränas att känna lukten av dem på femtio stegs avstånd och gräva upp dem på kommando.",al={"varför snufflenose-gopher","jordekorrens uppgift","varför jordekorrar"}},{q="Vem köper de här knölarna?",a="Mebok Mizzyrix, en goblinentreprenör verksam i Ratchet, köper dem för att sälja vidare till välbärgade köpare och internationella kontakter med rejäl vinst.",al={"vem vill ha blueleaf tubers","vem köper knölar","mebok-knölar"}}},fx={["9eab4987"]={q="Vad är en Blueleaf Tuber?",a="En Blueleaf Tuber är en mycket sällsynt ätlig rot som ligger djupt begravd i Razorfen Kraul. Den är eftertraktad för sitt kulinariska värde och räknas som en delikatess i hela världen, men det är farligt att samla in den eftersom quilboar härjar i dess hemtrakter.",al={"vad är blueleaf tuber","blueleaf tuber bakgrund","vad är blueleaf tubers"}},["094c1930"]={q="Var kommer Blueleaf Tuber ifrån?",a="Blueleaf Tubers är naturliga underjordiska rötter som bara finns i södra Barrens och växer djupt bland de trassliga rotsystemen i Razorfen Kraul. Ingen tillverkar dem. I stället skördas de direkt ur den underjordiska jorden med tränade snufflenose-gophers som får nosa upp dem.",al={"blueleaf tuber ursprung","var växer blueleaf tubers","vem tillverkade blueleaf tubers"}}},fp="14,141,27.249.0,26.273.0,34.113.0,35.121.0,40.170.0,22.151.0"}
P.entries["item:book-from-sven-s-farm"] = {n="Book from Sven's Farm",s="Book from Sven's Farm är en jordfläckad dagbok utan titel, uppgrävd bland ruinerna av Sven Yorgens plundrade gård i Duskwood. De splittrade anteckningarna avslöjar att en okänd iakttagare bevittnade massakern på Svens familj, vilket utlöste en outtröttlig jakt genom de skuggiga skogarna.",h="Book from Sven's Farm är en jordfläckad dagbok utan titel, uppgrävd bland ruinerna av Sven Yorgens plundrade...",kw={"book from sven's farm","darkshire","defias brotherhood","duskwood","jitters","skuggig gestalt","sven yorgen","worgen"},ang={["faction:Alliance"]="För Alliansens utredare är den här väderslitna boken nyckeln till att lösa de kusliga fasor som lamslår södra Duskwood och ta reda på hur den vilda worgenflocken fick fäste."},sec={{t="En ledtråd i jorden",b="Nedgrävd i en lös jordhög bland de förkolnade resterna av Svens gård i södra Duskwood innehåller den här oansenliga, väderslitna boken de febrila anteckningarna från en anonym vandrare. Anteckningarna ger ofullständiga glimtar av tragedin som drabbade gården och bekräftar Sven Yorgens mörkaste misstanke: någon lurade i skuggorna medan hans familj slaktades. Eftersom berättelsen slutar abrupt väcker boken fler frågor än den besvarar och får utredare att ta med den tillbaka till Darkshire i hopp om att hitta någon som känner igen handstilen eller den gåtfulle författaren."},{t="Den skuggiga gestalten",b="När dagboken visas för mystikerna och stadsborna i Darkshire avslöjas att dess verkliga ägare inte kom därifrån, utan flydde genom skogen i ren skräck. Spåren av blekta avtryck på sidorna leder till slut till Jitters, en feg lösdrivare som gömmer sig i skogen. De saknade avsnitten i boken berättar hur Defias Brotherhood blandade sig i förbjudna artefakter och oavsiktligt släppte lös de glupska worgen i Duskwood. När Jitters hittas kan berättelsen pusslas ihop, och den fullständiga dagboken kommer fram."}},faq={{q="Var hittar man Book from Sven's Farm?",a="Boken är nedgrävd i en ovårdad jordhög vid Sven Yorgens gårdsruin i södra Duskwood.",al={"var hittar man svens bok","jordhög vid svens gård","svens bok plats"}},{q="Vem skrev boken som hittades på Svens gård?",a="Boken saknar titel och namn. Författaren är en skräckslagen man som flydde från en fasa någon annanstans i Duskwood och gömde sig i Svens lada. Där bevittnade han slakten på Svens familj innan han förlorade sin dagbok.",al={"svens boks författare","vem skrev den jordfläckade boken","vem skrev dagboken"}},{q="Varför vill Sven Yorgen ha den här boken?",a="Sven såg en okänd gestalt smyga omkring nära sin lada efter att hans familj hade attackerats. Boken bevisar att iakttagaren fanns på riktigt och ger Sven den enda konkreta ledtråden till vad som egentligen hände den natten.",al={"varför bryr sig sven","sven yorgens reaktion på boken"}},{q="Vad händer med boken efter att du har undersökt den?",a="Efter att den ofullständiga boken visats för olika invånare i Darkshire och dess ägare spårats upp ersätts den till slut av Jitters' Completed Journal, som berättar hela historien.",al={"vad ersätter svens bok","behåller man svens bok"}},{q="Vilken större hemlighet hänger samman med bokens innehåll?",a="Den fullständiga dagboken förklarar vad som drev författaren att gömma sig och varför Svens familj attackerades. Berättelsen sträcker sig långt bortom en enda gård och handlar om mörkret som har sänkt sig över Duskwood.",al={"vilken historia finns i svens bok","worgenkoppling","defias-koppling"}}},fx={fd4c7f5f={q="Vad är Book from Sven's Farm?",a="Det är en titellös, jordfläckad dagbok som grävts fram ur ruinerna av Sven Yorgens förstörda gård i Duskwood. Sidorna är slitna och ofullständiga, men innehåller ett ögonvittnesskildring av fasorna som drabbade Svens gård och familj. Än viktigare är att den utgör ett fysiskt bevis på att en skuggig åskådare var där under massakern och innehåller viktiga svar om vem som angrep gården och varför.",al={"vad är book from sven's farm","jordfläckad bok i duskwood","vad är den jordfläckade boken"}}},fp="21,165,18.513.0,29.420.1,41.91.0,40.197.1,36.177.0,50.150.1,55.161.1"}
P.entries["item:book-stresses-of-iron"] = {n="Book: Stresses of Iron",s="I Stormwind Keep har Margulf Blaggons bok om metallurgi lånats ut till Northshire Abbey för avskrift.",h="I Stormwind Keep har Margulf Blaggons bok om metallurgi lånats ut till Northshire Abbey för avskrift.",kw={"brother kristoff","brother paxton","margulf blaggon","metallurgi","milton sheaf","northshire abbey","royal library","stresses of iron"},ang={["profession:Blacksmithing"]="Margulf Blaggons bok utforskar järnets styrka och de praktiska begränsningarna med att bearbeta det."},sec={{t="En lånad bok",b="Margulf Blaggon skrev om metallurgins praktiska och teoretiska sidor. Milton Sheaf ansvarade för volymen i Stormwind Keeps Royal Library. Biblioteket lånade ut den till Northshire Abbey, där Brother Paxton skrev av den för hand till sin egen samling. Paxtons arbete tog mycket längre tid än väntat, och Brother Kristoff väntade oroligt på att boken skulle återvända till staden på Cathedral Square."}},faq={{q="Vad handlar boken om?",a="Margulf Blaggons bok behandlar metallurgi och metallarbete, både i teori och praktik.",al={"vad handlar stresses of iron om","ämnet i stresses of iron","bokens innehåll"}},{q="Varför fanns boken i Northshire Abbey?",a="Brother Paxton lånade boken från Stormwinds Royal Library för att skriva av den för hand till sin egen samling innan han lämnade tillbaka originalet.",al={"varför hade paxton den","varför i northshire"}},{q="Vem ville få tillbaka boken?",a="Brother Kristoff ville få tillbaka boken. Medan han väntade på Cathedral Square bad han enträget om att få tillbaka den, och en äventyrare spårade den mellan Royal Library och Northshire.",al={"vem behöver boken","vem väntar på den"}}},fx={["7d684098"]={q="Varifrån kommer Stresses of Iron, och vem skrev den?",a="Boken skrevs av Margulf Blaggon som en vetenskaplig avhandling om metallurgi. Den hör hemma i Royal Library inne i Stormwind Keep, men Brother Paxton lånade volymen och tog den till Northshire Abbey för att noggrant skriva av ett exemplar till sina egna hyllor.",al={"vem skrev stresses of iron","stresses of iron författare","stresses of iron ursprung"}}},fp="22,104,17.397.0,23.89.0,37.138.0,29.180.0"}
P.entries["item:bottle-of-disease"] = {n="Bottle of Disease",s="En Bottle of Disease är en flaska med smittsamma brygder som bryggts av Forsaken i Ashenvale. De här flaskorna hittas i ett läger nära The Dor'Danil Barrow Den och vittnar om de odödas hotfulla försök att sprida pest i den orörda vildmarken där nattalverna lever.",h="En Bottle of Disease är en flaska med smittsamma brygder som bryggts av Forsaken i Ashenvale.",kw={"ashenvale","pest","bottle of disease","the dor'danil barrow den","forest song","forsaken","forsakens sjukdomar","kayneth stillwind"},ang={["class:Druid"]="Pestblandningar och konstgjorda farsoter strider mot den naturliga balansen och kräver ett snabbt ingripande från varje druid som svurit att skydda skogen.",["race:NightElf"]="Att fördärva Ashenvales jord med smitta från de odöda är en oförlåtlig skymf mot Kaldorei, särskilt när brygderna tillverkas alldeles intill The Dor'Danil Barrow Den."},sec={{t="Pest i de heliga skogarna",b="Djupt inne under den uråldriga trädkronan i östra Ashenvale har Forsaken smugit sig långt förbi Warsong Outriders frontlinjer. Odöda alkemister har upprättat en utpost nära The Dor'Danil Barrow Den, där de brygger avskyvärda smittor och förseglar dem i glasflaskor. För nattalverna som vaktar Forest Song är flaskorna tydliga bevis på ett lågmält och lömskt angrepp, inriktat på att förgifta skogsmarken och djurlivet i stället för att ta strid öppet."},{t="Kayneth Stillwinds undersökning",b="Kayneth Stillwind, en nattalvsvakt vid Forest Song, söker bevis för Forsakens onda avsikter. Genom att hämta en Bottle of Disease kan Stillwind analysera innehållet direkt. Nattalverna fruktar att brygderna inte bara är vapen mot beväpnade vakter, utan noggrant framställda reagenser avsedda att fördärva heliga gravhögar och bryta ned skogens försvarares kroppar och sinnen."}},faq={{q="Vad finns i Bottle of Disease?",a="Flaskan innehåller syntetiska gifter och magiska smittor som bryggts av Forsakens apotekare. De avskyvärda blandningarna är avsedda att fördärva levande vävnad och jord och speglar Royal Apothecary Societys bredare experiment med smittsamma pestbrygder.",al={"vad finns i flaskan","innehåll i bottle of disease","forsaken-dryck"}},{q="Var hittar man flaskorna?",a="De finns i ett avskilt Forsaken-läger söder om Forest Song, alldeles nära ingången till The Dor'Danil Barrow Den i östra Ashenvale.",al={"var hittar man bottle of disease","bottle of disease plats","forsaken-läger ashenvale"}},{q="Vem vill ha Bottle of Disease?",a="Kayneth Stillwind, en nattalvsväktare vid utposten Forest Song, ber Alliansens äventyrare hämta en flaska så att han kan testa innehållet och utröna Hordens verkliga avsikter.",al={"vem tar emot bottle of disease","lämna in bottle of disease","kayneth stillwind uppdrag"}},{q="Varför brygger Forsaken sjukdomar i Ashenvale?",a="Nattalverna misstänker att Forsaken tänker smitta den heliga skogen i tysthet och vanhelga gravhögarna i närheten, förgifta det naturliga ekosystemet och försvaga nattalvernas motstånd inifrån.",al={"varför forsaken i ashenvale","de odödas mål i ashenvale","forsakens gravhögar"}}},fx={["4091970d"]={q="Vad är Bottle of Disease?",a="Det är en förseglad flaska med starka gifter och farsoter som framställts av Forsaken. Agenter från Undercity brygger dessa vidriga blandningar i hemliga läger runtom i Ashenvale, tappar upp dem på flaska och sprider dem med avsikt i de urgamla alvskogarna.",al={"vad är bottle of disease","bottle of disease bakgrund","information om bottle of disease"}},["62494cf6"]={q="Varifrån kommer Bottle of Disease, och vem tillverkade den?",a="Flaskan bryggs av Forsaken-apotekare i ett avskilt läger söder om Forest Song, nära The Dor'Danil Barrow Den. Dessa odöda alkemister håller till nära heliga nattalvsgravar och samlar aktivt in och destillerar farliga gifter och farsoter på Kalimdor.",al={"vem tillverkade bottle of disease","bottle of disease ursprung","varifrån kommer bottle of disease"}},["9d281de4"]={q="Varför vill Kayneth Stillwind ha Bottle of Disease?",a="Kayneth Stillwind vid Forest Song behöver ett oskadat prov för att analysera Forsakens planer. Genom att testa blandningens alkemiska egenskaper hoppas nattalverna kunna bekräfta om de odöda tänker sprida farsoten i själva Ashenvale och förbereda ett effektivt motmedel.",al={"varför vill man ha bottle of disease","varför skaffa bottle of disease","varför vill kayneth ha sjukdomsflaskan"}}},fp="17,141,26.293.0,33.268.1,37.163.0,30.136.0,32.149.0,51.177.0"}
P.entries["item:bottle-of-moonshine"] = {n="Bottle of Moonshine",s="En Bottle of Moonshine är en stark spritdryck som säljs i den dystra bosättningen Darkshire. Barkeep Daniels i Lakeshire behöver snabbt en flaska för att fylla på stadens krogförråd, eftersom svartrockorkernas anfall har stoppat de vanliga leveranserna.",h="En Bottle of Moonshine är en stark spritdryck som säljs i den dystra bosättningen Darkshire.",kw={"barkeep daniels","bottle of moonshine","darkshire","spriten tar slut","duskwood","lakeshire","hembränt","scarlet raven tavern"},ang={["faction:Alliance"]="Att hämta sprit från Darkshire till Lakeshire visar hur sårbara försörjningslederna är mellan Stormwindkungarikets utspridda bosättningar i kristider."},sec={{t="En stark dryck som lindring",b="Lakeshire är belägrat av Blackrock-klanen, och den lokala värdshusvärden, Barkeep Daniels, är i stora svårigheter eftersom de vanliga försörjningskaravanerna inte kommer fram. För att hålla modet uppe hos stadsvakterna och de hårt prövade stadsborna skickar Daniels budbärare genom de södra kungarikena för att samla in regionala specialiteter. En av dem är en flaska starkt hembränt som bryggs och säljs på Scarlet Raven Tavern i grannområdet Duskwood, där lokalbefolkningen föredrar starka drycker för att hålla skogens växande fasa på avstånd."}},faq={{q="Var kan jag hitta en Bottle of Moonshine?",a="En Bottle of Moonshine kan köpas av värdshusvärden på Scarlet Raven Tavern i Darkshire, som ligger inom Duskwoods mörka gränser.",al={"var köpa hembränt","plats för hembränt i darkshire","försäljare av bottle of moonshine"}},{q="Vem vill ha flaskan?",a="Barkeep Daniels, värdshusvärden i Lakeshire i Redridge Mountains, ber om flaskan tillsammans med flera andra regionala drycker för att hålla sin källare välfylld under den pågående orkbelägringen.",al={"vem behöver hembränt","lämna in moonshine-uppdrag","barkeep daniels moonshine"}},{q="Varför börjar spriten ta slut i Lakeshire?",a="Fientliga Blackrock-orker har svärmat över Redridge Mountains, plundrat vägar och skurit av handelsleder. De vanliga leveranserna har uteblivit, så hyllorna på Lakeshires krog är nästan tomma.",al={"varför spriten tar slut","brist på förnödenheter i lakeshire","spritbrist i redridge"}}},fx={["1eb07341"]={q="Vad är Bottle of Moonshine?",a="Det är en stark spritdryck som säljs i Duskwood på Scarlet Raven Tavern i Darkshire. Olaglig eller sträv sprit kan verka malplacerad på ett sömnigt tillhåll vid sjön, men svåra tider kräver starka drycker.",al={"vad är moonshine","information om bottle of moonshine","vad är bottle of moonshine"}},["5d3a7e66"]={q="Var kommer den här Bottle of Moonshine ifrån?",a="Den här spriten kommer från den skuggiga staden Darkshire i Duskwood och säljs på Scarlet Raven Tavern. När de lokala leveranserna till kungariket är ansträngda får värdshusvärdarna leta där de kan för att hålla hyllorna fyllda.",al={"vem tillverkar moonshine","var tillverkas moonshine","moonshine ursprung"}},["08a7d809"]={q="Varför vill man ha Bottle of Moonshine i Lakeshire?",a="Barkeep Daniels behöver den för att hålla värdshuset i Lakeshire igång. Mellan Blackrock-orchernas invasion och störda handelsvägar har stadens spritförråd nästan tagit slut. Daniels skickar resenärer genom människornas länder för att samla in starka drycker, däribland den här spriten från Darkshire, så att hans pressade gäster blir nöjda.",al={"varför vill lakeshire ha moonshine","varför köpa moonshine","vem behöver moonshine"}}},fp="19,170,17.255.0,39.85.0,22.147.0,39.184.0"}
P.entries["item:bottle-of-zombie-juice"] = {n="Bottle of Zombie Juice",s="En Bottle of Zombie Juice är en stark, illasmakande sprit bryggd av den fräna Rot Blossom som växer i Duskwood. Den hämtas på värdshuset i Darkshire och sägs vara beställd av enstöringen Abercrombie för att hålla kylan i den dystra skogen borta.",h="En Bottle of Zombie Juice är en stark, illasmakande sprit bryggd av den fräna Rot Blossom som växer i...",kw={"abercrombie","bottle of zombie juice","darkshire","duskwood","leverans av juice","rot blossom","zombie juice"},ang={["faction:Alliance"]="Ärenden mellan Darkshire och den skuggiga vildmarken hjälper Duskwoods bekymrade invånare att hålla kontakten, även när uppdragen verkar tvivelaktiga.",["profession:Herbalism"]="Örtkunniga som känner till Duskwood vet att Rot Blossom inte lämpar sig som ingrediens i vanliga läkande tonika. Att destillera den till en dryck känns därför än mer oroande."},sec={{t="En frän brygd",b="Zombie Juice bryggs av Rot Blossom som plockats bland Duskwoods skuggiga jordar och är en ovanligt stark dryck. Bartendern som lämnar ut den varnar för att den är så potent att den kan väcka de döda. Vanligt folk håller sig borta från sådana vidriga destillat, men enstöringen Abercrombie hävdar att det är det enda som kan hålla honom varm under de fuktiga, kalla nätterna vid hans ensliga stuga."},{t="Tveksamt törstsläckande",b="Abercrombie insisterar på att spriten bara är en värmande nattfösare, men när han får flaskan råkar han nästan berömma budbärarens ”dårskap” i stället för dennes vänlighet. Det antyder att brygden kan ha ett mörkare och mer illasinnat syfte än att bara värma på värdshuset."}},faq={{q="Vad är Zombie Juice gjort av?",a="Zombie Juice är en destillerad sprit gjord av Rot Blossom, en illaluktande växt som växer i Duskwoods fördärvade jord.",al={"zombie juice ingredienser","vad innehåller zombie juice"}},{q="Vem vill få flaskan levererad?",a="Flaskan har beställts av Abercrombie, en excentrisk enstöring som bor i en enslig stuga vid Duskwoods västra gräns.",al={"vem behöver zombie juice","vem är zombie juice till","leverans av zombie juice"}},{q="Varför vill Abercrombie ha Zombie Juice?",a="Abercrombie hävdar att han behöver den starka drycken för att hålla sina gamla ben varma under Duskwoods bittra, mörka nätter, men hans märkliga uppträdande antyder att han kan ha andra användningar för en så potent brygd.",al={"varför dricker abercrombie det","abercrombie zombie juice anledning"}},{q="Kan spelare dricka Bottle of Zombie Juice?",a="Nej, just den här flaskan är ett uppdragsföremål som endast ska levereras till Abercrombie, och din främsta uppgift är att bära den oskadd till hans stuga.",al={"kan jag dricka zombie juice","går zombie juice att dricka"}}},fx={f1488eba={q="Vad är Bottle of Zombie Juice?",a="Bottle of Zombie Juice är en stark brygd av sprit från Rot Blossom som blandas i Duskwood. Den beskrivs som vidrig och otroligt stark, så stark att den sägs kunna väcka döda. Värdshusvärdar hanterar den motbjudande brygden med yttersta försiktighet.",al={"vad är zombie juice","bottle of zombie juice bakgrund","vad är juicen"}},b862f5ea={q="Varifrån kommer Bottle of Zombie Juice, och vem tillverkade den?",a="Juicen bryggs i Darkshire av den lokala värdshusvärden Tavernkeep Smitts, som destillerar den från Rot Blossom. Den tillreds särskilt på beställning för leverans till Abercrombies koja i Duskwoods hemsökta vildmark.",al={"vem tillverkade zombie juice","varifrån kommer zombie juice","vem brygger zombie juice"}}},fp="22,189,20.318.0,19.194.1,31.104.0,32.96.0,39.182.0,45.96.0"}
P.entries["item:bottom-of-gelkak-s-key"] = {n="Bottom of Gelkak's Key",s="Bottom of Gelkak's Key är en av tre delar av en sönderslagen mekanisk uppdragsnyckel som tillhörde den skeppsbrutna gnompiraten Gelkak Gyromast. När hans fartyg förliste utanför Darkshore plockades delen upp av strandens inhemska revkrypare.",h="Bottom of Gelkak's Key är en av tre delar av en sönderslagen mekanisk uppdragsnyckel som tillhörde den...",kw={"krypare","darkshore","styrman","gelkak","gyromast","nyckel","återhämtning","skeppsbrott"},ang={["profession:Engineering"]="Ingenjörer känner igen delen som en del av ett specialkonstruerat uppdragsverktyg som driver avancerade urverksautomater.",["race:Gnome"]="Gnomer uppskattar att Gyromast förlitade sig på urverksinnovation i stället för en besättning av kött och blod, trots att han var skeppsbruten och strandsatt på en fientlig kust."},sec={{t="Tagen av krypare",b="När Gelkak Gyromasts skepp sänktes av threshadons utanför Darkshores kust spolades gnomen i land tillsammans med sina ägodelar. Bland hans mest värdefulla ägodelar fanns uppdragsnyckeln som användes för att aktivera hans mekaniska styrman. Nyckeln splittrades mot kustklipporna i tre tydliga delar, och lokala asätare kastade sig genast över vrakspillrorna. Nyckelns nederdel snappades upp av de aggressiva kräftdjuren som strövar omkring i bränningarna, närmare bestämt rev- och tidvattenkryparna som letar igenom skräpet längs vattenlinjen."},{t="Återmontering",b="Gelkak kan inte aktivera sin mekaniska besättningsman utan att förena den nedre delen med mitt- och toppdelarna, som släpades bort av kustens murlocs och skogsstridare i inlandet. Först när han bänder loss det tunga stycket ur strandkrabbornas skal kan gnompiraten hoppas återställa sin konstruktion och hämnas på dem som förstörde hans expedition."}},faq={{q="Vad används Bottom of Gelkak's Key till?",a="Den är en av tre delar som behövs för att reparera uppdragsnyckeln som tillhör den strandsatte piraten Gelkak Gyromast. Nyckeln krävs för att återaktivera hans mekaniska styrman.",al={"vad gör gelkaks nyckel","syftet med bottom of gelkaks key","varför behöver jag gelkaks nyckelbotten"}},{q="Var kommer den här nyckeldelen ifrån?",a="Den finns vid kusten i Darkshore, uppplockad av lokala krabbor som Encrusted Tide Crawlers och Raging Reef Crawlers längs vattenbrynet.",al={"var hittar man bottom of gelkak key","vem släpper bottom of gelkaks key","plats för gelkak key bottom"}},{q="Varför är nyckeln uppdelad i tre delar?",a="När threshadons förliste Gelkaks skepp spolades han i land, och nyckeln slog i strandklipporna och splittrades i delar som spreds bland traktens vilda djur.",al={"varför gick gelkaks nyckel sönder","hur gick nyckeln sönder"}},{q="Vem är Gelkak Gyromast?",a="Gelkak Gyromast är en strandsatt gnompirat som slagit läger vid Darkshores stränder efter att en threshadonattack förstörde hans fartyg och skingrade hans utrustning.",al={"vem är gelkak","gelkak gyromasts historia"}}},fx={bb7c59d0={q="Vad är Bottom of Gelkak's Key?",a="Det är den nedersta delen av en mekanisk nyckel som tillhör den skeppsbrutne gnompiraten Gelkak Gyromast. När hans skepp förliste utanför Darkshores kust splittrades nyckeln mot de vassa klipporna vid nedslaget. Den här delen samlades upp ur vrakspillrorna av traktens strandkrypare.",al={"vad är bottom of gelkak's key","bottom of gelkak's key","vad är den här nyckeldelen"}}},fp="22,205,19.358.0,10.354.1,44.194.0,36.146.0,40.159.0,23.127.0"}
P.entries["item:branch-of-cenarius"] = {n="Branch of Cenarius",s="Branch of Cenarius är en helig relik från en dryad som stals av den avskyvärde satyren Geltharis i östra Ashenvale. Att återfå arvegodset var dryaden Anilias sista önskan; hon dog när hon försvarade det mot skogens fördärvare.",h="Branch of Cenarius är en helig relik från en dryad som stals av den avskyvärde satyren Geltharis i östra...",kw={"anilia","ashenvale","branch of cenarius","dryad","forest song","geltharis","illiyana","satyr"},ang={["class:Druid"]="Som Cenarius lärjungar känner druider en personlig plikt att återta varje artefakt som bär Skogsherrens namn från den demoniske satyrens vanhelgande.",["race:NightElf"]="För Ashenvales nattalver är det en helig plikt mot naturen att hjälpa dryaderna och återfinna deras förlorade förfädersklenoder."},sec={{t="En helig gren fallen i skugga",b="Cenarius döttrar vördar Branch of Cenarius, som står för både Skogsherrens välsignelse och den djupa samhörighet hans dryader har med Ashenvale. Dryadsystrarna Anilia och Illiyana höll grenen högt tills ett följe fördärvade satyrer överföll dem. Satyren Geltharis, som ledde följet, tog reliken och tillfogade Anilia dödliga sår nära de besudlade ruinerna i östra Ashenvale. Med sina sista andetag pekade Anilia norrut mot valvet där Geltharis håller till. Hon vädjade till en mästare att rycka den heliga grenen ur hans klor och återbörda den till dryaderna i Forest Song."}},faq={{q="Vad är Branch of Cenarius?",a="Branch of Cenarius är en dyrbar naturrelik som Ashenvales dryader håller kär. Den bär halvguden Cenarius namn och välsignelse och är en helig symbol för deras vård av den uråldriga skogen.",al={"lore om branch of cenarius","vad är den här grenen","dryadernas gren"}},{q="Vem stal Branch of Cenarius?",a="Den avskyvärde satyren Geltharis stal reliken. Han ledde ett bakhåll mot dryaderna nära östra Ashenvale. Geltharis fällde dryaden Anilia och flydde norrut genom en stenportal med grenen i sina klor.",al={"vem tog grenen","vem stal den","vem släpper branch of cenarius"}},{q="Vem tillhör grenen?",a="Grenen tillhör dryaderna i Forest Song. Anilia dog när hon försvarade den, så reliken återbördas till hennes sörjande syster Illiyana och Anilias sista önskan uppfylls.",al={"vem får grenen","vem vill ha grenen","vem ska jag ge den till"}},{q="Var återfinns grenen?",a="Grenen finns hos Geltharis, som håller till strax norr om ruinerna där Anilia faller i östra Ashenvale, nära gränsen till Azshara.",al={"grenens plats","var finns geltharis","var hittar man grenen"}}},fx={["4e4ec82f"]={q="Varför är det så viktigt att hämta Branch of Cenarius?",a="Ashenvales dryader betraktar grenen som en ovärderlig helig relik med band till deras fader Cenarius. När dryaden Anilia blev dödligt sårad av korrumperade satyrer nära Xavian var hennes sista önskan att den stulna grenen skulle tas tillbaka från Geltharis och tryggt återlämnas till dryaderna vid Forest Song.",al={"varför hämta branch of cenarius","varför vill dryaderna ha grenen","branch of cenarius syfte"}}},fp="18,160,31.442.0,31.174.0,33.179.0,30.156.1,30.123.0"}
P.entries["item:brass-collar"] = {n="Brass Collar",s="På Brackwell Pumpkin Patch bär Princess ett halsband av mässing som Ma Stonefield vill ha som bevis på att suggan är borta.",h="På Brackwell Pumpkin Patch bär Princess ett halsband av mässing som Ma Stonefield vill ha som bevis på att...",kw={"brackwell pumpkin patch","brass collar","elwynn forest","ma stonefield","princess","princess måste dö","the stonefield farm"},ang={["faction:Alliance"]="Som Alliance-äventyrare som hjälper Elwynns landsbygdsfolk bidrar du med Princess halsband till att lösa en fejd mellan grann gårdar."},sec={{t="Ett trofé från gårdsrivaliteten",b="Princess är en enorm, prisbelönt sugga som ägs av familjen Brackwell. Hon strövar omkring på deras pumpafält öster om Maclure-gården, och hennes aptit leder henne in bland grödorna på The Stonefield Farm. Efter att ha förlorat värdefulla grönsaker till suggan söker Ma Stonefield någon som är villig att döda henne. Princess bär ett mässingsband runt halsen, och halsbandet bevisar att hon inte kommer att plundra Stonefields fält igen."}},faq={{q="Var kommer Brass Collar ifrån?",a="Princess bär halsbandet vid Brackwell Pumpkin Patch i östra Elwynn Forest, bortom Maclure-gården.",al={"källa till brass collar","vem släpper brass collar","var får man tag på brass collar"}},{q="Varför vill Ma Stonefield ha halsbandet?",a="Princess äter Ma Stonefields prisgrönsaker. Halsbandet bevisar för Ma Stonefield att suggan har dödats innan hon hinner förstöra mer av skörden.",al={"varför stonefield vill ha halsbandet","ma stonefields syfte med halsbandet"}},{q="Vem äger Princess?",a="Princess tillhör familjen Brackwell och strövar omkring på deras pumpafält tillsammans med sina mindre galtkamrater.",al={"princess ägare","vem äger grisen"}},{q="Kan någon annan än Princess släppa det här föremålet?",a="Bara Princess kan lämna ifrån sig halsbandet. Det är utformat för att passa Brackwells enorma, prisbelönta sugga.",al={"andra som släpper halsbandet","var mer hittar man brass collar"}}},fx={["92e34b72"]={q="Vad är Brass Collar?",a="Brass Collar är det särskilda halsbandet som bärs av Princess, en prisbelönt sugga som ägs av familjen Brackwell. Eftersom Princess är enorm och brukar härja i grannarnas grödor är halsbandet ett obestridligt bevis på att det skadegörande djuret till slut har fällts.",al={"vad är brass collar","brass collar bakgrund","vem bär brass collar"}}},fp="12,112,28.400.0,38.105.0,39.151.0,18.104.0,46.97.0"}
P.entries["item:bristleback-attack-plans"] = {n="Bristleback Attack Plans",s="Bristleback Attack Plans består av grova kartor och taktiska anteckningar, utarbetade av quilboar från Brambleblade Ravine. De skisserar en samordnad belägring som ska överrumpla taurenboplatsen Camp Narache.",h="Bristleback Attack Plans består av grova kartor och taktiska anteckningar, utarbetade av quilboar från...",kw={"anfallsplaner","brambleblade ravine","bristleback","camp narache","chief hawkwind","mulgore","quilboar"},ang={["faction:Horde"]="Om Bristlebacks anfall hejdas får Horde behålla ett tryggt fotfäste på Mulgors heliga slätter, utan hot.",["race:Tauren"]="Genom att avslöja planen försvarar du själva träningsmarkerna där unga taurer genomgår sina första riter och skyddar dina äldste och noviser från en brutal quilboarbelägring."},sec={{t="En plan mot mesan",b="Djupt inne i en jordgrotta i Brambleblade Ravine avslöjar dessa klottrade taktiska skisser att Bristleback-quilboar inte längre bara gör räder längs Red Cloud Mesas gränser. I stället planerade deras ledare ett organiserat, långvarigt anfall för att tränga in i Camp Narache och utrota de unga taurerna som tränar där. Genom att överlämna kartan till Chief Hawkwind kan stammen skicka bud till Bloodhoof Village efter förstärkningar och hejda den förestående invasionen innan den börjar."}},faq={{q="Vad innehåller Bristleback Attack Plans?",a="Planerna består av en taktisk karta och grova instruktioner som beskriver en fullskalig belägring av Camp Narache. De visar att quilboar organiserar ett långvarigt anfall snarare än sporadiska räder.",al={"vad innehåller anfallsplanerna","vad finns på kartan","bristlebacks stridsplaner"}},{q="Var finns planerna?",a="De ligger övergivna på jordgolvet i en upphöjd grotta i Brambleblade Ravine, strax uppför en sidostig från Bristleback-hövdingens hydda.",al={"var finns planerna","var hittar jag kartan","bristleback attack plans plats"}},{q="Vad gör Chief Hawkwind när han får planerna?",a="Chief Hawkwind inser den överhängande faran för mesan och använder informationen för att kalla på hjälp och krigare från Bloodhoof Village, så att Camp Naraches försvar kan förstärkas.",al={"vad gör hawkwind","camp naraches svar","chief hawkwinds reaktion"}},{q="Varför anfaller Bristleback Camp Narache?",a="Bristleback-stammen hävdar territoriell överhöghet över de taggiga ravinerna och ser taurernas närvaro på mesan som ett intrång. Därför försöker de driva bort bosättningen helt.",al={"varför anfaller quilboar","bristlebacks motiv"}}},fx={["166f21b1"]={q="Varifrån kommer Bristleback Attack Plans?",a="Planerna kommer från Brambleblade Ravines djup och utarbetades av Bristleback-quilboarernas krigshövding. De ligger på en grov karta som gömts i deras grottsystem och beskriver stammens samordnade plan att belägra taurenbosättningen Camp Narache under en längre tid.",al={"vem gjorde bristleback attack plans","bristleback attack plans ursprung","vem skrev bristleback attack plans"}},aea2975f={q="Varför behöver Chief Hawkwind Bristleback Attack Plans?",a="Chief Hawkwind behöver planerna eftersom de avslöjar quilboarernas plan att belägra Camp Narache. Med bevis på det hotande angreppet kan hövdingen genast kalla på förstärkningar från närbelägna Bloodhoof Village, förbereda försvaret och stoppa anfallet innan bosättningen blir överrumplad.",al={"varför vill man ha bristleback attack plans","varför vill hawkwind ha attackplanerna","bristleback attack plans syfte"}}},fp="24,187,23.402.0,45.173.0,28.133.0,55.117.1,47.142.0"}
P.entries["item:bristleback-belt"] = {n="Bristleback Belt",s="Ett Bristleback Belt är enkel utrustning som quilboarfolket i Brambleblade Ravine har tillverkat och bär. För unga tauren som blir myndiga i Camp Narache är insamlingen av dessa bälten ett fysiskt bevis på mod under Styrkeprovet.",h="Ett Bristleback Belt är enkel utrustning som quilboarfolket i Brambleblade Ravine har tillverkat och bär.",kw={"bälte","brambleblade ravine","bristleback","camp narache","chief hawkwind","quilboar","red cloud mesa","styrkeprovet"},ang={["faction:Horde"]="Att hejda Mulgoreområdets aggressiva quilboarfolk säkrar de södra gränserna till Hordens kärnland i centrala Kalimdor.",["race:Tauren"]="Att ta bältet från en fallen Bristleback är en övergångsrit för varje ungdom på Red Cloud Mesa och markerar det första steget mot erkännande från de äldste i Thunder Bluff."},sec={{t="Bevis på provet",b="Red Cloud-stammen prövar alla ungdomar som vill vinna respekt i Thunder Bluff genom Earthmothers uråldriga riter. Den första prövningen, Styrkeprovet, kräver att den prövade skyddar stammen mot aktiva hot. Eftersom de fientliga Bristleback-quilboarfolket gång på gång plundrar stammens matförråd och överfaller jaktlag utanför Camp Narache, kräver Chief Hawkwind att inkräktarnas bälten lämnas in. När tolv bälten återlämnas till hövdingen bevisar det att den prövade kan möta faror direkt och slå tillbaka till stammens försvar."},{t="Quilboarfolkets hantverk",b="Dessa bälten har tagits från Bristleback-quilboarkrigare och schamaner i hela Brambleblade Ravine och tillverkats av grovt läder, snöre och skrot. För en taurenkrigare är de värdelösa som klädsel, men de är tydligt tillverkade av quilboarfolket och utgör ett obestridligt bevis på en besegrad fiende. Att föra tillbaka dem till lägerplatsen uppfyller ritens beviskrav."}},faq={{q="Vad används Bristleback Belts till?",a="Chief Hawkwind i Camp Narache kräver tolv Bristleback Belts som fysiskt bevis på att en prövad har klarat Styrkeprovet, det första av Earthmothers traditionella riter.",al={"varför behöver jag bristleback belt","bristleback belt användning","vad används bältet till"}},{q="Var kommer Bristleback Belts ifrån?",a="De tas från Bristleback-quilboar och Bristleback-schamaner som bor i Brambleblade Ravine, strax öster om Camp Narache på Red Cloud Mesa.",al={"var får man tag på bristleback belt","vem släpper bristleback belts","bristleback belt plats"}},{q="Varför vill Chief Hawkwind ha bälten i stället för huvuden eller vapen?",a="Bältena är ett lättburet bevis på att den prövade har besegrat stammens fiender. Riten efterfrågar särskilt bälten, utan att förklara varför de valts framför andra troféer.",al={"varför bälten","hawkwinds bevis"}},{q="Varför är Bristlebacks måltavlor?",a="Bristlebacks har trängt in på stammens mark från Brambleblade Ravine. De plundrar Camp Narache i skydd av mörkret och överfaller tauren-jaktlag över hela mesaslätten.",al={"varför döda bristlebacks","quilboarhotet i mulgore"}}},fx={["69faf7fa"]={q="Vad är ett Bristleback Belt?",a="Ett Bristleback Belt är ett enkelt klädesplagg som bärs av quilboarfolket i Brambleblade Ravine. De här grova läder- eller snörskärpen har tagits från fallna plundrare och fungerar som obestridliga krigstroféer. De visar stamäldste att ett inträngande hot har mötts och dödats.",al={"bristleback belt","vad är bristleback belt","föremålet bristleback belt"}},d50579da={q="Varifrån kommer ett Bristleback Belt, och vem tillverkar det?",a="De här bältena tillverkas av Bristleback-quilboar som har byggt en törnbeströdd bosättning i Brambleblade Ravine, strax öster om Camp Narache. Både deras främsta krigare och schamaner bär dem i strider mot tauren på Red Cloud Mesa.",al={"varifrån kommer bristleback belts","vem tillverkar bristleback belts","bristleback belts ursprung"}}},fp="16,169,17.422.0,14.289.0,36.181.0,37.121.0,63.169.0,40.152.0"}
P.entries["item:bristleback-quilboar-tusk"] = {n="Bristleback Quilboar Tusk",s="I norra och centrala The Barrens tas Bristleback Quilboar Tusks från dödade quilboar. Mankrik samlar dem som bevis på slakten och tecken på hämnd.",h="I norra och centrala The Barrens tas Bristleback Quilboar Tusks från dödade quilboar.",kw={"the barrens","bristleback","uppslukad av hat","the crossroads","mankrik","quilboar","bete"},ang={["faction:Horde"]="Quilboar hotar The Crossroads och försörjningslederna genom The Barrens. Att samla betar tjänar Mankriks vendetta och Hordens försök att pacificera området.",["race:Orc"]="Som orc känner du till blodsskuldernas tyngd och en krigares sorg. Mankriks jakt på sextio quilboar-troféer väcker en gemensam känsla för heder."},sec={{t="Hämndens troféer",b="Bristleback quilboar försvarar sitt territorium i The Barrens mot Hordens expansion. Deras taggiga elfenbenständer används som vapen i närstrid. Mankrik, en erfaren orc-krigare stationerad vid The Crossroads, förlorade sin fru i ett brutalt bakhåll från quilboar. Han samlar dussintals betar som vedergällning, en blodig räkning av det lidande han tänker återgälda Bristlebacks."}},faq={{q="Vem vill ha betarna?",a="Mankrik, en orc-krigare vid The Crossroads i The Barrens, vill ha betarna. Han söker hämnd på Bristleback quilboar efter att ett bakhåll skilde honom från hans fru.",al={"vem behöver bristleback-betar","vem tar emot bristleback quilboar tusk","lämna in betar"}},{q="Varför vill Mankrik ha så många betar?",a="Efter att quilboar-rövare övermannat Mankrik och lämnat honom att dö uppslukades han av sorg och raseri. Sextio betar ger honom bevis på att Bristleback-stammen decimeras som vedergällning.",al={"varför 60 betar","varför vill mankrik ha betar","mankriks hämnd"}},{q="Vilka quilboar har de här betarna?",a="Medlemmar av Bristleback-stammen bär dessa betar i The Barrens norra och centrala buskmarker och snåriga läger.",al={"var faller bristleback-betar","vem släpper bristleback quilboar tusk"}},{q="Har betarna någon annan användning än Mankriks vendetta?",a="Mankrik samlar dessa troféer enbart för hämndens skull. Quilboarbetar kan ibland bli stammens prydnadssaker eller handelsvaror, men dessa används inte på det sättet.",al={"användning av bristleback-betar","kan man tillverka saker av quilboar-betar"}}},fx={a893c973={q="Vad är en Bristleback Quilboar Tusk?",a="Det här är avhuggna betar från dödade Bristleback-quilboar som strövar omkring i The Barrens. För quilboarfolket är de naturliga kännetecken och tecken på vildsinthet, men för jägare på slätterna är de ett makabert, fysiskt bevis på ännu ett dödat odjur.",al={"bristleback quilboar tusk","vad är bristleback quilboar tusk","bristleback-bete"}},fe8719fb={q="Varifrån kommer en Bristleback Quilboar Tusk?",a="De tas direkt från käkarna på Bristleback-quilboar i hela The Barrens. Quilboar växer naturligt ut de här vassa betarna, och för att ta dem måste man skära loss dem från fallna fiender efter striden.",al={"varifrån kommer bristleback-betar","vem släpper bristleback quilboar tusk","källa till bristleback quilboar tusk"}}},fp="25,166,21.365.0,22.171.0,36.181.0,33.123.0,63.157.0"}
P.entries["item:brock-s-list"] = {n="Brock's List",s="Brock's List är ett meddelande sammanställt av gruvinstruktören Brock Stoneseeker i Thelsamar. Det innehåller namnen på de främsta gruveleverna som har förtjänat hedershackor från skråhallarna i Ironforge.",h="Brock's List är ett meddelande sammanställt av gruvinstruktören Brock Stoneseeker i Thelsamar.",kw={"brock's list","golnir bouldertoe","great forge","ironforge","loch modan","gruvdrift","thelsamar","thorgrum borrelson"},ang={["profession:Mining"]="För guldletare står Brock's List för det formella erkännandet av lärlingar som lämnar grovt grus bakom sig och träder in i Deep Mountain Mining Guilds stolta traditioner.",["race:Dwarf"]="Pergamentet speglar dvärgarnas hantverkstradition och hedrar unga som visar hängivenhet åt hacka och spade under Khaz Modan."},sec={{t="En utmärkelse för gruvarbetare",b="Gruvdrift är livsnerven i dvärgarnas civilisation, och lärlingar måste bevisa sin skicklighet innan de får anförtros krävande arbete i Khaz Modans ådror. I Thelsamar sammanställer den lokala gruvtränaren detta pergament för att belöna elever som utmärker sig i sina lektioner. Dokumentet förtecknar dem som har förtjänat hedershackor, eftertraktade tecken på skicklighet smidda i huvudstaden."},{t="Vägen till Great Forge",b="Eftersom hedersverktygen måste graveras och delas ut från huvudstaden anförtros pergamentet åt resenärer på väg till Ironforge. Brock's List förs med en gryf från Thelsamars rastplats direkt till Golnir Bouldertoe vid Deep Mountain Mining Guild i Great Forge, där de hedrade elevernas namn graveras in i sten och stål."}},faq={{q="Vad är Brock's List?",a="Det är en förteckning skriven av gruvtränaren Brock Stoneseeker i Thelsamar. Den anger vilka lärlingar som fick höga betyg i sin gruvutbildning och kvalificerade sig för ceremoniella hackor.",al={"brock's list","vad är det här för föremål","brock's lists syfte"}},{q="Vem ska jag lämna Brock's List till?",a="Visa först listan för Thorgrum Borrelson, gryfmästaren i Thelsamar, så att du får resa med. Bär den sedan direkt till Golnir Bouldertoe vid Deep Mountain Mining Guild i Ironforges Great Forge.",al={"vart ska jag ta listan","vem får brock's list","lämna in brock's list"}},{q="Varför behöver Golnir Bouldertoe dokumentet?",a="Golnir ansvarar för Deep Mountain Mining Guilds verktyg i Ironforge. Han har en låda med hedershackor redo och behöver Brock's skriftliga förteckning så att han kan hugga in varje elevs namn på deras belöning.",al={"varför golnir","varför behöver ironforge listan"}},{q="Varför skickas listan med gryf i stället för till fots?",a="Bergspassen genom Loch Modan leder tillbaka till Dun Morogh, men det snabbaste och säkraste sättet att leverera skråets ärenden direkt till Great Forge är att ta en gryf via rastplatsmästaren Thorgrum Borrelson.",al={"varför flyga till ironforge","varför ta en gryf"}}},fx={bca439a3={q="Varifrån kommer Brock's List, och vem skrev den?",a="Listan är skriven av Brock Stoneseeker, en erfaren gruvarbetare som bor i Thelsamar i Loch Modan. När unga dvärgar kommer till honom för att lära sig hantverket bedömer Brock deras framsteg och upprättar den här förteckningen över de framstående elever som har förtjänat särskilt erkännande för sitt hårda arbete.",al={"vem skrev brock's list","varifrån kommer brock's list","skaparen av brock's list"}}},fp="12,203,21.271.0,27.238.0,21.164.0,33.190.0,46.174.0,49.163.0"}
P.entries["item:broken-and-battered-samophlange"] = {n="Broken and Battered Samophlange",s="I norra The Barrens ligger Venture Company-maskineriet skadat efter en misslyckad inspektion. Den skadade samophlangen måste nå goblinexperter i Orgrimmar, där någon kanske förstår hur den fungerar.",h="I norra The Barrens ligger Venture Company-maskineriet skadat efter en misslyckad inspektion.",kw={"the barrens","maskinverkstad","nogg","orgrimmar","rilli greasygob","samophlange","venture company","wenikee boltbucket"},ang={["faction:Horde"]="Som medlem i Horde tar du med dig bärgat Venture Company-maskineri från The Barrens till Orgrimmars goblinverkstäder, där det kan avslöja värdefulla tekniska hemligheter.",["profession:Engineering"]="Som ingenjör ser du faran i att lägga till vred och spakar på en instabil Venture Company-mekanism utan ett schema."},sec={{t="Mekad bortom igenkänning",b="Venture Company tillverkade samophlanger för sitt arbete med naturresurser i norra The Barrens. Wenikee Boltbucket försökte inspektera och modifiera en av dem genom att lägga till mätare, spakar och vred för att mäta dess stabilitet. Hennes pillande försvagade i stället mekanismen och lämnade den skadad och nära att gå sönder. Eftersom fler tillägg kunde få den att sluta fungera helt skickade hon den ömtåliga apparaten till någon med erfarenhet från fabriken."},{t="Vägen till Orgrimmar",b="För att reparera apparaten krävs någon som har arbetat på Venture Companys produktionslinjer. Rilli Greasygob, en tidigare Venture-anställd, arbetar på Noggs Machine Shop i Orgrimmars Valley of Honor. Den skadade apparaten fångar ingenjörens blick. Den som samlar skrot från goblinernas verksamhet kan verka djärv, eller helt enkelt dumdristig."}},faq={{q="Vad är en samophlange?",a="En samophlange är en maskin som Venture Company tillverkat för sitt industriarbete i The Barrens. Få utomstående förstår hemligheterna bakom goblinernas ingenjörskonst.",al={"vad är det här för föremål","vad gör en samophlange","samophlangens syfte"}},{q="Varför är samophlangen trasig och tilltufsad?",a="Wenikee Boltbucket försökte modifiera samophlangen med extra mätare för att mäta dess stabilitet. Tilläggen försvagade den och skadade dess känsliga inre delar.",al={"vem hade sönder samophlangen","varför är den skadad","wenikee hade sönder den"}},{q="Vem kan laga den här skadade apparaten?",a="Rilli Greasygob kan undersöka den skadade apparaten. Den tidigare Venture Company-anställda arbetar på Noggs Machine Shop i Orgrimmars Valley of Honor.",al={"vem ska jag lämna den till","vart ska samophlangen","vem lagar den"}},{q="Var kom den här maskinutrustningen ursprungligen ifrån?",a="Maskineriet kommer från Venture Companys borrnings- och utvinningsverksamhet i norra The Barrens. Gobliningenjörer använder det för att driva tunga utvinningsmaskiner.",al={"samophlangens ursprung","var hittades den","venture companys ursprung"}}},fx={["35e2c2bf"]={q="Varför vill Rilli Greasygob ha Broken and Battered Samophlange?",a="Wenikee Boltbucket försökte pilla med den känsliga apparaten genom att lägga till extra mätare, men det sänkte dess strukturella hållfasthet till en bottennivå. Wenikee medger att mer pillande kan förstöra den helt och ber dig därför lämna den skadade manicken till Rilli Greasygob på Noggs maskinverkstad i Orgrimmar. Som tidigare anställd på Venture Company har Rilli den tekniska expertis som krävs för att reparera deras specialmaskiner.",al={"varför ta samophlange till rilli","vem vill ha broken samophlange","varför vill rilli ha samophlange"}}},fp="31,198,27.398.0,21.328.0,22.158.0,43.159.0,35.144.0,46.162.0"}
P.entries["item:broken-samophlange"] = {n="Broken Samophlange",s="I norra The Barrens väcker en trasig samophlange nyfikna ingenjörers intresse. Dess kugghjul och rörliga delar antyder ett syfte som ingen har upptäckt.",h="I norra The Barrens väcker en trasig samophlange nyfikna ingenjörers intresse.",kw={"the barrens","broken samophlange","kugghjul","the mor'shan rampart","samophlange","undermine","wenikee boltbucket"},ang={["faction:Horde"]="Apparaten dyker upp i hordterritorium i The Barrens och får lokala utposter, mekaniker och neutrala handelskontakter att samarbeta.",["profession:Engineering"]="För en ingenjör är samophlangen ett oemotståndligt mysterium: en maskin med ömtåliga kugghjul inuti, vars syfte kanske blir tydligt först när man plockar isär den och får den att fungera."},sec={{t="En förbryllande mekanism",b="Den trasiga samophlangen är en förbryllande apparat från norra The Barrens. Dess rörliga delar och fina kugghjul vittnar om omsorgsfullt hantverk, trots att den är trasig. Sputtervalve, en goblin i Ratchet, skadade den ömtåliga apparaten av misstag innan någon hann dokumentera hur den fungerade. Upphittaren hoppades skicka fungerande resultat till nyfikna kollegor i Undermine och sökte därför någon som kunde reparera den. Wenikee Boltbucket, en skicklig mekaniker nära gränsutposten The Mor'shan Rampart, var den de vände sig till."},{t="På jakt efter en mekanikers händer",b="Wenikee Boltbucket kan inte avgöra vad en samophlange är avsedd att göra, inte ens efter att ha undersökt dess förstörda delar. Men dess urverksljud och rörliga mekanik väcker hennes intresse. I stället för att kassera den som skrot ger hon sig i kast med att reparera apparaten och se dess mekanismer fungera med full kapacitet."}},faq={{q="Vad är en samophlange?",a="Inte ens mekanikerna som försöker reparera en samophlange kan säga vad den gör. Namnet ger inget svar, men de invecklade kugghjulen och rörliga delarna tyder på något okänt industriellt syfte.",al={"samophlangens syfte","vad gör en samophlange","samophlange betydelse"}},{q="Varför är samophlangen trasig?",a="Sputtervalve, goblinen i Ratchet, skadade det ömtåliga maskineriet när han manipulerade apparaten som lämnats till honom. Samophlangen stannade innan dess hemligheter kunde delas med kollegorna i Undermine, så de sökte en expert som kunde få den att fungera igen.",al={"hur gick den sönder","historien om broken samophlange"}},{q="Vem är Wenikee Boltbucket?",a="Wenikee Boltbucket är en nyfiken mekaniker i norra The Barrens, strax söder om The Mor'shan Rampart vid gränsen till Ashenvale. Hennes intresse för ingenjörskonst får henne att undersöka och bygga om märkliga apparater.",al={"var finns wenikee","var finns boltbucket"}},{q="Varför är gobliner i Undermine intresserade av den?",a="Gobliningenjörer och entreprenörer är ivriga att studera ovanlig mekanisk teknik. Nyheten om apparaten nådde kontakter i Undermine, som lockades av de fördelar den kanske kunde erbjuda.",al={"undermines intresse","varför bryr sig gobliner"}}},fp="18,153,20.501.0,24.288.0,22.184.0,30.253.0,26.207.0,46.192.0"}
P.entries["item:broken-tools"] = {n="Broken Tools",s="Broken Tools är de krossade resterna av dvärgarnas prospektörshackor, som med avsikt förstörts på ett städ. De är ett fysiskt bevis för Baine Bloodhoof på att den inträngande dvärgarnas utgrävning, som hotar Mulgore och dess djurliv, har avbrutits.",h="Broken Tools är de krossade resterna av dvärgarnas prospektörshackor, som med avsikt förstörts på ett städ.",kw={"baine bloodhoof","broken tools","utgrävningsplats","dvärgarnas grävande","smedja","mulgore","prospector's pick"},ang={["profession:Blacksmithing"]="När ett städ används för att metodiskt förstöra fint dvärgiskt järnsmide blir hantverkarens smedja ett verktyg för att försvara territoriet.",["race:Tauren"]="För taurerna står de förstörda verktygen de för till Baine för försvaret av Jordmodern mot inträngande grävande som plågar traktens djur."},sec={{t="Sabotage vid utgrävningen",b="Nordväst om Bloodhoof Village har dvärgarnas grävare upprättat en utgrävning i Mulgores kullar. Dvärgarna söker efter forntida historia under marken, men taurerna ser deras aggressiva grävande som en direkt skändning av Jordmodern. Oväsendet och förödelsen gör det lokala djurlivet oroligt, särskilt de kringströvande kodo-hjordarna. I stället för att bara driva bort grävarna instruerar unge Baine Bloodhoof försvararna att beslagta prospektörernas järnhackor och slå sönder dem vid en smedja, så att expeditionen inte kan hugga sig längre ner i jorden."}},faq={{q="Vad är dessa Broken Tools?",a="De är de förstörda huvudena och splittrade skaften från Prospector's Picks, tagna från dvärgarnas grävare i Mulgore och avsiktligt krossade vid en smedja.",al={"broken tools","vad är broken tools","krossade hackor"}},{q="Varför vill Baine Bloodhoof att de förstörs?",a="Baine anser att jordens upprivande skändar landet och gör Mulgore vilda djur ursinniga, särskilt kodoerna. När verktygen slås sönder upphör grävandet, och det blir tydligt att landet inte tänker överlämna sin visdom åt vårdslös utgrävning.",al={"varför förstöra hackor","varför vill baine ha trasiga verktyg","baine och dvärgarnas grävande"}},{q="Var kan hackorna slås sönder?",a="Det går bra med vilken fungerande smedja som helst. Du kan använda smedjan vid själva dvärgarnas utgrävningsplats eller besöka en i Bloodhoof Village eller uppe i Thunder Bluff.",al={"hur slår man sönder hackor","var finns en smedja","slå sönder prospector's pick"}},{q="Varför gräver dvärgar i Mulgore?",a="Dvärgarna tror att djupa hemligheter och forntida reliker ligger begravda under Mulgore. I sitt besatta sökande efter sitt ursprung gröper de ofta ur främmande länder utan hänsyn till invånarna som bor där.",al={"varför dvärgar i mulgore","dvärgarnas utgrävningsplats i mulgore"}}},fx={["76aab525"]={q="Varifrån kommer de här trasiga verktygen?",a="De här sönderslagna redskapen var ursprungligen stadiga gruvhackor, smidda och burna av dvärgiska prospektörer. Expeditionen sökte efter titanreliker och uråldriga hemligheter under Mulgore och tog med sig sina järnverktyg för att gräva i marken mot nordväst. Genom att frakta de hela hackorna till en smedja och slå sönder dem gör du gruvutrustningen till obrukbart skrot innan du återlämnar den till tauren som bevis på att utgrävningen har stoppats.",al={"trasiga verktygens ursprung","vem tillverkade broken tools","varifrån kommer broken tools"}}},fp="12,187,18.446.0,28.147.0,45.217.0,32.144.0,35.183.0"}
P.entries["item:bundle-of-crocolisk-skins"] = {n="Bundle of Crocolisk Skins",s="Bundle of Crocolisk Skins är ett färdigberett paket med garvade reptilhudar från Wetlands farliga träskmarker. Det är avsett för läderarbetarna i Menethil Harbor och utgör värdefull handelsvara för tillverkning av stadiga stövlar och slitstark hamnutrustning.",h="Bundle of Crocolisk Skins är ett färdigberett paket med garvade reptilhudar från Wetlands farliga träskmarker.",kw={"crocolisk","einar","james halloran","läder","menethil harbor","sida","skinn","wetlands"},ang={["faction:Alliance"]="Jägare från utkanterna levererar material som håller Menethil Harbors garnison och invånare väl utrustade mot det hårda, sumpiga klimatet."},sec={{t="Handel i Wetlands och familjegräl",b="Wetlands vidsträckta vattenvägar myllrar av crocolisks, vars tåliga, vattenavvisande hudar är en viktig handelsvara för kustbosättningen Menethil Harbor. Jägare som vågar sig ut i träskmarkerna samlar in och garvar skinnen innan de skickas västerut till lokala hantverkare som James Halloran. Men just det här knippet tog en ovanlig omväg och hamnade i en äventyrares händer: jägaren Einar sökte en kurir enbart för att slippa återvända till staden och möta sin frustrerade hustru Sidas ilska."}},faq={{q="Vad används Bundle of Crocolisk Skins till?",a="Knippet består av råa, garvade träskhudar som ska till James Halloran, en garvare verksam i Menethil Harbor. Halloran gör slitstarka stövlar, bälten och läderrustningar av de robusta skinnen, väl lämpade för att klara Wetlands fuktiga, översvämmade terräng.",al={"användning av crocolisk-skinn","vad används skinnen till","syftet med hudknippet"}},{q="Vem samlade in dessa crocolisk-skinn?",a="Skinnen samlades in och bands ihop av jägaren Einar ute i träskmarkerna. Vanligtvis tar han själv med sig sina handelsvaror till staden, men den här gången ber han förbipasserande resenärer att bära dem för att undvika ett gräl med sin hustru, Sida.",al={"vem gjorde knippet","vem samlade in skinnen","einar crocolisk"}},{q="Vem är James Halloran?",a="James Halloran är en verksam läderarbetare och garvare i hamnstaden Menethil Harbor. Han köper råa och garvade hudar från lokala träskjägare och tillverkar stövlar, garvat läder och praktisk utrustning åt sjömän, soldater och stadsbor.",al={"james hallorans roll","vem är halloran","garvare i menethil"}}},fx={["639d94c2"]={q="Vad är Bundle of Crocolisk Skins?",a="Det är ett inslaget paket med råa hudar från de farliga crocoliskar som lurar i Wetlands. Einar Stonegrip samlade ihop och band samman dem för att sälja till hantverkarna i Menethil Harbor, men personliga bekymmer hindrar honom från att leverera varorna själv.",al={"vad är bundle of crocolisk skins","bundle of crocolisk skins"}},["8cc4b9e1"]={q="Varför vill James Halloran ha Bundle of Crocolisk Skins?",a="James Halloran arbetar som garvare i Menethil Harbor och behöver regelbundna leveranser av färska hudar för att tillverka fina läderstövlar och garvade rustningar åt invånare och resenärer. Råa crocoliskhudar ger honom det slitstarka material han behöver för sitt hantverk och för att fylla sina hyllor.",al={"varför behöver james halloran hudar","varför vill någon ha bundle of crocolisk skins","james halloran och crocoliskhudar"}}},fp="25,130,37.363.0,47.202.0,35.209.0,22.233.0"}
P.entries["item:bundle-of-hides"] = {n="Bundle of Hides",s="Över The Barrens färdas en Bundle of Hides mot Thunder Bluff med hordens vindryttare. De garvade skinnen är en enkel kurirleverans till läderarbetarna, och leveransen visar resenärer hur vindryttarnätverket fungerar.",h="Över The Barrens färdas en Bundle of Hides mot Thunder Bluff med hordens vindryttare.",kw={"ahanu","the barrens","bundle of hides","the crossroads","devrak","hewa's armory","jahan","läderarbete","thunder bluff","vindryttare"},ang={["faction:Horde"]="Enkla leveranser som hudar färdas genom skyn längs wyverners flygrutter och knyter avlägsna utposter i Horden direkt till självständiga huvudstäder.",["race:Tauren"]="Som tauren förlitar du dig på naturmaterial och vördnadsfull jakt, och förvandlar hudar från den närliggande savannen till rustningar och hantverk som säljs i stånden i Mulgore."},sec={{t="Handel vid gränsen",b="Jägare flår bestarna i The Barrens för att få garvade hudar. Slätterna hyser väldiga hjordar av kodo, strövande lejon och kringvandrande raptorer. Skinnen förser läderarbetarna i Thunder Bluff, som gör utrustning, påsar, rustningar och remmar åt Horden."},{t="Frakt i skyn",b="Kurirer för paketet från The Crossroads till Thunder Bluff på Devraks tränade wyverner. Landvägen genom The Barrens och in i Mulgore är långsam och farlig, med kringströvande quilboar och centauranfallare. När hudarna lämnas över till en vindryttarkurir ser man hur snabbt flygresor kan korsa Kalimdors splittrade landskap."}},faq={{q="Vad används Bundle of Hides till?",a="Bundle of Hides för med sig skinn från djur i The Barrens till Ahanu, en läderarbetare i Thunder Bluff. Han tillverkar lädervaror och vapen åt tauren och deras allierade i Horden.",al={"syftet med bundle of hides","varför transportera hudar","vad används hudar till"}},{q="Vem tar emot leveransen i Thunder Bluff?",a="Ahanu tar emot paketet vid Hewa’s Armory, precis vid foten av Thunder Bluffs vindryttarplats.",al={"vem får hudarna","mottagare av bundle of hides","var finns ahanu"}},{q="Varför skickas knytet med en vindryttare?",a="Resan till fots från The Crossroads till Thunder Bluff tar flera dagar och innebär risk för bakhåll från centaurer eller quilboar. Devrak, flygmästaren i The Crossroads, transporterar varorna på en vindryttare så att de kommer fram snabbt och säkert.",al={"varför flyga med hudar","hudar med flyg från the crossroads","devrak vindryttare"}},{q="Vem gjorde i ordning knytet i The Barrens?",a="Jahan Hawkwing förberedde paketet av djur från The Barrens. Han säljer läder och ringbrynjor i The Crossroads och är kollega till Ahanu.",al={"vem gav bort hudarna","jahan hudar","vem samlade skinnen"}}},fx={["2b9c2280"]={q="Vad är Bundle of Hides?",a="Bundle of Hides är en förpackad leverans av råa skinn från vilda djur som strövar omkring i The Barrens. De har samlats in och förberetts lokalt nära The Crossroads och är ett viktigt hantverksmaterial som ska exporteras till Thunder Bluff. Där förvandlar skickliga läderarbetare de tåliga gränsmarksskinnen till rustningar, kläder och viktiga handelsvaror.",al={"vad är bundle of hides","föremålet bundle of hides","historien om bundle of hides"}}},fp="15,244,14.252.0,15.325.0,37.194.0,43.105.0,38.208.0,39.147.0"}
P.entries["item:bundle-of-wood"] = {n="Bundle of Wood",s="Nära Eastvale Logging Camp väntar Bundle of Wood bland träden på en brådskande leverans västerut.",h="Nära Eastvale Logging Camp väntar Bundle of Wood bland träden på en brådskande leverans västerut.",kw={"bundle of wood","eastvale","elwynn","skogshuggarläger","timmer","raelen","trä"},ang={["faction:Alliance"]="Som resande för Alliansen hjälper du till att återuppbygga Stormwind och ser till att livsviktiga timmerleveranser når bosättningarna i Elwynn och Westfall i tid."},sec={{t="Övergivet timmer",b="Nykapat timmer från Eastvale Logging Camp hjälper till att försörja kungariket Stormwind. Lägrets trä skickas västerut för att användas till stadsbyggnader och annan konstruktion. Björnar och vargar har trängt in i dungarna nordväst om lägret, och skräckslagna skogshuggare flydde och lämnade sina nyinsamlade Bundles of Wood bland träden. Leveransdeadlinen närmar sig, så förmannen Raelen behöver resande som tar sig förbi rovdjuren och hämtar timret innan virkesavtalen bryts."}},faq={{q="Varför lämnades träbuntarna i skogen?",a="Vargar och björnar överföll skogshuggarna som högg timmer nordväst om Eastvale Logging Camp och drev bort dem. Deras nyhuggna Bundles of Wood lämnades utspridda på skogsmarken.",al={"varför ligger trä på marken","varför överge trä","övergivet timmer i elwynn"}},{q="Vem behöver få träet insamlat?",a="Raelen, en förman vid Eastvale Logging Camp, behöver snarast få träet insamlat för att hinna med en nära förestående leveransdeadline.",al={"vem vill ha träet","raelen timmer","lämna in trä"}},{q="Var finns buntarna?",a="Buntarna ligger på marken precis nordväst om Eastvale Logging Camp, bland träden där Elwynns björnar och vargar strövar omkring.",al={"bundle of wood plats","var finns träet","träplatser vid eastvale"}},{q="Varför rensade inte stadsvakterna bort bestarna?",a="Raelen bad Deputy Rainer om hjälp med bestarna, men marshalerna och vakterna i Elwynn är hårt belastade i hela regionen. Skogsarbetarna behöver hjälp utifrån för att snabbt hämta stockarna.",al={"varför inga vakter","deputy rainer trä","vakter vid eastvale"}}},fx={e892b12c={q="Vad är Bundle of Wood?",a="Det här är travar av nyavverkat virke som arbetarna vid Eastvale Logging Camp har huggit och samlat ihop. Virket har förberetts för transport och bearbetning och vittnar om lägrets pågående timmerverksamhet i östra Elwynn Forest.",al={"vad är bundle of wood","bundle of wood i elwynn","vad är det för vedbuntar"}}},fp="14,90,16.462.0,54.189.0,30.125.0,30.129.0,48.189.0"}
P.entries["item:burning-blade-medallion"] = {n="Burning Blade Medallion",s="Kultister i Valley of Trials bär Burning Blade Medallion. Yarrog Baneshadow har den djupt inne i Burning Blade Coven, där dess mörka magi hotar Durotars unga krigare.",h="Kultister i Valley of Trials bär Burning Blade Medallion.",kw={"burning blade coven","burning blade medallion","durotar","felstalker","talisman","valley of trials","yarrog baneshadow","zureetha fargaze"},ang={["class:Warlock"]="Som Hordens häxmästare utövar du mörk magi under strikt disciplin. Medalljonen kännetecknar Burning Blades laglösa och obundna felmagi, som hotar Durotars stabilitet.",["race:Orc"]="För en orch påminner medalljonen om den demoniska fördärvning som en gång förslavade ditt folk. Den skuggan hotar nu unga noviser innan de lämnar Valley of Trials."},sec={{t="Ett tecken på korrumption",b="Zureetha Fargazes spådomar pekar ut medalljonen i Burning Blade Coven. Yarrog Baneshadow, en agent för Burning Blade-kulten, bär den djupt inne i de slingrande grottorna. Smycket kanaliserar mörk kraft bland kultens små impfamiljer och felstalkers. När du besegrar Yarrog och tar medalljonen sätter du stopp för kultens försök att underminera Hordens träningsplatser inifrån Durotar."}},faq={{q="Vad är Burning Blade Medallion?",a="Yarrog Baneshadow, en operatör för Burning Blade-kulten som gömmer sig i Durotar, bär den magiska talismanen. Den fokuserar mörk magi och visar att bäraren svurit sin trohet till kulten.",al={"burning blade-talisman","medaljong från coven","yarrogs medaljong"}},{q="Vem vill få medaljongen hämtad?",a="Zureetha Fargaze, en orakelförsedd orch utanför The Den i Valley of Trials, vill att du hämtar medalljonen. Hon hoppas kunna rensa bort demoniskt inflytande och studera kultens planer i området.",al={"vem hämtar medaljongen","var lämnar jag in medaljongen","zureetha fargaze-uppdrag"}},{q="Var finns medaljongen?",a="Yarrog Baneshadow har medalljonen djupt inne i Burning Blade Coven, en gömd grotta nordväst om The Den i Valley of Trials. Han lurar längs grottans övre avsatser.",al={"var finns yarrog baneshadow","burning blade medallion-plats","hur hittar jag medaljongen"}},{q="Vad innebär medaljongens närvaro för Durotar?",a="Medalljonens närvaro bekräftar att Burning Blade-kulten har placerat operatörer på Hordens prövningsplatser. Den visar att kultisterna har större och farligare ambitioner i orchernas hemland.",al={"varför finns kultister i valley of trials","finns burning blade i durotar"}}},fp="23,184,20.392.0,36.177.0,34.175.0,29.174.0,52.212.0"}
P.entries["item:burning-blood-quest-item"] = {n="Burning Blood (quest item)",s="I Duskwood samlas Burning Blood in från Nightbane worgen. Grimand Elmore behöver tjugo flaskor för smidesexperiment.",h="I Duskwood samlas Burning Blood in från Nightbane worgen.",kw={"burning blood","duskwood","furen longbeard","grimand elmore","gutspill","nightbane","roland's doom","worgen"},ang={["class:Warrior"]="Grimand Elmore använder Burning Blood för att prova smidesmetoder och lovar slitstark plåtrustning till krigare som för det till honom.",["profession:Blacksmithing"]="Smeder kan använda ovanliga material som brinnande worgenblod för att kyla och härda tunga metaller vid extrem hetta."},sec={{t="Ett flyktigt reagens",b="Nightbane worgen strövar omkring i Duskwood med en märklig vrede, och deras blod bränner med verklig hetta. Vätskan kan tappas från worgen som hemsöker skogarna och Roland's Doom. Den är vidrig att samla in, men dess hetta intresserar rustningsmakare som vill härda slitstark plåt."},{t="Elmores experiment",b="Grimand Elmore arbetar som rustningsmakare i Stormwinds Dwarven District. Han vill prova smidesmetoder som utvecklats av hans tidigare elev Furen Longbeard. För experimentet behöver Elmore Burning Blood och en tät, brinnande sten som hålls av worgen-hövdingen Gutspill. De som återvänder med den bubblande vätskan utlovas en stadig krigarrustning från hans smedja."}},faq={{q="Vad är Burning Blood?",a="Burning Blood är en het kroppsvätska från Nightbane worgen i Duskwood. Grimand Elmore behöver den till smidesexperiment.",al={"lore om burning blood","vad är burning blood","worgenblod"}},{q="Var kommer Burning Blood ifrån?",a="Burning Blood kommer från Nightbane worgen i Duskwood, särskilt de som håller till kring Roland's Doom.",al={"var hittar man burning blood","vem släpper burning blood","burning blood plats"}},{q="Varför behöver Grimand Elmore det?",a="Grimand Elmore behöver Burning Blood för att prova smidesmetoder som utvecklats av Furen Longbeard. Med en brinnande sten planerar han att smida skyddande ringbrynja åt en krigare.",al={"varför grimand vill ha burning blood","grimand elmore bloduppdrag"}},{q="Varför brinner Nightbanes blod?",a="Nightbane är onaturliga vidunder som kallats fram med mörk, kaotisk magi. Förbannelsen i deras blod ger det en våldsam, onaturlig hetta.",al={"varför worgen har brinnande blod","är worgenblod eld"}}},fp="26,128,18.267.0,19.351.0,22.126.0,35.93.0,32.159.0,42.123.0"}
P.entries["item:burning-rock"] = {n="Burning Rock",s="I Duskwood pyr Burning Rock i djupet av Roland's Doom. Gutspill, ledare för Nightbane-worgen, bär den, och Grimand Elmore i Stormwind behöver den och brinnande worgenblod för att smida förtrollade rustningar åt lovande krigare.",h="I Duskwood pyr Burning Rock i djupet av Roland's Doom.",kw={"burning rock","duskwood","furen longbeard","grimand elmore","gutspill","nightbane-worgen","roland's doom"},ang={["class:Warrior"]="Som krigare trotsar du farorna i Roland's Doom för att hämta Burning Rock. Grimand Elmore belönar ditt mod med en rustning som smids särskilt åt dig med hjälp av dess hetta.",["profession:Blacksmithing"]="Som smed kan du studera Burning Rock som en ovanlig värmekälla. Rustningssmeder i Stormwind och Ironforge utforskar okonventionella sätt att smälta och härda rustningar."},sec={{t="Ett glödande fynd",b="Gutspill bär Burning Rock genom gångarna i Roland's Doom. Grimand Elmore i Stormwind vill använda dess hetta till rustningar smidda med brinnande worgenblod. Han prövar smidestekniker som utvecklats av hans kollega Furen Longbeard för att göra tåliga plåtar åt erfarna krigare."}},faq={{q="Var finns Burning Rock?",a="Gutspill bär Burning Rock inne i Roland's Doom i östra Duskwood.",al={"burning rock plats","vem släpper burning rock","var får man tag på burning rock"}},{q="Vem vill ha Burning Rock?",a="Grimand Elmore, en dvärgisk smed i Dwarven District i Stormwind City, vill ha Burning Rock för att pröva experimentella smidestekniker.",al={"vem behöver burning rock","vem lämnar man burning rock till","grimand elmore burning rock"}},{q="Varför behöver Grimand Elmore den?",a="Grimand tänker pröva smidestekniker som utvecklats av Furen Longbeard. Tillsammans med Nightbane-worgenblod ger den glödande stenen hettan som behövs för att smida en unik rustning.",al={"användning av burning rock","varför burning rock","vad gör burning rock"}},{q="Vad har stenen för koppling till worgen?",a="Nightbane-worgen i Roland's Doom har märkliga eldiga egenskaper, däribland brinnande blod. Deras ledare, Gutspill, förvarar Burning Rock djupt inne i gruvan. Det är okänt om worgen hittade den där eller tog den med sig.",al={"varför har worgen burning rock","gutspill burning rock bakgrund"}}},fx={a40de154={q="Vad är Burning Rock?",a="Burning Rock är ett sällsynt, upphettat mineral som hittas djupt inne i Duskwoods hemsökta skogar. Den eldiga stenen hålls av Gutspill, ledaren bland de vilda Nightbane-worgen som håller till i Roland's Doom. Den behåller en intensiv hetta och eftersöks för specialiserat smide och metallurgi.",al={"vad är burning rock","föremålet burning rock","om burning rock"}}},fp="12,234,18.265.0,32.71.0,27.130.0,32.170.0,50.220.0"}
P.entries["item:cache-of-zanzil-s-altered-mixture"] = {n="Cache of Zanzil's Altered Mixture",s="I Venture Company-tornet nära The Sludge Fen ligger ett förråd med kraftfullt gift inlåst. Blandningen bär namnet Zanzil, en trollhäxdoktor från djungeln, och har väckt Shattered Hands uppmärksamhet.",h="I Venture Company-tornet nära The Sludge Fen ligger ett förråd med kraftfullt gift inlåst.",kw={"förändrad blandning","gallywix","kassaskrin","gift","shattered hand","shenthul","the sludge fen","venture co","zanzil"},ang={["class:Rogue"]="För Hordens skurkar är det en viktig övergångsrit att hämta blandningen, ett bevis på mästerskap i låsdyrkning, ficktjuveri och giftkunskap i Shattered Hands tjänst.",["faction:Horde"]="Venture Companys giftfyllda torn norr om The Sludge Fen hotar omgivningen och säkerheten i både Durotar och The Barrens."},sec={{t="Ett giftigt företag",b="Norr om The Sludge Fen i The Barrens har Venture Company en utpost i ett torn. Högst upp förvarar Grand Foreman Puzik Gallywix en samling av den förändrade blandningen, som bär trollhäxdoktorn Zanzils namn, i sin privata kassaskrin. Ett gift har försvagat alla i tornet och gjort dess goblininvånare sårbara för en djärv inkräktare."},{t="Återhämtning åt Shattered Hand",b="Shattered Hand, ett hemlighetsfullt skurkskrå under Orgrimmar, har lagt märke till farliga alkemiska material så nära Durotar. Mästartränaren Shenthul skickar operatörer för att storma tornet, döda Gallywix och bryta upp hans låda. Skrået vill både oskadliggöra hotet och studera blandningen för sitt eget underrättelsearbete. Att återta det flyktiga förrådet kräver god infiltrationsförmåga. Gifterna i den kontaminerade behållaren kan utsätta den som hanterar den för försvagande verkan."}},faq={{q="Vad är Zanzils förändrade blandning?",a="Zanzil's Altered Mixture är ett kraftfullt gift uppkallat efter trollhäxdoktorn Zanzil. En samling av det ligger inlåst i Venture Company-tornet nära The Sludge Fen, där ett gift har försvagat alla där inne.",al={"vad är zanzils blandning","vad är förrådet","zanzils dryck"}},{q="Var finns förrådet?",a="Samlingen finns i Gallywix's Lockbox högst upp i Venture Company-tornet, norr om The Sludge Fen i The Barrens.",al={"var finns blandningen","var finns zanzils förråd","blandningens plats"}},{q="Varför vill Shattered Hand ha blandningen?",a="Shenthul och Shattered Hand vill oskadliggöra Venture Companys verksamhet precis vid Hordens tröskel och återta ämnet för egna underrättelsestudier.",al={"vem vill ha blandningen","varför vill shenthul ha den","shattered hands uppdrag"}},{q="Hur öppnar du kistan med förrådet?",a="Kistan har känsliga kombinationslås som kräver avancerad låsdyrkning, och den kontaminerade behållaren kan utsätta den som hanterar den för försvagande gifter.",al={"hur dyrkar man upp gallywix kassaskrin","öppna zanzils kista","dyrka upp zanzils förråd"}}},fx={["83dd2f73"]={q="Varifrån kommer Zanzil's Altered Mixture, och vem tillverkade den?",a="Brygden kommer från häxdoktorn Zanzil, men hamnade i händerna på Venture Company, som verkar från The Barrens. Överförman Puzik Gallywix låste in den återstående förändrade blandningen i sitt privata kassaskrin högst upp i deras borrtorn nära The Sludge Fen.",al={"vem tillverkade zanzil altered mixture","den förändrade blandningens ursprung","varifrån kommer zanzils blandning"}}},fp="33,205,18.342.0,31.496.1,33.205.0,25.115.0,45.171.0,47.156.0"}
P.entries["item:cactus-apple"] = {n="Cactus Apple",s="I Valley of Trials ger kaktusäpplen orcherna en sällsynt fuktkälla i Durotars torra hetta.",h="I Valley of Trials ger kaktusäpplen orcherna en sällsynt fuktkälla i Durotars torra hetta.",kw={"cactus apple","cactus apple surprise","ökenfrukt","durotar","galgar","valley of trials"},ang={["profession:Cooking"]="Som vildmarkskock i Durotar kan du förvandla öknens kaktusar till en vätskerik måltid.",["race:Orc"]="Som ung orch i Durotar lär du dig att ta vara på varje knapp fuktdroppe som den röda ravinen erbjuder."},sec={{t="Ökenskörd",b="Kaktusäpplen växer i klasar på de tjocka kaktusarna som står utspridda över Valley of Trials. Att plocka dem innebär att arbeta bland taggarna, men frukten ger välkommen vätska i Durotars hetta. Galgar, en orch i dalen, samlar äpplena för att laga Cactus Apple Surprise, en svalkande godsak åt rekryter som uthärdar sin första träning."}},faq={{q="Var växer Cactus Apple?",a="Kaktusäpplen växer vilt i Valley of Trials i södra Durotar, nära basen av kraftiga kaktusväxter som står utspridda över sänkan.",al={"platser med cactus apple","var hittar man cactus apple","cactus apple-plats"}},{q="Vad är Cactus Apple Surprise?",a="Cactus Apple Surprise är en kyld rätt som Galgar lagar av nyplockade kaktusäpplen och som lindrar Durotars ökenhetta.",al={"vad är galgars överraskning","recept på cactus apple","galgars godsak"}},{q="Vem ber om dessa äpplen?",a="Galgar, en orch i Valley of Trials, ber unga rekryter att hämta sex färska äpplen i utbyte mot portioner av hans svalkande dessert.",al={"uppdragsgivare för cactus apple","vem vill ha cactus apple","galgars äpplen"}}},fx={["93b3f975"]={q="Vad är Cactus Apple?",a="Cactus Apple är en krispig och uppfriskande vild frukt som växer under de taggiga kaktusarna i Valley of Trials i Durotar. Trots de hårda, torra förhållandena i orchernas hemland ger de tåliga växterna saftiga frukter som skänker välbehövlig vätska och näring under den brännande ökensolen.",al={"vad är cactus apple","historien om cactus apple","vad är cactus apples"}},e52e1b37={q="Varifrån kommer Cactus Apples?",a="Cactus Apples är ökenfrukter som växer naturligt vid basen av kaktusar utspridda över Valley of Trials i Durotar. De tillverkas eller odlas inte av någon enskild person, utan spirar direkt ur den tåliga växtlighet som är anpassad till regionens röda raviner och torra klimat.",al={"varifrån kommer cactus apples","cactus apples ursprung","vem tillverkade cactus apples"}},["0fea9150"]={q="Varför vill Galgar ha Cactus Apples?",a="Galgar samlar in dem för att laga omgångar av sin berömda Cactus Apple Surprise. Den tryckande hettan i Valley of Trials tär hårt på både nya rekryter och erfarna krigare. Den söta, svalkande efterrätten av de här äpplena ger välbehövlig svalka mot den skoningslösa middagssolen.",al={"varför samla in cactus apples","varför vill galgar ha cactus apples","cactus apples användning"}}},fp="12,98,14.339.0,28.134.0,30.136.0,26.139.0"}
P.entries["item:calor-s-note"] = {n="Calor's Note",s="Calor's Note är en bit bleknat pergament som skogsmannen Calor skrivit för att rekommendera en beprövad äventyrare till Master Jonathan Carevin. Den fungerar som en introduktion till en skuggfull grupp som verkar sida vid sida med Darkshires formella stadsvakt, men är fristående från den.",h="Calor's Note är en bit bleknat pergament som skogsmannen Calor skrivit för att rekommendera en beprövad...",kw={"calor","calor's note","darkshire","duskwood","jonathan carevin","night watch","rekommendation","worgen"},ang={["class:Paladin"]="Jonathan Carevin välkomnar den som bär lappen med orden ”Ära under Ljuset”, som visar på en ideologisk samhörighet med heliga krigare som vill rena Duskwood från demoner och odöda.",["faction:Alliance"]="Eftersom Stormwinds armé helt saknas i Duskwood är inofficiella grupper som Carevins krets och Night Watch det enda skyddet mot mörkret vid den södra gränsen."},sec={{t="En sällsynt rekommendation",b="Duskwood erbjuder främlingar mycket lite värme, och Calor är ökänd för att vara svår att imponera på. Den som överlever möten med de blodtörstiga worgen som stryker genom skogarna vinner hans respekt och får honom att skriva detta korta meddelande. När den bleknade lappen förs till Darkshire fungerar den som ett trovärdighetsbevis och introducerar en främling direkt för Jonathan Carevin."},{t="En privat kamp",b="Darkshire förlitar sig på Night Watch för att försvara staden, men Calor och Carevin utkämpar en mörkare och mer hemlighetsfull strid. Calor beklagar öppet att stadsvakten är fler än hans egna, och hoppas hitta tillräckligt många dugliga kämpar för att föra deras privata krig vidare. När du överlämnar lappen får du tillträde till Carevins kampanj mot demoner, odöda och de dolda sympatisörer som bidrar till Duskwoods förfall."}},faq={{q="Vad är Calor's Note?",a="Det är ett handskrivet meddelande som Calor skrivit på en bit bleknat pergament. Det är ett personligt rekommendationsbrev som intygar en äventyrares stridsförmåga och pålitlighet mot Duskwoods fasor.",al={"calors lapp","vad är det här för lapp","vad står det på lappen"}},{q="Vem får lappen?",a="Lappen är adresserad till Jonathan Carevin, en sträng person som är stationerad i Darkshire och samordnar en särskild insats mot de mörka krafter som hotar trakten.",al={"vem ska jag ge lappen till","vem får calors lapp","jonathan carevins lapp"}},{q="Vad tycker Calor om Night Watch?",a="Calor anser att Night Watch inte räcker till mot de verkliga hoten som lurar i Duskwood. När han lämnar över lappen säger han att han vill rekrytera tillräckligt många dugliga allierade för att bli fler än stadsvakten. Han hoppas äntligen kunna slutföra det brådskande arbete som hans lilla grupp utför ensam.",al={"calor och night watch","varför vill calor bli fler än night watch"}},{q="Vilken sorts strid utkämpar Jonathan Carevin?",a="Master Carevin utkämpar en obeveklig strid mot demoner, odöda och dödliga medhjälpare som bistår dem i Duskwood. Han värdesätter vaksamhet och hängivenhet till det Heliga Ljuset och tar bara in beprövade personer i sin krets.",al={"carevins sak","vad gör carevin","vilka strider carevin mot"}}},fx={d10add4c={q="Vem skrev Calor's Note, och varifrån kommer den?",a="Anteckningen är skriven av Calor, en bister kämpe stationerad i Duskwoods hemsökta vidder. När du har visat vad du går för mot de våldsamma worgen som terroriserar skogen skriver han ett meddelande på en bit blekt pergament och skickar dig vidare till sin överordnade.",al={"calor's notes ursprung","vem skrev calors note","varifrån kommer calor note"}},fe7f9dd8={q="Varför vill Jonathan Carevin ha Calor's Note?",a="Mästare Jonathan Carevin kräver bevis innan han litar på någon i ett land som överskuggas av hot. Calors anteckning är ett officiellt erkännande som visar Carevin att du har Calors sällsynta respekt och kan hjälpa till i deras hemliga kamp mot demoner, odöda och mörkare krafter.",al={"varför ta calors note till carevin","varför vill carevin ha calors note","calor note användning för carevin"}}},fp="12,258,21.312.0,17.380.0,21.159.0,22.154.0,38.237.0,48.196.0"}
P.entries["item:candle-of-beckoning"] = {n="Candle of Beckoning",s="Candle of Beckoning är ett förtrollat ritualjus som den tillbakadragne nekromantikern Gunther Arcanus förvarar vid Brightwater Lake. Om du ställer ljuset på ett altare på en närliggande liten ö och tänder det, kallar du fram en rastlös ande vid namn Lillith Nefara.",h="Candle of Beckoning är ett förtrollat ritualjus som den tillbakadragne nekromantikern Gunther Arcanus...",kw={"brightwater lake","candle of beckoning","gunther arcanus","lillith nefara","bevisa lojalitet","den slumrande skuggan","tirisfal glades"},ang={["class:Mage"]="Gunthers förmåga att binda andar till rituella föremål som det här ljuset visar hans mästerskap inom nekromanti och besvärjelser, utanför Kirin Tors godkända läror.",["race:Undead"]="För Forsaken-sändebud från Undercity är hanteringen av Gunthers ritualjus ett nödvändigt steg för att övertyga den starkt självständige nekromantikern om att du inte är Lich Kings träl."},sec={{t="Ett lojalitetstest",b="Candle of Beckoning finns i en låda bredvid den ensamme magikern Gunther Arcanus på hans ö i Brightwater Lake. Ljuset används i en mörk kallelseritual. Gunther är en starkt självständig odöd trollkarl som på egen hand bröt sig fri från Lich Kings kontroll. Han är fortfarande vaksam mot både Scourge och Forsaken. För att bevisa att du inte är lojal mot Lich King ber Gunther dig ta ett av ljusen sydväst till en mindre ö. Där ställer du det på ett gammalt, blodfläckat bord. Lågans sken genomborrar slöjan mellan världarna och väcker den slumrande skuggan Lillith Nefara, en mäktig agent för Scourge, så att hon kan förgöras."}},faq={{q="Vad används Candle of Beckoning till?",a="Ljuset används för att kalla fram skuggan Lillith Nefara. När du ställer det på det gamla, blodfläckade ritualbordet på den mindre ön sydväst om Gunther Arcanus läger och tänder det, dras den slumrande anden in i den fysiska världen.",al={"vad gör candle of beckoning","användning av candle of beckoning","hur använder man candle of beckoning"}},{q="Var hittar du Candle of Beckoning?",a="Du får ljuset ur en låda bredvid Gunther Arcanus på hans ö i Brightwater Lake, i östra Tirisfal Glades, medan du utför hans lojalitetstest.",al={"var hittar man candle of beckoning","hur får man candle of beckoning","var finns ljuslådan"}},{q="Vem kallas fram av ljuset?",a="När du tänder ljuset kallar du fram Lillith Nefara, en mäktig agent för Scourge som hemsöker det blodiga altaret utanför öns södra kust. Du måste besegra henne för att bevisa att du inte tjänar Scourge.",al={"vem kallar ljuset fram","målet för ljusets kallelse","vem är lillith nefara"}},{q="Varför har Gunther Arcanus dessa ljus?",a="Gunther använder ljusen och ritualen kring dem som ett prov. Han misstror främlingar och värnar starkt om sin självständighet gentemot Scourge. Därför kräver han att alla som söker hans hjälp möter och förgör de rastlösa döda han kallar fram.",al={"varför har gunther ljus","gunthers ritualjus"}}},fx={["63af5e56"]={q="Vad är Candle of Beckoning?",a="Candle of Beckoning är ett förtrollat ritualjus som finns på nekromantikern Gunther Arcanus avskilda öreträtt i Brightwater Lake. Ljuset förvaras i en låda bredvid den tillbakadragna magikern och bär på kraftfulla besvärjelser som kan kalla på någon bortom dödens slöja. När det ställs på ett blodigt ritualbord på en närliggande liten ö och tänds fungerar lågan som ett övernaturligt lockbete som kallar fram Lillith Nefaras slumrande ande.",al={"vad är candle of beckoning","historien om candle of beckoning","vad är beckoning candle"}},cb4d5793={q="Varför skulle någon vilja ha Candle of Beckoning?",a="Den som söker ett möte eller en allians med Gunther Arcanus måste först bevisa sin lojalitet mot någon annan än Lich King. Gunther kräver bevis på trohet innan han delar med sig av sina imponerande förmågor till Forsaken. Genom att hämta Candle of Beckoning kan du locka fram och förgöra Lillith Nefara, visa din beslutsamhet att bekämpa Scourge och vinna den eremitiske nekromantikerns svårvunna respekt.",al={"varför behöver jag candle of beckoning","varför vill någon ha candle of beckoning","syftet med candle of beckoning"}}},fp="19,153,20.634.0,41.221.0,41.175.0,30.185.0,44.217.0"}
P.entries["item:cantation-of-manifestation"] = {n="Cantation of Manifestation",s="Cantation of Manifestation är en specialiserad arkansk besvärjelse nedtecknad på en pergamentrulle, som magiker använder för att avslöja osedda magiska avvikelser. I Undercity ger Anastasia Hartwell den till lärlingar som undersöker osynliga magiska väsen som hemsöker Algernon's butik i Apothecarium.",h="Cantation of Manifestation är en specialiserad arkansk besvärjelse nedtecknad på en pergamentrulle, som...",kw={"algernon","anastasia hartwell","apothecarium","cantation of manifestation","förvaringskista","magic quarter","riftspräng","undercity"},ang={["class:Mage"]="Cantation of Manifestation är ett viktigt redskap i din tidiga träning och lär dig att upptäcka dolda arkaniska strömmar och hålla instabila revvarelser i schack.",["race:Undead"]="Forsaken-besvärjare i Magic Quarter håller noggrann kontroll över arkaniska fluktuationer och ser till att magiska revor inte äventyrar Undercitys stabilitet."},sec={{t="Avslöja det osynliga",b="Cantation of Manifestation innehåller en fokuserad besvärjelse som är utformad för att tränga igenom magiska slöjor och tvinga okroppsliga, osynliga väsen in i det synliga spektrumet. Rullen förvaras i Magic Quarter i Undercity, nära Anastasia Hartwell, och anförtros åt dugliga magiker med uppdrag att hålla arkanska avvikelser i schack. När den läses högt på en plats med arkan instabilitet, som Algernon's alkemiska verkstad i Apothecarium, tvingar orden kringirrande riftspräng att materialiseras, så att magikern kan kuva och fånga dem i förvaringskistor för vidare studier."}},faq={{q="Vad gör Cantation of Manifestation?",a="Det är en magisk skriftrulle som innehåller en besvärjelse som avslöjar osynliga arkanska avvikelser. När den läses upp på platser med magiska revor eller störningar tvingar den osedda varelser, som riftspräng, att visa sig tydligt så att de kan bekämpas och fångas.",al={"vad är cantation of manifestation","cantationens syfte","hur fungerar cantation"}},{q="Var hittar jag Cantation i Undercity?",a="Den ligger på golvet precis bakom magiktränaren Anastasia Hartwell, i Magic Quarter i Undercity.",al={"cantationens plats i undercity","var finns cantation of manifestation","hitta cantation i undercity"}},{q="Varför behöver Anastasia Hartwell att den här rullen används?",a="En märklig magisk störning bröt ut i Algernon's alkemiska butik nere i Apothecarium. Osedda väsen helt och hållet bestående av magi började ströva omkring i lokalen, och Hartwell behöver att rullen läses på plats för att avslöja och fånga varelserna innan revan förvärras.",al={"varför använda cantation","hartwells motiv för uppdraget","anastasias störning"}},{q="Får jag behålla rullen efter att jag använt den?",a="Nej. När du har manifesterat riftsprängen och fångat dem i förvaringskistor måste du lämna tillbaka Cantation of Manifestation tillsammans med kistorna till Anastasia Hartwell.",al={"behålla cantation","förlorar jag cantation","lämna tillbaka cantation"}}},fx={["1a839123"]={q="Vad är Cantation of Manifestation?",a="Cantation of Manifestation är en specialiserad arkanrulle som används av magiker. När dess besvärjelse uttalas tränger den igenom magiska fördunklingar och tvingar osynliga väsen, som enbart består av arkan energi, att visa sig för blotta ögat.",al={"vad är cantation of manifestation","cantation of manifestation-rulle","vad gör cantation of manifestation"}},f236f2b5={q="Varför vill Anastasia Hartwell ha Cantation of Manifestation?",a="Osynliga magiska varelser har dykt upp kring Algernon's shop i Apothecarium, ett tecken på en störning i magins flöde. Magikertränarna behöver få besvärjelsen uppläst så att en lärling kan avslöja och fånga väsendena för studier. Då kan Undercity's magiker avgöra om störningen är en olyckshändelse eller en aktiv magisk attack.",al={"varför vill någon ha cantation of manifestation","varför behövs cantation of manifestation","varför vill anastasia ha cantation of manifestation"}}},fp="26,115,23.441.0,44.220.0,44.126.0,50.262.0,43.154.0"}
P.entries["item:canvas-scraps"] = {n="Canvas Scraps",s="I Razor Hill samlar Furl Scornbrow Canvas Scraps för att göra resväskor åt nya rekryter i Horde. Tyget kommer från mänskliga inkräktare och centaurstammar i Durotar.",h="I Razor Hill samlar Furl Scornbrow Canvas Scraps för att göra resväskor åt nya rekryter i Horde.",kw={"canvas scraps","bär din börda","durotar","furl scornbrow","kolkar","kul tiras","razor hill"},ang={["faction:Horde"]="Varje tygrest från inkräktare från Kul Tiras eller Kolkar-rövare hjälper till att utrusta nya försvarare som hörsammar Thralls kallelse i Durotar.",["profession:Tailoring"]="Krigare samlar vävd kanvas som råmaterial, och det tåliga tyget kan bli praktiska väskor för den hårda öknen."},sec={{t="Troféer från Durotars fiender",b="Marinsoldater och sjömän från Kul Tiras bär med sig kanvas längs Durotars östra kust. Deras utrustning och segel lämnar tygrester efter sig. Inåt land återanvänder Kolkar-centaurer grovt tyg från förrådskaravaner och tidigare strider. I deras läger och utrustning finns rester som kan tas till vara."},{t="En veterans hantverk",b="Furl Scornbrow håller utkik efter inkräktare från Razor Hill Watchtower. Den åldrade veteranen har lämnat striderna bakom sig, men tar vara på fiendens tyg. Han syr det till slitstarka bärväskor åt yngre soldater och hjälper den nya generationen att försvara Hordes gränser."}},faq={{q="Varifrån kommer Canvas Scraps?",a="Canvas Scraps kommer från mänskliga och centauriska fiender runt om i Durotar. Kul Tiras styrkor vid Tiragarde Keep och längs östkusten bär med sig sådant tyg, liksom Kolkar-centaurernas arbetare och spejare nära deras läger inåt land.",al={"vem släpper canvas scraps","var får man tag på canvas scraps","farma canvas scraps"}},{q="Varför vill Furl Scornbrow ha tygbitarna?",a="Furl Scornbrow är en åldrad Orc-veteran i Razor Hill Watchtower som inte längre kan strida vid frontlinjen. Han syr det tillvaratagna tyget till resväskor åt unga äventyrare.",al={"vem behöver canvas scraps","vad används canvas scraps till","furl scornbrow canvas"}},{q="Varför bär Kul Tiras trupper och kentaurer canvas?",a="Trupper från Kul Tiras kom till Durotar ombord på krigsskepp och har läger vid havet, där segelduk och vävd kanvas är vardagsnödvändigheter. Kolkar-centaurer får tag på grova tyger genom att plundra karavaner, leta längs kusten och råna resenärer på de torra slätterna.",al={"varför har kentaurer canvas","lore om mänskliga canvas scraps"}}},fx={["6d5b894e"]={q="Vad är Canvas Scraps?",a="Canvas Scraps är bitar av kraftigt, vävt tyg som tagits till vara från fienders läger och utrustning runt om i Durotar. Segelduk är tåligare än enkelt linne och används ofta till tung militär utrustning, segel och slitstarka tält. Sådana tygbitar kan se ut som skräp på slagfältet, men en skicklig skräddare eller hantverkare kan enkelt göra praktiska förnödenheter av de slitstarka fibrerna, till exempel stadiga bärväskor för krigare på marsch.",al={"vad är canvas scraps","föremålet canvas scraps"}}},fp="13,163,29.261.0,17.278.0,33.206.0,42.182.0,53.257.0"}
P.entries["item:cask-of-merlot"] = {n="Cask of Merlot",s="En Cask of Merlot är en tunna fint rödvin som produceras och säljs i Stormwind City. Den är en av flera regionala specialdrycker som värdshusvärden i Lakeshire behöver på grund av leveransbristen under svartrockorcernas invasion.",h="En Cask of Merlot är en tunna fint rödvin som produceras och säljs i Stormwind City.",kw={"barkeep daniels","cask of merlot","dry times","galina winery","lakeshire","merlot","roberto pupellyverbos","stormwind"},ang={["faction:Alliance"]="Att hämta tunnan visar den skarpa kontrasten mellan den trygga lyxen i Stormwinds kanaldistrikt och gränsstäderna i Redridge, där invånarna kämpar under belägring."},sec={{t="En smak av huvudstaden",b="Det här Cask of Merlot har skördats och jäst i kungarikets hjärta och kommer direkt från Galina Winerys källare, längs kanalerna vid Stormwinds Trade District. Vinmakaren Roberto Pupellyverbos sköter årgångarna där och tillgodoser huvudstadens mer förfinade smak. Till skillnad från Duskwoods starka månsken och den lantliga sprit som bryggs i Elwynn vittnar merlotvinet om människornas förfinade vinmakarkonst, som utövas i stadsmurarnas relativa trygghet."},{t="Påfyllning i Lakeshire",b="När Blackrock-klanen invaderade Redridge Mountains bröts försörjningsvägarna, och Lakeshire isolerades från sina vanliga handelsleveranser. Barkeep Daniels ger villiga kurirer i uppdrag att resa genom hela kungariket och fylla på källaren i hans värdshus, medan lokalbefolkningen törstar och är vettskrämd. Med tunnan kan försvararna och flyktingarna vid Lake Everstill skölja ner sina ransoner med något milt."}},faq={{q="Var hittar jag ett Cask of Merlot?",a="Det säljs av Roberto Pupellyverbos inne på Galina Winery. Butiken ligger längs kanalerna vid utkanten av Trade District i Stormwind City.",al={"var finns cask of merlot","var köpa merlot","vem säljer cask of merlot","vinsäljare i stormwind"}},{q="Varför behöver Barkeep Daniels det här vinet?",a="Lakeshires vanliga handelsleveranser har stoppats av svartrockorcernas invasion av Redridge. Barkeep Daniels håller på att få slut på alkohol och skickar äventyrare genom södra Azeroth för att hämta regionala specialiteter och hålla gästerna nöjda.",al={"dry times-uppdraget merlot","varför vill daniels ha vin","syftet med merlot i lakeshire"}},{q="Vilka andra drycker samlas in tillsammans med merlotvinet?",a="Daniels ber också om en Skin of Sweet Rum från Goldshire, en Bottle of Moonshine från Darkshire och en tunna Thunderbrew Lager från Grimbooze Thunderbrew i Westfalls kullar.",al={"dry times-drycker","daniels alkohollista","övrig alkohol i dry times"}},{q="Är Galina Winery i fara?",a="Vingården är trygg bakom Stormwind Citys stenbefästningar. Medan avlägsna områden som Westfall och Redridge plågas av banditer och orcattacker fortsätter handeln och vinframställningen ostört i huvudstadens kanaldistrikt.",al={"galina winerys bakgrund","vingård i stormwind"}}},fx={e882dee4={q="Vad är Cask of Merlot?",a="Det är en rejäl tunna med fint rödvin som produceras och säljs i Stormwind City. Vanliga invånare uppskattar det som ett vin för vardagen, medan avlägsna bosättningar som drabbats av oroligheter värdesätter stora mängder för att hålla värdshusen välförsedda och lokalbefolkningens humör uppe.",al={"vad är cask of merlot","föremålet cask of merlot","vad är merlot-tunnan"}},["33c97a45"]={q="Varifrån kommer Cask of Merlot, och vem tillverkade det?",a="Tunnan kommer från Galina Winery, som ligger längs kanalerna vid Trade District i Stormwind City. Den görs i ordning och säljs av Roberto Pupellyverbos, som förser stadens gäster och resande köpmän med vingårdens eftertraktade årgångsviner.",al={"cask of merlots ursprung","vem tillverkar merlot","varifrån kommer cask of merlot"}}},fp="14,90,22.390.0,20.349.0,34.137.0,40.235.0,53.179.0,31.210.0"}
P.entries["item:cask-of-scalder"] = {n="Cask of Scalder",s="I Stormwind är en tunna Barleybrew Scalder på väg till en gammal bekant. Det eldiga ölet förmedlar en gentjänst mellan dvärgar.",h="I Stormwind är en tunna Barleybrew Scalder på väg till en gammal bekant.",kw={"öl","barleybrew","cask of scalder","dwarven district","furen longbeard","sköldsmed","stormwind"},ang={["class:Warrior"]="Som krigare kan du få ta del av Furen Longbeards berömda smideskonst genom att ge honom en tunna fint öl, en viktig övergångsrit för att få pålitligt skydd.",["race:Dwarf"]="Som dvärg vet du att en leverans av en färsk tunna av Barleybrews finaste kan besegla en uppgörelse eller betala av en gammal skuld."},sec={{t="En dvärgisk uppgörelse",b="Resenärer som har visat sitt värde genom Rethban Gauntlet för med sig Barleybrew Scalder till Furen Longbeard i Stormwinds Dwarven District. Dvärgen är en skicklig sköldsmed och tycker att torra tider är outhärdliga. En tunna värmande öl ger Yorus Barleybrew möjlighet att kräva in en gammal gentjänst och få skickligt dvärghantverk i utbyte."}},faq={{q="Vad finns i Cask of Scalder?",a="Cask of Scalder är fylld med Barleybrew Scalder, ett eldigt brygg som tillverkas av familjen Barleybrew. Dvärgar uppskattar dess kraftiga smak och värmande styrka.",al={"vilken dryck finns i den här","scalderöl","barleybrew scalder"}},{q="Vem är tunnan avsedd för?",a="Tunnan är avsedd för Furen Longbeard, en skicklig dvärgisk sköldsmed som arbetar i Stormwinds Dwarven District.",al={"vem får tunnan","var ska jag lämna den","mottagare av scalder"}},{q="Varför levereras tunnan till Furen Longbeard?",a="Furen är skyldig Yorus Barleybrew en gentjänst. Tunnan stillar Furens törst under det han kallar torra tider och får honom att smida en tålig, enastående sköld åt budbäraren.",al={"varför furen vill ha scalder","gentjänst från sköldsmed","tunnans syfte"}}},fx={df3534f2={q="Vad är Cask of Scalder?",a="Cask of Scalder är en träkagge fylld med Barleybrew Scalder, ett mustigt öl som bryggs av familjen Barleybrew. Yorus Barleybrew ger den till dig som gåva och introduktion till sin dvärgvän i Stormwind, sköldsmeden Furen Longbeard.",al={"vad är cask of scalder","cask of scalder","vad är scalder"}},["1fd358f8"]={q="Varifrån kommer Cask of Scalder, och vem tillverkade det?",a="Yorus Barleybrew ger dig tunnan i Redridge Mountains efter att du segrat i Rethban Gauntlet. Denna särpräglade dryck bryggs av den välkända Barleybrew-klanen och bjuds som en rejäl gåva värdig en mästerligt smidd dvärgsköld.",al={"vem tillverkade cask of scalder","cask of scalders ursprung","varifrån kom cask of scalder"}}},fp="15,127,17.336.0,35.132.0,30.109.0,52.170.0"}
P.entries["item:cask-of-shimmer-stout"] = {n="Cask of Shimmer Stout",s="Cask of Shimmer Stout är en förseglad tunna med Rejold Barleybrews kraftiga nya öl, bryggd i de kalla höjderna i Dun Morogh. Den är känd för sin anmärkningsvärda styrka och yrselframkallande verkan och skickas österut över bergen som en munter gåva till andra bergsdvärgar.",h="Cask of Shimmer Stout är en förseglad tunna med Rejold Barleybrews kraftiga nya öl, bryggd i de kalla...",kw={"cask of shimmer stout","dun morogh","kadrell","loch modan","rejold barleybrew","shimmer stout","thelsamar"},ang={["race:Dwarf"]="För dvärgar är det en vördad tradition att dela fin öl mellan patrullerna. Den håller samman bergsväktarna som tjänstgör långt från varandra bland Khaz Modans karga toppar."},sec={{t="En munter leverans",b="Shimmer Stout bryggdes i Brewnall Village av Rejold Barleybrew och fick snabbt höga betyg bland ortens gäster och bergsdvärgar som trotsade den bitande kylan i Dun Morogh. Hans bror Mountaineer Barleybrew imponerades av brygden och beställde en tunna som skulle forslas genom det östra passet till Loch Modan. Dvärgar värdesätter stark dryck högt, både som en självklar del av umgänget och som ett praktiskt skydd mot den bitande bergskylan. Att dela en färsk brygd med kamrater långt borta är en långvarig militär tradition."},{t="En uppiggande dryck för dvärgar",b="När Mountaineer Kadrell öppnar tunnan och smakar på ölet under sin vakt i Thelsamar visar det sig leva upp till sitt rykte. Det är långt ifrån vanlig krogöl. En enda klunk Shimmer Stout sägs göra benen lätta och få en soldat att känna sig redo att lyfta — precis den sorts uppiggande dryck en dvärgspanare förlitar sig på under långa, ensliga patruller längs höga vägar."}},faq={{q="Vad är Shimmer Stout?",a="Shimmer Stout är ett kraftigt dvärgäle som Rejold Barleybrew bryggde i Dun Morogh. Den är högt uppskattad för sin styrka och är känd för att pigga upp kroppen och hålla kylan borta.",al={"vad är shimmer stout","shimmer stout i berättelsen","vem bryggde shimmer stout"}},{q="Vem skickas tunnan till?",a="Tunnan skickas till Mountaineer Kadrell, en vakt som är stationerad längs vägen genom bosättningen Thelsamar i Loch Modan.",al={"vem får tunnan","vart skickas tunnan","tunnans mottagare"}},{q="Varför skicka öl över bergen?",a="Bergsdvärgar delar ofta särskilt goda brygder med sina kamrater på avlägsna patruller. Efter att ha smakat Rejolds lyckade brygd ville hans bror bjuda Kadrell på ett prov av Dun Moroghs finaste nya recept.",al={"varför leverans","varför leverera öl","varför skicka till kadrell"}},{q="Vilken effekt har Shimmer Stout på den som dricker den?",a="Ölet är förvånansvärt kraftigt. När Mountaineer Kadrell smakar på det utbrister han att det får huvudet att snurra, gör benen lätta och får honom att känna sig som om han kunde flyga.",al={"hur stark är shimmer stout","shimmer stouts effekt"}}},fx={aa5543f0={q="Varifrån kommer Cask of Shimmer Stout, och vem bryggde det?",a="Detta starka öl bryggdes av Rejold Barleybrew i Brewnall Village i Dun Morogh. Hans bror, Mountaineer Barleybrew, blev så imponerad av brygden att han tappade upp den på tunna för att dela med sig utanför hemtrakterna och lät en äventyrare bära den ända till Loch Modan.",al={"vem bryggde shimmer stout","varifrån kommer shimmer stout","bryggaren bakom cask of shimmer stout"}},["3b29018e"]={q="Varför vill någon ha Cask of Shimmer Stout?",a="Mountaineer Barleybrew älskar sin brors nya recept och vill att vaktkamraten Mountaineer Kadrell ska få smaka på brygden. Kadrell patrullerar de kalla vägarna kring Thelsamar, och ett kraftigt dvärgbryggt öl som värmer blodet, gör kroppen lättare och huvudet tungt är en fin uppmuntran under långa vakter.",al={"varför skicka shimmer stout","vem vill ha cask of shimmer stout","varför vill kadrell ha shimmer stout"}}},fp="21,209,19.438.0,20.332.0,22.178.0,30.112.0,34.165.0,51.167.0"}
P.entries["item:cats-eye-emerald"] = {n="Cats Eye Emerald",s="I norra Barrens har Cats Eye Emerald väckt intresset hos Ratchets hamnmästare Dizzywig. Venture Companys chefer håller den knytnävsstora ädelstenen under bevakning i Boulder Lode Mine.",h="I norra Barrens har Cats Eye Emerald väckt intresset hos Ratchets hamnmästare Dizzywig.",kw={"boss copperplug","boulder lode mine","cats eye emerald","smaragd","ratchet","the sludge fen","venture company","wharfmaster dizzywig"},ang={["class:Rogue"]="Som skurk är det ett tillfälle att slå till att stjäla en väldig ädelsten mitt framför näsan på Venture Companys korrumperade arbetsledare.",["profession:Mining"]="Som gruvarbetare är det den lyckoträff varje gruvarbetare drömmer om att hitta en felfri, knytnävsstor ädelsten i en industriell gruva som Boulder Lode Mine."},sec={{t="En knytnävsstor förmögenhet",b="Arbetare från Venture Company fann en enorm smaragd i Boulder Lode Mine, nordost om The Sludge Fen. Ryktet om fyndet spreds snabbt över savannen. I goblinernas trakter förblir sällsynta ädelstenar sällan hemliga. Handelsskvaller förde nyheten från Ratchets hamn till Booty Bay, och hamnmästare Dizzywig fick höra om skatten. Han började smida planer på att skicka den till den öppna marknaden i Undermine."},{t="I företagets ägo",b="Venture Companys ledning håller smaragden väl bevakad inne i gruvan. Förmän, väktare och chefsoperatörer som Boss Copperplug försvarar den mot rivaliserande karteller och lyckosökare. Dizzywig har lovat dem som hjälper honom att säkra ädelstenen en andel på femtio procent."}},faq={{q="Vad är Cats Eye Emerald?",a="Cats Eye Emerald är en ovanligt stor smaragd, ungefär lika stor som en knytnäve, som gruvarbetare hittade i norra Barrens. Dess klarhet och storlek gör den värd en förmögenhet på världsmarknaden.",al={"vad är cats eye emerald","cats eye-ädelsten","vilken sorts ädelsten är det här"}},{q="Var hittades ädelstenen?",a="Gruvarbetare från Venture Company grävde fram ädelstenen inne i Boulder Lode Mine, nordost om The Sludge Fen i norra Barrens.",al={"var hittades den","ädelstenens plats","smaragd i boulder lode mine"}},{q="Vem i Ratchet vill ha smaragden?",a="Hamnmästare Dizzywig, som sköter frakt och gods vid Ratchets hamn, vill ha stenen åt välbärgade köpare genom handelskontakter i Undermine.",al={"vem köper smaragden","dizzywig och smaragden","vem ger uppdraget om smaragden"}},{q="Vem håller stenen inne i gruvan?",a="Högt uppsatta förmän från Venture Company förvarar smaragden inne i Boulder Lode Mine. En av Venture Co:s förmän eller väktare bär på den.",al={"vem släpper smaragden","vem har cats eye emerald","var hittar man cats eye emerald"}}},fx={["24f13ef4"]={q="Varifrån kommer Cats Eye Emerald?",a="Cats Eye Emerald är en naturlig ädelsten stor som en knytnäve, uppgrävd djupt inne i Boulder Lode Mine, en utgrävning som drivs av Venture Company nordost om The Sludge Fen i The Barrens. Den är inget föremål som smitts eller slipats av en hantverkare, utan grävdes nyligen upp ur jorden av en av företagets lyckosammare goblin-gruvarbetare.",al={"cats eye emeralds ursprung","var hittades cats eye emerald","vem tillverkade cats eye emerald"}}},fp="16,179,20.374.0,18.275.0,29.184.0,29.119.0,33.147.0,41.135.0"}
P.entries["item:cenarion-lunardust"] = {n="Cenarion Lunardust",s="Cenarion Lunardust är ett heligt pulver som Turak Runetotem skänker unga tauren-druider på Thunder Bluffs höjder. Det används för att väcka väktardjuret Lunaclaw vid en forntida Moonkin Stone på gränsen mellan Mulgore och The Barrens.",h="Cenarion Lunardust är ett heligt pulver som Turak Runetotem skänker unga tauren-druider på Thunder Bluffs...",kw={"kropp och själ","cenarion lunardust","druid of the claw","lunaclaw","lunardust","moonkin stone","turak runetotem"},ang={["class:Druid"]="För tauren-druider är pulvret den avgörande katalysatorn i övergångsriten som låser upp den forntida konsten att skifta gestalt till björn.",["race:Tauren"]="Pulvret knyter unga Shu'halo direkt till Cenarion Circles läror och visar hur deras gemenskap med naturen och Kalimdors vilda andar fördjupas."},sec={{t="En rit för kropp och själ",b="Cenarion Lunardust, som anförtros åt noviser redo att ta sin plats bland Druids of the Claw, bär Cenarion Circles välsignelser. När det strös över Moonkin Stone väster om Camp Taurajo kallar det lysande pulvret fram Lunaclaw, ett heligt djur som är satt att pröva novisen. Att besegra denna väktare prövar både fysisk styrka och andlig beslutsamhet och låter den unga druideleven ta till sig den kroppsliga och själsliga styrka som krävs för att anta björnens form."}},faq={{q="Vad används Cenarion Lunardust till?",a="Det strös över Moonkin Stone i kullarna mellan Mulgore och The Barrens, strax väster om Camp Taurajo. När pulvret används kallas Lunaclaw fram, ett mäktigt djur som noviser måste besegra för att bevisa sin styrka.",al={"vad gör lunardust","hur använder man cenarion lunardust","lunardusts syfte"}},{q="Vem ger ut Cenarion Lunardust?",a="Turak Runetotem, druidtränaren på Elder Rise i Thunder Bluff, ger pulvret till tauren-druider som genomgår prövningen för björnformen.",al={"vem ger lunardust","var får man tag på cenarion lunardust","turak runetotems pulver"}},{q="Vad händer om du förlorar ditt Cenarion Lunardust?",a="Om du förlorar pulvret eller misslyckas med prövningen mot Lunaclaw måste du återvända till Turak Runetotem på Elder Rise i Thunder Bluff för att få en ny påse.",al={"förlorat lunardust","behöver mer lunardust","var får man en till lunardust"}},{q="Varför måste en druid möta Lunaclaw?",a="Lunaclaw är stenens beskyddare och förkroppsligar balansen mellan fysisk styrka och inre beslutsamhet. Genom att utmana och besegra varelsen tar en blivande Druid of the Claw till sig lärdomarna om kropp och själ som krävs för att tygla den stora björnandens krafter.",al={"varför slåss mot lunaclaw","vem är lunaclaw","lunaclaws syfte"}}},fx={ca885fb9={q="Vad är Cenarion Lunardust?",a="Cenarion Lunardust är ett heligt pulver som tillverkas av Cenarions druider och anförtros endast åt dem som visat sitt engagemang. När pulvret strös över den uråldriga Moonkin Stone nära gränsen mellan The Barrens och Mulgore, kallar dess magi fram Lunaclaw. Då prövas om den unga druiden har den kroppsliga och själsliga styrka som krävs för att följa Kloens väg.",al={"vad är lunardust","cenarion lunardusts bakgrund","cenarion-pulver"}},d52557a0={q="Varför vill någon ha Cenarion Lunardust?",a="Bara blivande druider söker efter pulvret, eftersom det krävs för att kalla fram Lunaclaw vid Moonkin Stone. Utan det visar sig inte väktaren, och den som genomgår invigningen kan varken möta prövningen eller göra anspråk på den andliga styrka som krävs för att bli en sann Druid of the Claw.",al={"varför behövs lunardust","vem vill ha cenarion lunardust","varför används lunardust"}}},fp="18,173,24.371.0,36.197.0,36.138.0,49.126.0,31.232.0"}
P.entries["item:cenarion-moondust"] = {n="Cenarion Moondust",s="Cenarion Moondust är ett heligt pulver som anförtros nattalvdruider under deras prövningar för att bli Druider av Klorna. När det strös över den uråldriga Moonkin Stone i kullarna öster om Auberdine, lockar det fram Lunaclaw, grottans vilda väktare.",h="Cenarion Moondust är ett heligt pulver som anförtros nattalvdruider under deras prövningar för att bli...",kw={"auberdine","kropp och hjärta","cenarion moondust","druid av klorna","lunaclaw","mathrengyl bearwalker","moondust","moonkin stone"},ang={["class:Druid"]="För nattalvdruider markerar Cenarion Moondust det sista steget på vägen till att bli Druid av Klorna. Därefter väntar mästerskap i björnens form.",["race:NightElf"]="Pulvret speglar Cenarion Circles uråldriga traditioner, där naturdyrkan förenas med månritualer för att hedra Darkshores bestar."},sec={{t="Klons rit",b="Mathrengyl Bearwalker i Darnassus ger Cenarion Moondust till unga druider som ska genomgå sin sista prövning av hjärta och kropp. För att möta väktaren Lunaclaw och bevisa sitt värde måste den som prövas färdas till moonkinhålorna öster om Auberdine i Darkshore. När moondust strös över den uråldriga Moonkin Stone kallas besten fram för att pröva den som genomgår prövningen i strid. Då kan druiden ta till sig den bestående styrka som krävs för att anta björnens form."}},faq={{q="Vad används Cenarion Moondust till?",a="Nattalvdruider som genomgår sin prövning använder pulvret vid Moonkin Stone i Darkshore för att väcka Lunaclaw och prövas i sin styrka och beslutsamhet. Klarar de prövningen förtjänar de björnens kraft.",al={"användning av moondust","vad gör cenarion moondust","syftet med cenarion moondust"}},{q="Var använder jag Cenarion Moondust?",a="Det måste strös över Moonkin Stone i en moonkingrotta bland kullarna rakt öster om Auberdine i Darkshore.",al={"var använder man moondust","moonkin stones plats","var finns lunaclaws sten"}},{q="Vem ger Cenarion Moondust?",a="Mathrengyl Bearwalker, druidtränaren vid Cenarion Enclave i Darnassus, ger det till dem som visat sig redo för prövningen av kropp och hjärta.",al={"vem ger moondust","var får man tag på cenarion moondust","mathrengyl moondust"}},{q="Vad händer om jag tappar bort moondust?",a="Om moondust kommer bort eller förbrukas i ett misslyckat försök mot Lunaclaw måste den som genomgår prövningen återvända till Darnassus och be Mathrengyl Bearwalker om en ny prövning.",al={"tappat bort cenarion moondust","tappat bort moondust","få tillbaka moondust"}}},fx={d9963f3d={q="Vad är Cenarion Moondust?",a="Cenarion Moondust är ett heligt pulver som Cenarion Circle skänker till nattalvsdruider som söker sig till Druid of the Claw. Det bär vildmarkens välsignelse och används som en rituell ingrediens för att hedra och kalla fram uråldriga väktarandar.",al={"vad är cenarion moondust","cenarion moondusts bakgrund","månpulvrets syfte"}},["34087882"]={q="Varifrån kommer Cenarion Moondust, och vem tillverkade det?",a="Cenarion Circle bereder och förvarar pulvret i Darnassus. Det delas särskilt ut av druider som Mathrengyl Bearwalker till dem som visat vördnad och förtjänat rätten att genomgå deras heliga prövningar.",al={"vem tillverkade cenarion moondust","cenarion moondusts ursprung","varifrån kom månpulvret"}},["1f04d9d3"]={q="Varför behövs Cenarion Moondust?",a="Månpulvret behövs för att väcka Lunaclaw, det uråldriga odjur som vaktar Moonkin Stone i Darkshore. Lunaclaw antar bara utmaningen från den som strör detta heliga pulver över stenen, så att druiden kan bevisa sin kroppsliga och själsliga styrka.",al={"varför behöver jag cenarion moondust","varför används månpulver","vad är syftet med cenarion moondust"}}},fp="17,163,18.412.0,35.169.0,37.124.0,31.152.0,36.140.0"}
P.entries["item:centaur-bracers"] = {n="Centaur Bracers",s="I The Barrens tas Centaur Bracers av stupade Kolkar-krigare. Regthar Deathgate samlar in dem väster om The Crossroads som bevis på att centaurernas plundrare har röjts undan.",h="I The Barrens tas Centaur Bracers av stupade Kolkar-krigare.",kw={"the barrens","belöning","armband","centaur","the crossroads","deathgate","kolkar","regthar"},ang={["faction:Horde"]="Som medlem av Horden hjälper du till att skydda karavanernas försörjningsleder mellan Durotar, Mulgore och The Crossroads när du fäller Kolkar-plundrare.",["race:Tauren"]="Som tauren vet du att ditt folk i generationer har utsatts för brutala trakasserier från centaurklanerna. Att rensa bort Kolkar från The Barrens innebär hämnd och trygghet."},sec={{t="En blodig belöning",b="Kolkar-plundrare hotar Hordens fäste i The Barrens. Deras stupade krigare lämnar efter sig läder- och järnarmband, bevis på att en plundrare har avlägsnats från handelsvägarna. Regthar Deathgate, en orcisk spejare stationerad på höjderna väster om The Crossroads, erbjuder en stående belöning för dessa troféer för att hejda stammens aggression."}},faq={{q="Vem vill ha de här armbanden?",a="Regthar Deathgate, en Hordens spejare som slagit läger på en höjd väster om The Crossroads i The Barrens, tar emot armbanden som bevis på dina insatser mot de lokala Kolkar-centaurerna.",al={"vem tar emot centaur bracers","lämna in till regthar deathgate","vem köper centaur bracers"}},{q="Vilka centaurer bär de här armbanden?",a="Kolkar-krigare bär dessa armband när de strövar bland oaser och läger i norra The Barrens, däribland The Forgotten Pools och Lushwater Oasis.",al={"var kan man samla armband","kolkar-armband byte","källa till centaur bracers"}},{q="Varför vill Regthar att de samlas in?",a="Regthar vill minska Kolkars antal för att skydda Hordens territorium. Armbanden visar att krigare har dödat rövare i stället för att bara driva bort dem.",al={"varför samla armband","regthar deathgates motiv","syftet med centaur bracers"}}},fx={["2b8929fb"]={q="Vad är Centaur Bracers?",a="De här armskenorna är enkla rustningsdelar som kentaurkrigare bär runt om i The Barrens. De slits från dödade Kolkar-rövare och tjänar Horde som ett bistert, fysiskt bevis på en jägares framgång med att rensa ut deras aggressiva krigshärar.",al={"vad är centaur bracers","centaur bracers bakgrund"}},e954048b={q="Varifrån kommer Centaur Bracers?",a="De smids eller tillverkas av kentaurklanerna som strövar omkring på Kalimdors torra slätter, särskilt den fientliga Kolkar-stammen. Krigarna bär dem i strid som ett enkelt skydd mot sina många fienders klingor, pilar och klor.",al={"vem tillverkade centaur bracers","centaur bracers ursprung","varifrån kommer centaur bracers"}}},fp="15,178,15.344.0,24.167.0,34.145.0,37.157.0"}
P.entries["item:charred-horn"] = {n="Charred Horn",s="Charred Horns är de robusta, hettetåliga hornen som tas från unga chimaeror i Stonetalon Mountains bergsskrevor. De står emot hårda elementkrafter och är en viktig härdningskomponent vid specialiserad rustningssmide.",h="Charred Horns är de robusta, hettetåliga hornen som tas från unga chimaeror i Stonetalon Mountains...",kw={"charred horn","chimaera","eldhärdad ringbrynja","furen longbeard","stonetalon","stonetalon mountains"},ang={["class:Warrior"]="Furen Longbeard ber särskilt lovande krigare att hämta de här hornen runtom i Kalimdor och belönar deras farofyllda färd med skräddarsydd eldhärdad ringbrynja.",["profession:Blacksmithing"]="Hornen från dessa bestar visar prov på en ovanlig smidesteknik, där Kalimdors rovdjurs naturligt eldhärdade biologiska material används för att härda ringbrynjans länkar."},sec={{t="En sällsynt smideskomponent",b="Charred Horns tas från nykläckta och unga chimaeror som har sina bon på Stonetalon Mountains klippiga höjder. De är eftertraktade för sitt onaturliga motstånd mot eld och slag. Dvärgsmeden Furen Longbeard arbetar vid sin smedja i Stormwind och behöver en samling sådana horn för att tillverka eldhärdad ringbrynja. Tillsammans med giftiga spindelgaddar från Wetlands, flogiston från Razorfen Kraul och det galvaniserade hornet från en chimaeradrottning ger dessa förkalkade horn den grundläggande förstärkning som behövs för att tillverka en ovanligt slitstark skyddsrustning."}},faq={{q="Vilka varelser släpper Charred Horns?",a="De samlas in från nykläckta och unga chimaeror som hör hemma i den karga terrängen i Stonetalon Mountains i Kalimdor.",al={"var får man tag på charred horn","vem släpper charred horn","charred horn källa"}},{q="Vem vill ha hornen i Stormwind?",a="Mästersmeden Furen Longbeard ber om dem. Han använder deras eldhärdade egenskaper som råmaterial för att smida ett ovanligt tåligt ringbrynjeskydd för bröstet åt lovande krigare.",al={"vem använder charred horn","lämna in charred horn","furen longbeards horn"}},{q="Varför behöver Furen så många?",a="Furen behöver tolv Charred Horns för att få tillräckligt med råmaterial som härdats av värme för att förstärka ringarna och plattorna i sin eldhärdade ringbrynja ordentligt.",al={"varför 12 charred horns","charred horns användning"}},{q="Är de annorlunda än Galvanized Horn?",a="Ja. Charred Horns finns i mängd hos de mindre, yngre chimaerorna i Stonetalon, medan Galvanized Horn är en enda, mycket ovanligare trofé som tas direkt från en chimaeradrottning.",al={"galvanized horn jämfört med charred horn","skillnad mellan hornen"}}},fx={["785d7f85"]={q="Vad är Charred Horn?",a="Charred Horn är ett hårt, svartbränt horn från unga chimeror som strövar bland topparna i Stonetalon Mountains. Hornen härdas av det hårda bergsklimatet och odjurens elementära natur. De är ovanligt tåliga och därför ett eftertraktat råmaterial för särskilt smidesarbete.",al={"vad är charred horn","charred horns bakgrund","om charred horn"}}},fp="12,258,25.607.0,34.132.0,35.177.0,39.149.0,45.185.0"}
P.entries["item:chest-of-containment-coffers"] = {n="Chest of Containment Coffers",s="Chest of Containment Coffers innehåller förtrollade behållare som magiker använder för att fånga instabila magiska fenomen. Den är nödvändig utrustning för magiker som skickas ut för att undersöka och säkert fånga osynliga manaanomalier.",h="Chest of Containment Coffers innehåller förtrollade behållare som magiker använder för att fånga instabila...",kw={"anastasia hartwell","apothecarium","arkan anomali","inneslutningskista","magic quarter","reva"},ang={["class:Mage"]="Kistan innehåller nödvändiga fältredskap för magiker som lär sig hantera flyktiga arkaniska manifestationer och bevara levande exemplar för studier.",["race:Undead"]="Fördömda magiker använder de här kistorna för att säkra magiska anomalier nära Apothecarium utan att låta oprövade arkaniska krafter fördärva deras arbete."},sec={{t="Kärl för det osynliga",b="Magiska experiment och plötsliga planariska revor ger ofta upphov till flyktiga, osynliga anomalier som helt består av arkansk kraft. Vanliga fysiska burar kan inte hålla kvar varelser som enbart består av magi. Chest of Containment Coffers förser magiker med specialtillverkade, förtrollade kistor som kan fånga och hålla dessa kuvade varelser vid liv. Kistan står nära erfarna instruktörer som Anastasia Hartwell i Undercity och Jennea Cannon i Stormwind. Därifrån får noviserna utrustningen de behöver för att undersöka anomalier innan de kan destabilisera omgivningen."},{t="Rutiner för arkan inneslutning",b="När osynliga störningar uppenbarade sig i Algernon's shop i Apothecarium skickade de fördömda instruktörerna dit magiker med dessa kistor för att få kontroll över situationen. För att fånga en reva krävs en särskild skriftrulle som gör den synlig, besvärjelser som försvagar dess form och en kista från Chest of Containment Coffers att stänga in den i. När behållarna fyllts kan de fördömda forskarna säkert dissekera och studera fångarna, och avgöra om störningarna är slumpmässiga revor i Ley eller avsiktliga arkaniska angrepp."}},faq={{q="Vad finns i Chest of Containment Coffers?",a="Kistan innehåller specialtillverkade, tomma inneslutningskistor. Magiker hämtar dem för att säkra och fånga kuvade magiska varelser, som revor, under farliga fältundersökningar.",al={"vad innehåller kistan","inneslutningskistornas innehåll","kistans innehåll"}},{q="Var hittar du den här kistan?",a="I Undercity står den precis bakom magitränaren Anastasia Hartwell i Magic Quarter. En likadan kista finns också i Stormwind City, bakom Jennea Cannon i Wizard's Sanctum.",al={"var finns chest of containment coffers","var finns kistan med inneslutningskistor","var finns kistan"}},{q="Varför behöver magiker de här kistorna i stället för vanliga burar?",a="Varelserna som undersöks är revor som enbart består av ogripbar arkan energi. Vanliga material kan inte hålla kvar dem. Bara magiskt förtrollade inneslutningskistor kan fånga och stabilisera en arkan anomali.",al={"varför används kistorna","vad används kistorna till","hur fungerar kistorna"}},{q="Vad händer med kistorna när de har fyllts?",a="Fyllda kistor lämnas över till erfarna instruktörer för undersökning. De fångade varelserna analyseras för att ta reda på om den arkaniska störningen berodde på en naturlig reva eller ett avsiktligt angrepp från yttre krafter.",al={"vad händer med fångade revor","användning av filled containment coffer","varför fånga varelser"}}},fx={fa57c13a={q="Vad är Chest of Containment Coffers?",a="Det är en tung förrådskista som magikerlärare håller för att utrusta dem som undersöker magiska anomalier. Inuti finns en uppsättning förtrollade förvaringskistor som särskilt konstruerats för att binda och hålla oberäkneliga, icke-fysiska väsen som enbart består av arkan energi.",al={"vad är chest of containment coffers","chest of containment coffers","kista med förvaringskistor"}},c9b5ba3b={q="Varför vill Anastasia Hartwell att du tar med Chest of Containment Coffers?",a="Anastasia Hartwell har upptäckt osynliga magiska väsen som vandrar omkring i Algernon's alchemist shop i Apothecarium. Vanliga bojor kan inte hålla varelser som helt består av rå magi, så hon ger dig den här kistan med särskilt förberedda förvaringskistor för att fånga anomalierna levande och studera dem.",al={"varför ta med chest of containment coffers","varför behöver jag förvaringskistor","varför vill anastasia ha kistan med förvaringskistor"}}},fp="28,136,22.456.0,28.435.1,48.162.0,30.177.0,56.145.0,49.211.0"}
P.entries["item:chief-sharptusk-thornmantle-s-head"] = {n="Chief Sharptusk Thornmantle's Head",s="Chief Sharptusk Thornmantle's Head tas som ett bistert bevis på segern över ledaren för Bristleback quilboar, som hotar Red Cloud Mesa. Huvudet hämtas från djupet av Brambleblade Ravine och överlämnas till Brave Windfeather för att markera slutet på ett ihållande hot mot unga taurenkrigare.",h="Chief Sharptusk Thornmantle's Head tas som ett bistert bevis på segern över ledaren för Bristleback quilboar...",kw={"brambleblade","bristleback","huvud","mulgore","sharptusk","thornmantle","windfeather"},ang={["class:Hunter"]="För jägare är Sharptusk det ultimata bytet: en intelligent fiende som kan jaga tillbaka och förvandla en överlevnadskamp till ett verkligt prov på spårning och prickskytte.",["race:Tauren"]="Att ta huvudet av en mäktig motståndare är en viktig milstolpe för unga tauren och visar att de har beslutsamheten och skickligheten som krävs för att skydda sitt folks nygrundade hem."},sec={{t="Jaktens trofé",b="Taurenfolket håller sitt fridfulla hemland i Mulgore genom vaksamhet och styrka. Bristleback quilboar, som slagit sig ned i Brambleblade Ravine, har bedrivit en aggressiv kampanj mot stammarna i Camp Narache, påhejade av sin våldsamma hövding Sharptusk Thornmantle. Att skilja hans huvud från kroppen handlar inte om meningslös grymhet, utan ger ett slutgiltigt bevis på hans död och en tydlig varning till de överlevande quilboarstammarna som tränger in över mesans gränser."},{t="En jaktens prövning",b="Brave Windfeather kräver hövdingens huvud som en övergångsrit för unga jägare och försvarare av stammen. För tauren är mötet med en motståndare som är nog listig att slå tillbaka och organisera en hel krigshär en viktig prövning av stridsförmågan. När Sharptusks huvud överlämnas är prövningen avklarad, och den unga kämpen vinner anseende bland krigarna på Red Cloud Mesa."}},faq={{q="Varför vill Brave Windfeather ha Sharptusk Thornmantles huvud?",a="Brave Windfeather kräver otvetydiga bevis på att Bristleback quilboarhövdingen har fallit. Att ta med hans huvud visar att Sharptusk inte längre kommer att leda räder mot Camp Narache och signalerar till de kvarvarande quilboar att deras aggression kommer att mötas med beslutsam kraft.",al={"varför ta hans huvud","orsak till sharptusks huvud","windfeathers begäran om huvudet"}},{q="Vem var Chief Sharptusk Thornmantle?",a="Chief Sharptusk Thornmantle var ledare för Bristleback quilboar, som bodde i Brambleblade Ravine vid östra kanten av Red Cloud Mesa. Under hans befäl trakasserade och angrep Bristlebackfolket ständigt unga taurenkrigare.",al={"vem är sharptusk","sharptusk thornmantles bakgrund","quilboarhövding i mulgore"}},{q="Var får man tag på den här trofén?",a="Huvudet får du genom att döda Chief Sharptusk Thornmantle i hans provisoriska by, djupt inne i Brambleblade Ravine öster om Camp Narache.",al={"var hittar jag huvudet","sharptusks huvud plats"}}},fx={["27fbe344"]={q="Varifrån kommer Chief Sharptusk Thornmantle's Head?",a="Denna makabra trofé tas direkt från hövdingen för de Bristleback quilboar som håller till i Brambleblade Ravine, strax öster om Camp Narache. Sharptusk Thornmantle samlade sin provisoriska bosättning mot tauren från Red Cloud Mesa, vilket fick Braves att kräva hans avhuggna huvud som obestridligt bevis på att Bristleback-krigsinsatsen har krossats.",al={"ursprung för sharptusks huvud","var kom sharptusks huvud ifrån","vem har sharptusks huvud"}}},fp="34,219,18.341.0,20.326.0,66.221.0,36.193.0,30.145.0"}
P.entries["item:chok-sul-s-head"] = {n="Chok'sul's Head",s="Chok'sul's Head är ett makabert, fysiskt bevis på att Mo'grosh-ogreklanens hövding har dött. När det lämnas till Magistrate Bluntnose i Thelsamar säkrar det en officiell belöning från de lokala dvärgmyndigheterna.",h="Chok'sul's Head är ett makabert, fysiskt bevis på att Mo'grosh-ogreklanens hövding har dött.",kw={"chok'sul","chok'sul's head","loch modan","magistrate bluntnose","mo'grosh","ogre","stonewrought dam","thelsamar"},ang={["race:Dwarf"]="När Chok'sul röjs ur vägen minskar trycket på Ironforges lantliga bosättningar direkt, och viktiga samhällsbyggnader som Stonewrought Dam skyddas från brutal förstörelse."},sec={{t="Bevis på hövdingens fall",b="Ogrerna i Mo'grosh Stronghold utgör ett ständigt hot mot bosättningarna i Loch Modan och ligger bakom angrepp mot Thelsamar, utgrävningsplatserna och den livsviktiga Stonewrought Dam. Magistrate Bluntnose utlyste en belöning för odågan som tros samordna angreppen: Chok'sul. Med tanke på kaoset i de nordöstra kullarna kräver magistraten obestridliga bevis innan stadens medel betalas ut. Ogrhövdingens avhuggna huvud ger det makabra bevis som dvärgrådet behöver för att markera uppdraget som slutfört."}},faq={{q="Vem var Chok'sul?",a="Chok'sul var en ogrhövding stationerad i Mo'grosh Stronghold i nordöstra Loch Modan. Dvärgmyndigheterna tror att han låg bakom samordnade räder mot Thelsamar, Stonewrought Dam och närliggande utgrävningsplatser.",al={"vem är choksul","choksuls bakgrund","chok'suls identitet"}},{q="Varför vill Magistrate Bluntnose ha huvudet?",a="Magistrate Bluntnose utlyste en offentlig belöning för att Chok'sul skulle dödas, oavsett metod. Eftersom ogrernas räder har satt regionen under hård press kräver magistraten obestridliga bevis på hövdingens död innan ersättningen betalas ut ur Thelsamars kassakista.",al={"varför bluntnose vill ha huvudet","syftet med choksuls huvud","vem vill ha choksuls huvud"}},{q="Var verkade Chok'sul?",a="Chok'sul ledde sitt krigsfolk från Mo'grosh Stronghold, ett kraftigt befäst ogrfäste bland de klippiga kullarna i nordöstra Loch Modan.",al={"var finns choksul","mo'grosh strongholds plats","choksuls plats"}},{q="Vilka hot utgjorde Chok'sul mot regionen?",a="Man trodde att han samordnade aggressiva angrepp mot Thelsamar och närliggande dvärginfrastruktur, däribland Stonewrought Dam och lokala arkeologiska utgrävningsplatser.",al={"varför är choksul efterlyst","vad gjorde choksul"}}},fx={["8aed7d95"]={q="Varifrån kommer Chok'sul's Head?",a="Denna makabra trofé tas direkt från ogret Chok'sul i Mo'grosh Stronghold, beläget i Loch Modans nordöstra vildmark. Det är ingen artefakt eller tillverkad sak, utan själva krigshövdingens avhuggna huvud, taget av äventyrare som vill uppfylla den officiella belöning som Thelsamar utlyst.",al={"ursprung för choksuls huvud","var kom choksuls huvud ifrån","vem tillverkade choksuls huvud"}}},fp="15,160,29.440.0,17.195.0,44.216.0,27.97.0,45.137.0"}
P.entries["item:clarice-s-pendant"] = {n="Clarice's Pendant",s="Clarice's Pendant är ett litet minne som tillhör Clarice Foster, en odöd invånare i The Pools of Vision i Thunder Bluff. Det var en gång en gåva från hennes före detta make Yuriv, men smycket tjänar nu bara som en bitter påminnelse om en övergiven familj och en felriktad hängivenhet till Ljuset.",h="Clarice's Pendant är ett litet minne som tillhör Clarice Foster, en odöd invånare i The Pools of Vision i...",kw={"clarice foster","clarice's pendant","de fördömda","the sepulcher","silverpine forest","grav","tills döden skiljer oss åt","yuriv"},ang={["class:Paladin"]="Clarices förakt för Yurivs korståg påminner obehagligt om de personliga kostnaderna och splittrade hem som helig fanatism lämnar efter sig.",["race:Undead"]="Hänget lyfter fram tragedin och bitterheten som är vanlig bland de Fördömda, vars levande närstående ofta övergav dem för korståg som till slut inte skyddade någon."},sec={{t="En bitter gåva",b="Clarice's Pendant står för det splittrade mänskliga förflutna som är vanligt bland många av de Fördömda. Innan det tredje kriget slukade Lordaeron övergav Clarices make Yuriv henne och deras barn för att strida mot de odöda. Han förkunnade att hängivenheten till det Heliga Ljuset gick före allt annat. I stället för att rädda sitt hem dog Yuriv, och hans familj lämnades kvar för att till slut falla offer för just den Pestarmé han gett sig av för att bekämpa. För Clarice är hänget inget kärt minne, utan en förolämpande prydnad som symboliserar ett helt liv i skuggan av fanatism och plikt."},{t="Vid Yurivs grav",b="Clarice vill kapa de återstående känslomässiga banden till sitt tidigare liv och sin försummande make. Därför skickar hon en äventyrare för att lämna smycket direkt vid Yurivs grav i The Sepulcher. Graven är försummad och vandaliserad, begravd under ogräs och skräp. När hänget till slut läggs över kistans skulpterade händer blir ädelstenen märkbart matt och släcker den sista kvarvarande värmen från Clarices tidigare liv."}},faq={{q="Vem äger Clarice's Pendant?",a="Hänget tillhör Clarice Foster, en kvinna bland de Fördömda som bor i The Pools of Vision i Thunder Bluff. Hennes make Yuriv gav henne det medan hon levde, innan han drog ut i krig.",al={"vem tillhör hänget","vems hänge är det här","clarice foster"}},{q="Vem var Yuriv?",a="Yuriv var Clarices make medan hon levde. Han övergav Clarice och deras barn för att bekämpa det växande hotet från de odöda i det Heliga Ljusets namn. Han dog och begravdes i en försummad grav i The Sepulcher.",al={"clarices make","vem är yuriv","yurivs grav"}},{q="Varför vill Clarice göra sig av med hänget?",a="Clarice klandrar Yuriv för att ha satt sitt korståg och sin hängivenhet till Ljuset före henne och deras barn. Hans offer ledde inte till något: han dog ändå, och hon lämnades kvar för att till slut återuppväckas som odöd, det tillstånd han försökte utrota.",al={"varför kasta bort hänget","varför hatar clarice yuriv","clarice's pendant-uppdrag"}},{q="Vad händer när hänget läggs på Yurivs grav?",a="När hänget lämnas vid Yurivs grav uppfylls Clarices önskan att göra sig av med minnessaken och den smärtsamma anknytning den står för.",al={"vad händer vid yurivs grav","hänge på grav"}}},fp="17,220,14.487.0,25.379.1,27.175.0,14.199.0,48.241.0,57.110.1"}
P.entries["item:claw-key"] = {n="Claw Key",s="Claw Key är en av tre druidiska nycklar som gömts i Talon Den på toppen av Stonetalon Peak. Tillsammans med Barrow Key och Sleepers' Key krävs den för att låsa upp den förtrollade Talon Den Hoard.",h="Claw Key är en av tre druidiska nycklar som gömts i Talon Den på toppen av Stonetalon Peak.",kw={"barrow den","claw key","druidernas gömställe","gatekeeper's key","stonetalon peak","talon den","talon den hoard","the den"},ang={["class:Druid"]="Nyckeln har fått sitt namn efter de ikoniska Druids of the Claw och speglar de heliga traditionerna och skyddande besvärjelser som skapats av nattalvernas barrow-invånare.",["faction:Horde"]="Genom att förhöra tillfångatagna nattalver kan Horde kringgå druidernas uråldriga försvar och plundra de heliga artefakterna som förvaras på toppen av Stonetalon Peak."},sec={{t="Talon Dens skydd",b="Nattalvernas druider anlade Talon Den högt uppe på Stonetalon Peak som en fristad och förvaringsplats för mäktiga reliker. För att hålla skatterna säkra från inkräktare gömde de dem bakom ett flerskiktat säkerhetssystem. Själva skatten förseglades med tre olika förtrollade lås: Barrow Key, Sleepers' Key och Claw Key. Varje nyckel gömdes i ett särskilt druidiskt gömställe, utformat som en fackla, i barrow den slingrande tunnlar."},{t="Att bryta upp gömställena",b="Druiderna lämnade inte nycklarna obevakade eller lättåtkomliga. För att öppna gömstället där Claw Key finns måste du först skaffa Gatekeeper's Key, som ligger nära ingången till barrow den. När du har hämtat den är Claw Key en viktig del i att bryta druidernas försegling och göra anspråk på rikedomarna som gömts djupt inne i berget."}},faq={{q="Vad används Claw Key till?",a="Claw Key är en av tre nycklar som behövs för att låsa upp Talon Den Hoard, en skyddad stenkista i hjärtat av Talon Den på Stonetalon Peak.",al={"claw key användning","vad öppnar claw key","nyckel till talon den hoard"}},{q="Var hittar du Claw Key?",a="Den ligger gömd i ett druidiskt gömställe som förklätts till en fackla i Talon Dens tunnlar på Stonetalon Peak. För att öppna gömstället krävs Gatekeeper's Key från ingången till den.",al={"claw key plats","var finns claw key","hitta claw key"}},{q="Vilka andra nycklar behövs tillsammans med Claw Key?",a="För att låsa upp Talon Den Hoard måste du samla Claw Key, Barrow Key och Sleepers' Key, som alla finns i olika gömställen runt om i den.",al={"andra nycklar","talon den-nycklar","nycklar till den"}},{q="Varför gömde druiderna nycklarna?",a="Nattalvernas druider byggde Talon Den för att förvara mäktiga reliker utom nyfikna blickar. De använde ett komplicerat system med nycklar och dolda gömställen för att hålla inkräktare borta.",al={"varför nycklarna är gömda","talon den-historia"}}},fx={["31018164"]={q="Vad är Claw Key?",a="Claw Key är en av tre förtrollade nycklar tillverkade av nattalvernas druider från Stonetalon Peak. Den ligger inlåst i ett dolt gömställe i den underjordiska The Talon Den och utgör en viktig del av en sinnrik skyddsbesvärjelse som ska hindra obehöriga från att komma åt deras mest värdefulla skatter.",al={"vad är claw key","information om claw key","vilken sorts nyckel är claw key"}},e0ebbe01={q="Varifrån kommer Claw Key, och vem tillverkade den?",a="Nyckeln tillverkades av druiderna som grundade The Talon Den högt uppe på Stonetalon Peak. För att skydda sina reliker skapade de denna nyckel tillsammans med Barrow- och Sleepers-nycklarna och låste in den i ett skyddat gömställe som kräver Gatekeeper's Key för att öppnas.",al={"vem tillverkade claw key","claw keys ursprung","var kom claw key ifrån"}},["9663afaa"]={q="Varför vill någon ha Claw Key?",a="Claw Key eftersöks eftersom den krävs för att ta sig in i Talon Den Hoard. Druiderna låste in många mäktiga artefakter i grottans djup bakom tre särskilda nyckelhål, så att bara den som samlar alla tre nycklar kan göra anspråk på de gömda relikerna.",al={"varför hitta claw key","varför skaffa claw key","claw keys syfte i berättelsen"}}},fp="8,87,22.378.0,20.265.0,30.142.0,32.171.0,50.131.0,35.139.0"}
P.entries["item:cliffspring-river-sample"] = {n="Cliffspring River Sample",s="En glasflaska med grumligt, illaluktande vatten från foten av vattenfallet vid Cliffspring River i Darkshore. Provet samlades in åt Thundris Windweaver i Auberdine och utgör ett konkret bevis på en tilltagande korruption som hotar kustbosättningen.",h="En glasflaska med grumligt, illaluktande vatten från foten av vattenfallet vid Cliffspring River i Darkshore.",kw={"auberdine","blackwood","cliffspring","felwood","prov","thundris","flaska","vattenfall","windweaver"},ang={["class:Druid"]="Druider är särskilt lyhörda för balansen i naturliga vattendrag, så den onaturliga giftigheten i provet från Cliffspring är brådskande att undersöka och rena.",["race:NightElf"]="För nattalverna i Auberdine är all korruption av norra Kalimdors vatten ett allvarligt omen om den pågående förödelse som sprider sig från Felwood."},sec={{t="En förgiftad ström",b="Cliffspring River rinner ner från Darkshores karga östra höjder och forsar förbi gamla stenbroar innan den mynnar ut i havet vid Mist's Edge. På senare tid har flodens kristallklara vatten blivit smutsigt och synligt korrumperat. Thundris Windweaver fruktar att det giftiga vattnet snart ska förorena Auberdines kust och vattenförsörjning. Därför gav han resenärer i uppdrag att hämta ett vattenprov direkt från dammen under flodens nedre vattenfall. Provet bekräftar det värsta: en onaturlig förruttnelse driver stadigt nedströms mot kusten."},{t="Ekon från Felwood",b="Lokala Blackwood furbolgs bor längs stränderna uppströms och påverkas av det mörknande vattnet, men vattenprovet tyder på en mycket djupare sjukdom än enkelt stök från stammen. Thundris känner igen korruptionens vidriga natur och ser att den har sitt ursprung högt ovanför klipporna i öster, i Felwoods fördärvade vidder. Det förgiftade provet är ett tydligt bevis på att den demoniska sjukdom som plågar bergstopparna sipprar ner i Darkshores avrinningsområden. Auberdines försvarare måste därför förbereda ett aktivt motangrepp."}},faq={{q="Var samlas Cliffspring River Sample in?",a="Det hämtas från dammen under det första vattenfallet längs Cliffspring River, norr om Auberdine. Resenärer måste följa floden inåt land tills de når vattenfallet under en bro.",al={"var hämtar jag provet","cliffspring river plats","prov från vattenfallsdammen"}},{q="Varför behöver Thundris Windweaver det här vattnet?",a="Thundris fruktar att flodens förorening ska smutsa ner kustvattnen nära Auberdine. Genom att samla in och undersöka ett fysiskt prov kan han analysera förgiftningen och utforma en plan för att motverka den.",al={"varför samla in vattnet","thundris floduppdrag","syftet med flodprovet"}},{q="Vad får Cliffspring River att bli förorenad?",a="De korrumperade Blackwood furbolgs bor längs floden, men Thundris misstänker att det verkliga ursprunget ligger längre österut i Felwood, där den kvarvarande demoniska förödelsen sipprar in i bergens källflöden.",al={"vad förgiftade floden","varför är vattnet korrumperat","källan till flodens korruption"}},{q="Är Blackwood furbolgs ansvariga för giftet?",a="De förvärrar problemet längs flodstränderna, men de är inte grundorsaken. Furbolgs har själva fallit offer för den större korruption som sköljer ner från de fördärvade landen i öster.",al={"gjorde furbolgs det","blackwood furbolgs förgiftning","förgiftar furbolgs vattnet"}}},fx={["2e135e3b"]={q="Vad är Cliffspring River Sample?",a="Det är en flaska med illasmakande, korrumperat flodvatten som samlats i ett tomt provrör vid foten av vattenfallet längs Cliffspring River. Den är ett konkret bevis på att en otäck smitta sköljer nedströms genom Darkshore.",al={"cliffspring river sample","vad är cliffspring river sample","vattenprov från cliffspring river"}},["57059c85"]={q="Varifrån kommer Cliffspring River Sample?",a="Provet samlas från pölen nedanför Cliffspring Rivers första vattenfall, norr om Auberdine. Du hämtar själv det naturliga vattnet med ett Empty Sampling Tube, men dess onaturliga orenhet har sitt ursprung i korrumperande krafter uppströms som strömmar ned från Felwood.",al={"varifrån kommer cliffspring river sample","cliffspring river samples ursprung","vem gjorde cliffspring-provet"}}},fp="24,183,17.461.0,17.334.1,48.166.0,45.142.0,51.165.0,54.187.0"}
P.entries["item:cloth-request"] = {n="Cloth Request",s="På Canal Tailor and Fit Shop tar Rema Schneider emot Harlan Bagleys beställning på nytt tyg och stickade varor. Hans lager töms snabbt.",h="På Canal Tailor and Fit Shop tar Rema Schneider emot Harlan Bagleys beställning på nytt tyg och stickade...",kw={"canal tailor shop","cloth request","harlan bagley","rema schneider","påfyllning","stormwind"},ang={["faction:Alliance"]="Stormwinds invånare känner oro och förbereder sig för stridigheter, trots att regentskapet inte har gjort några officiella tillkännagivanden.",["profession:Tailoring"]="Beställningen pekar på Stormwinds textilhandel, där lokala tygmakare som familjen Schneider förser diversebutiker och klädbutiker med vävda varor."},sec={{t="Stor efterfrågan på slitstarka varor",b="Harlan Bagley ber Rema Schneider om en ny leverans av stickade plagg och tyg. Bagley nämner en plötslig och oroande ökning av handeln: stadsbor och resenärer köper rustningar och slitstarka kläder som om de förberedde sig för en brutal årstid. Rema förbryllas och känner sig på sin vakt inför rusningen. House of Nobles har inte utlyst något öppet krig, så Rema undrar varför stadsborna i tysthet rustar sig och om kronans ledare döljer oro."}},faq={{q="Vad är Cloth Request?",a="Cloth Request är Harlan Bagleys skriftliga beställning till Rema Schneider på nytt tyg och stickade plagg för att fylla på hans butik.",al={"vad är cloth request","föremålet cloth request","harlans beställningslapp"}},{q="Varför behöver Harlan Bagley mer tyg?",a="Bagleys verksamhet har varit ovanligt livlig. Stadsbor och resenärer har köpt stora mängder rustningar och slitstarka kläder, så hans lager har tömts.",al={"varför harlan behöver tyg","varför bagley har slut på varor","bagleys skäl till påfyllning"}},{q="Vart ska den här beställningen skickas?",a="Beställningen ska till Rema Schneider på Canal Tailor and Fit Shop, längs Stormwinds vattenvägar.",al={"vart lämnar jag cloth request","vem får cloth request","leverans av cloth request"}},{q="Varför köper folk i Stormwind så mycket rustningar och kläder?",a="Varken köpmän eller vanligt folk vet säkert. Rema Schneider tycker att den plötsliga rusningen är oroande och undrar om hovet döljer uppblossande fientligheter eller faror för allmänheten.",al={"varför köper folk rustningar","är stormwind i krig","rema schneiders misstankar"}}},fx={b4374b3c={q="Varifrån kommer Cloth Request, och vem skrev den?",a="Begäran är skriven av Harlan Bagley, en köpman i Stormwind. När affärerna plötsligt tar fart och invånarna köper slitstarka kläder och rustningar, skriver Bagley en beställning för att få ännu en leverans stickade kläder och hålla hyllorna fyllda.",al={"vem skrev cloth request","cloth requests ursprung","var kom cloth request ifrån"}}},fp="13,150,21.430.0,26.123.0,39.147.0,35.95.0,62.193.0"}
P.entries["item:cloven-hoof"] = {n="Cloven Hoof",s="Cloven Hoof är en mystisk relik som Galak-centaurstammen vaktar djupt inne i Thousand Needles. Den förvaras i en uråldrig, helig låga i Splithoof Hold och utstrålar en ovanlig övernaturlig energi som taurenlärda gärna vill förstå.",h="Cloven Hoof är en mystisk relik som Galak-centaurstammen vaktar djupt inne i Thousand Needles.",kw={"uråldrigt eldfat","cloven hoof","galak","rau cliffrunner","helig låga","splithoof crag","splithoof hold"},ang={["class:Shaman"]="Rituella inslag används för att säkert släcka magiska lågor och hämta förtrollade reliker. Det visar hur subtil andlig efterforskning kan vara i Kalimdor.",["race:Tauren"]="I generationer har de nomadiska tauren lidit under centaurernas obevekliga angrepp. Att avslöja ursprunget och de magiska hemligheterna bakom reliker som Cloven Hoof ger värdefull kunskap om deras historiska fiender."},sec={{t="En helig centaurrelik",b="Cloven Hoof förvaras i en uråldrig eldfat längst in i Splithoof Hold och är en av Galak-centaurernas mest värdefulla reliker. Artefakten är ständigt omsluten av magiska lågor. För att kunna hantera den måste man släcka elden en kort stund med välsignat vatten. Centaurernas samhälle är känt för sin brutalitet och splittring i våldsamma klaner, men deras vördnad för eldfatet tyder på en rituell betydelse med direkt koppling till deras ursprung. Taurenobservatörer som Rau Cliffrunner vid Freewind Post tror att den märkliga aura som strålar från hoven kan ge avgörande insikter om den ras som plågat Kalimdors slätter i generationer."}},faq={{q="Var förvaras Cloven Hoof?",a="Cloven Hoof ligger i en uråldrig eldfat längst in i Splithoof Hold, en grotta i Splithoof Crag norr om Freewind Post. Den vaktas noga av Galak-centaurernas elitkrigare.",al={"cloven hoof plats","var hittar man cloven hoof","relik i splithoof hold"}},{q="Varför vill Rau Cliffrunner ha Cloven Hoof?",a="Rau Cliffrunner vill studera artefakten för att lära sig mer om centaurernas ursprung och magi. Han känner en märklig energi från reliken och hoppas att den ska avslöja sedan länge dolda hemligheter om de fientliga klanerna.",al={"varför hämta cloven hoof","rau cliffrunner uppdrag","vem vill ha cloven hoof"}},{q="Hur hämtar man Cloven Hoof från eldfatet?",a="Reliken är omsluten av magisk eld och kan inte tas direkt. En flaska med särskilt vatten måste hällas i det uråldriga eldfatet för att tillfälligt släcka den heliga lågan. Då kan hoven snabbt tas innan elden flammar upp igen.",al={"hur hämtar man cloven hoof","släcka helig låga","användning av filled etched phial"}},{q="Vilka är Galak-centaurerna som vaktar den?",a="Galak-stammen är den främsta centaurfraktionen i de norra delarna av Thousand Needles. De har sitt fäste i Splithoof Crag och försvarar aggressivt sin heliga eld mot främlingar.",al={"galak-centaurer","centaurer i splithoof crag","vem vaktar lågan"}}},fx={b52742f5={q="Vad är Cloven Hoof?",a="Cloven Hoof är en mystisk, uråldrig relik som vördas av Galak-kentaurerna i Thousand Needles. Föremålet är inneslutet i en evig, helig låga djupt inne i Splithoof Hold och utstrålar en märklig, outredd energi som väcker taurenforskarnas starka nyfikenhet.",al={"vad är cloven hoof","cloven hoof-reliken","vad är hoven"}}},fp="11,183,22.497.0,30.156.0,46.192.0,50.207.0,38.178.0"}
P.entries["item:comar-s-heart"] = {n="Comar's Heart",s="Comar's Heart är en makaber ritualkomponent, utskuren ur Comar Villard, en trofast mänsklig vandrare som söker efter sin försvunna hustru i Wetlands träskmarker. Forsaken-krigslåses i Undercity söker efter denna relik av ren hängivenhet för att nära en succubus framkallningsriter.",h="Comar's Heart är en makaber ritualkomponent, utskuren ur Comar Villard, en trofast mänsklig vandrare som...",kw={"carendin halgar","comar villard","comar's heart","hjärtan av de rena","succubus","temple of the damned","undercity","wetlands"},ang={["class:Warlock"]="Att ta Comar's Heart visar demonologins kalla, pragmatiska grymhet: obefläckad dödlig dygd är bara ett lockbete för att dra en succubus i din tjänst.",["race:Undead"]="För Forsaken visar skördandet av hjärtat från en trofast mänsklig älskare den totala känslomässiga brytningen mellan de levande och de odöda i Lordaeron."},sec={{t="En renhetens ledstjärna",b="För att binda en varelse så nyckfull och rovgirig som en succubus måste krigslåsen locka demonen med sann renhet och hängivenhet. Carendin Halgars lärjungar i Undercity pekar ut Comar Villard som en av de få män med så obefläckad trohet. Medan oroligheterna svepte över Eastern Kingdoms vandrade Comar envist längs Wetlands regnvåta vägar, fast besluten att inte ge upp sökandet. Det är just denna orubbliga kärlek som gör honom till ett mål för slakt och förvandlar hans ännu bultande hjärta till det perfekta lockbetet för en demonisk tjänare."},{t="Förförelsens pris",b="För att få tag på hjärtat måste Forsaken-lärlingar färdas långt söderut genom omstridda områden, förbi Thandol Span och djupt in i alliansdominerade träskmarker. Organet förs tillbaka till Temple of the Damned tillsammans med Dalin's Heart. Det ser helt alldagligt ut, trots den djupa godhet som en gång drev dess ägare. Men för Nether är den kvarvarande dygden som strålar från Comars kött ett berusande lockbete, starkt nog att dra en succubus genom dimensionsslöjan och in i krigslåsens våld."}},faq={{q="Vem var Comar Villard?",a="Comar Villard var en hängiven människa som sökte efter spår av sin försvunna hustru i de farliga Wetlands. Hans oändliga kärlek och orubbliga vägran att ge upp hoppet gjorde honom känd som en verkligt godhjärtad man.",al={"vem är comar","comar villards bakgrund","varför döda comar"}},{q="Varför behöver krigslåsen Comar's Heart?",a="Krigslåsen i Undercity behöver hjärtat från en helt ren och hedervärd dödlig för att locka till sig och binda en succubus. Demonen dras naturligt till att korrumpera och festa på äkta dygd, vilket gör Comars orubbliga hängivenhet till ett oemotståndligt lockbete.",al={"varför behöver man comars hjärta","vad används comars hjärta till","succubus hjärtats bakgrund"}},{q="Var hittar man Comar Villard?",a="Han vandrar längs huvudvägen i norra Wetlands, strax söder om Thandol Span, som förbinder Arathi Highlands och Khaz Modan.",al={"comar villards plats","var är comar","hur hittar man comar"}},{q="Vem skickar krigslåsen för att hämta hjärtat?",a="Uppgiften tilldelas av krigslåstränarna i Undercity, under ledning av Carendin Halgar i Temple of the Damned, som en del av en lärlings ritualträning för att frammana en succubus.",al={"vem vill ha comars hjärta","vem ger hjärtan av de rena","carendin halgar hjärta"}}},fx={["7acb4df8"]={q="Vad är Comar's Heart?",a="Comar's Heart är bokstavligen hjärtat som skurits ut ur Comar Villard, en trofast mänsklig vandrare i Wetlands. Häxmästare värdesätter det som ett sällsynt exempel på oförstörd dygd, genomsyrat av trofasthet och evig kärlek.",al={"vad är comars hjärta","föremålet comars heart","comar's heart i berättelsen"}},a49b76cf={q="Varifrån kommer Comar's Heart?",a="Det tas direkt ur bröstet på Comar Villard, en man som söker igenom Wetlands förrädiska träsk efter varje spår av sin försvunna hustru. Det är ingen artefakt smidd med trolldom, utan ett dödligt organ vars rena hängivenhet gör det till en kraftfull ritualingrediens.",al={"varifrån kommer comars hjärta","vem skapade comars hjärta","comars hjärtas ursprung"}}},fp="13,171,18.440.0,22.444.1,22.165.0,35.135.0,29.133.0,40.183.0"}
P.entries["item:consecrated-rune"] = {n="Consecrated Rune",s="En Consecrated Rune är ett heligt, inskrivet föremål som ges till blivande dvärgpaladiner under deras träning i Coldridge Valley. Den fungerar som en första kallelse från Bromos Grummner, som uppmanar de nyblivna att inställa sig i Anvilmar och påbörja sin formella tjänst som Knights of the Silver Hand.",h="En Consecrated Rune är ett heligt, inskrivet föremål som ges till blivande dvärgpaladiner under deras träning...",kw={"anvilmar","bromos grummner","coldridge valley","consecrated rune","holy light","paladin","silver hand"},ang={["class:Paladin"]="För dvärgpaladiner innebär mottagandet av denna rune det formella steget in i Knights of the Silver Hands led under Bromos Grummners vägledning.",["race:Dwarf"]="Runan speglar hur mänskliga heliga traditioner har vävts in i dvärgarnas stridskultur, med rötter i den gemensamma alliansen och den ömsesidiga respekten mellan Ironforge och mänskligheten."},sec={{t="En kallelse till Silver Hand",b="Nybörjare bland dvärgpaladinerna som visar vad de går för i Coldridge Valley får en Consecrated Rune när de har visat grundläggande stridsförmåga. Runan är inskriven med heliga ord och välsignad av Holy Light, och kommer från Bromos Grummner, paladintränaren som håller till i Anvilmar. Dvärgar hyser stor respekt för Holy Lights traditioner, som deras mänskliga allierade har introducerat för dem. Att läsa runan är både en officiell kallelse och en symbolisk övergångsrit som bekräftar nybörjarens plats bland Knights of the Silver Hand."}},faq={{q="Vad används Consecrated Rune till?",a="Runan är en skriftlig kallelse avsedd att läsas av dvärgpaladiner under utbildning. Den uppmanar dem att söka upp Bromos Grummner i Anvilmar för att fortsätta sin paladinträning.",al={"consecrated rune syfte","vad gör runan","consecrated rune uppdragsföremål"}},{q="Vem skickar Consecrated Rune?",a="Den skickas av Bromos Grummner, dvärgarnas paladintränare som är stationerad i Anvilmar i Coldridge Valley.",al={"vem gav mig consecrated rune","runans ursprung","bromos grummner rune"}},{q="Varför följer dvärgpaladiner Silver Hands traditioner?",a="Dvärgarna lärde sig mycket om Holy Light och Silver Hands seder av mänskliga mentorer. De hyser stor vördnad för ordens historia, traditioner och tron på att en enda uppoffring kan förändra Azeroths öde.",al={"dvärgpaladin silver hand","varför är dvärgar paladiner","dvärgar och holy light"}}},fx={dda1df9e={q="Vad är Consecrated Rune?",a="Det är en runristad dvärgasten välsignad i det heliga Ljuset, skickad som en formell kallelse till novispaladinernas träning i Coldridge Valley. Dvärgar förenar runhantverk med heliga läror och använder sådana stenar för att förmedla högtidliga budskap och kalla de blivande Ljusets försvarare till sina mentorer.",al={"vad är consecrated rune","föremålet consecrated rune","vad betyder consecrated rune"}},["924bde77"]={q="Varför vill Bromos Grummner att du ska få Consecrated Rune?",a="Bromos Grummner skickar runan för att pröva om du är redo och visa dig vägen till Anvilmar för formell träning. Oro håller på att växa i Dun Morogh, och Knights of the Silver Hand behöver dugliga, disciplinerade händer som kan upprätthålla sin heliga plikt och skydda Azeroth från fara.",al={"varför consecrated rune","varför vill bromos ha consecrated rune","varför får jag consecrated rune"}}},fp="16,174,28.529.0,38.129.0,31.111.0,65.197.0"}
P.entries["item:console-key"] = {n="Console Key",s="Vid Venture Companys utgrävningsplats i The Barrens har Tinkerer Sniggles Console Key. Den låser upp huvudterminalen och gör att samophlange kan tas bort när apparaten har stängts av.",h="Vid Venture Companys utgrävningsplats i The Barrens har Tinkerer Sniggles Console Key.",kw={"the barrens","console key","kontrollkonsol","samophlange","tinkerer sniggles","venture company"},ang={["faction:Horde"]="Att ta Console Key från Tinkerer Sniggles hjälper till att störa Venture Companys exploaterande industriarbete i hjärtat av The Barrens.",["profession:Engineering"]="Venture Company använder specialtillverkade lås med nyckel för att skydda känsliga tekniska prototyper som samophlange från konkurrenter."},sec={{t="Säkra apparaten",b="Venture Company driver en industriell utpost i norra The Barrens. Dess ångdrivna maskiner är beroende av en anordning som kallas samophlange. Konsolen är låst för obehöriga, och endast Tinkerer Sniggles, platsens chefstekniker, bär Console Key. Nyckeln öppnar terminalhöljet så att maskineriet kan stängas av."},{t="Stäng av anläggningen",b="När extraventilerna har vridits och apparaten svalnat till stillestånd bryter Console Key de sista kretsarna. När den vrids tömmer den terminalens återstående ström och låser upp dess hölje, så att samophlange kan bändas loss från maskineriet."}},faq={{q="Vad låser Console Key upp?",a="Console Key låser upp huvudkonsolen vid Venture Companys maskineri i norra The Barrens. När maskineriet står stilla tömmer den terminalen på ström och blottar samophlange.",al={"vad används console key till","vad öppnar console key","användning av console key"}},{q="Vem har Console Key?",a="Tinkerer Sniggles bär Console Key. Ingenjören från Venture Company håller till i en hydda strax nordost om huvudkonsolens apparat.",al={"vem tappar console key","var får man tag på console key","tinkerer sniggles nyckel"}},{q="Varför är konsolen låst från början?",a="Venture Company låser terminalen för att hindra rivaler och oregerliga arbetare från att manipulera maskineriet eller ta värdefulla delar som samophlange.",al={"varför behöver jag en nyckel","varför är samophlange låst"}},{q="Kan du använda nyckeln innan du stänger ventilerna?",a="Använd Console Key när ventilerna har stängts och mätarna visar noll. Om du försöker använda den aktiva konsolen riskerar du ett mekaniskt bakslag.",al={"använd nyckeln först","kan jag bara låsa upp konsolen"}}},fx={["4424a0fd"]={q="Vad är Console Key?",a="Console Key är en mekanisk säkerhetsnyckel som innehas av Venture Companys uppfinnare, ansvarig för kontrollkonsolen i The Barrens. Den passar i det låsta höljet runt samophlange och ser till att bara behörig personal kommer åt den känsliga maskinen och terminalens inre delar.",al={"console key","vad är console key"}},["81c16021"]={q="Varför vill någon ha Console Key?",a="När apparaten har stängts av och strömmen runnit ur kontrollkonsolen förblir höljet låst. Du behöver Console Key för att låsa upp själva kontrollpanelen, det sista steget för att säkert kunna lossa och ta hand om samophlange från terminalen.",al={"varför skaffa console key","varför behöver jag console key","console keys syfte"}}},fp="11,193,22.339.0,21.240.1,33.191.0,28.132.0,45.155.0,52.131.0"}
P.entries["item:control-console-operating-manual"] = {n="Control Console Operating Manual",s="Vid Venture Company-anläggningen sydväst om The Sludge Fen vägleder Control Console Operating Manual arbetarna genom maskineriet. Den förklarar hur ventilerna ska stängas och samophlange-mekanismen kopplas ur.",h="Vid Venture Company-anläggningen sydväst om The Sludge Fen vägleder Control Console Operating Manual...",kw={"the barrens","kontrollpanel","goblinernas ingenjörskonst","driftmanual","samophlange","the sludge fen","venture company"},ang={["faction:Horde"]="Manualen ger Hordens utredare en inblick i Venture Companys invasiva industriella verksamhet i hela norra The Barrens.",["profession:Engineering"]="Manualen visar goblinernas ingenjörskonst: system med högt tryck och begränsad säkerhet, styrda av ett kaotiskt virrvarr av spakar och ventiler i stället för balanserade säkerhetsmekanismer."},sec={{t="Att tyda goblinernas maskineri",b="Sydväst om The Sludge Fen driver Venture Company en borrnings- och forskningsanläggning i norra The Barrens. Maskineriet kopplar samman mätare, trycksatta ventiler och mekanismer med en anordning som kallas samophlange. Utan rätt instruktioner kan arbete med de instabila reglagen orsaka ett farligt haveri eller låsa systemet. Manualen anger ventilsekvensen för att koppla ur kärnapparaten utan att utlösa ett explosivt haveri."}},faq={{q="Vad används Control Console Operating Manual till?",a="Control Console Operating Manual förklarar hur du använder Venture Company-konsolen sydväst om The Sludge Fen. Den vägleder dig genom stängningen av ventilerna så att samophlange kan kopplas ur.",al={"vad gör manualen","manualens användning","varför har jag en driftmanual"}},{q="Vad är en samophlange?",a="Inte ens forskarna utanför Venture Company förstår helt vad en samophlange gör. Den verkar vara en kärnmekanism konstruerad av gobliner och kopplad till borrning och industriarbete i The Barrens.",al={"vad gör samophlange","samophlange i berättelsen","vad är den här maskinen"}},{q="Vem skrev manualen?",a="Venture Company-teknikerna som ansvarade för forskningsutposten utarbetade manualen. Den skulle hjälpa arbetarna att använda konsolen och hålla trycknivåerna i dess reglerventiler på avsedda nivåer.",al={"vem gjorde manualen","manualens upphovsperson"}},{q="Vad händer om jag tappar bort manualen?",a="Konsolen har mätare och avläsningar som visar ventiltrycket. En skicklig äventyrare kan läsa av panelen och hantera brytarna utan att ha manualen till hands.",al={"borttappad manual","borttagen driftmanual"}}},fx={["4b9f7b43"]={q="Vad är Control Console Operating Manual?",a="Det är en instruktionsguide som hämtats från Venture Company och beskriver hur kontrollkonsolen fungerar vid deras forskningsanläggning sydväst om The Sludge Fen. Den förklarar hur deras maskiner fungerar, så att en tekniker säkert kan hantera ventilerna och koppla ur apparaten.",al={"vad är control console manual","control console manual","venture company-manual"}},["5e9de40e"]={q="Varför eftersöks Control Console Operating Manual?",a="Manualen beskriver de exakta momenten som krävs för att stänga av och koppla ur Venture Companys mystiska samophlange. Utan att tyda instruktionerna vore det nästan omöjligt att hantera konsolens oberäkneliga spakar, knappar och trycksatta kontrollventiler på måfå.",al={"varför vill man ha control console manual","varför behövs manualen","varför är manualen användbar"}}},fp="32,194,28.424.0,54.189.0,22.202.0,22.205.0,34.151.0"}
P.entries["item:corroded-shrapnel"] = {n="Corroded Shrapnel",s="Corroded Shrapnel består av taggiga metallfragment som sitter djupt inbäddade i de korrumperade treants i Stonetalon Mountains. Skrotet har bärgats från fallna väktare som Charred och Blackened Ancients och är fysiska bevis på den hemska beväpning som Venture Company använde under sin reträtt.",h="Corroded Shrapnel består av taggiga metallfragment som sitter djupt inbäddade i de korrumperade treants i...",kw={"charred ancient","corroded shrapnel","gaxim","kaela shadowspear","stonetalon","treant","venture company"},ang={["class:Druid"]="Att se Kalimdors majestätiska uråldriga väktare förvridas av industriell goblinammunition och variga metallskärvor påminner starkt om priset för tygellös exploatering av vildmarken.",["race:Gnome"]="Gaxims jakt på de besmittade splittren visar hur praktiskt och vetenskapligt gnomer angriper ekologiska avvikelser som förbryllar traditionella skogsväktare."},sec={{t="Spår av industriell förödelse",b="När Venture Company drevs tillbaka från lundarna i Stonetalon använde goblinerna brutala och vårdslösa ammunitionstyper för att täcka sin flykt. Splitter från dessa explosiva vapen slet sig in i dalens försvarande treants och bäddade in taggig metall djupt i deras bark och kärna. I stället för att läka föll de uråldriga väktarna långsamt offer för korruptionen. Deras trä svartnade och deras vrede vändes mot alla som klev in i dalen. Kaela Shadowspear söker de rostiga, besmittade fragment som bärgats från dessa sårade väktare, så att gnomingen Gaxim Rustfizzle kan analysera korruptionens exakta mekanismer."}},faq={{q="Varifrån kommer detta splitter?",a="Corroded Shrapnel bärgas från kropparna av korrumperade treants i Stonetalon Mountains, däribland Charred Ancients, Blackened Ancients och Vengeful Ancients.",al={"var hittar jag splitter","corroded shrapnel byte","vem släpper splitter"}},{q="Varför sitter splitter inbäddat i treants?",a="Venture Company avfyrade explosiv, taggig ammunition mot treants när skogens väktare reste sig för att driva bort goblinernas skogshuggare från dalen. Metallskärvorna fastnade i deras bark under striden och kom aldrig ut.",al={"hur hamnade splitter i treants","varför är treants fulla av metall"}},{q="Ligger splittren bakom korruptionen hos skogens uråldriga väktare?",a="Enligt Kaela Shadowspear tror gnomingen Gaxim att korruptionen som plågar treants är direkt kopplad till den hemska kemiska eller metalliska sammansättningen hos vapnen som de retirerande goblinerna använde.",al={"förorenade splitter treants","varför är treants arga"}},{q="Vem vill undersöka splittren?",a="Nattalven Kaela Shadowspear ber om ett prov så att hon kan lämna det till gnomuppfinnaren Gaxim. Han vill studera dess egenskaper för att avslöja vad som plågar treants.",al={"vem behöver splittren","lämna in splitter"}}},fx={["1f081bfa"]={q="Vad är Corroded Shrapnel?",a="Corroded Shrapnel består av taggiga metallbitar som lämnats kvar av goblinernas vapen. Dessa rostiga, nedbrutna bitar av sprängammunition sitter djupt inbäddade i ärrad bark på Stonetalon-träden och tros bära på ett kvardröjande gift eller en otäck smitta som drabbar skogens väktare.",al={"vad är corroded shrapnel","corroded shrapnel i berättelsen","föremålet corroded shrapnel"}}},fp="17,185,27.497.0,35.141.0,44.188.0,63.159.0,34.152.0"}
P.entries["item:corrupt-manifestation-s-bracers"] = {n="Corrupt Manifestation's Bracers",s="Besudlade armskenor ligger vid Silverpine Forests kust, kvarlevor efter en förvriden vattenelementar. Schamanlärlingar hämtar dem under Call of Water och kastar dem i Brazier of Everfount tillsammans med rent vatten för att rena helgedomen och kalla fram en ren vattenande.",h="Besudlade armskenor ligger vid Silverpine Forests kust, kvarlevor efter en förvriden vattenelementar.",kw={"brazier of everfount","call of water","corrupt manifestation's bracers","shamanuppdrag","silverpine forest","vattenelementar"},ang={["class:Shaman"]="Som schaman är det sista provet i Call of Water att hämta och rena armskenorna. Det bevisar att du kan lugna och återställa förvridna element."},sec={{t="Ett renande offer",b="Pestens plåga nådde Lordaerons andar. Längs Silverpine Forests dimhöljda kust, väster om The Sepulcher, föll en helig vattenhelgedom offer för förvridning. Dess vattenmanifestation blev en aggressiv skugga. Schamanlärlingar måste besegra den och hämta dess armskenor. Vid Brazier of Everfount kastar de banden i lågorna tillsammans med rent vatten, häver förvridningen och kallar fram en obefläckad vattenande."}},faq={{q="Vad används armskenorna till?",a="Armskenorna kastas i Brazier of Everfount tillsammans med rent vatten under en reningsrit. Riten driver bort förvridningen från Silverpine-helgedomen och kallar fram en ren vattenande.",al={"vad gör armskenor","armskenor till call of water","användning av korrumperade armskenor"}},{q="Var kommer armskenorna ifrån?",a="Armskenorna kommer från en Corrupt Minor Manifestation of Water nära en besudlad elementarhelgedom vid Silverpine Forests kust, väster om The Sepulcher.",al={"var får jag tag på armskenor","var finns den korrumperade manifestationen"}},{q="Varför blev vattenelementaren korrumperad?",a="Pesten och de mörka krafterna som hemsökte Lordaeron förvrängde elementaren och skilde de lokala andarna från schamanernas gemenskap.",al={"varför är vattnet besmittat","vattenkorrumpering i silverpine forest"}}},fx={["0d8aeb2f"]={q="Vad är Corrupt Manifestation's Bracers?",a="Dessa armskenor är fysiska lämningar knutna till en korrumperad Minor Manifestation of Water som finns längs Silverpine Forests förgiftade kust. Liksom många elementarvarelser bundna till det dödliga planet bär den armskenor som förankrar och formar dess vattenkropp. Även efter att varelsen besegrats behåller armskenorna andliga rester av elementarens korrumperade existens, vilket gör dem till viktiga katalysatorer för reningsritualer.",al={"vad är corrupt manifestation's bracers","corrupt manifestation bracers","vad är det här för armskenor"}}},fp="31,264,20.421.0,32.182.0,31.147.0,43.130.0"}
P.entries["item:corrupted-brain-stem"] = {n="Corrupted Brain Stem",s="Corrupted Brain Stems är biologiska prover som samlats in från de förvridna naga och satyrer som lever i Blackfathom Deeps och längs Ashenvales kust. Gershala Nightwhisper i Auberdine vill studera de fysiska deformiteter som hänsynlös magisk korruption har orsakat. Genom att undersöka dessa hjärnor hoppas Night Elf-lärda förstå och kanske förhindra att blood elves drabbas av samma öde.",h="Corrupted Brain Stems är biologiska prover som samlats in från de förvridna naga och satyrer som lever i...",kw={"ashenvale","auberdine","blackfathom deeps","corrupted brain stem","gershala nightwhisper","naga","forska om korruptionen","satyr"},ang={["faction:Alliance"]="Alliance-spejare som skickas till Ashenvale trotsar djupen i Blackfathom för att hjälpa Auberdines lärda förstå de växande hoten över hela Azeroth.",["race:NightElf"]="För Night Elf är insamlingen av dessa kvarlevor en dyster påminnelse om folkets tragiska historia och de monstruösa följderna av okontrollerat bruk av arkansk magi och felmagi."},sec={{t="Förvandlingens anatomi",b="Satyrerna och naga i Kalimdor är levande vittnesbörd om förbjuden magis och demoniska pakters förvridande kraft. För länge sedan förvandlades hänsynslösa kaldorei highborne oåterkalleligt till ormlika vattenbestar och demoniska, hornbeklädda vidunder. Hjärnstammarna som samlats in från dessa varelser uppvisar omfattande fysiska mutationer och ger direkta anatomiska bevis för hur djupt korrumperande energier tränger in i nervsystemet hos varelser som en gång var alver."},{t="Gershalas varning",b="I kustbosättningen Auberdine följer Night Elf Gershala Nightwhisper de oroande ryktena om blood elves i Eastern Kingdoms. Hon fruktar att deras flört med demonisk trolldom ska skapa ännu en generation monster på Azeroth och skickar därför äventyrare till Blackfathom Deeps. Genom att dissekera vävnad från både naga och satyrer hoppas forskaren kartlägga den magiska förfallsprocessen innan ännu en alvkultur går förlorad."}},faq={{q="Vilka varelser ger en Corrupted Brain Stem?",a="De samlas in från naga och satyrer i Blackfathom Deeps och längs Ashenvales omgivande stränder, däribland Blackfathom-orakel, havshäxor och Fallenroot-satyrer.",al={"vem släpper hjärnstammar","corrupted brain stem byte","var får man hjärnstammar"}},{q="Vem vill ha hjärnstammarna, och varför?",a="Gershala Nightwhisper, som finns i hamnstaden Auberdine i Darkshore, ber om dem för att bedriva anatomisk forskning om magisk korruption.",al={"vem behöver corrupted brain stem","gershala-uppdrag","lämna in hjärnstammar"}},{q="Vad hoppas Night Elf lära sig av dessa prover?",a="Gershala fruktar att blood elves bruk av demonisk magi ska förvandla dem till monster, likt hur de forntida highborne blev naga och satyrer. Genom att studera dessa hjärnstammar kan man se hur demoniska energier förändrar alvers biologi.",al={"varför studera naga och satyrer","korruptionens historia och forskning","blood elves koppling"}},{q="Kan de hittas utanför grottorna i Blackfathom Deeps?",a="Ja. Vissa Fallenroot-satyrer och Blackfathom-tidsprestinnor som håller till utanför grottans ingång längs Ashenvales kust bär också på dem.",al={"utanför blackfathom","hjärnstammar i ashenvale","släpper fiender på ytan dem"}}},fx={["3ff1da04"]={q="Vad är en Corrupted Brain Stem?",a="En Corrupted Brain Stem är ett anatomiskt prov taget från satyrerna och naga som lever i och runt Blackfathom Deeps. Båda folken var en gång nattalver vars kroppar och sinnen förändrades våldsamt genom demoniska pakter eller uråldriga, skuggfyllda djup. Dessa hjärnstammar bär tydliga fysiska spår av den magiska förvrängningen och är därför värdefulla anatomiska studieobjekt för lärda som undersöker hur mörk trolldom förvrider dödligt kött.",al={"vad är corrupted brain stem","föremålet corrupted brain stem","corrupted brainstem i berättelsen"}},["53f0c38a"]={q="Varifrån kommer Corrupted Brain Stem?",a="Dessa hjärnstammar tas från Fallenroot-satyren och naga från Blackfathom som lever i de underjordiska grottorna och ruinerna kring Blackfathom Deeps längs Ashenvales kust. De är inga tillverkade föremål, utan biologiska rester från varelser som förvridits under årtusenden av korruption, ondskefull kraft och mörka förvandlingar.",al={"varifrån kommer corrupted brain stem","vem släpper corrupted brain stem","corrupted brain stem ursprung"}}},fp="20,297,25.315.0,18.366.0,44.145.0,36.99.0,58.168.0,60.126.0"}
P.entries["item:corrupted-kor-gem"] = {n="Corrupted Kor Gem",s="En Corrupted Kor Gem är en kraftfull magisk kanal, förvriden av nagornas mörka riter kring Blackfathom Deeps. Besvärjare åtrår sådana stenar för deras förmåga att lagra ren magisk kraft, men ädelstenen måste renas innan den kan användas i rättfärdigt hantverk.",h="En Corrupted Kor Gem är en kraftfull magisk kanal, förvriden av nagornas mörka riter kring Blackfathom Deeps.",kw={"blackfathom deeps","corrupted kor gem","kor-ädelsten","naga","rening","thundris windweaver","tidvattensprästinna"},ang={["class:Paladin"]="Paladiner som vill smida heliga vapen måste återfinna och rena en Kor Gem som bevis på sin förmåga att möta ondskan och förvandla mörker till rättfärdig styrka.",["race:NightElf"]="Nattalvslärda som Thundris Windweaver känner till faran med nagareliker som tränger in i Darkshore och skyddar kunskapen som krävs för att rena de forntida stenarna."},sec={{t="Kärl för besmittad kraft",b="Kor-ädelstenar har naturligt den sällsynta förmågan att fånga och hålla stora mängder magisk energi, vilket gör dem ovärderliga för trollkarlar och förtrollat smide. Längs kusten nära ruinerna av Blackfathom Deeps gör dock de bofasta nagorakelprästerna och tidvattensprästinnorna anspråk på dessa stenar för sina skumma ritualer. Med vidriga förtrollningar förvrider ormkönet stenen och fyller den med ondskefull, havsburen besmittelse. Denna infusion besmittar ädelstenens väsen, men dess inneboende kraft förblir stark och lockar dem som behöver enastående magiska fokuspunkter att skörda dem från nagorna."},{t="Renande och smide",b="En Corrupted Kor Gem måste renas innan Thundris Windweaver låter den föras till Jordan Stilwell. Nattalven i Auberdine renar bort nagornas onda magi och försäkrar paladinen om att ädelstenens kraft är intakt, redo för smedens ritual."}},faq={{q="Vad används en Kor Gem till?",a="Kor-ädelstenar fungerar som kraftfulla kanaler och reservoarer för magisk energi. Besvärjare använder dem för att hålla enorma kraftreserver till sina besvärjelser, medan skickliga smeder infogar dem i förtrollade vapen för att kanalisera magiska krafter.",al={"vad är kor-ädelstenar","kor-ädelstenens syfte","kor-ädelstenens historia"}},{q="Var hittar man Corrupted Kor Gems?",a="Corrupted Kor Gems bärs av naga-besvärjare, särskilt Blackfathom Tide Priestesses och Blackfathom Oracles, som håller till utanför och inne i de forntida ruinerna som leder till Blackfathom Deeps vid gränsen mellan Ashenvale och Darkshore.",al={"var hittar man corrupted kor gem","kor-ädelstenens plats","vem släpper kor-ädelsten"}},{q="Varför måste ädelstenen renas?",a="Nagorna mättar ädelstenarna med vidrig magi under sina ritualer. Om en besmittad ädelsten används i heligt hantverk kan smedjan eller bäraren besmittas. Därför måste en mästare över naturen eller ljuset, som Thundris Windweaver, driva ut ondskan innan ädelstenen smids in i ett vapen.",al={"rena kor-ädelsten","varför rena kor-ädelsten","är ädelstenen ond"}},{q="Bevarar reningen ädelstenens kraft?",a="Ja. Efter att ha renat ädelstenen försäkrar Thundris Windweaver paladinen om att dess kraft är intakt och att den bör fungera väl i Jordan Stilwells ritual.",al={"förstör reningen ädelstenen","svagare efter rening"}}},fx={["114a4618"]={q="Vad är Corrupted Kor Gem?",a="Corrupted Kor Gem är ett magiskt kärl som ursprungligen var avsett att lagra rå arkan energi eller besvärjelsekraft, men som förvridits av mörk magi. Nagabesvärjare har genomsyrat stenen med sin egen vidriga kraft och förvandlat en annars neutral ledare till en besudlad relik som sjuder av illvillig energi.",al={"vad är corrupted kor gem","information om corrupted kor gem","berätta om corrupted kor gem"}},["1218ae71"]={q="Varifrån kommer Corrupted Kor Gem, och vem skapade den?",a="Kor-gemmer skapades ursprungligen som ledare där besvärjare kunde lagra magisk energi, men dessa förvridna varianter förvaras och förändras av nagorna som lever kring Blackfathom Deeps i nordvästra Ashenvale. Nagaprästinnor och orakel har mättat gemmerna med sin egen avskyvärda magi och förvandlat dem till redskap för mörka ritualer.",al={"vem skapade corrupted kor gem","corrupted kor gem ursprung","varifrån kom kor gem"}},["1d7ce70e"]={q="Varför vill någon ha Corrupted Kor Gem?",a="Heliga paladiner söker efter gemmen på uppdrag av smeden Jordan Stilwell för att hjälpa till att smida ett rättfärdighetens vapen, men först måste Thundris Windweaver rena den från dess onda magi. Dess förmåga att hålla magisk energi gör den värdefull för ritualer när den väl har renats.",al={"varför skaffa corrupted kor gem","vem vill ha corrupted kor gem","varför behöver jag kor gem"}}},fp="17,198,24.403.0,25.253.1,27.137.0,35.208.0,29.156.0,42.122.0"}
P.entries["item:cougar-claws"] = {n="Cougar Claws",s="Cougar Claws skördas från slättlandspumor som strövar omkring på Mulgore centrala slätter. De är ett viktigt material i taurenfolkets rituella hantverk och förkroppsligar de vilda rovdjurens otämjda balans och naturliga vildsinthet.",h="Cougar Claws skördas från slättlandspumor som strövar omkring på Mulgore centrala slätter.",kw={"reningstotem","cougar claws","slättlandspuma","mulgore","mull thunderhorn","thunderhorn totem"},ang={["class:Shaman"]="Schamaner inser att de lokala rovdjurens essens har en obruten förbindelse med slätternas andar, vilket gör dem till oumbärliga kanaler för renande skydd och reningstotemer.",["race:Tauren"]="När unga tauren samlar in dessa klor lär de sig att jakt bygger på balans och andlig nödvändighet, i skarp kontrast till den vårdslösa förorening som goblinernas företag orsakar."},sec={{t="Ett kärl för naturlig balans",b="Slättlandspuman är en av Mulgore vidsträckta grässlätters främsta jägare och smyger sig instinktivt graciöst på sitt byte. Enligt taurenfolkets tradition är det inte fråga om vårdslös slakt eller troféjakt att ta klorna från ett sådant rovdjur, utan ett sätt att kanalisera djurets naturande. När goblinernas verksamhet börjar skända slätternas förfäders vatten ber Mull Thunderhorn unga jägare att samla in dessa klor tillsammans med prairie stalkers klor. Taurenfolket tror att de rena, ofördärvade rovdjursinstinkterna hos de inhemska djuren kan vävas in i en rituell totem som kan skura bort onaturliga gifter och mörk trolldom från den förgiftade Thunderhorn Water Well."}},faq={{q="Vad används Cougar Claws till?",a="Mull Thunderhorn använder dem tillsammans med stalker claws för att skapa Thunderhorn Cleansing Totem. Taurenfolket väver in de inhemska rovdjurens rena ande i rituella föremål för att rena vattenkällor som förgiftats av goblinernas industriella verksamhet.",al={"cougar claws användning","varför samla cougar claws","cougar claws syfte"}},{q="Var kommer Cougar Claws ifrån?",a="De tas från slättlandspumor som stryker omkring på The Rolling Plains i Mulgore, främst öster och väster om Bloodhoof Village.",al={"var hitta cougar claws","cougar claws källa","vem släpper cougar claws"}},{q="Varför behöver Mull Thunderhorn rovdjursklor för att rena en vattenkälla?",a="Taurenfolkets schamanistiska och druidiska traditioner vördar den renhet med vilken vilda djur jagar. Till skillnad från gobliner som utnyttjar och skändar jorden lever inhemska rovdjur i fullständig balans med landet, vilket gör deras essens idealisk för att motverka konstgjord fördärvning.",al={"varför rovdjursklor","varför mull behöver klor","rovdjursklor till totem"}},{q="Är Cougar Claws användbara till något annat?",a="Förutom att tillverka den rituella totemen för Thunderhorn Water Well har de ingen särskild användning och säljs vanligtvis till lokala handlare.",al={"andra användningar av cougar claws","sälja cougar claws"}}},fx={ad1b83a1={q="Vad är Cougar Claws?",a="Det är naturliga klor från tassarna på slättpumor som stryker omkring på Mulgore slätter. Taurenschamaner ser klorna som mer än bara troféer: de är symboler för den naturliga jakten och förkroppsligar den rena, obefläckade balans som råder bland vildmarkens bestar.",al={"vad är cougar claws","lore om föremålet cougar claws","vad är det här för klor"}}},fp="12,169,27.577.0,31.208.0,32.123.0,64.224.0,42.144.0"}
P.entries["item:courser-eye"] = {n="Courser Eye",s="Courser Eyes är biologiska ingredienser som skördas från de hornbärande coursers som strövar omkring i Stonetalon Mountains högland. Witch Doctor Jin'Zil i Malaka'jin söker en stor mängd för att tillreda en brygd som han hånfullt kallar skogsmagi.",h="Courser Eyes är biologiska ingredienser som skördas från de hornbärande coursers som strövar omkring i...",kw={"antlered courser","courser eye","skogsmagi","great courser","jin'zil","malaka'jin","stonetalon"},ang={["race:NightElf"]="Att slakta Stonetalon Mountains coursers för att förse en häxdoktors grymma experiment på tillfångatagna nattalver är ett angrepp på deras vördnad för naturen.",["race:Troll"]="Witch Doctor Jin'Zils grovhuggna användning av djurdelar speglar den mörkare, praktiska sidan av trollalkemi och mojo-hantverk som används mot Hordens fiender."},sec={{t="En trolls brygd",b="I den avlägsna utposten Malaka'jin tillreder Witch Doctor Jin'Zil olika stammixer för att bekämpa nattalverna som gör anspråk på området. Hjorthjärtan är inte ovanliga ingredienser i voodoo och folkal kemi, men Jin'Zil kräver trettio courser-ögon på en gång, långt fler än vad vanlig magi kräver. Tillsammans med fey dragon-fjäll, sav och morrhår från kattdjur utgör ögonen grunden för en dödlig brygd, avsedd för nattalvfångarna som sitter inlåsta i burar längst bak i hans håla."}},faq={{q="Var hittar man courser-ögon?",a="De skördas från olika coursers, både Antlered Coursers och Great Coursers, som hör hemma på de högre höjderna i Stonetalon Mountains, särskilt kring Mirkfallon Lake och Stonetalon Peak.",al={"platser med courser eye","var hittar man courser eye","hur får man courser eye"}},{q="Varför behöver Witch Doctor Jin'Zil så många ögon?",a="Jin'Zil hävdar att man aldrig kan ha för många ögon när man tillreder en ordentlig brygd. Han blandar dem med delar från traktens djurliv till brygden som han hånfullt kallar skogsmagi.",al={"varför trettio ögon","varför behöver jinzil ögon","vad gör jinzil med courser eyes"}},{q="Vad händer när Jin'Zil färdigställer sin skogsmagiska brygd?",a="Jin'Zil planerar att använda sin skogsmagiska brygd på nattalvfångarna som hålls i burar i hans grotta. Deras öde avslöjas när experimentet genomförs.",al={"resultat av jinzils skogsmagi","vad händer med fångarna i malakajin"}}},fx={["5cdf5ac9"]={q="Vad är Courser Eye?",a="Courser Eye är ett alkemiskt reagens som utvinns från de hjortliknande coursers som hör hemma i Stonetalon Mountains. För de flesta som bor i skogarna är de bara en del av den lokala faunan, men i händerna på en listig utövare blir dessa många ögon en råvara till kraftfulla brygder.",al={"vad är courser eye","föremålet courser eye","vad är courser eyes"}},a4aa468a={q="Varifrån kommer Courser Eye?",a="Dessa ögon samlas direkt från de behornade coursers och great coursers som betar i Stonetalon Mountains, särskilt kring Mirkfallon Lake och nära Stonetalon Peak. De är naturliga delar från bergens vilda bestar, inte tillverkade eller förtrollade artefakter.",al={"varifrån kommer courser eyes","vem skapade courser eye","courser eye ursprung"}}},fp="11,196,20.388.1,29.159.0,48.142.1,60.157.1"}
P.entries["item:covert-ops-pack"] = {n="Covert Ops Pack",s="Covert Ops Pack är en uppsättning specialutrustning för sprängningar och operationsscheman, sammanställd för Alliansens spionverksamhet i Stonetalon Mountains. Väskan är utformad för att slå ut Venture Companys rovlystna närvaro i Windshear Crag och gör det möjligt för agenter att utföra samordnat sabotage och säkra värdefull teknisk underrättelseinformation.",h="Covert Ops Pack är en uppsättning specialutrustning för sprängningar och operationsscheman, sammanställd för...",kw={"covert ops pack","cragpool lake","ng-5-sprängämnen","plan alpha","plan beta","venture company","windshear crag"},ang={["faction:Alliance"]="Den hemliga operationen som organiseras med det här paketet stöder direkt vaktposternas kamp mot kommersiell skövling i Stonetalon Mountains.",["profession:Engineering"]="Paketet står för gnomisk uppfinningsrikedom riktad mot goblinernas industri och använder specialanpassade NG-5-laddningar för att avslöja hemligheterna bakom Venture Companys maskiner."},sec={{t="Sabotage enligt plan",b="Covert Ops Pack har delats ut för hemliga anfall djupt inne på Venture Companys territorium och förenar rå sprängkraft med taktisk precision. Den innehåller färgkodade NG-5-sprängladdningar med tillhörande fjärrutlösare samt utförliga instruktioner med namnen Plan Alpha och Plan Beta. Strategin bygger på att utlösa kraftiga avledningsmanövrer vid viktig infrastruktur, nämligen sågverket vid Cragpool Lake och den östra gruvan. Medan gobliner skyndar sig för att släcka bränder och undersöka mekaniska fel kan en infiltratör smita förbi tumultet och stjäla viktiga dokument och scheman."},{t="Gemensamma intressen",b="Packens innehåll fyller två syften för Alliansen i Stonetalon. För nattalvernas vaktposter stör explosionerna och stölderna den skoningslösa kalhuggningen och exploateringen av den heliga bergssluttningen. För Alliansens uppfinnare är dokumenten själva den främsta belöningen. Återvinningen av Venture Companys ingenjörsscheman ger sällsynta insikter i goblinernas tunga maskiner och avslöjar mekaniska svagheter att utnyttja. Den låter också Alliansens ingenjörer anpassa industriella innovationer till sina egna konstruktioner."}},faq={{q="Vad finns i Covert Ops Pack?",a="Paketet innehåller två par färgade sprängladdningar: röda och blå NG-5-laddningar med tillhörande fjärrdetonatorer. Det innehåller också skriftliga uppdragsgenomgångar med detaljer om Plan Alpha och Plan Beta.",al={"innehåll i covert ops pack","vad innehåller paketet","föremål i covert ops pack"}},{q="Vad är sprängämnenas taktiska syfte?",a="NG-5-sprängämnena placeras ut på Venture Companys arbetsplatser för att skapa högljudda, våldsamma avledningsmanövrer. De är inte själva slutmålet, utan ska distrahera vakterna så att en agent kan infiltrera sågverket och gruvan oupptäckt.",al={"varför använda bomber","vad används ng-5-sprängämnen till","sprängning alpha beta"}},{q="Vilken underrättelseinformation är målet för operationen?",a="Uppdraget riktar in sig på Venture Companys ingenjörsplaner från sågverket söder om Cragpool Lake, följt av ledningens brev som förvaras inne i Windshear Mine, vid klippans östra ände.",al={"vad ska vi stjäla","paketets uppdragsmål","covert ops-mål"}},{q="Vem har nytta av materialet som återvinns med paketet?",a="Både nattalvernas vaktposter som försvarar Stonetalon och Alliansens ingenjörer har nytta av det. Vaktposterna ser avskogningsarbetet lamslås, medan Alliansens konstruktörer studerar de beslagtagna ritningarna för att hitta svagheter i Venture Companys skördare och samla idéer till sin egen teknik.",al={"vem vill ha venture-planerna","vem är paketet till för","vaktposternas hemliga operation"}}},fx={["8d787d42"]={q="Vad är Covert Ops Pack?",a="Covert Ops Pack är en särskild sabotagesats för infiltrationsuppdrag i Windshear Crag. Den innehåller färgkodade NG-5-sprängladdningar, matchande fjärrutlösare och detaljerade uppdragsplaner. De är avsedda att skapa distraktioner vid bestämda tidpunkter medan viktiga dokument från Venture Company hämtas mitt framför näsan på dem.",al={"vad är covert ops pack","information om covert ops pack","covert ops-utrustning"}},["23fc442d"]={q="Varifrån kommer Covert Ops Pack, och vem tillverkade den?",a="Paketet sätts samman av en alliansens uppfinnare som hjälper nattalvernas Sentinels i Stonetalon Mountains. Med en kombination av precisionsingenjörskonst och taktisk sprängning tillverkade uppfinnaren de instabila NG-5-laddningarna och fjärrutlösarna särskilt för att hjälpa agenter att slå till mot Venture Companys anläggningar.",al={"vem skapade covert ops pack","varifrån kom covert ops pack","skaparen av covert ops pack"}},ca775219={q="Varför behövs Covert Ops Pack?",a="Att anfalla befästa platser som Venture Companys sågverk och gruva vore självmord, eller skulle varna vakterna innan viktig information kan säkras. Paketet innehåller verktyg för att placera fjärrstyrda sprängladdningar och skapa kontrollerat kaos på en annan plats. Försvararna lockas bort så att du kan smyga in och hämta deras ingenjörsplaner och korrespondens.",al={"varför behöver jag covert ops pack","varför covert ops pack","covert ops pack syfte"}}},fp="15,188,18.422.0,25.368.0,35.149.0,47.150.0,45.173.0,58.223.0"}
P.entries["item:crate-of-crash-helmets"] = {n="Crate of Crash Helmets",s="En tung leverans med huvudskydd till dvärgarnas Siege Engine, på väg till The Shimmering Flats i Thousand Needles. De robusta hjälmarna behövs omgående av Brassbolts-bröderna för att skydda testförare mot hjärnskakningar från deras experimentella raketbilar.",h="En tung leverans med huvudskydd till dvärgarnas Siege Engine, på väg till The Shimmering Flats i Thousand...",kw={"crate of crash helmets","mirage raceway","raketbil","the shimmering flats","siege engine","thousand needles","wizzle brassbolts"},ang={["profession:Engineering"]="Varje ingenjör förstår den hårfina balansen mellan maximal framdrivning och katastrofalt haveri – och hur nödvändig tung rustning är när säkerhetsfunktioner kommer i andra hand.",["race:Gnome"]="För gnomen vid Mirage Raceway är hjärnskakningar hos piloter helt enkelt en del av verksamheten när de försöker överträffa rivalerna bland gobliner på saltslätten."},sec={{t="Säkerhet i hög fart",b="Ute över The Shimmering Flats bländande vita vidder testar gnomiska ingenjörer mekanisk framdrivning till det yttersta. Tyvärr för testpiloterna går de experimentella raketbilar som Brassbolts-bröderna konstruerat långt snabbare än de säkert kan styra. Eftersom förarna regelbundet råkar ut för våldsamma krascher och skallskador räcker vanliga lädermössor inte längre. För att deras skara av frivilliga våghalsar inte ska försvinna helt packas tåliga Siege Engine-hjälmar från dvärgarna och skickas över havet, så att förarna förblir vid medvetande och vid liv."}},faq={{q="Vad finns i Crate of Crash Helmets?",a="Lådan innehåller tunga Siege Engine-hjälmar från dvärgarnas militära förråd. De är byggda för att stå emot explosionsstötar och våldsamma fordonskollisioner och ger det kraftigaste huvudskyddet som finns för höghastighetstester.",al={"lådans innehåll","vilka hjälmar är det","typ av kraschhjälmar"}},{q="Vem behöver hjälmarna?",a="De skickas till Wizzle Brassbolts och hans bror vid Mirage Raceway i The Shimmering Flats. Deras vårdslösa fordonskonstruktioner slår gång på gång ut testpiloter, vilket gör att det finns ett akut behov av ordentligt huvudskydd.",al={"vem får hjälmarna","vem är lådan till","hjälmarnas destination"}},{q="Varför kraschar Brassbolts-bröderna så ofta?",a="Gnomisk fordonsdesign prioriterar rå fart och tekniska gränsöverskridanden framför stabil väghållning. Bröderna byggde en ovanligt snabb raketbil, men dess enorma hastighet gör kollisioner på saltöken nästan oundvikliga.",al={"varför kraschar de","problem med raketbilen","gnomiska racingkrascher"}},{q="Vart levereras hjälmarna?",a="Leveransen måste föras till The Shimmering Flats, den vidsträckta saltslätten i den sydöstra delen av Thousand Needles i Kalimdor.",al={"leveransplats","var finns wizzle","vart ska de här"}}},fx={["94078cd5"]={q="Varifrån kommer Crate of Crash Helmets, och vem tillverkade den?",a="Lådan packades och tillhandahölls av den dvärgiska ingenjören Pilot Longbeard i Dun Morogh. Longbeard samlade ihop ett förråd med stadiga hjälmar från dvärgarnas Siege Engines för att hjälpa sina gamla vänner, bröderna Brassbolt. De behöver desperat huvudskydd åt sina testpiloter ute i The Shimmering Flats.",al={"vem skapade crate of crash helmets","varifrån kom crate of crash helmets","crash helmets ursprung"}}},fp="22,262,21.584.0,42.227.0,24.218.0,49.232.0,38.147.0"}
P.entries["item:crate-of-horseshoes"] = {n="Crate of Horseshoes",s="I Elwynn är femtio järnhästsko beställda till Lakeshire.",h="I Elwynn är femtio järnhästsko beställda till Lakeshire.",kw={"crate of horseshoes","elwynn forest","goldshire","lakeshire","redridge","smith argus","verner osgood"},ang={["faction:Alliance"]="Kurirer som fraktar varor mellan Elwynn och Redridge håller rikets bräckliga handelsvägar öppna och avlägsna garnisoner utrustade, trots att Stormwind håller inne med militär förstärkning.",["profession:Blacksmithing"]="Leveransen visar den jämna efterfrågan på grundläggande smidesvaror längs gränsvägarna som förbinder städerna. Lakeshire är beroende av Goldshires städ för att hålla dragdjuren i arbete."},sec={{t="En leverans till Lakeshire",b="Smith Argus smidde femtio nya hästskor i Goldshire, packade sedan lådan och spikade igen den. Verner Osgood beställde dem till Lakeshire, där ständiga angrepp från gnoller och orcher gör att lokala hantverkare är beroende av Elwynn för viktiga metallvaror. Leveransen svarar mot Verners desperata behov av utrustning, och Argus bifogar en sträng faktura så att hantverkaren i Redridge vet att överlevnad vid gränsen har ett högt pris."}},faq={{q="Vad finns i Crate of Horseshoes?",a="Lådan innehåller femtio järnhästskor smidda av Smith Argus i Goldshire. En bifogad faktura kräver betalning av köparen.",al={"lådans innehåll","vad finns i lådan","hästskolådans innehåll"}},{q="Vem beställde lådan?",a="Verner Osgood beställde hästskorna. Han är handelsman och hantverkare i Lakeshire i Redridge Mountains och behöver dem för att hålla sitt arbete och de lokala dragdjuren igång.",al={"vem vill ha hästskorna","verners hästskor","lådans mottagare"}},{q="Vem tillverkade hästskorna?",a="Smith Argus, Goldshires smed i Elwynn Forest, smidde hästskorna, packade lådan och gjorde den klar för leverans.",al={"vem smidde hästskorna","smed i goldshire","smith argus"}},{q="Varför behöver Verner hästskor från Elwynn?",a="Fientliga Blackrock-orcher och gnoller belägrar Lakeshire, vilket lämnar gränsbosättningen isolerad och med brist på råvaror och handelsvaror. Lokala arbetare måste hämta grundläggande förnödenheter från tryggare bosättningar som Goldshire.",al={"varför redridge behöver hästskor","varför importera hästskor","lakeshires försörjningsproblem"}}},fx={["50a21bee"]={q="Vad är Crate of Horseshoes?",a="Crate of Horseshoes är en tung trälåda med femtio nyss smidda hästskor och en bifogad faktura. Smith Argus förberedde leveransen i Goldshire för att fullgöra en beställning från Verner Osgood, som desperat behöver nytt järn för att sko dragdjur och riddjur i närbelägna Lakeshire.",al={"vad är crate of horseshoes","lore om crate of horseshoes","vad ska hästskorna användas till"}}},fp="19,57,23.433.0,39.122.0,23.179.0,29.124.0,44.219.0"}
P.entries["item:crate-of-inn-supplies"] = {n="Crate of Inn Supplies",s="Crate of Inn Supplies är ett paket som packats i Coldridge Valley och ska till Thunderbrew Distillery i Kharanos. Bergspasset har tagits över av troggs, så de vanliga leveransvägarna är avskurna och värdshuset är beroende av förbipasserande resenärer som kan bära fram varorna.",h="Crate of Inn Supplies är ett paket som packats i Coldridge Valley och ska till Thunderbrew Distillery i...",kw={"anvilmar","coldridge","låda","frosthammer","hands","kharanos","springsprocket","förnödenheter","tannok","troggs"},ang={["race:Dwarf"]="Att bära de här förnödenheterna blir en ung dvärgs första uppdrag bortom Coldridge Valley, där hen trotsar det troggfyllda passet för att hjälpa sina fränder i Kharanos.",["race:Gnome"]="För nyanlända gnomer är det ett praktiskt sätt att vinna de lokala dvärgarnas välvilja att frakta Hands Springsprockets paket till dem som driver värdshusen i Dun Morogh."},sec={{t="Genom troggpasset",b="Vanligtvis går varor smidigt mellan Anvilmars lugna träningsområden och de livliga städerna i Dun Morogh. Men de senaste troggangreppen har stängt av Coldridge Pass och hindrat civila bud från att ta sig fram tills beväpnade bergsvakter kan rensa vägarna. Hands Springsprocket har packat den här tunga lådan, som innehåller viktiga värdshusförnödenheter som Tannok Frosthammer i Kharanos otåligt har väntat på under avbrottet."}},faq={{q="Vad finns i lådan?",a="Lådan innehåller vanliga värdshusförnödenheter som skickats från Coldridge Valley för att hålla värdshuset i Kharanos välfyllt för resenärer och lokalbor som söker värme.",al={"lådans innehåll","värdshusförnödenheternas innehåll","vad finns i lådan"}},{q="Vem skickar lådan till Kharanos?",a="Hands Springsprocket, som håller till nära Anvilmar, packar lådan och ber äventyrare på väg ut från Coldridge Valley att bära den över bergspasset.",al={"vem lämnar över lådan","hands springsprocket","avsändare"}},{q="Varför kunde inte det vanliga budet leverera den?",a="Troggs har tagit över Coldridge Pass, vilket gör resan för farlig för vanliga bud utan en fullständig eskort av bergsvakter. Äventyrare som är skickliga nog att kämpa sig igenom är värdshusets enda omedelbara hopp om att få varorna.",al={"varför kan inte hands leverera den","passet blockerat","varför anlita en äventyrare"}},{q="Vem tar emot förnödenheterna?",a="Tannok Frosthammer, värdshusvärdens assistent på Thunderbrew Distillery i Kharanos, tar emot paketet.",al={"vem får lådan","tannok frosthammer","värdshusvärd i kharanos"}}},fx={bc2f2ebd={q="Vad är Crate of Inn Supplies?",a="Det är ett paket med varor som Hands Springsprocket packade vid Coldridge Pass. Det ska till Thunderbrew Distillery och värdshuset i Kharanos. Eftersom troggar har spärrat vägen ut ur Coldridge Valley blev leveransen försenad tills en arbetsför resenär kunde bära den genom passet.",al={"vad är crate of inn supplies","uppdragsföremålet crate of inn supplies","vad är det här för låda"}},e676223e={q="Varför behövs Crate of Inn Supplies i Kharanos?",a="Tannok Frosthammer, som är assistent på värdshuset i Kharanos, har väntat på färska varor från Coldridge Valley medan nyheterna varit få på grund av troggupproret. När de vanliga kurirvägarna är avskurna behöver värdshuset få varorna genom passet för att kunna förse resenärer och lokalbor vid brasan.",al={"varför vill tannok ha lådan","varför behöver de förnödenheter till värdshuset","crate of inn supplies syfte"}}},fp="21,189,22.314.0,25.143.0,32.136.0,43.198.0,26.109.0"}
P.entries["item:crate-of-lightforge-ingots"] = {n="Crate of Lightforge Ingots",s="I Duskwood bär Crate of Lightforge Ingots hopp mot Morbent Fel. Den sällsynta, helgade metallen är på väg till Dwarven District i Stormwind.",h="I Duskwood bär Crate of Lightforge Ingots hopp mot Morbent Fel.",kw={"låda","dwarven district","grimand elmore","tackor","järn","ljussmittad","morbent fel","stormwind"},ang={["class:Paladin"]="Dessa tackor svarar på det heliga ljuset, vilket gör vapen smidda av dem till ett naturligt gissel för nekromantiker och deras odöda tjänare.",["profession:Blacksmithing"]="Att bearbeta ljussmittat järn är en sällsynt konst. Även Grimand Elmore kan gå flera år utan att hantera den heliga metallen."},sec={{t="En helig leverans",b="Duskwoods hopp vilar i den här lådan med ljussmittat järn. Den sällsynta metallen kan kanalisera helig kraft mot mörka väsen, medan Morbent Fels skydd avvärjer vanligt stål. Bara en hantverkare som kan dess härdning och vördar dess heliga natur kan bearbeta den."},{t="Stormwinds vapensmed",b="Grimand Elmore ska ta emot lådan i Stormwinds Dwarven District. Den skicklige dvärgiske vapensmeden har inte arbetat med ljussmittat järn på flera år, men går med på att smida det till ett helgat vapen. Dess kraft ska bryta igenom Morbent Fels försvar och fälla honom."}},faq={{q="Vad finns i den här lådan?",a="Lådan innehåller helgat ljussmittat järn, samlat till ett vapen som ska tränga igenom nekromantikern Morbent Fels magiska försvar.",al={"lådans innehåll","vad är ljussmittat järn","vad finns i lådan"}},{q="Vem ska ta emot den här lådan?",a="Lådan är avsedd för Grimand Elmore, en skicklig dvärgisk vapensmed i Stormwinds Dwarven District.",al={"vem ska jag lämna lådan till","lådans mottagare","vart ska lådan"}},{q="Varför behövs ljussmittat järn?",a="Morbent Fels skydd avvärjer vanligt stål. Ljussmittat järn kan kanalisera helig kraft mot mörka väsen.",al={"varför ljussmittat järn","varför inte vanligt järn","morbent fels svaghet"}},{q="Vem packade lådan?",a="Glorin Steelbrow packade det ljussmittade järnet du återfann i lådan för leverans till Grimand Elmore i Stormwind.",al={"vem packade tackorna","vem gav lådan"}}},fp="26,152,17.254.0,28.270.1,26.130.0,38.101.0,30.114.0,22.117.0"}
P.entries["item:crate-with-holes"] = {n="Crate With Holes",s="En portabel transportbehållare som goblinentreprenören Mebok Mizzyrix tillhandahåller i Ratchet. Lufthålen gör att den tryggt kan transportera en tränad Snufflenose Gopher som används för att spåra underjordiska kulinariska läckerheter i quilboarens fäste Razorfen Kraul.",h="En portabel transportbehållare som goblinentreprenören Mebok Mizzyrix tillhandahåller i Ratchet.",kw={"blueleaf tubers","crate with holes","mebok mizzyrix","ratchet","razorfen kraul","snufflenose gopher"},sec={{t="En sniffare i en låda",b="För att få tag på sällsynta Blueleaf Tubers i Razorfen Krauls taggiga djup förlitar sig goblinhandlaren Mebok Mizzyrix på tränade Snufflenose Gophers i stället för att gräva på måfå. Eftersom murmeldjur inte bara kan följa med en äventyrare till fots längs The Barrens dammiga stigar packar Mebok varje litet djur i en välventilerad trälåda. När lådan väl har burits in i quilboarens lya, genom fuktiga gångar fulla av rötter, öppnas den så att varelsen därinne kan följa sitt skarpa luktsinne till nedgrävda knölar."}},faq={{q="Vad finns i Crate With Holes?",a="Lådan innehåller en levande Snufflenose Gopher som tränats av Mebok Mizzyrix. Hålen i träet låter djuret andas under transporten genom The Barrens.",al={"vad finns i lådan","lådans innehåll","vad finns inuti"}},{q="Var får jag tag på Crate With Holes?",a="Du kan hämta en låda direkt från högen bredvid Mebok Mizzyrix i hamnstaden Ratchet, vid The Barrens östkust.",al={"lådans plats","var hittar man crate with holes","meboks låda"}},{q="Hur fungerar lådan inne i Razorfen Kraul?",a="Om du öppnar lådan inne i Razorfen Kraul släpps Snufflenose Gopher ut. När du styr den med en Snufflenose Command Stick använder murmeldjuret sitt skarpa luktsinne för att hitta nedgrävda Blueleaf Tubers under jorden.",al={"hur använder man crate with holes","använda lådan","kalla fram murmeldjur"}},{q="Varför är Blueleaf Tubers så svåra att hitta utan murmeldjuret?",a="Blueleaf Tubers växer djupt under jorden bland rötterna i Razorfen Kraul. De går inte att se med blotta ögat, men Snufflenose Gophers kan känna lukten av dem på femtio stegs avstånd.",al={"varför behövs murmeldjuret","hitta knölar","knölarnas plats"}}},fx={["39b6cc8f"]={q="Varifrån kommer Crate With Holes, och vem tillverkade den?",a="Lådan tillhandahålls av Mebok Mizzyrix, en driftig goblinhandlare med bas i hamnstaden Ratchet i The Barrens. För att skörda de värdefulla rötter som göms i quilboarens fäste Razorfen Kraul kom Mebok på ett sätt att tryggt transportera tränade snufflenose-gophers till platsen. Han slog hål i vanliga fraktlådor så att hans dyrbara små djur kunde andas under transporten.",al={"crate with holes ursprung","vem skapade crate with holes","varifrån kom crate with holes"}},["08415caf"]={q="Varför vill Mebok Mizzyrix ha tillbaka Crate With Holes?",a="Mebok förväntar sig att få tillbaka lådan tillsammans med sin kommandostav och de skördade Blueleaf Tubers, eftersom tränade snufflenose-gophers är en investering han inte har råd att förlora. Knölarna är en ytterst sällsynt delikatess runtom i världen. Utan hans tränade gophers och deras specialbyggda transportlådor är det praktiskt taget omöjligt att hitta dem djupt begravda i Razorfen Kraul.",al={"varför vill mebok ha lådan","varför vill någon ha crate with holes","crate with holes syfte"}}},fp="16,265,18.509.0,36.170.0,36.153.0,46.216.0,59.181.0"}
P.entries["item:crawler-leg"] = {n="Crawler Leg",s="Ett Crawler Leg är en avhuggen lem från någon av krabborna som strövar längs Darkshores dimhöljda kust. För de flesta resenärer är den värdelös, men de tåliga kitinlederna lämpar sig förvånansvärt väl för mekaniska improvisationer.",h="Ett Crawler Leg är en avhuggen lem från någon av krabborna som strövar längs Darkshores dimhöljda kust.",kw={"auberdine","buzzbox 827","crawler leg","darkshore","reef crawler","tide crawler","wizbang cranktoggle"},ang={["profession:Engineering"]="Wizbang Cranktoggles beslut att använda krabbappendage som provisoriska mekaniska hävstänger är typiskt för gnomisk improvisation i fält. Han kringgår vanliga metallstag till förmån för lokala resurser som finns till hands.",["race:Gnome"]="Bara en gnom skulle se en strand full av aggressiva kräftdjur och dra slutsatsen att deras avhuggna ben är de perfekta reservdelarna till ett känsligt telekommunikationsnät för långdistansbruk."},sec={{t="Gnomisk uppfinningsrikedom vid kusten",b="Krabborna i Darkshore, från pygmé-tide crawlers till större reef crawlers, är kända för sina robusta, tåliga skal. Night Elf-väktare bryr sig föga om de avfallna lemmarna från kustens skadedjur, men den excentriske gnomingenjören Wizbang Cranktoggle fann oväntad nytta i dem. Wizbang höll till i Auberdine och konstruerade sina prototyper till kommunikationsapparater för långdistansbruk, så kallade buzzboxes, för att drivas med improviserade lokala delar. De ledade segmenten och det tåliga kitinet i crawler legs ger den exakta mekaniska friktion och hävstång som krävs för att reparera Buzzbox 827, som står vid strandlinjen strax söder om staden."}},faq={{q="Vad används crawler legs till?",a="Crawler legs samlas in för att reparera Buzzbox 827, en experimentell kommunikationsstation som uppfinnaren Wizbang Cranktoggle placerat längs Darkshores kust, strax söder om Auberdine.",al={"crawler leg användning","varför spara crawler legs","buzzbox crawler leg"}},{q="Var kommer crawler legs ifrån?",a="De kan plockas från olika krabbarter längs stränderna i Darkshore, däribland Pygmy Tide Crawlers, Young Reef Crawlers, Encrusted Tide Crawlers och Reef Crawlers.",al={"crawler leg källa","vilka krabbor släpper crawler legs","var hittar man crawler leg"}},{q="Varför behöver en mekanisk buzzbox krabbben?",a="Wizbang Cranktoggle konstruerade medvetet sina maskiner för att använda delar från det närliggande djurlivet vid löpande underhåll i fält. Crawler legs styva leder och kitinsegment passar direkt in i buzzboxens kugghjul och återställer dess inre mekanismer.",al={"varför krabbor till maskin","buzzbox krabbben bakgrund","hur lagar crawler leg buzzbox"}}},fx={bab31e79={q="Vad är Crawler Leg?",a="Crawler Leg är en avhuggen lem från någon av de olika crawler-arterna som krälar längs Darkshores dimhöljda stränder. Med sina hårda kitinskal och tåliga leder är benen förvånansvärt robusta och passar bra för enkla, improviserade maskinreparationer.",al={"vad är crawler leg","föremålet crawler leg","om crawler legs"}}},fp="11,159,30.514.0,31.189.0,32.156.0,45.212.0"}
P.entries["item:creeper-ichor"] = {n="Creeper Ichor",s="Creeper Ichor är en sällsynt, ytterst giftig vätska som utvinns ur mosskrypare som lurar i skogarna i Hillsbrad Foothills. Royal Apothecary Society i Tarren Mill söker efter den som ett kraftfullt biologiskt ämne för att framställa nya farsoter mot de levande.",h="Creeper Ichor är en sällsynt, ytterst giftig vätska som utvinns ur mosskrypare som lurar i skogarna i...",kw={"apothecary lydon","creeper ichor","creepthess","elixir of suffering","hillsbrad foothills","mosskrypare","tarren mill"},ang={["race:Undead"]="För fördömda som är lojala mot sin sak innebär insamling av dödliga beståndsdelar som Creeper Ichor ett direkt stöd till Royal Apothecary Societys kampanj för att rensa Lordaeron från de levande."},sec={{t="Apotekarforskning i Hillsbrad",b="I Tarren Mill utför Apothecary Lydon experiment för att skapa nya dödliga gifter och utrota den omgivande människobefolkningen. Lydon avskyr kullarnas rena luft och livfulla natur och söker efter naturliga gifter och biologiska katalysatorer från det lokala djurlivet. De giftiga vätskorna från skogens jättespindlar, särskilt den svårfunna ichorn inuti fullvuxna mosskrypare, är en idealisk grund för hans Elixir of Suffering. Blandad med andra reagenser, som tungor från gråbjörnar, hjälper vätskan de fördömda att fullända sin dödliga alkemi."}},faq={{q="Vilka varelser ger Creeper Ichor?",a="Vätskan utvinns ur mosskrypare i Hillsbrad Foothills, däribland Giant Moss Creepers, Forest Moss Creepers, Elder Moss Creepers och den särskilt framstående spindeln Creepthess.",al={"var hittar man creeper ichor","vad släpper creeper ichor","varelser som släpper creeper ichor"}},{q="Varför behöver Apothecary Lydon vätskan?",a="Apothecary Lydon använder Creeper Ichor som ett viktigt dödande ämne i sin pågående alkemi­forskning för att brygga Elixir of Suffering, som ska sprida farsot bland och utrota de levande människorna i Hillsbrad.",al={"varför lydon vill ha ichor","elixir of suffering syfte","vad används creeper ichor till"}},{q="Varför är Creeper Ichor så svår att hitta?",a="Mosskrypare är vanliga i skogarna kring Tarren Mill, men användbara mängder av just denna ytterst giftiga ichor är sällsynta. Därför måste jägare döda många spindlar innan de hittar ett användbart exemplar.",al={"varför sällsynt","droppchans för creeper ichor"}}},fx={f45507cb={q="Vad är Creeper Ichor?",a="Creeper Ichor är en ytterst sällsynt kroppsvätska som utvinns från moss creepers som hemsöker Hillsbrad Foothills. Dessa jättelika spindeldjur stryker omkring i skogarna och på fälten runt Tarren Mill, men bara sällan ger någon av dem ifrån sig en så potent och ren vätska att den duger som alkemiskt reagens. För Royal Apothecary Society är denna giftiga essens ett förstklassigt dödligt ämne, uppskattat för sin naturliga giftighet och sin flyktiga potential i brygder.",al={"vad är creeper ichor","lore om creeper ichor","moss creeper-ichor"}},["3620ba85"]={q="Varifrån kommer Creeper Ichor?",a="Creeper Ichor tillverkas inte för hand, utan utvinns direkt från de olika moss creeper-arterna som hör hemma i Hillsbrad Foothills, däribland giant, forest och elder creepers samt ökända bestar som Creepthess. Det är en naturlig kroppsvätska som bildas i dessa jättelika rovdjursspindlar. För att hitta ett exemplar med en användbar, koncentrerad mängd måste man spåra upp och döda dussintals av dem ute i vildmarken.",al={"varifrån kommer creeper ichor","creeper ichor ursprung","vem skapade creeper ichor"}}},fp="13,216,32.463.0,35.179.0,42.206.0,42.193.0"}
P.entries["item:crocolisk-skin-classic"] = {n="Crocolisk Skin (Classic)",s="Crocolisk Skin kommer från de sega hudarna hos krokoliskerna som lever på öarna och i vattnen i The Loch i Loch Modan. Handlare och läderarbetare värdesätter dem för deras slitstyrka, och de betingar ett gott pris trots faran med att skaffa dem.",h="Crocolisk Skin kommer från de sega hudarna hos krokoliskerna som lever på öarna och i vattnen i The Loch i...",kw={"krokoliskjakt","crocolisk skin","the farstrider lodge","loch crocolisk","loch modan","marek ironheart","the loch"},ang={["class:Hunter"]="The Farstrider Lodge visar respekt för varje spårare som vågar vada ut till öarna och brotta ner en sprattlande krokolisk för att få dess hud.",["race:Dwarf"]="Loch Modans berömda krokolisker är ett välkänt lokalt prov på uthållighet för både bergsbestigare och skogsmän vid lodgen."},sec={{t="En farlig handel",b="The Lochs kalla vatten vimlar av aggressiva krokolisker som bygger sina bon på sjöns öar och stränder. Att jaga dem är ingen enkel uppgift, eftersom dessa ursinniga bestar har rakbladsvassa tänder och tjocka, tåliga fjäll som kan stå emot vårdslösa klingor. Trots farorna jagar jägare från The Farstrider Lodge ofta dessa varelser. Skräddare, läderarbetare och avlägsna handlare söker ständigt efter hudarna för att tillverka slitstarka kläder och skyddande rustningar, vilket gör ett knippe oskadade hudar till en värdefull handelsvara i trakten."}},faq={{q="Var kommer krokoliskhudar ifrån?",a="De samlas in från Loch Crocolisks och Large Loch Crocolisks som lever i vattnen och på öarna i The Loch i Loch Modan.",al={"var få tag på krokoliskhudar","källa till lochkrokoliskhud","vem släpper krokoliskhud"}},{q="Vem köper eller handlar med dessa hudar i Loch Modan?",a="Marek Ironheart, en erfaren dvärgjägare stationerad vid The Farstrider Lodge, samlar in dem tillsammans med krokoliskkött för att sälja till besökande handlare och hantverkare.",al={"vem vill ha krokoliskhudar","krokoliskhudar vid the farstrider lodge","marek ironhearts hudar"}},{q="Varför är dessa hudar eftertraktade?",a="Handlare värdesätter de sega, fjälliga hudarna för att tillverka slitstarka kläder och rustningar. Eftersom bestarna är vildsinta och svåra att döda ger hudar av god kvalitet en säker inkomst.",al={"vad används krokoliskhudar till","användning av krokoliskskinn","varför jaga krokolisker"}},{q="Anses det farligt att jaga krokolisker i The Loch?",a="Ja. Krokoliskerna är ökända för sin aggressivitet och har kraftiga käkar och sågtandade tänder som kan slita av lemmar. Lokala jägare som Marek Ironheart berättar ofta om möten där de nästan mist livet när de försökt hålla fast sitt byte.",al={"är lochkrokolisker farliga","fara med krokoliskjakt"}}},fx={c6e655b9={q="Vad är Crocolisk Skin?",a="Crocolisk Skin är det sega, fjälliga skinn som tas från crocolisks i vattnen och på öarna i Loch Modan. Det uppskattas för sin hållbarhet och särpräglade struktur och är ett värdefullt råmaterial för läderarbetare och skräddare som vill tillverka slitstarka kläder, skyddsutrustning eller specialrustningar.",al={"vad är crocolisk skin","crocolisk-skinn","vad är croc-skinn"}}},fp="24,200,17.375.0,35.119.0,45.136.0,30.141.0,55.209.0"}
P.entries["item:crocolisk-tear-classic"] = {n="Crocolisk Tear (Classic)",s="En Crocolisk Tear är ett märkligt alkemiskt reagens som samlas in från krokoliskerna i Loch Modans vatten. Chief Engineer Hinderweir behöver den för att framställa en neutraliserande blandning som kan oskadliggöra Dark Iron-sprängämnen.",h="En Crocolisk Tear är ett märkligt alkemiskt reagens som samlas in från krokoliskerna i Loch Modans vatten.",kw={"crocolisk tear","dark iron","hinderweir","loch modan","reagens","stonewrought dam","the loch"},ang={["profession:Engineering"]="Dvärgingenjörer som Chief Engineer Hinderweir använder ofta okonventionella alkemiska föreningar för att neutralisera avancerade sprängämnen när vanliga verktyg inte räcker till."},sec={{t="En märklig beståndsdel",b="Krokoliskerna i Loch är tåliga reptiler som hör hemma i Loch Modans tempererade vatten. Jägare uppskattar ofta deras skinn och kött, men Chief Engineer Hinderweir upptäckte en oväntad användning för deras sekret. Tillsammans med kraftfullt spindelgift och resonanta ogremineraler ger en krokolisks tår de särskilda kemiska egenskaper som krävs för att motverka de flyktiga Dark Iron-sprängladdningar som hotar Stonewrought Dam."}},faq={{q="Vad används Crocolisk Tear till?",a="Chief Engineer Hinderweir vid Stonewrought Dam behöver en Crocolisk Tear för att blanda en kemisk lösning som ska oskadliggöra sprängämnen utplacerade av Dark Iron-sabotörer.",al={"crocolisk tears användning","varför behöver jag crocolisk tear","vem vill ha crocolisk tears"}},{q="Var kan man samla in Crocolisk Tears?",a="De samlas in från Loch Crocolisks och Large Loch Crocolisks som lever i vattnet och på de grunda stränderna vid The Loch i Loch Modan.",al={"var droppar crocolisk tears","crocolisk tears plats","hur får man crocolisk tears"}},{q="Vilka andra material blandas med tåren?",a="Hinderweir blandar tåren med Lurker Venom från lokala skogsspindlar och en Mo'grosh Crystal från ogres i de nordöstra kullarna för att färdigställa desarmeringsmedlet.",al={"hinderweirs ingredienser","material för desarmering","vad mer behövs med crocolisk tear"}}},fx={["27a8e6d1"]={q="Vad är Crocolisk Tear?",a="Crocolisk Tear är en sällsynt alkemisk ingrediens som utvinns direkt från krokoliskerna i Loch Modans vatten. Trots det gamla talesättet om falsk gråt har dessa kroppsvätskor ovanliga egenskaper som gör dem användbara i särskilda blandningar, särskilt när de blandas med andra kraftfulla lokala ingredienser för att neutralisera flyktiga sprängämnen.",al={"crocolisk tear","vad är crocolisk tear","föremålet crocolisk tear"}}},fp="24,106,19.327.0,34.145.0,38.118.0,48.164.0"}
P.entries["item:crossroads-supply-crate"] = {n="Crossroads Supply Crate",s="Stulna förnödenheter till The Crossroads ligger utspridda bland Razormane-lägren i The Barrens. En plundrad karavan lämnade bosättningen med brist på mat, verktyg och andra nödvändigheter.",h="Stulna förnödenheter till The Crossroads ligger utspridda bland Razormane-lägren i The Barrens.",kw={"crossroads","crossroads supply crate","quilboar","razormane","förnödenheter till crossroads","the barrens","thork"},ang={["faction:Horde"]="The Crossroads förbinder Durotar, Mulgore och de norra vildmarkerna. Förnödenheterna hjälper till att skydda Hordes resor och logistik i Kalimdor."},sec={{t="Plundrade förnödenheter",b="Razormane quilboar plundrade en karavan med förnödenheter till The Crossroads. Lådorna släpades till närliggande läger bland snåren och jordhålorna. Thork, bosättningens befälhavare, vill få tillbaka dem innan utposten får farlig brist på mat, verktyg och andra nödvändigheter."}},faq={{q="Vad är de här försörjningslådorna?",a="Lådorna innehåller mat, verktyg och andra förnödenheter avsedda för Horde-bosättningen The Crossroads. En Razormane-attack spred ut dem efter att quilboar plundrat en försörjningskaravan på vägarna i The Barrens.",al={"förnödenheter till crossroads","vad finns i lådorna","information om supply crate"}},{q="Vem stal försörjningslådorna?",a="Razormane quilboar anföll karavanen och släpade lådorna till sina närliggande taggiga läger för att festa och samla på bytet.",al={"vem tog lådorna","vem överföll karavanen","quilboar-tjuvar"}},{q="Vem letar efter lådorna?",a="Thork, en orcisk officer stationerad vid The Crossroads, vill ha tillbaka de stulna lådorna så att garnisonen och lokalbefolkningen har tillräckligt med förnödenheter.",al={"vem vill ha lådorna","lämna in försörjningslådor","thorks förnödenheter"}},{q="Var finns lådorna?",a="Lådorna ligger utspridda i Razormane quilboar-läger i The Barrens med omnejd.",al={"lådornas platser","var hittar man försörjningslådor","platser för crossroads supply crate"}}},fp="23,164,20.277.0,29.198.0,28.126.0,32.129.0,29.84.0"}
P.entries["item:crude-flint"] = {n="Crude Flint",s="Crude Flint-bitar är grova stenar som Mosshide-gnollerna bär med sig genom Wetlands för att göra upp eld. Gnollerna använder dem för att tända brasor med nyhugget kärrvirke, något som gör den lokala beskyddaren Rethiel the Greenwarden rasande.",h="Crude Flint-bitar är grova stenar som Mosshide-gnollerna bär med sig genom Wetlands för att göra upp eld.",kw={"crude flint","eldförbud","gnoll","greenwarden","mosshide","rethiel","eldstål","wetlands"},ang={["class:Druid"]="Att förstöra levande växter enbart för gnollernas bekvämlighet strider direkt mot naturens principer. Därför är det en självklar plikt för varje vildmarkens beskyddare att beslagta och krossa dessa eldstål."},sec={{t="Eld i kärret",b="Dessa enkla, obearbetade eldstål ger Mosshide-gnollerna deras främsta sätt att skapa värme och tillaga kött i Wetlands fuktiga träsk. Tyvärr för träskets ekosystem fäller Mosshide levande träd för att hålla sina härdar och bål brinnande. Denna vårdslösa avverkning och förbränning av levande grenar väckte Rethiel the Greenwardens vrede. Han ser varje gnista som ett angrepp på naturens balans."},{t="Greenwardens vedergällning",b="Fast besluten att stoppa slakten av träskets träd ger Rethiel förbipasserande äventyrare i uppdrag att systematiskt ta ifrån Mosshide-flocken dess eldstål. Beskyddaren tänker inte använda de beslagtagna stenarna till något annat. Han ska krossa varenda bit till damm och kasta fragmenten i havet, så att gnollerna inte längre kan bränna Wetlands levande trä."}},faq={{q="Vad används Crude Flint till?",a="Mosshide-gnollerna använder Crude Flint som primitiva eldstål för att göra upp eld och få värme samt laga mat. Resande samlar in dem åt Rethiel the Greenwarden för att hindra gnollerna från att sätta eld på levande träd.",al={"crude flint användning","vad gör crude flint","crude flint syfte"}},{q="Vilka varelser bär Crude Flint?",a="De flesta vuxna och specialiserade medlemmar av Mosshide-gnollstammen bär dem, däribland Mosshide Brutes, Trappers, Fenrunners, Mistweavers, Mystics, Alphas och Gnawbone. De mindre Mosshide-gnollerna och blandrashundarna bär dem inte.",al={"vem släpper crude flint","var hittar man crude flint","vilka gnoller har eldstål"}},{q="Varför vill Rethiel att eldstålen förstörs?",a="Rethiel förfäras över att gnollerna fäller Wetlands levande träd och bränner veden för att få värme. Genom att förstöra deras eldstål och kasta skärvorna i havet hoppas han beröva dem förmågan att tända destruktiva eldar för gott.",al={"varför förstöra crude flint","rethiel eldstål anledning","orsak till eldförbud"}},{q="Är dessa eldstål värdefulla för hantverk?",a="Nej. Trots att de är mineraler är detta grova stenar som bara duger till att skapa en enkel låga. De saknar den renhet och form som smeder och ingenjörer behöver.",al={"kan jag använda crude flint i smide","är crude flint ett hantverksmaterial"}}},fx={b9abde94={q="Vad är Crude Flint?",a="Crude Flint är en grov, primitiv sten som används för att göra upp eld och som bärs av Mosshide-gnollerna i Wetlands. Med dessa enkla verktyg slår gnollerna gnistor för att tända sina lägereldar och bränner träskets levande grenar för att hålla sig varma.",al={"vad är crude flint","crude flint i historien","vad är det här för flinta"}},e1f52dc4={q="Var kommer Crude Flint ifrån, och vem har tillverkat den?",a="Dessa stenar formas genom knackning och bärs av Mosshide-gnollerna i Wetlands träskmarker. Nästan varje vuxen Mosshide-rövare, fällläggare och mystiker har en till hands som ett nödvändigt överlevnadsverktyg för att göra upp eld i det fuktiga träsket.",al={"vem tillverkade crude flint","var får gnollerna tag på crude flint","crude flints ursprung"}}},fp="11,169,20.257.1,29.299.1,29.185.1,34.208.0,43.222.1,39.128.0"}
P.entries["item:crystal-kelp-frond"] = {n="Crystal Kelp Frond",s="Murlocker för Crystal Kelp Fronds från havet till Crystal Lake i Elwynn Forest. William Pestle i Goldshire söker dem till en osynlighetsdryck.",h="Murlocker för Crystal Kelp Fronds från havet till Crystal Lake i Elwynn Forest.",kw={"crystal kelp","crystal kelp frond","crystal lake","goldshire","invisibility liquor","murlock","william pestle"},ang={["profession:Herbalism"]="Crystal Kelp Fronds är vattenlevande, till skillnad från örter som har rötter i jorden, och växer inte i vanliga ört-noder i Elwynn. Örtplockare och samlare måste lirka loss dem från lokala murlocker, som förvarar fronderna."},sec={{t="En sällsynt vattenlevande ingrediens",b="Crystal Kelp Fronds kommer från saltvattenhav, så att de finns i sötvattnet i Elwynn Forest är ovanligt. Murlocstammar längs Crystal Lakes stränder samlar in och förvarar fronderna av egna skäl. Alkemister värdesätter deras märkliga förmåga att förvränga synen. William Pestle i Goldshire använder dem som huvudingrediens i en osynlighetsdryck, tänkt att hjälpa förälskade att smita förbi familjens vakande ögon."}},faq={{q="Var växer crystal kelp naturligt?",a="Crystal kelp växer i saltvattenhav. Den hör inte hemma i sötvattensjöar, även om murlocker samlar in bitarna och bär dem till platser som Crystal Lake.",al={"var växer crystal kelp","crystal kelps ursprung","kelpens livsmiljö"}},{q="Varför har murlockerna vid Crystal Lake havstång?",a="Texten anger inget skäl till att murlockerna vid Crystal Lake har havstång. Den säger att de samlar in och förvarar fronderna av egna skäl.",al={"varför har murlocker kelp","murlockers skäl till kelp"}},{q="Vem vill ha Crystal Kelp Fronds i Goldshire?",a="William Pestle, en apotekare på Lion's Pride Inn i Goldshire, vill ha Crystal Kelp Fronds. Han använder dem för att brygga osynlighetsdryck åt Maybell Maclure, så att hon kan smita från familjens vingård för att träffa Tommy Joe Stonefield.",al={"vem behöver crystal kelp","william pestle och kelp"}},{q="Vilka egenskaper har crystal kelp?",a="Alkemister värdesätter Crystal Kelp Fronds för deras förmåga att förvränga synen. William Pestle använder dem i en osynlighetsdryck som ska hjälpa förälskade att passera obemärkta.",al={"kelpens effekter","vad gör crystal kelp"}}},fx={e295764f={q="Vad är Crystal Kelp Frond?",a="Crystal Kelp Frond är en bit kristallkelp, en sällsynt vattenväxt som hör hemma i havet. Trots att det främst är en marin växt samlas dessa fronder ibland in och förvaras av murlocer kring sötvatten som Crystal Lake. Alkemister värdesätter fronderna för deras kraftfulla, genomskinliga egenskaper, som kan användas för att brygga särskilda drycker som Invisibility Liquor.",al={"vad är crystal kelp frond","information om crystal kelp","vad är kristallkelp"}},["8bde59b0"]={q="Varför vill någon ha Crystal Kelp Fronds?",a="William Pestle, alkemisten i Goldshire, behöver kristallkelpfronder för att brygga en kraftfull Invisibility Liquor. Han tänker använda brygden för att hjälpa unga Maybell Maclure att obemärkt smita från familjens övervakade vingård och i hemlighet träffa sin förbjudna kärlek, Tommy Joe Stonefield.",al={"vem behöver kristallkelp","varför samla crystal kelp fronds","vad används kristallkelp till"}}},fp="18,149,22.409.0,39.159.0,51.136.0,43.232.1,42.162.0"}
P.entries["item:crystal-phial"] = {n="Crystal Phial",s="En fläckfri Crystal Phial som druïden Tenaron Stormgrip anförtrott åt unga nattalvseventyr i Shadowglen. Den används för att hämta heligt vatten från en närliggande månbrunn och inleder en serie riter som ska hedra och nära det växande världsträdet Teldrassil.",h="En fläckfri Crystal Phial som druïden Tenaron Stormgrip anförtrott åt unga nattalvseventyr i Shadowglen.",kw={"aldrassil","crown of the earth","crystal phial","månbrunn","shadowglen","teldrassil","tenaron stormgrip"},ang={["class:Druid"]="Druider vördar månbrunnar djupt och använder deras fridfulla egenskaper för att kanalisera naturens krafter och främja ny tillväxt utan att falla för den arkana trolldomens lockelser.",["race:NightElf"]="För unga kaldorei som tar sina första steg utanför Aldrassil är det en grundläggande övergångsrit att fylla ampullen. Den knyter dem direkt till Elunes vatten och deras folks återhämtning efter det tredje kriget."},sec={{t="Ett kärl för heliga vatten",b="Den här sköra glasampullen ges till novisa nattalver uppe på Aldrassil och har ett viktigt ceremoniellt syfte. Tenaron Stormgrip ger de unga beskyddarna i uppgift att bära den till månbrunnen strax norr om grenen och samla dess glödande vatten. Ampullen är enkelt utformad, men rymmer vatten som genomsyrats av den heliga arvet från Evighetens brunn. Att återvända med en Filled Crystal Phial är det första steget på pilgrimsfärden Crown of the Earth och lär unga kaldorei den sköra balansen mellan magi, historia och natur i deras nya öhem."}},faq={{q="Vad används Crystal Phial till?",a="Ampullen används för att samla välsignat vatten från månbrunnen strax norr om Aldrassil i Shadowglen. När den fyllts lämnas den tillbaka till Tenaron Stormgrip som en del av uppdraget Crown of the Earth.",al={"crystal phial syfte","användning av crystal phial","vad gör jag med ampullen"}},{q="Vem ger dig Crystal Phial?",a="Druiden Tenaron Stormgrip ger unga äventyrare den tomma Crystal Phial när han tilldelar dem deras första uppgifter uppe på Aldrassils stora gren.",al={"vem ger crystal phial","var får man crystal phial"}},{q="Varför är det betydelsefullt att samla månbrunnsvatten?",a="Månbrunnar innehåller helgade vatten som är knutna till Evighetens brunns väsen och Elunes nåd. Vattnet som hämtas i ampullen används för att förstå följderna av det tredje kriget och delta i ritualer som ska nära Teldrassil.",al={"varför månbrunnsvatten","månbunnsvattnets betydelse","månbrunnens syfte"}},{q="Vad händer när ampullen fyllts?",a="Den blir en Filled Crystal Phial. När du lämnar tillbaka den till Tenaron Stormgrip klarar du ditt första prov och får lära dig mer om hur världsträdet skapades och vårdas över hela Teldrassil.",al={"efter att ampullen fyllts","användning av filled crystal phial"}}},fx={d56aa813={q="Vad är Crystal Phial?",a="Crystal Phial är ett ömtåligt, specialtillverkat kärl som Tenaron Stormgrip tillhandahåller uppe på Aldrassil i Shadowglen. Det är utformat för att säkert transportera heliga vätskor, och dess rena kristallkonstruktion ser till att det magiska månbrunnsvattnet inte förorenas när du bär tillbaka det från skogens heliga helgedomar.",al={"vad är crystal phial","föremålet crystal phial"}},["819f868c"]={q="Varför vill Tenaron Stormgrip att Crystal Phial ska fyllas?",a="Tenaron Stormgrip ber dig fylla Crystal Phial som det första steget i din invigning i nattalvernas samhälle och den större världen. Månbrunnarna innehåller vatten som välsignats med Evighetens brunns arv. Väktare vördar dem som helgedomar åt Elune, och druider tar hand om dem. När du samlar vattnet får du lära dig om uppoffringarna vid Mount Hyjal och sätts på prov för att se om du är redo att förstå Teldrassils bräckliga tillstånd.",al={"varför fylla crystal phial","varför vill tenaron ha månbrunnsvatten","varför vill tenaron ha crystal phial"}}},fp="13,183,26.424.0,35.184.0,32.73.0,44.182.0,39.211.0"}
P.entries["item:crystalized-scales"] = {n="Crystalized Scales",s="Crystalized Scales är hårdnade, mineraliserade hudar som samlas in från basilisker i Kalimdors karga miljöer, som The Charred Vale och Thousand Needles. När de mals till ett fint pulver blir de ovanliga fjällen ett exotiskt magiskt reagens som trollkarlar i Stormwind eftertraktar.",h="Crystalized Scales är hårdnade, mineraliserade hudar som samlas in från basilisker i Kalimdors karga miljöer...",kw={"basilisk","the charred vale","collin mauren","crystalized scales","reagens","stonetalon mountains","stormwind","thousand needles"},ang={["class:Mage"]="För magiutövare visar dessa fjäll hur miljöpåverkan förändrar djurens magiska sammansättning och ger upphov till specialiserade reagenser för unika besvärjelseformler.",["faction:Alliance"]="Att skaffa dessa fjäll överbryggar det väldiga avståndet mellan Alliansens huvudstad Stormwind och Kalimdors otämjda vildmarker."},sec={{t="Ett sällsynt reagens från Kalimdor",b="Basilisker som uthärdar extrem hetta och aska utvecklar styva hudar täckta av kristaller. Det gäller särskilt dem som lever i The Charred Vale i Stonetalon eller på Thousand Needles skimrande saltslätter. Dessa Crystalized Scales bär på en latent magisk resonans och är därför mycket värdefulla för lärda magiker på andra sidan Stora havet, som experimenterar med ovanlig magi."},{t="Maurens magiska arbete",b="I det mänskliga kungariket Stormwind söker magikern Collin Mauren aktivt upp äventyrare på väg mot Kalimdors gränstrakter för att få tag på dessa fjäll. Mauren mal de kristallina mineralskikten till damm och använder det som ett viktigt reagens i nyskapade besvärjelser och sin egen magiska forskning."}},faq={{q="Vilka varelser ger Crystalized Scales?",a="De samlas främst in från basilisker som anpassat sig till karga områden, som de brända, svedda och svartnade basiliskerna i The Charred Vale i Stonetalon, samt saltstensbasiliskerna i Thousand Needles.",al={"var kan fjäll hittas","vilka varelser ger crystalized scales","varifrån kommer basiliskfjäll"}},{q="Vem söker efter dessa fjäll i Stormwind?",a="Collin Mauren, en trollkarl i Stormwind City, anlitar resenärer på väg till Stonetalon för att samla in dem till hans magiska experiment.",al={"vem vill ha crystalized scales","collin mauren fjäll","vem använder dessa fjäll"}},{q="Hur används fjällen i magi?",a="Enligt Collin Mauren ger de kristallina fjällen ett kraftfullt reagens när de mals till ett fint pulver. Det behövs för att driva hans specialbesvärjelser, som han själv har skapat.",al={"varför är crystalized scales magiska","fjäll som reagens till besvärjelser"}},{q="Finns Crystalized Scales bara i Stonetalon?",a="Mauren ber särskilt äventyrare som beger sig mot The Charred Vale i Stonetalon att samla in dem, men liknande kristallina hudar kan också skördas från saltstensbasilisker i Thousand Needles.",al={"fjäll från thousand needles","andra platser att hitta fjäll"}}},fx={cec6ea6a={q="Vad är kristalliserade fjäll?",a="Kristalliserade fjäll är hårda, kristallina ytterplattor som utvinns från vissa basiliskarter. De finns bland annat på basilisker i ogästvänliga områden som The Charred Vale i Stonetalon Mountains. Dessa tåliga fjäll har unika, mineraliska egenskaper som gör dem värdefulla för lärda och magiker.",al={"vad är kristalliserade fjäll","kristalliserade fjäll i historien","om kristalliserade fjäll"}},["5be8a367"]={q="Var kommer kristalliserade fjäll ifrån?",a="Fjällen växer naturligt på vissa basilisksorter. De utvinns ofta från de förkolnade, svärtade och svedda basilisker som strövar omkring i de brinnande ödemarkerna i Stonetalon Mountains Charred Vale, samt från saltstensbasilisker på Thousand Needles saltöknar.",al={"kristalliserade fjälls ursprung","var får man tag på kristalliserade fjäll","källa till kristalliserade fjäll"}}},fp="18,189,23.263.0,20.250.0,40.194.0,41.127.0,40.132.0,51.158.0"}
P.entries["item:curative-animal-salve"] = {n="Curative Animal Salve",s="Curative Animal Salve är ett växtbaserat läkemedel som druidiska örtkunniga brygger för att lindra och läka vilda djur som drabbats av en spridande ekologisk sjukdom. Det bereds både i Darkshore och The Barrens och används som en första behandling för sjuka varelser som lider av osynliga föroreningar i landet.",h="Curative Animal Salve är ett växtbaserat läkemedel som druidiska örtkunniga brygger för att lindra och läka...",kw={"alanndarian nightsong","curative animal salve","bota de sjuka","makt över gifter","sjuka hjortar","sjuk gasell","tonga runetotem"},ang={["class:Druid"]="Att ge detta läkemedel är en grundläggande prövning i att lära sig lindra effekterna av gifter och sjukdomar. Det visar din hängivenhet till Cenarion Circles uppdrag i hela Kalimdor.",["race:Tauren"]="Användningen av salvan i The Barrens visar hur taurendruider förkroppsligar Cenarius läror och arbetar i harmoni med förfädernas cirkelriter för att läka jorden."},sec={{t="Att läka vildmarken",b="Curative Animal Salve tillverkas av lokalt insamlade örter och bereds i satser om tio doser för att behandla vilda djur som drabbats av en spridande korruption. I Darkshores dimmiga skogar instruerar Alanndarian Nightsong unga druider att stryka salvan på sjuka hjortar som strövar mellan Cliffspring River och Ashenvales gränser. Långt söderut, i The Barrens torra vidder, brygger Tonga Runetotem ett identiskt läkemedel för att behandla sjuka gaseller som betar norr om The Crossroads. Båda örtkunniga samarbetar med lokala myndigheter för att framställa större mängder, medan fältutövare ger salvan direkt till djur som lider av miljörelaterad ohälsa."},{t="Tecken på djupare ohälsa",b="När salvan stryks direkt på ett djur lindras dess lidande, men Cenarion Circle ser dessa åkommor som enbart symtom på en mycket större störning. I Moonglade konstaterar Dendrite Starblaze att varken kustens drabbade hjortar eller savannens lidande gaseller är slumpmässiga offer. I stället är de ovetande offer för en spridande plåga som når Kalimdor från flera håll. Att ge salvan är en grundläggande prövning för noviser. Den testar deras hängivenhet till att skydda naturen och deras förmåga att rena bort gifter."}},faq={{q="Vad används Curative Animal Salve till?",a="Salvan stryks direkt på drabbade vilda djur för att bota deras åkommor. Druider använder den för att behandla sjuka hjortar som strövar genom Darkshore och sjuka gaseller som betar norr om The Crossroads i The Barrens.",al={"syftet med curative animal salve","hur man använder curative animal salve","vad gör salvan"}},{q="Vem bereder salvan?",a="I Darkshore bereder Alanndarian Nightsong salvan i Auberdine av insamlade ingredienser. I The Barrens brygger Tonga Runetotem vid The Crossroads blandningen åt horde-druider.",al={"vem tillverkar salvan","var kommer salvan ifrån"}},{q="Varför är hjortarna och gasellerna sjuka från början?",a="Enligt Dendrite Starblaze från Cenarion Circle är djuren offer för en tilltagande förorening och korruption som sprider sig över Kalimdor. De är bland de första offren för en ekologisk plåga som rubbar balansen.",al={"varför är djuren sjuka","vad förgiftar hjortarna i darkshore","gasellsjuka i the barrens"}},{q="Hur många doser innehåller en sats?",a="En vanlig fältsats innehåller tillräckligt med salva för tio behandlingar innan örtblandningen tar slut helt.",al={"hur många laddningar","hur många gånger kan salvan användas"}}},fx={a20a877c={q="Vad är Curative Animal Salve?",a="Curative Animal Salve är en örtmedicin som blandas för att behandla vilda djur som drabbats av en onaturlig sjukdom som sprider sig. Druiders allierade tillreder den av lokala ingredienser. Den renar bort sjukdomen som förgiftar oskyldiga djur, som Darkshores hjortar och The Barrens gaseller.",al={"läkande salva","vad är djursalva","curative animal salve i historien"}}},fp="21,213,17.530.0,28.474.0,39.191.0,23.152.0,54.185.0,36.65.0"}
P.entries["item:daffodil-bouquet"] = {n="Daffodil Bouquet",s="Daffodil Bouquet är en färsk bukett med färgglada blommor som örtkännaren Martie Jainrose har plockat i Lakeshire. Den är tänkt som en romantisk uppskattningsgåva från Guard Parker till Darcy, men väcker oavsiktligt lokalt skvaller och småaktig rivalitet.",h="Daffodil Bouquet är en färsk bukett med färgglada blommor som örtkännaren Martie Jainrose har plockat i...",kw={"daffodil bouquet","påskliljor","darcy","guard parker","lakeshire","martie jainrose","redridge"},ang={["profession:Herbalism"]="Örtkännare som besöker Lakeshire känner igen buketten som ett verk av den växtplockande kollegan Martie Jainrose, vilket belyser den lokala handeln med vilda blommor."},sec={{t="En trasslig gåva",b="När Guard Parker vill visa Darcy sin tacksamhet på värdshuset i Lakeshire för att hon packar hans dagliga lunch, ordnar han en gest genom stadens örtkännare, Martie Jainrose. Martie binder en bukett påskliljor och nämner att de är hennes personliga favoriter. Men när buketten levereras till Darcy väcker de färgglada blommorna genast misstankar: Darcy känner igen dem som Marties signaturblomma och misstänker småaktig svartsjuka från den andra kvinnan. Halvt på skämt säger hon att Martie kanske har förgiftat stjälkarna av ren illvilja."}},faq={{q="Vad används Daffodil Bouquet till?",a="Buketten är avsedd för Darcy på värdshuset i Lakeshire. Guard Parker ordnar så att den levereras till henne som ett innerligt tack för lunchen hon lagar och skickar till honom när han är i tjänst.",al={"syftet med daffodil bouquet","vad gör jag med daffodil bouquet","vem får påskliljorna"}},{q="Vem gjorde buketten?",a="Martie Jainrose, den lokala örtkännaren och blomsterförsäljaren i Lakeshire, plockar och binder buketten på begäran. Hon väljer medvetet påskliljor eftersom de är hennes favoritblomma.",al={"vem gjorde buketten","daffodil bouquets ursprung","varifrån kom blommorna"}},{q="Varför reagerar Darcy misstänksamt på blommorna?",a="Darcy känner genast igen påskliljorna som Marties favoritblomma snarare än något som valts särskilt för henne. Hon kallar Martie en svartsjuk rival och undrar skämtsamt om buketten har förgiftats av illvilja, men tar ändå emot gåvan.",al={"varför är darcy arg","darcy förgiftade blommor","rivaliteten mellan darcy och martie"}},{q="Är påskliljorna faktiskt förgiftade?",a="Nej. Darcys misstankar är bara lokalt drama och teatralisk svartsjuka mellan de två kvinnorna i Lakeshire. Blommorna är helt ofarliga.",al={"är buketten förgiftad","förgiftade martie påskliljorna"}}},fx={d233835e={q="Vad är Daffodil Bouquet?",a="Daffodil Bouquet är en bukett färska gula blommor som plockats i Redridge Mountains. Den består särskilt av Martie Jainroses favoritblommor och är tänkt som ett tack till Darcy på Lakeshire Inn i utbyte mot en måltid.",al={"vad är daffodil bouquet","daffodil bouquet i historien","föremålet daffodil bouquet"}},c8a417a4={q="Varför vill Darcy ha Daffodil Bouquet?",a="Darcy bad inte uttryckligen om blommor, men Guard Parker ville återgälda tjänsten efter att hon skickat honom en varm lunch vid vaktposten i Three Corners. Han ber dig hämta en bukett för att göra henne glad. Hon tar tacksamt emot blommorna och sätter dem i vatten, utan att först inse vilken örtkunnig som har plockat dem.",al={"varför leverera daffodil bouquet","varför vill darcy ha blommor","vem vill ha daffodil bouquet"}}},fp="16,170,15.354.0,38.128.0,26.144.0,49.216.1,36.108.1"}
P.entries["item:daggerspine-scale"] = {n="Daggerspine Scale",s="En Daggerspine Scale är ett segt reptilfjäll från Daggerspine-nagor som stryker längs Hillsbrad Foothills sydkust. Royal Apothecary Society söker efter fjällen, som fungerar som en viktig katalysator för att aktivera giftiga brygder i Forsakens pågående pestexperiment.",h="En Daggerspine Scale är ett segt reptilfjäll från Daggerspine-nagor som stryker längs Hillsbrad Foothills...",kw={"daggerspine","daggerspine scale","elixir of agony","hillsbrad","lydon","naga","royal apothecary society","undercity"},ang={["faction:Horde"]="När du samlar fjäll längs sydkusten måste du ta dig fram försiktigt, eftersom Daggerspines läger ligger farligt nära Alliance-hamnen Southshore.",["race:Undead"]="När du skaffar dessa fjäll för du Royal Apothecary Societys forskning framåt, så att de kan utveckla förödande nya plågor mot Forsakens fiender."},sec={{t="Apotekarens forskning",b="Royal Apothecary Society söker ständigt biologiska reagenser för att förbättra sina gifter, plågor och hopkok. När apotekarna förfinade den experimentella brygden Elixir of Agony upptäckte de att fjäll från de lokala Daggerspine-nagorna hade unika reaktiva egenskaper. Tillsammans med trollars regenererande elixir och murlocorgan hjälper fjällen till att kemiskt aktivera vilande smittämnen i råa blandningar. För att få tag på dem måste du jaga längs den klippiga kusten öster om Southshore och trotsa både den våldsamma nagastammen och Alliance-styrkor i närheten."}},faq={{q="Vad används Daggerspine Scales till?",a="De samlas in åt Apothecary Lydon i Tarren Mill som en del av forskningen om Elixir of Agony. I kombination med andra reagenser aktiverar fjällen de smittande egenskaperna i en alkemisk Mudsnout Mixture.",al={"användning av daggerspine scale","varför samla daggerspine scales","vad gör daggerspine scales"}},{q="Var kommer fjällen ifrån?",a="De flås från Daggerspine-nagor, däribland shorestalkers, shorehunters, screamers, sirens och deras ledare Lady Zephris. De håller till längs Hillsbrad Foothills kust, precis öster om människornas bosättning Southshore.",al={"var hittar man daggerspine scales","vem släpper daggerspine scales","daggerspine scales plats"}},{q="Varför vill Royal Apothecary Society ha nagafjäll?",a="Sällskapets apotekare har fastställt att de tåliga fjällen från Daggerspine-stammen har precis de kemiska egenskaper som krävs för att utlösa specifika smittämnen i deras experimentella hopkok av fördärv och sjukdomar.",al={"varför nagafjäll","apotekare nagafjäll"}}},fx={["8e2c4377"]={q="Vad är Daggerspine Scale?",a="Daggerspine Scale är ett tåligt vattenfjäll som utvinns från Daggerspine-nagorna som stryker längs Hillsbrad Foothills kust. Dessa ormliknande varelser har unika biologiska egenskaper som gör deras ömsade och utvunna fjäll till eftertraktade ingredienser i Royal Apothecary Societys lömska brygder.",al={"vad är daggerspine-fjäll","föremålet daggerspine scale","om daggerspine scale"}}},fp="17,250,19.555.0,37.205.0,32.216.0,55.206.0"}
P.entries["item:dal-bloodclaw-s-skull"] = {n="Dal Bloodclaw's Skull",s="Dal Bloodclaw's Skull tas från hövdingen för Thistlefur-furbolgarna i norra Ashenvale. När du lämnar den till Raene Wolfrunner i Astranaar blir den ett konkret bevis på att en nära förestående attack mot nattalvernas bosättning har avvärjts.",h="Dal Bloodclaw's Skull tas från hövdingen för Thistlefur-furbolgarna i norra Ashenvale.",kw={"ashenvale","astranaar","dal bloodclaw","furbolg","raene wolfrunner","skalle","thistlefur"},ang={["faction:Alliance"]="När Dal Bloodclaw fälls säkras Astranaars norra flank, så att Alliansens främsta tillflyktsort i centrala Ashenvale förblir försvarad.",["race:NightElf"]="För nattalverna är det en sorglig nödvändighet att döda fallna furbolghövdingar. Uråldriga allierade har förvridits av fördärv och hotar nu bosättningar som Astranaar direkt."},sec={{t="En hövdings fall",b="Thistlefur-furbolgarna norr om Astranaar har snabbt blivit fler och mer aggressiva, fördärvade liksom stora delar av Ashenvales urgamla skogar. Nattalvsvakten Raene Wolfrunner fruktade att stammen snart skulle samla mod nog att marschera rakt mot Astranaar. Därför beordrade hon att deras led skulle decimeras och deras ledare, Dal Bloodclaw, dödas. Att ta Dal Bloodclaw's Skull är inte en trofé för småaktig hämnd, utan ett dystert och obestridligt bevis på att stammens ledarskap har slagits sönder, vilket ger Astranaars försvarare värdefull tid."}},faq={{q="Vem var Dal Bloodclaw?",a="Dal Bloodclaw var hövding för Thistlefur-furbolgarna som bodde i Thistlefur Hold, strax norr om Astranaar. Under hans ledning växte den fientliga stammen snabbt och blev ett överhängande hot mot den närliggande nattalvsgarnisonen.",al={"dal bloodclaw","vem är bloodclaw","thistlefur-hövding"}},{q="Varför vill Raene Wolfrunner ha skallen?",a="Raene Wolfrunner behöver bevis på att Thistlefur-hövdingen har dödats. Med Dal Bloodclaw död hoppas nattalverna att oordningen bland de överlevande furbolgarna ska sätta stopp för alla organiserade planer på att anfalla Astranaar.",al={"varför skalle","raene wolfrunner skalle","bevis på död"}},{q="Varför är Thistlefur-furbolgarna så fientliga?",a="Liksom många furbolgstammar i Ashenvale har Thistlefur-furbolgarna dukat under för den utbredda fördärvning som dröjer kvar i skogen. Den har förvandlat dem från fredliga skogsgrannar till våldsamma och revirhävdande hot.",al={"varför är furbolgar aggressiva","furbolgfördärv","thistlefur galen"}}},fx={b1ad26a7={q="Vad är Dal Bloodclaw's Skull?",a="Det är det avhuggna kraniet från Dal Bloodclaw, hövdingen för de korrumperade Thistlefur-furbolgerna som bor i Thistlefur Hold norr om Astranaar. Det är ett makabert bevis på hans död.",al={"vad är dal bloodclaw's skull","dals kranium","vad är det här för kranium"}},fa2f0114={q="Var kommer Dal Bloodclaw's Skull ifrån?",a="Kraniet tas direkt från Dal Bloodclaws kvarlevor i Thistlefur Hold, djupt inne i norra Ashenvale, efter att han dödats för att bryta ledarskapet över hans växande stam.",al={"var kommer dal bloodclaw's skull ifrån","vem tillverkade dal bloodclaw's skull","dal bloodclaw-kraniets ursprung"}}},fp="21,183,22.416.0,22.183.0,41.185.0,43.201.0"}
P.entries["item:dalaran-mana-gem"] = {n="Dalaran Mana Gem",s="Dalaran Mana Gems är kristalliserade arkanreserver som bärs av Kirin Tor-personal i Silverpine Forest. Forsaken-magiker åtrår dessa ädelstenar som kraftfulla råkomponenter för att skapa förtrollade kläder som spellfire robes.",h="Dalaran Mana Gems är kristalliserade arkanreserver som bärs av Kirin Tor-personal i Silverpine Forest.",kw={"ambermill","dalaran mana gem","josef gregorian","kirin tor","linne","manasten","silverpine forest","spellfire robes"},ang={["class:Mage"]="Forsaken-magiker under utbildning skickas ut för att samla in dessa ädelstenar som en övergångsrit och bevisa både sin stridsduglighet och sin förmåga att bemästra insamlade arkanakällor.",["race:Undead"]="Insamlingen visar Forsakens kalla pragmatism. De lägger bort sentimentaliteten gentemot sina forna mänskliga kollegor i Dalaran för att stärka sin egen fraktions överlevnad."},sec={{t="Stulen arkana",b="Kirin Tors magiker, besvärjare och vakter som är stationerade kring Ambermill i Silverpine Forest bär särskilda manastenar för att fokusera och fylla på sina arkanenergier. För Forsaken-utövarna i Undercitys Magic Quarter är dessa kristallina ledare en lättillgänglig källa till koncentrerad magisk essens. Även om vissa odöda magiker erkänner ett gemensamt akademiskt arv med Dalaran, dikterar praktiska behov och en överlevnadsfilosofi att obevekliga rivaler är lovligt byte vars magiska resurser kan tas ifrån dem."},{t="Att väva spellfire",b="När de samlas in från stupade Kirin Tor-operatörer förs dessa ädelstenar till skräddare som Josef Gregorian i Undercity tillsammans med buntar av enkelt linne. Vanliga hantverkare kan inte kanalisera arkan kraft direkt, men skickliga skräddare kan binda in manastenarna i tygets väv. Denna infusion förvandlar vanlig tråd till förtrollade kläder som kan stärka en nybörjarmagikers koppling till det arkana."}},faq={{q="Var kommer Dalaran Mana Gems ifrån?",a="De bärs av Kirin Tor-styrkor som är stationerade i Silverpine Forest, särskilt kring Dalaran-lägren och utposterna nära Ambermill, sydost om The Sepulcher.",al={"var kan man samla manastenar","dalaran-ädelsten byte","vem släpper manastenar"}},{q="Vad används dessa ädelstenar till?",a="Forsaken-magiker använder dem som viktiga förtrollningskomponenter. De förs tillsammans med linne till Josef Gregorian i Undercity och ger den magiska laddning som krävs för att väva spellfire robes.",al={"vad används manastenar till","varför behöver jag dalaran mana gems"}},{q="Varför bär Kirin Tor ädelstenarna i Silverpine?",a="Medlemmar av Kirin Tor använder manastenar som personliga förråd av arkan kraft för att upprätthålla sina besvärjelser, försvarsskydd och frammaningar i fientliga områden som Silverpine Forest.",al={"varför har dalarans magiker ädelstenar","kirin tor manastenar bakgrund"}},{q="Varför riktar Forsaken in sig på Dalarans magiker för att få tag på dessa ädelstenar?",a="Även om Forsaken delar akademiska rötter med Dalarans magiska tradition betraktar de sina levande motsvarigheter som rivaler. Mentorer i Undercity anser att varje magiker som inte kan försvara sin arkana rikedom är för svag för att överleva, vilket rättfärdigar att deras komponenter tas till vara.",al={"forsaken mot dalarans magiker","varför döda dalaran för kläder"}}},fx={["02094a76"]={q="Vad är Dalaran Mana Gem?",a="Dalaran Mana Gem är en magiskt laddad sten som bärs av Kirin Tor-agenterna i Silverpine Forest. Kristallerna är genomsyrade av arkan energi och är viktiga beståndsdelar vid tillverkning av förtrollade kläder, som spellfire-mantlarna som Forsaken-skräddare syr i Undercity.",al={"vad är dalaran mana gem","dalaran mana gem","manasten i silverpine"}}},fp="16,137,13.391.0,21.291.0,37.155.0,29.116.0,56.168.0,56.239.0"}
P.entries["item:dalaran-pendant"] = {n="Dalaran Pendant",s="Dalaran Pendant är magiska talismaner som bärs av Kirin Tor-trollkarlarna stationerade i byn Ambermill i Silverpine Forest. The Forsaken vill samla in dessa hängen för att störa magikernas arkana arbete och spåra kraftens ursprung.",h="Dalaran Pendant är magiska talismaner som bärs av Kirin Tor-trollkarlarna stationerade i byn Ambermill i...",kw={"allister","ambermill","dalaran pendant","kirin tor","the sepulcher","silverpine"},ang={["class:Mage"]="Hängena fungerar som fokus för Kirin Tors vävning och visar hur Dalarans trollkarlar samordnar komplex kollektiv magi.",["race:Undead"]="Att beröva Kirin Tor dessa hängen är ett viktigt steg för att säkra Silverpine Forest mot mänskliga trollkarlar som försöker återupprätta sitt fotfäste."},sec={{t="Ambermills amuletter",b="I byn Ambermill väver Kirin Tor-trollkarlar, besvärjare och beskyddare aktivt mäktiga arkana besvärjelser som hotar The Forsakens kontroll över södra Silverpine Forest. Varje agent bär en instämd Dalaran Pendant. Vid The Sepulcher ger Shadow Priest Allister The Forsakens agenter i uppdrag att återta dessa hängen för att bromsa magikernas arbete och ta reda på vem som leder deras magiska väv."}},faq={{q="Vad är Dalaran Pendant?",a="Det är en arkansmyckad amulett som bärs av Kirin Tor-besvärjare, magiker och beskyddare stationerade i Ambermill. The Forsaken återtar dem för att avbryta trollkarlarnas rituella arbete och undersöka deras magiska hantverk.",al={"vad är dalaran pendant","kirin tor-halsband silverpine"}},{q="Vem bär dessa hängen?",a="De bärs av de mänskliga magikerna, besvärjarna och beskyddarna från Dalaran som ockuperar Ambermill i Silverpine Forest.",al={"vem släpper dalaran pendant","var får man tag på dalaran pendant"}},{q="Varför vill Shadow Priest Allister ha dem?",a="Shadow Priest Allister och hans allierade Dalar behöver hängena för att bromsa trollkarlarnas besvärjelser och ringa in den mäktiga magiker som styr väven av magisk energi i Ambermill.",al={"varför allister vill ha hängen","ambermill-hänge undersökningar"}},{q="Var ligger Ambermill?",a="Ambermill ligger i södra Silverpine Forest. Resenärer som färdas söderut från The Sepulcher tar den östra avtagsvägen från huvudvägen för att hitta byn.",al={"ambermills läge","hur tar man sig till ambermill"}}},fp="15,147,20.349.0,28.188.0,27.104.0,42.155.0,27.141.0"}
P.entries["item:dalaran-status-report"] = {n="Dalaran Status Report",s="Dalaran Status Report är en samling känsliga underrättelser som Kirin Tor-magikerna i Ambermill i Silverpine Forest har sammanställt. Den beskriver den återuppbyggda staden Dalarans nuvarande tillstånd och är därför ett värdefullt dokument för Forsaken och Deathstalkers i Undercity.",h="Dalaran Status Report är en samling känsliga underrättelser som Kirin Tor-magikerna i Ambermill i Silverpine...",kw={"ambermill","ambermills kista","dalaran status report","deathstalkers","kirin tor","mennet carkad","yrkets verktyg","varimathras"},ang={["class:Rogue"]="Mennet Carkad använder hämtningen av rapporten som ett fältprov för att träna Deathstalkers i den svåra konsten att dyrka lås och infiltrera områden där vaksamma magiker håller vakt.",["race:Undead"]="Kvarlevorna av Kirin Tor i Ambermill är en nagel i ögat på Forsaken i Silverpine. Därför är alla underrättelser om deras verksamhet viktiga för Undercitys säkerhet."},sec={{t="Ögon på den återuppbyggda staden",b="Scourge plundrade Dalaran, och Archimonde fällde stadens höga spiror under det tredje kriget. De magiker som överlevde tog tidigt bort stadens skyddande sköld under återuppbyggnaden och bygger nu upp den öppet. Kirin Tor har också enklaver som Ambermill i sydöstra Silverpine Forest. Dalaran Status Report innehåller underrättelser om Dalarans tillstånd som Deathstalkers vill åt."},{t="Ett prov för en Deathstalker",b="För att behålla kontrollen över Lordaeron krävs ständig vaksamhet, och Lord Varimathras håller noga uppsikt över alla kvarlevor av Alliance och Kirin Tor. Efter att Forsaken-förhörsledare pressat fram erkännanden från en tillfångatagen Kirin Tor-magiker beordrade dreadlorden Deathstalkers att skaffa rapporten. Dokumentet gömdes i en låst kista djupt inne i Ambermill och blev både en nödvändighet i fält och ett mandomsprov för nyinvigda rogues som lärde sig konsten att dyrka lås under Mennet Carkad i Rogues' Quarter."}},faq={{q="Vad är Dalaran Status Report?",a="Det är en samling konfidentiella dokument från Kirin Tor som beskriver Dalarans nuvarande förhållanden, återuppbyggnadsarbete och tillstånd. Magikerna som bemannar utposten Ambermill har sammanställt dem.",al={"vad är den här rapporten","dalaranrapport","dokument från ambermill"}},{q="Var förvaras rapporten?",a="Magikerna i Ambermill låste in rapporten i en kista i sin bosättning i sydöstra Silverpine Forest för att skydda den från inkräktare och nyfikna blickar.",al={"var finns rapporten","var finns ambermills kista","hur hittar man statusrapporten"}},{q="Varför vill Undercity ha rapporten?",a="Lord Varimathras och Forsaken ser de överlevande i Kirin Tor som ett omedelbart hot. Med rapporten kan Deathstalkers bedöma Dalarans militära styrka och hemliga återuppbyggnadsprojekt.",al={"varför vill forsaken ha den här","varimathras dalaranrapport","deathstalkers uppdrag"}},{q="Hur fick Deathstalkers veta om dokumentet?",a="Deathstalkers fick reda på att dokumentet fanns och var det låg direkt från en tillfångatagen Kirin Tor-fånge som hölls för förhör i Undercity.",al={"hur fick undercity reda på det","fångens erkännande"}}},fx={f1fae308={q="Var kommer Dalaran Status Report ifrån, och vem har skrivit den?",a="Rapporten skrevs av Kirin Tor-magikerna som är stationerade i Ambermill i södra Silverpine Forest. Efter Dalarans förödelse under det tredje kriget upprätthåller de överlevande magikerna utposter i de omgivande regionerna för att hålla uppsikt över sin fallna stad, dokumentera pågående händelser och samordna sina återstående styrkor.",al={"vem skrev dalaran status report","dalaran status reports ursprung"}}},fp="21,135,27.438.0,21.480.1,34.176.0,25.102.0,40.202.0,51.122.0"}
P.entries["item:dalin-s-heart"] = {n="Dalin's Heart",s="Dalin's Heart är en makaber ritualkomponent, utskuren ur Dalin Forgewright, en hedervärd man som patrullerade nära The Greymane Wall i Silverpine Forest. Warlocks i Undercity söker efter den som ett offer av obefläckad renhet, avsett att locka till sig en succubus och binda den i sin tjänst.",h="Dalin's Heart är en makaber ritualkomponent, utskuren ur Dalin Forgewright, en hedervärd man som patrullerade...",kw={"carendin halgar","dalin forgewright","dalin's heart","the greymane wall","hjärtan från de rena","silverpine forest","succubus","undercity"},ang={["class:Warlock"]="Att skaffa detta hjärta är en viktig övergångsrit för Forsaken-warlocks som lär sig att snärja en succubus. Det visar att de är villiga att skörda obefläckad godhet för att bemästra demoner.",["race:Undead"]="Jakten på Dalins hjärta visar den bittra verkligheten i Lordaeron efter Scourge, där kvarvarande levande, altruistiska människor utanför The Greymane Wall blir byte för Forsaken."},sec={{t="Ett rent hjärta för mörk magi",b="För att åkalla och kuva en succubus behöver warlocks i Undercity ett sällsynt lockbete: de fysiska hjärtana från verkligt dygdiga dödliga. Dalin Forgewright gick sitt mörka öde till mötes genom sin osjälviska hängivenhet och tillbringade dagarna med att försvara desperata flyktingar från Lordaeron, som nekades trygghet vid den förseglade The Greymane Wall. Hans outtröttliga altruism gör honom till ett föredöme i godhet i ett förfallet land, och därför är hans hjärta ett oemotståndligt byte för demoniska förförelseriter i Temple of the Damned."}},faq={{q="Vem var Dalin Forgewright?",a="Dalin Forgewright var en hedervärd människa som vigt sitt liv åt att skydda flyktingar från Lordaeron, strandsatta utanför de stängda portarna vid The Greymane Wall i södra Silverpine Forest.",al={"dalin forgewright","vem är dalin","dalins historia"}},{q="Varför behöver warlocks Dalin's Heart?",a="Warlock-besvärjare i Undercity behöver hjärtat från en verkligt ren och hedervärd man som rituellt lockbete för att locka till sig och kuva en succubus.",al={"varför dalins hjärta","dalins hjärtas syfte","varför vill warlocks ha dalins hjärta"}},{q="Vem tar emot Dalin's Heart?",a="Hjärtat lämnas till Carendin Halgar, en warlocktränare i Temple of the Damned i Undercity.",al={"vem tar emot hjärtat","lämna in dalins hjärta","vart lämna dalins hjärta"}},{q="Vilken annan komponent behövs tillsammans med hjärtat?",a="Carendin Halgar behöver både Dalin's Heart och Comar's Heart, som tillhör Comar Villard, en trogen make som irrar omkring i Wetlands i sökandet efter sin försvunna hustru.",al={"hjärtan från de rena, annat hjärta","annat hjärta som behövs","andra hjärtat"}}},fx={["5b5f5201"]={q="Vad är Dalin's Heart?",a="Det är det bokstavliga, fysiska hjärtat som skurits ut ur Dalin Forgewright, en hedervärd man som tar hand om Lordaeron-flyktingar nära The Greymane Wall i Silverpine Forest. Även om det rent fysiskt inte går att skilja från något annat människohjärta, bär det på en särskild andlig renhet från en osjälvisk och dygdig själ.",al={"vad är dalin's heart","beskrivning av dalin's heart","föremålet dalin's heart"}},d7d2edf8={q="Var kommer Dalin's Heart ifrån?",a="Hjärtat kommer från Dalin Forgewright, en dygdig man som tar hand om Lordaeron-flyktingarna vid den stängda Greymane Wall i södra Silverpine Forest. En häxmästare måste spåra upp och döda honom för att ta organet direkt från hans lik.",al={"var får man tag på dalin's heart","dalin's hearts ursprung","vem släpper dalin's heart"}}},fp="13,95,26.369.0,26.159.0,35.105.0,26.107.0,52.144.0"}
P.entries["item:darkhound-blood"] = {n="Darkhound Blood",s="Darkhound Blood är en motbjudande kroppsvätska som utvinns ur de besmittade hunddjuren som strövar omkring på fälten och i skogarna i Tirisfal Glades. Den samlas in på uppdrag av Royal Apothecary Society och används som ett tidigt reagens i deras mörka experiment för att skapa en dödlig ny pest.",h="Darkhound Blood är en motbjudande kroppsvätska som utvinns ur de besmittade hunddjuren som strövar omkring på...",kw={"en ny pest","apothecary johaan","brill","darkhound","darkhound blood","royal apothecary society","tirisfal glades"},ang={["faction:Horde"]="Medan mörka experiment pågår i Brill är det få utanför Forsakens innersta krets som till fullo förstår den giftiga potential som Royal Apothecary Society håller på att frigöra.",["race:Undead"]="Att samla in reagenser som Darkhound Blood är ett viktigt arbete för Forsaken och hjälper Lady Sylvanas och Royal Apothecary Society att smida det ultimata vapnet mot Scourge."},sec={{t="Bränsle till The New Plague",b="Under Lady Sylvanas Windrunners befäl strävar Royal Apothecary Society efter att utveckla en smittsam farsot som kan utplåna Arthas och hans Scourge. Apothecary Johaan, som är stationerad i Brill, menar att lokala bestar, korrumperade av mörka energier och motståndskraftiga mot det omgivande förfallet, har ovanliga biologiska egenskaper. Genom att destillera blod från vilda darkhounds hoppas Johaan hitta biologiska ämnen som kan stå emot eller sprida smittsamma nekrotiska stammar."}},faq={{q="Vad används Darkhound Blood till?",a="Apothecary Johaan i Brill använder det som ett grundläggande reagens i Royal Apothecary Societys forskning för att skapa en helt ny pest, dödligare än allt Azeroth någonsin skådat.",al={"användning av darkhound blood","varför samla darkhound blood","syftet med darkhound blood"}},{q="Vilka varelser ger detta blod?",a="Det utvinns ur olika darkhounds som strövar omkring i Tirisfal Glades, däribland cursed, ravenous och decrepit darkhounds.",al={"var hittar man darkhound blood","vem släpper darkhound blood","källa till darkhound blood"}},{q="Varför används darkhounds i pestforskningen?",a="Apothecary Johaan menar att blodet från bestar som vant sig vid de korrumperade markerna i Tirisfal kan innehålla de biologiska hemligheter som krävs för att framställa en ostoppbar farsot.",al={"varför darkhounds","apothecary johaans teori","darkhounds egenskaper"}}},fx={db825c3d={q="Vad är Darkhound Blood?",a="Darkhound Blood är en förgiftad kroppsvätska som utvinns från de vilda mörkerhundarna som stryker omkring i Tirisfal Glades. Mörk magi och kvardröjande odödhet har förvridit hundarna, vars blod har unika, motståndskraftiga egenskaper. Alkemister och forskare finner det motbjudande och farligt för vanliga levande varelser, men idealiskt för biologiska experiment, särskilt vid undersökningar av smittsamma ämnen eller hur man motverkar nekrotiskt förfall.",al={"vad är darkhound blood","darkhound blood i historien","förklara darkhound blood"}},["93cde5f9"]={q="Varifrån kommer Darkhound Blood, och vem har gjort det?",a="Det här blodet samlas naturligt in från de förbannade, glupska och förfallna darkhound-hundar som stryker omkring i Tirisfal Glades hemsökta skogar och förfallna gårdar. Det är ingen konstgjord brygd, utan kroppsvätska från bestar som har anpassat sig till och tagit upp den pestsmitta som förgiftat regionen sedan tredje kriget.",al={"källa till darkhound blood","var kommer darkhound blood ifrån","vem skapade darkhound blood"}}},fp="15,275,23.478.0,33.185.0,33.119.0,48.179.0"}
P.entries["item:darkshore-grouper"] = {n="Darkshore Grouper",s="Darkshore Grouper är en tålig saltvattenfisk som lever i det dimhöljda kustvattnet längs Darkshore. Den är uppskattad både som en god basfångst och som sportfisk, men har blivit svårare att fånga från bryggorna sedan murlocernas aktivitet drev bort de lokala fiskarna från deras båtar.",h="Darkshore Grouper är en tålig saltvattenfisk som lever i det dimhöljda kustvattnet längs Darkshore.",kw={"auberdine","blump family fishing pole","darkshore","darkshore grouper","fiske","grouper","gubber blump","murloc"},ang={["profession:Cooking"]="Darkshore Grouper är en mångsidig ingrediens i enkla kustrecept och ett praktiskt byte för resande kockar som vill vässa sina färdigheter längs stranden.",["race:Dwarf"]="Dvärgfiskaren Gubber Blump för vidare familjens stolta fisketradition vid Kalimdors stränder och belönar alla som kan mäta sig med hans släkts fångstskicklighet."},sec={{t="En basvara från den höljda kusten",b="I Darkshores kalla havsvatten är Darkshore Grouper en uppskattad fångst bland kustfiskare. Fisken värdesätts för sin mångsidighet i matlagningen och hamnar i en mängd enkla kustnära rätter som uppskattas av resenärer och invånare runt Auberdine. Den går att dra upp ur bränningarna med enkel fiskeutrustning, men fiskare tycker att det är lika roligt att fånga den som att äta den."},{t="Murlocernas hot",b="Förr tog fiskare som Gubber Blump små båtar ut på djupare vatten för att fånga mängder av grouper. Men de alltmer aggressiva kustmurlocerna har fått de flesta båtar runt Auberdine att ligga stilla. Eftersom fiskarna nu är hänvisade till stränderna och bryggorna misstänker lokalbefolkningen att de framryckande murlocerna äter upp det lokala grouperbeståndet, så det krävs tålamod för att få en god fångst."}},faq={{q="Var kan man fånga Darkshore Grouper?",a="Darkshore Grouper fångas genom att kasta ut en fiskelina i saltvattnet längs Darkshores kust, även i vattnen runt Auberdine.",al={"var fiskar man grouper","darkshore grouper plats","hur fångar man darkshore grouper"}},{q="Vem vill ha Darkshore Grouper i Auberdine?",a="Gubber Blump, en dvärgisk fiskare som bor i Auberdine, ber resenärer fånga Darkshore Grouper åt honom i utbyte mot ett uppskattat Blump Family Fishing Pole.",al={"vem behöver grouper","gubber blump fisk","uppdragsgivare för grouper"}},{q="Varför använder inte fiskarna båtar för att fånga grouper?",a="Aggressiva murlocer har spridit sig längs Darkshores kust och gjort båtturer ut på vattnet alltför farliga för de lokala fiskarna.",al={"varför har båtarna slutat gå","auberdines fiskebåtar","murlocer grouper"}},{q="Måste man ha ett uppdrag för att fånga Darkshore Grouper?",a="Nej. Darkshore Grouper är visserligen målet för uppgifter som lokalbor som Gubber Blump ber om, men det är en vanlig saltvattenfisk som alla fiskare kan fånga genom att kasta ut linan i Darkshores vatten.",al={"är grouper ett uppdragsföremål","kan jag fiska grouper när som helst"}}},fx={bdb033c0={q="Vad är Darkshore Grouper?",a="Darkshore Grouper är en lokal saltvattenfisk som simmar utanför Darkshores dimhöljda kust. Den uppskattas högt av lokala sportfiskare som Gubber Blump och är omtyckt både som en fin fångst att dra upp ur bränningarna och som mångsidig matlagning hemma.",al={"vad är darkshore grouper","fisken darkshore grouper","om darkshore grouper"}},["97e4a4d8"]={q="Varifrån kommer Darkshore Grouper?",a="Darkshore Grouper är en vild saltvattenfisk som hör hemma i kustvattnen längs Darkshore. Ingen tillverkar eller skapar den, men för att fånga den måste du kasta ut ett metspö i bränningarna från stranden eller bryggorna.",al={"darkshore groupers ursprung","var kommer darkshore grouper ifrån","varifrån kommer darkshore grouper"}},f987244e={q="Varför vill Gubber Blump ha Darkshore Grouper?",a="Gubber Blump älskar helt enkelt att fånga och äta dem, och säger att det finns gott om fina rätter att laga på färsk fångst. Fientliga murlocer har drivit bort de lokala fiskebåtarna, så han förlitar sig på hjälpsamma resenärer som kan dra upp fisk från kusten.",al={"varför vill man ha darkshore grouper","varför vill gubber ha grouper","vad används darkshore grouper till"}}},fp="17,182,30.341.0,17.316.0,37.114.0,41.163.0,50.93.0,58.158.0"}
P.entries["item:darksoul-shackle"] = {n="Darksoul Shackle",s="En Darksoul Shackle är en förtrollad boja som bärs av Moonrage Darksoul-worgen som stryker omkring i Silverpine Forest. Dessa redskap skapades under ärkemagikern Arugals ledning och eftertraktas av Forsaken-magiker vid The Sepulcher, som försöker lösa upp den vilda magi som håller regionen i sitt grepp.",h="En Darksoul Shackle är en förtrollad boja som bärs av Moonrage Darksoul-worgen som stryker omkring i...",kw={"arugal","dalar dawnweaver","darksoul shackle","moonrage darksoul","the sepulcher","silverpine forest","worgen"},ang={["class:Mage"]="En granskning av bojorna visar hur en desperat trollkarl använde grova förtrollade föremål för att stötta instabila besvärjelser som han inte kunde kontrollera ordentligt.",["race:Undead"]="För Forsaken är det avgörande att bryta Arugals grepp om Silverpine Forest för att skydda deras södra gränser och bevisa Undercitys mystiska lärdomars överlägsenhet gentemot Dalarans misslyckanden."},sec={{t="En krycka för sviktande magi",b="När ärkemagikern Arugal släppte lös worgen i Silverpine Forest räckte hans egen behärskning av de mystiska krafterna inte till för att fullt ut styra och upprätthålla de utomjordiska bestarna. För att kompensera för sina brister band han förtrollade redskap, som Darksoul Shackles, till sina skapelser. Bojorna leder yttre trolldom in i Moonrage Darksouls, stärker deras övernaturliga kraft och förankrar förbannelsen som håller dem i träldom under Shadowfang Keep."},{t="Kirin Tors granskning",b="Vid The Sepulcher betraktar Forsaken-magikern Dalar Dawnweaver Arugal som en farligt inkompetent person vars inblandning förstörde Kirin Tors försvar mot Scourge. Genom att samla Darksoul Shackles och sådana som slitits av Moonrage Gluttons utvinner Forsaken-forskarna de kvarvarande förtrollningarna som vävts in i metallen. Studier av dessa kryckor avslöjar de strukturella bristerna i Arugals magi och ger Forsaken de mystiska insikter som krävs för att utforma en motåtgärd mot hans varglika plåga."}},faq={{q="Vad är en Darksoul Shackle?",a="Det är en förtrollad metallboja som bärs av Moonrage Darksoul-worgen i Silverpine Forest. Den skapades av ärkemagikern Arugal för att förstärka hans bristfälliga magi och binda bestarna till hans vilja.",al={"vad är darksoul shackles","darksoul shackle föremålsbakgrund","vad är den här bojan"}},{q="Vem vill ha Darksoul Shackles?",a="Dalar Dawnweaver, en Forsaken-magiker stationerad vid The Sepulcher i Silverpine Forest, behöver dem. Han studerar förtrollningarna i bojorna för att hitta en lösning på Arugals worgenutbrott.",al={"vem behöver darksoul shackles","vem tar bojorna","dalar dawnweaver uppdrag"}},{q="Var kommer bojorna ifrån?",a="De tas från liken efter Moonrage Darksouls, aggressiva worgen som hemsöker de norra och östra delarna av Silverpine Forest.",al={"vem släpper darksoul shackles","darksoul shackle varelse","var hittar man darksoul shackle"}},{q="Varför satte Arugal bojor på worgen?",a="Enligt Dalar Dawnweaver var Arugal inte en tillräckligt skicklig magiker för att styra bestarna med enbart sin egen kraft. Han förlitade sig på förtrollade föremål som dessa bojor för att leda och upprätthålla den instabila magi som håller flocken samman.",al={"varför bär worgen bojor","syftet med arugals boja"}}},fp="16,207,28.358.0,18.455.1,27.193.0,28.177.0,34.107.0,42.219.0"}
P.entries["item:darnassus-marzipan"] = {n="Darnassus Marzipan",s="Under Hallow's End delar värdshusvärdarna i Darnassus ut festlig marsipan till besökare som dansar för att få den. Den här sötsaken tillverkas i nattalvernas huvudstad inför höstfirandet och är en av fyra godsaker som Jesper behöver.",h="Under Hallow's End delar värdshusvärdarna i Darnassus ut festlig marsipan till besökare som dansar för att få...",kw={"godis","darnassus","darnassus marzipan","hallow's end","jesper","marsipan","godsaker"},ang={["faction:Alliance"]="Som resenär i Alliansen kan du samla godsaker från Darnassus, Ironforge och Stormwind. Hallow's End för samman Alliansens vitt skilda folk i gemensamt firande.",["race:NightElf"]="Som kaldorei kan du ta del av höstens lättsammare seder. Värdshusvärdarna i Darnassus bjuder resenärer på söt marsipan när de tackar för gästfriheten med en livlig dans."},sec={{t="En smak av världsträdet",b="Under Hallow's End delar alliansens huvudstäder en tradition av lättsamt bus eller godis. Dvärgar erbjuder starka mintpastiller, Stormwind tillverkar seg nougat och värdshusvärdarna i Darnassus förbereder len marsipan åt besökarna. För att få en bit måste du visa lite feststämning och dansa när värdshusvärden ber dig. Sötsaken är en av fyra regionala godsaker som Jesper är ute efter. Han är ett sjukt föräldralöst barn på Cathedral Square i Stormwind och kan inte själv gå ut och samla godis."}},faq={{q="Vad används Darnassus Marzipan till?",a="Under Hallow's End behöver Jesper Darnassus Marzipan som en av fyra olika sötsaker. Han är ett sjukt föräldralöst barn på barnhemmet vid Cathedral Square i Stormwind. Ta med den tillsammans med godis från Ironforge, Gnomeregan och Stormwind, så får du ett knippe festliga pumpagodisar.",al={"darnassus marzipan användning","vad gör jag med marsipan"}},{q="Hur får du tag på Darnassus Marzipan?",a="Under Hallow's End ger värdshusvärdarna i Darnassus dig marsipan efter att ha bett dig dansa en kort stund.",al={"hur får jag darnassus marzipan","var får jag tag på marsipan"}},{q="Varför kan Jesper inte själv få tag på marsipanen?",a="Jesper är sjuk och kan inte gå ut och tigga godis. Han finns på barnhemmet i Stormwind, vid Cathedral Square, och är beroende av att äventyrare samlar in de avlägsna godsakerna åt honom.",al={"varför behöver jesper godis","varför kan jesper inte gå"}}},fx={["06b4a124"]={q="Vad är Darnassus Marzipan?",a="Darnassus Marzipan är ett festligt bakverk från nattalvernas huvudstad Darnassus. Under höstfesten Hallow's End delar man ut den här mandelmassesötsaken till festdeltagare. Den är en av de fyra traditionella högtidsgodisarna som ges till resenärer som utför festliga upptåg i utbyte mot något gott.",al={"vad är darnassus marzipan","darnassus marzipans bakgrund","vilken sorts godis är darnassus marzipan"}},cf1db7fa={q="Varifrån kommer Darnassus Marzipan, och vem har gjort den?",a="Sötsaken kommer från nattalvernas huvudstad Darnassus, uppe bland Teldrassils grenar. Under Hallow's End delar stadens värdshusvärd ut den till besökare som underhåller krogen med en dans. Det firar gemenskapen och glädjen som förenar Alliansen i Kalimdor och Eastern Kingdoms.",al={"var kommer darnassus marzipan ifrån","vem gör darnassus marzipan","darnassus marzipans ursprung"}},["1983589f"]={q="Varför vill någon ha Darnassus Marzipan?",a="Utöver att vara en högtidsdelikatess bland alver är den eftertraktad av dem som inte kan fira Hallow's End på egen hand. Jesper, en sjuk föräldralös pojke på Cathedral Square i Stormwind, ber resenärer gå bus eller godis åt honom så att han kan få smaka godsaker från hela Alliansen.",al={"varför vill man ha darnassus marzipan","vem vill ha darnassus marzipan","varför samlar man på darnassus marzipan"}}},fp="18,203,25.452.0,36.271.0,37.102.0,42.169.0"}
P.entries["item:darthalia-s-sealed-commendation"] = {n="Darthalia's Sealed Commendation",s="Darthalia's Sealed Commendation är en officiell rapport, skriven av Förfallnas stridsbefälhavare i Tarren Mill. Den lovordar en soldats outtröttliga fälttåg mot Hillsbrads människor och förmedlar nyheten om segrarna direkt till Undercitys högsta befäl.",h="Darthalia's Sealed Commendation är en officiell rapport, skriven av Förfallnas stridsbefälhavare i Tarren...",kw={"utmärkelse","darthalia","hillsbrad","southshore","tarren mill","undercity","varimathras"},ang={["faction:Horde"]="Utmärkelsen markerar en viktig strategisk seger i Lordaeron och visar Undercitys ledning att Alliansens befästa fästen vid de södra kullarna kan monteras ned systematiskt.",["race:Undead"]="En soldats anseende inom Dark Ladys växande militära hierarki stärks av Darthalias höga lovord och genom att utmärkelsen överlämnas direkt i tronsalen."},sec={{t="Rapportera till högsta befälet",b="Efter de brutala sammandrabbningarna i Hillsbrad Foothills skrev High Executor Darthalia denna förseglade rapport för att officiellt dokumentera segrarna över Hillsbrads mänskliga försvarare och förödelsen bland deras ställningar. Dokumentet förseglades för att skydda befälhavarens omdöme från nyfikna blickar och adresserades till Varimathras, rådgivare åt Lady Sylvanas Windrunner och en fruktad dreadlord. För Förfallnas ledning i Royal Quarter ger sådana skrivelser konkreta bevis för att Alliansens enklaver söder om Lordaeron kan krossas, så att de nordliga garnisonerna kan fokusera på hotet från Scourge."}},faq={{q="Vad är Darthalia's Sealed Commendation?",a="Det är en officiell krigsutmärkelse skriven av High Executor Darthalia i Tarren Mill. Dokumentet berömmer formellt en krigares insats mot Alliansen under slaget om Hillsbrad och är avsett för högsta befälet i Undercity.",al={"förseglad utmärkelse","darthalias brev","rapport om hillsbrad"}},{q="Vem ska ta emot utmärkelsen?",a="Utmärkelsen ska överlämnas direkt till dreadlorden Varimathras, som övervakar militära operationer tillsammans med Lady Sylvanas Windrunner i Undercitys Royal Quarter.",al={"vem ska jag lämna det till","lämna in utmärkelsen","vem får darthalias utmärkelse"}},{q="Varför bryr sig Varimathras om striderna i Hillsbrad?",a="Förfallna anser att Lich King och hans Scourge är det främsta existentiella hotet från norr, men människornas närvaro i Hillsbrad stör ständigt deras försörjningslinjer och säkerheten vid den södra gränsen. Varimathras värdesätter segrar på slagfältet som undanröjer det mänskliga hindret och låter Undercitys styrkor fokusera på det större kriget.",al={"varför varimathras bryr sig","dreadlord i hillsbrad","förfallnas strategi i hillsbrad"}}},fx={fd99e080={q="Varifrån kommer Darthalia's Sealed Commendation, och vem har gjort den?",a="Darthalia har skrivit och förseglat det här brevet. Hon är en befälhavare bland de Förfallna som samordnar Hordens styrkor i Hillsbrad Foothills. Hon har sett ditt mod och din outtröttliga uthållighet under det bittra fälttåget mot människornas bosättningar i Hillsbrad. Därför skrev hon personligen den här officiella rapporten för att berömma dina insatser på slagfältet inför överkommandot.",al={"vem skrev darthalias rekommendation","varifrån kommer darthalias rekommendation","vem gav den förseglade rekommendationen"}},["9dfe1fb6"]={q="Varför vill Varimathras ha Darthalia's Sealed Commendation?",a="Darthalia skickar dokumentet direkt till Varimathras i Undercity, så att ledarskapet bland de Förfallna uppmärksammar din dödliga effektivitet. Fursten av skräck ser Scourge i norr som det främsta hotet, men människorna i Alliansen i Hillsbrad stör deras större strategiska planer. Den här rekommendationen bevisar formellt att avgörande angrepp mot människornas bosättningar kan lyckas under skickliga fältmästare som du.",al={"varför ska den förseglade rekommendationen levereras","varför vill varimathras ha rekommendationen","syftet med darthalias rekommendation"}}},fp="31,105,22.437.0,40.186.0,31.125.0,58.252.0"}
P.entries["item:deadmire-s-tooth"] = {n="Deadmire's Tooth",s="Deadmire's Tooth är en trofé från den uråldriga krokilisk som kallas Deadmire och som smyger genom Dustwallow Marshs grumliga vatten. När du överlämnar den till jägaren Melor Stonehoof på Thunder Bluff bevisar du att den åldrande rovjägaren fått en barmhärtig och hedervärd död.",h="Deadmire's Tooth är en trofé från den uråldriga krokilisk som kallas Deadmire och som smyger genom Dustwallow...",kw={"krokilisk","deadmire","dustwallow","hunter rise","melor stonehoof","thunder bluff","tand"},ang={["class:Hunter"]="För jägare som lär sig av mentorerna på Hunter Rise är det en lärdom att ta tanden: jakten måste präglas av respekt och barmhärtighet, inte bara av jakten på troféer.",["race:Tauren"]="Jakten på Deadmire gestaltar Jordmodernas kretslopp av balans, där åldrande rovdjur leds mot frid i stället för att lämnas att lida."},sec={{t="En barmhärtighetens trofé",b="I taurenjägarnas traditioner på Hunter Rise är spårning av vilda djur mer än ett prov på stridsförmåga eller meningslös blodsport. Det är ett andligt förbund som bygger på balans, vördnad och ibland barmhärtighet. Deadmire var en gång en av de ståtligaste krokilisken i Dustwallow Marsh, men hans höga ålder gjorde hans sista år till en plågsam pina. Trots att han hade samma okuvliga anda och skräckinjagande vildhet som i sin krafts dagar blev hans väldiga ben och sviktande kropp ett fängelse av ändlös smärta. Att ta Deadmire's Tooth ger Melor Stonehoof ett konkret bevis på att bestens långvariga lidande äntligen har fått ett slut genom en hedervärd jakt."}},faq={{q="Vad används Deadmire's Tooth till?",a="Tanden lämnas till Melor Stonehoof på Hunter Rise i Thunder Bluff. Den fullbordar jakten han ger dig, att spåra upp Deadmire, och bevisar att den uråldriga rovjägaren fick en barmhärtig befrielse.",al={"lämna in deadmire's tooth","vem vill ha deadmire's tooth","vad gör jag med deadmire's tooth"}},{q="Var kommer Deadmire's Tooth ifrån?",a="Tanden tas direkt från Deadmire, en enorm och uråldrig krokilisk som stryker omkring i södra Dustwallow Marshs träsk och vatten öster om Tabetha's Farm.",al={"var får jag tag på deadmire's tooth","vem släpper deadmire's tooth","deadmire plats"}},{q="Varför vill Melor Stonehoof att Deadmire dödas?",a="Melor ser inte Deadmire som ett monster, utan som en ädel varelse som i sin ålderdom uthärdar outhärdlig fysisk smärta. Jakten är en barmhärtighetshandling som låter krokiliskens livslåga falna i frid i stället för att tyna bort i långsam plåga.",al={"varför döda deadmire","melor stonehoof anledning","är deadmire ond"}}},fx={["4f19a846"]={q="Vad är Deadmire's Tooth?",a="Deadmire's Tooth är en trofé från käken på Deadmire, en enorm och uråldrig krokolis som lurar i Dustwallow Marsh träskmarker. För jägare som följer taurenernas traditioner i Thunder Bluff är tanden ett fysiskt bevis på att det mäktiga odjuret har spårats upp och fått ett barmhärtigt slut.",al={"deadmire's tooth","vad är deadmires tand","information om deadmire's tooth"}},["200b2360"]={q="Varför vill någon ha Deadmire's Tooth?",a="Melor Stonehoof, en jakttränare på Hunter Rise i Thunder Bluff, ber om tanden som bevis på din jakt. Deadmire lever med ständig, plågsam smärta på grund av sin höga ålder och sina utslitna gamla ben. Taurener vördar naturen och ser barmhärtighet som en del av jägarens heliga plikt. Om du visar Melor tanden vet han att du har gjort slut på det ädla odjurets lidande.",al={"varför ska man ta med deadmire's tooth","vem vill ha deadmire's tooth","varför vill melor ha tanden"}}},fp="16,212,17.420.0,34.155.0,38.141.0,46.202.0"}
P.entries["item:death-cap"] = {n="Death Cap",s="Death Cap är en sällsynt, kraftfull svamp som gömmer sig i den skuggiga grottan bakom Cliffspring Falls i Darkshore. Night Elf-al kemister söker den för dess unika egenskaper, men för att skörda den måste du bege dig in i ett underjordiskt näste som Grove of the Ancients har varnat för.",h="Death Cap är en sällsynt, kraftfull svamp som gömmer sig i den skuggiga grottan bakom Cliffspring Falls i...",kw={"auberdine","barithras moonshade","grottsvampar","cliffspring falls","darkshore","death cap","grove of the ancients","scaber stalk"},ang={["profession:Herbalism"]="Att samla in Death Cap åt Barithras kräver ingen yrkesmässig skära, men varje örtakännare förstår faran med att skörda sällsynta svampar i fuktiga, korrumperade underjordiska hålor.",["race:NightElf"]="Att hämta Death Cap tjänar två syften: det hjälper Barithras att tillverka drycker i Auberdine och bekräftar de dystra föraningar som Grove of the Ancients har uttryckt."},sec={{t="En giftig blomning i mörkret",b="Death Cap växer endast i grottans fuktiga underjordiska djup, bakom Cliffspring Falls längs Darkshores nordöstra bergsryggar. Till skillnad från de mer talrika Scaber Stalk som täcker grottgolvet i närheten är Death Cap sällsynt och utmärkande. Night Elf-örtakännare som Barithras Moonshade värdesätter svampen för experimentell bryggning, men att hämta ens ett enda exemplar kräver att man trotsar en grotta som sägs hysa en spirande korruption."},{t="Omen vid Cliffspring",b="Att skörda Death Cap är lika mycket ett spaningsuppdrag som ett alkemiskt ärende. Väktare från Grove of the Ancients varnade lokala Kaldorei för att närma sig vattenfallet, eftersom de kände en ondskefull närvaro slå rot i mörkret. Den som kliver in i grottan för att plocka svampen måste möta de krafter som lurar där och gjort den fuktiga hålan till sitt näste."}},faq={{q="Var hittar jag Death Cap?",a="Death Cap växer i den dolda grottan bakom Cliffspring Falls, vid bergsväggen i nordöstra Darkshore.",al={"death cap plats","var finns death cap","svamp i cliffspring-grottan"}},{q="Vem vill ha svampen?",a="Barithras Moonshade, en alkemist i kustbosättningen Auberdine, söker Death Cap för att brygga en specialiserad dryck.",al={"vem behöver death cap","barithras svampuppdrag"}},{q="Varför samlade inte Barithras Moonshade in den själv?",a="Trädväktare från Grove of the Ancients varnade Barithras för grottan bakom Cliffspring Falls, eftersom de kände att en annalkande ondska hade gjort grottan till sitt gömställe.",al={"varför hämtar han den inte själv","barithras varning"}},{q="Hur skiljer sig Death Cap från Scaber Stalk?",a="Scaber Stalk är relativt vanliga över hela Cliffspring-grottans golv, medan Death Cap är en mer sällsynt och kraftfull svamp som kräver noggrann spaning för att hitta.",al={"death cap jämfört med scaber stalk","skillnad mellan svampar"}}},fx={["508b05a0"]={q="Vad är Death Cap?",a="Death Cap är en ytterst sällsynt och kraftfull svamp som hittas djupt inne i Darkshores skuggiga vrår. Till skillnad från vanliga skogssvampar trivs den bara i särskilda, undangömda grottor, till exempel grottan bakom Cliffspring Falls. Det olycksbådande namnet vittnar både om dess sällsynthet och dess möjliga farlighet, vilket gör den till ett eftertraktat exemplar bland alkemister och örtmedicinare som studerar regionens unika växtliv.",al={"vad är death cap","svampen death cap","vilken sorts svamp är death cap"}}},fp="9,179,25.369.0,19.271.1,29.113.0,24.115.0,50.136.0,50.108.0"}
P.entries["item:deathstalker-report"] = {n="Deathstalker Report",s="Deathstalker Report är en skriftlig rapport, författad av Deathstalker Rane Yorick, som beskriver militär spaning i Silverpine Forest. Den innehåller viktig taktisk information om Scourges rörelser i området och tillståndet för Forsakens främsta spanare, avsedd för High Executor Hadrec i The Sepulcher.",h="Deathstalker Report är en skriftlig rapport, författad av Deathstalker Rane Yorick, som beskriver militär...",kw={"deathstalker report","hadrec","quinn","rane yorick","scourge","the sepulcher","silverpine forest"},ang={["class:Rogue"]="Att bära med sig information som samlats in av erfarna Deathstalkers ger en direkt inblick i det hemliga spaningsarbete som håller Forsakens militär funktionsduglig.",["race:Undead"]="Rapporten visar Deathstalkers skoningslösa effektivitet och den ständiga fara de står inför. De samlar in underrättelser och säkrar Lordaerons gränser åt Sylvanas."},sec={{t="Information från frontlinjen",b="Spaning i norra Silverpine Forest är ett livsfarligt uppdrag, även för de odöda. Efter att ha överraskats i ett bakhåll och blivit fastklämda av Scourge som strök omkring i tallskogarna, var Deathstalkers Rane Yorick och Quinn Yorick tvungna att sammanställa sina fynd i den här hastigt skrivna rapporten. Den sammanfattar oväntat starkt motstånd från Scourge, som hotar Forsakens territoriella ambitioner i regionen. Eftersom Quinn skadades svårt under uppdraget anförtros dokumentet åt förbipasserande allierade, så att High Executor Hadrec får besked i The Sepulcher utan dröjsmål."}},faq={{q="Vad är Deathstalker Report?",a="Det är en fältrapport sammanställd av Deathstalker Rane Yorick, som dokumenterar farorna, Scourges aktiviteter och hindren som Forsakens spanare möter i Silverpine Forest.",al={"vad är den här rapporten","deathstalker report i berättelsen","vad är deathstalker report"}},{q="Vem skrev rapporten?",a="Rapporten skrevs av Deathstalker Rane Yorick efter att hon tagit hand om sin skadade bror, Deathstalker Quinn, efter ett möte med Scourge i området.",al={"vem skrev deathstalker report","rapportens författare","vem skrev den"}},{q="Vem levereras rapporten till?",a="Den är adresserad till och levereras till High Executor Hadrec, Forsakens befälhavare vid The Sepulcher, som övervakar militära operationer i hela Silverpine Forest.",al={"vart ska rapporten","vem får rapporten","hadrecs rapport"}},{q="Varför behövs rapporten så brådskande?",a="High Executor Hadrec hade underskattat den enorma mängden Scourge i Silverpine Forest. Rapporten beskriver dessa fientliga styrkor och ger viktig information för att skydda Forsakens ockupationsinsatser.",al={"varför är den viktig","varför behöver hadrec den","vilken information finns i den"}}},fp="19,103,22.437.0,32.107.0,21.143.0,31.121.0,37.186.0"}
P.entries["item:deepfury-s-orders"] = {n="Deepfury's Orders",s="Deepfury's Orders är ett skrynkligt pergament som hittades på Ol' Rustlockes kropp under Thandol Span. Det innehåller mörka instruktioner tillhörande Dark Iron-dvärgarna som överföll den dvärglika försvararen på spaningsuppdrag.",h="Deepfury's Orders är ett skrynkligt pergament som hittades på Ol' Rustlockes kropp under Thandol Span.",kw={"dark iron","deepfury","order","rhag garmason","rustlocke","thandol span","wetlands"},ang={["faction:Alliance"]="De avlyssnade orderna avslöjar ett sabotageförsök mot den främsta landvägen mellan Dun Morogh, Wetlands och Alliansens norra utposter.",["race:Dwarf"]="Upptäckten av Dark Iron-dvärgarnas intriger under Thandol Span känns djupt för Ironforge-dvärgarna. Bron är ett av deras kungarikes största ingenjörsverk och en livsviktig nordlig handelsförbindelse."},sec={{t="Ett grepp under bron",b="När dvärgförsvararen vid bron, Ol' Rustlocke, spanade på Thandol Spans grund blev han trängd och dödad i ett plötsligt bakhåll av Dark Iron-dvärgar. Intill hans knutna näve låg dessa order, skrivna av fiendeledaren Deepfury. Dokumentet utgör ett direkt bevis på en samordnad plan riktad mot bron som förbinder Wetlands med Arathi Highlands."},{t="Hotet avslöjas",b="När du återför Deepfury's Orders till Rhag Garmason bekräftar det brons garnisons mörkaste misstankar. Dark Iron-dvärgarna har iscensatt avsiktliga operationer direkt under det storslagna stenverket i Thandol Span. Det är långt ifrån en slumpmässig skärmytsling och har lett till brådskande vädjanden om förstärkningar från Ironforge och Stormwind."}},faq={{q="Vad är Deepfury's Orders?",a="Det är skriftliga militärorder som tillhör Dark Iron-befälhavaren Deepfury. De hittades bredvid Ol' Rustlockes lik under Thandol Span.",al={"deepfurys order","vad är det här för order","deepfurys pergament"}},{q="Var hittades orderna?",a="Pergamentet hittades bredvid Ol' Rustlockes knutna näve, i de grottliknande bärande konstruktionerna under Thandol Span i norra Wetlands.",al={"var finns orderna","rustlockes plats","hitta deepfurys order"}},{q="Vem var Ol' Rustlocke?",a="Ol' Rustlocke var en dvärgspanare stationerad vid Thandol Span. Han gick ner för att undersöka märklig aktivitet kring brons bärande konstruktioner och överfölls av Dark Iron-dvärgar.",al={"vem är rustlocke","ol rustlockes historia"}},{q="Vem får Deepfury's Orders?",a="Orderna förs till Rhag Garmason, dvärgbefälhavaren som håller stånd vid Dun Modr nära Thandol Span. Han läser dem för att bedöma hotet från Dark Iron-dvärgarna.",al={"vem ska jag lämna orderna till","rhag garmason"}}},fx={["21094d89"]={q="Varifrån kommer Deepfury's Orders?",a="De här skriftliga orderna kommer från Dark Iron-klanen och är uppkallade efter Deepfury, en agent eller ledare som styr fientligheterna kring Thandol Span. De bars av Dark Iron-dvärgarna som överföll och mördade bergsbestigaren Ol' Rustlocke. Orderna lämnades kvar i jorden bredvid hans fallna kropp.",al={"vem skrev deepfury's orders","källan till deepfury's orders","vem utfärdade deepfury's orders"}},ac08f373={q="Varför vill Rhag Garmason ha Deepfury's Orders?",a="Rhag Garmason behöver konkreta bevis på vad som hände med hans försvunne spejare, Ol' Rustlocke. Pergamentet bekräftar dystert bergsbestigarens död och avslöjar de fientliga planer som Dark Iron-dvärgarna smider nära bron.",al={"varför ta med deepfury's orders till rhag","varför vill man ha deepfury's orders","rhag garmasons order"}}},fp="17,190,24.334.0,21.249.1,27.164.0,27.156.0,22.170.0,31.162.0"}
P.entries["item:deepmoss-egg"] = {n="Deepmoss Egg",s="I Stonetalon Mountains lockar Deepmoss Eggs till sig goblinhandlare från Ratchet. Deepmoss-spindlar lägger täta kullar i klippor och raviner, och piraterna i Booty Bay värdesätter dem till omeletter.",h="I Stonetalon Mountains lockar Deepmoss Eggs till sig goblinhandlare från Ratchet.",kw={"booty bay","deepmoss egg","djupmossespindel","mebok mizzyrix","ratchet","sishir canyon","stonetalon","windshear crag"},ang={["profession:Cooking"]="Som kock kanske du tvekar inför att använda spindelägg, men matgästerna i Booty Bay värdesätter uppvispade ägg som en äventyrlig delikatess och betalar goblinpriser för dem."},sec={{t="En delikatess från klipporna",b="Deepmoss-spindlar bygger bon över hela Stonetalon Mountains, särskilt i Sishir Canyon och under de överlevande träden i Windshear Crag. De lämnar täta kullar med livskraftiga ägg i tjocka, nätspunna säckar, skyddade av fuktig bergsmossa. De flesta resenärer har liten nytta av dem, men goblinhandlare ser en chans att göra vinst."},{t="En mattrend i Booty Bay",b="I Booty Bay har omeletter på spindelägg blivit en säregen kulinarisk fluga bland rika pirater och äventyrslystna matgäster. De lokala förråden räcker inte för att stilla deras aptit, så Mebok Mizzyrix från Ratchet ordnar leveranser genom Wharfmaster Dizzywig. Samlare trotsar de giftiga spindelkullarna i Stonetalon för att hämta färska äggsamlingar, som blir värdefull last."}},faq={{q="Var hittar man Deepmoss Eggs?",a="Deepmoss Eggs finns i Stonetalon Mountains, nordväst om The Barrens. Äggsamlingar ligger under de överlevande träden i Windshear Crag och djupare in i Sishir Canyons giftiga hålor.",al={"äggens platser","var hittar man deepmoss eggs","deepmoss egg plats"}},{q="Vem vill samla in äggen?",a="Mebok Mizzyrix, en goblinhandlare i Ratchet, anlitar samlare för att hämta Deepmoss Eggs. Han ordnar så att Wharfmaster Dizzywig skeppar äggsamlingarna över havet.",al={"vem behöver deepmoss eggs","vem köper deepmoss eggs","mebok mizzyrix uppdrag"}},{q="Vad används äggen egentligen till?",a="Äggen skickas till Booty Bay, där omeletter på spindelägg har blivit en populär, om än bisarr, kulinarisk fluga bland pirater och andra matgäster.",al={"användning av spindelägg","varför samla spindelägg","spindelomeletter"}},{q="Varför varnas man för Sishir Canyon när man samlar äggen?",a="Sishir Canyon är en yngelplats full av vuxna spindlar, nät och uppätna byten. Mebok råder alla med känslig mage att i stället samla ägg under de glesa träden i Windshear Crag.",al={"varning för sishir canyon","känslig mage sishir"}}},fx={["19ff336a"]={q="Vad är ett Deepmoss Egg?",a="Ett Deepmoss Egg är ett ägg ur en kull från deepmoss-spindlarna i Stonetalon Mountains. Äggen ligger samlade under träd och djupt inne i bergsklyftor. Framför allt våghalsiga äventyrare samlar in de silkessvepta äggen för att tjäna pengar på märkliga matmarknader på andra sidan havet.",al={"vad är deepmoss eggs","deepmoss egg","deepmoss eggs"}},["80df5d4f"]={q="Varifrån kommer Deepmoss Eggs?",a="Äggen läggs av deepmoss-spindlarna som härjar bland Stonetalon Mountains klippor och dalar, särskilt vid Windshear Crag och den förrädiska Sishir Canyon. De läggs naturligt i kullar nära kvarvarande trädrötter och spindelbon, inte tillverkas av någon tänkande dödlig.",al={"deepmoss eggs ursprung","varifrån kommer deepmoss eggs","vem lägger deepmoss eggs"}}},fp="12,192,23.318.0,24.335.0,30.190.0,32.161.0,36.132.0,54.195.0"}
P.entries["item:defias-docket"] = {n="Defias Docket",s="Defias-agenter har gömt sina order på Addle's Stead i västra Duskwood. Dokumenten ger Stormwinds sökande efter sitt försvunna sändebud ett spår till Brotherhoods planer.",h="Defias-agenter har gömt sina order på Addle's Stead i västra Duskwood.",kw={"addle's stead","defias docket","defias-kassaskrin","duskwood","elling trias","den försvunna diplomaten","watcher backus"},ang={["class:Rogue"]="Som skurk kan du se hur Defias Brotherhood använder chiffer och hemlig logistik bakom fasaden av vanlig laglöshet.",["faction:Alliance"]="Som medlem av Alliansen kan du se att dokumenten avslöjar en samordnad Defias-sammansvärjning som sträcker sig långt bortom vanligt banditliv."},sec={{t="Ett spår in i mörkret",b="Mästare Elling Trias pekar ut Duskwood för utredarna när de följer spår efter kungarikets försvunna diplomat. Watcher Backus har lagt märke till ovanliga Defias-rörelser som samlas vid Addle's Stead, den övergivna gården söder om vägen från Westfall. En kassaskrin på gården innehåller Defias Docket. Dokumenten följer Brotherhoods rörelser och avslöjar verksamhet som sträcker sig längre än vägrån och lokalt banditliv."},{t="Sammansvärjningens nät",b="Dokumenten visar sig vara så invecklade och politiskt farliga att Watcher Backus vägrar behålla dem. Han fruktar ett strängt straff från sina överordnade om de ertappar honom med dokumenten. Tillbaka i Trias ostbutik i Stormwind City avslöjar dokumenten en omfattande kidnappningsplan med stora resurser från Defias. De nämner också aktörer i undre världen, däribland en med kodnamnet ”Fist”."}},faq={{q="Vad är Defias Docket?",a="Defias Docket är en bunt officiella order och dokument som tillhör Defias Brotherhood. Den beskriver deras planer och hemliga operationer kring Duskwood och Westfall.",al={"vad är dokumenten","defias-dokument","försvunna diplomaten dokument"}},{q="Var hittar man Defias Docket?",a="Du hittar dokumenten inlåsta i en Defias-kassaskrin på den förfallna gården vid Addle's Stead, söder om vägen från Westfall in i västra Duskwood.",al={"dokumentens plats","var hittar man defias docket","addle's stead dokument"}},{q="Varför förvarades dokumenten i Duskwood?",a="Defias-agenter använde Addle's Stead som en avlägsen utpost mellan Westfall och Duskwood. Där samordnade de en operation av hög prioritet, utom räckhåll för Stormwinds främsta patruller.",al={"varför är det i duskwood","defias vid addle's stead"}},{q="Vem analyserar dokumenten?",a="Watcher Backus granskar dokumenten en kort stund och skickar dem sedan till Elling Trias i Stormwind City. Trias privata underrättelsenätverk är specialiserat på att tyda hemliga meddelanden från undre världen.",al={"vem får dokumenten","vem läser dokumenten"}}},fx={b7a864a3={q="Varifrån kommer Defias Docket, och vem har gjort det?",a="Defias Brotherhood har själva upprättat den här officiella samlingen dokument. Den beskriver deras hemliga planer och samordnar agenter i olika regioner. Brödraskapets agenter gömde dokumenten säkert i en kassakista på Addle's Stead, en stillsam gård strax över gränsen till Duskwood, där brödraskapets medlemmar samlades innan du hittade dem.",al={"vem skrev defias docket","defias dockets ursprung","varifrån kommer dokumentet"}},["4693de43"]={q="Varför vill någon ha Defias Docket?",a="Utredare som söker efter den försvunne diplomaten behöver konkreta bevis på konspirationen. Watcher Backus inser att dokumentet är alldeles för detaljerat för att vara en enkel skenmanöver. Elling Trias i Stormwind använder innehållet för att avslöja brödraskapets hemliga planer, däribland hänvisningar till nyckelpersoner som ”Fist”.",al={"varför är dokumentet viktigt","varför vill man ha defias docket","vem vill ha defias docket"}}},fp="13,178,21.413.0,21.383.1,26.174.0,33.154.0,36.181.0,24.189.0"}
P.entries["item:defias-tower-key"] = {n="Defias Tower Key",s="Vid Klaven's Tower i Westfall visar Defias Tower Key att en infiltratör nått den bevakade gränsen. Stormwinds agenter försöker få tag på den från de missbildade drönarna utanför.",h="Vid Klaven's Tower i Westfall visar Defias Tower Key att en infiltratör nått den bevakade gränsen.",kw={"agent kearnen","defias tower key","duskwood chest","klaven mortwake","klaven's tower","missbildad defias-drönare","mathias shaw","si:7"},ang={["class:Rogue"]="Som skurk som arbetar med SI:7 måste du använda smygande och ficktjuveri för att få tag på Defias Tower Key, samtidigt som du håller dödliga gifter i åtanke.",["faction:Alliance"]="Som medlem av Alliansen hjälper du Stormwind att undersöka Defias Brotherhoods märkliga leveranser från Duskwood genom att säkra underrättelser från Klaven's Tower."},sec={{t="Ett pris från den förvridna vakten",b="Klaven's Tower står vid Westfalls kust som ett fäste för Defias Brotherhood. Nya leveranser från Duskwood har fört nya vakter till området: missbildade Defias-drönare, odöda och täckta av taggar. SI:7-agenter håller uppsikt över området och ber fältagenter att länsa fickorna på dessa vaktposter. Att möta dem i strid är inte rätt sätt att bevisa att gränsen har passerats. Nyckeln visar att en infiltratör tog sig igenom utan att slå larm."},{t="Avslöja kopplingen till Duskwood",b="Nyckeln leder till en kista inuti Klaven's Tower, förseglad med leveranser från Duskwood. I kistan finns Klaven Mortwake's Journal. När dagboken når Master Mathias Shaw i Stormwind avslöjar den en konspiration som går längre än vanliga vägrån. Defias har gått samman med Venture Company för att smuggla specialiserade trollgifter som upptäckts av Zanzil the Outcast. Blandningarna kan väcka de döda, vilket förklarar de groteska, hostande vidundren runt tornet."}},faq={{q="Hur får du tag på Defias Tower Key?",a="Du måste ficktjuva en av de missbildade Defias-drönarna som vaktar Klaven's Tower i Westfall. Nyckeln kan inte tas från en besegrad fiende.",al={"var får jag tag på nyckeln","hur får man defias tower key","vem tappar defias tower key"}},{q="Vad öppnar Defias Tower Key?",a="Nyckeln låser inte upp tornets dörr eller Duskwood Chest där inne. Master Mathias Shaw behöver den som bevis på att en agent infiltrerat området obemärkt.",al={"öppnar den duskwood chest","vilken dörr öppnar den","vad låser defias key upp"}},{q="Vad är de missbildade Defias-drönarna som vaktar tornet?",a="De är groteska, taggiga odöda vakter runt Klaven's Tower. Agent Kearnen vet inte vad som skapat dem och ber agenter att undersöka leveransen de vaktar.",al={"vem har nyckeln","vad är tornvakterna","vad är den taggiga zombien"}},{q="Vem skickar agenter för att hämta den här nyckeln?",a="Agent Kearnen, en SI:7-spejare som håller uppsikt över Klaven's Towers gräns, ger fältskurkar i uppdrag att skaffa nyckeln och hämta innehållet i Duskwood Chest åt Master Mathias Shaw i Stormwind.",al={"vem ger uppdraget","vem vill ha nyckeln"}}},fx={a3164c95={q="Vad är Defias Tower Key?",a="Det är en järnnyckel som bärs av de groteska vakterna kring Klaven's Tower i Westfall. SI:7-agenten Agent Kearnen såg den hos det taggiga odöda vidundret som vaktar platsen och identifierade den som ett viktigt bevis på Defias Brotherhoods hemliga verksamhet vid befästningen.",al={"defias tower key","vad är defias tower key","defias-nyckel"}},["2bb6b303"]={q="Varför vill SI:7 ha Defias Tower Key?",a="Master Mathias Shaw och Agent Kearnen behöver att agenter från skurkarnas led säkrar nyckeln när de infiltrerar tornet för att undersöka mystiska leveranser från Duskwood. Om du för tillbaka den bevisar du att du lyckats ta dig igenom bevakningen och hämta de mörka hemligheter som låsts in i Klaven Mortwakes fäste.",al={"varför hämta defias tower key","vem vill ha defias tower key","varför hämta defias-nyckeln"}}},fp="16,168,30.445.0,34.457.1,39.138.0,36.165.0,56.166.1,42.182.0"}
P.entries["item:deliah-s-ring"] = {n="Deliah's Ring",s="Deliah's Ring är ett graverat smycke som återfanns i en hög med lik som Rot Hide-gnollerna samlat i Silverpine Forest. Minnesgåvan bär inskriften ”For Deliah” och leder längs ett mörkt spår tillbaka till ett pestoffer som rövats från Tirisfals massgravar.",h="Deliah's Ring är ett graverat smycke som återfanns i en hög med lik som Rot Hide-gnollerna samlat i...",kw={"brill","deliah","deliah's ring","graverad ring","fenris isle","hadrec","magistrate sevren","rot hide-gnoller"},ang={["race:Undead"]="Ringen visar den bistra verkligheten i Forsaken-tillvaron: dödliga band ruttnar ofta bort tillsammans med köttet, även om några få fortfarande håller fast vid minnet av dem de älskade i livet."},sec={{t="En minnesgåva i träsket",b="Ringen upptäcktes på en knotig, relativt färsk hand från ett lik bland gnollhögarna i Silverpine Forest. Den bär den enkla inskriften ”For Deliah”. Fyndet avslöjar att de lokala Rot Hide-gnollerna inte bara plundrar slagfält, utan aktivt räder Tirisfal Glades massgravar och för mänskliga lik och Forsaken-lik söderut till Fenris Isle för sina egna avskyvärda syften."},{t="Band till Brill",b="När föremålet förs till Forsaken-myndigheterna skickar High Executor Hadrec det vidare till Brill, där Magistrate Sevren för register över de nyligen avlidna. Sevren bekräftar att Deliah bodde i Brill innan hon dog av pesten och begravdes där, innan gravplundrare grävde upp hennes kvarlevor. Spåret efter ringen blottar den kvarvarande sorgen hos dem hon lämnade bakom sig och prövar om dödlig hängivenhet kan överleva övergången till odödlighet."}},faq={{q="Var hittar man Deliah's Ring?",a="Ringen upptäcks under undersökningar av Rot Hide-gnollernas högar i norra Silverpine Forest. Den sitter på handen till ett osvept pestoffer bland de plundrade döda.",al={"var hittar man deliahs ring","deliahs rings plats","hur får man deliahs ring"}},{q="Vem var Deliah?",a="Deliah var en tidigare invånare i Brill som dog av pesten. Hennes kropp begravdes i de lokala massgravarna innan Rot Hide-gnollerna stal den och släpade den till Silverpine Forest.",al={"vem är deliah","deliahs historia","deliah från brill"}},{q="Varför hade Rot Hide-gnollerna hennes kropp?",a="De plågebundna Rot Hide-gnollerna har plundrat Tirisfal Glades gemensamma gravar, samlat på sig lik och fört dem mot sitt fäste på Fenris Isle.",al={"varför stjäl gnoller kroppar","rot hide stjäl lik","vad gör gnollerna med lik"}},{q="Vad står det på ringen?",a="På ringens insida är orden ”For Deliah” ingraverade, vilket visar att den var en personlig gåva från en älskare eller make innan hon dog.",al={"ringens gravyr","vad står det på ringen","for deliah ring"}}},fx={c1c1eafc={q="Vad är Deliah's Ring?",a="Deliah's Ring är ett graverat personligt smycke som hittades på handen av en avliden kvinna bland Rot Hide-gnollerna i Silverpine Forest. Med den enkla inskriptionen ”Till Deliah” är det ett sällsynt, kvarvarande tecken på kärlek och liv från Lordaeron innan pesten slog till.",al={"vad är deliah's ring","deliah's ring historia","om deliah's ring"}},a38bd9ea={q="Varför vill man ha Deliah's Ring?",a="High Executor Hadrec ser ringen som ett viktigt bevis för att Rot Hide-gnollerna plundrar massgravar i Tirisfal Glades efter färska lik. Utöver denna militära ledtråd kan ringen hjälpa till att identifiera den döda kvinnan genom Brills register, och ge en möjlighet att ta reda på vem som en gång älskade henne och om den personen fortfarande lever.",al={"varför behålla deliah's ring","vem vill ha deliah's ring","varför lämna in deliah's ring"}}},fp="13,212,22.357.0,13.355.1,29.148.0,15.162.0,42.172.0,36.123.0"}
P.entries["item:delivery-to-mathias"] = {n="Delivery to Mathias",s="Keryn Sylvius skickar ett förseglat paket från Goldshire till Master Mathias Shaw i Stormwind. Leveransen ger en lovande skurk en inblick i SI:7:s inre verksamhet.",h="Keryn Sylvius skickar ett förseglat paket från Goldshire till Master Mathias Shaw i Stormwind.",kw={"delivery to mathias","goldshire","keryn sylvius","mathias shaw","old town","paket","si:7","stormwind"},ang={["class:Rogue"]="Som skurk bär du ett paket som markerar vägen från enklare grändslagsmål till kunglig underrättelsetjänst under Mathias Shaw.",["faction:Alliance"]="Som Alliance-agent för du hemliga meddelanden mellan regionala spejare och huvudstaden och hjälper Stormwinds hemlighetsfulla spionageapparat att bekämpa inre omstörtning."},sec={{t="Ett kurirprov",b="Ett paket från Lion's Pride Inn till Stormwind Barracks kan verka som ett vanligt kuriruppdrag. För en blivande skurk är det en audition för Stormwind Intelligence. Den lokala tränaren Keryn Sylvius anförtror paketet åt novisa ficktjuvar och ger dem en direkt introduktion till Master Mathias Shaw. Leveransen prövar om de kan ta sig genom huvudstaden obemärkt, hålla låg profil och följa diskreta order utan att ställa frågor."},{t="Porten till SI:7",b="Överlämningen för in en agent i SI:7:s högkvarter i Old Town. Mathias Shaw använder sådana leveranser för att skilja bedragare från verkliga talanger. De som överlämnar paketet utan att tveka får viktiga fältuppdrag, med början i hemlig spaning och infiltration av Defias smugglarnätverk i Elwynn Forest."}},faq={{q="Vad finns i Delivery to Mathias?",a="Paketet förblir förseglat för kuriren. Det kan innehålla underrättelserapporter, bedömningar av rekryter eller konfidentiellt material om lokala hot som Defias Brotherhood i Elwynn.",al={"vad finns i paketet","leveransens innehåll","paketets innehåll"}},{q="Vem skickar den här leveransen?",a="Keryn Sylvius lämnar över leveransen. Hon är en agent och tränare inom skurkarnas led, stationerad på övervåningen i Lion's Pride Inn i Goldshire.",al={"vem gav mig paketet","paketets avsändare","keryn sylvius paket"}},{q="Var har Mathias Shaw sitt högkvarter?",a="Mathias Shaw har sitt högkvarter på andra våningen i SI:7-byggnaden, i det sydöstra hörnet av Old Town inom Stormwind Barracks-området.",al={"var är mathias shaw","vart ska paketet levereras","shaws plats"}},{q="Vad händer efter att paketet överlämnats till Shaw?",a="När Shaw har bekräftat din förmåga inviger han dig i fältspioneri och skickar dig för att infiltrera Jerod's Landing. Där stjäl du en frakttidtabell från en Defias-hamnarbetare.",al={"nästa uppdrag efter leveransen","vad gör shaw","efter delivery to mathias"}}},fx={["1dd6c783"]={q="Vad är Delivery to Mathias?",a="Det är ett förseglat paket som Keryn Sylvius, skurkarnas tränare i Goldshire, anförtror åt dig. Det överlämnas som ett ärende, men är främst en introduktion och ett kompetensprov inför Master Mathias Shaw vid SI:7:s högkvarter i Stormwind.",al={"vad är delivery to mathias","delivery to mathias paket","keryn sylvius paket"}},["2bd7511f"]={q="Varför vill Mathias Shaw ha leveransen?",a="Master Mathias Shaw leder SI:7, Stormwinds underrättelseorganisation, och Keryn Sylvius fick i uppdrag att förmedla uppdrag och lovande rekryter till honom. När du bär paketet säkert till Old Town visar du att du kan följa hemliga instruktioner och hantera känsliga uppdrag åt kronans spionmästare.",al={"varför vill shaw ha leveransen","varför leverera paket till mathias","varför vill mathias ha det"}}},fp="19,158,16.428.0,15.335.0,39.181.0,24.132.0,46.156.0,49.182.1"}
P.entries["item:deviate-hide"] = {n="Deviate Hide",s="Deviate Hide är muterade hudar från bestarna i Wailing Caverns. Druider söker dessa främmande skinn, förvridna av Naralexs korrumperade dröm, för att göra slitstarka lädervaror av mardrömmens smitta.",h="Deviate Hide är muterade hudar från bestarna i Wailing Caverns.",kw={"the barrens","deviate hide","läder","nalpak","naralex","mardröm","skinn","wailing caverns"},ang={["class:Druid"]="För druider innebär insamlingen av deviate-hudar en skoningslös konfrontation med Emerald Nightmares korrumperande makt över naturen, även om lärjungar som Nalpak försöker rena de korrumperade materialen och använda dem för att överleva."},sec={{t="Mardrömmens besmittade skinn",b="När nattalvdruiden Naralex föll i djup sömn under The Barrens förvandlades hans dröm till en Emerald Nightmare som förvrängde grottans ekosystem. Bestarna som lurade i djupet förvandlades till onaturliga deviate-rovdjur med hårda, muterade hudar. Skinnen är märkta av ondska, men har en ovanlig och smidig tålighet som gör dem särskilt lämpade för läderhantverk. Nalpak, som håller till högt ovanför grottöppningen i den dödskalleformade klippan, samlar in hudarna för att studera deras egenskaper och göra dem till tåliga bruksryggsäckar."}},faq={{q="Vad skiljer deviate-hudar från vanligt läder?",a="Deviate-hudar kommer från varelser som förvridits av Emerald Nightmare, som sipprar ut från Naralexs sömn. Fördärvet förändrar deras kött och ger det en märklig, främmande tålighet och elasticitet som vanliga djurhudar saknar.",al={"deviate hide-lore","varför är deviate-hudar märkliga","deviate-skinnens natur"}},{q="Vem samlar in hudarna?",a="Nalpak, en lärjunge till Naralex som slagit läger i grottan i ögonhålan ovanför ingången till Wailing Caverns, söker efter skinnen. Han tror att material från de onda deviate-bestarna kan renas och formas till användbara lädervaror.",al={"vem vill ha deviate-hudar","nalpak hudar","vem behöver deviate hide"}},{q="Var hittar man deviate-hudar?",a="De tas från de olika deviate-bestarna som stryker omkring i Wailing Caverns under The Barrens, däribland rovfåglar, huggormar, krokilisker och dreadfangs.",al={"var droppar deviate-hudar","hur får man tag på deviate-hudar"}}},fx={["8b5833f5"]={q="Var kommer Deviate Hide ifrån, och vem har tillverkat det?",a="Deviate-hudar kommer från de märkliga, förvridna bestar som strövar djupt inne i Wailing Caverns. Dessa varelser skapades inte av dödliga händer. De uppstod i stället under The Barrens och muterades av den fasansfulla mardröm som uppslukade druiden Naralex när han föll i djup sömn. Den onaturliga fördärvningen förändrade den inhemska faunan och gav dess skinn främmande, övernaturliga egenskaper.",al={"varifrån kommer deviate-hudar","deviate hide ursprung","vem har tillverkat deviate hide"}}},fp="12,267,30.569.0,56.225.0,30.260.0,30.158.0"}
P.entries["item:devlin-s-remains"] = {n="Devlin's Remains",s="Devlin's Remains är de samlade skelettdelarna från Devlin Agamand, den yngre sonen i den förmögna familj som ägde Agamand Mills. Som en viljelös Scourge-träl strök han omkring på vägarna nära familjens förfallna gods. Han fälldes så att hans ben kunde lämnas till en hämndlysten överlevare i Brill.",h="Devlin's Remains är de samlade skelettdelarna från Devlin Agamand, den yngre sonen i den förmögna familj som...",kw={"agamand mills","brill","coleman farthing","devlin agamand","devlin's remains","de hemsökta kvarnarna","tirisfal glades"},ang={["race:Undead"]="För Forsaken står Agamands för Lordaerons gamla, privilegierade adel, vars misslyckanden lämnade vanligt folk att dö och återuppstå som monster. Skändningen av Devlins kvarlevor blir därmed en hämnd från underklassen."},sec={{t="Ett bittert arv",b="I livet levde Devlin Agamand i skuggan av sin äldre bror Thurman. Thurman var mild och lång, medan Devlin mindes som fysiskt bräcklig och vass i tungan. När Plague of Undeath svepte genom norra Tirisfal Glades misslyckades familjen Agamand med att skydda sina marker och arbetare. Devlin var en av de första som föll. Han återuppväcktes som en glupsk Scourge-ghoul vars hetsiga, vansinniga pladder hemsökte vägkanten på vägen upp mot Agamand Mills."},{t="Hämnd på spiselkransen",b="Coleman Farthing, en Forsaken som bor i Brill, hyser ett djupt och varaktigt agg mot hela Agamand-släkten. Han håller dem direkt ansvariga för att de inte räddade hans familj när pesten kom, och gav resande i uppdrag att låta Devlin vila och samla in hans kvarlevor. Farthing ville visa upp Devlins ben på sin spiselkrans och njuta av vetskapen om att hans forna herrar reducerats till stoft och krossade fragment under hans häl."}},faq={{q="Vem var Devlin Agamand i livet?",a="Devlin var den yngre sonen i familjen Agamand, de rika jordägarna som byggde Agamand Mills i norra Tirisfal Glades. Till skillnad från sin milda och bredaxlade bror Thurman var Devlin svag, sjuklig och beryktat hetlevrad, känd för sin bittra och vassa tunga.",al={"vem är devlin","devlin agamands bakgrund","om devlin"}},{q="Varifrån samlades Devlins kvarlevor?",a="De togs från Devlin Agamands Scourge-kontrollerade lik, som låg strax söder om Agamand Mills längs vägen genom Tirisfal Glades.",al={"var är devlin","var hittar man devlin","devlin agamands plats"}},{q="Varför vill Coleman Farthing ha benen?",a="Coleman Farthing avskyr familjen Agamand och anser att de övergav och svek honom och hans närstående när Plague bröt ut. Han tänker montera Devlins ben på spiselkransen i Brill som en trofé för hämnd och tillfredsställelse.",al={"varför farthing vill ha kvarlevorna","coleman farthings motiv","varför samla agamandben"}},{q="Tillhör Devlin Forsaken?",a="Nej. När Devlin föll offer för Plague gick hans sinne helt förlorat till Scourge. Han irrade omkring vid kvarnarna som en viljelös odöd ghoul och babblade vansinnigt tills han förstördes.",al={"är devlin forsaken","var devlin scourge"}}},fx={["0d9d3e5c"]={q="Vad är Devlin's Remains?",a="Devlin's Remains är skelettbenen efter Devlin Agamand, den yngre sonen i den framstående Agamand-dynastin. Efter att ha fallit offer för de odödas pest förvandlades Devlin till en tanklös Scourge-varelse som irrade längs vägen till familjens förstörda kvarnar, tills han dräptes och samlades in.",al={"vad är devlin's remains","devlin remains föremål","vem är devlin's remains"}}},fp="16,292,15.413.0,23.360.0,31.253.0,42.123.0,43.211.0,31.148.0"}
P.entries["item:dirt-caked-pendant"] = {n="Dirt-Caked Pendant",s="I The Barrens ger en tillfångatagen orch ifrån sig Dirt-Caked Pendant som han bar. Minnessaken når Gan'rul Bloodeye i Orgrimmar, där den används för att dra till sig en succubus.",h="I The Barrens ger en tillfångatagen orch ifrån sig Dirt-Caked Pendant som han bar.",kw={"själarnas slukare","dirt-caked pendant","dogran","gan'rul bloodeye","kärlekens gåva","succuba","zankaja"},ang={["class:Warlock"]="Som häxmästare under utbildning ser du hur dödligas sorg och hängivenhet kan hjälpa dig att befalla demoner från Twisting Nether.",["race:Orc"]="Som orch ser du Dograns bitterljuva val: han vägrar att bli en börda för sin klan och livspartner som krympling och ger upp sin minnessak för att göra en krigares sista motstånd."},sec={{t="En tragisk minnessak",b="Dogran ger ifrån sig Dirt-Caked Pendant medan han hålls fången i The Barrens. Förgiftad och så svårt skadad att han inte kan återhämta sig kommer han inte att återvända till sin livspartner, Zankaja, som en börda. Han väljer i stället att dö kämpande mot sina fångvaktare. Hänget bär på hans outtalade kärlek till henne. En häxmästare tar minnessaken till Orgrimmar, där häxmästarna i Cleft of Shadow använder dess hjärtesorg och hängivenhet."},{t="Lockbete för en demon",b="I Cleft of Shadow ser Gan'rul Bloodeye hur hänget kan dra till sig en succubus. Dessa demoner dras till dödligas längtan, romantik och tragedi. Häxmästaren rengör och polerar Dogran's Pendant tills det glänser och förvandlar en symbol för hängiven kärlek till ett lockbete. Sedan kallar häxmästaren fram en succubus för att möta den i rituell strid och kuva den."}},faq={{q="Var kommer det leriga smycket ifrån?",a="Dogran, en tillfångatagen orchkrigare i The Barrens, räcker dig hänget när du har gett honom Ken'zigla's Draught och väckt hans sinnen till liv.",al={"smyckets ursprung","var får jag smycket","vem ger smycket"}},{q="Vad har smycket med Zankaja att göra?",a="Zankaja är Dograns livspartner i Orgrimmar. Han ger upp hänget och döljer att han överlevde, så att hon slipper ta hand om honom som en invalidiserad krigare.",al={"vem är zankaja","dogran och zankaja","smyckets betydelse"}},{q="Varför behöver Gan'rul Bloodeye just det här smycket?",a="Succubi dras till starka känslor hos dödliga, särskilt romantik, hjärtesorg och hängivenhet. När Dogran's Pendant har rengjorts kan det fokusera kallelsen som lockar en succubus in i åkallandecirkeln.",al={"varför behövs smycket","smycke som lockbete för succuba","gan'rul bloodeyes smycke"}},{q="Vad händer när smycket har förts till Orgrimmar?",a="När du har överlämnat hänget i Orgrimmar rengör Gan'rul Bloodeye det och använder dess dragningskraft för att inleda The Binding. En succubus lockas in i cirkeln under Cleft of Shadow, där du ska besegra och kuva den.",al={"vad händer sedan med smycket","vad gör jag med smycket"}}},fx={cbd86f91={q="Vad är Dirt-Caked Pendant?",a="Dirt-Caked Pendant är ett anlöpt minnessmycke som bars av den tillfångatagna orchen Dogran. Det gavs som ett tecken knutet till hans livskamrat Zankaja och bär på starka känslor av kärlek och längtan – precis de egenskaper en häxmästare behöver när han förbereder sig för att locka till sig och kuva en succubus.",al={"vad är dirt-caked pendant","dirt-caked pendant historia","vad är dirt-caked pendant för slags föremål"}}},fp="18,162,14.386.1,16.338.1,44.129.0,44.149.1,53.191.0,57.209.1"}
P.entries["item:disarming-colloid"] = {n="Disarming Colloid",s="Disarming Colloid är ett specialiserat kemiskt ämne som motverkar det explosiva Seaforium-krutets instabilitet. Dvärgen Ashlan Stonesmirk i Wetlands tillhandahåller det som den avgörande stabiliserande beståndsdelen i en neutraliserande blandning, avsedd att förhindra en katastrofal sprängning av Stonewrought Dam.",h="Disarming Colloid är ett specialiserat kemiskt ämne som motverkar det explosiva Seaforium-krutets...",kw={"ashlan stonesmirk","dark iron","disarming colloid","sprängämnen","hinderweir","seaforium","stonewrought dam","wetlands"},ang={["profession:Engineering"]="Ingenjörer känner igen Seaforium som en avancerad sprängämnesblandning med enorm förstörelsekraft. Den kräver exakta kemiska motmedel som den här kolloiden, snarare än primitiv mekanisk oskadliggöring.",["race:Dwarf"]="Upptäckten av Seaforium riktat mot Stonewrought Dam är ett direkt hot mot dvärgarnas ingenjörsmästerverk och säkerheten i Loch Modan ovanför."},sec={{t="Ett kemiskt neutraliseringsmedel",b="När Ashlan Stonesmirk analyserade det ovanliga sprängkrut som Dark Iron-sprängexperter lämnat vid Stonewrought Dam i Loch Modan kände han genast igen det på dess tydliga doft och fina silverkristaller: Seaforium. Seaforium är ofarligt när det är helt torrt, men blir oerhört destruktivt vid kontakt med fukt. Därför utgör det ett existentiellt hot mot den vattenmättade Stonewrought Dam. För att hejda reaktionen innan en detonation sker tillhandahöll Stonesmirk en neutraliserande kolloid. När den blandas med tre särskilda lokala ingredienser — lurker-gift, krossad Mo'grosh Crystal och en crocolisk-tår — neutraliserar kolloiden effektivt Seaforium-blandningens explosiva egenskaper."}},faq={{q="Vad används Disarming Colloid till?",a="Det är det grundläggande kemiska ämne som behövs för att oskadliggöra Seaforium-krut. När det blandas med lurker-gift, krossad Mo'grosh Crystal och en crocolisk-tår neutraliserar det den instabila reaktion som annars skulle orsaka en katastrofal explosion när Seaforium blir vått.",al={"kolloidens syfte","vad gör disarming colloid","neutraliseringsmedel för seaforium"}},{q="Vem skapade eller tillhandahöll kolloiden?",a="Den neutraliserande kolloiden tillhandahålls av Ashlan Stonesmirk, en sprängämnesexpert som tjänstgör vid regementet som vaktar Dun Modr i Wetlands. Han har genomskådat Dark Iron-dvärgarnas plan att spränga Stonewrought Dam.",al={"vem ger kolloiden","ashlan och kolloiden"}},{q="Varför är Seaforium så farligt i Wetlands?",a="Seaforium-krut är kemiskt inert när det är torrt, men kontakt med fukt gör det våldsamt explosivt. Eftersom Wetlands är vattenmättat och målet är själva Stonewrought Dam innebär fuktigt Seaforium ett omedelbart hot om omfattande förödelse.",al={"varför är seaforium farligt","vått seaforium"}},{q="Vem ska kolloiden levereras till?",a="Ashlan Stonesmirk säger att kolloiden och nyheten om Seaforium-planen genast ska skyndas direkt till Chief Engineer Hinderweir vid Stonewrought Dam.",al={"vem ska jag lämna kolloiden till","lämna in kolloiden"}}},fx={["6b4ad5ab"]={q="Vad är Disarming Colloid?",a="Disarming Colloid är en specialblandning för neutralisering, tillredd av Ashlan Stonesmirk. När den blandas med tre andra kraftfulla reagenser – Lurker Venom, krossad Mo'grosh Crystal och en Crocolisk Tear – oskadliggör den säkert den flyktiga kemiska reaktionen i Seaforium-sprängpulver, innan fukt kan utlösa den explosiva blandningen.",al={"vad är disarming colloid","disarming colloid föremål","colloid historia"}},["1c3f9fc5"]={q="Varför behövs Disarming Colloid?",a="Chefingenjör Hinderweir behöver omedelbart kolloiden för att avvärja en katastrof vid Stonewrought Dam i Loch Modan. Dark Iron-sabotörer har placerat flyktigt Seaforium vid dammen. Utan detta kemiska medel för att oskadliggöra reaktionen kan kontakt med vatten spränga dammen i bitar.",al={"varför behövs disarming colloid","varför vill man ha colloid","vem vill ha disarming colloid"}}},fp="17,180,22.493.0,35.197.0,37.202.0,46.212.0,38.136.0"}
P.entries["item:disarming-mixture"] = {n="Disarming Mixture",s="Disarming Mixture är en specialblandad kemisk lösning som Chief Engineer Hinderweir tillreder vid Stonewrought Dam. Den har skapats för att neutralisera instabila Seaforium-sprängladdningar och används för att hindra Dark Iron-sabotörer från att förstöra den väldiga dvärgbyggnaden som håller tillbaka vattnet i Loch Modan.",h="Disarming Mixture är en specialblandad kemisk lösning som Chief Engineer Hinderweir tillreder vid...",kw={"dark iron","disarming mixture","sprängämnen","hinderweir","loch modan","kruttunna","seaforium","stonewrought dam"},ang={["profession:Engineering"]="Disarming Mixture visar prov på praktisk motteknik: genom snabb kemisk neutralisering görs instabila Seaforium-laddningar ofarliga utan att detonera.",["race:Dwarf"]="Att bevara Stonewrought Dam är avgörande för att skydda dalarna och lågländerna runtomkring. Därför är snabb användning av neutraliseraren viktig för dvärgarnas säkerhet."},sec={{t="En kemisk neutraliserare",b="När Dark Iron-sabotörer placerade en stor Seaforium-laddning under grunden till Stonewrought Dam var vanliga metoder för att desarmera den alltför riskabla. Utan omedelbart stöd från Mountaineers blandade Chief Engineer Hinderweir Disarming Mixture av ingredienser som sprängämnesexperten Ashlan Stonesmirk hade angett, för att snabbt neutralisera sprängladdningen under vattnet. När lösningen rörs ner direkt i den placerade kruttunnan neutraliserar den de reaktiva ämnena och gör en katastrofal explosion till en ofarlig, fräsande rest."}},faq={{q="Vad används Disarming Mixture till?",a="Blandningen är framtagen för att neutralisera en stor Seaforium-laddning i en tunna som Dark Iron-upprorsmakare placerat under vatten vid grunden till Stonewrought Dam.",al={"vad gör disarming mixture","användning av disarming mixture","syftet med disarming mixture"}},{q="Vem tillverkar Disarming Mixture?",a="Chief Engineer Hinderweir, dvärgbyggmästaren som ansvarar för underhåll och försvar vid Stonewrought Dam, blandar de nödvändiga ingredienserna till lösningen.",al={"vem tillverkar disarming mixture","vem ger disarming mixture","hinderweirs blandning"}},{q="Varför behövdes blandningen i stället för att bara desarmera bomben?",a="Seaforium-pulver är ofarligt när det är torrt, men kan explodera med enorm kraft när det blir blött. Den kemiska blandningen neutraliserar det reaktiva pulvret direkt i tunnan och undanröjer explosionsrisken medan den ligger under vatten vid dammen.",al={"varför inte desarmera som vanligt","varför använda kemikalier på bomben","varför disarming mixture"}}},fx={["8d78f743"]={q="Vad är Disarming Mixture?",a="Disarming Mixture är en särskild kemisk blandning som tillretts för att neutralisera flyktiga explosiva ämnen. När den blandas i Seaforium eller högklassigt sprängpulver reagerar den med de explosiva materialen och avaktiverar dem kemiskt. Laddningarna blir då ofarliga och fräser i stället för att detonera katastrofalt.",al={"vad är disarming mixture","disarming mixture föremål","om disarming mixture"}}},fp="17,192,22.395.0,39.134.0,34.132.0,67.186.0"}
P.entries["item:divined-scroll"] = {n="Divined Scroll",s="Divined Scroll är ett förtrollat pergament som nattalverna i Silverwind Refuge använder för att avslöja källan till de oroliga vattnen i Ashenvale. Genom att kanalisera den kvarvarande magin i intakta vattenelementarmskenor avslöjar pergamentet identiteten på den avfälliga magiker som åkallar dem.",h="Divined Scroll är ett förtrollat pergament som nattalverna i Silverwind Refuge använder för att avslöja...",kw={"ashenvale","divined scroll","divining scroll","elementalarmskenor","mystral lake","silverwind refuge","velene starstrike"},ang={["class:Mage"]="Pergamentet bygger på grundläggande principer för att spåra frammaning och visar hur elementarbindningar alltid bär den outplånliga arkaniska signaturen från magikern som skapade dem.",["race:NightElf"]="För väktarna som försvarar Ashenvale är spådomsverktyg som detta pergament avgörande för att avslöja dödliga förorenare vars arkaniska inblandning hotar skogens heliga vatten."},sec={{t="Spåra åkallaren",b="Det förgiftade vattnet i Mystral Lake har länge oroat väktarna som skyddar Ashenvale. För att ta reda på vem som manipulerar vattenelementalerna som hemsöker sjön ger Sentinel Velene Starstrike resenärer en oladdad Divining Scroll. Genom att samla in intakta armskenor direkt från de dödade elementalerna och använda dem som ett arkaniskt reagens överförs de vilande bindningarna i metallen till pergamentet. Den färdiga Divined Scroll blottlägger den magiska signaturen från den avfälliga magiker som ligger bakom plågan."},{t="Magikern avslöjad",b="När skriften på Divined Scroll väl har laddats leder den Sentinel Velene direkt till en dödlig skyldig: en vårdslös magiker som medvetet fördärvar skogens orörda vattenpölar. Med avslöjandet nedtecknat på pergamentet kan väktarna planera sin hämnd och skicka spejare för att jaga åkallaren som skändar deras heliga vildmark."}},faq={{q="Vad används Divined Scroll till?",a="Divined Scroll avslöjar identiteten på magikern som åkallar och binder fientliga vattenelementaler i Ashenvales sjöar, så att Sentinel Velene Starstrike kan rikta in sig direkt på den skyldiga.",al={"vad gör divined scroll","divined scrolls syfte","varför skapa divined scroll"}},{q="Hur skapas Divined Scroll?",a="Den skapas genom att kasta den tomma Divining Scroll som Sentinel Velene Starstrike tillhandahåller på fem Intact Elemental Bracers som samlats in från besegrade vattenelementaler kring Mystral Lake.",al={"hur skapar man divined scroll","tillverkning av divined scroll","hur får jag divined scroll"}},{q="Varför behövs elementalarmskenorna för att spå pergamentet?",a="Armskenorna fungerar som de fysiska bindningar som håller elementalerna kvar på det dödliga planet. Deras kvarvarande förtrollningar ger den magiska signatur som pergamentet behöver för att identifiera den specifika magiker som frammanade dem.",al={"varför intakta armskenor","elementalarmskenornas syfte"}},{q="Vem ska jag lämna Divined Scroll till?",a="Lämna den färdiga Divined Scroll till Sentinel Velene Starstrike vid Silverwind Refuge längs vägen i södra Ashenvale.",al={"var lämnar jag in divined scroll","vem vill ha divined scroll"}}},fx={["155064fc"]={q="Vad är Divined Scroll?",a="Divined Scroll blir till när en Divining Scroll används tillsammans med intakta armband från vattenelementaler som förorenar Ashenvales vatten. Scrollen genomsyras av de mystiska spår som finns kvar på armbanden och avslöjar information om den specifika besvärjare som kallade fram och fördärvade elementalerna.",al={"vad är divined scroll","divined scroll syfte","vad gör divined scroll"}},ebb5ddd6={q="Var kommer Divined Scroll ifrån, och vem har tillverkat den?",a="Du skapar själv Divined Scroll genom att kanalisera Sentinel Velene Starstrikes Divining Scroll genom flera intakta elementalarmband. Armbanden fungerar som ett arkaniskt reagens som låter scrollens spådomsmagi fokusera på och registrera de magiska signaturerna från elementalerna som skapade dem.",al={"vem skapade divined scroll","divined scroll ursprung","hur skapades divined scroll"}}},fp="14,189,20.437.0,16.277.1,36.165.0,34.151.0,58.169.0,37.123.0"}
P.entries["item:divining-scroll"] = {n="Divining Scroll",s="Divining Scroll är ett förtrollat pergament som Sentinel Velene Starstrike tillhandahåller vid Silverwind Refuge. Dess magi låter undersökare spåra den onaturliga magiska signaturen hos vattenelementalerna som hemsöker Ashenvale tillbaka till deras skapare.",h="Divining Scroll är ett förtrollat pergament som Sentinel Velene Starstrike tillhandahåller vid Silverwind...",kw={"ashenvale","divined scroll","divining scroll","elementalbracers","silverwind refuge","velene starstrike","vattenelementaler"},ang={["class:Mage"]="Rullen visar klassisk spådomsmagi som används för att spåra arkanisk resonans och avslöjar att en annan utövare av arkanisk magi missbrukar elementarframmaning i heliga kaldoreilundar.",["race:NightElf"]="För Sentinels som skyddar Ashenvale är rullen ett viktigt verktyg för att avslöja utomstående som vanhelgar skogens orörda vatten med onaturlig korruption."},sec={{t="Spåra onaturliga elementaler",b="När korrumperade vattenelementaler började stiga upp ur Ashenvales orörda dammar förstod Sentinels att störningen inte var naturlig. Sentinel Velene Starstrike skaffade denna spådomsrulle för att hitta den ansvariga. Genom att kanalisera rullens magi genom intakta elementalbracers som fokuserande reagens kan användaren utvinna besvärjarens signatur och förvandla det tomma pergamentet till en Divined Scroll som namnger den skyldiga."}},faq={{q="Vad används Divining Scroll till?",a="Rullen är avsedd att avslöja vem som skapade de korrumperade vattenelementalerna som invaderar Ashenvale. Med intakta elementalbracers som fokus kanaliserar pergamentet spådomsmagi för att läsa besvärjarens aura och anteckna dennes identitet.",al={"vad gör rullen","divining scrolls syfte","varför använda divining scroll"}},{q="Vem tillhandahåller Divining Scroll?",a="Sentinel Velene Starstrike ger rullen till Alliance-undersökare vid Silverwind Refuge i södra Ashenvale medan hon utreder de förorenade vattnen.",al={"vem ger divining scroll","var får man rullen","velene starstrikes rulle"}},{q="Varför behövs intakta elementalbracers?",a="De flesta bracers splittras så att de inte längre går att känna igen under strid. Några få intakta bracers behåller fortfarande tillräckligt med kvarvarande bindningsmagi från sin besvärjare för att fungera som ett lämpligt arkaniskt fokus för spådomen.",al={"varför bracers","intakta elementalbracers","reagens till rullen"}},{q="Vad händer när rullen används?",a="När föremålet aktiveras i närheten av fem intakta bracers förbrukas det och blir en Divined Scroll, som avslöjar att en avfällig magiker medvetet frammanar de korrumperade elementalerna till skogens sjöar.",al={"divined scroll","efter att rullen använts","vad förvandlas den till"}}},fx={["51ca655d"]={q="Vad är Divining Scroll?",a="Divining Scroll är ett förtrollat pergament som används för att avslöja magiska ursprung. När dess kraft fokuseras med intakta elementalarmband som reagens kan den spåra bindningssignaturerna hos vattenelementalerna som plågar Ashenvale och identifiera den fredlösa magiker som kallade dem till skogens rena vatten.",al={"vad är divining scroll","divining scroll historia","divining scroll föremål"}},af5653e2={q="Varför vill man ha Divining Scroll?",a="Sentinel Velene Starstrike behöver scrollen för att ta reda på vem som fyller Ashenvales sjöar och vattensamlingar med fördärvade vattenelementaler. Utan scrollens spådomsmagi kan nattalverna inte hitta magikern som bär ansvaret eller stoppa den fortsatta skändningen av deras heliga vildmark.",al={"varför behövs divining scroll","varför behövs scrollen","divining scroll syfte"}}},fp="15,140,28.343.0,37.187.0,33.152.0,40.153.0,38.198.1"}
P.entries["item:dogran-s-pendant"] = {n="Dogran's Pendant",s="Dogran's Pendant lockar en succubus till warlocksen i Orgrimmar. Dogran, en sårad ork, bär det medan han är skild från sin partner, Zankaja. I Cleft of Shadow förvandlar warlocks sorgen som är bunden till det till ett lockbete.",h="Dogran's Pendant lockar en succubus till warlocksen i Orgrimmar.",kw={"cleft of shadow","dogran","dogran's pendant","gan'rul bloodeye","orgrimmar","succubus","bindningen","zankaja"},ang={["class:Warlock"]="Som warlock i Horden använder du Dogran's Pendant för att bevisa att du behärskar Nether och lära dig att åkalla en succubus.",["faction:Horde"]="Som medlem av Horden kan du se hängets kopplingar till personliga tragedier i The Barrens och Durotar och till warlockskulten i Orgrimmar."},sec={{t="En källa till hjärtesorg",b="Dogran's Pendant bär sorgen hos en ork som skilts från Zankaja. Fångenskap och svåra skador har kastat en skugga över deras kärlek. Warlocksen i Cleft of Shadow vet att demoner som succubi livnär sig på kärlek, längtan och sårbarhet. De använder sorgens kraft i hänget för att locka en succubus genom Twisting Nether och in i Neeru Fireblades cirkel för åkallning."},{t="Underkastelse och minne",b="Under Gan'rul Bloodeyes ledning använder en blivande warlock hänget för att åkalla en succubus och kuva den i strid. Provet visar att man behärskar demonens förföriska manipulationer. När ritualen är över återgår hänget till Gan'rul, som ska överlämna det till Zankaja."}},faq={{q="Vad används Dogran's Pendant till?",a="Warlocks använder Dogran's Pendant för att åkalla en succubus i Neeru Fireblades tält i Cleft of Shadow. När demonen har åkallats och besegrats återgår hänget till Gan'rul Bloodeye.",al={"användning av smycket","vad gör jag med dograns smycke","dograns smyckesuppdrag"}},{q="Varför reagerar en succubus på smycket?",a="En succubus livnär sig på begär, kärlek och passion och vet hur den ska manipulera dem. Hänget är bundet till Dogran och Zankajas tragiska kärlek och lockar demonen genom Nether.",al={"varför vill en succubus ha smycket","varför åkallar smycket en demon","smyckets bakgrund"}},{q="Vem var Dogran?",a="Dogran är en ork vars fångenskap och skador undersöks av Hordens warlocks genom kontakter som Blind Cazul och Ken'zigla. Han älskar Zankaja men vägrar belasta henne med att ta hand om en invalid.",al={"vem är dogran","dograns berättelse"}},{q="Vad händer med smycket efter åkallningsritualen?",a="När warlocken besegrat den åkallade succubusen återgår hänget till Gan'rul Bloodeye, som kan överlämna det till Zankaja.",al={"vem får smycket","lämna tillbaka dograns smycke"}}},fx={f4378ded={q="Vad är Dogran's Pendant?",a="Dogran's Pendant är ett personligt minnessmycke knutet till orchen Dograns och hans älskade Zankajas tragiska öde. Den lilla medaljongen är fylld av rå längtan och sorg och fungerar som ett kraftfullt fokus för mörk magi. Under häxmästarnas bindningsritualer kan den locka en succubus genom tomrummet.",al={"vad är dogran's pendant","dogran's pendant information","dogran's pendant historia"}},bd6e6859={q="Varför vill man ha Dogran's Pendant?",a="Häxmästare söker medaljongen eftersom dess känslomässiga kraft gör den till ett perfekt lockbete för en succubus. Den drar demonen rakt in i en åkallningscirkel där den kan kuvas och bindas. När ritualen är över behöver Gan'rul Bloodeye få tillbaka den för att kunna lämna beskedet till Dograns livskamrat, Zankaja.",al={"varför vill de ha dogran's pendant","vem vill ha dogran's pendant","dogran's pendant syfte"}}},fp="16,215,23.362.0,27.274.1,34.189.0,43.170.0,15.203.0,55.122.0"}
P.entries["item:dolanaar-delivery"] = {n="Dolanaar Delivery",s="Dolanaar Delivery är ett knippe skördade örter som skickas från Shadowglens druidmarker till byn Dolanaar. Det anförtros åt unga resenärer som lämnar den skyddade dalen och är ett enkelt ärende som förbinder dem med Innkeeper Keldamyr längs vägen.",h="Dolanaar Delivery är ett knippe skördade örter som skickas från Shadowglens druidmarker till byn Dolanaar.",kw={"aldrassil","leverans","dolanaar","örter","keldamyr","porthannius","shadowglen"},ang={["profession:Herbalism"]="Leveransen visar på den stadiga efterfrågan på växter från Aldrassils trakter, som ska fylla förråden i Teldrassils avlägsna bosättningar.",["race:NightElf"]="Att ta emot paketet markerar ett övergångsprov för unga kaldorei som lämnar Shadowglens skyddande grenar och träder ut i den vidare världen."},sec={{t="Ett knippe från Shadowglen",b="Det här paketet har skördats i Aldrassils skuggiga lundar och innehåller färska örter till bosättningen Dolanaar. Porthannius är upptagen med pågående angelägenheter bland druiderna i Shadowglen och förlitar sig därför på unga äventyrare som färdas söderut längs vägen för att tryggt bära knippet till Innkeeper Keldamyr."},{t="Välkommen till härden",b="När paketet levereras kommer resenären raka vägen till tröskeln till värdshuset i Dolanaar. Keldamyr tar tacksamt emot varorna och passar på att påminna trötta vägfarare om behovet av vila, sinnesro och den trygghet som värdshusets härd erbjuder innan de färdas djupare in i Teldrassil."}},faq={{q="Vad finns i Dolanaar Delivery?",a="Paketet innehåller ett urval färska örter som skördats i Shadowglen, avsedda för Innkeeper Keldamyr och gästerna på värdshuset i Dolanaar.",al={"vilka örter finns i paketet","innehållet i dolanaar delivery","vad finns i paketet"}},{q="Vem skickar leveransen?",a="Porthannius, en alv som sköter ärenden med druiderna i Shadowglen, gör i ordning knippet men har inte tid att själv resa söderut.",al={"vem ger mig leveransen","vem skickade örterna","porthannius leverans"}},{q="Vem tar emot paketet i Dolanaar?",a="Leveransen förs direkt till Innkeeper Keldamyr, som sköter det gemensamma värdshuset mitt i Dolanaar.",al={"vem ska jag lämna örterna till","mottagare av dolanaar delivery","keldamyrs örter"}},{q="Varför kunde inte Porthannius leverera paketet själv?",a="Porthannius har brådskande, oavslutade ärenden med druiderna kring Aldrassil och måste därför söka upp en äventyrare på väg söderut längs skogsvägen.",al={"varför stannar porthannius","varför skickade porthannius mig"}}},fx={["432231a6"]={q="Vad är Dolanaar Delivery?",a="Dolanaar Delivery är ett paket med färska örter som samlats in i Shadowglen och ska till bosättningen Dolanaar längre söderut. Porthannius anförtror det åt dig. Paketet står för den vanliga handeln och provianteringen från Shadowglens skyddade lundar till det större nattalvsamhället.",al={"vad är dolanaar delivery","dolanaar paket","shadowglen paket"}},["7521a0db"]={q="Varför vill Innkeeper Keldamyr ha Dolanaar Delivery?",a="Innkeeper Keldamyr behöver de färska örterna från Shadowglen för att hålla förråden på värdshuset i Dolanaar fyllda. Örterna behövs för att brygga drycker, laga stärkande måltider och ta hand om trötta resenärer och försvarare som söker vila och läkedom på Teldrassil.",al={"varför behöver keldamyr örter","dolanaars örter syfte","varför vill man ha dolanaar delivery"}}},fp="17,137,24.231.0,21.193.0,37.110.0,24.137.0,37.85.0,52.137.0"}
P.entries["item:dragonmaw-war-banner"] = {n="Dragonmaw War Banner",s="Dragonmaw War Banners är samlingsbaner som bärs av Dragonmaw-orcherna, som håller stånd i Wetlands. De är märkta med klanens symboler och fungerar som stridsbevis för dvärgarna som försvarar Menethil Harbor och försöker hejda det växande orchhotet.",h="Dragonmaw War Banners är samlingsbaner som bärs av Dragonmaw-orcherna, som håller stånd i Wetlands.",kw={"dragonmaw","grim batol","menethil","nek'rosh","stoutfist","krigsbaner","wetlands"},ang={["faction:Alliance"]="Att ta baner från Dragonmaw försvagar en gammal fiende till Alliansen innan de kan återuppbygga den fruktansvärda styrka de hade under det andra kriget.",["race:Dwarf"]="För dvärgarna i Khaz Modan är det avgörande att rensa träsket från Dragonmaw-baner för att hålla handelslederna till Menethil Harbor säkra från orchernas plundringsstyrkor."},sec={{t="Tecken på ett bestående hot",b="Efter det andra kriget splittrades Dragonmaw-klanen när de förlorade kontrollen över sina trälar, de röda drakarna. De rasande drakarna vände sig mot sina fångvaktare och drev de överlevande bort från Grim Batol och ut i de östra kullarna. På senare tid har de återstående orcherna börjat samla styrka igen under hövdingen Nek'rosh och rest sina krigsbaner över läger nordost om Menethil Harbor. Dessa grova, imponerande baner står både för deras kvardröjande trots och för ett direkt hot mot bosättningarna i träskmarkerna."},{t="Bevis på seger",b="Captain Stoutfist, som är stationerad i Menethil Harbor, ger alliansens äventyrare i uppdrag att slå till mot lägren i träsket och ta med sig dessa baner tillbaka. Baneren, som tagits från plundrare, centurioner och benväktare, bekräftar för dvärgarnas garnison att Dragonmaw-lägren bryts ned systematiskt innan klanen kan inleda samordnade räder."}},faq={{q="Varför vill Captain Stoutfist ha baneren?",a="Captain Stoutfist vill ha baneren som konkreta bevis på att äventyrare har attackerat Dragonmaw-lägret nordost om Menethil Harbor och decimerat deras styrkor.",al={"varför samla baner","krigsbaner syfte","varför stoutfist vill ha baner"}},{q="Vilka bär Dragonmaw War Banners?",a="Baneren bärs av olika Dragonmaw-stridskämpar i lägren i Wetlands, däribland plundrare, träsklöpare, centurioner, stridsmästare, skuggväktare, benväktare och hövdingen Nek'rosh själv.",al={"vem släpper dragonmaw-baner","var hittar man krigsbaner","vilka orcher har baner"}},{q="Varför är Dragonmaw-orcherna i Wetlands?",a="Mot slutet av det andra kriget förlorade Dragonmaw kontrollen över sina tillfångatagna röda drakar. De befriade drakarna jagade våldsamt sina forna herrar och tvingade de överlevande orcherna att fly från sitt fäste i Grim Batol och skingras i träskmarkerna och de omgivande bergen.",al={"varför är dragonmaw här","dragonmaws historia i wetlands","dragonmaw-lore"}},{q="Vem leder Dragonmaw-klanen nu?",a="Klanen leds av hövdingen Nek'rosh, son till deras förre hövding Nekros. Nek'rosh har svurit att hämnas på de röda drakarna som vände sig mot hans far och dödade honom.",al={"dragonmaws ledare","vem är nek'rosh","hövdingen nek'rosh"}}},fx={abf078db={q="Vad är en Dragonmaw War Banner?",a="Dessa baner är Dragonmaw-klanens samlingssymboler i Wetlands. De bär symboler från en orchklan som är ökänd för att en gång ha förslavat den röda drakflocken, och står för dess militära stolthet och obevekliga trots. För Alliansens försvarare i Menethil Harbor bevisar de att ett läger har brutits och dess krigare drivits på flykt.",al={"vad är dragonmaw war banner","dragonmaw-banér","dragonmaw war banners"}},["2c481a00"]={q="Var kommer Dragonmaw War Banners ifrån, och vem har tillverkat dem?",a="De tillverkas och bärs av de överlevande orcherna i Dragonmaw-klanen. Efter att ha förlorat sitt fäste Grim Batol och flytt undan de befriade röda drakarnas vrede samlade Dragonmaw sig på nytt i bergen och träskmarkerna nordost om Menethil Harbor. Där tillverkar deras plundrare, centurioner och schamaner baner för att markera sitt nytagna territorium och samla sina växande krigarskaror under hövding Nek'rosh.",al={"vem tillverkade dragonmaw-baneren","dragonmaw war banner ursprung","varifrån kommer krigsbaneren"}}},fp="20,159,29.429.0,17.293.0,46.144.0,38.153.0,43.262.0,33.166.0"}
P.entries["item:dried-seeds"] = {n="Dried Seeds",s="Vid The Crossroads ger Tonga Runetotem resenärer Dried Seeds för att pröva den livgivande kraften under The Barrens vatten.",h="Vid The Crossroads ger Tonga Runetotem resenärer Dried Seeds för att pröva den livgivande kraften under The...",kw={"the barrens","bubblande spricka","the crossroads","dried seeds","the stagnant oasis","tonga runetotem"},ang={["class:Druid"]="Som druid kan du använda de döda fröna för att studera de märkliga energierna som stiger ur marken i The Barrens.",["faction:Horde"]="Som Horde-äventyrare kan du hjälpa Tonga Runetotem att undersöka förändringarna i den torra jorden i The Barrens."},sec={{t="Fröna och oasen",b="Tonga Runetotem studerar de märkliga ångsprickorna under The Barrens vatten. Vid The Forgotten Pools fann han sprickor under ytan och vill nu ta reda på om det finns en under The Stagnant Oasis åt sydost. Han ger resenärer Dried Seeds, som verkar livlösa, att lägga i den bubblande sprickan. Deras reaktion kan visa om energin under oaserna kan väcka liv i döda frön."}},faq={{q="Vad används Dried Seeds till?",a="Du använder Dried Seeds för att pröva den bubblande sprickan under The Stagnant Oasis. Lägg dem i dess vatten och se om energin där kan få dem att gro igen.",al={"användning av dried seeds","vad gör jag med dried seeds","syftet med dried seeds"}},{q="Vem ger ut Dried Seeds?",a="Tonga Runetotem, en tauren-druid vid The Crossroads, ger resenärer Dried Seeds. Han studerar de plötsliga utbrotten av växtlighet i The Barrens.",al={"vem ger dried seeds","var kommer dried seeds ifrån"}},{q="Var finns sprickan där fröna ska användas?",a="Sprickan ligger under vattnet i The Stagnant Oasis, sydost om The Crossroads i The Barrens.",al={"var ska dried seeds planteras","sprickans plats i the stagnant oasis","bubblande spricka dried seeds"}},{q="Vad händer när fröna utsätts för sprickan?",a="Tonga ber dig lägga de döda fröna i den bubblande sprickan och iaktta dem. Deras reaktion visar vad hans experiment ger för resultat.",al={"växer fröna","resultat av dried seeds"}}},fx={aa7d6cee={q="Vad är Dried Seeds?",a="Det här är helt döda och ofruktsamma växtfrön som du fått för ett ekologiskt experiment. På egen hand har de vissnat bortom allt naturligt hopp om att gro, vilket gör dem till ett idealiskt kontrollobjekt för att testa om de mystiska bubblande sprickorna i The Barrens oaser har onaturliga, livgivande egenskaper.",al={"vad är dried seeds","föremålet dried seeds","dried seeds i berättelsen"}},f2970934={q="Varför vill Tonga Runetotem att du testar Dried Seeds?",a="Tonga Runetotem vill avslöja den sanna naturen hos de märkliga sprickor som bubblar under vattnet i The Barrens oaser. Genom att utsätta livlösa, ofruktsamma frön direkt för sprickan vid The Stagnant Oasis hoppas han kunna se om vattnet kan sätta fart på tillväxt där naturligt liv har misslyckats helt.",al={"varför dried seeds","varför använda dried seeds","syftet med tongas frön"}}},fp="11,121,23.394.1,34.151.0,29.138.0,36.102.0,55.133.1"}
P.entries["item:durnan-s-scalding-mornbrew"] = {n="Durnan's Scalding Mornbrew",s="Durnan's Scalding Mornbrew är en nyligen upphälld, rykande het dvärgisk dryck avsedd för Durnan Furcutter i Coldridge Valley. Eftersom drycken snabbt tappar värmen i den iskalla bergsluften måste den skyndas direkt till Anvilmar innan den kallnar.",h="Durnan's Scalding Mornbrew är en nyligen upphälld, rykande het dvärgisk dryck avsedd för Durnan Furcutter i...",kw={"anvilmar","coldridge valley","dun morogh","durnan furcutter","mornbrew","skållhet"},ang={["race:Dwarf"]="För en dvärg från Dun Morogh finns det få större förolämpningar än att låta gott öl eller mornbrew kallna i bergsfrosten."},sec={{t="En kamp mot kylan",b="I den bitande kylan i Coldridge Valley finns det få bekvämligheter som slår en mugg färsk mornbrew, rykande het. När en kurir blir försenad med att leverera en omgång till Grelin Whitebeard riskerar den färska muggen, avsedd för Durnan Furcutter inne i Anvilmar, att frysa till is. Durnan förväntar sig uttryckligen att hans brygd ska vara skållhet, så det finns bara ett kort tidsfönster på några minuter för att bära den ångande muggen uppför den snöiga stigen till berghallen innan den svalnar helt."}},faq={{q="Vem är brygden avsedd för?",a="Brygden är avsedd för Durnan Furcutter, en dvärg som är stationerad inne i bosättningen Anvilmar i Coldridge Valley.",al={"vem får mornbrew","mottagare av durnans mornbrew","vart ska brygden"}},{q="Varför måste leveransen ske så snabbt?",a="Den iskalla luften i Dun Morogh drar snabbt värmen ur muggar som står öppna. Durnan har uttryckligen beställt skållhet mornbrew, och en ouppvärmd eller ljummen mugg duger helt enkelt inte åt honom.",al={"varför tidsgräns","brygden kallnar","varför skynda med mornbrew"}},{q="Varifrån kommer leveransen?",a="Drycken lämnas över nära Grelin Whitebeard's läger utanför Anvilmar, efter att kuriren inser att hen inte kan nå smedjan i tid på egen hand.",al={"varifrån kommer mornbrew","vem häller upp brygden"}},{q="Vad händer när Durnan får muggen?",a="Durnan tar genast en paus från sina plikter inne i Anvilmar för att njuta av den ångande drycken medan den fortfarande är varm.",al={"durnans reaktion","lämna in mornbrew"}}},fx={["93832100"]={q="Vad är Durnan's Scalding Mornbrew?",a="Det är en nyupphälld mugg het dvärgisk morgonbrygd, särskilt avsedd för Durnan Furcutter i Anvilmar. Den bryggs för att värma benen mot den bitande bergskylan i Coldridge Valley och måste drickas rykande het för att verkligen sitta rätt.",al={"vad är scalding mornbrew","föremålet durnan mornbrew","mornbrew-dryck"}},c7c22f23={q="Varför vill Durnan ha Scalding Mornbrew?",a="Durnan Furcutter beställde den ångande brygden för att njuta av under en välförtjänt paus från arbetet i Anvilmar. Dvärgar tar sin morgondryck på allvar, och om en sådan mustig mugg hinner kallna förstörs hela njutningen.",al={"varför durnan vill ha mornbrew","varför behövs mornbrew","syftet med durnans dryck"}}},fp="26,143,23.321.0,29.94.0,48.127.0,34.153.0,42.91.0"}
P.entries["item:durotar-tiger-fur"] = {n="Durotar Tiger Fur",s="På Echo Isles utanför Durotars sydöstra kust ger tigrarna Darkspear päls, och deras flyktingbefolkning växer stadigt. Trollfolket använder skinnen till filtar, tält och rustningar.",h="På Echo Isles utanför Durotars sydöstra kust ger tigrarna Darkspear päls, och deras flyktingbefolkning växer...",kw={"durotartiger","durotar tiger fur","echo isles","praktiskt byte","sen'jin village","trollskinn","vel'rin fang"},ang={["class:Hunter"]="Som jägare följer du Echo Isles tigrar på ett sätt som påminner om klassiska trolljaktriter, där tålamod och kamouflage krävs för att överraska de smygande örovdjuren.",["race:Troll"]="För Darkspear innebär tigerskinnen överlevnad i Sen'jin Village och en påminnelse om den smärtsamma förlusten av deras hemland på Echo Isles."},sec={{t="En livsviktig resurs för Darkspear",b="I Sen'jin Village måste Darkspear hushålla med knappa förråd. De låter de lokala tigrarna föröka sig tills deras växande behov kräver en gallring. Trollfolket bereder de tjocka skinnen till varor som bosättningen behöver, däribland skyddande rustningar och varma filtar för skiftande årstider."},{t="Jakt på Echo Isles",b="Echo Isles ligger söder om Durotar, på andra sidan öppet vatten. Darkspear kallade en gång ögruppen sitt hem, tills häxdoktorn Zalazane drev bort dem. Jägarna möter faror från Zalazanes trälbundna undersåtar och från tigrar som lurar bland det täta lövverket. Erfarna jägare som Vel'rin Fang berättar att de tillbringar hela dagar orörliga i djungelns snår för att få till ett enda rent dödande."}},faq={{q="Var får man tag på tigerpäls från Durotar?",a="Jägarna samlar Durotar Tiger Fur från tigrar på Echo Isles, utanför Durotars sydöstra kust.",al={"var får man tigerpäls","durotar tiger fur plats","hur får man tigerpäls"}},{q="Varför behöver trollen i Sen'jin Village dessa pälsar?",a="Vel'rin Fang samlar pälsen åt den växande Darkspear-bosättningen, där trollfolket använder den till filtar, tält och skyddande läderrustningar mot skiftande årstider.",al={"varför samla tigerskinn","vem behöver tigerpäls","bytenas praktiska syfte"}},{q="Varför jagar trollen inte för många tigrar?",a="Darkspear låter tigerbeståndet växa och gallrar bara när det växande samhällets behov tär på förråden av skydd och kläder.",al={"tigerskydd","gallra hjorden"}}},fx={e997b985={q="Vad är Durotar Tiger Fur?",a="Durotar Tiger Fur är skinn från vilda tigrar som stryker omkring på Echo Isles utanför Durotars sydöstra kust. Dessa skinn är tåliga, varma och slitstarka och utgör en viktig råvara för Darkspear Trolls i Sen'jin Village. De tillverkar vardagsföremål av skinnen för att skydda sitt folk mot det hårda klimatet.",al={"vad är durotar tiger fur","tigerpäls från durotar","vad är det här skinnet"}},c85f7978={q="Varifrån kommer Durotar Tiger Fur?",a="Skinnen flås direkt från Durotars tigrar, som jagar genom Echo Isles täta snår. De tillverkas inte av hantverkare, utan kommer från vild jakt utförd av förföljare och spejare som vågar sig ut i vattnen söder om Sen'jin Village.",al={"durotar tiger furs ursprung","varifrån kommer tigerskinnen","vem gör durotar tiger fur"}}},fp="17,189,34.280.0,22.378.0,38.102.0,53.170.0,41.129.0"}
P.entries["item:duskbat-wing"] = {n="Duskbat Wing",s="En Duskbat Wing är ett råmaterial som samlas in från de lädervingade fladdermöss som fladdrar genom skymningen kring Deathknell. I den resursfattiga bosättningen Forsaken tar lokala skräddare till vara på dessa läderartade vingar och gör om dem till stadig provisorisk rustning åt nyuppståndna soldater.",h="En Duskbat Wing är ett råmaterial som samlas in från de lädervingade fladdermöss som fladdrar genom...",kw={"deathknell","duskbat","duskbat wing","novice elreth","scavenger paw","de fördömda","tirisfal glades"},ang={["profession:Tailoring"]="Novice Elreth visar prov på den enkla och praktiska överlevnadsskrädderi som behövs i Tirisfal, där tåliga fladdermusvingar används som ersättning för läder och tyg.",["race:Undead"]="För nyuppväckta Forsaken är insamlingen av dessa vingar en av de allra första överlevnadsuppgifterna, så att du inte faller i bitar under dina första skärmytslingar."},sec={{t="Provisoriskt skydd i Deathknell",b="När nya odöda kravlar sig upp ur jorden i Deathknell har de knappt mer än trasor och sköra ben på sig. Omgivna av kvarvarande Scourge och tanklöst fientligt djurliv måste de nyblivna Forsaken skrapa ihop all skyddsutrustning de kan hitta. Novice Elreth, Shadow Priest Sarvis medhjälpare, samlar in Duskbat Wings tillsammans med vargtassar för att lappa ihop och förstärka kläder och rustningar åt nyuppväckta krigare innan de skickas ut i vildmarken för att strida."}},faq={{q="Vad används Duskbat Wings till?",a="I Deathknell använder Novice Elreth duskbat wings tillsammans med tassar från asätare som råmaterial för att tillverka, laga och förstärka rustningar och kläder åt nyuppväckta Forsaken-rekryter.",al={"användning av duskbat wing","varför samla duskbat wings","syftet med duskbat wings"}},{q="Var kommer Duskbat Wings ifrån?",a="De samlas in från Duskbats och Mangy Duskbats som hemsöker dungarna och sluttningarna kring byn Deathknell i Tirisfal Glades.",al={"var hittar man duskbat wings","duskbat wings källa","vem släpper duskbat wings"}},{q="Vem efterfrågar vingarna i Deathknell?",a="Novice Elreth, som tar hand om de sårade och tillverkar utrustning under ledning av Shadow Priest Sarvis i kapellet i Deathknell, ber rekryterna att samla in dem.",al={"vem behöver duskbat wings","lämna in duskbat wing","uppdragsgivare för duskbat wing"}},{q="Varför förlitar sig Forsaken på fladdermusdelar till rustningar?",a="Deathknell har nästan inga försörjningslinjer eller någon traditionell tillverkning. De lokala vårdarna måste leta upp tåligt skinn, päls och läderartade fladdermusvingar från Tirisfals inhemska rovdjur för att sy enkelt skyddande plagg åt rekryter som ska ut i strid.",al={"varför fladdermusvingar till rustning","rustning av fladdermusskinn för forsaken"}}},fx={d5eef861={q="Vad är en Duskbat Wing?",a="En Duskbat Wing är den läderartade vinge som tas från skymningsfladdermöss som fladdrar genom Tirisfal Glades hemsökta skogar. I Deathknell, där tillverkade varor är sällsynta, är vingarna en livsviktig råvara. Skräddare och vårdare bland de Förfallna syr och garvar fladdermushuden till slitstarka kläder och lätt rustning åt nyvaknade odöda innan de skickas ut för att möta farorna i gläntorna.",al={"vad är duskbat wing","föremålet duskbat wing","om duskbat wing"}}},fp="12,109,35.392.0,32.153.0,33.109.0,39.152.0,48.266.0"}
P.entries["item:dusky-crab-cakes"] = {n="Dusky Crab Cakes",s="Dusky Crab Cakes är en smakrik rätt som Chef Grual lagar i Darkshire för att stilla Jitters desperata hunger. Den lokala delikatessen har en syrlig smak, och en utsvulten Jitters tycker att den är utsökt.",h="Dusky Crab Cakes är en smakrik rätt som Chef Grual lagar i Darkshire för att stilla Jitters desperata hunger.",kw={"darkshire","duskwood","dusky crab cakes","grual","jitters","spindelben"},ang={["profession:Cooking"]="Gruals kakor visar hur en påhittig kock kan skapa en syrlig lokal specialitet av ingredienserna som finns i Duskwood."},sec={{t="En tvivelaktig delikatess",b="I Duskwoods dunkla skogar är färska råvaror sällsynta, och kockarna måste använda det kött som skogen ger. När den skräckslagna luffaren Jitters plågas av hungerkramper lagar Chef Grual en sats av sina berömda ”krabbkakor”. För en utomstående ser rätten ut som en oskyldig fiskbiff, men Gruals hemliga ingrediens är betydligt mindre aptitlig: de seniga, slemmiga benen från Duskwoods monstruösa spindlar. Jitters slukar snabbt kakorna, helt ovetande om vad han egentligen äter."}},faq={{q="Vad består Dusky Crab Cakes egentligen av?",a="Chef Grual håller receptet på sin specialitet för sig själv. Den hemliga ingrediensen avslöjas när man samlar förnödenheter åt honom i Duskwood.",al={"ingredienser i krabbkakor","vad innehåller dusky crab cakes","spindelkött"}},{q="Vem äter Dusky Crab Cakes?",a="Kakorna lagas åt Jitters, en nervös man som söker skydd i Raven Hill och klagar över att magen kurrar våldsamt.",al={"vem får krabbkakorna","vem är de avsedda för","jitters mat"}},{q="Hur reagerar Jitters på kakorna?",a="Jitters är utsvulten och slukar glatt kakorna utan att ifrågasätta receptet. Han är bara tacksam över att de stillar hungern.",al={"jitters reaktion","tycker jitters om kakorna"}},{q="Vem lagar Dusky Crab Cakes?",a="Chef Grual, kocken på Scarlet Raven Tavern i Darkshire, lagar rätten av förnödenheter som samlats in åt honom.",al={"vem lagar krabbkakorna","chef grual","kock i darkshire"}}},fp="16,136,23.365.1,43.134.0,30.121.0,36.130.0,31.113.0"}
P.entries["item:dust-devil-debris"] = {n="Dust Devil Debris",s="Över hela Westfall lämnar Dust Devils laddat grus efter sig. Magiker värdesätter detta skräp som reagens för att förtrolla pergament och binda kommunikationsbesvärjelser till skriftrullar.",h="Över hela Westfall lämnar Dust Devils laddat grus efter sig.",kw={"collin mauren","dust devil debris","dust devils","kommunikationsbesvärjelse","skriftrulle","stormwind","westfall"},ang={["class:Mage"]="Som magiker kan du se hur elementära rester används i skrivkonst och kommunikationsmagi, där rått elementärt kaos förenas med arkan disciplin."},sec={{t="Luft spunnen till pergament",b="Dust Devils sveper fram över Westfalls slätter som våldsamma virvelvindar. När en fälls kollapsar den levande stormen till laddat damm och grus som kallas Dust Devil Debris. En svag rest av den elementära virveln finns kvar i stoftet. I Stormwind uppskattar magiker som Collin Mauren det för specialiserad trolldom. Gruset blandas i förtrollat bläck och pergament och hjälper en trollkarl att binda en luftig kommunikationsbesvärjelse till en skriftrulle, så att ord kan färdas genom kungariket."}},faq={{q="Vad används Dust Devil Debris till?",a="Collin Mauren använder Dust Devil Debris för att skapa en specialiserad kommunikationsskriftrulle. Dess kvarvarande elementära energi hjälper honom att fästa känslig kommunikationsmagi på papper.",al={"användning av dust devil debris","varför samla dust devil debris","syftet med skräpet"}},{q="Var kommer detta skräp ifrån?",a="Dust Devil Debris kommer från resterna av Dust Devils, fientliga luftvarelser som strövar omkring på Westfalls karga jordbruksmarker och vägar.",al={"var skräpet finns","dust devil-byte","skräp från westfall"}},{q="Varför är Dust Devils farliga?",a="Dust Devils är fientliga luftvarelser som strövar omkring i Westfall. Collin Mauren varnar för att det innebär att möta farliga varelser när man samlar in deras skräp.",al={"varför elementärer i westfall","dust devils ursprung i westfall"}},{q="Vem är Collin Mauren?",a="Collin Mauren är en mänsklig magiker i Stormwinds Mage Quarter. Han använder sin expertis inom arkana konster för att skapa förtrollade skriftrullar och magiska komponenter åt andra magiker och nyfikna forskare.",al={"collin mauren","vem vill ha skräpet"}}},fx={["2f6e3759"]={q="Vad är Dust Devil Debris?",a="Dust Devil Debris består av virvlande grus, smuts och kvarvarande magisk materia som lämnas efter när en stoftdjävul besegras i Westfall. Dessa elementära virvelvindar piskar över de torra slätterna, och deras rester behåller tillräckligt med inneboende kraft för att fungera som verksamma reagenser för besvärjare och skrivare.",al={"vad är dust devil debris","dust devil debris","föremålet dust devil debris"}}},fp="17,167,23.468.0,35.163.0,33.128.0,30.141.0,21.189.0"}
P.entries["item:dwarven-tinder"] = {n="Dwarven Tinder",s="Dwarven Tinder är ett särskilt preparerat brännbart ämne som används av Alliansens styrkor i Wetlands. Det delades ut till sabotörer med uppdrag att bränna Dragonmaw-klanens belägringsmaskiner innan de kunde sättas in mot Menethil Harbor.",h="Dwarven Tinder är ett särskilt preparerat brännbart ämne som används av Alliansens styrkor i Wetlands.",kw={"katapulter","dragonmaw","dwarven tinder","menethil harbor","nek'rosh","sabotage","wetlands"},ang={["faction:Alliance"]="När Dun Algaz-passen är omstridda är det avgörande att bränna fiendens krigsmaskiner innan de når Menethil Harbor, så att Alliansens främsta hamn i träskmarkerna kan stå kvar.",["race:Dwarf"]="Dvärgiska ingenjörer och spejare känner till värdet av pålitliga eldstartare, särskilt i Wetlands ständigt blöta och regnpiskade träskmarker."},sec={{t="Sabotaget mot Dragonmaw",b="När Alliansens spejare upptäckte att hövding Nek'rosh hade byggt tunga katapulter i Dragonmaw-lägret stod Menethil Harbor inför en omedelbar kris. Hårda strider i Dun Algaz hade skurit av hamnen från förstärkningar i söder, och försvararna skulle inte klara en lång belägring. Lösningen var ett förebyggande sabotage. Dwarven Tinder gavs till frivilliga som ryckte in i orkernas område. Det fattar snabbt eld av en gnista och brinner så hett att det kan förtära förstärkta belägringsmaskiner av trä på några minuter."}},faq={{q="Vad används Dwarven Tinder till?",a="Dwarven Tinder används för att tända eld på och förstöra belägringskatapulterna som Dragonmaw-klanen byggt i Wetlands, så att de inte kan inleda en artilleribeskjutning av Menethil Harbor.",al={"syftet med dwarven tinder","varför använda dwarven tinder","vad gör dwarven tinder"}},{q="Varför bränner man katapulterna i stället för att erövra dem?",a="Menethil Harbors garnison är kraftigt underlägsen i antal och avskuren från förstärkningar från Ironforge på grund av blockaden vid Dun Algaz. Försvararna har inte manskap nog att erövra eller återta tunga belägringsmaskiner djupt inne på fientligt Dragonmaw-territorium. Därför är förstörelse det enda möjliga försvaret.",al={"varför förstöra katapulterna","varför inte ta belägringsmaskinerna"}},{q="Vem förberedde detta fnöske?",a="Fnösket tillhandahålls av dvärgarnas garnison i Menethil Harbor och har särskilt förberetts för snabb och pålitlig antändning under militära sabotageuppdrag.",al={"vem tillverkade fnösket","varifrån kommer dwarven tinder"}}},fx={["5fa2c489"]={q="Vad är Dwarven Tinder?",a="Dwarven Tinder är särskilt preparerat och mycket lättantändligt tände som Menethil Harbors försvarare tillhandahåller. Dvärgiska milismän har gjort det så att det snabbt fattar eld av minsta gnista. Därmed kan stora krigsmaskiner av trä snabbt och grundligt antändas i de fuktiga våtmarkerna innan fienden hinner reagera.",al={"vad är dwarven tinder","föremålet dwarven tinder","om dwarven tinder"}},f9865b90={q="Varför behövs Dwarven Tinder just nu?",a="Dragonmaw-orcherna under Nek'rosh har byggt enorma belägringskatapulter för att slå sönder Menethil Harbor. Med förstärkningar från Ironforge avskurna av hårda strider i Dun Algaz kan Menethil inte uthärda en långvarig belägring. Du måste använda tändet för att infiltrera Dragonmaw-lägret och bränna deras krigsmaskiner till aska innan de kan marschera.",al={"varför dwarven tinder","varför behövs dwarven tinder","varför behöver vi tände"}}},fp="14,129,24.480.0,32.125.0,49.234.0,25.126.0"}
P.entries["item:ear-of-balgaras"] = {n="Ear of Balgaras",s="Ear of Balgaras tjänar som ett dystert bevis på att Balgaras the Foul, en svartjärnsdemonist som ledde anfallet mot Dun Modr, har dött. Örat togs från den fege befälhavarens lik och ger Ironforges bergsjägare, som försvarar norra Wetlands, ett avslut.",h="Ear of Balgaras tjänar som ett dystert bevis på att Balgaras the Foul, en svartjärnsdemonist som ledde...",kw={"balgaras the foul","svartjärn","dun modr","ear of balgaras","longbraid the grim","thandol span","wetlands"},ang={["class:Warlock"]="Balgaras utövade skuggmagi och felmagi i det fördolda. Hans nederlag innebar att sätta stopp för en vilsekommen utövare som hade förött den norra vägen.",["race:Dwarf"]="För Ironforges dvärgar innebär det här örat att en blodig skuld för släktingarna som slaktades när Thandol Span saboterades äntligen är reglerad."},sec={{t="En dyster trofé",b="Dun Modr lades i ruiner när svartjärnsinkräktare saboterade Thandol Span och utplånade den lokala dvärggarnisonen. Balgaras the Foul var deras befälhavare på plats, en intrigant demonist som ledde sina trupper från skuggorna och undvek personlig strid. För Longbraid the Grim, bergakungens officer som var stationerad utanför den förstörda utposten, krävde rättvisan ett konkret bevis på att ledaren fallit. När Balgaras öra skärs av står det bortom tvivel att demonistens skräckvälde vid den norra gränsen är över."},{t="Rättvisa för de fallna",b="När Dun Modr gick förlorat miste Longbraid sin bror och dussintals ståndaktiga soldater som omkom när West Bridge rasade. Att visa upp demonistens öra lagar inte den förstörda bron eller återupplivar de fallna, men det får de överlevande svartjärnskrafterna som är utspridda i norra Wetlands att vackla. Utan Balgaras att leda dem blir det mycket lättare för Ironforges spejare att hålla de återstående rövarna i schack innan en ny befälhavare skickas från söder."}},faq={{q="Vem var Balgaras the Foul?",a="Balgaras the Foul var en svartjärnsdvärg och demonist som förde befäl över krigarskaran som angrep Dun Modr och förstörde Thandol Spans West Bridge. Han var ökänd för sin feghet och skickade vågor av soldater i döden medan han själv höll sig gömd för Alliansens patruller.",al={"vem är balgaras","balgaras bakgrund","balgaras the foul"}},{q="Varför vill Longbraid the Grim särskilt ha hans öra?",a="Longbraid the Grim krävde obestridliga bevis för att den undflyende demonisten verkligen hade dödats. Ett avskuret öra är en klassisk trofé från gränslandet som bekräftar uppdragets fullbordan, utan att bäraren behöver släpa hela liket tillbaka till dvärglägret.",al={"varför ett öra","varför skära av örat","longbraids bevis"}},{q="Vad händer med svartjärnen när Balgaras är död?",a="Utan sin beräknande ledare tappar de överlevande svartjärnskrafterna i Dun Modr sammanhållningen. De hemsöker fortfarande ruinerna, men Longbraid tror att de är tillräckligt oorganiserade för att Alliansen ska kunna hantera dem innan Ironforges fiender hinner skicka en ersättare.",al={"vad händer när balgaras dör","svartjärnen i dun modr"}}},fx={a51409b4={q="Varifrån kommer Ear of Balgaras?",a="Det här avskurna örat kommer direkt från Balgaras the Foul, en feg trollkarl av Dark Iron som verkar i Wetlands norra delar. Balgaras för befäl över de fientliga dvärgar som anföll Dun Modr och förstörde den västra delen av Thandol Span, men han föredrar att gömma sig medan hans hantlangare strider.",al={"ear of balgaras ursprung","var får man tag på balgaras öra","vem har balgaras öra"}}},fp="15,164,13.474.0,22.363.0,26.239.0,54.207.0,53.231.0"}
P.entries["item:ebonlocke-s-response-to-solomon"] = {n="Ebonlocke's Response to Solomon",s="Ebonlocke's Response to Solomon är ett officiellt brev skrivet av Lord Ello Ebonlocke, borgmästare i Darkshire. Det förs tillbaka till Lakeshire och avvisar blankt Redridges desperata vädjan om militär hjälp från Night Watch.",h="Ebonlocke's Response to Solomon är ett officiellt brev skrivet av Lord Ello Ebonlocke, borgmästare i...",kw={"darkshire","duskwood","ebonlocke","lakeshire","brev","budbärare","night watch","redridge","solomon"},ang={["faction:Alliance"]="Brevet blottlägger hur fullständigt Alliansens kärnland har brutit samman: Redridge, Duskwood och Westfall har alla lämnats åt sitt öde av Stormwinds kungliga hov."},sec={{t="Ett bittert avslag",b="Inför svartstensorkernas intrång sökte Magistrate Solomon i Lakeshire förstärkningar från Duskwood efter att Stormwind ignorerat hans vädjanden. Lord Ello Ebonlockes svar är svidande och kompromisslöst. Ebonlocke påpekar att Night Watch bara finns eftersom Stormwind övergav Darkshire när fördärvande magi först grep tag i skogen. Om staden tömdes på sina försvarare för att hjälpa Redridge skulle Duskwood stå utan försvar och falla för ondskan innan milisen ens nådde skogsbrynet."},{t="Den sönderfallande gränsen",b="När Solomon får brevet skakar insikten honom djupt. Stormwind-armén har dragits tillbaka från Westfall och kungliga gardet saknas i Darkshire; hela rikets södra gräns har lämnats att förfalla. Solomon avfärdar inte Ebonlockes ilska, utan ser ett fruktansvärt mönster: kronans plötsliga försummelse av rikets utkanter tyder på förräderi i Stormwind Citys högsta maktskikt."}},faq={{q="Vad är Ebonlocke's Response to Solomon?",a="Det är ett förseglat brev skrivet av Lord Ello Ebonlocke i Darkshire och adresserat till Magistrate Solomon i Lakeshire. I brevet vägrar Ebonlocke att skicka Night Watch för att försvara Redridge och förklarar att Duskwood knappt håller sina egna mardrömmar stången.",al={"ebonlockes brev","ebonlockes svar","brev till solomon"}},{q="Varför skickar Darkshire ingen hjälp till Lakeshire?",a="Darkshire har inga kungliga trupper. Night Watch består helt av lokala frivilliga, eftersom Stormwind övergav området. Lord Ebonlocke varnar för att Darkshire skulle översvämmas av odöda och vidriga varelser om hans vakter marscherade bort, innan de ens hunnit lämna skogen.",al={"varför hjälper inte night watch","varför vägrade darkshire","ebonlocke vägrar solomon"}},{q="Hur reagerar Magistrate Solomon på brevet?",a="Magistrate Solomon blir chockad och bestört. När han får veta att kungliga gardet övergav Darkshire, precis som armén drog sig ur Westfall, blir han övertygad om att fulspel eller förräderi lamslår ledningen i Stormwind.",al={"solomons reaktion","vad säger solomon"}},{q="Vem skrev brevet?",a="Brevet skrevs av Lord Ello Ebonlocke, den hårt prövade borgmästaren i Darkshire och ledaren för Council of Darkshire, som ansvarar för stadens försvar.",al={"vem är ebonlocke","lord ebonlocke"}}},fx={de19eb29={q="Varför vill Magistrate Solomon ha Ebonlockes svar?",a="Magistrate Solomon är desperat efter förstärkningar för att försvara Lakeshire mot Blackrock-orcherna. Efter att Stormwind upprepade gånger ignorerat hans vädjanden om militär hjälp vände han sig till Darkshire i hopp om att Lord Ello Ebonlocke kunde avvara Night Watch. Solomon väntar ivrigt på brevet för att få veta om hjälp är på väg från Duskwood, men får bara upptäcka att Darkshire är lika övergivet och hårt ansatt som Redridge.",al={"varför behöver solomon brevet","varför lämna ebonlockes svar","varför skicka svar till solomon"}}},fp="31,120,16.450.0,22.329.1,40.201.0,43.270.0,48.204.1,22.140.0"}
P.entries["item:echeyakee-s-hide"] = {n="Echeyakee's Hide",s="Vid The Crossroads väntar Sergra Darkthorn på Whitemists bleka skinn, från den legendariska vita lejonhanen i The Barrens. Taurener vördar besten som en förkroppsligad barmhärtighet och död, medan jägare tar med pälsen som bevis på sin skicklighet.",h="Vid The Crossroads väntar Sergra Darkthorn på Whitemists bleka skinn, från den legendariska vita lejonhanen i...",kw={"the barrens","the crossroads","echeyakee","echeyakee's hide","sergra darkthorn","vitt lejon","whitemist"},ang={["class:Hunter"]="Som jägare tar du pälsen från savannens främsta smygjägare som en tidig övergångsrit och lär dig vildmarkens nyanser som Horde-spårare.",["race:Tauren"]="Som tauren hedrar du Whitemists snabba ande när du jagar Echeyakee, ett heligt prov på barmhärtighet och smygande snarare än blott erövring."},sec={{t="Whitemists trofé",b="Echeyakee betyder Whitemist på språket Taur-ahe. Lejonet fick det namnet bland savannens rovdjur för sin smygande vita päls och sina snabba dödande attacker, som avslutade bytesdjurens liv innan rädsla eller smärta hann infinna sig. En jägare lockar fram den svårfångade katten nära de väldiga kodo-benen nordost om The Crossroads med ett ceremoniellt horn och tar sedan pälsen. Att ta den till Sergra Darkthorn bevisar stridsfärdighet och hedrar Whitemists tysta, barmhärtiga slut."}},faq={{q="Varifrån kommer Echeyakee's Hide?",a="Echeyakee's Hide kommer från det vita lejonet Echeyakee, som håller till bland väldiga kodoskelett nordost om The Crossroads i The Barrens. Sergra Darkthorn ger dig Horn of Echeyakee för att locka fram honom.",al={"var får jag tag på echeyakee's hide","hur får man tag på echeyakee hide","echeyakees pälsens plats"}},{q="Vem vill ha Echeyakee's Hide?",a="Sergra Darkthorn, en orcisk jägare vid The Crossroads, vill ha Echeyakee's Hide. Hon skickar ut stigande Horde-jägare för att spåra den stora katten och återvända med hans päls som bevis på deras band till vildmarken.",al={"vem lämnar in echeyakee hide","lämna in echeyakees hide","vem behöver echeyakee hide"}},{q="Vad betyder namnet Echeyakee?",a="Echeyakee betyder Whitemist på taurenernas språk. Namnet hedrar kattens bleka päls och tron på att han rörde sig över savannen som rullande dimma och dödade utan utdragen skräck eller plåga.",al={"echeyakee översättning","betydelsen av echeyakee","taurennamnet echeyakee"}}},fx={["718fd4d1"]={q="Vad är Echeyakee's Hide?",a="Det är skinnet från Echeyakee, det vördnadsfulla vita lejon som taurerna kallar Whitemist. Echeyakee betraktas som savannkatternas kung i The Barrens och jagar med oslagbar smygförmåga och snabbhet, som både nåd och död. Hans skinn är ett fysiskt bevis på att en jägare hade skickligheten och modet att kalla fram och besegra det legendariska rovdjuret.",al={"vad är echeyakees hide","echeyakee hide","vitt lejonskinn"}}},fp="16,227,19.439.0,38.197.0,27.197.0,34.196.0"}
P.entries["item:egalin-s-grimoire"] = {n="Egalin's Grimoire",s="Egalin's Grimoire är en högt skattad arkan skrift som beskriver de grundläggande riterna för att frammana och befalla en voidwalker. Den skrevs av en mästerlig häxmästare och är en oumbärlig lärobok i Undercitys Temple of the Damned.",h="Egalin's Grimoire är en högt skattad arkan skrift som beskriver de grundläggande riterna för att frammana och...",kw={"carendin halgar","varelse från tomrummet","egalin","egalin's grimoire","perrine","temple of the damned","voidwalker"},ang={["class:Warlock"]="Egalin's Grimoire innehåller de exakta teknikerna som behövs för att dra en voidwalker från Nether och binda den till din vilja, en viktig övergångsrit för varje utövare.",["race:Undead"]="Genom att återta boken berövar du fanatiska Scarlet Crusade ett mäktigt magiskt föremål som stals direkt från Undercitys utövare."},sec={{t="Ett mästerverk",b="Den här skriften, författad av mästerbesvärjaren Egalin, beskriver den känsliga och farliga processen att dra en kaosvarelse från Nether. Egalin var känd bland utövarna för sin obehindrade kontroll över frammanade voidwalkers, en förmåga han förde vidare till sina elever, däribland Carendin Halgar. Utan de särskilda formler och kanaliseringsmetoder som finns nedtecknade i texten riskerar en oförberedd besvärjare att slitas i stycken av varelsen de kallar fram."},{t="Scarlet Crusades stöld",b="Skriften stals från Forsaken-häxmästarna av en agent för Scarlet Crusade vid namn Perrine, som gömde den i en kista i ett torn i västra Tirisfal Glades. Trots fanatikernas hat mot mörk magi verkade tjuven i stort sett ovetande om bokens verkliga betydelse och behandlade den som föga mer än beslagtaget kätterskt byte, tills Forsaken-noviser som ville bemästra tomrummet hämtade den."}},faq={{q="Vem var Egalin?",a="Egalin var en utomordentligt begåvad häxmästare och Carendin Halgars mentor. Han är ihågkommen som den förste bland dem som frammanade en voidwalker och som någon som befäl över kaotiska väsen med fullständig lätthet.",al={"vem är egalin","egalin bakgrund","vem skrev skriften"}},{q="Varför är Egalin's Grimoire så farlig?",a="Boken innehåller besvärjelserna och kanaliseringsmetoderna som behövs för att frammana en voidwalker. Om en häxmästare försöker utföra ritualen utan att ha lärt sig instruktionerna ordentligt kommer det frammanade tomrummets väsen att slita häxmästaren i stycken.",al={"vad gör skriften","farlig voidwalker-skrift","varför är den farlig"}},{q="Hur fick Scarlet Crusade tag på boken?",a="En agent för Scarlet Crusade vid namn Perrine lyckades stjäla skriften från Forsaken-häxmästarna. Hon låste in den i en kista i ett vakttorn tillhörande Crusade i västra Tirisfal Glades, till synes ovetande om dess verkliga magiska värde.",al={"vem stal boken","perrine och skriften","varför har korsfararna den"}},{q="Vem behöver få tillbaka skriften?",a="Carendin Halgar, häxmästarläraren som bor i Temple of the Damned under Undercity, behöver skriften för att lära nya noviser att frammana och binda voidwalkers.",al={"vem vill ha skriften","vem lämnar in egalin's grimoire","carendin halgar bok"}}},fx={cc7caae6={q="Vad är Egalin's Grimoire?",a="Egalin's Grimoire är en unken, specialiserad formelbok som innehåller hemligheterna bakom att åkalla varelser ur kaoset bortom. Den beskriver i detalj processen och besvärjelsens uppbyggnad som krävs för att frammana och binda en avgrundsvandrare, en varelse som kan slita en oförberedd åkallare i stycken.",al={"vad är egalins grimoire","egalin-boken","vad är formelboken"}},["29951967"]={q="Varifrån kommer Egalin's Grimoire och vem skrev den?",a="Boken skrevs av Egalin, en mästerlig häxmästare som hyllas bland Undercitys utövare som den förste att frammana en avgrundsvandrare. Egalin undervisade andra framstående häxmästare, däribland Carendin Halgar, som vördnadsfullt såg upp till sin mentors obehindrade kontroll över åkallade fasor.",al={"vem skrev egalins grimoire","egalin-bokens ursprung","vem gjorde egalins grimoire"}},c5f2fef1={q="Varför vill man ha Egalin's Grimoire?",a="Häxmästarna i Temple of the Damned behöver formelboken för att lära blivande utövare att frammana avgrundsvandrare. När en Scarlet Crusade-agent vid namn Perrine stal den och gömde den i ett närliggande torn blev det avgörande att återta texten, så att dess farliga ritualer inte hamnade i fiendens händer och livsviktig kunskap kunde återföras till de Förfallna.",al={"varför vill de ha egalins grimoire","vem vill ha formelboken","varför återta egalin-boken"}}},fp="17,169,15.351.0,17.360.1,15.152.0,38.217.0,41.198.0,33.161.0"}
P.entries["item:electropeller"] = {n="Electropeller",s="En elektropeller är en specialiserad mekanisk komponent som konstruerats av gnomuppfinnaren Wizbang Cranktoggle. Den skulle driva en explosiv lockanka, men en hel säck med sådana manicker försvann i Darkshores sötvattenfloder under en misslyckad nattlig utflykt.",h="En elektropeller är en specialiserad mekanisk komponent som konstruerats av gnomuppfinnaren Wizbang...",kw={"auberdine","cliffspring river","darkshore","lockanka","elektropeller","elektropellrar","wildbend river","wizbang cranktoggle"},ang={["profession:Engineering"]="Elektropellern är ett klassiskt exempel på gnomisk ingenjörskonst: ambitiös, motordriven och farlig. Den konstruerades för en explosiv lockanka som hamnade i floden innan den ens hann testköras ordentligt.",["race:Gnome"]="Wizbang Cranktoggle för den stolta gnomiska traditionen vidare genom att förena vild teknisk ambition med förbryllande missöden. Med glatt humör ber han förbipasserande sportfiskare att rädda resterna av hans nattliga experiment."},sec={{t="Missöden vid flodstranden",b="Gnomisk ingenjörskonst kräver precision, men uppfinnarna bakom den är inte alltid lika metodiska. Wizbang Cranktoggle, en excentrisk gnom verksam i Auberdine, konstruerade elektropellern som en framdrivningskomponent till en experimentell, självgående lockanka som skulle explodera. När Cranktoggle spanade efter vattenvägar i Darkshore efter att ha druckit lite för mycket, tuppade han av. Han vaknade till igen flera timmar senare med svedd hår och en tom packning. Hans samling elektropellrar hade fallit i sötvattenströmmarna och delarna låg utspridda i Darkshores floder och sjöar, tills tålmodiga sportfiskare fick upp dem."}},faq={{q="Vad används en elektropeller till?",a="Elektropellrar är motordrivna framdrivningsmekanismer som konstruerats av Wizbang Cranktoggle. Han uppfann dem särskilt för att driva en experimentell, självgående lockanka som skulle explodera och som han utvecklade i Darkshore.",al={"elektropellerns syfte","vad gör en elektropeller","varför en lockanka"}},{q="Hur hamnade delarna i Darkshores floder?",a="Wizbang Cranktoggle strövade omkring i Darkshore på natten, småberusad och på jakt efter en vattenväg att testa. Han tuppade av och vaknade i Auberdine med svedd hår, efter att av misstag ha tappat hela säcken med delar i sötvattenbäckarna.",al={"varför i vattnet","hur försvann elektropellrarna","cranktoggles misstag"}},{q="Var kan man få upp elektropellrar?",a="De driver omkring i Darkshores inre sötvatten, bland annat i Cliffspring River och Wildbend River, där lyckosamma sportfiskare kan få upp dem ur vattnet.",al={"var fiskar man upp elektropellrar","elektropellrarnas platser","fiske i cliffspring river"}},{q="Vem vill ha tillbaka de här komponenterna?",a="Wizbang Cranktoggle, en gnom som bor i Auberdine, behöver få tillbaka tolv stycken så att han kan fortsätta sin forskning om lockankan.",al={"vem behöver elektropellrar","vem är cranktoggle","gnomuppdrag i auberdine"}}},fx={["3f720660"]={q="Vad är en electropeller?",a="En electropeller är en specialiserad mekanisk framdrivningskomponent tillverkad med gnomisk ingenjörskonst. De motoriserade delarna driver vattenfarkoster, särskilt de excentriska uppfinningar som Wizbang Cranktoggle har konstruerat, som hans motordrivna ankliknande lockbeten.",al={"vad är electropeller","föremålet electropeller","vad är electropellers"}}},fp="13,114,27.425.0,34.139.0,54.206.0,38.126.0,36.118.0"}
P.entries["item:elixir-of-pain"] = {n="Elixir of Pain",s="Elixir of Pain är en experimentell alkemisk brygd, tillverkad av Forsaken-apotekare stationerade i Tarren Mill. Den destilleras av blod som samlats in runt Hillsbrad Foothills och ska testa biologiska medel för Lady Sylvanas mörkare syften.",h="Elixir of Pain är en experimentell alkemisk brygd, tillverkad av Forsaken-apotekare stationerade i Tarren...",kw={"apotekare","elixir of pain","farmer ray","hillsbrad fields","royal apothecary society","stanley","sylvanas","tarren mill"},ang={["faction:Horde"]="Forsakens allierade kallas ofta in för att hjälpa till med dessa dystra tester och bevittna på nära håll de obehagliga metoder som forskarna i Tarren Mill använder.",["race:Undead"]="Royal Apothecary Societys känslokalla fälttester visar att Forsaken är beredda att ta till alla medel för att utveckla kemiska vapen mot de levande."},sec={{t="Apotekarnas experiment",b="Royal Apothecary Society söker outtröttligt efter nya formler för att stärka Forsakens ställning mot sina dödliga grannar och Scourge. Elixir of Pain är ett sådant försök, blandat av färska ingredienser som samlats in runt Hillsbrad Foothills. Drycken har tillverkats utan större hänsyn till de levande och ska visa att flyktiga ämnen kan användas för att tjäna Dark Lady."},{t="Fälttest på Stanley",b="Apotekarna vill testa drycken på ett diskret försöksobjekt i stället för att riskera värdefulla militära tillgångar eller genast röja sin verksamhet för Hillsbrads försvarare. Stanley får elixiret. Han är en till synes ofarlig tamhund som tillhör Farmer Ray på den norra gården i Hillsbrad Fields. I stället för att stilla dö dör det stackars djuret en våldsam förvandling och blir ett rasande monster."}},faq={{q="Vad är syftet med Elixir of Pain?",a="Elixir of Pain är en experimentell dryck som skapats för att testa biologiska föreningar åt Royal Apothecary Society. Skaparna hoppas att blandningarna så småningom ska leda till förödande brygder som tjänar Lady Sylvanas och säkrar Forsakens dominans.",al={"varför tillverka elixir of pain","elixirets syfte","vad gör elixiret"}},{q="Vem är Stanley?",a="Stanley är en hund som tillhör Farmer Ray på den norra gården i Hillsbrad Fields. Forsaken-apotekarna väljer honom som ett ovetande försöksobjekt för att se hur deras nybryggda elixir påverkar kroppen.",al={"vem är stanley","farmer rays hund","stanleys hund"}},{q="Varför testas elixiret på Stanley?",a="Apothecary Lydon vill fälttesta sitt nyblandade elixir och skickar det till Farmer Rays lilla hund Stanley för att se hur djuret reagerar.",al={"vad händer med stanley","dör stanley","stanley förvandlas till varg"}},{q="Var testas elixiret?",a="Testet sker utanför den norra bondgården i Hillsbrad Fields, sydväst om Tarren Mill. Stanley brukar vila nära verandan framför Farmer Rays hus.",al={"var lämnar jag elixiret","var finns stanley","farmer rays gård"}}},fx={["5a45fd3d"]={q="Vad är Elixir of Pain?",a="Elixir of Pain är en experimentell alkemisk brygd som framställts för de Förfallnas krigsinsats i Hillsbrad Foothills. Den bryggs av färskt blod och flyktiga reagenser och fungerar som en tidig prototyp för de mörka farsoter och gifter som Royal Apothecary Society vill utveckla åt Lady Sylvanas.",al={"vad är elixir of pain","föremålet elixir of pain","smärtdryck"}},["52862df0"]={q="Varifrån kommer Elixir of Pain och vem gjorde den?",a="Elixiret bryggs vid de Förfallnas utpost Tarren Mill. En alkemist blandar färskt blod från varelser i de omgivande kullarna med andra frätande ingredienser för att skapa ett virulent vapen som ska främja den Mörka damens erövring av området.",al={"vem gjorde elixir of pain","skaparen av elixir of pain","varifrån kommer elixir of pain"}}},fp="14,174,26.347.0,24.336.1,42.207.0,15.187.0,36.149.1,27.151.0"}
P.entries["item:elixir-of-suffering"] = {n="Elixir of Suffering",s="Elixir of Suffering är en alkemisk brygd som Apothecary Lydon kokar ihop i Tarren Mill. Den har utvecklats på uppdrag av Royal Apothecary Society och är ett experimentellt steg mot en smittsam pest som ska utrota både levande människor och Scourge.",h="Elixir of Suffering är en alkemisk brygd som Apothecary Lydon kokar ihop i Tarren Mill.",kw={"apothecary lydon","elixir of suffering","forsakens pest","hillsbrad foothills","royal apothecary society","tarren mill","umpi"},ang={["race:Undead"]="Royal Apothecary Society arbetar över hela Lordaeron med att skapa ett vapen som ska säkra Forsakens självständighet från både Scourge och de levande människorna, och Lydons giftiga experiment i Tarren Mill är ett viktigt steg."},sec={{t="Apotekarens experiment",b="I den förfallna byn Tarren Mill blandar Apothecary Lydon outtröttligt råa ingredienser som samlats in i den omgivande vildmarken till giftiga brygder. Elixir of Suffering är en tidig milstolpe i Royal Apothecary Societys övergripande uppdrag: att ta fram en ny pest som ska utrota både levande och döda. Lydon testar det dödliga elixiret på sin olycksaliga assistent, en groda vid namn Umpi, för att säkerställa dess styrka."}},faq={{q="Vad är syftet med Elixir of Suffering?",a="Elixiret är en experimentell brygd som Apothecary Lydon kokar ihop som en del av Royal Apothecary Societys forskning. Det ska användas för att testa dödliga föreningar avsedda för Forsakens nya pest mot mänskligheten och Scourge.",al={"varför framställa elixir of suffering","vad gör elixiret","syftet med elixir of suffering"}},{q="Vem är Umpi?",a="Umpi är en vanlig groda som Apothecary Lydon håller i Tarren Mill. Trots att Umpi skämtsamt kallas assistent fungerar grodan främst som ett ovetande försöksdjur för nykokade alkemiska gifter.",al={"vem är grodan","vem är paddan","lydons assistent"}},{q="Vad händer när Umpi dricker elixiret?",a="När den olycksaliga grodan får Elixir of Suffering att dricka kväker den och dör nästan omedelbart av giftet, vilket visar hur dödlig Apothecary Lydons blandning är.",al={"dör umpi","vad händer med paddan"}}},fx={["14f85f3d"]={q="Vad är Elixir of Suffering?",a="Elixir of Suffering är en experimentell brygd från Royal Apothecary Society i Tarren Mill. Den ingår i de Förfallnas pågående försök att skapa en ny farsot och har utformats för att vålla både levande och odöda olidlig smärta och död.",al={"vad är elixir of suffering","elixir of suffering i berättelsen","vad gör elixir of suffering"}},fa4e475a={q="Varifrån kommer Elixir of Suffering, och vem tillverkade den?",a="Elixiret bryggs av Apothecary Lydon, som är stationerad i Tarren Mill i Hillsbrad Foothills. På uppdrag av Royal Apothecary Society och Lady Sylvanas Windrunner samlar Lydon lokala ingredienser i kullarna för att skapa och förädla den dödliga drycken.",al={"vem tillverkade elixir of suffering","skaparen av elixir of suffering","varifrån kom elixir of suffering"}},["1d085d8d"]={q="Varför vill Apothecary Lydon skapa Elixir of Suffering?",a="Apothecary Lydon tillreder elixiret för att uppfylla Dark Ladys storslagna plan: att skapa ett vapen kraftfullt nog att utrota både Scourge och mänskligheten. Lydon testar dess dödlighet på lokalbefolkningen för att säkerställa att brygden orsakar största möjliga plåga och en snabb död.",al={"varför tillverka elixir of suffering","syftet med elixir of suffering","varför vill lydon ha elixiret"}}},fp="19,177,26.349.0,47.163.0,12.163.0,41.145.1"}
P.entries["item:elune-s-tear"] = {n="Elune's Tear",s="Elune's Tear är ett sällsynt, självlysande mineral som finns på Iris Lakes centrala ö i Ashenvale. Night Elf-örtmedicinare och helare vördar stenen som en helig välsignelse från Mångudinnan och söker den för dess kraft att rena magisk korrumpering och dödliga sjukdomar.",h="Elune's Tear är ett sällsynt, självlysande mineral som finns på Iris Lakes centrala ö i Ashenvale.",kw={"ashenvale","astranaar","botemedel","elune's tear","iris lake","orendil","pelturas","relara"},ang={["class:Priest"]="De som vördar ljuset och månen känner igen stenens medfödda kraft att driva bort skugga och förruttnelse. Den visar de återställande mirakel som tillskrivs Elunes prästinnor.",["race:NightElf"]="För Night Elves är reliker som bär Elunes namn heliga gåvor. Att använda stenen för att rädda ett oskyldigt barn speglar det eviga bandet mellan kaldorei och Månmammans helande nåd."},sec={{t="En helig reningssten",b="Elune's Tear finns avskilt på den lilla ön i Iris Lake, öster om Astranaar. Det är en mystisk sten som tros bära renheten från Mångudinnan själv. Sjön har inte undgått skogens korrumpering: vattnet har blivit sjukligt grönt och förvridna sumpbestar strövar längs stränderna. Stenen är känd bland lokala Night Elf-örtmedicinare och helare, som Orendil Broadleaf, som ett nödhjälpmedel med förmåga att skölja bort djupt rotad korrumpering när vanliga skogsomslag inte räcker."},{t="Ett desperat botemedel",b="När en mystisk tärande sjukdom drabbar den unga Night Elf Relara Whitemoon i Astranaar, prövar hennes far Pelturas alla vanliga läkemedel utan framgång. På apotekaren Orendils inrådan söker Pelturas upp Elune's Tear för att tillreda en stärkande gryta med stenen. Den ger omedelbart hopp mot den märkliga sjukdomen, men den envisa korrumpering som plågar Ashenvale kräver ofta ännu mäktigare reningsriter."}},faq={{q="Vad är Elune's Tear?",a="Elune's Tear är ett sällsynt magiskt mineral som vilar på ön i Iris Lake i Ashenvale. Night Elves betraktar den som en helig relik, genomsyrad av Elunes renande beröring, som främst används för att bota onaturlig korrumpering och virulenta sjukdomar.",al={"elunes tear","vad är den här stenen","vad gör elunes tear"}},{q="Var finns Elune's Tear?",a="Stenen finns på ön mitt i Iris Lake, öster om Astranaar i centrala Ashenvale. Resenärer kan nå den genom att följa bäcken norrut från huvudvägen.",al={"var finns elunes tear","iris lake stenens plats","hitta elunes tear"}},{q="Varför behöver Pelturas Whitemoon stenen?",a="Pelturas söker stenen för att rädda sin sjuka dotter, Relara. När vanliga örtmediciner inte kan hejda den onaturliga sjukdom som sprider sig genom hennes kropp, råder apotekaren Orendil honom att endast stenens stärkande renhet kan rena åkomman.",al={"varför pelturas vill ha den","relara botemedel","vem behöver elunes tear"}},{q="Vad vaktar stenen vid Iris Lake?",a="Förvridna sumpbestar strövar omkring vid Iris Lake, vars vatten har blivit sjukligt grönt av korrumperingen som sprider sig genom Ashenvale.",al={"fiender vid iris lake","vad skyddar elunes tear"}}},fp="12,119,24.375.0,18.379.1,21.181.0,32.160.0,42.195.0,35.119.0"}
P.entries["item:embalming-ichor"] = {n="Embalming Ichor",s="Embalming Ichor är en onaturlig konserveringsvätska som utvinns ur kropparna på Rot Hide-gnoller i norra Tirisfal Glades. Den håller gnollerna vid liv som vandrande döda och har väckt stort intresse hos Forsaken Apothecaries, som vill analysera dess egenskaper för att bekämpa Scourge.",h="Embalming Ichor är en onaturlig konserveringsvätska som utvinns ur kropparna på Rot Hide-gnoller i norra...",kw={"apothecaries","brill","embalming ichor","garren's haunt","gravplundrare","magistrate sevren","massgravar","rot hide"},ang={["profession:Herbalism"]="Konserveringsvätskan i Rot Hide-gnollerna visar upp mörka alkemiska metoder som väcker intresse hos örtmästare och kemister som studerar pestens reagenser.",["race:Undead"]="För Forsaken är det livsviktigt att hindra Scourge från att få färska lik från massgravarna, både för att skydda Tirisfal och för att säkra råmaterial till sin egen överlevnad."},sec={{t="Onaturlig konservering",b="Rot Hide-gnollerna som härjar i Garren's Haunt och de närliggande massgravarna är inga vanliga vilddjur. De är ruttnande, konserverade trälar som Scourge skickar ut för att gräva upp pestoffer. Genom deras förmultnade ådror flyter Embalming Ichor, en motbjudande vätska som artificiellt bevarar deras kött och ger dem en långvarig vandödaexistens. För Magistrate Sevren i Brill fyller det dubbla syften att återta flaskor med denna vätska: det bekräftar att gravplundrarna har förintats och ger forskare från Royal Apothecary Society färska prover att dissekera, studera och använda som vapen mot Lich King's hantlangare."}},faq={{q="Vad är Embalming Ichor?",a="Det är ett alkemiskt konserveringsämne som finns i de levande döda kropparna hos Rot Hide-gnoller i Tirisfal Glades. Vätskan bevarar deras ruttnande kött och håller dem i rörelse i Scourges tjänst.",al={"embalming ichor","vad är ichor","gnollvätska"}},{q="Vem vill att vätskan samlas in?",a="Magistrate Sevren, som styr staden Brill, beordrar Forsaken-mästare att utvinna den ur dödade Rot Hide-gnoller så att Royal Apothecary Society kan studera dess kemiska sammansättning.",al={"vem behöver embalming ichor","magistrate sevren ichor","vem vill ha ichor"}},{q="Varför gräver Rot Hide-gnollerna upp gravar?",a="Scourge använder Rot Hide-gnollerna för att gräva upp pestoffrens kroppar i de norra massgravarna nära Garren's Haunt och få råmaterial till att stärka sina led.",al={"varför plundrar gnoller gravar","massgravar tirisfal","gnollers koppling till scourge"}},{q="Vad planerar Forsaken att göra med vätskan?",a="Apothecaries i Undercity studerar vätskan för att avslöja dess hemligheter i hopp om att utveckla motåtgärder eller nya alkemiska formler mot Scourge.",al={"vad gör sevren med ichor","apothecaries studerar ichor","användning av embalming ichor"}}},fx={e6b7bf5e={q="Varifrån kommer Embalming Ichor, och vem tillverkade det?",a="Embalming Ichor utvinns ur Rot Hide-gnollerna som hemsöker Mass Grave och Garren's Haunt i Tirisfal Glades. Det är den vidriga, onaturliga vätska som Scourge använder för att väcka dessa odöda gnolltjänare till liv och bevara dem. Den upprätthåller det skenbara liv som driver dem att gräva upp lik åt sina herrars arméer.",al={"embalming ichors ursprung","vem tillverkade embalming ichor","varifrån kommer ichor"}}},fp="15,153,22.435.0,24.176.0,31.133.0,46.151.0,47.114.0"}
P.entries["item:emerald-dreamcatcher"] = {n="Emerald Dreamcatcher",s="Emerald Dreamcatcher är en helig Night Elf-amulett, skapad för att dra till sig subtil kraft från The Emerald Dream. Den gavs till Tallonkai Swiftroot av druiderna i Ban'ethil Barrow Den och lämnades kvar i Starbreeze Village när Gnarlpine-furbolgerna föll för korruptionen och övertog bosättningen.",h="Emerald Dreamcatcher är en helig Night Elf-amulett, skapad för att dra till sig subtil kraft från The Emerald...",kw={"ban'ethil barrow den","dolanaar","emerald dreamcatcher","furbolg","gaerolas talvethren","starbreeze village","tallonkai swiftroot","teldrassil"},ang={["class:Druid"]="Amuletten är en direkt länk till de slumrande druiderna i Ban'ethil Barrow Den och visar hur deras samhörighet med The Emerald Dream ger hjälp åt Kaldorei-bosättningarna nedanför.",["race:NightElf"]="Att återta reliken är en liten seger mot sjukdomen som sprider sig och tar Starbreeze Village och Teldrassils omgivande grenar i anspråk."},sec={{t="En gåva från Ban'ethil",b="Emerald Dreamcatcher skapades under överinseende av Gaerolas Talvethren, Ban'ethil Barrow Dens druidiska väktare, och är en förtrollad relik som bara ges till några få utvalda. Den är utformad för att suga upp omgivande energier direkt från The Emerald Dream och välsigna den som bär den med tur och beskydd. När Starbreeze Village föll för de vansinniga Gnarlpine-furbolgerna lämnades amuletten kvar i en byrå, mitt i fientligt och korrumperat område."}},faq={{q="Vad gör Emerald Dreamcatcher?",a="Enligt Tallonkai Swiftroot suger amuletten upp rå energi från The Emerald Dream och skänker tur och livskraft åt den som äger den. Den ses som en sällsynt ynnestgåva från Cenarion Circle-druiderna.",al={"emerald dreamcatchers krafter","vad är dreamcatchern till för","dreamcatcherns historia"}},{q="Vem skapade Emerald Dreamcatcher?",a="Den gavs till Tallonkai av Gaerolas Talvethren, druidväktaren som vakar över den slumrande Cenarion Circle i Ban'ethil Barrow Den.",al={"vem skapade dreamcatchern","vem gav tallonkai dreamcatchern"}},{q="Varför lämnades dreamcatchern kvar i Starbreeze Village?",a="Tallonkai hade förvarat amuletten i sin byrå i Starbreeze Village. När de lokala Gnarlpine-furbolgerna uppslukades av korruption och blev våldsamma måste bosättningen överges innan han hann hämta den.",al={"varför lämnade tallonkai kvar den","var tappades dreamcatchern bort"}},{q="Varför är furbolgerna i Starbreeze Village fientliga?",a="Gnarlpine-stammen på Teldrassil har fallit offer för en mörk, spridande korruption som driver dem in i ett aggressivt raseri och tvingar Night Elf-folket att fly från avlägsna bosättningar som Starbreeze.",al={"varför föll starbreeze","furbolger i starbreeze village"}}},fx={a335891d={q="Vad är Emerald Dreamcatcher?",a="Emerald Dreamcatcher är en sällsynt och kraftfull förtrollad amulett som druiderna på Teldrassil har tillverkat. Den kan dra kraft direkt från The Emerald Dream och kanaliserar lugnande naturmagi som skänker tur och klarhet åt den som bär den. Tallonkai Swiftroot i Dolanaar betraktar den som en dyrbar personlig gåva, som bara ges till ett fåtal utvalda.",al={"vad är emerald dreamcatcher","föremålet emerald dreamcatcher","vad är dreamcatcher för slags föremål"}},["54ca5db1"]={q="Varför vill Tallonkai Swiftroot ha tillbaka Emerald Dreamcatcher?",a="Tallonkai Swiftroot tvingades lämna amuletten i sin byrå när Gnarlpine-furbolgerna föll för korruptionen och tog över Starbreeze Village. Talismanen har en andlig kraft som drar tur från The Emerald Dream, men den betyder också mycket för honom personligen eftersom den är en sällsynt gåva från Gaerolas Talvethren, väktare för Ban'ethil Barrow Den.",al={"varför vill tallonkai ha dreamcatcher","varför hämta dreamcatcher","varför är dreamcatcher viktig"}}},fp="20,229,21.421.0,38.184.0,34.151.0,59.206.0,51.209.0"}
P.entries["item:empty-blue-waterskin"] = {n="Empty Blue Waterskin",s="Brine skickar Empty Blue Waterskin norrut från The Barrens för att hämta heligt vatten. Vätskan hjälper henne att tillreda brygden som behövs för att åkalla och blidka vattenanden.",h="Brine skickar Empty Blue Waterskin norrut från The Barrens för att hämta heligt vatten.",kw={"ashenvale","the barrens","brine","call of water","empty blue waterskin","the ruins of stardust","water totem"},ang={["class:Shaman"]="Som schaman bär och fyller du waterskin som ett viktigt steg i att bemästra vattnets andar. Den rena vätskan behövs för att skapa din permanenta Water Totem.",["faction:Horde"]="Som medlem av Horden måste du resa från The Barrens in i fientligt Night Elf-territorium i västra Ashenvale för att hämta vattnet."},sec={{t="Ett heligt kärl",b="Brine ger Empty Blue Waterskin till en schamanlärling i sin hydda på en kulle i södra The Barrens. Kärlet markerar den sista och farligaste insamlingsuppgiften i den tidiga träningen. För att tala med vattnets ande måste lärlingen söka upp rena, orörda källor runt Kalimdor. Waterskin är avsedd för en undangömd fontän djupt inne i The Ruins of Stardust, vid Ashenvales omstridda gränstrakter."},{t="Skogskällan",b="Lärlingen måste lämna Hordens trygga områden och resa in bland uråldriga lundar som vaktas av naturens bestar och Night Elf. Vid en fontän i den förstörda helgedomen djupt inne i The Ruins of Stardust fylls waterskin och blir en Filled Blue Waterskin. Tillsammans med vattenprover från The Barrens och Tarren Mill gör innehållet det möjligt för Brine att brygga drycken som behövs för att åkalla och blidka vattnets elementarande."}},faq={{q="Vad används Empty Blue Waterskin till?",a="Empty Blue Waterskin bär vatten från fontänen djupt inne i The Ruins of Stardust i Ashenvale tillbaka till Brine, som använder det för att brygga en dryck av rent vatten.",al={"vad gör empty blue waterskin","användning av empty blue waterskin","varför har jag empty blue waterskin"}},{q="Vem ger dig denna vattensäck?",a="Brine ger dig waterskin vid sin hydda i södra The Barrens, söder om Camp Taurajo nära Razorfen-gränsen.",al={"vem ger empty blue waterskin","var får man blue waterskin"}},{q="Var måste vattensäcken fyllas?",a="Fyll den vid den centrala fontänen djupt inne i The Ruins of Stardust i sydvästra Ashenvale, strax bortom Lake Mystral nära bergsryggen i Stonetalon.",al={"var fyller man empty blue waterskin","blue waterskin plats","var fyller jag den"}},{q="Varför behöver Brine vatten från Ashenvale?",a="Brine vill skapa den renaste vattenflaskan som finns på Kalimdor. De orörda, heliga källorna i Night Elf-ruinerna ger den rena slutkomponenten som krävs för att tala med vattnets elementandar.",al={"varför vatten från ashenvale","varför vatten från ruins of stardust"}}},fx={["6fa6361d"]={q="Vad är Empty Blue Waterskin?",a="Empty Blue Waterskin är ett rituellt kärl som anförtros åt shamanlärlingar under deras prövningar. Det ges av eremiten Brine i södra Barrens och är utformat för att samla in och bära rent vatten från heliga platser utan att dess andliga kraft fördärvas.",al={"empty blue waterskin","vad är blue waterskin","blue waterskins syfte"}}},fp="20,175,15.406.0,19.413.0,42.163.0,29.113.0,35.152.0,41.209.0"}
P.entries["item:empty-brown-waterskin"] = {n="Empty Brown Waterskin",s="I The Barrens ger Brine en shamanlärling en tom vattenlägel.",h="I The Barrens ger Brine en shamanlärling en tom vattenlägel.",kw={"the barrens","brine","call of water","quilboarer","sapta","shaman","vattenflaska"},ang={["class:Shaman"]="Som shaman är det en övergångsrit på vägen mot din Water Totem att bära den här vattenlägeln. Den visar balansen mellan vördnad för elementen och den hårda kampen för att överleva."},sec={{t="En lektion i knapphet",b="Brine ger en shamanlärling en tom läderlägel inför det första provet i Call of Water. Lärlingen måste bära den till vattenhålet under hennes boning och återvända med den full. Den lokala quilboar-stammen vaktar poolen och värdesätter dess vatten. I The Barrens, där vatten är en bristvara, kan även en liten oas upprätthålla liv och utlösa våld."}},faq={{q="Vad används Empty Brown Waterskin till?",a="Shamanlärlingar använder den tomma vattenlägeln för att hämta vatten från den naturliga dammen under Brines hydda i The Barrens. Fylld behövs den för att bereda elementär sapta.",al={"vattenflaskans syfte","vad gör den bruna vattenflaskan","användning av empty brown waterskin"}},{q="Vem ger ut den här vattenflaskan?",a="Brine, en eremit i södra The Barrens, ger vattenlägeln till shamaner som genomför sin elementära pilgrimsfärd för att kommunicera med vattnets andar.",al={"vem ger vattenflaskan","uppdragsgivare för brown waterskin","var hittar man en tom vattenflaska"}},{q="Varför försvarar quilboarerna vattenkällan?",a="Regn är sällsynt i hela The Barrens, och vatten är en bristvara. För quilboar betyder även ett litet vattenhål rikedom och överlevnad, så de vaktar det och anfaller alla som hämtar vatten därifrån.",al={"varför anfaller quilboarerna","quilboarer och vatten","varför vaktas pölen"}},{q="Vad händer när vattenflaskan är fylld?",a="När lägeln doppas i oasen under Brines kulle blir den en Filled Brown Waterskin. Om du återlämnar den till Brine kan hon pröva din förståelse för naturens balans innan hon skickar dig över världen efter mer sällsynta vatten.",al={"vad gör man efter att ha fyllt den","lämna in vattenflaskan","lämna in filled brown waterskin"}}},fx={["805e4eda"]={q="Vad är Empty Brown Waterskin?",a="Empty Brown Waterskin är ett enkelt kärl som eremiten Brine i södra Barrens ger till blivande shamaner. Det är ett hjälpmedel på vägen mot att tala med vattnets andar. För att förtjäna Water Sapta måste du bära kärlet till ett närliggande vattenhål som vaktas av våldsamma quilboar och fylla det med rent vatten. Då får du se hur liv och konflikter kretsar kring den knappa fukten på de torra slätterna.",al={"vad är empty brown waterskin","historien om empty brown waterskin","brown waterskin"}}},fp="21,68,20.344.0,43.161.0,28.148.0,48.182.0,37.217.0"}
P.entries["item:empty-cleansing-bowl"] = {n="Empty Cleansing Bowl",s="Empty Cleansing Bowl är ett rituellt kärl som Thundris Windweaver gav dig för att hjälpa till att undersöka Blackwood-furbolgernas fördärv. När du fyller det i månbrunnen i Auberdine och blandar i matprover skapas en blandning som tillfälligt kan bryta en satyrs demoniska inflytande.",h="Empty Cleansing Bowl är ett rituellt kärl som Thundris Windweaver gav dig för att hjälpa till att undersöka...",kw={"auberdine","blackwood","reningsskål","darkshore","empty cleansing bowl","månbrunn","thundris windweaver","xabraxxis"},ang={["class:Druid"]="Att använda vatten från månbrunnar för att bryta onaturliga plågor speglar druidernas grundläggande uppgift: att återställa naturens skadade balans i Darkshore.",["race:NightElf"]="Den renande ritualen visar hur Elunes månbrunnar kan upphäva avskyvärd demonisk smitta. Den ger hopp om att nattalvernas gamla allierade bland furbolgerna en dag kan räddas."},sec={{t="Ett renande kärl",b="Thundris Windweaver anförtrodde äventyrare i Auberdine Empty Cleansing Bowl, som är utformat för att bära heligt vatten från den lokala månbrunnen. Nattalverna upptäckte att de nordliga Blackwood-furbolgerna drabbats av demoniskt vansinne, iscensatt av satyrer som styr dem med förtrollade talismaner. När du hämtar rent månvatten i skålen och blandar det med furbolgernas insamlade nötter, säd och frukt skapar kärlet en välsignad måltid som tillfälligt återställer de drabbades förstånd och avslöjar satyrövervakaren bakom allt."}},faq={{q="Vad ska jag göra med Empty Cleansing Bowl?",a="Ta skålen till månbrunnen i Auberdine och doppa den i det välsignade vattnet för att skapa Filled Cleansing Bowl. Sedan behöver du samla in prover på säd, nötter och frukt från det nordliga Blackwood-furbolglägret att blanda i.",al={"använda tom reningsskål","så använder du tom reningsskål","var fyller man reningsskålen"}},{q="Varför behöver nattalverna den här skålen för att bekämpa furbolgernas fördärv?",a="Blackwood-furbolgerna är bundna av satyrernas talismaners mörka magi. Thundris Windweaver använder skålen för att hålla en helgad blandning som tillfälligt botar furbolgerna från deras raseri och lockar fram deras dolda satyrkontrollant, Xabraxxis.",al={"varför reningsskål","reningsskålens syfte"}},{q="Vem ger dig Empty Cleansing Bowl?",a="Thundris Windweaver, en nattalvslärd i Auberdine, ger dig skålen när han ber dig avslöja källan till Blackwood-fördärvet längs Cliffspring River.",al={"vem ger reningsskålen","uppdragsgivare för reningsskålen"}},{q="Vad händer när blandningen är färdig?",a="Om du placerar den färdiga blandningen nära den nordliga lägereldsplatsen renas furbolgerna i närheten tillräckligt länge för att väcka satyren Xabraxxis vrede. Då kan du döda honom och ta hans Talisman of Corruption.",al={"reningsskål vid lägerelden","placera reningsskålen"}}},fx={["2a179129"]={q="Vad är Empty Cleansing Bowl?",a="Empty Cleansing Bowl är ett rituellt kärl som Thundris Windweaver har anförtrott åt dig i Auberdine. Det är tillverkat för att rymma det helgade vattnet från en moonwell tillsammans med vilda växter. Kärlet är nödvändigt för att förbereda en renande offergåva som kan häva den demoniska smitta som plågar traktens djur och furbolger.",al={"vad är empty cleansing bowl","historien om cleansing bowl","syftet med empty cleansing bowl"}}},fp="20,209,24.474.0,43.206.0,70.206.1,38.169.0,42.196.1"}
P.entries["item:empty-cliffspring-falls-sampler"] = {n="Empty Cliffspring Falls Sampler",s="Empty Cliffspring Falls Sampler är en särskild flaska som Cenarion Circle anförtror åt unga Night Elf-druider. Den används för att samla in ett vattenprov vid mynningen till grottan vid Cliffspring River i Darkshore, för att hjälpa till att fastställa vilken giftig smitta som fördärvar det lokala djurlivet.",h="Empty Cliffspring Falls Sampler är en särskild flaska som Cenarion Circle anförtror åt unga Night Elf-druider.",kw={"alanndarian nightsong","cenarion circle","cliffspring falls","cure poison","darkshore","dendrite starblaze","provflaska"},ang={["class:Druid"]="Att fylla provflaskan vid den nagaöversvämmade grottan är en övergångsrit för unga druider och leder direkt till att de får lära sig Cure Poison.",["race:NightElf"]="De lurande naga förorenar Darkshores rena skogsvatten och hotar både vilddjuren och bosättningen Auberdine."},sec={{t="Undersökning av det förgiftade vattnet",b="Cliffspring Falls är den främsta sötvattenkällan i norra Darkshore, så varje störning av dess källflöden innebär livsfara för det lokala ekosystemet. När traktens hjortar började dö av ett våldsamt tärande gift gav Dendrite Starblaze från Cenarion Circle dessa tomma provflaskor till unga druider som sänts ut från Moonglade. Druiderna måste ta sig djupt in bland klipporna nära fallet, ända fram till ingången till en grotta som nu kryllar av fientliga naga, och ösa upp ett användbart vattenprov."},{t="Ett botemedel tar form",b="När behållaren fyllts avslöjar det grumliga innehållet ett djupare ekologiskt fördärv. Det förorenade provet förs till Alanndarian Nightsong i Auberdine och bekräftar att illasinnade ämnen förgiftar grundvattnet. Genom att studera föroreningarna som fastnat i glaset får Alanndarian och Cenarion-druiderna den kunskap de behöver för att ta fram ett motgift och lära novisen grundläggande druidiska läkekonster."}},faq={{q="Vad används provflaskan till?",a="Det är en tom behållare som ges till druider för att samla in förgiftat vatten vid grottmynningen vid Cliffspring Falls i Darkshore. Provet hjälper Cenarions örtkunniga att fastställa orsaken till förgiftningen som drabbar traktens djurliv och bota den.",al={"provflaskans användning","vad används cliffspring-provflaskan till","tom provflaska syfte"}},{q="Var tas vattenprovet?",a="Provet måste öses upp direkt vid grottmynningen nära Cliffspring Falls, högt uppe i nordöstra Darkshores kullar. Fientliga naga håller till vid grottans ingång, så provtagningen är farlig.",al={"var fyller man provflaskan","cliffspring-provflaskans plats","plats att fylla provflaskan"}},{q="Vem får den fyllda behållaren?",a="Den fyllda provflaskan lämnas till Alanndarian Nightsong, en Night Elf-läkare och Cenarion-representant som är stationerad i kustbosättningen Auberdine.",al={"vem får den fyllda provflaskan","var lämnar man in provflaskan","alanndarian provflaska"}},{q="Varför tar man prov vid Cliffspring Falls i stället för i andra floder?",a="Cliffspring Falls är den främsta sötvattenkällan i norra Darkshore. Dendrite Starblaze spårade sjukdomen som plågar traktens hjortar till dessa källflöden, så ett direkt vattenprov är avgörande för att ta fram ett botemedel.",al={"varför cliffspring falls","vad förgiftar darkshore","cliffspring-gift"}}},fx={["0413bdcd"]={q="Vad är Empty Cliffspring Falls Sampler?",a="Det är ett särskilt kärl som ges till druider i Cenarion Circle för att samla in ett rent vattenprov från Cliffspring Falls i Darkshore. Eftersom fallen misstänks vara förgiftade krävs en steril behållare avsedd för ändamålet, så att det giftiga vattnet kan undersökas utan att provet förorenas eller bäraren skadas.",al={"vad är cliffspring falls sampler","föremålet cliffspring sampler"}},dccecdc8={q="Varifrån kommer Empty Cliffspring Falls Sampler, och vem tillverkade den?",a="Provröret tillhandahålls av druiderna i Cenarion Circle i Moonglade, närmare bestämt genom Dendrite Starblaze. När Cenarion Circle märkte att något onaturligt hade börjat förgifta Darkshores djurliv, tillverkade de behållarna så att betrodda lärlingar kunde säkra rena prover direkt från misstänkta föroreningskällor.",al={"vem gav mig cliffspring sampler","vem tillverkade provröret","provrörets ursprung"}}},fp="31,185,32.359.0,19.284.1,36.199.0,32.145.0,34.110.0,63.208.0"}
P.entries["item:empty-dreadmist-peak-sampler"] = {n="Empty Dreadmist Peak Sampler",s="Vid Dreadmist Peak söker druider efter förorenat vatten i ett tomt kärl från Cenarion Circle. Provet kan hjälpa till att fastställa orsaken till och bota farsoten som sprider sig bland djuren i norra The Barrens.",h="Vid Dreadmist Peak söker druider efter förorenat vatten i ett tomt kärl från Cenarion Circle.",kw={"the barrens","burning blade","dendrite starblaze","dreadmist peak","empty dreadmist peak sampler","den främsta källan","tonga runetotem"},ang={["class:Druid"]="Som druid är det en del av din utbildning i att bota förgiftningar samt upptäcka och lindra lidande i vildmarken att samla ett prov med det här kärlet.",["faction:Horde"]="Som medlem av Horde bär du det här provkärlet till Tonga Runetotem vid The Crossroads för att hjälpa honom att hejda den ekologiska förödelsen på The Barrens norra slätter."},sec={{t="Spåra farsoten",b="Dendrite Starblaze misstänker att dammarna på toppen av Dreadmist Peak ligger bakom en sjukdom som drabbar gaseller och skapar oro i norra The Barrens. Dammarna påverkar vädret, och druiden befarar att de hänger samman med farsoten som sprider sig. Han skickar ut druidelever med tomma provkärl för att trotsa bergets höjder och hämta vatten från toppen. Burning Blade, en demon dyrkande sekt, härjar nu på berget."},{t="Ett avgörande prov",b="Druider bär det tomma provkärlet uppför Dreadmist Peak för att samla vatten från dammen. De tar provet till Tonga Runetotem vid The Crossroads, där det kan hjälpa honom att ta fram ett botemedel och skydda de vilda djuren som hör hemma där."}},faq={{q="Vad är syftet med Empty Dreadmist Peak Sampler?",a="Empty Dreadmist Peak Sampler är en tom behållare, ett specialkärl från Cenarion Circle som druider använder för att hämta vatten från den förorenade dammen på toppen av Dreadmist Peak. De tar provet till Tonga Runetotem för att hjälpa till att ta fram ett botemedel mot sjukdomarna som drabbar djurlivet.",al={"vad gör det här föremålet","användning av dreadmist-provkärl","varför har jag det här provkärlet"}},{q="Vart måste provkärlet tas?",a="Ta provkärlet till den högt belägna dammen på toppen av Dreadmist Peak, nordväst om The Crossroads i The Barrens, och hämta ett vattenprov.",al={"var fyller jag provkärlet","provkärlets plats","hur fyller jag empty dreadmist peak sampler"}},{q="Vem tillhandahåller provkärlet?",a="Dendrite Starblaze tillhandahåller provkärlet för Cenarion Circle och skickar sedan druiden att samordna med Tonga Runetotem.",al={"vem ger provkärlet","vem startade det här uppdraget"}},{q="Varför är det så viktigt att ta vattenprov från Dreadmist Peak?",a="Dammarna på toppen av Dreadmist Peak påverkar det regionala vädret och dimman. Burning Blade-sekten har fördärvat toppen, och förorenat avrinningsvatten sprider sig över slätterna och förgiftar traktens djur.",al={"varför pölen på dreadmist peak","varför är vattnet dåligt"}}},fx={cf2d7f72={q="Vad är Empty Dreadmist Peak Sampler?",a="Det är ett särskilt kärl som Dendrite Starblaze från Cenarion Circle har anförtrott åt hordens druider. Det är endast avsett att förvara och transportera vatten från de högt belägna dammarna på Dreadmist Peak, så att det kan analyseras utan att spillas ut eller förorenas ytterligare.",al={"vad är dreadmist peak sampler","föremålet empty dreadmist peak sampler","dreadmist peak sampler"}}},fp="28,172,18.413.0,18.208.1,56.239.0,41.124.0,25.130.0,58.189.0"}
P.entries["item:empty-leaden-collection-phial"] = {n="Empty Leaden Collection Phial",s="Empty Leaden Collection Phial är en skärmad behållare som gnomiska uppfinnare konstruerat för att samla upp radioaktivt nedfall från ruinerna av Gnomeregan. Den är tillverkad av bly för att skydda bäraren från dödlig kontaminering och används av äventyrare som hjälper Ozzie Togglevolt i Kharanos. Ozzie hoppas att det infångade skenet kan ge ett botemedel åt deras drabbade släktingar – eller åtminstone en ovanligt kraftfull dryck.",h="Empty Leaden Collection Phial är en skärmad behållare som gnomiska uppfinnare konstruerat för att samla upp...",kw={"empty leaden collection phial","nedfall","gnogain","gnomeregan","kharanos","blyflaska","ozzie togglevolt","strålning"},ang={["profession:Engineering"]="Blyflaskan visar prov på gnomisk uppfinningsrikedom: strålskydd av tungmetall kombineras med en sugapparat som säkert samlar upp flyktiga partiklar från omgivningen.",["race:Gnome"]="Gnomeregans förödelse är fortfarande ett öppet sår för de landsförvisade gnomerna. Därför står mycket på spel i varje experimentellt försök att häva det giftiga nedfallet, hur excentrisk forskaren än må vara."},sec={{t="Ett skärmat kärl",b="När Gnomeregans ventilationsschakt fyllde den underjordiska staden med giftig strålning för att utrota trogg-hotet, förvandlades stadens överlevande försvarare i stället till spetälska gnomer, medan de invaderande bestarna bestrålades. Ozzie Togglevolt ville studera och häva följderna och tillverkade därför Empty Leaden Collection Phial. Den specialbyggda flaskan är gjord av tungt bly som skyddar den som hanterar den från den omgivande faran. Den suger upp det giftiga gröna sken som dröjer kvar på kropparna av Irradiated Invaders och Pillagers som stryker omkring i ruinerna. När den förseglats blir den till Full Leaden Collection Phial, som innehåller det råa, farliga material som behövs för experimentella botemedel."}},faq={{q="Vad används flaskan till?",a="Flaskan används för att suga upp och förvara farligt radioaktivt nedfall från Irradiated Invaders och Irradiated Pillagers nära Gnomeregans yttre tunnlar. När nedfallet förseglas blir behållaren en Full Leaden Collection Phial för forskning.",al={"vad gör flaskan","hur använder man empty leaden collection phial","flaskans syfte"}},{q="Varför är flaskan gjord av bly?",a="Det radioaktiva nedfallet i Gnomeregan är dödligt för oskyddade levande varelser och kan orsaka svår strålsjuka eller förvandla gnomer till spetälska. Den täta blystrukturen fungerar som en skyddsbarriär och håller samlaren säker från den instabila, glödande smittan inuti.",al={"varför en blyflaska","varför bly"}},{q="Vem skapade uppsamlingsredskapet?",a="Flaskan tillhandahålls av den gnomiska uppfinnaren Ozzie Togglevolt, som utför sina kaotiska experiment i Kharanos i Dun Morogh. Han ger behållaren till äventyrare som är villiga att trotsa den giftiga utkanten av den förstörda staden.",al={"vem tillverkade flaskan","ozzie togglevolts flaska","vem gav mig flaskan"}},{q="Vad hoppas Ozzie åstadkomma med det insamlade nedfallet?",a="Ozzie och hans medarbetare Razzle försöker uppfinna ett botemedel för de spetälska gnomer som drabbades av katastrofen. Som med många gnomiska projekt medger Ozzie att experimentformeln också kan visa sig bli ett recept på otroligt stark rom, eller kanske ett botemedel mot skallighet.",al={"varför samla nedfall","gnogainets syfte","vad tillverkar ozzie"}}},fx={["8d10cd55"]={q="Vad är Empty Leaden Collection Phial?",a="Det är en tung, skärmad behållare som är särskilt utformad för att samla in och förvara radioaktivt nedfall från de förorenade varelser som strövar bland ruinerna i Gnomeregan. Flaskan är tillverkad av tjockt bly som skyddar bäraren från det farliga smaragdgröna skenet. Den gör det möjligt för gnomiska forskare att ta prover av de giftiga resterna utan att drabbas av sjukdomen som förvrängde den fallna staden.",al={"vad är empty leaden collection phial","leaden collection phial","empty phial i gnomeregan"}}},fp="29,186,17.517.0,27.213.0,30.178.0,35.168.0,59.219.0"}
P.entries["item:empty-red-waterskin"] = {n="Empty Red Waterskin",s="I Tarren Mill är en tom röd vattenlägel på väg till en brunn som inte har förorenats. Brine ger den till shamanlärlingar inför deras elementprövningar.",h="I Tarren Mill är en tom röd vattenlägel på väg till en brunn som inte har förorenats.",kw={"brine","call of water","empty red waterskin","hillsbrad foothills","tarren mill","water sapta"},ang={["class:Shaman"]="Som shaman bär och fyller du denna lägel som ett första steg mot att bemästra Water Totem och stämma dina sinnen till vattnets motståndskraftiga andar.",["race:Orc"]="Som orc hör du Brine jämföra den rena brunnen i Tarren Mill med Warchief Thrall, en ledstjärna av styrka och hopp som består trots enormt lidande."},sec={{t="Ett kärl för rent vatten",b="Brine ger shamanlärlingar denna enkla röda lägel inför prövningarna i Call of Water. De tar den över havet till Tarren Mill i Hillsbrad Foothills. Forsaken kontrollerar staden, men dess centrala brunn ger fortfarande friskt källvatten. Den fyllda lägeln för med sig ett prov till Brine, som blandar vattnet till en Vial of Purest Water inför lärlingens prövning."}},faq={{q="Vad används Empty Red Waterskin till?",a="Shamaner använder lägeln under prövningarna i Call of Water för att hämta källvatten från brunnen i Tarren Mill. Vattnet förvandlar den till en Filled Red Waterskin.",al={"vad används empty red waterskin till","vad gör man med rött vattenskinn"}},{q="Vem ger dig vattenskinnet?",a="Brine, en orcisk shamaneremit på en kulle i södra Barrens, ger lägeln till shamanlärlingar som genomgår elementprövningar.",al={"vem ger rött vattenskinn","uppdragsgivare för rött vattenskinn"}},{q="Varför samlar man vatten just i Tarren Mill?",a="Tarren Mill står under Forsakens kontroll, men dess centrala brunn är fortfarande oförstörd. Brine ser den rena källan som ett tecken på hopp och liv som består i ett vanhelgat land.",al={"varför vatten från tarren mill","berättelsen om brunnen i tarren mill"}},{q="Vad händer när vattenskinnet är fyllt?",a="När du har fyllt lägeln vid brunnen tar du den tillbaka till Brine i Barrens. Han blandar vattnet med andra sällsynta prover till en Vial of Purest Water, som Islen Waterseer använder för att skapa Water Sapta.",al={"vad gör jag härnäst med rött vattenskinn","lämna in filled red waterskin"}}},fx={["29d0aa45"]={q="Vad är Empty Red Waterskin?",a="Det är en tom behållare som anförtros åt shamanlärlingar under deras prövningar i Call of Water. Den är utformad för att säkert transportera vätska långa sträckor och ska samla in och bevara rent brunnsvatten från Hillsbrad Foothills, så att det senare kan bryggas till en elementär sapta.",al={"vad är empty red waterskin","föremålet red waterskin","historien om empty red waterskin"}}},fp="19,142,23.352.0,41.149.0,28.131.0,47.166.0,43.206.0"}
P.entries["item:empty-sampling-tube"] = {n="Empty Sampling Tube",s="Empty Sampling Tube är en glasbehållare som Thundris Windweaver tillhandahåller i Auberdine. Den är avsedd för att samla in förorenat vatten från Cliffspring River, så att Night Elf-lärda kan studera den framryckande smittan som hotar Darkshore.",h="Empty Sampling Tube är en glasbehållare som Thundris Windweaver tillhandahåller i Auberdine.",kw={"auberdine","cliffspring river","darkshore","empty sampling tube","mist's edge","thundris windweaver","vattenprov"},ang={["class:Druid"]="Provtagningsröret är ett tidigt försök att diagnostisera den demoniska smittan från Felwood, som sipprar ut i Darkshores orörda floder och gör det lokala djurlivet sjukt.",["race:NightElf"]="För Auberdines Night Elves är det viktigt att undersöka Cliffspring River för att hindra det förorenade avrinningsvattnet från att förgifta deras kustfristad vid Mist's Edge."},sec={{t="Att undersöka vattnet",b="Medan Darkshores vildmark dukar under för en smygande farsot börjar de naturliga vattendragen bli förorenade. Thundris Windweaver, en utredare stationerad i Auberdine, tillhandahåller det här tomma glasröret för att samla konkreta bevis från Cliffspring River. Provet tas ur pölen nedanför det första vattenfallet norr om staden och låter Night Elf-naturkunniga undersöka föroreningen som sköljer mot Mist's Edge."},{t="Spåra källan",b="Fientliga Blackwood-furbolgs håller till i läger längs flodstränderna, men Windweaver misstänker att de bara är offer och spridare, inte den verkliga källan till förruttnelsen. När röret fylls bekräftas det att föroreningen rinner ner från de smittade höjderna i Felwood i öster. Det insamlade provet blir grunden för att ta fram ett möjligt botemedel och förbereda ett direkt svar på farsoten."}},faq={{q="Vad är syftet med Empty Sampling Tube?",a="Det är ett förseglat glasrör som används för att samla ett vattenprov från den förorenade Cliffspring River norr om Auberdine. Provet lämnas till Thundris Windweaver så att han kan analysera de skadliga ämnen som sprider sig genom Darkshore.",al={"varför har jag det här röret","vad gör provtagningsröret","rörets syfte"}},{q="Var ska vattenprovet tas?",a="Röret ska fyllas vid det första vattenfallet längs Cliffspring River, norr om Auberdine under en bro, precis där vattnet samlas innan det rinner vidare mot Mist's Edge.",al={"var fyller man röret","var ligger cliffspring river","plats för provtagningsröret"}},{q="Vem tillhandahöll röret?",a="Thundris Windweaver, en Night Elf-naturkunnig som studerar miljöhoten kring Auberdine, anförtror röret åt äventyrare som vågar sig ut i den smittade vildmarken.",al={"vem ger röret","uppdragsgivare för röret","thundris windweaver"}},{q="Vad förorenar Cliffspring River?",a="De lokala Blackwood-furbolgs håller till längs flodstränderna och förvärrar smutsen, men den verkliga källan till den skadliga smittan är Felwoods förorenade skog, högt uppe i bergen österut.",al={"varför är floden grön","vad förorenade vattnet","smittan i cliffspring"}}},fx={["54012ea9"]={q="Vad är Empty Sampling Tube?",a="Det är en ren glasflaska som har förberetts särskilt och getts till dig för att samla in vatten från Cliffspring River. Thundris Windweaver behöver en oförorenad behållare för att säkra ett rent prov av den vidriga sörja som just nu rinner ut i havet norr om Auberdine.",al={"vad är empty sampling tube","historien om det tomma röret","om empty sampling tube"}},b354763d={q="Varför vill Thundris ha ett prov i det här röret?",a="Vattnet i Darkshore gör invånarna snabbt sjuka, och Thundris misstänker att den vidriga smittan som rinner nedför Cliffspring River når Auberdines kust. Genom att undersöka ett färskt prov från den här behållaren hoppas han kunna avgöra om de lokala Blackwood-furbolgerna eller en mörkare korruption från Felwoods östra högland bär skulden. Det ger nattalverna underlag för sina motåtgärder.",al={"varför efterfrågas empty sampling tube","varför samla in vatten från cliffspring","varför vill thundris ha ett prov"}}},fp="19,163,18.370.0,18.316.1,47.201.0,47.166.0,23.115.0,40.161.1"}
P.entries["item:empty-water-tube"] = {n="Empty Water Tube",s="Empty Water Tube är ett enkelt glaskärl som delas ut i Auberdine för att samla heligt månbrunnsvatten. Det ska bära den välsignade vätskan upp till den märkliga röda kristallen på Darkshores östra klippor.",h="Empty Water Tube är ett enkelt glaskärl som delas ut i Auberdine för att samla heligt månbrunnsvatten.",kw={"när vattnet sköljer över","auberdine","darkshore","empty water tube","felwood","månbrunn","moonwell water tube","röd kristall"},ang={["class:Druid"]="Druider vördar månbrunnar djupt och använder deras oförstörda vatten för att studera avvikelser och rena märkliga störningar som tränger in från korrumperade områden som Felwood.",["race:NightElf"]="Att hantera invigt månbrunnsvatten är en helig plikt för Kaldorei, som vördar månbrunnarna som heliga källor välsignade av gudinnan Elune."},sec={{t="Ett kärl för välsignat vatten",b="Väktare och lärda som studerar den mystiska röda kristallen längs Darkshores östra ås behöver ren månessens för att undersöka dess natur. Vanligt glas eller vanliga flaskor kan lätt förorena invigt vatten, så den här förseglade ampullen anförtros särskilt åt de forskare som besöker månbrunnen i Auberdine. När den har fyllts bärs innehållet uppför bergssluttningarna för att se hur det främmande mineralet reagerar på Elunes magi."},{t="Att undersöka Felwoods skugga",b="Bergen omedelbart öster om Darkshore gränsar till Felwood, ett område som är grundligt förgiftat av demonisk korruption. Auberdines försvarare misstänker att den olycksbådande karmosinröda monoliten vid klipporna har en mörk koppling till den förstörda skogen. Genom att låta månbrunnsvatten skölja över dess gallerverk hoppas forskarna att det heliga vattnet ska avslöja kristallens inre struktur utan att utlösa en katastrofal frigörelse av den kraft som är fångad därinne."}},faq={{q="Vad är syftet med Empty Water Tube?",a="Det är en tom behållare som du får i Auberdine för att hämta vatten direkt från byns månbrunn. Vattnet behövs för att analysera en märklig röd kristall som hittats bland Darkshores östra höjder.",al={"syftet med empty water tube","varför har jag empty water tube","vad gör jag med water tube"}},{q="Var ska röret fyllas?",a="Det måste doppas i månbrunnen i Auberdine. När det fylls förvandlas föremålet till Moonwell Water Tube.",al={"var fyller jag water tube","var fyller jag empty water tube","plats att fylla water tube"}},{q="Varför behövs månbrunnsvatten till kristallen?",a="Månbrunnsvatten bär på Elunes kraftfulla, renande magi. De lärda tror att om de häller det över den mystiska röda kristallen reagerar det med kristallens yta och avslöjar ledtrådar om dess ursprung och sammansättning.",al={"varför månbrunnsvatten","vad gör månbrunnsvatten med kristallen","röd kristall månbrunnsvatten"}},{q="Varför oroar sig Auberdines invånare för kristallen?",a="Kristallen står nära den höga åsen med utsikt över Felwood, en skog som är svårt korrumperad av Burning Legion. De lokala väktarna fruktar att kristallen kan utgöra ett allvarligt hot mot Darkshore om den har en koppling till den fördärvade vildmarken.",al={"är kristallen farlig","kristallfara darkshore","varför undersöka den röda kristallen"}}},fx={["8160d8ef"]={q="Vad är Empty Water Tube?",a="Det är en enkel, tom glasflaska som du får i Auberdine för att samla in vatten från byns moonwell. När den är fylld använder du det välsignade vattnet för att testa den mystiska, främmande röda kristall som ligger mot bergen i Darkshore.",al={"vad är empty water tube","empty water tube","flaska för vatten från moonwell"}}},fp="16,128,27.379.0,24.372.1,44.148.0,32.108.0,45.158.0,56.186.0"}
P.entries["item:enchanted-gaea-seeds"] = {n="Enchanted Gaea Seeds",s="Enchanted Gaea Seeds är särskilt förberedda botaniska frön som ska återställa livskraften i Kalimdors härjade landskap. De har kraft genom druidisk magi och samlats in vid Sun Rock Retreat. De planteras direkt i den askfyllda jorden i The Charred Vale för att motverka förödelsen och väcka naturlig växtlighet till liv.",h="Enchanted Gaea Seeds är särskilt förberedda botaniska frön som ska återställa livskraften i Kalimdors härjade...",kw={"the charred vale","enchanted gaea seeds","gaea seed","återfödelse","stonetalon","sun rock retreat","tammra windwhisper"},ang={["class:Druid"]="Fröna visar druidernas grundläggande plikt att vårda återfödelsens kretslopp och aktivt locka tillbaka tåligt liv till ett rike som slukats av förödelse och skogsbrand.",["race:Tauren"]="För Shu'halo vid Sun Rock Retreat är planteringen av de förtrollade fröna en andlig förvaltningshandling för att hedra Jordmodern och återta sargad mark."},sec={{t="En gnista i askan",b="Enchanted Gaea Seeds visar hur horden med druidisk magi försöker läka de djupa ärren i Stonetalon Mountains. När de råa Gaea-fröna har samlats in och förtrollats i en ritual av Tammra Windfield vid Sun Rock Retreat, har de kraft nog att stå emot den utbredda korruptionen och elementarfördärvet. När fröna trycks ner i de bördiga jordkullarna som fortfarande finns kvar under sotet i The Charred Vale, slår de rot trots de hårda förhållandena och förankrar nytt liv i ett landskap som domineras av fientliga eldelementaler och invasiva harpyor."},{t="Löftet om förnyelse",b="Målet med att plantera de förtrollade fröna går längre än vanlig trädgårdsskötsel. Det är ett aktivt försök att vända utvecklingen i kampen om Stonetalon Mountains framtid. Magin som vävts in i fröskalen låter dem stå emot kvarvarande korruption och skapa fäste för traktens växter. När de frodas ska den återställda växtligheten lugna de upprörda eldelementalerna, tränga undan vilda harpyor och motverka den omfattande avskogning som Venture Company orsakar genom sin skoningslösa avverkning."}},faq={{q="Vad används Enchanted Gaea Seeds till?",a="De planteras i bördiga jordkullar i The Charred Vale. Syftet är att få tåliga växter att gro, stå emot miljömässig korruption och börja läka landet som förstörts av eld och krig.",al={"syftet med gaea-frön","vad gör enchanted gaea seeds","varför plantera gaea-frön"}},{q="Vem skapade eller förtrollade fröna?",a="Råa Gaea-frön samlas in i den omgivande vildmarken och förs till Tammra Windfield vid Sun Rock Retreat. Hon förtrollar dem så att de kan överleva den fientliga, askfyllda jorden i The Charred Vale.",al={"vem skapade fröna","tammra windwhisper-frön","hur görs gaea-frön"}},{q="Varför måste de planteras i The Charred Vale?",a="The Charred Vale är centrum för den ekologiska förstörelsen i Stonetalon Mountains och har tagits över av ursinniga eldelementaler och harpyor. När fröna planteras direkt i de jordkullar som finns kvar tillförs liv som bidrar till att lugna oron i regionen.",al={"var ska jag plantera dem","varför the charred vale","plantering i the charred vale"}},{q="Vilka hot möter de planterade fröna?",a="The Charred Vale plågas svårt av fientliga eldelementaler som uppstått ur branden, aggressiva Bloodfury-harpyor som häckar i ruinerna och den industriella förstörelse som breder ut sig från Venture Company i närheten.",al={"faror i the charred vale","vad förstör landet"}}},fx={["2eba8b82"]={q="Vad är Enchanted Gaea Seeds?",a="Enchanted Gaea Seeds är tåliga, magiskt behandlade frön som Tammra Windfield har förberett i Sun Rock Retreat. De är utformade för att stå emot miljöförstöring och fungerar som en kraftfull katalysator för återfödelse. De kan slå rot i ödelagd jord och inleda den långa läkningen av svedd mark.",al={"vad är enchanted gaea seeds","historien om enchanted gaea seeds"}}},fp="20,187,20.375.0,22.329.0,39.174.0,37.193.0,45.233.0,36.201.0"}
P.entries["item:enchanted-resonite-crystal"] = {n="Enchanted Resonite Crystal",s="Enchanted Resonite Crystal är ett alkemiskt förändrat mineral, genomsyrat av schamanistisk magi av Mor'rogal i Stonetalon Mountains. Det har skapats särskilt för att krossa Resonite-tunnan som håller den sovande, uråldriga Earthen vid namn Goggeroc fången.",h="Enchanted Resonite Crystal är ett alkemiskt förändrat mineral, genomsyrat av schamanistisk magi av Mor'rogal...",kw={"earthen vaknar","enchanted resonite crystal","goggeroc","mor'rogal","resonite-tunna","resonite crystal","stonetalon mountains"},ang={["class:Shaman"]="Kristallen visar hur elementmanipulation kan rubba även den uråldriga titanformade jordmagi som håller levande sten samman.",["faction:Horde"]="Balansen i Stonetalon är bräcklig, och Mor'rogal förlitar sig på Hordens hjältar för att oskadliggöra uråldriga hot innan de hotar utposterna i området."},sec={{t="Krossaren av uråldrig sten",b="Råa resonitkristaller från Stonetalon Mountains djupa grottor har ovanliga harmoniska egenskaper och jordegenskaper. Schamanen Mor'rogal insåg faran som slumrade i en förseglad underjordisk tunna och förändrade råmineralerna med sina elementkrafter. Den Enchanted Resonite Crystal som skapades fungerar som ett precisionsverktyg: när den slås mot den förstärkta Resonite-tunnan stör den dess hölje och väcker med våld den väldiga Earthen Goggeroc, medan han fortfarande är omtöcknad efter sin långa sömn."},{t="Hotet från Goggeroc",b="Mor'rogal trodde att en uråldrig Earthen som lämnades utan tillsyn skulle innebära katastrof för den bräckliga balansen i Stonetalon och större delen av Kalimdor. Genom att krossa tunnan med den förtrollade kristallen vill Mor'rogal tvinga varelsen att vakna i försvagat tillstånd. Det ger ett kort tillfälle att förgöra Goggeroc innan hans fulla elementkraft återvänder."}},faq={{q="Vad används Enchanted Resonite Crystal till?",a="Den används för att krossa Resonite-tunnan djupt inne i koboldfyllda grottor i Stonetalon Mountains och släppa lös den sovande Earthen som kallas Goggeroc.",al={"användning av enchanted resonite crystal","vad gör kristallen","krossa resonite-tunnan"}},{q="Vem skapade den förtrollade kristallen?",a="Taurenschamanen Mor'rogal skapade den genom att genomsyrade råa resonitkristaller med sina schamanistiska krafter för att försvaga och blottlägga varelsen som sover i tunnan.",al={"vem skapade kristallen","mor'rogals kristall","skaparen av enchanted resonite"}},{q="Varför måste Goggeroc väckas och förgöras?",a="Mor'rogal fruktar att den ojämförliga styrkan hos en uråldrig Earthen på fri fot skulle hota hela Stonetalon och Kalimdor. När kristallen väcker honom blir han tillfälligt försvagad, vilket gör det möjligt att besegra honom.",al={"varför döda goggeroc","är goggeroc farlig","hotet från goggeroc"}},{q="Vad ska jag göra med kristallen när jag har besegrat Goggeroc?",a="Du måste återlämna Enchanted Resonite Crystal till Mor'rogal tillsammans med en bekräftelse på att Goggeroc har dödats.",al={"återlämna resonite crystal","lämna in enchanted resonite crystal"}}},fx={ed58de6b={q="Vad är Enchanted Resonite Crystal?",a="Det är en förändrad mineralisk talisman som Mor'rogal i Sun Rock Retreat har laddat med shamanistisk kraft. Resonite Crystals är naturligt förekommande mineraler i grottorna i Stonetalon Mountains. När kristallen har förvandlats med magi fungerar den som en nyckel och en hammare, särskilt avsedd att krossa resonitekistan som håller den sovande jordjätten Goggeroc fången.",al={"vad är enchanted resonite crystal","historien om enchanted resonite crystal","vad betyder resonite crystal"}},d1731b4b={q="Varför vill Mor'rogal ha Enchanted Resonite Crystal?",a="Mor'rogal behöver kristallen för att befria och döda Goggeroc innan jordvarelsen vaknar med full styrka. Han fruktar att en fri jordvarelse utgör en oöverträffad fara som kan ödelägga hela Stonetalon Mountains. När du krossar kistan vaknar Goggeroc i ett kraftigt försvagat tillstånd, vilket ger dig den enda möjliga chansen att fälla honom.",al={"varför vill man ha enchanted resonite crystal","varför behöver mor'rogal kristallen","varför enchanted resonite crystal"}}},fp="26,150,24.394.0,22.288.1,48.143.1,35.146.0,44.176.0,59.96.0"}
P.entries["item:encrypted-memorandum"] = {n="Encrypted Memorandum",s="Encrypted Memorandum är ett kodat meddelande som ges till nybörjartjuvar i Coldridge Valley. Det ser ut som officiell kommunikation, men är i själva verket en hemlig inbjudan från den lokala tjuvtränaren Solm Hargrin, som manar landsflyktiga skurkar till samarbete.",h="Encrypted Memorandum är ett kodat meddelande som ges till nybörjartjuvar i Coldridge Valley.",kw={"anvilmar","coldridge valley","dun morogh","encrypted memorandum","gnomeregan","tjuvtränare","solm hargrin"},ang={["class:Rogue"]="Detta kodade brev är din formella kallelse till Dun Moroghs skuggor och för dig direkt till din lokala tränare i Anvilmar.",["race:Gnome"]="Efter Gnomeregans fall lever gnomiska tjuvar som flyktingar bland dvärgarna. I det här meddelandet finner de ett stillsamt erbjudande om gemenskap och överlevnad."},sec={{t="En diskret kallelse",b="I Anvilmars livliga dvärgfäste måste tjuvar hålla en låg profil. I stället för att värva nya rekryter öppet använder tränaren Solm Hargrin Encrypted Memorandum för att ta kontakt. Det kodade pergamentet ser ut som en officiell order från avlägsna överordnade och visar blivande tjuvar var de kan få vägledning, utan att väcka oönskad uppmärksamhet från vakterna eller misstänksamma stadsbor."},{t="Gemenskap i Coldridge",b="Bakom chiffertexten döljer sig ett budskap om praktisk överlevnad. Efter Gnomeregans fall trängs fördrivna gnomer med sina dvärgallierade i Dun Moroghs snötäckta bosättningar, där spänningarna ligger nära ytan. Solm använder meddelandet för att skapa en stillsam gemenskap och påminna sina elever om att de som utövar deras yrke måste se efter varandra när syndabockstänkande och fördomar hotar att ge dem skulden för varje försvunnen prydnadssak."}},faq={{q="Vad är Encrypted Memorandum?",a="Det är ett kodat pergament som lämnas till nybörjartjuvar i Coldridge Valley. Det uppmanar dem att söka tjuvträning under förevändning av att vara ett officiellt meddelande.",al={"vad är encrypted memorandum","memorandumföremål","tjuvmeddelande"}},{q="Vem skrev memorandumet?",a="Det skrevs av Solm Hargrin, tjuvtränaren i Anvilmar, som maskerade det som officiella order för att i hemlighet samla sina skurkaktiga gelikar.",al={"vem skrev memorandumet","vem skickade encrypted memorandum","memorandumets författare"}},{q="Varför är meddelandet krypterat?",a="Tjuvar i Coldridge Valley undviker offentlig granskning. Genom att maskera inbjudan som ett rutinmässigt tjänstemeddelande hindras lokala myndigheter och nyfikna åskådare från att upptäcka den hemliga träningen.",al={"varför krypterat","varför chifferskrift","varför är det kodat"}},{q="Vad vill Solm Hargrin?",a="Solm vill erbjuda stridsträning, vägledning och ömsesidigt skydd. Han betonar att tjuvar måste hålla ihop i det tätbefolkade Dun Morogh, där de snabbt får skulden när föremål försvinner.",al={"vad vill solm","varför hitta solm","solms syfte"}}},fx={["88db5375"]={q="Varför vill någon ha Encrypted Memorandum?",a="Memorandumet är endast avsett för dig. Solm Hargrin, skurkarnas tränare i Coldridge Valley, har skrivit det som en inbjudan till andra som utövar samma hantverk som du. Det är förklätt till officiell korrespondens och ska leda dig till honom utan att väcka oönskad uppmärksamhet bland invånarna i Anvilmar.",al={"varför vill man ha encrypted memorandum","vem vill ha encrypted memorandum","syftet med encrypted memorandum"}}},fp="20,194,18.349.0,20.377.1,33.170.0,26.136.0,29.196.0,28.186.0"}
P.entries["item:encrypted-parchment"] = {n="Encrypted Parchment",s="I Valley of Trials leder Encrypted Parchment unga orc-skurkar till The Den. Gornek ger den till rekryter som visar lovande egenskaper, och dess chiffer leder dem till Rwag, den gömda tränaren.",h="I Valley of Trials leder Encrypted Parchment unga orc-skurkar till The Den.",kw={"durotar","encrypted parchment","gornek","orc rogue","rwag","shattered hand","the den","valley of trials"},ang={["class:Rogue"]="Som skurk får du en kallelse till träning i Hordens hemliga konster hos mentorer med band till Shattered Hand.",["race:Orc"]="Som orch kanske du föredrar öppen och hederlig strid, men det här meddelandet välkomnar dem vars talanger ligger i överlevnadens tystare, dödligare konster."},sec={{t="En kallelse ur skuggorna",b="Unga orcher visar sin styrka i Valley of Trials under den öppna himlen. De som har fallenhet för smygande, bedrägeri och svärdskonst får särskild uppmärksamhet. Efter att ha mött traktens vilda djur får lovande orc-skurkar Encrypted Parchment av Gornek. Dess kodade ord lockar dem som kan läsa ett meddelande som är avsett att förbli dolt."},{t="Band till Shattered Hand",b="Chiffret leder en nybörjare in i The Den, förbi klanens andra tränare, för att hitta Rwag. Där får rekryten veta att Shattered Hand har ordnat kallelsen. Orden verkar inom Hordens hemliga nätverk, och att svara på kallelsen inleder en skurks träning i spioneri och skuggkonst."}},faq={{q="Vad är syftet med Encrypted Parchment?",a="Encrypted Parchment är en kodad kallelse som leder unga orc-skurkar till tränaren Rwag, inne i The Den i Valley of Trials.",al={"vad är encrypted parchment","pergamentets syfte","varför encrypted parchment"}},{q="Vem skickar pergamentet till dig?",a="Gornek ger dig pergamentet efter dina första prövningar i dalen. Meddelandet kommer från Rwag, skurkarnas tränare.",al={"vem skrev pergamentet","pergamentets avsändare","vem gav mig pergamentet"}},{q="Varför är meddelandet skrivet med chiffer?",a="Rwag och hans kontakter i Shattered Hand värdesätter hemlighetsmakeri. Chiffret leder rekryter som passar skurkens listiga väg in i deras dolda led.",al={"varför är det chiffrerat","varför chiffrerat","hemligt meddelande"}},{q="Vilken organisation ligger bakom kallelsen?",a="Rwag avslöjar att Shattered Hand bad honom hålla utkik efter dugliga rekryter. Orden tränar skurkar i smygande och spioneri, så att de kan tjäna Horden från skuggorna.",al={"vem vill träna mig","shattered hand rogue","vilken fraktion skickade detta"}},{q="Kan trollrogues använda det här pergamentet?",a="Nej. Trollskurkar börjar också i Valley of Trials, men de får en Encrypted Tablet i stället.",al={"troll encrypted parchment","är det också för troll"}}},fx={["268fdb07"]={q="Vad är Encrypted Parchment?",a="Encrypted Parchment är ett kodat brev som skickas till lovande unga orctjuvar som visar vad de går för i Valley of Trials. Det är skrivet med tjuvspråk eller chiffer för att undvika nyfikna blickar och hänvisar dig till din tränare Rwag, som håller sig dold i The Den.",al={"vad är encrypted parchment","föremålet encrypted parchment","vad är det här pergamentet"}},fa1aab52={q="Varför får du Encrypted Parchment?",a="Du får brevet eftersom du har fångat Shattered Hands uppmärksamhet. Det är ett skrå av lönnmördare och spejare som tjänar Horden. De vill ta dig under sina vingar, lära dig ditt dödliga hantverk och se till att du vet var deras hemliga agent Rwag finns.",al={"varför behöver jag encrypted parchment","varför encrypted parchment","syftet med encrypted parchment"}}},fp="19,186,26.329.0,26.284.0,47.132.0,31.117.0,37.147.0,40.163.0,36.98.0"}
P.entries["item:encrypted-rune"] = {n="Encrypted Rune",s="En Encrypted Rune är ett kodat kallelsemeddelande som ges till lovande nya rogues i Coldridge Valley. Det levereras i hemlighet och uppmanar mottagaren att tyda innehållet och söka upp rogue-tränaren Solm Hargrin i Anvilmar.",h="En Encrypted Rune är ett kodat kallelsemeddelande som ges till lovande nya rogues i Coldridge Valley.",kw={"anvilmar","chiffer","coldridge valley","dun morogh","encrypted rune","rogue","solm hargrin"},ang={["class:Rogue"]="Den här runan markerar din första formella kontakt med nätverket av rogues i Dun Morogh och inviger dig i konsten att smyga, använda snabba klingor och överleva.",["race:Dwarf"]="Runan förs vidare i Coldridge Valley och kallar ännu ett barn av Ironforge att bemästra skuggorna och skydda klanens intressen under ytan."},sec={{t="En kodad kallelse",b="I Coldridge Valleys skyddade, snöiga dalgång är öppen rekrytering sällan de lokala skurkarnas och spejarnas stil. I stället får noviser som visar fallenhet för smygande och list en Encrypted Rune i hemlighet. Den inskrivna stenen är märkt med subtila chiffer och bär på en diskret inbjudan från Solm Hargrin, rogue-mentorn som håller till i Anvilmar. Den fungerar både som ett privat prov i att läsa tjuvars tungomål och som en introduktion till den skuggkonst som krävs för att överleva Dun Moroghs hårda vildmark."},{t="Ögon i skuggorna",b="När de tyder runan leds nya rogues till Solm, som vill stärka dalens hemliga styrkor medan de lokala spänningarna ökar. Utöver grundläggande svärdskonst och smygtekniker betonar Solm vaksamhet och kamratskap och påminner de nyrekryterade rogues om att det är ännu viktigare för deras sort att hålla ihop i denna tid av ansträngd fred."}},faq={{q="Vad är Encrypted Rune?",a="Det är ett kodat meddelande som ges till nyblivna rogues i Coldridge Valley och instruerar dem att anmäla sig hos Solm Hargrin i Anvilmar för träning.",al={"vad är den här runan","encrypted runes syfte","vad gör runan"}},{q="Vem skickade Encrypted Rune?",a="Meddelandet kommer från Solm Hargrin, rogue-tränaren som är stationerad i Anvilmar. Han använder det för att kalla till sig nya rekryter i tysthet, utan att väcka oönskad uppmärksamhet.",al={"vem skrev den","vem gav den här","runans avsändare"}},{q="Vart ska jag ta runan?",a="Ta de dechiffrerade instruktionerna till Solm Hargrin, som finns inomhus i Anvilmar i Coldridge Valley.",al={"vart ska jag gå","vem ska jag lämna den till","var finns solm"}},{q="Varför är meddelandet krypterat?",a="Rogues förlitar sig på hemlighetsmakeri, bedrägeri och dold kommunikation. En krypterad runa ser till att bara en blivande rogue som kan läsa chiffret hörsammar kallelsen, så att deras metoder förblir dolda.",al={"varför chiffret","varför är den kodad","varför en hemlig runa"}}},fx={["1ca7ae1e"]={q="Varför skickades Encrypted Rune till dig?",a="Solm Hargrin, tjuvtränaren i Anvilmar, skickade runan för att fånga din uppmärksamhet som en lovande tjuv i Coldridge Valley. Problemen tilltar i Dun Morogh, så han söker efter dugliga händer bland dvärgar och gnomer som vet hur man håller en klinga kall och håller sig i skuggorna. Han bjuder in dig att söka upp honom för vidare träning.",al={"varför har jag encrypted rune","varför skickade solm encrypted rune","syftet med encrypted rune"}}},fp="14,174,15.345.0,19.282.0,27.149.0,28.101.0,29.86.0,29.110.0"}
P.entries["item:encrypted-scroll"] = {n="Encrypted Scroll",s="Den Encrypted Scroll är ett diskret pergament som överlämnas till lovande nyuppståndna skurkar i Deathknell. Med David Trias sigill ber det mottagaren att anmäla sig för formell utbildning bland de Forsakens hemliga agenter.",h="Den Encrypted Scroll är ett diskret pergament som överlämnas till lovande nyuppståndna skurkar i Deathknell.",kw={"david trias","deathknell","encrypted scroll","forsaken-skurkar","skurk tränare","shadowstalkers","tirisfal glades"},ang={["class:Rogue"]="Rullen markerar början på din yrkesutbildning i smygande, dyrkning av lås och smutsig strid under Forsakens skurkars vaksamma blickar.",["race:Undead"]="För de nyuppståndna i Deathknell innebär kallelsen en tidig möjlighet att säkra sig en meningsfull roll i Sylvanas framväxande rike."},sec={{t="En hemlig kallelse",b="När en nyväckt Forsaken visar fallenhet för smygande och ränksmideri förblir det inte oupptäckt länge. Envision Scroll överlämnas i Deathknell när en spanare visar sig klara sig mot den själlösa Scourge som strövar omkring på den närliggande begravningsplatsen. Med skurk tränaren David Trias personliga sigill instruerar rullen bäraren att söka upp honom på det lokala värdshuset. Den fungerar som ett första urval och visar nybörjaragenter vägen till den disciplin som krävs för att tjäna Dark Lady, i stället för att slösa bort sin andra chans till liv som simpla ficktjuvar."},{t="Shadowstalkers ögon",b="Meddelandet är kort och uppmanar skurken att ta kontakt i Deathknell innan hen beger sig djupare in i Tirisfal Glades. Trias håller uppsikt över lovande talanger på Shadowstalkers vägnar, Forsakens hemliga gren. För att överleva i Lordaeron förlitar sig Forsaken i hög grad på ljudlösa klingor och listiga spanare för att bekämpa Scarlet Crusade, överlevande alliansenklaver och kvarvarande Scourge-avskum. Att besvara denna kodade kallelse är det första steget mot att ansluta sig till det hemliga nätverket."}},faq={{q="Vad är syftet med Encrypted Scroll?",a="Encrypted Scroll är en inledande kallelse riktad till nyuppståndna Forsaken-skurkar. Den instruerar dem att anmäla sig hos David Trias på värdshuset i Deathknell för att påbörja sin yrkesutbildning som skurkar.",al={"vad gör rullen","varför krypterad rulle","rullens syfte"}},{q="Vem skickar Encrypted Scroll?",a="Rullen bär David Trias personliga sigill. Han är skurk tränaren som är stationerad i Deathknell och håller utkik efter lovande nya rekryter.",al={"vem skrev rullen","rullens avsändare","vem kommer rullen från"}},{q="Vad är Shadowstalkers som David Trias nämner?",a="Shadowstalkers är en hemlig grupp av Forsaken-skurkar, spanare och lönnmördare som verkar i hela Lordaeron. Trias bedömer nya talanger för att avgöra vilka som så småningom förtjänar att ansluta sig till deras led.",al={"vilka är shadowstalkers","shadowstalkers forsaken","shadowstalkers orden"}},{q="Vart ska jag ta Encrypted Scroll när jag har läst den?",a="När du har läst rullen ska du ta den direkt till David Trias, som finns inne på värdshuset i Deathknell.",al={"var lämna in rullen","vem ska jag lämna rullen till","lämna in rullen"}}},fx={["0c548ac5"]={q="Vad är Encrypted Scroll?",a="Encrypted Scroll är ett diskret, chiffrerat meddelande som skickas till nyvaknade tjuvar i Deathknell. Det är stämplat med tjuvtränaren David Trias personliga sigill och fungerar som en första kallelse och ett prov på diskretion. Det uppmanar lovande infiltratörer att presentera sig innan de tar sig an mer omfattande spaningsuppdrag för de Fördömda.",al={"vad är encrypted scroll","vad är den här skriftrullen","information om encrypted scroll"}},["496fc5eb"]={q="Varför vill David Trias kontakta dig med Encrypted Scroll?",a="David Trias använder brevet för att rekrytera och bedöma ny talang bland de nyuppståndna Fördömda. Shadowstalkers och den unga nationen behöver skarpa, dugliga infiltratörer snarare än klumpiga ficktjuvar. Genom att i tysthet kalla lovande rekryter till värdshuset i Deathknell ser han till att blivande agenter får rätt träning och fortsätter på vägen mot att tjäna Dark Ladys underrättelsenätverk.",al={"varför skickar david trias skriftrullen","varför behövs encrypted scroll","varför kontaktar encrypted scroll mig"}}},fp="16,202,16.437.0,26.455.0,44.119.0,31.128.0,53.156.0,54.66.0"}
P.entries["item:encrypted-sigil"] = {n="Encrypted Sigil",s="Encrypted Sigil är en kodad bricka som ges till nyvaknade nattalvsrogues i Shadowglen. Den bär dolda instruktioner från tränaren Frahun Shadewhisper och leder de nyblivna agenterna till att påbörja sin träning medan hoten mot Teldrassil växer.",h="Encrypted Sigil är en kodad bricka som ges till nyvaknade nattalvsrogues i Shadowglen.",kw={"aldrassil","encrypted sigil","frahun shadewhisper","kaldorei rogue","rogueinstruktör","shadowglen","teldrassil"},ang={["class:Rogue"]="Sigillet är startpunkten för en nattalvsrogues färd och prövar din förmåga att tyda instruktioner och ta kontakt med din lokala mentor.",["race:NightElf"]="För Kaldorei ger hemliga agenter livsviktig information i en skör tid, när nya intrång hotar de urgamla skogsgränserna från Horden."},sec={{t="En dold kallelse",b="I den skyddade gläntan i Shadowglen kontaktas nattalver som just blivit spejare och infiltratörer på diskreta sätt. En tyst budbärare överlämnar Encrypted Sigil direkt till den blivande agenten på uppdrag av Frahun Shadewhisper. Sigillet döljer sitt innehåll på ett sätt som passar yrket och instruerar mottagaren att söka upp Frahun nära Aldrassil. För Shadewhisper visar det att den blivande agenten kan följa subtila instruktioner och hantera hemliga meddelanden."},{t="Ögon i skuggorna",b="Frahun använder kallelsen för att betona hur nödvändiga rogues är i en orolig värld. Med spänningar som pyr mellan nattalverna och den avlägsna Horden påminner Shadewhisper sina rekryter om att öppet krig inte är den enda faran som hotar deras folk. Rogues måste vara Kaldoreis vaksamma ögon och osynliga klingor, samla underrättelser över hela Teldrassil och lära sig slå till innan hoten får fäste i världsträdets grenar."}},faq={{q="Vad är syftet med Encrypted Sigil?",a="Det fungerar som en första kallelse till nattalvsrogues under utbildning. Med dolda instruktioner leder det bäraren till Frahun Shadewhisper nära Aldrassil för att inleda sin formella rogueutbildning.",al={"vad gör sigillet","vad är encrypted sigil till för","varför har jag encrypted sigil"}},{q="Vem skickar Encrypted Sigil?",a="Sigillet skickas av Frahun Shadewhisper, rogueinstruktören som finns i Shadowglen under Aldrassils grenar.",al={"vem skrev sigillet","vem skickade encrypted sigil","vem kommer sigillet från"}},{q="Vad vill Frahun Shadewhisper mig?",a="Frahun vill bedöma om du är redo, betona de växande farorna som hotar nattalverna, däribland möjlig osämja som Horden kan väcka, och ge dig grundläggande stridsutbildning.",al={"varför vill frahun träffa mig","frahuns uppdrag","varför prata med frahun"}},{q="Vart ska jag ta sigillet när jag har läst det?",a="Ta det till Frahun Shadewhisper, som finns inne i det stora trädet Aldrassil i Shadowglen.",al={"vart ska jag ta encrypted sigil","var finns frahun","var är frahun"}}},fx={f0a92b78={q="Vad är Encrypted Sigil?",a="Encrypted Sigil är ett kodat meddelande till lovande nattalvtjuvar som påbörjar sin resa i Shadowglen. Det är märkt med dold skrift för att skydda känsliga ärenden från nyfikna blickar. Det fungerar som en officiell kallelse från den lokala tjuvtränaren Frahun Shadewhisper, som vill bedöma och vägleda nya talanger inför de skuggfyllda utmaningar som väntar deras folk.",al={"vad är encrypted sigil","berättelsen om encrypted sigil","vad gör sigillet"}},["66ac44ca"]={q="Varför vill Frahun Shadewhisper att Encrypted Sigil ska återlämnas?",a="Frahun Shadewhisper ber dig att ta tillbaka sigillet till honom när du har dechiffrerat det, så att han kan bekräfta att du fått kallelsen och kan följa yrkets metoder diskret. När du visar upp tecknet bekräftar du din identitet och att du är redo att börja din formella träning i smygande, informationsinsamling och vapenhantering.",al={"varför vill frahun ha sigillet","varför återlämna encrypted sigil","vem vill ha encrypted sigil"}}},fp="15,174,16.383.0,19.368.0,43.154.0,30.114.0,43.173.0,45.67.0"}
P.entries["item:encrypted-tablet"] = {n="Encrypted Tablet",s="I Valley of Trials skickar Encrypted Tablet unga trollskurkar till Rwag. Skurkarnas tränare ristar in dess kodade budskap och håller till i The Den.",h="I Valley of Trials skickar Encrypted Tablet unga trollskurkar till Rwag.",kw={"durotar","encrypted tablet","skurkarnas tränare","rwag","shattered hand","the den","valley of trials"},ang={["class:Rogue"]="Som skurk får du den chiffrerade skiffertavlan som ditt första steg in i Hordens formella led. Den visar dig till Rwags träning i The Den.",["race:Troll"]="Som en Darkspear-troll under träning i Durotar får du den här tavlan som bevis på att din smidighet och förmåga att smyga har fångat dalens tränares uppmärksamhet."},sec={{t="En dold kallelse",b="Unga trollskurkar får Encrypted Tablet när de anländer till Valley of Trials. Dess chiffrerade ord visar dem vägen till Rwag, en orctränare som bor i The Dens skuggiga grottor. Skiffertavlan håller de lokala skuggagenternas förehavanden hemliga och prövar samtidigt om nya rekryter kan förstå budskapet."},{t="Handens ögon",b="När rekryterna tyder tavlan får de kontakt med Hordens större skuggnätverk. När de rapporterar till Rwag får spejarna veta att syndikat som Shattered Hand följer deras framsteg. Syndikaten förlitar sig på dalens tränare för att avgöra om blivande ficktjuvar, spioner och lönnmördare är skärpta nog att tjäna den nya nationen."}},faq={{q="Vad används Encrypted Tablet till?",a="Encrypted Tablet uppmanar unga trollskurkar att rapportera till Rwag, skurkarnas tränare som håller till i The Den i Valley of Trials.",al={"plattans syfte","vad gör encrypted tablet","varför har jag encrypted tablet"}},{q="Vem skrev meddelandet på plattan?",a="Rwag, skurkarnas tränare i Valley of Trials, skrev budskapet. Han ansvarar för att träna tjuvar, ficktjuvar och lönnmördare åt Horden.",al={"vem skickade encrypted tablet","plattans upphovsperson","vem skrev det här"}},{q="Var hittar jag Rwag?",a="Rwag håller till i The Den, ett grottsystem längs den norra bergsryggen i Valley of Trials i Durotar.",al={"var finns rwag","rwags plats","hitta skurkarnas tränare i valley of trials"}},{q="Vad syftar ”Handen” som Rwag nämner på?",a="The Hand är Shattered Hand, en hemlig orden i Hordens skuggnätverk för skurkar. Rwag rapporterar till dem om hur redo nya agenter från dalen är.",al={"vilken hand","vilka är handen","shattered hands koppling"}}},fx={["395214f3"]={q="Vad är Encrypted Tablet?",a="Encrypted Tablet är en kodad stentavla som skickas särskilt till dig när du börjar din träning i Valley of Trials. Den är krypterad för att skydda innehållet från nyfikna blickar och fungerar som en kallelse som prövar din klurighet och visar dig vägen till den lokala tjuvtränaren.",al={"encrypted tablet","vad är encrypted tablet","föremålet tablet"}},["3f134c2e"]={q="Varför behövs Encrypted Tablet?",a="Tjuvtränaren Rwag skickade tavlan för att se till att nyanlända skurkar hittar till hans lya. När du dechiffrerar det krypterade meddelandet visar du att du har det förstånd som krävs av en tjuv och får veta precis var du ska söka hans vägledning.",al={"varför behövs encrypted tablet","varför behövs tavlan","vem vill ha encrypted tablet"}}},fp="16,161,16.312.0,16.338.0,38.131.0,36.144.0,21.101.0,37.156.0"}
P.entries["item:essence-of-nightlash"] = {n="Essence of Nightlash",s="Essence of Nightlash är en kvarvarande magisk rest från bansheen Nightlash, som besegrades vid Dead Fields. Den är ett obestridligt bevis för High Executor Hadrec på att Scourge-styrkan som stärkte de lokala rot hide-gnollerna har brutits.",h="Essence of Nightlash är en kvarvarande magisk rest från bansheen Nightlash, som besegrades vid Dead Fields.",kw={"banshee","dead fields","stoft","essens","hadrec","nightlash","rot hide","the sepulcher"},ang={["class:Mage"]="Arkanister och lärda undersöker ofta resterna efter förstörda bansheer för att studera hur spektrala odöda förankrar nekrotisk magi i den fysiska världen.",["race:Undead"]="Forsaken-soldater ser det som livsviktigt att utrota bansheer som Nightlash. Eftersom de själva en gång föll offer för Scourges herravälde är det avgörande att förgöra Lich Kings agenter för att säkra Lordaeron åt sitt eget folk."},sec={{t="Bansheen vid Dead Fields",b="På en övergiven gård i norra Silverpine, känd som Dead Fields, har flockar av odöda rot hide-gnoller befäst sig under Scourges befäl. De första anfallen från Forsaken slogs gång på gång tillbaka, inte av de vildsinta gnollerna, utan av deras vålnadslika befälhavare: bansheen Nightlash. Med jämrande magi stärkte hon gnollernas led och drev styrkorna från Sepulcher på flykten. När hon dödas upplöses hennes okroppsliga gestalt till stoft och lämnar efter sig en kristallin, magisk essens som visar att hon har upplösts för gott."},{t="Bevis på Scourges nederlag",b="Eftersom bansheer inte lämnar efter sig någon kropp är Essence of Nightlash det enda fysiska beviset på att den ondskefulla anden har förstörts. High Executor Hadrec vid Sepulcher behöver essensen för att bekräfta att Scourges lokala fäste har fallit, så att Forsaken äntligen kan säkra sin norra gräns och kuva hotet från rot hide-gnollerna."}},faq={{q="Vad är Essence of Nightlash?",a="Det är kristalliserat stoft som blir kvar när Scourge-bansheen Nightlash besegras. Eftersom andar saknar fysiska kroppar fungerar den här magiska resten som bevis på hennes död.",al={"essence of nightlash","nightlash-stoft","vad är nightlash-essens"}},{q="Vem är Nightlash?",a="Nightlash är en banshee i Scourges tjänst som leder och stärker rot hide-gnollerna från Dead Fields i norra Silverpine.",al={"vem är nightlash","nightlash-lore","bansheen nightlash"}},{q="Vem vill ha essensen?",a="High Executor Hadrec vid Sepulcher ber Forsaken-mästare hämta den som bevis på att bansheen som slog tillbaka hans styrkor vid fronten har oskadliggjorts.",al={"vem behöver nightlash-essens","vem lämnar in essensen","high executor hadrec"}},{q="Varför samarbetar gnollerna med en banshee?",a="Rot hide-gnollerna vid Dead Fields har dukat under för de odödas farsot och blivit Scourges trälar. Nightlash skickades dit för att övervaka dem och ge magiskt stöd mot Forsaken-patruller.",al={"gnoller och scourge","rot hide och scourge","varför gnoller med banshee"}}},fx={["13c624cf"]={q="Var kommer Essence of Nightlash ifrån?",a="Essensen kommer från bansheen Nightlash själv. När du möter och besegrar henne vid Dead Fields kollapsar hennes vålnadsgestalt och hennes essens förvandlas till stoft. Kvar blir lämningen som du samlar upp.",al={"essence of nightlashs ursprung","hur får man essence of nightlash","varifrån får man essence of nightlash"}}},fp="20,188,30.487.0,23.314.0,33.176.0,17.122.0,23.134.0,42.188.0"}
P.entries["item:essential-artificial"] = {n="Essential Artificial",s="En Essential Artificial är en mångsidig, standardiserad mekanisk komponent som är avgörande för gnomiska uppfinnare och ingenjörer. Delarna lämnades kvar i förråd under den kaotiska evakueringen av Gnomeregan och är mycket eftertraktade av gnomer som vill återuppta sitt tekniska arbete från exilen i Ironforge.",h="En Essential Artificial är en mångsidig, standardiserad mekanisk komponent som är avgörande för gnomiska...",kw={"artificial extrapolator","ingenjörskomponent","essential artificial","gnomeregan","klockmort spannerspan","tinker town"},ang={["profession:Engineering"]="Ingenjörer kan uppskatta elegansen hos en nästan universell mekanisk del som är utformad för att passa sömlöst i olika maskiner och experimentella konstruktioner.",["race:Gnome"]="Varje komponent som bärgas från Gnomeregans bestrålade korridorer hjälper de landsflyktiga gnomerna att återupprätta sitt tekniska övertag medan de söker skydd i Ironforge."},sec={{t="Standardiserad uppfinningsrikedom",b="Före Gnomeregans fall var Essential Artificial en hörnsten i gnomisk ingenjörskonst till vardags. Uppfinnare beskriver den som en nästan universell komponent som ingick i otaliga manicker, urverksunderverk och tunga maskiner i de underjordiska salarna. Den standardiserade utformningen gjorde den oumbärlig för smeder och maskinister som behövde pålitliga, utbytbara moduldelar."},{t="Bärgning från djupet",b="När trogginvasionen och den efterföljande strålningskatastrofen tvingade gnomerna att fly i panik lämnades stora lager av dessa komponenter kvar. De finns fortfarande i tunga, ångdrivna behållare som kallas artificial extrapolators, utspridda i Gnomeregans djupare gångar. I Tinker Town rekryterar mästerhantverkaren Klockmort Spannerspan modiga äventyrare för att återvända till de förorenade ruinerna och bärga delarna, så att forskning och uppfinningar kan fortsätta."}},faq={{q="Vad är en Essential Artificial?",a="Det är en standardiserad, mycket mångsidig mekanisk komponent som gnomiska smeder och uppfinnare använder flitigt i sina experiment, maskiner och manicker.",al={"vad är essential artificials","föremålet essential artificial","vad är den här komponenten"}},{q="Varför lämnades de kvar i Gnomeregan?",a="När troggarna invaderade och staden fylldes av dödlig strålning flydde gnomerna i all hast. I evakueringspaniken lämnades lager av vardagliga komponenter helt enkelt kvar i förvaringsbehållare.",al={"varför finns de i gnomeregan","varför övergavs de"}},{q="Vem vill få komponenterna bärgade?",a="Klockmort Spannerspan, en ambitiös gnomisk uppfinnare som håller till i Tinker Town i Ironforge, söker efter dem för att driva sina pågående experiment och sin tekniska forskning i exil.",al={"vem behöver essential artificials","vem hämtar dem","klockmort spannerspans uppdrag"}},{q="Var finns de i ruinerna?",a="De förvaras i stora, ångdrivna mekaniska behållare som kallas artificial extrapolators, utspridda i de djupare delarna av förorenade Gnomeregan.",al={"var hittar jag essential artificials","var finns artificial extrapolator"}}},fx={["691fb1fc"]={q="Var kommer essential artificials ifrån, och vem tillverkade dem?",a="Essential artificials är precisionskomponenter som konstruerades och tillverkades av Gnomeregans pysslare och smeder innan deras stora stad föll. De massproducerades för gnomisk teknologi och förvarades i automatiska behållare som kallades artificial extrapolators, placerade i stadens djupare industrikomplex.",al={"vem tillverkade essential artificials","essential artificials ursprung","var kommer essential artificials ifrån"}}},fp="20,170,24.312.0,23.452.0,32.153.0,40.138.0,37.161.0,38.161.0"}
P.entries["item:etched-note"] = {n="Etched Note",s="Etched Note är en formell kallelse till lovande unga taurenjägare som vilar vid Camp Narache. Den är skriven av lägrets jaktinstruktör Lanka Farshot och välkomnar nybörjaren till jaktens traditioner och kallar hen till sin första undervisning.",h="Etched Note är en formell kallelse till lovande unga taurenjägare som vilar vid Camp Narache.",kw={"camp narache","etched note","lanka farshot","mulgore","red cloud mesa","taurenjägare","instruktörens kallelse"},ang={["class:Hunter"]="Anteckningen markerar ditt formella inträde i jägarnas tradition och utlovar lektioner i hantering av avståndsvapen och samspel med slätternas bestar.",["race:Tauren"]="Med dina äldstes och din släkts förväntningar på dina axlar kallar mottagandet av anteckningen dig att bemästra Mulgore böljande gräsmarker innan du reser till avlägsna länder."},sec={{t="En kallelse till jakt",b="I Camp Naraches trygga famn uppmärksammas unga shu'halo tidigt för sina naturliga anlag och sin släkthistoria. En budbärare överlämnar Etched Note på uppdrag av Lanka Farshot, lägrets jaktmentor. Den beskriver jägaren som stammens hjärta och påminner strängt om att rå instinkt måste formas genom rigorös undervisning och djup vördnad för Mulgore vildmark."},{t="Shu'halos traditioner",b="För tauren är jakt mycket mer än ett praktiskt sätt att överleva. Den är en hedrad, helig disciplin som är invävd i stammens samhälle. Anteckningen påminner läsaren om att jägare förenar krigarens, schamanens och druidens roller och att stammen kommer att se till dem för vägledning och beskydd. När eleven överlämnar brevet till Lanka tar hen sina första officiella steg mot att lära sig vapenkonst, förstå bestar och fullgöra sin plikt att försvara och försörja stammarna."}},faq={{q="Vad är syftet med Etched Note?",a="Den fungerar som en inledande kallelse för taurenjägare i träning. När du läser anteckningen får du veta att du ska infinna dig hos Lanka Farshot i Camp Narache för att påbörja din formella träning i prickskytte och kunskap om bestar.",al={"vad gör anteckningen","användning av etched note","varför fick jag etched note"}},{q="Vem skrev anteckningen?",a="Meddelandet skrevs av Lanka Farshot, jaktinstruktören i Camp Narache. Han skickar kurirer över platån för att hitta unga jägare som är redo att lära sig.",al={"vem skickade etched note","vem skrev den","författare till etched note"}},{q="Varför är jakt så viktig för tauren?",a="Jakt är en hörnsten i taurens överlevnad, andlighet och stamtradition. Skickliga jägare skaffar mat och material åt sitt folk samtidigt som de lever i direkt balans med landet och vördar andarna hos de bestar de fäller.",al={"taurenjägarnas historia","varför jagar tauren","jakt i taurens kultur"}},{q="Vart ska anteckningen lämnas?",a="Ta anteckningen direkt till Lanka Farshot, som står nära paviljongen och träningsplatserna i Camp Narache på Red Cloud Mesa.",al={"vart ska jag ta anteckningen","vem ska jag lämna in den till","lämna in etched note"}}},fx={["10b0f74a"]={q="Vad är Etched Note?",a="Etched Note är en skriven kallelse särskilt riktad till nybörjarjägare av taurenfolket som anländer till Camp Narache. Den är ristad med ett kort meddelande från lägrets jakttränare Lanka Farshot. Den påminner dig om att jägarna är stammens hjärta och ber dig söka upp honom i Camp Narache för att börja bemästra jakten.",al={"vad är etched note","föremålet etched note","etched note i mulgore"}},bd70af04={q="Varför vill Lanka Farshot att du tar med dig Etched Note?",a="Lanka Farshot låter skicka lappen för att ta lovande unga jägare direkt under sina vingar. Han tänker pröva om du är redo och lära dig jaktens viktiga traditioner, från att hantera avståndsvapen till att tämja bestar. På så sätt ser han till att du kan tjäna och skydda stammen på Mulgore-slätterna.",al={"varför lämna över etched note","varför vill lanka ha etched note","syftet med etched note"}}},fp="11,172,18.260.0,26.348.0,39.162.0,20.138.0,42.199.0,34.116.0"}
P.entries["item:etched-parchment"] = {n="Etched Parchment",s="Gornek ger jägarna i Valley of Trials en kallelse från Jen'shan. Etched Parchment visar dem vägen till deras första lektioner i Durotar.",h="Gornek ger jägarna i Valley of Trials en kallelse från Jen'shan.",kw={"durotar","etched parchment","gornek","jägare","jen'shan","tränare","valley of trials"},ang={["class:Hunter"]="Som jägare får du detta budskap som ditt första övergångsprov i Durotar. Det för dig till Jen'shan, som lär ut spårning, distansvapen och överlevnad.",["faction:Horde"]="Som medlem av Horde finslipar du ditt hantverk. För en jägare markerar detta pergament det första steget mot att föda din klan och vakta Durotars gränser."},sec={{t="En kallelse till jakten",b="Unga orcher och Darkspear Trolls inleder sina riter i Valley of Trials. När rekryterna visar vad de går för mot traktens skadedjur vägleder Gornek dem mot deras kall. Han ger Etched Parchment till dem som ska hantera båge, bössa och huggtänder. Budskapet kommer från Jen'shan, en skicklig jaktinstruktör som söker nya ögon och stadiga händer."},{t="Den första lektionen",b="När jägaren tar med sig pergamentet till Jen'shan börjar träningen i Durotar. Hon lär ut att den vilda vägen kräver hängivenhet: att bemästra öknens vidunder kräver lika mycket ansträngning som en arkanists magi eller en shamanens arbete med andarna. Hennes kallelse för nya jägare till lektioner i skytte och överlevnad i vildmarken."}},faq={{q="Vad används Etched Parchment till?",a="Etched Parchment visar nya jägare i Valley of Trials vägen till deras instruktör, Jen'shan.",al={"användning av etched parchment","vad gör etched parchment"}},{q="Vem delar ut pergamentet?",a="Gornek ger pergamentet till unga jägare nära The Den i Valley of Trials.",al={"vem delar ut etched parchment","uppdragsgivare för etched parchment"}},{q="Vem skrev Etched Parchment?",a="Jen'shan skrev budskapet. Hon är en trollisk jaktinstruktör i Valley of Trials, redo att träna nya skyttar.",al={"vem skickade etched parchment","pergamentets författare"}},{q="Var hittar man Jen'shan?",a="Jen'shan väntar i Valley of Trials i Durotar, nära träningsområdet, för att undervisa nya orc- och trolljägare.",al={"var finns jen'shan","hitta jen'shan"}}},fx={ddc4492f={q="Vad är Etched Parchment?",a="Etched Parchment är en skriven kallelse särskilt riktad till nybörjarjägare som anländer till Valley of Trials. Du får den av Gornek. Den innehåller en direkt uppmaning att söka upp den lokala jakttränaren Jen'shan, så att du kan börja lära dig att överleva i Durotars hårda röda ödemarker och bemästra vilddjuren som strövar där.",al={"vad är etched parchment","föremålet etched parchment","om etched parchment"}},f14a07d9={q="Varför vill Jen'shan att du lämnar tillbaka Etched Parchment till henne?",a="Jen'shan sparar inte pergamentet som en dyrbar relik. Hon använder det som en formell kallelse för att föra de blivande jägarna till sig. När du överlämnar det bekräftar du att du hörsammat hennes uppmaning och är redo att lära dig bågskytte, prickskytte och att överleva sida vid sida med Durotars vildsinta rovdjur.",al={"varför ta med etched parchment","varför vill jen'shan ha pergamentet","syftet med etched parchment"}}},fp="16,141,21.339.0,16.321.0,33.91.0,29.81.0,31.111.0,28.119.0"}
P.entries["item:etched-rune"] = {n="Etched Rune",s="Etched Rune är en ristad stentavla som ges till blivande dvärgjägare i Coldridge Valley. Den fungerar som en inbjudan från jakttränaren Thorgas Grimson och visar nybörjarna att söka upp honom i Anvilmar för att påbörja sin formella vildmarksutbildning.",h="Etched Rune är en ristad stentavla som ges till blivande dvärgjägare i Coldridge Valley.",kw={"anvilmar","coldridge valley","dun morogh","dvärgjägare","etched rune","jaktträning","thorgas grimson"},ang={["class:Hunter"]="Runan markerar din första formella kallelse till dvärgarnas urgamla jaktkonst, där du får lära dig att spåra, respektera dina djurföljeslagare och överleva i den hårda vildmarken med ditt eget förstånd.",["race:Dwarf"]="Ristade stenar och runor är traditionella sätt för dvärgar att föra vidare hantverkskunskaper och brådskande instruktioner, även till härdade vandrare i Coldridge Valleys snö."},sec={{t="Vildmarkens kall",b="Den här lilla stentavlan, täckt av särskilda dvärgrunor, ges vidare till nybörjare som visar fallenhet bland snödrivorna i Coldridge Valley. Runan har skickats av bergsbestigaren och jakttränaren Thorgas Grimson och uppmanar nyblivna spårare att avbryta sina sysslor utomhus och bege sig till Anvilmar. Att läsa stenen markerar jägarens första steg bort från grundläggande överlevnad och mot en djupare förståelse för vildmarkens hantverk – att lära sig respektera Dun Moroghs bestar, spåra bergsrovdjur, sköta avståndsvapen och uthärda de skoningslösa elementen."}},faq={{q="Vad är syftet med Etched Rune?",a="Runan fungerar som en kallelse till utbildning för dvärgjägare. När du läser inskriften på tavlan får du veta att du ska söka upp Thorgas Grimson inne i Anvilmars värme för att få formell vägledning i jägarens hantverk.",al={"vad gör etched rune","använda etched rune","varför har jag etched rune"}},{q="Vem skrev eller skickade Etched Rune?",a="Runan skickades av Thorgas Grimson, den lokala jakttränaren som håller till i Anvilmar. Han ger dessa ristade stenar till nybörjare som rör sig i trakterna kring Coldridge Valley och visar fallenhet för att överleva i den frusna vildmarken.",al={"vem skickade etched rune","vem gav mig den här runan","etched rune upphovsperson"}},{q="Vart ska jag ta Etched Rune när jag har läst den?",a="Ta runan till Anvilmars huvudbyggnad i Coldridge Valley. Där hittar du Thorgas Grimson nära smedjan och träningshallarna, redo att lära dig spårning, vapenvård och dvärgarnas jakttraditioner.",al={"var ska jag ta etched rune","lämna in etched rune","thorgas grimson plats"}}},fx={["455fa37e"]={q="Vad är Etched Rune?",a="Etched Rune är en ristad stentavla som lämnas till nybörjarjägare av dvärgasläkt när de börjar sin träning i Coldridge Valley. I stället för vanligt pergament fungerar den som en beständig kallelse med ett budskap inristat i runor, vilket speglar dvärgarnas djupt rotade hantverk och traditioner kring överlevnad i vildmarken.",al={"vad är etched rune","föremålet etched rune","berättelsen om etched rune"}},["537b1d7a"]={q="Varför vill Thorgas Grimson att du tar med dig Etched Rune?",a="Runan är en formell kallelse till träning som skickats av Thorgas Grimson, jakttränaren i Anvilmar. När du bär den med dig bekräftar du att du visat grundläggande förmåga i dalen och är redo för ordentlig undervisning i spårning, vapenvård och vildmarkens traditioner.",al={"varför vill thorgas ha runan","varför behövs etched rune","syftet med kallelsen i etched rune"}}},fp="11,168,16.413.0,39.131.0,34.159.0,52.185.0"}
P.entries["item:etched-sigil"] = {n="Etched Sigil",s="En inskriven bricka som en skogslöpare överlämnar till nyvakna Night Elf-jägare i Shadowglen. Den bär en kallelse från jakttränaren Ayanna Everstride uppe på den väldiga grenen Aldrassil.",h="En inskriven bricka som en skogslöpare överlämnar till nyvakna Night Elf-jägare i Shadowglen.",kw={"aldrassil","ayanna everstride","etched sigil","jägare","shadowglen","teldrassil"},ang={["class:Hunter"]="Denna inskrivna talisman markerar början på en kaldorei-jägares resa mot att bemästra bågen och djurens seder under Ayanna Everstrides vägledning.",["race:NightElf"]="Sigillet överlämnas i Shadowglens avskilda trädkronor och hedrar de uråldriga traditionerna hos nattalvernas skogsväktare, som vigt sig åt att skydda Teldrassil."},sec={{t="Vildmarkens kallelse",b="Etched Sigil är ristad med jaktens tecken och överlämnas till nyvakna Night Elf-jägare när de träder in i Shadowglen. Brickan är en officiell underrättelse och välkomsthälsning från Ayanna Everstride, den lokala jakttränaren som bor högt uppe bland Aldrassils urholkade grenar. Sigillet uppmanar nybörjaren att söka upp henne och inleder en livslång utbildning i bågskytte, spårning i vildmarken och det uråldriga bandet mellan nattalvernas jägare och deras djur."}},faq={{q="Vad är syftet med Etched Sigil?",a="Sigillet är en direkt kallelse som uppmanar en nybörjare bland Night Elf-jägarna att söka upp sin tränare, Ayanna Everstride, uppe i Aldrassil i Shadowglen. Där får hen börja sin formella utbildning i överlevnad, spårning och bågskytte.",al={"vad gör etched sigil","använda etched sigil","varför har jag det här sigillet"}},{q="Vem skickar Etched Sigil?",a="Det tillverkas och skickas av Ayanna Everstride, jakttränaren som vakar över de spirande skogsjägarna i Shadowglen.",al={"vem skickade etched sigil","varifrån kommer etched sigil"}},{q="Vart ska sigillet tas?",a="Det ska föras till de övre delarna av det väldiga trädet Aldrassil, mitt i Shadowglen, där Ayanna Everstride väntar.",al={"vart ska jag ta etched sigil","vem ska jag ge etched sigil till"}},{q="Varför får Night Elf-jägare ett sigill i stället för ett brev på papper?",a="Kaldorei-traditioner föredrar naturliga ristningar och tåliga brickor med heliga symboler för Elune och vildmarken framför vanligt pergament. Det speglar jägarens band till skogen.",al={"varför sigill i stället för brev","vad är sigillet gjort av"}}},fx={fbac1def={q="Vad är Etched Sigil?",a="Etched Sigil är ett tecken med en ristad kallelse till blivande nattalvjägare i Shadowglen. En budbärare överlämnar det till dig när du anländer till Teldrassil. Det fungerar som en officiell introduktion till Ayanna Everstride och bjuder in dig att påbörja din formella träning i prickskytte och bestträning under Aldrassils grenar.",al={"vad är etched sigil","föremålet etched sigil","om etched sigil"}},e2d33d60={q="Varför vill Ayanna Everstride att du tar med dig Etched Sigil till henne?",a="Ayanna Everstride skickar sigillet för att se till att du vet var du kan få vägledning i Shadowglen. När du återlämnar det till henne högst upp i Aldrassil visar du att du fått hennes meddelande och är redo att påbörja din träning. Du får lära dig att hantera bågar med säker precision och visa respekt för Kalimdors vilda varelser.",al={"varför ta med etched sigil","varför vill ayanna ha sigillet","vem vill ha etched sigil"}}},fp="12,77,20.381.0,40.147.0,27.76.0,32.66.0,68.77.0"}
P.entries["item:explosive-stick-of-gann"] = {n="Explosive Stick of Gann",s="I södra Barrens vänder Gann Stonespire stulna dvärgplaner mot Bael Modan. Han byggde sprängladdningen för att sabotera dvärgarnas flygmaskin.",h="I södra Barrens vänder Gann Stonespire stulna dvärgplaner mot Bael Modan.",kw={"bael modan","explosive stick of gann","flygmaskin","gann stonespire","prospektören khazgorm","stonespire-stammen","the barrens"},ang={["profession:Engineering"]="Som ingenjör kan du se hur stulna ritningar vändes mot dvärgarnas maskiner.",["race:Tauren"]="Som tauren hämnas du den fördrivna stammen Stonespire och slår tillbaka mot Prospectorernas utgrävning i Kalimdors heliga jord."},sec={{t="Ett hämndens vapen",b="När Prospector Khazgorm ledde Ironforges utgrävning i södra Kalimdor drev dvärgarna bort taurenfolket Stonespire från deras förfädersby och jämnade deras heliga marker med marken för att bygga Bael Modan. Gann Stonespire tog tillbaka Khazgorms ritningar för att hämnas sina fördrivna och stupade fränder. Han studerade planerna och satte ihop en laddning med kraft nog att förstöra tung maskinutrustning."},{t="Siktet inställt på flygmaskinen",b="Gann tillverkade sprängstaven för dvärgarnas flygmaskin på ett utsiktstorn ovanför utgrävningen. För honom är maskinen mer än ett transportmedel eller ett krigsvapen. Den symboliserar Alliansens herravälde över taurenfolkets heliga jord. Att förstöra den lamslår dvärgarnas utpost och blir ett slag för den förlorade stammen Stonespire."}},faq={{q="Vad är Explosive Stick of Gann?",a="Gann Stonespire tillverkade sprängladdningen av återfunna dvärgscheman för att sabotera Prospectorernas maskiner på sina förfäders marker.",al={"explosive stick of gann","ganns sprängladdning","ganns bomb"}},{q="Vem tillverkade sprängladdningen?",a="Gann Stonespire satte ihop sprängladdningen för att hämnas sin stam efter att dvärgarna från Ironforge vid Bael Modan förstört deras by och skändat deras hemland i södra Barrens.",al={"vem tillverkade den","vem är gann","gann stonespire"}},{q="Vad är sprängladdningen tänkt att spränga?",a="Laddningen ska förstöra dvärgarnas flygmaskin på ett torn ovanför utgrävningen vid Bael Modan. Förstörelsen lamslår platsens spaning och blir en symbolisk hämnd för stammen Stonespire.",al={"vad ska jag spränga","flygmaskin som mål","var använder jag den"}},{q="Hur lärde sig en tauren att tillverka dvärgarnas sprängämnen?",a="Gann byggde staven av ingenjörsritningar som han återfann från Prospector Khazgorm, ledaren för dvärgarnas utgrävning vid Bael Modan. Han vände inkräktarnas egen teknik mot dem.",al={"hur byggde gann den","sprängämnesscheman","khazgorms ritningar"}}},fp="23,150,23.376.0,25.314.1,36.143.0,24.180.0,42.209.0,50.180.0"}
P.entries["item:faded-shadowhide-pendant"] = {n="Faded Shadowhide Pendant",s="En anlupen talisman som en gång bars av Shadowhide-gnollerna i Redridge och var förtrollad att förmedla mörka order. Till bärarens förvåning innehåller hänget också ett fördröjt magiskt meddelande från magikern Theocritus.",h="En anlupen talisman som en gång bars av Shadowhide-gnollerna i Redridge och var förtrollad att förmedla mörka...",kw={"elwynn","gnoller","morganth","hänge","redridge","shadowhide","theocritus","tower azora"},ang={["class:Mage"]="Hänget visar hur subtilt magiskt avlyssnande kan vara och att även grova eller mörka förtrollningar kan avkodas och kapas av en disciplinerad magiker.",["faction:Alliance"]="Att hämta den här amuletten hjälper Tower Azora att försvaga Shadowhide-gnollerna som hotar stabiliteten i både Elwynn Forest och Lakeshire."},sec={{t="Ett brutet nätverk",b="Shadowhide-gnollerna som strövar i Redridge Mountains lyder en ondskefull herre vid namn Morganth och samordnar sina rörelser genom förtrollade hängen. När High Mage Theocritus undersökte talismanerna från sin tillflykt i Tower Azora utformade han en experimentell besvärjelse för att tränga igenom deras mystiska frekvens. Hans magiska sändning tog flera veckor på sig att visa sig, men det här bleknade hänget bevisade att gnollernas kommunikationslinje kan kapas, vilket öppnar en väg att begränsa deras mörke herres inflytande."},{t="Magikerns ambition",b="Att själv studera det bleknade hänget ger Theocritus mycket mer än bara avlyssnat prat. Genom att undersöka hur förtrollningen klarade hans intrång hoppas magikern finslipa sin trolldom till ett vapen som kan skicka förlamande attacker direkt genom alla likadana amuletter som bärs runt om i Redridge. Att återlämna föremålet till Tower Azora i Elwynn Forest är det viktiga första steget mot att bryta Morganths grepp om regionens gnoller."}},faq={{q="Vad är Faded Shadowhide Pendant?",a="Det är en förtrollad amulett som ursprungligen bars av Shadowhide-gnoller i Redridge Mountains för att ta emot order från deras herre, Morganth. Just det här hänget har förändrats av en avlyssnad sändningsbesvärjelse från High Mage Theocritus.",al={"shadowhide pendant","vad är det här hänget","theocritus hänge"}},{q="Varför hörs en röst från hänget?",a="High Mage Theocritus ägnade flera månader åt att undersöka hur han magiskt kunde tränga igenom hängenas kommunikationslänk. Rösten du hör är ett eko av en besvärjelse han sände ut flera veckor tidigare och bevisar att hans besvärjelse lyckades ta sig in i gnollernas nätverk.",al={"vem talar","kroppslös röst","theocritus röst"}},{q="Vem är Theocritus?",a="Theocritus är High Mage och bor i Tower Azora i östra Elwynn Forest. Han ägnar sina magiska studier åt att hålla uppsikt över mörka hot på andra sidan gränsen i Redridge, särskilt den avfällige trollkarlen Morganth.",al={"theocritus bakgrund","high mage theocritus","magikern i tower azora"}},{q="Vem är Morganth?",a="Morganth är en avfällig, ondskefull magiutövare som verkar från Redridge. Han utövar ett mörkt inflytande över det lokala Shadowhide-gnollpacket och ger dem order genom dessa förtrollade hängen.",al={"morganths identitet","vem är morganth","gnollernas herre"}},{q="Vad tänker Theocritus göra med hänget?",a="Theocritus tänker studera hänges förtrollning i sitt laboratorium. Hans slutmål är att hitta ett sätt att skicka förlamande magiska attacker genom nätverket och ögonblickligen oskadliggöra alla gnoller som bär ett sådant hänge.",al={"varför vill theocritus ha det","hänges syfte","göra hängen till vapen"}}},fx={["6c0e263d"]={q="Var kommer Faded Shadowhide Pendant ifrån, och vem tillverkade det?",a="Halsbandet kommer från Shadowhide-kobolderna i Redridge och deras mörke mästare, trollkarlen Morganth, som också är en tjuv. Morganth tillverkade eller förtrollade dessa småsaker som mystiska kanaler för att förmedla hans order direkt till koboldflockarna under hans kontroll.",al={"vem tillverkade faded shadowhide pendant","varifrån kommer shadowhide pendant","faded shadowhide pendants ursprung"}}},fp="24,203,16.415.0,19.343.1,37.184.0,40.215.0,18.163.0,16.120.0,49.182.0"}
P.entries["item:fallen-moonstone"] = {n="Fallen Moonstone",s="En Fallen Moonstone är en lysande, magiskt laddad sten som samlas upp ur Fallen Sky Lakes stilla vatten i Ashenvale. Stenarna är fyllda med helig månenergi och har kraftfulla läkande egenskaper som kan återställa livskraft och bota svår svaghet.",h="En Fallen Moonstone är en lysande, magiskt laddad sten som samlas upp ur Fallen Sky Lakes stilla vatten i...",kw={"ashenvale","astranaar","fallen moonstone","fallen sky lake","moonstone","pelturas whitemoon","relara","shadethicket oracle"},ang={["class:Priest"]="De som tillhör The Sisterhood of Elune känner igen stenarnas månljus som ett påtagligt uttryck för läkande nåd.",["race:NightElf"]="För Kaldorei är reliker knutna till Elunes strålglans heliga redskap för att bevara liv. De skänker gudomlig läkedom när dödlig medicin sviker."},sec={{t="Gåvor från natthimlen",b="Förr samlades Fallen Moonstones i stora mängder längs stränderna och i de grunda vattnen i Fallen Sky Lake, sydöst om Astranaar. Nattalverna värdesatte dem högt för deras läkande magi och månens välsignelse, och sökte ofta upp dem när vanliga botemedel inte räckte till. Men det blev förrädiskt att samla dem när korrupta Shadethicket-träskbestar invaderade sjön. Deras ledare, en Shadethicket Oracle, samlade på alla stenar den kunde hitta på en liten ö mitt i sjön och stängde därmed ute de lokala Kaldorei från en livsviktig källa till läkedom."},{t="En fars räddning",b="När unga Relara Whitemoon blev svårt sjuk i Astranaar fick vanliga behandlingar ned hennes feber, men hon förblev blek och klamrade sig fast vid livet med bara några andetag kvar. Hennes far, Pelturas Whitemoon, insåg att endast en månsten med koncentrerad läkande kraft kunde återställa hennes uttömda livskraft. En sten ur Shadethicket Oracles samling gav gnistan som behövdes för att rädda barnets liv."}},faq={{q="Vad är en Fallen Moonstone?",a="Det är en sällsynt, glödande sten som finns vid Fallen Sky Lake i Ashenvale. Den är mättad med månens magi och har en kraftfull läkande energi som nattalverna använder för att återställa styrkan hos svårt försvagade personer.",al={"vad är fallen moonstone","fallen moonstone i historien","moonstone i ashenvale"}},{q="Var finns Fallen Moonstones?",a="De kommer från Fallen Sky Lake, sydöst om Astranaar i Ashenvale. Förr låg de utspridda över sjöbottnen, men de fientliga Shadethicket-träskbestarna samlade dem och lade dem i en hög på en ö mitt i sjön.",al={"var hittar man fallen moonstone","fallen moonstone plats"}},{q="Vem har månstenarna vid Fallen Sky Lake?",a="Shadethicket Oracle, ledaren för de korrupta träskbestarna som håller till vid Fallen Sky Lake, samlade Fallen Moonstones på en ö mitt i sjön.",al={"vem har fallen moonstone","shadethicket oracle och moonstone"}},{q="Varför behöver Pelturas Whitemoon en Fallen Moonstone?",a="Hans unga dotter, Relara, överlevde en försvagande feber men var sedan kritiskt svag och blev allt sämre. Pelturas förstod att naturlig vila inte skulle räcka för att hålla henne vid liv. Månstenens medfödda magi behövdes för att återställa hennes livskraft.",al={"pelturas whitemoons dotter","varför behövs moonstone","relara botemedel"}}},fp="16,227,22.445.0,20.390.1,27.210.0,34.208.0,48.149.0,52.211.0"}
P.entries["item:fandral-s-message"] = {n="Fandral's Message",s="Fandral's Message är ett brev skrivet av Arch Druid Fandral Staghelm i Darnassus. En äventyrare får i uppdrag att föra det över havet till Onu, en Ancient of Lore i Darkshore.",h="Fandral's Message är ett brev skrivet av Arch Druid Fandral Staghelm i Darnassus.",kw={"ancient of lore","auberdine","darkshore","darnassus","fandral staghelm","fandral's message","grove of the ancients","onu","the oracle glade"},ang={["class:Druid"]="Att bära meddelanden mellan Cenarion Enclave i Darnassus och Ancients of Lore i Darkshore visar på de skilda filosofierna hos Fandral Staghelms offensiva drivkraft och de äldre druidiska väktarnas tålmodiga traditionalism.",["race:NightElf"]="Att leverera meddelandet är ett av de första stegen bort från Teldrassils krona och ner mot Kalimdors fastlands urgamla skogar."},sec={{t="Ett meddelande från ärkedruiden",b="Detta förseglade meddelande skrevs av Arch Druid Fandral Staghelm i Cenarion Enclave och är en direkt kontakt mellan nattalvernas tillförordnade druidledare och Onu, den vördnadsvärda Ancient of Lore som bor i Grove of the Ancients. Efter att ha fått rapporter om tillståndet i Teldrassil's Oracle Glade slösar Staghelm ingen tid på att skicka bud söder om Auberdine. Resenärer måste ta sig över vattnet till Darkshore och på så vis förbinda hjärtat av det nya världsträdet med det äldre, skuggiga fastlandet."},{t="Olika tempo",b="Även om innehållet i meddelandet förblir en sak mellan Arch Druid och Onu, visar själva leveransen på en subtil skillnad i temperament inom Cenarion Circle. När Onu tar emot dokumentet påpekar han att Fandral ständigt verkar ovanligt otålig och skyndar på sådant som de gamla anser bör utvecklas naturligt. För Darkshores långlivade treanter står Fandral's skyndsamhet i skarp kontrast till det tålamod och den visdom som Archdruid Malfurion Stormrage en gång förkroppsligade."}},faq={{q="Vad är Fandral's Message?",a="Det är ett officiellt skriftligt meddelande från Arch Druid Fandral Staghelm till Onu, en Ancient of Lore som bor i Grove of the Ancients i Darkshore.",al={"föremålet fandral's message","fandral's message","ärkedruidens brev"}},{q="Vem skickar meddelandet och varför?",a="Arch Druid Fandral Staghelm skriver det i Darnassus. Efter att ha fått uppdateringar om Oracle Glade i Teldrassil skickar han bud till Onu, som har väntat på nyheter från världsträdets krona.",al={"vem skrev detta","varför skickar fandral ett meddelande"}},{q="Vart ska meddelandet?",a="Meddelandet ska lämnas till Onu i Grove of the Ancients, som ligger i Darkshore, rakt söder om kustbosättningen Auberdine.",al={"vem får meddelandet","vart ska meddelandet lämnas","fandral's messages destination"}},{q="Vad tycker Onu om brevet?",a="När Onu tar emot det påpekar han att Fandral alltid verkar ha bråttom. Den gamle konstaterar att naturen rör sig i sin egen takt och funderar över att Shan'do Malfurion Stormrage förstod den sanningen mycket bättre än Fandral.",al={"onus reaktion","vad säger onu"}}},fx={["22d06606"]={q="Varför vill Onu ha Fandral's Message?",a="Onu, en uråldring av lärdom som vilar i Grove of the Ancients i Darkshore, har väntat på besked från ärkedruiden Fandral Staghelm om hur det står till med Teldrassil. Efter att ha fått nyheter från The Oracle Glade skickade Fandral dig genast över havet med detta meddelande. Onu tar tålmodigt emot brevet, men tänker stilla att den rastlöse ärkedruiden alltid verkar ha alldeles för bråttom jämfört med det tålamod och den visdom som Shan'do Stormrage en gång visade.",al={"varför vill onu ha meddelandet","varför behöver onu fandrals brev","varför leverera fandrals meddelande"}}},fp="17,149,29.456.0,18.286.1,26.144.0,31.142.0,35.96.0,34.149.0"}
P.entries["item:fang-of-vagash"] = {n="Fang of Vagash",s="Fang of Vagash är en väldig rovtand från det beryktade odjuret Vagash i Dun Moroghs snöiga berg. Den är ett konkret bevis för traktens uppfödare på att monstret som hotade deras värdefulla baggar äntligen har dödats.",h="Fang of Vagash är en väldig rovtand från det beryktade odjuret Vagash i Dun Moroghs snöiga berg.",kw={"amberstill ranch","dun morogh","fang of vagash","ironforge","skydda hjorden","bagge","vagash"},ang={["class:Hunter"]="Att spåra upp ett topprovdjur som Vagash i Dun Moroghs isande berg är ett tidigt prov på spårning, överlevnad i vildmarken och skicklighet i att fälla odjur.",["race:Dwarf"]="Amberstill Ranch föder upp de härdiga bergsbockarna som är oumbärliga för dvärgarnas bergsklättrare och resenärer. När du tar tillbaka Vagashs huggtand skyddar du direkt Ironforges mest värdefulla riddjur."},sec={{t="Jaktens trofé",b="Dun Moroghs höga berg är hem åt bitande kyla och vildsinta rovdjur, men inget har plågat traktens gårdar som Vagash. Det här vildsinta odjuret lurar på höjderna ovanför Amberstill Ranch och smyger ofta nerför sluttningarna i skydd av mörkret för att slakta värdefulla baggar. Ironforges trupper har redan fullt upp, så de lokala fåraherdarna kan inte räkna med stadsvakten som skydd. Att döda odjuret och skära loss en av dess vassa huggtänder är ett obestridligt bevis på att betesmarkerna åter är trygga."}},faq={{q="Vad används Fang of Vagash till?",a="Huggtanden lämnas till uppfödarna på Amberstill Ranch i Dun Morogh som ett fysiskt bevis på att Vagash har dödats. Som tack belönar de tacksamma ranchägarna jägaren som skyddat deras levebröd.",al={"vad används fang of vagash till","vad gör man med fang of vagash","lämna in vagashs huggtand"}},{q="Vem är Vagash?",a="Vagash är ett ovanligt dödligt odjur som håller till i de snöiga kullarna strax ovanför baggarnas betesmarker i Dun Morogh. Bland traktens dvärgar har han ett fruktat rykte för att plundra hjordarna om natten.",al={"vad är vagash","var finns vagash","vagashs historia"}},{q="Varför har Ironforges vakter inte dödat Vagash?",a="Ironforges trupper är redan utspridda. Eftersom få soldater kan avvaras för patrullering på landsbygden måste ranchägarna förlita sig på förbipasserande äventyrare för att ta hand om farliga rovdjur.",al={"varför hjälper inte vakterna","var är ironforges armé","bergsklättrare vagash"}}},fx={fc16a334={q="Vad är Fang of Vagash?",a="Fang of Vagash är en enorm trofé från munnen på Vagash, ett våldsamt rovdjur som stryker omkring på åsarna i Dun Morogh. Den är ett obestridligt bevis på att det hotfulla odjuret äntligen har jagats ner och dödats.",al={"vad är fang of vagash","vagashs huggtand i historien","fang of vagash"}},["695a78ed"]={q="Var kommer Fang of Vagash ifrån?",a="Den här huggtanden är inte tillverkad, utan en naturlig tand som bändes loss ur Vagashs käftar. Det vildsinta monstret har sitt näste i de snöiga kullarna strax ovanför Amberstill Ranch.",al={"var får man fang of vagash","vem gjorde fang of vagash","ursprunget till vagashs huggtand"}},f04ec442={q="Varför vill Rudra Amberstill ha Fang of Vagash?",a="Rudra Amberstill vill ha huggtanden som ett konkret bevis på att rovdjuret är dött. Vagash har gjort räder mot ranchen om natten och slukat dyrbara baggar. Det hotar familjen Amberstills försörjning, samtidigt som Ironforges vakter är för få för att försvara dem.",al={"varför vill någon ha fang of vagash","vem vill ha vagashs huggtand","rudra amberstill och huggtanden"}}},fp="14,156,18.459.0,36.183.0,14.181.0,45.171.0"}
P.entries["item:fangore-s-paw"] = {n="Fangore's Paw",s="Fangore's Paw är den avhuggna handen från Lieutenant Fangore, en befälhavare bland Shadowhide-gnollerna i Redridge Mountains. Den tjänar som ett makabert bevis på gnollhövdingens död för Magistrate Solomon i Lakeshire. Den dystra belöningen utlystes för att undanröja krigsherrens hot mot den belägrade staden.",h="Fangore's Paw är den avhuggna handen från Lieutenant Fangore, en befälhavare bland Shadowhide-gnollerna i...",kw={"fangore","gnoll","lakeshire","morganth","tass","redridge","shadowhide","solomon"},ang={["faction:Alliance"]="Att fälla Fangore och återlämna hans tass ger den hårt ansatta staden Lakeshire en välbehövlig lättnad. Staden får knapphändigt militärt stöd från Stormwind."},sec={{t="Trofé från en fallen hövding",b="Lieutenant Fangore är en av de främsta fältbefälhavarna för Shadowhide-gnollerna, som tränger fram genom Redridge Mountains. Fangore tjänar Morganth, den avfällige magikern, och leder våldsamma anfall mot handelsvägar, avlägsna gårdar och försvarsverken kring Lake Everstill. Eftersom gnollplundrare inte bär traditionella uniformer, officiella sigill eller fanor som kan bekräfta deras dödsfall, förlitar sig stadens myndigheter på makabra fysiska bevis. Magistrate Solomon krävde uttryckligen Fangore's Paw som otvetydigt bevis på att han avrättats, så att Lakeshires invånare skulle kunna andas ut en aning mitt bland de växande hoten runt omkring."}},faq={{q="Vem tillhör den här tassen?",a="Tassen tillhör Lieutenant Fangore, en ökänd ledare inom Shadowhide-gnollklanen som härjar i Redridge Mountains. Han organiserar räder och leder styrkor på den mörke trollkarlen Morganths uppdrag.",al={"vem är fangore","vems tass är det här","fangores identitet"}},{q="Varför vill Magistrate Solomon ha tassen?",a="Magistrate Solomon utfärdade en officiell efterlysning där Fangore fördöms som en avskyvärd fiende till Stormwind. Han kräver den avhuggna tassen som obestridligt fysiskt bevis på att Shadowhide-löjtnanten har dödats.",al={"varför samla in fangores tass","solomons bevis för belöningen","magistratens bevis"}},{q="Vem arbetar Lieutenant Fangore för?",a="Fangore tjänar Morganth, en avfälling som utövar mörk magi och hotar Lakeshire från sitt torn i de östra bergen. Morganth styr gnollernas verksamhet mot kungariket.",al={"fangores herre","vem leder fangore","kopplingen till morganth"}},{q="Var hittar man Lieutenant Fangore?",a="Lieutenant Fangore håller till i vildmarken i Redridge Mountains, bland de fientliga lägren som tillhör Shadowhide-gnollerna.",al={"fangores plats","var finns fangore","hitta fangore"}}},fx={["62ed4317"]={q="Var kommer Fangore's Paw ifrån?",a="Tassen tas direkt från liket efter Lieutenant Fangore, en ökänd ledare för de Shadowhide-gnoller som lever i Redridge Mountains. Den är ingen tillverkad relik eller ett vapen, utan en avskuren trofé som tagits i strid för att bekräfta att den farlige gnollbefälhavaren har oskadliggjorts.",al={"fangore's paw ursprung","varifrån kommer fangore's paw","vem gjorde fangore's paw"}}},fp="13,221,28.526.0,28.197.0,41.197.0,38.171.0,34.119.0"}
P.entries["item:farren-s-report"] = {n="Farren's Report",s="Farren's Report är en officiell rapport skriven av Lieutenant Farren Orinelle i Southshore, där han redogör för sina undersökningar av de lokala naga. Med dokumentet vädjar Farren till sin tidigare mentor, Major Samuelson i Stormwind Keep, i hopp om att få återvända till huvudstaden.",h="Farren's Report är en officiell rapport skriven av Lieutenant Farren Orinelle i Southshore, där han redogör...",kw={"farren orinelle","farren's report","major samuelson","naga","förflyttning","redpath","southshore","stormwind keep"},ang={["faction:Alliance"]="Dokumentet belyser det byråkratiska spelet inom Alliansens militär, där avlägsna poster i Hillsbrad krockar med officerare som smider planer för tryggare tjänstgöring i Stormwind.",["race:Human"]="För Alliansens människor visar det att bära på Farrens rapport den bestående länken mellan Southshore, den belägrade tillflyktsorten i söder, och det kungliga hovet i Stormwind Keep."},sec={{t="En väg bort från Southshore",b="Stationerad vid den krigshärjade kusten i Hillsbrad Foothills tröttnade Lieutenant Farren Orinelle på det lokala ledarskapet och den avlägsna gränstrakten. Efter att ha gett äventyrare i uppdrag att jaga Daggerspine-naga för att samla bevis på hotet sammanställde Orinelle sina resultat i en formell rapport. I stället för att lämna in den till sin befälhavare, Marshal Redpath, tänkte Farren skicka den direkt till Major Samuelson, kapten för vakten i Stormwind Keep. Farren hade utbildats under Samuelson och hoppades att dokumentet skulle visa hans duglighet och motivera en omedelbar förflyttning tillbaka till Stormwind Citys bekvämligheter."}},faq={{q="Vad är Farren's Report?",a="Det är en formell militär rapport skriven av Lieutenant Farren Orinelle, som sammanfattar hans insatser mot Daggerspine-naga som tränger in på Southshores stränder.",al={"farrens rapport","vad är den här rapporten","orinelles rapport"}},{q="Varför vill Farren få rapporten levererad till Stormwind?",a="Farren vill bli förflyttad bort från Southshore och tillbaka till Stormwind City. Han adresserar rapporten direkt till Major Samuelson, sin tidigare mentor och kapten för Stormwinds vakt, i hopp om att få en fördelaktig förflyttning.",al={"varför skicka rapporten till stormwind","farrens mål","varför samuelson"}},{q="Varför håller Farren rapporten hemlig för Redpath?",a="Farren vill undvika granskning från Marshal Redpath och det lokala ledarskapet, som kanske skulle ta illa upp över att en officer utnyttjar ett lokalt hot enbart för att ordna en personlig förflyttning tillbaka till tryggheten i huvudstaden.",al={"varför dölja för redpath","redpaths hemlighet"}},{q="Hur reagerar Major Samuelson när han får rapporten?",a="Major Samuelson berömmer sin tidigare elev för att ha tagit initiativ mot nagan i Southshore och lovar att ta rapporten i beaktande när han går igenom vaktens placeringar under den kommande månaden.",al={"samuelsons reaktion","lämna in för förflyttning"}}},fx={["97a8ff6b"]={q="Var kommer Farren's Report ifrån, och vem skrev den?",a="Dokumentet skrevs i Southshore av Lieutenant Farren Orinelle själv. Farren är stationerad vid Hillsbrad Foothills farliga gränstrakter och sammanställde rapporten om sina insatser mot traktens murlocer och naga för att få högsta befälets uppmärksamhet i huvudstaden.",al={"vem skrev farren's report","farren's report ursprung","vem gjorde farren's report"}}},fp="15,153,26.533.0,24.162.0,49.189.0,55.194.0,49.182.1"}
P.entries["item:fathom-core"] = {n="Fathom Core",s="Fathom Core är en specialiserad relik som återfunnits i en nedsänkt fathom stone djupt inne i Blackfathom Deeps. När den dechiffreras ger den en fullständig redogörelse för elementens aktivitet i området. The Earthen Ring söker efter artefakten för att ta reda på vilka mörka ritualer Twilight's Hammer-kulten utför under Ashenvale.",h="Fathom Core är en specialiserad relik som återfunnits i en nedsänkt fathom stone djupt inne i Blackfathom...",kw={"blackfathom deeps","earthen ring","fathom core","fathom stone","je'neu sancrea","moonshrine ruins","twilight's hammer","zoram'gar outpost"},ang={["class:Shaman"]="Som en artefakt som skildrar elementens strömmar är Fathom Core av stort intresse för Earthen Ring. Den visar hur uråldriga reliker kan avslöja elementmanipulation.",["faction:Horde"]="Att återfinna kärnan hjälper Je'neu Sancrea direkt och säkrar Hordens fotfäste vid Zoram'gar Outpost mot Twilight's Hammers korrumperande planer."},sec={{t="Elementens krönika",b="Fathom Core ligger i en uråldrig fathom stone under vattnet bland Moonshrine Ruins och fungerar som en historisk redogörelse för elementfenomen. Den registrerar och bevarar förändringar, störningar och kraftiga skiftningar i elementen över tid. För Earthen Ring-schamanen som är stationerad vid Zoram'gar Outpost är det viktigt att få tag på kärnan för att förstå hur Twilight's Hammer-kultisterna manipulerar elementen i området för sina egna syften."}},faq={{q="Vad är Fathom Core?",a="Fathom Core är en magisk anordning som kan registrera och återge en detaljerad historik över all elementaktivitet i närheten. Den finns inuti en uråldrig fathom stone i Moonshrine Ruins.",al={"vad gör fathom core","fathom core bakgrund","vad är det"}},{q="Var finns Fathom Core?",a="Kärnan finns djupt inne i de grottliknande salarna i Blackfathom Deeps vid Ashenvales kust. Den ligger innesluten i en fathom stone under vattnet vid Moonshrine Ruins.",al={"fathom core plats","var hittar man fathom core","fathom stone plats"}},{q="Vem vill ha Fathom Core och varför?",a="Je'neu Sancrea, en Earthen Ring-schaman stationerad vid Zoram'gar Outpost, söker efter kärnan. Genom att analysera dess redogörelse för elementens skiftningar hoppas Je'neu och hans krets kunna dechiffrera och motverka Twilight's Hammer-kultens omstörtande verksamhet i ruinerna.",al={"vem behöver fathom core","varför vill je'neu ha fathom core","earthen ring fathom core"}},{q="Varför är Twilight's Hammer intresserade av Blackfathom Deeps?",a="Kultisterna har bosatt sig i de nedsänkta ruinerna för att tvinga och korrumpera de lokala elementen. De försöker få dem att tjäna mörka syften och ta total kontroll över det underjordiska templet.",al={"twilight's hammer blackfathom","kultister i bfd"}}},fp="11,187,19.330.0,24.137.0,33.149.0,34.224.0,61.213.0"}
P.entries["item:feather-charm"] = {n="Feather Charm",s="Feather Charm är enkla magiska föremål som bärs av unga Frostmane-troll i Coldridge Valleys snötäckta dalar. Trots sina enkla material har de en medfödd magisk resonans som fångar lokala häxmästares uppmärksamhet.",h="Feather Charm är enkla magiska föremål som bärs av unga Frostmane-troll i Coldridge Valleys snötäckta dalar.",kw={"alamar grimm","anvilmar","coldridge valley","dun morogh","feather charm","ung frostmane","häxmästare"},ang={["class:Warlock"]="För blivande häxmästare i Dun Morogh är det ett viktigt disciplinprov att ta fjäderamuletter från trollmagiker innan Alamar Grimm anförtros dem ritualen för att frammana en imp.",["race:Gnome"]="Gnomiska häxmästare som verkar från Anvilmar studerar dessa enkla trollfetischer för att undersöka den råa, oförädlade magi som kanaliseras av primitiva Frostmane-magiker."},sec={{t="Trollamuletter och mörka studier",b="Frostmane-trollen som bor i de snöiga grottorna sydväst om Anvilmar är mest kända för sin territoriella vildhet, men deras unga ägnar sig åt enkel magi. Fjäderamuletterna som dessa unga troll bär har en svag men omisskännlig magisk kraft. I Anvilmar tycker häxmästerinstruktören Alamar Grimm att de är ett fascinerande studieobjekt, överraskande nog för grov trollmagi, och använder dem som ett prov för blivande häxmästare som vill lära sig att binda sin första imp."}},faq={{q="Vem bär dessa fjäderamuletter?",a="De bärs av unga Frostmane-troll som lurar i den snöiga grottan sydväst om Anvilmar i Coldridge Valley.",al={"var kommer feather charm ifrån","vem släpper feather charm","amulet från ung frostmane"}},{q="Varför vill Alamar Grimm ha dem?",a="Alamar Grimm finner amuletternas inneboende magi fascinerande och värd att forska om, något han menar är ganska oväntat för trollhantverk. Han kräver dem av blivande häxmästare för att pröva deras fysiska uthållighet och magiska förmåga innan han lär dem att frammana en imp.",al={"varför behöver alamar amuletterna","alamar grimm feather charms","vad gör grimm med dem"}},{q="Är Frostmane-trollen skickliga magianvändare?",a="Frostmane-stammen ses till största delen som rå och fientlig, men deras unga visar prov på grundläggande trollformler. Fjäderamuletterna de bär fokuserar denna enkla magi och visar att även deras oerfarna magiker använder arkana eller schamanistiska krafter.",al={"kan frostmane-troll använda magi","ung frostmane-magi"}},{q="Hur ser amuletterna ut?",a="De är enkla talismaner flätade av fjädrar och snöre, tillverkade av unga Frostmane-troll som fokus för sin tidiga magiträning i Dun Moroghs kalla grottor.",al={"beskrivning av feather charm","feather charms utseende"}}},fx={a2188847={q="Vad är en Feather Charm?",a="En Feather Charm är en enkel magisk talisman som tillverkas och bärs av Frostmane-trollens noviser i Dun Morogh. De verkar vara enkla prydnader gjorda av de primitiva bergstrollen, men charmerna kanaliserar en särskild magisk energi som väcker intresse hos forskare och besvärjare som studerar trollens mystik.",al={"vad är feather charm","feather charms historia","om feather charm"}},["6facee45"]={q="Var kommer Feather Charms ifrån, och vem tillverkar dem?",a="Charmerna tillverkas av de unga magikerna i Frostmane-stammen, som bor i de iskalla grottorna sydväst om Anvilmar. De unga trollnoviserna fyller fjädrarna med sina egna krafter, som just har börjat vakna, och bär dem som fokuspunkter medan de övar sin enkla magi i Coldridge Valley.",al={"vem tillverkar feather charms","var kommer feather charms ifrån","frostmane feather charms ursprung"}}},fp="13,138,31.446.0,33.96.0,32.213.0,43.232.0,29.152.0"}
P.entries["item:fel-cone"] = {n="Fel Cone",s="Fel Cone är fördärvade frökottar som faller från Teldrassils grenar. De syns lätt på de giftiga gröna ångorna som sipprar ur skalen. Trots att de är motbjudande och genomsyrade av mörka krafter hittar de lokala Night Elf-försvararna på fiffiga sätt att använda dem mot närgångna lurendrejare.",h="Fel Cone är fördärvade frökottar som faller från Teldrassils grenar.",kw={"dolanaar","fel cone","satyr","sona sina handlingar","syral bladeleaf","teldrassil","zenn foulhoof"},ang={["class:Druid"]="Att se hur skogens friska frökottar förvandlas till rykande rester av kaosmagi påminner druiderna om den bräckliga balans som de kämpar för att bevara i hela Teldrassil.",["race:NightElf"]="Att Fel Cones finns är ett oroande tecken på sjukdom djupt inne i Teldrassils rötter. Det visar att inte ens Världsträdets späda skott är skyddade från demonisk korruption."},sec={{t="Fördärv i trädkronan",b="Teldrassil är ungt, men fördärvet har redan trängt in i dess levande ved. Fel Cone är tydliga tecken på denna lömska röta: knotiga, nedfallna kottar som bolmar av motbjudande grön rök. De ligger utspridda under grenarna strax öster om Dolanaar. Kottarna är genomsyrade av besudlad magi som förvrider den naturliga floran och gör dem farliga att röra vid eller äta utan försiktighet."},{t="Besk medicin",b="När oförsiktiga resenärer faller för Zenn Foulhoofs knep, kräver de lokala väktarna botgöring. Han är en lurpassande satyr som lurar förbipasserande att göra som han vill. Syral Bladeleaf och Sentinels skickar ångerfulla äventyrare att samla in dessa giftiga kottar och lämna dem till Foulhoof, som om de vore ett oskyldigt mellanmål. Den koncentrerade korruptionen i fröet utlöser en märklig förvandling och gör den vidriga satyren tillfälligt till en ofarlig groda."}},faq={{q="Vad är en Fel Cone?",a="En Fel Cone är en fördärvad kotte som faller från Teldrassils grenar. Den är besudlad av onaturlig magi, pyr med en kuslig grön rök och innehåller instabila, förvandlande krafter.",al={"vad är fel cones","fel cone-historia","vad är fel cone"}},{q="Var hittar man Fel Cones?",a="De ligger på skogsmarken under träden strax öster om Dolanaar, i hjärtat av Teldrassil.",al={"var finns fel cones","fel cone-plats","hur hittar man fel cones"}},{q="Varför vill Council of the Forest att de samlas in?",a="Om du ovetande hjälpte satyren Zenn Foulhoof att skada naturens varelser ger Council of the Forest dig en chans att sona dina handlingar. De ber dig samla Fel Cones och lura Zenn att äta dem som en läxa.",al={"samla kottar för att sona","varför samla fel cones","vem vill ha fel cones"}},{q="Vad händer när någon äter en Fel Cone?",a="Council of the Forest tänker använda kottarna för att lära Zenn Foulhoof en läxa. Han väntas tro att de är ett ofarligt mellanmål. Den exakta effekten avslöjas när planen sätts i verket.",al={"vad gör fel cone","äta fel cone","zenn foulhoof groda"}}},fx={["5dfa7f39"]={q="Var kommer Fel Cones ifrån, och vem tillverkade dem?",a="Fel Cones tillverkas inte av dödliga händer. De är fördärvade frökottar som faller naturligt från grenarna på Teldrassils träd. En otäck, böljande grön rök stiger från dem och visar att den mörka korrumpering som plågar det stora världsträdet har trängt djupt in i själva fröna och jorden.",al={"var kommer fel cones ifrån","vem gjorde fel cones","fel cone ursprung"}}},fp="8,139,20.297.0,17.295.1,19.173.0,29.89.0,55.211.1,42.126.1"}
P.entries["item:fel-moss"] = {n="Fel Moss",s="Fel Moss är ett besmittat växtämne som sprider sig genom Teldrassils skogar. Det bär på demoniska och fördärvande krafter och förs vidare av fientliga grell och grellkin. Det utgör ett lömskt hot mot vilda djur och World Trees inhemska furbolgstammar.",h="Fel Moss är ett besmittat växtämne som sprider sig genom Teldrassils skogar.",kw={"fel moss","gnarlpine","grell","grellkin","shadowglen","tarindrella","teldrassil","ursal the mauler"},ang={["class:Druid"]="För druiderna i Cenarion Circle är Fel Moss en alarmerande cancersvulst som sprider sig genom Teldrassil och visar att det nyfödda World Tree är djupt sårbart för demonisk farsot.",["race:NightElf"]="Nattalverna vördar Teldrassil som sitt nya hemland. Därför är förekomsten av Fel Moss ett oroande omen om att freden fortfarande är utom räckhåll, även bland deras heliga grenar."},sec={{t="En farsot på World Tree",b="Teldrassil planterades för att återge nattalverna deras odödlighet och läka naturen, men fördärvet har redan smugit sig in bland dess orörda grenar. Fel Moss är ett av de tydligaste tecknen på denna förstörelse. Den klänger sig fast vid och sprids av de smådjävulska grell och grellkin som hemsöker Shadowglen. Denna ondskefulla växt avger en onaturlig och illvillig magi. Skogens beskyddare, som dryaden Tarindrella, har börjat samla in prover för att se hur djupt rötan har trängt in i den heliga skogskronan."},{t="Galenhetens frön",b="Faran med Fel Moss sträcker sig längre än till skogens förfall; den påverkar också levande varelsers sinnen med våldsam kraft. Furbolger som en gång levde i fred på Teldrassils höjder har fallit offer för dess beröring. De har övergett sina traditionella boplatser och slutit sig samman i den fientliga Gnarlpine-stammen. Dessa drabbade varelser har drivits till vansinne av mossans onda krafter under ledare som Ursal the Mauler. De visar hur sjukdomen växer sig stark i det stora trädet."}},faq={{q="Vad är Fel Moss?",a="Fel Moss är en vidrig, magiskt fördärvad växtmassa som finns på Teldrassil. Den är genomsyrad av hemska krafter, klänger sig fast vid pestsmittade varelser och sprider vansinne och fysisk förvridning i det omgivande ekosystemet.",al={"fel moss i berättelsen","vad är fel moss","vad gör fel moss"}},{q="Var kommer Fel Moss ifrån?",a="På Teldrassil hittar äventyrare klumpar av Fel Moss på de förvridna grell och grellkin som strövar omkring på kullarna nära Shadowglen. Den kommer från vidriga fördärvande krafter som har slagit rot i själva World Tree.",al={"var hittar man fel moss","fel moss byte","fel moss ursprung"}},{q="Hur påverkar Fel Moss furbolgerna?",a="Fel Moss fungerar som en katalysator för fördärv. När furbolger utsätts för dess onda krafter drivs de in i våldsamt vansinne. De en gång fredliga stammarna på Teldrassil förvandlas då till den aggressiva och främlingsfientliga Gnarlpine-stammen.",al={"furbolger fördärv","varför är gnarlpine galna","gnarlpine fel moss"}},{q="Vem försöker stoppa spridningen av Fel Moss?",a="Dryaden Tarindrella i Shadowglen ber unga försvarare samla prover av Fel Moss från grellkin för att bekräfta sina misstankar om fördärv i skogen. Hon hänvisar bekymrade beskyddare vidare till druider som Athridas Bearmantle i Dolanaar.",al={"vem studerar fel moss","vem vill ha fel moss","tarindrella uppdrag"}}},fx={["464589e1"]={q="Varför vill Tarindrella ha Fel Moss?",a="Tarindrella vill ha prover av Fel Moss för att ta reda på om de aggressiva grellerna och grellkin som hemsöker Shadowglen verkar under dess onda förtrollning. Genom att säkra denna förgiftade växtlighet hoppas hon kunna bedöma hur långt korrumperingen har spridit sig och förstå hotet mot de närbelägna Gnarlpine-furbolgerna.",al={"varför samla fel moss","tarindrella och fel moss","varför vill de ha fel moss"}}},fp="8,196,24.439.0,16.329.1,17.171.0,30.173.0,38.213.0,45.248.0"}
P.entries["item:felix-s-box"] = {n="Felix's Box",s="Felix's Box är en liten behållare med personliga tillhörigheter som tillhör Felix Whindlebolt, en flykting som flydde från Gnomeregans fall. Lådan försvann under den panikartade evakueringen till Dun Morogh, plundrades av lokala Frostmane-troll och fördes till deras läger sydväst om Anvilmar.",h="Felix's Box är en liten behållare med personliga tillhörigheter som tillhör Felix Whindlebolt, en flykting...",kw={"anvilmar","coldridge valley","dun morogh","felix whindlebolt","felix's box","frostmane","gnomeregan","flykting"},ang={["profession:Engineering"]="De återfunna verktygen och behållarna utgör en livlina för en uppfinnare och visar hur svårt gnomiska hantverkare har det när de tvingas lämna sin utrustning bakom sig.",["race:Gnome"]="För gnomiska äventyrare som börjar i Coldridge Valley innebär återfinnandet av Felix personliga ägodelar konkret hjälp åt en medflykting som lider av de bittra följderna av Gnomeregans evakuering."},sec={{t="Förlorad under flykten från Gnomeregan",b="När strålningen sköljde genom Gnomeregan under det misslyckade försöket att utrota hotet från troggarna, anslöt sig Felix Whindlebolt till gnomernas panikartade flykt till Coldridge Valley. I sin desperation att undkomma de radioaktiva ångorna tappade Felix sina mest värdefulla personliga ägodelar och sitt hantverksutrustning längs den snöiga vägen. Innan han hann hämta dem plundrade ursprungsbefolkningens Frostmane-troll resterna vid vägen och släpade hans låda, tillsammans med hans kista och hink med bultar, tillbaka till sina primitiva bosättningar sydväst om Anvilmar."},{t="En flyktings dilemma",b="Felix var ovan vid fysiskt våld och illa rustad för Dun Moroghs hårda vildmark, så han tvingades be förbipasserande äventyrare i Anvilmar om hjälp att återfå sina tillhörigheter. Att hämta Felix's Box innebär mer än att återlämna en enkel behållare; det ger en fördriven hantverkare, som förlorade allt i katastrofen som ödelade hans underjordiska hemland, en bit av sitt vanliga liv och sin försörjning tillbaka."}},faq={{q="Vad är Felix's Box?",a="Det är en behållare med Felix Whindlebolts personliga tillhörigheter. Han är en gnomhantverkare som flydde från Gnomeregan efter stadens katastrofala förorening.",al={"felix låda","vad är den här lådan","felix låda bakgrund"}},{q="Hur hamnade lådan hos Frostmane-trollen?",a="Felix övergav sin utrustning när han flydde från de bestrålade ångorna som vällde ut ur Gnomeregan. Frostmane-troll som patrullerade kullarna sydväst om Anvilmar letade igenom utrustningen vid vägen och släpade den till sitt läger.",al={"varför har trollen felix låda","vem stal felix låda","hur försvann den"}},{q="Vem är Felix Whindlebolt?",a="Felix Whindlebolt är en civil gnomflykting som för närvarande bor i Anvilmar. Han är traumatiserad av Gnomeregans fall och strandsatt utan sina livsviktiga verktyg och personliga ägodelar.",al={"felix whindlebolt","vem är felix"}},{q="Vilka andra saker förlorade Felix?",a="Förutom lådan plundrade Frostmane-trollen Felix's Chest och hans Bucket of Bolts och spred ut alla tre bland sina läger sydväst om Anvilmar.",al={"felix andra föremål","felix tillhörigheter","felix förlorade utrustning"}}},fx={["8f76c19d"]={q="Varför vill Felix Whindlebolt ha tillbaka sin låda?",a="Felix Whindlebolt är en gnom på flykt som tvingades lämna Gnomeregan i panik när strålning fyllde staden. I sin desperata flykt förlorade han sina verktyg och personliga ägodelar till Frostmane-trollen. Som vanlig hantverkare och flykting i Anvilmar saknar han stridsförmågan att själv våga sig in i trollens läger, men han behöver desperat få tillbaka sin stulna låda och sina tillhörigheter för att kunna bygga upp sitt liv igen.",al={"varför vill felix ha lådan","varför hitta felix's box","vad felix's box är till för"}}},fp="11,110,34.433.0,20.303.0,20.140.0,49.151.0,25.134.0,32.140.0"}
P.entries["item:felix-s-bucket-of-bolts"] = {n="Felix's Bucket of Bolts",s="Felix's Bucket of Bolts är en behållare med reservdelar och verktyg som tillhör Felix Whindlebolt, en gnomflykting som flydde när Gnomeregan föll. Under flykten genom Dun Morogh blev hinken stulen av lokala Frostmane-troll och släpad till deras närliggande läger.",h="Felix's Bucket of Bolts är en behållare med reservdelar och verktyg som tillhör Felix Whindlebolt, en...",kw={"anvilmar","bultar","dun morogh","felix","frostmane","gnomeregan","flykting","troll","whindlebolt"},ang={["profession:Engineering"]="Ingen finmekaniker kan arbeta utan grundläggande beslag, vilket gör en enkel hink med bultar till en dyrbar ägodel när man börjar om i Dun Moroghs snö.",["race:Gnome"]="Varje räddad hink med delar är en liten bit av Gnomeregan som räddats undan undergången och hjälper flyktingar att skapa ett nytt fäste i Coldridge Valley."},sec={{t="En flyktings utspridda verktyg",b="När strålning översvämmade Gnomeregan efter katastrofen med troggarna flydde tusentals gnomer ut i Dun Moroghs iskalla vildmark med allt de kunde bära. Felix Whindlebolt lyckades fly med sin viktiga utrustning, men i kaoset under flykten mot Anvilmar överfölls han av Frostmane-trollen som håller till i klipporna sydväst om staden. Trollfolket plundrade hans ägodelar, däribland den här hinken full av bultar och delar, och lämnade hantverkaren strandsatt utan det nödvändiga material han behövde för att utöva sitt hantverk i exil."}},faq={{q="Vad är Felix's Bucket of Bolts?",a="Det är en tung behållare fylld med metallbultar, beslag och tillbehör för finmekanik som tillhör Felix Whindlebolt, en landsförvisad gnom som söker skydd i Anvilmar.",al={"hink med bultar","felix hink","felix hink med bultar"}},{q="Vem stal hinken?",a="Frostmane-trollen stal hinken tillsammans med Felix andra personliga tillhörigheter när han flydde katastrofen i Gnomeregan.",al={"vem tog bultarna","troll stal hink","vem har felix bultar"}},{q="Vart tog trollen den?",a="Trollen bar tillbaka den till sina läger i klipporna sydväst om Anvilmar i Coldridge Valley.",al={"var är bultarna","hinkens plats","felix bultar läger"}},{q="Varför är hinken viktig för Felix?",a="Gnomflyktingarna flydde från sitt hem med nästan ingenting. För en ingenjör eller hantverkare som Felix är enkla fästdon och delar nödvändiga för att överleva och bygga upp sina liv på nytt långt från Gnomeregan.",al={"varför vill felix ha bultar","felix whindlebolt bultarnas betydelse"}}},fp="23,162,27.472.0,32.120.0,21.109.0,29.107.0,38.188.0"}
P.entries["item:felix-s-chest"] = {n="Felix's Chest",s="Felix's Chest är en behållare med personliga tillhörigheter som den landsförvisade gnomen Felix Whindlebolt tappade under flykten från Gnomeregan. Frostmane-troll som lurade nära Coldridge Valley förde bort den, och nu står den övergiven i ett av deras primitiva bergsläger.",h="Felix's Chest är en behållare med personliga tillhörigheter som den landsförvisade gnomen Felix Whindlebolt...",kw={"en flyktings dilemma","anvilmar","coldridge valley","felix whindlebolt","felix's chest","frostmane","gnomeregan"},ang={["race:Gnome"]="Kistan är en gripande påminnelse om Gnomeregans kaotiska evakuering, då flyende gnomer förlorade nästan allt till vildmarken och opportunistiska plundrare."},sec={{t="En flyktings förluster",b="När Gnomeregans underjordiska teknikstad föll för troggarnas intrång och giftigt radioaktivt nedfall flydde tusentals gnomer mot Dun Moroghs snöiga yta med allt de kunde bära. Felix Whindlebolt lyckades fly från de bestrålade ruinerna, men mitt i evakueringens panik plundrade de lokala Frostmane-trollen vägarna och hann ikapp de utspridda överlevarna. Felix förlorade sina viktigaste verktyg och tillhörigheter, och hans stadiga kista släpades bort till de grova läger som trollen håller i klippbranterna sydväst om Anvilmar."}},faq={{q="Vad finns i Felix's Chest?",a="Kistan innehåller de personliga tillhörigheter som Felix Whindlebolt lyckades rädda med sig när han flydde från Gnomeregan. Han lämnade dem bakom sig i brådskan att komma undan den dödliga strålningen. De är till liten nytta för trollen, men utgör de sista resterna av hans tidigare liv.",al={"innehållet i felix chest","vad finns i kistan","byte i felix's chest"}},{q="Varför har Frostmane-trollen Felix's tillhörigheter?",a="Frostmane-trollen trakasserar regelbundet resenärer och plundrar Coldridge Valley. När gnomiska flyktingar skingrades över Dun Morogh för att fly från sin förstörda stad överföll trollen eftersläntrarna och släpade deras övergivna utrustning och packning tillbaka till sina läger.",al={"varför har trollen felix chest","vem stal felix chest","trollen felix whindlebolt"}},{q="Var finns kistan?",a="Kistan finns sydväst om Anvilmar i Coldridge Valley, nära tälten i en Frostmane-bosättning och bland andra plundrade förnödenheter.",al={"var finns felix chest","felix chest plats","hitta felix chest"}}},fx={cd14610d={q="Vad är Felix's Chest?",a="Felix's Chest är en kista med personliga tillhörigheter och verktyg som ägs av Felix Whindlebolt, en gnomisk flykting som nu tar skydd i Anvilmar. När Gnomeregan blev bestrålat flydde Felix till Dun Morogh, men förlorade kistan till Frostmane-trollen under den kaotiska flykten.",al={"vad är felix's chest","felix's chest","vem äger felix's chest"}},bcb95cf5={q="Varför vill Felix ha tillbaka sin kista?",a="Felix Whindlebolt flydde från Gnomeregans tragiska fall med nästan ingenting kvar. Kistan innehåller hans personliga tillhörigheter och praktiska verktyg, sådant han behöver för att överleva och börja om bland dvärgarna i Coldridge Valley. Han saknar stridsförmågan att själv kämpa mot Frostmane-trollen och förlitar sig därför på äventyrslystna som vill hämta den åt honom.",al={"varför vill felix ha sin kista","varför behövs felix's chest","varför hämta felix's chest"}}},fp="13,141,18.417.0,29.239.0,52.260.0,27.133.0"}
P.entries["item:felstalker-hoof"] = {n="Felstalker Hoof",s="I Durotars Valley of Trials möter unga shamaner demoniska felstalkers som ett mognadsprov. Deras hovar förs till Canaga Earthcaller innan de lär sig att samtala med jordandar.",h="I Durotars Valley of Trials möter unga shamaner demoniska felstalkers som ett mognadsprov.",kw={"burning blade coven","call of earth","canaga earthcaller","durotar","earth sapta","felstalker","felstalker hoof","valley of trials"},ang={["class:Shaman"]="Som shaman börjar du din väg mot gemenskap med jordandarna genom att dräpa demoner och samla deras hovar. Provet prövar tålamodet och den envisa uthållighet du behöver för att använda en Earth Totem.",["faction:Horde"]="Demoniska felstalkers på Durotars övningsmarker påminner Horden om att Burning Blades fördärv ännu dröjer sig kvar i dess länder."},sec={{t="En prövning för schamaner",b="Canaga Earthcaller skickar unga shamaner mot den demoniska smitta som hotar Durotar. Burning Blade Coven ligger norrut i Valley of Trials, där felstalkers strövar bland sektens vidriga tjänare. Att ta en felstalkers hov prövar en shamans uthållighet, beslutsamhet och ande. De som betvingar bestarna visar sig redo att ta emot jordens hemligheter och förbereda den ceremoniella sapta för att tala med elementandar."}},faq={{q="Vad används Felstalker Hoof till?",a="Du för två Felstalker Hooves till Canaga Earthcaller i Valley of Trials. De visar att en shamanlärling har styrkan och anden att börja tala med jordelementet.",al={"vad gör felstalker hoof","hov som uppdragsföremål","varför samla felstalker hooves"}},{q="Var kommer hovarna ifrån?",a="Hovarna kommer från demoniska Felstalkers i och kring Burning Blade Coven, i norra Valley of Trials i Durotar.",al={"var hittar man felstalker hoof","felstalker hoof plats","vem släpper hovar"}},{q="Vem behöver dessa hovar?",a="Canaga Earthcaller, shamantränaren nära The Den i Valley of Trials, ber om hovarna under Call of Earth-riten.",al={"vem vill ha felstalker hooves","vem lämnar man in hoven till","canaga earthcaller uppdrag"}},{q="Kan alla äventyrare samla in dessa hovar?",a="Shamaner som genomgår elementinvigningen söker Felstalker Hooves. Krigare, häxmästare och lönnmördare genomgår sina egna prövningar i dalen och behöver dem inte.",al={"kan andra än schamaner få hovar","är hoven bara för schamaner"}}},fx={["1af4909c"]={q="Vad är en Felstalker Hoof?",a="En Felstalker Hoof är en fysisk trofé från de demoniska felstalkers som Burning Blade-kultisterna har kallat fram i Durotar. Den används inte som hantverksmaterial, utan tas som bevis på stridsduglighet av unga schamaner som söker kontakt med jordens andar.",al={"vad är felstalker hoof","information om felstalker hoof","vad är felstalker-hoovar"}}},fp="15,192,16.424.0,37.178.0,32.128.0,26.127.0,40.156.0"}
P.entries["item:fenwick-s-head"] = {n="Fenwick's Head",s="Fenwick's Head är det makabra beviset på att Fenwick Thatros avrättats, hämtat vid Lordamere Lake. Den krävs av Forsaken-skurkar som följer direkta order från Lord Varimathras.",h="Fenwick's Head är det makabra beviset på att Fenwick Thatros avrättats, hämtat vid Lordamere Lake.",kw={"deathstalkers","fenwick","lordamere","mennet carkad","rogues' quarter","silverpine","thatros","varimathras"},ang={["class:Rogue"]="Att göra anspråk på Fenwick's Head är en avgörande milstolpe för Forsaken-skurkar på uppgång. Det visar att de är pålitliga Deathstalkers och ger dem tillgång till avancerad träning.",["race:Undead"]="Jakten visar hur hänsynslöst Forsaken krossar rivaliserande fraktioner av odöda som utmanar deras kontroll över Silverpine Forest och stränderna vid Lordamere Lake."},sec={{t="Ett kontrakt från skuggorna",b="I Undercitys Rogues' Quarter agerar Mennet Carkad på brådskande underrättelser som kommer direkt från dreadlord Varimathras. En fientlig odöd ledare vid namn Fenwick Thatros har etablerat ett fäste nära de förfallna hamnarna vid Lordamere Lake i Silverpine Forest. För att hindra hotet från att samla fientliga odöda mot Forsaken skickar Carkad ut lovande Deathstalkers för att hitta Thatros, döda honom och skilja hans huvud från kroppen som otvetydigt bevis på att han dödats."},{t="En övergångsrit",b="Att återlämna Fenwick's Head till Carkad handlar om mer än att bara hämta ut en belöning; det är ett avgörande prov för Deathstalker-operatörer. När den avskurna trofén visas upp bekräftar det skurkens förmåga att infiltrera och lönnmörda, och öppnar dörren till djupare och mer specialiserad undervisning i skuggkonsterna från Forsakens mästare."}},faq={{q="Vem var Fenwick Thatros?",a="Lord Varimathras identifierade Fenwick Thatros som en odöd ledare som hade befäst sig i Silverpine Forest. Hans närvaro nära de förfallna hamnarna vid Lordamere Lake gjorde honom till ett omedelbart hot mot Forsakens intressen i området.",al={"vem är fenwick","fenwick thatros bakgrund","vem var thatros"}},{q="Vem vill ha Fenwick's Head?",a="Huvudet krävs av Mennet Carkad, en Deathstalker-tränare i Undercitys Rogues' Quarter, som utför en brådskande order från Lord Varimathras.",al={"vem vill ha huvudet","vem lämnade in det till","mennet carkad"}},{q="Var finns Fenwick Thatros?",a="Enligt underrättelser från Deathstalker-spejare håller Fenwick Thatros till vid de förfallna hamnarna längs stranden av Lordamere Lake i Silverpine Forest.",al={"fenwick thatros plats","var finns fenwick","hitta fenwick"}},{q="Varför måste hans huvud skiljas från kroppen?",a="Mennet Carkad kräver otvetydiga fysiska bevis på att hotet har undanröjts helt innan han låter en operatör gå vidare till avancerad skuggträning.",al={"varför ta hans huvud","varför halshugga honom"}}},fx={bc6d2652={q="Var kommer Fenwick's Head ifrån?",a="Det här avhuggna huvudet kommer från Fenwick Thatros, en odöd ledare som påträffas nära de förfallna bryggorna vid Lordamere Lakes stränder i Silverpine Forest. Det är inget tillverkat föremål, utan de kusliga kvarlevorna efter en fiendebefälhavare som tagits på slagfältet.",al={"fenwick's head ursprung","var får man fenwick's head","vem hade fenwick's head"}}},fp="14,161,27.404.0,17.280.0,24.205.0,25.150.0,33.116.0,29.132.0"}
P.entries["item:fey-dragon-scale"] = {n="Fey Dragon Scale",s="En Fey Dragon Scale är en skimrande skogsrelik från de skygga faerie dragons som lever kring Stonetalon Peak. Den eftertraktas av Darkspear-häxdoktorn Jin'Zil, som använder den som en exotisk ingrediens i en alkemisk brygd som hånar Night Elfs naturmagi.",h="En Fey Dragon Scale är en skimrande skogsrelik från de skygga faerie dragons som lever kring Stonetalon Peak.",kw={"faerie dragon","fey dragon scale","skogsmagi","jin'zil","malaka'jin","nal'taszar","stonetalon peak"},ang={["faction:Horde"]="Genom att hjälpa Jin'Zil säkrar du Hordes fotfäste i Stonetalon Mountains och slår direkt mot Night Elfs närvaro högre upp längs sluttningarna.",["race:NightElf"]="Faerie dragons är dyrkade följeslagare och skogsväktare för kaldoreierna; att se deras fjäll ryckas loss för en trollhäxdoktors dödliga hån är en skymf mot naturen."},sec={{t="En sällsynt skogsskörd",b="Faerie dragons är mystiska och skygga varelser med starka band till Kalimdors vilda lundar, särskilt de orörda skogarna kring Stonetalon Peak. Deras fjäll bär ett naturligt magiskt skimmer som påminner om de djupa skogar de skyddar. Night Elfs vördar dem som ofarliga skogsandar och bundsförvanter, medan utomstående ser dem som en otämjd källa till sällsynta magiska ingredienser."},{t="En hånfull brygd",b="I Horde-bosättningen Malaka'jin kokar Witch Doctor Jin'Zil ihop en ondskefull blandning som parodierar kaldoreiernas heliga traditioner. Genom att blanda ett Fey Dragon Scale med trädsaft, morrhår från kattdjur och dussin efter dussin med courserögon brygger Jin'Zil något han hånfullt kallar \"skogsmagi\". Den grymma brygden är ingen harmlös naturvälsignelse, utan är avsedd för de tre Night Elfs han håller inspärrade."}},faq={{q="Varifrån kommer fjället?",a="Fjället skördas från faerie dragons som fladdrar genom högländernas lundar kring Stonetalon Peak, däribland skygga varelser som Wily Fey Dragons och Nal'taszar.",al={"var droppar fey dragon scale","var hittar man fey dragon scale","vem droppar fey dragon scale"}},{q="Varför vill Witch Doctor Jin'Zil ha ett Fey Dragon Scale?",a="Witch Doctor Jin'Zil i Malaka'jin ber om fjället tillsammans med andra skogsingredienser för att brygga det han hånfullt kallar \"skogsmagi\" åt sina inspärrade Night Elf-fångar.",al={"varför vill jin'zil ha detta","vad används fjället till","jin'zils ingrediens till skogsmagi"}},{q="Vad händer när Jin'Zil har bryggt klart?",a="Jin'Zil tänker använda den färdiga brygden på sina tre fångna Night Elfs. Deras öde avslöjas när han sätter planen i verket.",al={"vad gör jin'zil med brygden","resultatet av jin'zils magi","jin'zils fångar"}}},fx={["9423a9c1"]={q="Vad är en Fey Dragon Scale?",a="En Fey Dragon Scale är en skimrande, iriserande fjäll från de svårfångade fédrakarna vid Stonetalon Peak. Dessa mystiska varelser är nära knutna till vildmarkens naturliga energier. För en alkemist eller häxdoktor är fjället ett kraftfullt, magiskt laddat reagens, fyllt av den uråldriga skogens råa essens.",al={"vad är fey dragon scale","fey dragon scale i historien","om fey dragon scales"}}},fp="16,167,21.239.0,20.290.1,32.125.0,54.167.0,44.142.1"}
P.entries["item:filled-amethyst-phial"] = {n="Filled Amethyst Phial",s="The Filled Amethyst Phial innehåller heligt vatten från den uråldriga månkällan under The Oracle Trees grenar. Vattnet har samlats in åt Corithras Moonrage och renats, och Cenariondruiderna använder det för att studera Teldrassils oroväckande och bristfälliga tillväxt.",h="The Filled Amethyst Phial innehåller heligt vatten från den uråldriga månkällan under The Oracle Trees grenar.",kw={"amethyst phial","corithras moonrage","crown of the earth","filled amethyst phial","månkällan","the oracle glade","oracle tree","teldrassil"},ang={["class:Druid"]="Cenariondruider vördar månkällor som kanaler för naturens och astral energi. De använder renade kärl som den här flaskan för att studera Teldrassils skadade ekologi.",["race:NightElf"]="För kaldorei innebär det att fylla flaskan en dyster insikt: Drak-aspekterna förkastade deras nya, strålande hem, och deras förlorade odödlighet har inte återvänt."},sec={{t="Vatten från The Oracle Tree",b="Långt åt nordväst i Teldrassil ligger The Oracle Glade, där öns äldsta och mäktigaste månkällor vilar under det väldiga Oracle Tree. De mindre månkällorna runtom i grenverket tillgodoser nattalvernas dagliga behov, men vattnet i denna källa är genomsyrat av Elunes nåds rena essens. Druider som fått i uppdrag att hålla uppsikt över världsträdets hälsa använder särskilda ametistflaskor för att samla in och bevara denna kraftfulla vätska för tester och rituell rening."},{t="En bristfällig återväxt",b="Att föra provet tillbaka till Corithras Moonrage fyller ett sorgset syfte. Ärkedruiden Fandral Staghelm lyckades resa Teldrassil för att ersätta det fallna Nordrassil, men Drak-aspekterna vägrade helga det. Utan Nozdormus välsignelse, som skulle återge nattalverna deras odödlighet, eller Alexstraszas skydd av dess livskraft, förblir Teldrassils tillväxt hämmad och plågad av korruption. Prover från gläntan visar att inte ens öns heligaste vatten kan dölja den krypande sjukdom som slår rot i världsträdet."}},faq={{q="Varifrån kommer vattnet i den här flaskan?",a="Vattnet hämtas direkt från månkällan i The Oracle Glade, i nordvästra Teldrassil, under de väldiga rötterna till Oracle Tree.",al={"var fyller jag den","månkällans plats","oracle trees källa"}},{q="Vad gör månkällan i Oracle Glade särskild?",a="Den vördas som den första och mäktigaste månkällan som skapats på Teldrassil. Där finns Elunes kraft koncentrerad, och den uråldriga Oracle Tree vakar själv över den.",al={"varför oracle glade","oracle moonwells betydelse"}},{q="Vem ber dig samla in vattnet?",a="Corithras Moonrage, en nattalvdruid stationerad i Dolanaar, ger unga äventyrare i uppdrag att samla in vattnet som en del av ritualerna kring Crown of the Earth.",al={"vem vill ha flaskan","corithras uppdrag"}},{q="Varför testar druiderna Teldrassils månkällor?",a="Teldrassil reste sig utan Drak-aspekternas välsignelser och är därför sårbart. Druiderna tar prover från månkällorna för att hålla uppsikt över världsträdets hälsa, som visar oroväckande tecken på korruption och hämmad tillväxt.",al={"varför testa vattnet","teldrassils sjukdom"}}},fx={d7e170ec={q="Vad är Filled Amethyst Phial?",a="Filled Amethyst Phial är en behållare med heligt vatten från månbrunnen under The Oracle Tree i The Oracle Glade. Den kallas den första och mäktigaste av Teldrassils månbrunnar. Det skimrande vattnet rymmer en koncentrerad essens av Elunes nåd, vilket gör provet avgörande för kaldorei som undersöker öns hälsa.",al={"vad är filled amethyst phial","föremålet filled amethyst phial","vad amethyst phial är till för"}}},fp="21,175,24.374.0,16.466.1,45.103.0,44.173.0,34.125.0,50.205.0"}
P.entries["item:filled-blue-waterskin"] = {n="Filled Blue Waterskin",s="Schamaner samlar vatten för sina prövningar vid Ruins of Stardust i Ashenvale. Filled Blue Waterskin innehåller ett orört prov från den uråldriga källan.",h="Schamaner samlar vatten för sina prövningar vid Ruins of Stardust i Ashenvale.",kw={"ashenvale","brine","call of water","filled blue waterskin","lake mystral","the ruins of stardust","schamanuppdrag"},ang={["class:Shaman"]="Som schaman samlar du in detta vatten som det sista steget i att bemästra vatten och tar dig över fientliga fraktionsgränser för att gå i förbindelse med naturens renaste vattenkällor.",["faction:Horde"]="Som en hordelärling ger du dig norrut in i Ashenvales omstridda skogar och nattalvernas förfädersmarker för att fullborda heliga riter, med verklig fara på vägen."},sec={{t="Ashenvales heliga källa",b="De som påbörjar Call of Water färdas norrut från The Barrens in i Ashenvales täta skogar. Bortom Lake Mystral ligger Ruins of Stardust vid bergen som skiljer Ashenvale från Stonetalon. Vilda skogsdjur vaktar den avskilda alviska helgedomen. Mitt i sjön håller en orörd källa vatten som inte fläckats av korruption eller torka. En blå vattensäck fylld från dess bäcken innehåller provet som schamanmästarna söker för rituell invigning."},{t="En harmonins rit",b="Brine, en eremit och vattenexpert, bor på en kulle i södra The Barrens och behöver det sista provet. Han blandar det med vatten från brunnar och källor med andra egenskaper och destillerar sedan den rena essensen till en offergåva. Gåvan kan mana fram och lugna vattnets elementandar och därmed fullborda en lärlings prövning."}},faq={{q="Var samlas vattnet som fyller denna vattensäck?",a="Vattnet kommer från en liten källa mitt i sjön vid Ruins of Stardust, i sydvästra Ashenvale bortom Lake Mystral.",al={"var fyller jag den","ruins of stardusts källa","vattenplats"}},{q="Vem behöver detta vatten?",a="Brine, en eremit som bor i södra The Barrens, behöver vattnet till de Call of Water-prövningar han ger novisschamaner.",al={"vem vill ha den blå vattenskinnen","brine vatten","call of water npc"}},{q="Varför samlar man in detta prov?",a="Brine behöver det sista provet för att brygga en dryck av ovanligt rent vatten, så att en blivande schaman kan gå i förbindelse med och hedra vattnets elementandar.",al={"varför behöver jag den","vad används filled blue waterskin till"}},{q="Är området där vattnet hämtas farligt?",a="Ja. Fientliga vilda djur, däribland lokala elementandar och vildsinta bestar, håller till vid Ruins of Stardust och försvarar den uråldriga alvlunden.",al={"ruins of stardust fara","är källan i ashenvale säker"}}},fx={["031dd284"]={q="Vad är Filled Blue Waterskin?",a="Filled Blue Waterskin är en läderbehållare fylld med rent källvatten från en fontän i The Ruins of Stardust, djupt inne i Ashenvales skogar. Den är ett av de viktiga elementprover som en schaman behöver under de heliga prövningarna i Call of Water.",al={"vad är filled blue waterskin","föremålet filled blue waterskin"}},eff34fc2={q="Var kommer Filled Blue Waterskin ifrån, och vem gjorde den?",a="Själva vattenskinnet är en tom påse som Brine, en eremit i södra Barrens, gav dig. Den blir Filled Blue Waterskin när du reser norrut till Ashenvales urgamla alvmarker och hämtar färskt vatten från den heliga fontänen mitt i sjön vid The Ruins of Stardust.",al={"varifrån kommer filled blue waterskin","vem gjorde filled blue waterskin","källa till filled blue waterskin"}},["320c16da"]={q="Varför vill Brine ha Filled Blue Waterskin?",a="Brine behöver det här provet som den sista delen i en samling med tre sorters rent vatten från olika delar av Azeroth. När hon blandar det med de andra vattenkällorna du har samlat in skapar hon en flaska oförorenat, rent vatten som behövs för nästa del av din schamanska övergångsrit.",al={"varför behöver brine filled blue waterskin","varför vill någon ha filled blue waterskin","vad filled blue waterskin är till för"}}},fp="21,155,26.449.0,17.315.0,51.136.0,24.120.0,46.164.0,50.134.0"}
P.entries["item:filled-brown-waterskin"] = {n="Filled Brown Waterskin",s="I The Barrens bär Filled Brown Waterskin med sig färskt vatten från dammen nedanför Brines hydda. Blivande schamaner tar den till henne för att börja brygga sapta, som används för att tala med vattenandar.",h="I The Barrens bär Filled Brown Waterskin med sig färskt vatten från dammen nedanför Brines hydda.",kw={"the barrens","brine","brown waterskin","call of water","filled brown waterskin","quilboar","sapta","shamanuppdrag"},ang={["class:Shaman"]="Som schaman hämtar du vattnet som Brines första praktiska prov under Call of Water. Det lär dig att respektera balansen och de starka känslor som omger vatten."},sec={{t="En livgivande torka",b="Dammen nedanför Brines hydda är en sällsynt källa till färskt vatten i The Barrens. Quilboar i närheten strider våldsamt om den, och en nybörjarschaman ser hur vattenbrist kan få varelser att försvara det som håller dem vid liv."}},faq={{q="Vad används Filled Brown Waterskin till?",a="Du tar vattnet till Brine vid hennes hydda i södra The Barrens. Hon använder det för att börja tillreda sapta, en dryck som låter schamaner uppfatta och tala med vattenandar.",al={"användning av brown waterskin","vad är filled brown waterskin","vad gör jag med filled brown waterskin"}},{q="Var kommer vattnet ifrån?",a="Vattnet kommer från en liten sötvattensdamm strax nedanför åsen under Brines avlägsna hydda. Quilboar i området strider våldsamt om dammen.",al={"var hämtar man vatten","dammens plats","var ligger vattenhålet"}},{q="Varför slåss quilboar om den här vattenkällan?",a="Regn är ytterst sällsynt i det torra The Barrens, så quilboar håller fest när det kommer. De vaktar naturliga källor mot främlingar, även till döden.",al={"varför anfaller quilboar","quilboar och vatten","varför är vatten heligt för quilboar"}}},fx={["52b5cef0"]={q="Vad är Filled Brown Waterskin?",a="Det är en enkel vattenbehållare fylld från sötvattensdammen nedanför Brines hydda i det torra The Barrens. Vattnet hämtas som en del av en schamans prövning och fungerar som ett rent elementprov som visar hur även en anspråkslös vattensamling kan upprätthålla liv och skapa konflikter i en uttorkad öken.",al={"filled brown waterskin","vad är filled brown waterskin","vad är den bruna vattenbehållaren"}}},fp="22,187,21.208.0,44.170.0,32.136.0,49.153.0"}
P.entries["item:filled-cliffspring-falls-sampler"] = {n="Filled Cliffspring Falls Sampler",s="Filled Cliffspring Falls Sampler innehåller grumligt vatten från källflödena nära Cliffspring Falls i Darkshore. Det samlades in på uppdrag av Cenarion Circle och är avgörande bevis för att avslöja vad som förgiftar traktens hjortdjur.",h="Filled Cliffspring Falls Sampler innehåller grumligt vatten från källflödena nära Cliffspring Falls i...",kw={"alanndarian nightsong","auberdine","cenarion circle","cliffspring falls","darkshore","dendrite starblaze","förgiftat vatten","provflaska"},ang={["class:Druid"]="Att hämta och analysera det förgiftade vattnet är ett viktigt prövningsprov för alliansens druider och lägger grunden för att bemästra Cure Poison.",["race:NightElf"]="För nattalverna i Darkshore är det avgörande att säkra källflödena vid Cliffspring och skydda Auberdines ekologi från motbjudande, främmande föroreningar."},sec={{t="En förgiftad källa",b="Cliffspring Falls är den främsta dricksvattenkällan för stora delar av Darkshore. Vattnet störtar ner från de östra högländerna mot havet. På senare tid har dock de djur som är beroende av vattnet, särskilt traktens hjortdjur, drabbats av en försvagande, onaturlig sjukdom. På uppmaning av Dendrite Starblaze i Moonglade hämtar druidiska noviser provet direkt vid mynningen till en grotta som kryllar av fientliga naga. Flaskan innehåller synligt rutten vätska, vilket bekräftar att regionens främsta färskvattenkälla har förorenats."},{t="Vägen till ett botemedel",b="Det motbjudande provet förs till Alanndarian Nightsong i Auberdine och ger Cenarion Circle de fysiska bevis som behövs för att studera giftet. I stället för att bara göra sig av med det använder Alanndarian det förorenade vattnet för att analysera smittämnets sammansättning. När druidernas lyckas fastställa slammets exakta egenskaper kan de framställa en läkande salva. Det är ett viktigt steg i utvecklingen av riten som ger utövare makt över gift."}},faq={{q="Vad finns i Filled Cliffspring Falls Sampler?",a="Den innehåller förorenat vatten som skopats upp vid grottmynningen nära Cliffspring Falls i Darkshore. Vattnet är synligt missfärgat och bär på giftet som gör traktens hjortdjur sjuka.",al={"provets innehåll","vilket vatten finns i flaskan","vad finns i provet"}},{q="Vem ber om vattenprovet?",a="Dendrite Starblaze från Cenarion Circle instruerar unga druider att samla in provet. Alanndarian Nightsong i Auberdine tar emot det för att analysera giftet och ta fram ett botemedel.",al={"vem vill ha vattenprovet","vem ska jag ge provflaskan till","vem behöver den fyllda provflaskan"}},{q="Varför är Cliffspring Falls så viktigt?",a="Cliffspring Falls är den främsta dricksvattenkällan i Darkshore. Föroreningar i fallet sprids genom de lokala vattendragen och påverkar hela vildmarken.",al={"varför cliffspring falls","cliffspring falls betydelse"}},{q="Vad får vattnet att bli smutsigt?",a="Vattnet kommer från trakten kring en grotta som nyligen översvämmats av fientliga naga. Deras närvaro sammanfaller med att källflödena förorenats, vilket sprider onaturlig sjukdom bland traktens djur.",al={"vem förgiftade vattnet","varför är fallet förgiftat","naga vid cliffspring falls"}}},fx={["57552b8f"]={q="Varifrån kommer Filled Cliffspring Falls Sampler, och vem har tillverkat den?",a="Det tomma provröret av glas delas ut till unga druider av Dendrite Starblaze i Moonglade på uppdrag av Cenarion Circle. Det blir Filled Cliffspring Falls Sampler när du tar det till mynningen av den nagaangripna grottan intill Cliffspring Falls i Darkshore och hämtar vatten direkt ur den förorenade bäcken.",al={"ursprung till filled cliffspring falls sampler","vem tillverkade cliffspring sampler","var får man cliffspring sampler"}}},fp="32,189,16.353.0,16.310.1,52.176.0,31.171.0,38.156.0,39.168.0"}
P.entries["item:filled-containment-coffer"] = {n="Filled Containment Coffer",s="En Filled Containment Coffer är en förtrollad behållare som Förfallna besvärjare använder för att fånga oberäkneliga magiska väsen. Genom att använda Cantation of Manifestation för att avslöja och försvaga sprickfödda varelser i Apothecarium kan magiker fånga anomalierna i dessa förstärkta lådor för säker undersökning.",h="En Filled Containment Coffer är en förtrollad behållare som Förfallna besvärjare använder för att fånga...",kw={"algernon","anastasia hartwell","apothecarium","arkan störning","cantation of manifestation","förvaringskista","filled containment coffer","sprickfödd varelse"},ang={["class:Mage"]="Förfallna lärlingar hanterar dessa förvaringskistor som en praktisk lektion i abjuration och lär sig att avslöja gömda magiska väsen och binda instabil arkan energi i fysiska skydd.",["race:Undead"]="Apothecariums säkerhet är av största vikt för de Förfallna, så utredning och instängning av varje mystiskt magiskt genombrott är en brådskande inrikes angelägenhet."},sec={{t="Att fånga det osedda",b="När oförklarliga magiska störningar visade sig i Algernon's shop i Apothecarium gav den Förfallna magikern Anastasia Hartwell magiker i uppdrag att fånga de ansvariga väsendena. Eftersom sprickvarelserna enbart består av levande magisk energi och rör sig osedda är vanliga burar värdelösa. I stället gör besvärjare väsendena synliga med Cantation of Manifestation, besegrar dem i strid och slår igen dessa särskilt förberedda förvaringskistor runt dem. De förseglade lådorna skyddar bäraren från flyktiga magiska bakslag samtidigt som de håller exemplaren intakta för magisk dissektion."},{t="Magisk forensik",b="Förekomsten av levande manavarelser i Undercity utgör ett allvarligt hot. När de väl har förseglats i förvaringskistor transporteras de tillfångatagna bestarna tillbaka till Anastasia Hartwell och stadens lärda. De Förfallna magikerna oroar sig främst för om dessa intrång beror på naturliga sprickor i Azeroths magiska väv eller är inledande sonderingar inför ett beräknande magiskt angrepp riktat mot kungariket."}},faq={{q="Vad finns i en Filled Containment Coffer?",a="Varje kista innehåller en fångad sprickfödd varelse, ett osynligt väsen som består helt av rå magisk energi och visade sig i Algernon's alchemy shop i Apothecarium.",al={"vad finns i kistan","kistans innehåll","monster i fylld kista"}},{q="Hur fyller man en förvaringskista?",a="En magiker måste läsa Cantation of Manifestation för att göra de gömda varelserna synliga, besegra dem i strid och använda en tom kista för att fånga den återstående energin innan den skingras.",al={"hur fyller man kistan","hur fångar jag den sprickfödda varelsen","fylla kistan"}},{q="Vem vill ha de fyllda kistorna i Undercity?",a="Anastasia Hartwell, en framstående magikerlärare i Magic Quarter i Undercity, ber om de förseglade kistorna för att undersöka störningen som hotar staden.",al={"vem hämtar kistorna","uppdragsgivare för kistan","anastasia hartwell kista"}},{q="Varför studerar de Förfallna dessa varelser?",a="Undercitys lärda måste ta reda på om anomalin var slumpmässiga revor i det lokala magiflödet eller ett avsiktligt, samordnat angrepp från en fientlig magisk rival.",al={"varför studera sprickfödda varelser","orsak till sprickor i undercity"}}},fx={d6cc8dac={q="Vad är en Filled Containment Coffer?",a="En Filled Containment Coffer är en förtrollad behållare som magiker använder för att fånga och hålla kvar flyktiga varelser som består helt av magisk energi, till exempel riftspawn. När varelsen har tvingats fram i synlig form och kuvats, håller kistan den säkert för transport och studier utan att låta dess magiska väsen skingras.",al={"vad är filled containment coffer","filled containment coffer","föremålet containment coffer"}},["1e3ef013"]={q="Varifrån kommer en Filled Containment Coffer, och vem har tillverkat den?",a="De tomma kistorna är särskilda magiska föremål som delas ut av magilärare som Anastasia Hartwell i Undercity. De fylls när en magilärling spårar upp osynliga magiska varelser, som de som lurar kring Algernon's shop i Apothecarium, tvingar fram dem, försvagar dem och förseglar dem inuti.",al={"vem tillverkade containment coffer","containment coffer ursprung","var kommer containment coffers ifrån"}}},fp="25,235,19.534.0,16.349.0,43.150.0,35.176.0,44.159.0,46.169.0"}
P.entries["item:filled-crystal-phial"] = {n="Filled Crystal Phial",s="En Filled Crystal Phial innehåller heligt vatten från månskålen strax norr om Aldrassil i Shadowglen. Vattnet samlades in på uppdrag av Tenaron Stormgrip och ger nybörjare en första inblick i den heliga och oberäkneliga kraft som flödar genom Teldrassil.",h="En Filled Crystal Phial innehåller heligt vatten från månskålen strax norr om Aldrassil i Shadowglen.",kw={"aldrassil","crown of the earth","crystal phial","filled crystal phial","månskål","shadowglen","tenaron stormgrip","well of eternity"},ang={["class:Druid"]="Druider vördar månskålens vatten djupt och använder dess livgivande energier för att vårda fördärvad växtlighet och hålla de stora träden vid liv.",["race:NightElf"]="Varje ung kaldorei som börjar sin träning under Aldrassil fyller denna flaska och begrundar Mount Hyjals uppoffring och sin heliga plikt att skydda naturen."},sec={{t="Månskålens vatten",b="För att förbereda unga nattalver innan de ger sig ut i den större världen skickar Tenaron Stormgrip dem att hämta vatten från månskålen i Shadowglen. Flaskan innehåller mer än vanligt källvatten; månskålar är genomsyrade av kvarvarande energier som spåras tillbaka till den uråldriga Well of Eternity. Vaktposterna vördar dessa platser som välsignade helgedomar till Elune, och druider kanaliserar deras läkande egenskaper när de vårdar naturen, men den forna arkanistiska magin är fortfarande strikt förbjuden. Att hämta detta vatten är första steget mot att förstå uppoffringarna vid Mount Hyjal och den varsamma balans som krävs för att vårda Teldrassil."}},faq={{q="Vad finns i Filled Crystal Phial?",a="Flaskan innehåller vatten från månskålen norr om Aldrassil i Shadowglen. Vattnet bär på rester av den uråldriga Well of Eternity, välsignat av Elunes ljus och vårdat av druider.",al={"vilket vatten finns i flaskan","flaskans innehåll","vad finns i crystal phial"}},{q="Vem ber dig fylla flaskan?",a="Tenaron Stormgrip, som är stationerad högt uppe bland Aldrassils grenar, skickar ut spirande äventyrare för att hämta vattnet som en del av deras övergångsrit och historiska undervisning.",al={"vem vill ha flaskan","vem ger uppdraget med crystal phial","tenaron stormgrips uppdrag"}},{q="Varför vill Tenaron Stormgrip ha vattnet?",a="Tenaron använder insamlingen som en första lektion i nattalvernas historia efter det tredje kriget och lär unga äventyrare om Nordrassils uppoffring, månskålarnas kraft och det fortsatta ansvaret för Teldrassil.",al={"varför fylla crystal phial","crown of the earths syfte"}},{q="Är vattnet farligt?",a="Vattnet bär på mäktig magi med rötter i den uråldriga Well of Eternity. Druider och prästinnor använder det säkert till välsignelser och läkedom, men vårdslös arkanistisk manipulation av sådant vatten ledde till katastrof i forna tider och är fortfarande strikt förbjuden.",al={"är månskålens vatten farligt","är vattnet magiskt"}}},fx={e7bb2009={q="Vad är Filled Crystal Phial?",a="Filled Crystal Phial är ett ömtåligt kristallkärl med vatten från månkällan i Shadowglen. Det innehåller den rena, heliga vätskan som genomsyrats av Well of Eternitys uråldriga kraft, avsedd både som ett heligt offer och som en praktisk lektion i ditt folks fortsatta andliga förvaltarskap.",al={"vad är filled crystal phial","filled crystal phial","föremålet filled crystal phial"}},e140e7c7={q="Varifrån kommer Filled Crystal Phial?",a="Den skapas när du tar en tom kristallflaska som Tenaron Stormgrip har gett dig och sänker ned den direkt i den heliga månkällan strax norr om Aldrassil i Shadowglen.",al={"filled crystal phial ursprung","varifrån kommer filled crystal phial","hur får man filled crystal phial"}}},fp="20,199,22.505.0,40.195.0,31.149.0,43.202.0,25.228.0"}
P.entries["item:filled-cursed-ooze-jar"] = {n="Filled Cursed Ooze Jar",s="En Filled Cursed Ooze Jar innehåller giftiga rester från en förbannad slemvarelse som samlats in i Felwoods fördärvade skogar. Den samlas in åt Laris Geardawdle, en gnomisk lärd i Ironforge som försöker avslöja slemvarelsernas ursprung i Azeroth.",h="En Filled Cursed Ooze Jar innehåller giftiga rester från en förbannad slemvarelse som samlats in i Felwoods...",kw={"cursed ooze","explorers' league","felwood","filled cursed ooze jar","ironforge","laris geardawdle","slem"},ang={["faction:Alliance"]="Alliansens naturfilosofer i Ironforge håller noga uppsikt över Forsakens förehavanden och noterar att Royal Apothecary Society också har visat ett mörkt intresse för att samla in slemprover runtom i Azeroth.",["race:Gnome"]="Laris Geardawdles besatthet av slemaforskning är djupt personlig och drivs av en önskan att ära de hemlösa gnomen och bevisa deras intellektuella värde för dvärgvärdarna i Ironforge."},sec={{t="Ett märkligt exemplar",b="Medan de flesta äventyrare undviker de vidriga pölarna och frätande slemvarelserna som kryper omkring på Kalimdor, ser den gnomiska forskaren Laris Geardawdle dem som ett biologiskt mysterium. När han lade märke till att slemvarelser förekommer i vitt skilda miljöer och såg hur Forsaken-apotekare samvetsgrant samlade in dem, utvecklade Geardawdle en kontroversiell teori: slem kan vara uråldriga utsöndringar med direkt koppling till Azeroths skapelse. För att samla in ett prov måste du våga dig in i Felwoods fördärvade skogar, besegra en förbannad slemvarelse och skopa upp den frätande massan i en tom burk innan den löses upp helt."},{t="Akademiska ambitioner",b="Att säkra dessa illaluktande prover tjänar ett dubbelt syfte för Geardawdle. Utöver jakten på naturvetenskapliga rön hoppas han att en stor upptäckt ska befästa hans anseende inom den dvärgledda Explorers' League. Efter Gnomeregans förödande fall känner många gnomiska flyktingar i Ironforge en stark press att bevisa sitt värde för sina dvärgvärdar, och Geardawdle tror att om han avslöjar slemvarelsernas uråldriga hemligheter visar det alla att det inte var något misstag att välkomna gnomen."}},faq={{q="Var kommer den här burken ifrån?",a="Du får den genom att använda en Empty Cursed Ooze Jar på resterna av en besegrad Cursed Ooze i Felwoods fördärvade områden.",al={"var får jag tag på cursed ooze jar","hur får jag filled cursed ooze jar","ooze jar plats"}},{q="Vem vill ha de här slemproverna?",a="Laris Geardawdle, en gnomisk forskare i Hall of Explorers i Ironforge, efterfrågar dem för att driva sin forskning om naturhistoria framåt.",al={"vem behöver ooze jars","laris geardawdle uppdrag","vem lämnar in ooze jar"}},{q="Varför studerar Laris Geardawdle slemvarelser?",a="Han lade märke till att både naturen och Royal Apothecary Society visar stort intresse för slemvarelser. Han antar att slem kan vara uråldriga utsöndringar med koppling till själva skapelsen och utvecklingen av liv på Azeroth, men behöver fysiska prover för att pröva sina teorier.",al={"varför studera slemvarelser","geardawdles slemteori","varför slem"}},{q="Varför bryr sig en gnom om Explorers' League?",a="Efter Gnomeregans fall sökte gnomiska flyktingar skydd bland dvärgarna i Ironforge. Geardawdle hoppas att ett stort vetenskapligt genombrott genom Explorers' League ska visa deras värdar att det var rätt val att ge gnomen skydd.",al={"varför explorers' league","gnomer i ironforge"}}},fx={b5982a20={q="Vad är Filled Cursed Ooze Jar?",a="Det är en särskilt förberedd provbehållare fylld med ett färskt prov från en dödad förbannad slemvarelse i Felwood. Dessa vidriga, förvridna slemvarelser frodas bland den demoniska förruttnelsen i den förgiftade skogen, så även små rester är flyktiga och farliga att hantera utan lämpliga glasbehållare.",al={"vad är filled cursed ooze jar","syftet med filled cursed ooze jar","cursed ooze jar"}}},fp="22,156,18.442.0,17.400.0,30.110.0,29.122.0,39.246.0,50.208.0"}
P.entries["item:filled-dreadmist-peak-sampler"] = {n="Filled Dreadmist Peak Sampler",s="På Dreadmist Peak innehåller ett fyllt provrör vatten som hordens druider samlat från pölarna på toppen. Cenarion Circle undersöker provet för att ta reda på vad som förgiftar djurlivet i norra The Barrens.",h="På Dreadmist Peak innehåller ett fyllt provrör vatten som hordens druider samlat från pölarna på toppen.",kw={"burning blade","cenarion circle","dreadmist peak","druid","filled dreadmist peak sampler","the barrens","den främsta källan","tonga runetotem"},ang={["class:Druid"]="Som horddruid samlar du in det här provet som en övergångsrit. Det lär dig hur korruption sprider sig genom naturliga vattendrag och förbereder dig på att bemästra läkande magi.",["faction:Horde"]="Som medlem av horden kan du se hotet från kulten Burning Blade växa inom hordens territorium i The Barrens."},sec={{t="En förgiftad källa",b="På Dreadmist Peaks höga klippor finns pölar vars dimmor formar väder och regn över norra The Barrens. Burning Blade, som dyrkar demoner, upprättade sitt kultnäste på toppen, och vattnet blev snart surt. Cenarion-druider misstänker att demoniska ritualer förgiftade ångorna som ger näring åt den omgivande savannen. De skickar noviser för att samla ett prov i ett särskilt provrör. Den illasmakande vätskan bekräftar deras farhågor: dess korruption kan göra hjordarna nedanför sjuka."},{t="Att bota savannen",b="Vid Crossroads använder Tonga Runetotem provet för att hjälpa till att hitta ett motgift. Burning Blade misstänks ha förorenat vattnet, och dess egenskaper hjälper Cenarion Circle att förstå giftet. Genom att studera föroreningen i ampullen tillverkar druiderna örtmediciner för döende gaseller och lär sig att behärska sin egen naturliga makt över gift."}},faq={{q="Var hämtar man vattenprovet?",a="Provet kommer från en pöl på toppen av Dreadmist Peak, nordväst om Crossroads i The Barrens.",al={"var hämtar jag provet","dreadmist sampler plats","var fyller jag flaskan"}},{q="Varför är vattnet på Dreadmist Peak förgiftat?",a="Kulten Burning Blade har tagit över Dreadmist Peaks höjder för att dyrka demoner. Dendrite Starblaze misstänker att kulten förorenat toppens naturliga vatten.",al={"varför är vattnet i dreadmist förgiftat","vem förgiftade dreadmist peak","burning blade vatten"}},{q="Vem behöver den fyllda flaskan?",a="Tonga Runetotem behöver det fyllda provröret. Han är en Cenarion-druid vid Crossroads som undersöker den plötsliga sjukdomen bland djurlivet i The Barrens.",al={"vem ska jag lämna flaskan till","tonga runetotem sampler","lämna in dreadmist-vatten"}},{q="Hur påverkar det förgiftade vattnet The Barrens?",a="Dreadmist Peaks luftiga höjder och pölar påverkar det lokala vädret och dimman. När ångorna väl förgiftats lägger de sig över savannen norr om huvudvägen och gör de inhemska gasellerna sjuka.",al={"vad gör vattnet","sjuka gaseller i the barrens","dreadmist dimmans effekt"}},{q="Vad används flaskan till efter att provet har samlats in?",a="Tonga Runetotem studerar den illasmakande vätskan för att förstå dess demoniska förorening och använder sedan kunskapen för att tillverka en läkande salva som druider kan behandla drabbade gaseller med.",al={"vad gör tonga med det","botemedel mot giftet","forskning om kraft över gift"}}},fx={f843c928={q="Vad är Filled Dreadmist Peak Sampler?",a="Det är en särskild flaska med ett vattenprov från den högt belägna dammen på toppen av Dreadmist Peak. Cenarion Circle ger den till druidernas invigda. Den är ett viktigt fysiskt bevis på den vidriga föroreningen som nu sipprar genom de höga bergskällorna och förstör djurlivet över de norra slätterna.",al={"vad är filled dreadmist peak sampler","dreadmist sampler","fylld provflaska druid"}},["2e934816"]={q="Varifrån kommer Filled Dreadmist Peak Sampler, och vem har tillverkat den?",a="Den tomma provflaskan av glas ges av Cenarion Circle i Moonglade till unga druider som studerar konsten att bota sjukdomar. Du fyller den själv vid dammen på toppen av Dreadmist Peak i The Barrens, där de demon dyrkande Burning Blade-kultisterna samlas och förorenar källflödena som påverkar klimatet i trakten.",al={"vem tillverkade dreadmist sampler","varifrån kommer dreadmist sampler","dreadmist sampler ursprung"}},cb57b91c={q="Varför vill Tonga Runetotem ha Filled Dreadmist Peak Sampler?",a="Tonga Runetotem vid The Crossroads behöver snabbt vattnet för att studera farsoten som drabbar de norra delarna av The Barrens. Gaseller och traktens djur blir våldsamt sjuka, och genom att analysera detta orena prov från toppen hoppas Tonga kunna hitta det onaturliga giftet och blanda till ett verksamt örtmedel som läker landet.",al={"varför vill tonga ha provet","tonga runetotem dreadmist-prov","varför hämta filled dreadmist sampler"}}},fp="29,195,16.444.0,18.336.1,36.102.0,43.159.0,29.148.0,48.183.0,51.171.0"}
P.entries["item:filled-etched-phial"] = {n="Filled Etched Phial",s="En Filled Etched Phial är ett utsmyckat dryadkärl fyllt med helgat vatten, hämtat direkt från en nattalvsmånbrunn i Ashenvale. Taurenerna i Thunder Bluff har bett om det, eftersom det välsignade vattnet har den sällsynta andliga kraft som krävs för att släcka den eviga låga som skyddar en helig centaurrelik.",h="En Filled Etched Phial är ett utsmyckat dryadkärl fyllt med helgat vatten, hämtat direkt från en...",kw={"ashenvale","dryad","etched phial","filled etched phial","galak","månbrunn","rau cliffrunner","thousand needles","zangen stonehoof"},ang={["race:NightElf"]="Nattalverna ser stölden av en dryads flaska och hordens agenter som skummar månbrunnsvatten som ett oförlåtligt intrång i Ashenvales heligaste helgedomar.",["race:Tauren"]="För taurenerna är det ett väl avvägt slag mot centaurerna i Galak-klanen att säkra vattnet. De vänder Cenarius barns gemensamma naturmagi mot sina gamla stamfiender."},sec={{t="Månbrunnsvatten och dryadhantverk",b="För att få tag i denna flaska måste du ta dig in på nattalvernas territorium, djupt inne i Ashenvale. Först måste du hämta det tomma kärlet från dryaderna kring Raynewood Retreat, där deras skira behållare tillverkas för att rymma rena, läkande drycker. Därefter fylls flaskan vid en helig månbrunn nära Falfarren Rivers västra strand. Där fångar den upp vatten som sjuder av himmelsk, naturbunden kraft. För nattalverna är det en uppenbar skändning att ta vattnet utan lov, men taurerna ser det som en livsviktig åtgärd mot ett regionalt hot längre söderut."},{t="Nyckeln till centaurernas trolldom",b="Zangen Stonehoof och Rau Cliffrunner sökte just detta vatten på grund av de dolda mytiska banden mellan dryader och centaurer. Båda släktena härstammar från Cenarius, vilket ger deras magiska traditioner en djup, sammanflätad resonans. I Thousand Needles vaktar Galak-klanen en uråldrig relik, skyddad av en obeveklig evig eld som har brunnit sedan centaurernas skapelse. Tack vare sina gemensamma ursprungskrafter kan det välsignade månbrunnsvattnet i denna dryadflaska tränga igenom och släcka den skyddande lågan."}},faq={{q="Vad finns i Filled Etched Phial?",a="Den innehåller heligt vatten som hämtats direkt från en nattalvsmånbrunn i Ashenvale, nära Falfarren River. Vattnet förvaras i en utsmyckad glasflaska som tagits från dryader nära Raynewood Retreat.",al={"vilket vatten finns i flaskan","vad är etched phial fylld med"}},{q="Varför behöver taurenerna månbrunnsvatten?",a="Rau Cliffrunner behöver det helgade vattnet för att bryta igenom en evig skyddande låga som upprätthålls av centaurerna i Galak-klanen i Thousand Needles. Eftersom dryader och centaurer har ett gemensamt ursprung genom Cenarius är månbrunnsvattnet stämt för att upplösa den uråldriga förtrollning som skyddar deras relik.",al={"varför månbrunnsvatten","varför behöver rau månbrunnsvatten"}},{q="Varifrån kommer den tomma flaskan?",a="Kärlet bärs av Laughing Sisters, dryaderna som vandrar i skogarna kring Raynewood Retreat i centrala Ashenvale.",al={"var hittar jag etched phial","hur får jag tag på en tom flaska"}},{q="Vem ska du lämna Filled Etched Phial till?",a="När du har hämtat vattnet lämnar du det först till Zangen Stonehoof på High Rise i Thunder Bluff. Han skickar dig sedan vidare med det till Rau Cliffrunner vid Freewind Post i Thousand Needles.",al={"vem får flaskan","lämna in flaskan"}}},fp="19,163,31.432.0,24.407.1,39.180.0,38.252.1,37.116.0,46.181.0"}
P.entries["item:filled-jade-phial"] = {n="Filled Jade Phial",s="Filled Jade Phial innehåller heligt vatten från månskällan nära Starbreeze Village. Det förs tillbaka till Dolanaar och används i en pågående ritual för att fylla på huvudstadens centrala vattenkällor, medan unga Night Elf lär sig sitt folks historia.",h="Filled Jade Phial innehåller heligt vatten från månskällan nära Starbreeze Village.",kw={"corithras moonrage","crown of the earth","dolanaar","filled jade phial","jade phial","månskälla","starbreeze village","teldrassil"},ang={["class:Druid"]="Att vårda månskällorna knyter druiderna direkt till den läkande magi som håller Darnassus vid liv och till Cenarion Circles pågående arbete med att vårda det unga Världsträdet.",["race:NightElf"]="Vattenhämtningen stärker en ung kaldoreis heliga plikt gentemot Teldrassil och förmedlar viktig historia om förlusten av odödligheten efter Mount Hyjal."},sec={{t="Starbreeze vatten",b="Druiderna i Darnassus använder heligt vatten från månskällor runt Teldrassils grenar för att fylla på sina centrala källor. Särskilt tillverkade kärl, som jadeflaskan som Corithras Moonrage anförtrott unga äventyrare i Dolanaar, är anpassade för att hålla det rena vattnet säkert. Genom att bege sig österut till månskällan utanför Starbreeze Village samlar de invigda in det livsviktiga vattnet och visar sin hängivenhet till att vårda Världsträdet."},{t="En historielektion",b="Att återlämna Filled Jade Phial till Dolanaar är mer än ett enkelt ärende; varje påfyllt kärl ger ett nytt kapitel i kaldoreiernas muntliga historia. När Corithras Moonrage får den fyllda flaskan berättar han om den desperata tiden efter det tredje kriget: Nordrassils förbränning, förlusten av Night Elfs odödlighet, Befriarens frigivning och Shan'do Malfurion Stormrages plötsliga försvinnande."}},faq={{q="Var fyller man Jade Phial?",a="Jade Phial fylls genom att du interagerar med det heliga vattnet i månskällan strax utanför Starbreeze Village, öster om Dolanaar på Teldrassil.",al={"var fyller man jade phial","hur får man filled jade phial","starbreeze månskällans plats"}},{q="Vem behöver Filled Jade Phial?",a="Corithras Moonrage, en äldre Night Elf som befinner sig i bosättningen Dolanaar, ber resenärer hämta vattnet som en del av ritualuppgifterna Crown of the Earth.",al={"vem vill ha filled jade phial","corithras moonrage uppdragsföremål"}},{q="Varför samlar man månskällvatten i flaskor som denna?",a="Druiderna i Darnassus måste regelbundet fylla på sina viktigaste månskällor. De använder särskilt tillverkade kärl som Jade Phial för att säkert transportera rent vatten från avlägsna källor runt Teldrassil.",al={"varför samla månskällvatten","vad används jade phial till"}},{q="Vilken historia berättar Corithras när man lämnar in den?",a="När Corithras Moonrage får den fyllda flaskan återberättar han de mörka följderna av slaget vid Mount Hyjal och minns förlusten av Night Elfs odödlighet, frigivningen av Illidan Stormrage och Shan'do Malfurion Stormrages oförklarliga försvinnande.",al={"vad berättar corithras","crown of the earth historia"}}},fx={["10c296e8"]={q="Vad är Filled Jade Phial?",a="Filled Jade Phial är ett särskilt tillverkat kärl av jade med heligt vatten från månkällan nära Starbreeze Village. Sådant invigt vatten, genomsyrat av månenergi och naturens nåd, är avgörande för nattalverna när de ska upprätthålla livet i Teldrassil och utföra sina andliga riter.",al={"vad är filled jade phial","filled jade phial bakgrund","filled jade phial"}}},fp="17,191,20.333.0,19.292.0,31.107.0,35.120.0,54.161.0,55.241.0"}
P.entries["item:filled-pure-sample-jar"] = {n="Filled Pure Sample Jar",s="En Filled Pure Sample Jar innehåller ett oförstört exemplar av uråldrigt slem från avlägsna vildmarker. Det ger avgörande grunddata åt gnomforskaren Laris Geardawdle i Ironforge, som studerar hur miljöfördärv förändrar levande materia.",h="En Filled Pure Sample Jar innehåller ett oförstört exemplar av uråldrigt slem från avlägsna vildmarker.",kw={"filled pure sample jar","klibbigt slem","ironforge","laris geardawdle","slem","un'goro crater"},ang={["faction:Alliance"]="Alliansens upptäcktsresande som beger sig till extrema områden som Un'Goro Crater förser forskare i trygghetens Ironforge med viktiga naturhistoriska data.",["race:Gnome"]="Gnomforskare betraktar fältbiologi genom strikt empiriska metoder. Att jämföra förorenat slem från Felwood med rena exemplar från Un'Goro är ett exempel på standardmetoden inom forskning."},sec={{t="På jakt efter oförstört slem",b="När gnomforskaren Laris Geardawdle studerade slem över hela Azeroth upptäckte han ett oroande fenomen: dessa formlösa varelser absorberar och återspeglar den magiska påverkan och miljöfördärvet i sina livsmiljöer. Efter att ha katalogiserat de fördärvade slemmen i Felwood insåg Laris att han behövde en kontrollgrupp för att förstå förruttnelsens natur. En Filled Pure Sample Jar innehåller slem från orörd vildmark, som det uråldriga ekosystemet i Un'Goro Crater, och ger forskare ett oförändrat exemplar att jämföra med sjuka och fördärvade varianter."},{t="Uråldrigt ekosystem",b="Eftersom slem är extremt formbara organismer går det inte att samla in verkligt ”rena” prover nära dagens civilisation, demoniska härdar eller nekromantiska efterverkningar. De klibbiga slemmen i den otämjda sänkan i Un'Goro Crater är fortfarande relativt isolerade från yttre fördärv, vilket gör dem till en idealisk vetenskaplig standard för de vetgiriga i Ironforge."}},faq={{q="Vem vill ha de rena proverna?",a="Laris Geardawdle, en gnomforskare stationerad i Ironforge, vill ha dessa rena burkar för att fortsätta sin pågående studie av Azeroths slempopulationer.",al={"laris geardawdle uppdrag","vem behöver filled pure sample jar","vem vill ha burkarna"}},{q="Varför behöver Laris rent slem i stället för fördärvat slem?",a="Laris insåg att slem snabbt anpassar sig till och absorberar egenskaper från sin omgivning, som det demoniska förruttnandet i Felwood. För att förstå omfattningen av och mekanismen bakom detta fördärv behöver han oförstörda grundprover att jämföra med.",al={"varför rent slem","varför rent prov","syftet med slemanalys"}},{q="Var kan man samla in prover av rent slem?",a="Rena prover samlas in från de klibbiga slemmen i den uråldriga vildmarken i Un'Goro Crater, där växter och djur fortfarande är isolerade från yttre härdar.",al={"var hittar jag rent slem","plats för pure sample jar","var fyller jag rena burkar"}},{q="Vad händer när proverna levereras till Ironforge?",a="Laris använder proverna för laboratorietester av anpassning och miljötålighet. Han belönar äventyrare som vågar sig ut i farliga vildmarker för att hämta dem.",al={"uppdragsbelöning laris","vad gör laris med dem"}}},fx={["630b5cc1"]={q="Vad är en Filled Pure Sample Jar?",a="Det är en lufttät glasbehållare fylld med ett oförorenat slemprov. Till skillnad från slem som förvridits av demoniska krafter eller farsot, utgör ämnet inuti ett rent grundprov på slemvarelsers liv, varsamt bevarat för akademiska studier.",al={"vad är filled pure sample jar","vad betyder pure sample jar","filled pure sample jar"}},e9b3a5fa={q="Varifrån kommer en Filled Pure Sample Jar?",a="De tomma behållarna tillverkas och delas ut av Laris Geardawdle i Ironforge. Du fyller dem själv ute i fält genom att samla trögflytande rester från vilda, oförvridna slemvarelser som frodas i orörda naturområden som Un'Goro Crater.",al={"filled pure sample jar ursprung","varifrån kommer pure samples","vem tillverkade pure sample jar"}}},fp="22,206,30.422.0,18.278.0,29.116.0,54.230.0,41.134.0,57.156.0"}
P.entries["item:filled-red-waterskin"] = {n="Filled Red Waterskin",s="I Tarren Mill ger en brunn klart källvatten till en shamanprövning. Filled Red Waterskin innehåller vatten från byns brunn, bland ruiner som hålls av de Fördömda.",h="I Tarren Mill ger en brunn klart källvatten till en shamanprövning.",kw={"brine","call of water","empty red waterskin","filled red waterskin","sapta","shaman","tarren mill"},ang={["class:Shaman"]="Som shaman prövar du med detta vatten din förmåga att finna och värna den livgivande balansen i världens mest förfallna och sorgsna hörn.",["faction:Horde"]="Som Hordens förkämpe från Kalimdor reser du till Tarren Mill, där de Fördömda kämpar mot Alliansens styrkor i Eastern Kingdoms."},sec={{t="En fyrbåk i fördärvade trakter",b="Brine, en eremit i The Barrens, skickar shamanlärlingar till Tarren Mill för att öva vattenmagi. Resan går till Hillsbrad Foothills, där förfall och döda omger staden. Ändå ger brunnen mitt i staden fortfarande klart källvatten. Brine ser detta rena vatten som ett tecken på uthållighet i ett vanhelgat land. Hon jämför den orörda källan med Warchief Thralls beslutsamhet genom svårigheter. Att hämta vattnet prövar en lärlings respekt för dess renhet, även i fientliga omgivningar."}},faq={{q="Vad finns i Filled Red Waterskin?",a="Filled Red Waterskin innehåller rent källvatten från den offentliga brunnen mitt i Tarren Mill.",al={"vilket vatten finns i den","vatten från tarren mill","innehåll i röd vattenflaska"}},{q="Varför vill Brine ha vatten från Tarren Mill?",a="Brine ser den friska källan i Tarren Mill som ett sällsynt tecken på renhet mitt i de Fördömdas förfall. Hon behöver vattnet för att brygga sapta till en shamans vattenprov.",al={"varför tarren mill","varför brine behöver detta","syftet med röd vattenflaska"}},{q="Hur kan brunnen förbli ren i en stad med odöda?",a="Ingen vet varför källan har förblivit opåverkad av pesten omkring den. Brine säger att de Fördömda i Tarren Mill kanske inte känner igen eller värdesätter den heliga källans renhet mitt ibland dem.",al={"varför är brunnen inte fördärvad","är brunnen i tarren mill förgiftad","helig brunn i tarren mill"}},{q="Hur hänger Thrall ihop med uppdraget?",a="Brine jämför den rena brunnen i en ruinerad stad med Thrall. Han uthärdade stort lidande och fångenskap, och kom sedan ut stark och obefläckad för att leda orcfolket genom mörka tider.",al={"jämförelse med thrall","varför nämns thrall"}}},fx={c913c28c={q="Varifrån kommer Filled Red Waterskin?",a="Du får den genom att ta med en Empty Red Waterskin, som Brine ger dig i The Barrens, hela vägen till Hillsbrad Foothills och hämta rent vatten från bybrunnen i Tarren Mill. Brine minns brunnen som en häpnadsväckande källa med färskt vatten mitt i en Forsaken-bosättning.",al={"filled red waterskin ursprung","var får man filled red waterskin","vem tillverkade filled red waterskin"}}},fp="20,172,26.488.0,40.105.0,43.150.0,47.183.0,37.180.0"}
P.entries["item:filled-tainted-ooze-jar"] = {n="Filled Tainted Ooze Jar",s="En Filled Tainted Ooze Jar innehåller trögflytande, förgiftat slem som skopats direkt från resterna av slemvarelser som strövar omkring i Felwoods fördärvade skogar. Proverna förvaras i särskilda behållare och förs till Ironforge för att stödja radikala teorier om livets ursprung på Azeroth.",h="En Filled Tainted Ooze Jar innehåller trögflytande, förgiftat slem som skopats direkt från resterna av...",kw={"explorers' league","felwood","ironforge","laris geardawdle","royal apothecary society","slem","förgiftat slem"},ang={["faction:Alliance"]="Alliansens spejare håller noga uppsikt över Forsaken's Royal Apothecary Society. Att förstå varför Undercity samlar in slem över hela kontinenterna är en viktig underrättelseprioritet.",["race:Gnome"]="För de gnomiska flyktingarna som bor i Ironforge är banbrytande vetenskapliga bidrag till Explorers' League avgörande för att bevisa sitt värde och återgälda dvärgarnas gästfrihet efter Gnomeregans tragedi."},sec={{t="Slem från den fördärvade skogen",b="De förgiftade slemvarelserna som strövar omkring i norra Kalimdor bär på Felwoods djupa, kvardröjande fördärv. Att samla in dem kräver försiktig förvaring i burkar från gnomiska forskare. De flesta resenärer undviker de giftiga varelserna helt, men proverna ger ovanligt material för naturfilosofi och biologiska studier långt från de härjade skogarna."},{t="Geardawddles storslagna teori",b="Proverna samlas in på uppdrag av Laris Geardawdle, en ambitiös gnomisk forskare som tjänstgör hos Explorers' League i Ironforge. Geardawdle fascineras av hur vanligt förekommande slemvarelser är och har lagt märke till att Forsaken's Royal Apothecary Society också intresserar sig aktivt för dem. Trots akademikernas vanliga skepsis teoretiserar han att slemvarelser kan vara uråldriga utsöndringar med koppling till själva skapelsen av Azeroth. Att säkra proverna är hans försök att vinna anseende bland dvärgiska forskare efter Gnomeregans tragiska fall."}},faq={{q="Vad finns i en Filled Tainted Ooze Jar?",a="Den innehåller ett färskt prov från resterna av en besegrad Tainted Ooze från Felwood, förseglat i en gnomisk insamlingsburk.",al={"vad finns i burken","innehåll i burk med förgiftat slem","vad är förgiftat slem"}},{q="Vem vill ha slemproverna?",a="Laris Geardawdle, en gnomisk forskare som arbetar med Explorers' League i Hall of Explorers i Ironforge, ber om dem för att utveckla sina studier av naturhistoria.",al={"vem tar slemmet","laris geardawdle-uppdrag","vem vill ha förgiftat slem"}},{q="Varför studerar Laris Geardawdle slemvarelser?",a="Geardawdle såg hur Royal Apothecary Society samlade in slemprover och blev fast besluten att först förstå deras natur. Han hyser en okonventionell teori om att slemvarelser är uråldriga utsöndringar med koppling till skapelsen av Azeroth, och hoppas kunna befästa sitt vetenskapliga anseende i Ironforge.",al={"varför studera slem","geardawddles slemteori","varför vill gnomen ha slem"}},{q="Var samlas proverna in?",a="De samlas in i Felwood genom att besegra Tainted Oozes och använda en tom behållarburk på deras kvarlevor.",al={"var hittar man förgiftat slem","plats för burk med förgiftat slem","var fyller jag burken"}}},fx={["297c9c04"]={q="Varifrån kommer en Filled Tainted Ooze Jar, och vem har tillverkat den?",a="Själva burken kommer från gnomforskaren Laris Geardawdle i Ironforge, som tillverkar särskilda tomma glasbehållare för att säkert samla flyktiga prover. Den fylls först när en äventyrare dödar en förorenad slemvarelse i Felwoods förvridna skogar och använder burken för att skrapa upp rester av varelsens geléaktiga kropp.",al={"tainted ooze jar ursprung","vem tillverkade tainted ooze jar","varifrån kommer tainted ooze jars"}}},fp="23,194,27.293.0,25.440.0,41.136.0,29.156.0,39.245.0,34.113.0"}
P.entries["item:filled-tourmaline-phial"] = {n="Filled Tourmaline Phial",s="Den fyllda Filled Tourmaline Phial innehåller förtrollat vatten hämtat från månsjön intill Pools of Arlithrien i södra Teldrassil. Vattnet samlades in på begäran av Corithras Moonrage och ingår i arbetet med att övervaka världsträdets hälsa och balans medan det växer.",h="Den fyllda Filled Tourmaline Phial innehåller förtrollat vatten hämtat från månsjön intill Pools of...",kw={"corithras moonrage","crown of the earth","filled tourmaline phial","gnarlpine","månsjö","pools of arlithrien","teldrassil","tourmaline phial"},ang={["class:Druid"]="För druider berör det kontroversiella arvet efter ärkedruiden Fandral Staghelm direkt att bära phialen. Han drev på för att plantera Teldrassil under Shan'do Stormrages oförklarliga frånvaro.",["race:NightElf"]="Månsjöarnas vatten är en livsviktig andlig livlina för kaldorei, vilket gör korruptionen i de omgivande Gnarlpine-lundarna till ett djupt oroande omen för deras nya hem."},sec={{t="Arlithriens vatten",b="Tourmaline Phial har utformats särskilt för att hämta vatten från månsjön sydost om vägen till Darnassus, vid Pools of Arlithriens stränder. Det har blivit farligt att hämta vatten från denna helgedom på grund av de plötsligt aggressiva Gnarlpine furbolgs, fridfulla grannar som snabbt har förfallit till våldsamt vansinne. Corithras Moonrage ger resenärer i uppdrag att trotsa de fientliga lundarna för att säkra vattnet och försöka diagnostisera den tilltagande korruption som skakar landet."},{t="Teldrassils rötter",b="När phialen återförs till Dolanaar börjar Corithras Moonrage fundera över hur grenverket ovanför kom till. Efter Shan'do Malfurion Stormrages försvinnande samlade ärkedruiden Fandral Staghelm de äldstes cirkel på andra sidan havet i Darkshore för att plantera Teldrassil i hopp om att återfå deras förlorade odödlighet. Vattnet i den ädelstensprydda phialen speglar tillståndet hos detta heliga experiment – en ambition som nu har fläckats av en oförklarlig sjukdom som sprider sig bland både bestar och furbolgs."}},faq={{q="Vad används Filled Tourmaline Phial till?",a="Det är en förtrollad behållare med månsjövatten som Corithras Moonrage har begärt i Dolanaar. Han samlar vatten från månsjöar över hela Teldrassil för att studera hur korruptionen sprider sig och förklara världsträdets historia för nyanlända försvarare.",al={"användning av fylld tourmaline phial","tourmaline phials syfte","varför fylla phialen"}},{q="Var ligger månsjön för Tourmaline Phial?",a="Månsjön ligger sydost om Darnassus huvudport, längs stränderna vid Pools of Arlithrien i sydvästra Teldrassil. Området är hårt omstritt av rasande Gnarlpine furbolgs.",al={"var fyller jag tourmaline phial","månsjön vid pools of arlithrien","arlithriens källa plats"}},{q="Varför anfaller furbolgarna nära månsjön?",a="Gnarlpine furbolgs, som en gång var fredliga björnfolk och levde sida vid sida med nattalverna, har fallit offer för en krypande korruption som drabbar Teldrassil. Deras plötsliga förfall till vettlöst våld är ett av flera symptom som plågar det unga världsträdet.",al={"varför är gnarlpine galna","furbolgers fientlighet vid arlithrien","vansinniga gnarlpine"}},{q="Vem är Corithras Moonrage?",a="Corithras Moonrage är en nattalvsk lärd och väktare stationerad i Dolanaar. Han vägleder unga äventyrare genom riten som kallas Crown of the Earth och lär dem om nattalvernas historia, planteringen av Teldrassil och Malfurion Stormrages försvinnande.",al={"corithras roll","corithras i dolanaar"}}},fx={["360c6167"]={q="Vad är Filled Tourmaline Phial?",a="Det är en tom turmalinflaska fylld med det heliga, självlysande vattnet från månkällan nära Pools of Arlithrien i Teldrassil. Nattalvdruider använder flaskor av olika mineraler för att hämta rent månkällvatten över hela ön. På så vis hålls varje prov åtskilt för deras heliga riter och för att rena landet.",al={"vad är filled tourmaline phial","föremålet filled tourmaline phial"}},b07aae52={q="Varifrån kommer Filled Tourmaline Phial?",a="Själva kärlet får du av Corithras Moonrage i Dolanaar. Du fyller flaskan genom att ta den sydöst om Darnassus till månkällan vid stranden av Pools of Arlithrien och hämta vatten direkt ur källan, mitt bland de strövande, uppretade Gnarlpine-furbolgerna.",al={"filled tourmaline phial ursprung","varifrån kommer filled tourmaline phial"}},c83d83e7={q="Varför vill Corithras Moonrage ha Filled Tourmaline Phial?",a="Corithras Moonrage samlar vatten från Teldrassils olika månkällor för att bedöma och bevara det unga Världsträdets andliga livskraft. När fördärvet kryper in bland grenarna och driver de inhemska Gnarlpine-furbolgerna till vansinne hjälper det druiderna att bevara den heliga balansen och förstå vad som hemsöker deras hem, om de samlar in och undersöker vatten från olika delar av trädet.",al={"varför vill corithras ha flaskan","syftet med filled tourmaline phial","varför samla månkällvatten"}}},fp="23,178,20.410.0,23.408.1,45.257.0,55.170.0,49.195.0,26.256.0"}
P.entries["item:filled-vessel"] = {n="Filled Vessel",s="Filled Vessel innehåller renat vatten från de olika heliga månbrunnarna på Teldrassil. Corithras Moonrage i Dolanaar anförtrodde den åt kurirer, som levererar den till Arch Druid Fandral Staghelm i Darnassus för att hjälpa honom studera världsträdets åkommor.",h="Filled Vessel innehåller renat vatten från de olika heliga månbrunnarna på Teldrassil.",kw={"cenarion enclave","corithras moonrage","crown of the earth","darnassus","fandral staghelm","filled vessel","månbrunnsvatten","teldrassil"},ang={["class:Druid"]="För Cenarion-adepter är leveransen av kärlet deras första officiella ärende åt Arch Druid Fandral Staghelm. Den visar på nära håll hur ekologiskt sårbart Teldrassil är.",["race:NightElf"]="Månbrunnsvattnet står för kaldoreiernas nya hems heliga livsnerver. Där blandas Elunes magi med det obundna världsträdets osäkra tillväxt."},sec={{t="En samling heliga vatten",b="Teldrassil planterades utan välsignelser från de stora aspekterna Alexstrasza och Nozdormu, vilket lämnade dess väldiga grenar sårbara för oväntad korruption, märkliga bestar och vansinniga furbolgstammar. För att övervaka och rena de växande grenarna skickas nattalvsakoliter ut för att samla vattenprover från månbrunnar runt om bland grenarna. Corithras Moonrage samlar de insamlade flaskorna i en enda Filled Vessel och skickar den vidare till huvudstaden. Blandningen är ett viktigt prov på Teldrassils livskraft för Arch Druid Fandral Staghelm, som arbetar outtröttligt i Cenarion Enclave för att finna ett botemedel mot det stora trädets utbredda brister."}},faq={{q="Vad finns i Filled Vessel?",a="Kärlet innehåller vatten från flera månbrunnar utspridda över Teldrassil, samlat i ett enda kärl av Corithras Moonrage i Dolanaar.",al={"kärlets innehåll","vilket vatten är det här","vad finns i kärlet"}},{q="Vem behöver Filled Vessel?",a="Filled Vessel förs till Arch Druid Fandral Staghelm, som håller till högst upp i Cenarion Enclave i Darnassus.",al={"vem ska jag lämna filled vessel till","vart ska kärlet","lämna in filled vessel"}},{q="Varför behöver Fandral Staghelm vattenproverna?",a="Teldrassil saknar de traditionella drakaspekternas välsignelser, vilket gör att märklig korruption, aggressiva vilddjur och galna furbolger plågar dess grenar. Staghelm studerar det blandade vattnet för att diagnostisera trädets brister och finna ett botemedel mot dess plågor.",al={"varför staghelm vill ha vatten","syftet med staghelms månbrunnsvatten","varför samla månbrunnsvatten"}},{q="Vem förberedde kärlet?",a="Corithras Moonrage, en nattalv stationerad i Dolanaar, häller flaskorna som unga äventyrare samlat in i kärlet innan han skickar det till Darnassus.",al={"vem gjorde filled vessel","vem lämnar filled vessel","corithras filled vessel"}}},fp="13,201,29.541.0,33.132.0,28.103.0,51.251.0,24.135.0"}
P.entries["item:final-clue-to-sanders-treasure"] = {n="Final Clue to Sanders' Treasure",s="Längs Westfalls kust pekar Captain Sanders sista anvisningar ut mot havet. En lapp i en gammal kruka leder skattletare västerut mot hans begravda skatt.",h="Längs Westfalls kust pekar Captain Sanders sista anvisningar ut mot havet.",kw={"captain sanders","kista","ledtråd","pirat","skatt","westfall","whiskeykruka"},ang={["class:Rogue"]="Som rogue kan du följa Captain Sanders anvisningar ut till havs och leta efter skatter längs Westfalls stränder, bortom Defias fickor."},sec={{t="En sjömans sista ord",b="Captain Sanders lämnade sina sista anvisningar i en gammal whiskeykruka vid Westfalls kust. Piraten hade spritt kryptiska lappar längs strandlinjen, och den här fullbordar spåret. Från krukan leder anvisningarna rakt västerut över havet. Följ dem genom bränningarna till en enslig klippa ute till havs, där hans järnbeslagna sjökista ligger."}},faq={{q="Vad står det på den sista ledtråden?",a="Lappen visar västerut från whiskeykrukan och ut till havs, där en liten ö rymmer skattkistan.",al={"ledtrådstext","vad står det på ledtråden","sanders anvisningar"}},{q="Var hittades den här ledtråden?",a="Ledtråden låg i en gammal whiskeykruka vid Westfalls kust. Den var det tredje steget i Captain Sanders ledtrådsspår.",al={"var hittar jag sista ledtråden","gammal krukas plats","ledtrådens plats"}},{q="Vem var Captain Sanders?",a="Captain Sanders var en pirat vars tillhörigheter och skattkartor spolades upp längs Westfalls kust. Före sin död lämnade han gömda lappar och markörer över landsbygden som leder till hans skattgömma.",al={"vem är captain sanders","sanders piratberättelse","vem gömde skatten"}},{q="Vart leder den här ledtråden till slut?",a="Lappen leder dig västerut från Westfalls kust till en enslig ö, där Captain Sanders sjökista står.",al={"var finns kistan","sanders ö","öns plats"}}},fx={ed69490f={q="Vad är Final Clue to Sanders' Treasure?",a="Det är en väderbiten papperslapp som plockats upp ur kapten Sanders gamla whiskyflaska längs Westfalls kust. Anteckningen luktar svagt av sprit och bläcket har runnit av fukten. Den utgör kulmen på en skattjakt som den avlidne piratkaptenen ordnade och ger de sista anvisningarna för att hitta hans nedgrävda skatt.",al={"vad är final clue to sanders treasure","vad är den sista ledtråden","vad är det här för ledtråd"}},["0f7c35ef"]={q="Varifrån kommer Final Clue to Sanders' Treasure, och vem har skrivit den?",a="Ledtråden skrevs av kapten Sanders själv och förseglades i en gammal flaska intill den ensamma väderkvarnen på Westfalls havsklippor. Piratkaptenen gömde den som det sista steget i en invecklad led längs kusten, så att bara den som var tillräckligt ihärdig för att följa hans utspridda markörer skulle hitta hans gömda byte.",al={"vem skrev final clue","varifrån kommer final clue","final clue ursprung"}},["9095866c"]={q="Varför vill någon ha Final Clue to Sanders' Treasure?",a="Den som följer Captain Sanders spår söker hans sedan länge försvunna piratskatt. Tidigare ledtrådar förde från ett landmärke vid kusten till ett annat, men den här sista lappen visar uttryckligen att man ska bortom Westfalls stränder och ut på öppet hav, rakt mot den ensliga ön där kaptenens kista väntar.",al={"varför vill någon ha sista ledtråden","varför hitta sista ledtråden","sista ledtrådens syfte"}}},fp="31,145,24.331.0,29.124.0,26.119.0,24.195.0,37.107.0"}
P.entries["item:fine-crab-chunks"] = {n="Fine Crab Chunks",s="Fine Crab Chunks är de finaste köttbitarna från kustlevande kräftdjur som strövar längs Darkshores stränder. De är mycket uppskattade för sin mångsidighet i matlagningen och eftertraktade av lokalbefolkningen längs kusten och hungriga fiskare som vill laga en mängd olika skaldjursrätter.",h="Fine Crab Chunks är de finaste köttbitarna från kustlevande kräftdjur som strövar längs Darkshores stränder.",kw={"auberdine","krabba","darkshore","encrusted tide crawler","fine crab chunks","havets frukter","gubber blump","reef crawler"},ang={["faction:Alliance"]="Att förse invånarna vid bryggorna i Auberdine med mat hjälper till att hålla Alliansens utsatta utpost vid liv bland Darkshores dystra faror.",["profession:Cooking"]="Alla blivande kockar vid kusten kommer att uppskatta Gubber Blumps encyklopediska passion för krabba, från soppor, sallader och pepparkryddningar till regionala delikatesser som Ironforge surprise crab."},sec={{t="Havets frukter",b="Darkshores dimmiga, karga stränder kryllar av småkrypande kräftdjur, särskilt Reef Crawlers och Encrusted Tide Crawlers. Många resenärer ser de bepansrade strandströvarna som skadedjur eller faror längs vattenlinjen, men driftiga finsmakare anser att köttet hör till kustens främsta läckerheter. De utvalda bitarna från dessa varelser är saftiga och möra och passar till nästan alla tänkbara tillagningssätt, från kokning och grillning till fritering och mustiga grytor."}},faq={{q="Vilka varelser ger Fine Crab Chunks?",a="De samlas in från Reef Crawlers och Encrusted Tide Crawlers som strövar längs Darkshores klippiga stränder och tidvattengrunda vatten.",al={"var får man fine crab chunks","vilka krabbor ger köttbitar","källa till krabbkött"}},{q="Vem vill ha Fine Crab Chunks i Darkshore?",a="Gubber Blump, en entusiastisk fiskare som håller till vid bryggorna i Auberdine, letar efter dessa utvalda köttbitar. Han älskar skaldjur och uppskattar dem för sitt stora utbud av hemlagade krabbrätter.",al={"vem behöver fine crab chunks","vem tar emot krabbkött","gubber blump krabba"}},{q="Kan du laga riktiga måltider av dem?",a="De här särskilda råa köttbitarna samlas främst in åt Gubber Blump och används inte som ingrediens i något särskilt recept. Den lokala matlagningstraditionen ser dock krabbkött som mycket mångsidigt: det passar att baka, grilla, koka, steka, fritera och blanda i sallader eller grytor.",al={"kan man tillaga fine crab chunks","vad kan man laga med fine crab chunks","krabbrecept"}}},fx={a1097ca6={q="Vad är Fine Crab Chunks?",a="Fine Crab Chunks är de bästa köttbitarna från de kraftiga krabborna längs Darkshores dimhöljda kust. De uppskattas för sin mörhet och mångsidighet, och lokala finsmakare ser dem som havets verkliga gåva, lämplig för nästan vilken tillagning som helst.",al={"vad är fina krabbköttbitar","fina krabbköttbitar i berättelsen","vad är fint krabbkött"}},["09afcf23"]={q="Var kommer Fine Crab Chunks ifrån?",a="De här läckerbitarna tas direkt från de vilda skaldjur som strövar längs Darkshores kust, särskilt Reef Crawlers och Encrusted Tide Crawlers. De tillverkas inte av dödliga händer, utan styckas färska från varelserna som trivs i det kalla bränningarna.",al={"var kommer fina krabbköttbitar ifrån","fina krabbköttbitars ursprung"}},["1943045a"]={q="Varför vill Gubber Blump ha Fine Crab Chunks?",a="Gubber Blump, en excentrisk fiskare vid kajen i Auberdine, är fullständigt besatt av krabbkött. Han är strandsatt med sitt fiskespö och förlitar sig på resenärer som samlar färska bitar, så att han kan laga en oändlig mängd krabbrätter, från bakade och grillade rätter till krabbsallader och grytor.",al={"varför vill gubber ha krabbköttbitar","vem vill ha fina krabbköttbitar","varför samla fina krabbköttbitar"}}},fp="16,138,16.214.0,38.116.0,40.96.0,40.177.0"}
P.entries["item:fine-moonstalker-pelt"] = {n="Fine Moonstalker Pelt",s="En Fine Moonstalker Pelt är det tjocka, orörda skinnet från de mest fullvuxna rovgiriga moonstalkers som strövar omkring i södra Darkshore. Terenthis i Auberdine använder dessa dyrbara pälsar för att väva en förtrollad mantel som låter sökare obemärkt ta sig förbi skogens fientliga bestar.",h="En Fine Moonstalker Pelt är det tjocka, orörda skinnet från de mest fullvuxna rovgiriga moonstalkers som...",kw={"auberdine","darkshore","fine moonstalker pelt","hona","moonstalker","hane","terenthis","volcor","wildbend river"},ang={["class:Hunter"]="Att spåra hanarna och honorna nära Wildbend River sätter en jägares spårningsförmåga på prov mot några av de grymmaste rovdjuren i Kalimdors kustområden.",["race:NightElf"]="Night elves vördar moonstalkers heliga vildhet och tar bara deras skinn när nöden är stor, för att hjälpa fallna fränder som Volcor."},sec={{t="Flådda flockledare",b="Vanliga moonstalkers strövar genom Darkshores dimhöljda skogar, men bara äldre moonstalker-hanar och moonstalker-honor har tillräckligt täta och friska pälsar för att ge ett fint skinn. Dessa mäktiga vildkatter hävdar revir längs Wildbend River och längre söderut mot Ashenvales gränser, där de jagar med dödligt tålamod."},{t="En mantel av förklädnad",b="Att samla in dessa skinn är ingen troféjakt. Terenthis ber om fem hela skinn för att skapa ett förtrollat plagg åt resande som söker efter den försvunne Night Elf Volcor. När skinnen vävs samman och binds med naturmagi bildar de en kamouflagekappa som omsluter bäraren i en illusion och dämpar dennes närvaro för Darkshores vilda djur, så länge bäraren avstår från aggressiva handlingar."}},faq={{q="Vilka varelser ger Fine Moonstalker Pelt?",a="Bara de fullvuxna ledarna för moonstalker-flockarna ger dessa skinn, närmare bestämt moonstalker-hanar och moonstalker-honor. Yngre eller vanliga moonstalkers har inte skinn av tillräcklig kvalitet.",al={"vad ger fine moonstalker pelt","var får man moonstalker-skinn","vilka katter har skinn"}},{q="Var finns de fullvuxna moonstalkers?",a="Dessa väldiga vildkatter håller till i södra Darkshore, särskilt nära Wildbend Rivers stränder och längre söderut längs skogsvägen mot Ashenvale.",al={"var finns hanarna och honorna","moonstalker-hane plats","moonstalker-hona plats"}},{q="Varför behöver Terenthis skinnen?",a="Terenthis använder fem av skinnen för att skapa en förtrollad mantel. Manteln är laddad med magi som ska dölja en räddare för rovdjur under sökandet efter den försvunne Night Elf Volcor.",al={"vad används skinnen till","varför samla moonstalker-skinn","terenthis skinnuppdrag"}},{q="Gör den färdiga manteln dig helt osynlig?",a="Manteln skapar en skör naturlig illusion som håller bestar på avstånd. Terenthis varnar för att allt utöver att tala med andra kommer att störa förtrollningen och skingra förklädnaden.",al={"hur fungerar manteln","mantelns illusionsbegränsningar","vad bryter mantelns smygande"}}},fx={["399f6830"]={q="Vad är en Fine Moonstalker Pelt?",a="En Fine Moonstalker Pelt är det bästa skinnet från de fullvuxna moonstalkerhanar och -honor som strövar omkring i Darkshores vildmarker. Dessa mäktiga nattsaberkatter har tjock, smidig päls som kan hålla kvar svaga naturförhäxningar, vilket gör deras skinn betydligt mer värdefulla och slitstarka än yngre djurs sträva päls.",al={"fine moonstalker pelt","vad är moonstalker-päls","fin päls"}},e53e751f={q="Var kommer en Fine Moonstalker Pelt ifrån?",a="Skinnen kommer från de största fullvuxna moonstalkers som jagar längs Darkshores kuster och i skogarna, särskilt nära Wildbend River och längre söderut mot gränsen till Ashenvale. Endast fullvuxna moonstalkerhanar och -honor ger skinn som är tjocka och friska nog att räknas som fina pälsar.",al={"var hittar man fin moonstalker-päls","moonstalker-pälsens ursprung","vem släpper fin moonstalker-päls"}}},fp="21,221,25.309.0,20.277.1,45.128.0,43.119.0,36.163.0,54.174.0"}
P.entries["item:fire-tar"] = {n="Fire Tar",s="I östra delen av The Barrens bär Razormane-spellcasters på Fire Tar. Hordens shamaner använder det för att brygga Fire Sapta, som låter dem kommunicera med eldsandar.",h="I östra delen av The Barrens bär Razormane-spellcasters på Fire Tar.",kw={"call of fire","fire sapta","fire tar","quilboar","razormane","schamanens totem","telf joolam","the barrens"},ang={["class:Shaman"]="Som shaman är det en viktig övergångsrit att samla Fire Tar. Du söker elementär resonans i den vida världen och använder den sedan för att brygga Fire Sapta och förtjäna din Fire Totem.",["faction:Horde"]="Som medlem av Horden korsar du Southfury River från Durotar in i The Barrens för att samla Fire Tar. Där ställs du mot de aggressiva Razormane-stammarna."},sec={{t="En brygd från Razormane",b="Razormane-geomancers, mystics och thornweavers bär på Fire Tar. Quilboar använder det flammbundna ämnet i sin hårda magi och sina ritualer. Shamaninstruktörer värdesätter det som en världslig reagent som hjälper dödligas sinnen att nå elementens råa vrede."},{t="Vägen till Fire Totem",b="Unga orc- och trollshamaner reser till Telf Joolam, högt uppe bland Durotars klippor, för att smida sina Fire Totems. Telf ber dem om en Reagent Pouch som tagits från Burning Blade-kultister och Fire Tar som samlats in från Razormane. Han brygger de två ingredienserna till en Fire Sapta. När en shaman dricker den kan hen uppfatta eldsandarna som väntar på de närliggande topparna."}},faq={{q="Vad används Fire Tar till?",a="Shamaner tar med sig Fire Tar till Telf Joolam i Durotar, där han brygger det med reagents från Burning Blade till en Fire Sapta. Brygden låter en shaman se och kommunicera med eldsandar för att förtjäna en Fire Totem.",al={"användning av fire tar","vad gör fire tar","varför behöver jag fire tar"}},{q="Vem bär på Fire Tar?",a="Razormane-quilboar som kan besvärjelser bär på Fire Tar i östra delen av The Barrens. Bland dem finns Razormane Geomancers, Mystics, Thornweavers och Water Seekers.",al={"vem släpper fire tar","fiender med fire tar","var hittar man fire tar"}},{q="Varför behöver schamaner ingredienser från fientliga magiker?",a="Saptas behöver fysiska beståndsdelar som mättats med motsvarande element. Razormane-besvärjare och Burning Blade-warlocks kanaliserar hetta och förödande lågor, så deras vardagliga material bär på den eldiga essens som behövs för att väcka en shamans elementseende.",al={"varför quilboars tjära","varför warlocks och quilboars"}},{q="Var brygger Telf Joolam Fire Sapta?",a="Telf Joolam brygger Fire Sapta på en hög klippa med utsikt över Durotars klippor, nära stigen mellan Razor Hill och The Barrens. Han lär invigda att balansera lågornas destruktiva och skapande natur.",al={"var finns telf joolam","lämna in fire tar"}}},fx={["1e4fc5f4"]={q="Vad är Fire Tar?",a="Fire Tar är ett flyktigt, elementärt ämne som bärs av besvärjare bland Razormane quilboar i Barrens. Denna stickande beck är genomsyrad av eldens grundläggande väsen och uppskattas av utövare av elementmagi för sin naturliga samhörighet med lågor.",al={"vad är fire tar","information om fire tar","beskriv fire tar"}},["006bd002"]={q="Var kommer Fire Tar ifrån, och vem tillverkar det?",a="Fire Tar samlas in från Razormane quilboar-besvärjarna som bor i östra Barrens, däribland deras geomancers, mystics och thornweavers. Telf Joolam ber noviser att ta med det som en ingrediens till hans Fire Sapta.",al={"vem tillverkar fire tar","fire tars ursprung","var kommer fire tar ifrån"}}},fp="8,154,29.252.0,26.348.0,26.202.0,21.148.0,61.246.0,43.200.0"}
P.entries["item:fizzle-s-claw"] = {n="Fizzle's Claw",s="I Thunder Ridge förs Fizzle Darkstorms klo till Razor Hill som bevis på hans död. Den goblinske häxmästaren var en farlig konspiratör inom Burning Blade.",h="I Thunder Ridge förs Fizzle Darkstorms klo till Razor Hill som bevis på hans död.",kw={"burning blade","mörka stormar","durotar","fizzle darkstorm","fizzle's claw","orgnil soulscar","razor hill","thunder ridge"},ang={["class:Warlock"]="Som häxmästare vet du att Fizzle Darkstorm använde kaoskonster i Burning Blades tjänst och vände sina talanger mot Horden.",["faction:Horde"]="Som medlem av Horden hjälper du till att rena Durotar från skuggkulter som hotar den unga nationens säkerhet när du visar upp Fizzles klo i Razor Hill."},sec={{t="En grym trofé",b="Orgnil Soulscar skickade styrkor för att rensa bort skuggkulter som hotade orchernas hemland. Han pekade ut Fizzle Darkstorm som en anstiftare som spred fördärv i Thunder Ridge. Klofragmentet ger Hordens befälhavare bevis på att häxmästaren, som verkade under Burning Blades baner, har dödats."},{t="Hotet i Thunder Ridge",b="Thunder Ridge ligger strax nordväst om Razor Hill, tillräckligt nära för att hota de omkringliggande områdena. Hordens spejare förde Fizzles klo tillbaka till Razor Hill och bekräftade att hans ritualer och försök att etablera ett fäste för Burning Blade hade stoppats."}},faq={{q="Vem tillhör den här handen?",a="Klon tillhörde Fizzle Darkstorm, en goblinsk häxmästare med anknytning till Burning Blade.",al={"vem är fizzle","fizzle darkstorm","handens ägare"}},{q="Varför vill Orgnil Soulscar ha Fizzle's Claw?",a="Orgnil Soulscar vill ha bevis på att Fizzle är död. Burning Blade verkar i hemlighet, och klon bekräftar att detta hot mot Durotar har undanröjts.",al={"varför behövs handen","orgnil soulscar hand","bevis på död"}},{q="Var hittades handen?",a="Klon togs från Fizzle Darkstorm vid hans läger i Thunder Ridge, nordväst om Razor Hill i Durotar.",al={"fizzles plats","var är fizzle","hand från thunder ridge"}},{q="Vad gör Burning Blade i Durotar?",a="Burning Blade försöker undergräva orchernas nya hemland med demoniskt fördärv, mörk trolldom och inbördes oro. Häxmästare som Fizzle upprättar dolda läger för att sprida kaos i regionen.",al={"burning blade i durotar","varför finns kultister i thunder ridge"}}},fx={["0fb0af8e"]={q="Vad är Fizzle's Claw?",a="Fizzle's Claw är den avhuggna handen från Fizzle Darkstorm, en förrädisk goblinhäxmästare som är allierad med sekten Burning Blade. Den fungerar som ett makabert fysiskt bevis på hans död för Orgnil Soulscar i Razor Hill och bekräftar att sektens ledare, som ställde till problem i Thunder Ridge, har oskadliggjorts för gott.",al={"vad är fizzles klo","föremålet fizzles claw","vem är fizzle claw"}}},fp="13,153,13.293.0,27.246.0,29.90.0,44.151.0,25.106.0,43.199.0"}
P.entries["item:flagongut-s-fossil"] = {n="Flagongut's Fossil",s="Flagongut's Fossil är ett uråldrigt fynd från utgrävningsplatserna i Wetlands. Det anförtroddes åt dvärgarnas Explorers' League och rymmer dolda hemligheter som Archaeologist Flagongut försöker tyda med hjälp av en mystisk relik kallad Stone of Relu.",h="Flagongut's Fossil är ett uråldrigt fynd från utgrävningsplatserna i Wetlands.",kw={"utgrävning","explorers' league","flagongut","fossil","relu","stone of relu","wetlands","whelgar"},ang={["faction:Alliance"]="Om man säkrar föremål från Whelgar's förstörda utgrävningsplats hindrar man vilddjur från att förstöra värdefull historia och fientliga styrkor från att plundra den i träsket.",["race:Dwarf"]="För dvärgarnas utforskare är fossiler som Flagongut's inga rena kuriositeter. De är fysiska band till forntiden, som Explorers' League har vigt sig åt att gräva fram."},sec={{t="Utgrävning och studier",b="Den här uråldriga fossilen grävdes fram under dvärgarnas expeditioner i Khaz Modan och är mer än bara förstenad sten. Archaeologist Flagongut tror att den rymmer bortglömda krafter knutna till världens äldsta historia, jämförbara med fynd på andra sidan havet i Darkshore. Under regionala studier förvarades fossilen hos Prospector Whelgar på hans utgrävningsplats i Wetlands södra kullar."},{t="Att låsa upp reliken",b="När Flagongut upptäckte Stone of Relu insåg han att den var nyckeln som krävdes för att tyda fossilens hemligheter. Men stenen förlorades efter ett bakhåll av fläckiga rovfåglar på vägen. För att äntligen låsa upp fyndets hemligheter behöver Flagongut äventyrare som hämtar fossilen från Whelgars utgrävning och återfår stenen som svalts av djuren i Wetlands."}},faq={{q="Vad är Flagongut's Fossil?",a="Det är ett uråldrigt arkeologiskt fynd från Wetlands, som dvärgarnas Explorers' League förvarar för att analysera och avslöja hemligheter från världens forntid.",al={"vad är fossilen","flagonguts fossil och bakgrund"}},{q="Var finns fossilen?",a="Den finns i grottan högst upp vid Whelgar's Excavation Site, bland Wetlands södra berg, bevakad av de fläckiga rovfåglar som övertog utgrävningen.",al={"fossilens plats","var finns flagonguts fossil","whelgars fossilgrotta"}},{q="Varför vill Flagongut ha den tillbaka?",a="Flagongut tror att han kan tyda fossilens dolda magiska hemligheter om den kombineras med Stone of Relu, och jämföra dess egenskaper med liknande fynd i Kalimdor.",al={"varför vill flagongut ha den","vad ska flagongut göra med den"}},{q="Hur hänger den ihop med Darkshore?",a="Flagongut ser en koppling mellan fyndet i Wetlands och fossilen som Prospector Remtravel hittade på andra sidan havet i Darkshore. Han tror att Stone of Relu kan låsa upp kraften i båda relikerna.",al={"koppling till darkshore","remtravels fossil"}}},fp="18,184,20.296.0,19.280.1,27.151.0,28.155.0,36.144.0,33.183.0"}
P.entries["item:flatland-cougar-femur"] = {n="Flatland Cougar Femur",s="Ett Flatland Cougar Femur är ett tätt lårben från de rovdjurslika pumor som stryker omkring i Mulgore gyllene gräs. Det är en viktig ingrediens i en traditionell taurenkur mot dödliga, giftiga infektioner.",h="Ett Flatland Cougar Femur är ett tätt lårben från de rovdjurslika pumor som stryker omkring i Mulgore gyllene...",kw={"bloodhoof village","lårben","flatland cougar","maur raincaller","mazzranache","mulgore"},ang={["class:Hunter"]="Att spåra Flatland Cougar kräver skarp blick bland Mulgore vajande snår och prövar en ung jägares förmåga att fälla ett rovdjur utan att skada bytet.",["race:Tauren"]="För Mulgore tauren är jakten på Flatland Cougar både ett prov på vaksamhet och en källa till viktiga material för traditionella kurer från slätterna."},sec={{t="En kur mot ett giftigt bett",b="Flatland Cougar är ett av Mulgore farligaste inhemska rovdjur. Den smälter in bland de torra snåren tills den kastar sig över ett ovetande byte. Jägare tar ofta pumaskinn och klor till läderarbete och troféer, men de kraftiga, märgrika benen har också ett praktiskt värde inom den lokala läkekonsten. När Maur Raincaller, en tauren från Bloodhoof Village, fick ett giftigt sår av den monstruösa rosa stridern Mazzranache, bad han brådskande om ett lårben från en puma och delar från andra lokala bestar. Benet krossas eller kokas för att utvinna dess verksamma ämnen. De blir till ett motgift som kan dra feber och dödligt gift ur ett varigt bett."}},faq={{q="Vad används Flatland Cougar Femur till?",a="Maur Raincaller använder lårbenet för att brygga en nödkur i Bloodhoof Village. Den ökända plainstridern Mazzranache bet honom, och han behöver märgen och benet för att blanda ett motgift innan varelsens starka gift dödar honom.",al={"vad pumans lårben används till","vad är det här benet till","uppdrag med lårben"}},{q="Var får du tag på Flatland Cougar Femur?",a="Du får det från Flatland Cougar som strövar omkring på de centrala och södra slätterna i Mulgore. De håller ofta till nära sluttningarna och stryker genom de höga gräsen kring Bloodhoof Village.",al={"var hittar man lårben","var pumans lårben finns","vilka fiender släpper det"}},{q="Varför behöver Maur Raincaller just ett pumaben?",a="Taurenörtläkare och schamaner använder ofta täta ben och märg från rovdjur i traditionella salvor och tinkturer. Man tror att Mulgore främsta rovdjurs styrka och tålighet ger den återställande grund som behövs för att neutralisera starka gifter.",al={"varför pumaben","varför lårben"}},{q="Vem är Maur Raincaller?",a="Maur Raincaller är en tauren som bor i Bloodhoof Village. Efter att ha vandrat över slätterna råkade han ut för Mazzranache, en legendarisk strider som hans farfar en gång slogs mot. Han kom undan med knapp nöd, men hade ett infekterat, giftigt bett i axeln.",al={"maur raincaller","vem behöver benet"}}},fx={cc87b9fc={q="Vad är ett Flatland Cougar Femur?",a="Det är ett kraftigt ben från ett bakben, taget från de rovgiriga flatland cougars som strövar på Mulgore-slätterna. Sådana täta och tåliga ben efterfrågas ofta av stammarnas helare och schamaner för att bereda traditionella salvor, omslag och läkemedel.",al={"vad är flatland cougar femur","föremålet flatland cougar femur","vad är ett cougar-lårben"}},["47eeaceb"]={q="Var kommer ett Flatland Cougar Femur ifrån?",a="Det tas direkt från flatland cougars, de slanka rovdjur som hör hemma på Mulgore-gräsmarkerna. Till skillnad från tillverkade redskap eller brygder är det här en rå, naturlig trofé som jägare samlar in när de spårar vilddjuren över de vidsträckta slätterna.",al={"flatland cougar femurs ursprung","var hittar man flatland cougar femur","vem släpper cougar-lårben"}}},fp="21,163,28.582.0,43.223.0,44.192.0,58.258.0,23.217.0"}
P.entries["item:flatland-prowler-claw"] = {n="Flatland Prowler Claw",s="En Flatland Prowler Claw tas från de farliga kattdjursrovdjur som stryker omkring på Mulgore grässlätter. För blivande jägare är insamlingen av dessa klor en traditionell övergångsrit som visar list och kampvilja inför Thunder Bluffs äldste.",h="En Flatland Prowler Claw tas från de farliga kattdjursrovdjur som stryker omkring på Mulgore grässlätter.",kw={"flatland prowler","flatland prowler claw","hunter rise","melor stonehoof","mulgore","skorn whitecloud","jägarens väg","thunder bluff"},ang={["class:Hunter"]="Att fälla smygande prowlers prövar jägarens uppmärksamhet i fält. Därför blir klorna en symbol för den respekt som förtjänats bland skarpskyttarna på Thunder Bluffs Hunter Rise.",["race:Tauren"]="För tauren är jakten en hedervärd andlig tradition, och att visa upp klorna från ett listigt slättrovdjur markerar en invigd jägares första steg mot att tjäna stammen som spårare."},sec={{t="Ett bevis för jägaren",b="Flatland prowlers hör till de listigaste och mest revirhävdande rovdjuren som strövar över Mulgore vindpinade slätter. De är snabba på tassarna och skickliga på att överraska byten i det höga gräset. Därför utgör de ett verkligt hot mot resande och ett värdigt prov för unga jägare. Att samla deras vassa klor är inte bara en överlevnadsuppgift, utan en erkänd tradition. Skorn Whitecloud råder lovande vandrare att ta dessa troféer och visa upp dem för Melor Stonehoof på toppen av Thunder Bluffs Hunter Rise. Det bevisar att de har den beslutsamhet och fältvana som krävs för att följa jägarens väg."}},faq={{q="Vad används Flatland Prowler Claws till?",a="De är ett konkret bevis på skicklighet och mod. Unga jägare tar med sig fyra sådana klor till Melor Stonehoof vid Hunter Rise i Thunder Bluff för att visa att de är redo att följa jägarens väg.",al={"användning av prowler claw","varför samla prowler claws","klor för jägarens väg"}},{q="Vem ber dig samla in dem?",a="Den äldre jägaren Skorn Whitecloud uppmanar lovande spårare att samla klor från Mulgore prowlers som bevis innan de presenterar sig för Melor Stonehoof.",al={"vem vill ha prowler claws","uppdragsgivare för prowler claws"}},{q="Varför är flatland prowlers ett lämpligt byte?",a="Flatland prowlers är tåliga, smygande och listiga köttätare som hör hemma på Mulgore slätter. Att spåra upp och besegra sådana vaksamma rovdjur visar att en blivande jägare har det tålamod och de stridsinstinkter som tauren-traditionen kräver.",al={"varför flatland prowlers","är prowlers farliga"}}},fx={cc11ac90={q="Vad är en Flatland Prowler Claw?",a="Det är en klo från en flatland prowler, en av de rovgiriga vildkatter som strövar på Mulgore-gräsmarkerna. Bland taurenjägare är dessa klor ett påtagligt bevis på en ung jägares list, tålamod och växande förmåga att spåra byten.",al={"flatland prowler claw","vad är prowler claw"}},a7640831={q="Var kommer Flatland Prowler Claws ifrån?",a="Klorna kommer direkt från de rovgiriga flatland prowlers som jagar på Mulgore-gräsmarkerna där vinden sveper fram. De tillverkas inte, utan måste tas loss varsamt av en jägare efter att ha spårat upp och besegrat de smidiga bestarna i vildmarken.",al={"var hittar man prowler claws","hur får man tag på prowler claws"}},b4c8d82b={q="Varför vill någon ha Flatland Prowler Claws?",a="Skorn Whitecloud skickar blivande vandrare på jakt efter klorna för att bevisa sitt värde för Melor Stonehoof på Hunter's Rise i Thunder Bluff. Jakt är en av de högsta hedersbetygelserna i taurenkulturen, och klor från så tåliga och listiga rovdjur visar att du har den gryende skicklighet och anda som krävs för att följa jägarens väg.",al={"varför samla prowler claws","vem behöver prowler claws","varför vill melor stonehoof ha klor"}}},fp="21,166,16.422.0,41.189.0,29.129.0,52.196.0"}
P.entries["item:foreman-s-blackjack"] = {n="Foreman's Blackjack",s="Foreman's Blackjack håller peonerna i arbete i Durotars Valley of Trials. Förmän använder den läderklädda käppen för att väcka arbetare som somnar under Hordens tidiga byggnadsarbete.",h="Foreman's Blackjack håller peonerna i arbete i Durotars Valley of Trials.",kw={"klubba","durotar","foreman's blackjack","lata peoner","peon","thazzril","valley of trials"},ang={["faction:Horde"]="Blackjacken speglar den praktiska insats som krävs för att tämja Durotar, där det krävs att varje arbetare arbetar utan uppehåll för att bosätta sig i ett hårt land.",["race:Orc"]="För unga orcher som träder in i Valley of Trials ger blackjacken en tidig lektion i Hordens hierarki: de som saknar en krigares styrka eller mod förvisas till arbete och hålls i schack med våld."},sec={{t="Ett verktyg för orciskt arbete",b="Durotars karga öken kräver lager av timmer till Hordens nya hem. I Valley of Trials faller arbetet på peonerna, och Foreman Thazz'ril håller arbetslagen igång med Foreman's Blackjack. Den viktade klubban ger arbetare som slumrar under dalens skuggande träd en omskakande väckning, inte ett dödligt slag. Livet som peon i den nya Horden innebär utmattande, otacksamt arbete under järnhård kontroll."}},faq={{q="Vad används Foreman's Blackjack till?",a="Överordnade ger blackjacken till unga äventyrare för att tillrättavisa sovande peoner i Valley of Trials. Ett slag rycker en slumrande peon vaken och skickar genast tillbaka dem till att hugga och bära ved.",al={"användning av klubban","varför använda klubban","peonklubba"}},{q="Vem äger den här klubban?",a="Foreman Thazz'ril äger blackjacken. Arbetsförmannen är stationerad i Valley of Trials, där han övervakar insamlingen av råvirke till den unga orchiska bosättningen.",al={"vem ger klubban","vem äger foreman's blackjack"}},{q="Varför somnar peonerna hela tiden på jobbet?",a="Orchiska peoner arbetar outtröttliga, utmattande skift med att samla ved under Durotars hårda sol. När tröttheten tar över slumrar de ofta utan tillåtelse under dalens glesa träd.",al={"varför är peoner lata","lata peoner som sover"}},{q="Får jag behålla klubban när jag är klar med uppgiften?",a="Nej. Den överordnade kräver att verktyget lämnas tillbaka omedelbart efter att de arbetsovilliga har tillrättavisats. Det hålls till hands för arbetsförmän som upprätthåller arbetskvoterna.",al={"behålla klubban","får jag behålla foreman's blackjack"}}},fx={["4e7ef009"]={q="Vad är Foreman's Blackjack?",a="Foreman's Blackjack är en tung batong klädd i läder som Foreman Thazz'ril bär i Valley of Trials. Det är ett oansenligt redskap för disciplin, utformat för att inte åsamka svåra krigsskador, utan ge ett skarpt, svidande slag som får sovande arbetare på benen igen.",al={"vad är blackjacken","föremålet foreman's blackjack","vad är foreman's blackjack"}},["9e33a4a7"]={q="Varför vill Foreman Thazz'ril ha tillbaka sin blackjack?",a="Foreman Thazz'ril förlitar sig på sin blackjack för att hålla ordning på arbetslagen i Valley of Trials. Utan den har han få möjligheter att tvinga de utmattade, omotiverade peons att fortsätta hugga och släpa timmer åt Horden. När du har hjälpt till att få arbetarna tillbaka till sina sysslor förväntar han sig att få tillbaka sitt oumbärliga redskap.",al={"varför lämna tillbaka blackjacken","varför behöver thazz'ril blackjacken","varför vill han ha blackjacken"}}},fp="19,179,22.423.0,41.198.0,24.173.0,48.189.0,50.149.0"}
P.entries["item:forged-steel-bars"] = {n="Forged Steel Bars",s="I norra Barrens saknas Thun'grim Firegazes stålbarrer. Att återta dem visar att en krigare är besluten att återta stulen egendom.",h="I norra Barrens saknas Thun'grim Firegazes stålbarrer.",kw={"the barrens","smitt stål","forged steel bars","järnkista","razormane","stulen järnkista","thun'grim firegaze"},ang={["class:Warrior"]="Att återta Thun'grims stulna stål visar att en krigare kan spåra upp tjuvar och möta farliga quilboarflockar. I gengäld erbjuder Thun'grim skräddarsydda vapen.",["profession:Blacksmithing"]="De raffinerade barrerna visar skillnaden mellan grov, stampräglad skrotmetall och kvalitetsstålet som smids av tränade smeder i Horde."},sec={{t="Stulen metall",b="Thun'grim Firegaze, en synskadad orksmed, har ett läger i norra Barrens. Razormane quilboar tog hans järnkista under en nattlig räd och distraherade honom med grymtningar och frustningar medan tjuvarna smet iväg. Quilboar kunde inte bearbeta fint stål och lämnade den oöppnade kistan nära en förstörd vagn i sitt läger i nordväst. Barrerna är fortfarande oskadda för krigare som är villiga att återta dem."}},faq={{q="Vem äger de här smidda stålstängerna?",a="Barrerna tillhör Thun'grim Firegaze, en orkisk rustningssmed och vapensmed som bor i ett läger i norra Barrens.",al={"vem äger stängerna","thun'grims stål","vems stål är det här"}},{q="Varför stal quilboarerna dem?",a="Razormane quilboar stal dem för att plundra Thun'grims värdesaker. Eftersom de visste att hans syn var dålig hånade och distraherade de honom medan andra bar iväg hans järnkista.",al={"varför stjäla stål","quilboarernas motiv","razormanes stöld"}},{q="Använde quilboarerna stålet?",a="Nej. Razormanes saknade skickligheten att bearbeta så fint raffinerat stål. De lämnade kistan oöppnad bredvid en trasig vagn i sitt läger.",al={"smidde quilboarerna något","vad gjorde quilboarerna med stålet"}},{q="Vad erbjuder Thun'grim i utbyte mot dem?",a="Thun'grim erbjuder blivande krigare ett tillverkat vapen i utbyte mot att de vågar sig in i quilboar-lägren och återlämnar alla barrerna.",al={"belöning för smitt stål","vad får jag för stålet"}}},fx={["4e666297"]={q="Vad är Forged Steel Bars?",a="De här tackorna är ett lager av förädlad metall av hög kvalitet som tillhör smeden Thun'grim Firegaze. De förvaras säkert inlåsta i en järnkista vid hans läger och är fina material avsedda för smide av tåliga vapen. De är råa och har ännu inte blivit färdiga vapen, men hantverket överträffar vida det grova skrot som är typiskt för Barrens.",al={"vad är forged steel bars","information om forged steel bars","stulna ståltackor"}}},fp="17,144,12.398.0,33.114.0,32.171.0,31.136.0,45.122.0"}
P.entries["item:fragments-of-rok-alim"] = {n="Fragments of Rok'Alim",s="Fragments of Rok'Alim är de krossade stenresterna efter en uråldrig jordelementar som strövar omkring i Thousand Needles kanjoner. När de lämnas till Dorn Plainstalker vid The Weathered Nook blir de ett obestridligt fysiskt bevis på att en krigare har besegrat en uråldrig fasa i envig.",h="Fragments of Rok'Alim är de krossade stenresterna efter en uråldrig jordelementar som strövar omkring i...",kw={"dorn plainstalker","elementar","fragment","krossaren","rok'alim","styrkeprovet","thousand needles","the weathered nook"},ang={["class:Shaman"]="Rok'Alim är en uråldrig jordande som varit bunden till världen långt före vår tids schamanistiska pakter. Hans obevekliga natur gör honom till ett fascinerande studieobjekt för elementarisk råstyrka.",["race:Tauren"]="Att övervinna kvarlevor från Azeroths uråldriga förflutna ligger nära tauren-traditionerna att pröva harmoni, uthållighet och personlig styrka mot landets mäktigaste faror."},sec={{t="Rester av en uråldrig kraft",b="Medan de flesta elementarer försvann från Azeroth efter att de gamla gudarna bannlysts, hade några få tillräcklig råstyrka för att överleva på ytan utan att kallas fram med dödligas magi. Rok'Alim the Pounder är en av dessa överlevare och strövar omkring på kanjonernas slätter söder om huvudvägen. De lokala kentaurerna känner igen honom på dånet när hans steniga nävar krossar allt som är dumdristigt nog att komma i hans väg. Om du fäller denna levande kvarleva från urvärlden får du taggiga bitar av tät, animerad sten – en trofé som bevisar oöverträffad fysisk styrka."},{t="Styrkeprovet",b="För tauren-eremiten Dorn Plainstalker är det avgörande momentet i Styrkeprovet att återfinna fragmenten. Som en del av en serie andliga och kampinriktade riter som hålls högt uppe i The Weathered Nook kräver provet att en aspirant möter en varelse med obeveklig råstyrka. Om du lämnar över Rok'Alims sönderslagna spillror bevisar du att du har modet och den fysiska styrkan som krävs för att överleva Kalimdors hårdaste faror."}},faq={{q="Vad är Fragments of Rok'Alim?",a="De är de krossade stenresterna efter Rok'Alim the Pounder, en uråldrig jordelementar som strövar omkring i Thousand Needles nordvästra kanjoner. De tjänar som bevis på att elementaren har besegrats.",al={"fragments of rokalim","vad är rokalimfragment","rokalims sten"}},{q="Vem vill ha dessa stenfragment?",a="Dorn Plainstalker, en tauren-uppdragsgivare som bor vid The Weathered Nook högt uppe längs Thousand Needles kanjonklippor, ber om fragmenten för att avsluta Styrkeprovet.",al={"vem tar emot rokalimfragment","lämna in fragments of rokalim","dorn plainstalker uppdrag"}},{q="Varför är Rok'Alim betydelsefull?",a="Till skillnad från de flesta nutida elementarer som måste frammana­s av dödliga magiker har Rok'Alim dröjt sig kvar i världen sedan de gamla gudarnas tid. Kentaurstammarna i kanjonerna gav honom namnet 'the Pounder' på grund av det dånande ljudet när hans nävar krossar sitt byte.",al={"varför är rokalim speciell","rokalim historia","vem är rokalim the pounder"}},{q="Var hittar man Rok'Alim?",a="Rok'Alim strövar omkring i Thousand Needles nordvästra sänka, söder om områdets huvudväg bland sandstensspirorna.",al={"rokalims plats","hitta rokalim the pounder","var dyker rokalim upp"}}},fx={ab6946f8={q="Var kommer Fragments of Rok'Alim ifrån?",a="Fragmenten är bitar som brutits loss från Rok'Alim the Pounder, en väldig stenelementar som vandrar runt på kanjonens nordvästra botten i Thousand Needles. Till skillnad från elementarer som dödliga besvärjare frammanar är Rok'Alim en uråldrig överlevare från de gamla gudarnas era, med tillräcklig inneboende kraft för att förbli bunden till världen även efter att hans herrar föll. De har inte tillverkats av dödliga händer, utan brutits direkt från hans levande stenform.",al={"fragments of rokalims ursprung","var kommer rokalimfragmenten ifrån","vem tillverkade rokalimfragmenten"}}},fp="21,278,28.570.0,18.449.0,35.188.0,32.176.0,28.253.0,24.131.0"}
P.entries["item:frostwolf-banner"] = {n="Frostwolf Banner",s="Frostwolf Banner är en stamfana som förvaras djupt inne i Wildpaw Cavern i Alterac Valley. Hordens nykomlingar skickas dit för att hämta den som en förfädersrit på vägen till vuxenlivet, väcka sin stridsanda och förtjäna sin första klansymbol.",h="Frostwolf Banner är en stamfana som förvaras djupt inne i Wildpaw Cavern i Alterac Valley.",kw={"alterac valley","frostwolf banner","gnoller","insignia","prövningsplats","warmaster laggrond","wildpaw cavern"},ang={["faction:Horde"]="Att hämta den här fanan markerar en krigares formella första strid och invigning i den legendariska Frostwolf Clan under Warmaster Laggrond.",["race:Orc"]="För orcer hedrar återlämnandet av en förlorad klanfana från vilda gnoller Frostwolf Clans arv och Thralls förfädersarv i Alterac Mountains."},sec={{t="En övergångsrit",b="För Hordens krigare som anländer till Alterac Valley börjar vägen till en verklig plats bland Frostwolf Clan med ett prov på uthållighet. Warmaster Laggrond skickar nyrekryter söderut, in i de fuktiga, fientliga gångarna i Wildpaw Cavern, ett näste fullt av revirhävdande gnoller. Att nå fanan som göms där inne och återvända med den oskadd visar mod, bevisar att krigarens stridsraseri har vaknat och ger dem Frostwolf-novisens insignia."}},faq={{q="Varför finns Frostwolf Banner i en gnollgrotta?",a="Warmaster Laggrond och klanen har medvetet placerat fanan i Wildpaw Cavern för att göra dess läge till ett invigningsprov. En färd in i gnollernas revir tvingar nya krigare att skaka av sig självbelåtenheten, möta faran och väcka sin stridsanda.",al={"varför finns fanan i wildpaw","gnoller har en fana","frostwolf banners plats"}},{q="Vem ska jag lämna tillbaka Frostwolf Banner till?",a="Fanan måste lämnas tillbaka till Warmaster Laggrond i Alterac Valley. När du överlämnar den välkomnar han formellt en nykomling till Frostwolf-ledet och belönar denne med en insignia som visar dennes ställning.",al={"vem vill ha frostwolf banner","lämna in fanans uppdrag","laggrond och fanan"}},{q="Varför ser fanan så ovanlig ut för ett Frostwolf-ärke?",a="Laggrond erkänner den som en klanfana för prövningar, men dess mönster liknar äldre staminsignier, däribland symboler som förknippas med tidiga orciska klaner från den gamla Horden.",al={"skymningshammarens symbol på fanan","fanan ser fel ut","frostwolf banners utformning"}}},fx={cf6c63b1={q="Vad är Frostwolf Banner?",a="Frostwolf Banner är en stamfana som representerar Frostwolf Clan i Alterac Valley. Dess emblem liknar märkligt nog uråldrig klansymbolik snarare än deras vanliga vapen, men den är fortfarande en hedrad symbol för klanens närvaro och makt i den frusna dalen.",al={"vad är frostwolf banner","frostwolf banner i berättelsen","om frostwolf banner"}},["518ec450"]={q="Varför vill Warmaster Laggrond att Frostwolf Banner återtas?",a="Warmaster Laggrond kräver att alla nykomlingar som vill strida tillsammans med Frostwolves i Alterac Valley genomgår ett stridsprov. Om du hämtar fanan från djupet av det gnollangripna Wildpaw Cavern bevisar du ditt mod, väcker din krigaranda och förtjänar en novis insignier bland klanen.",al={"varför återta frostwolf banner","varför vill laggrond ha fanan","frostwolf banners syfte"}}},fp="16,195,17.403.0,48.206.0,40.160.0,57.196.0"}
P.entries["item:full-leaden-collection-phial"] = {n="Full Leaden Collection Phial",s="En tung, blyfodrad flaska fylld med radioaktivt nedfall från de trogger som hemsöker Gnomeregan. Uppfinnaren Ozzie Togglevolt har bett om det farliga provet i hopp om att framställa ett botemedel för bestrålade lepragnomer – eller kanske blanda till en farligt stark rom.",h="En tung, blyfodrad flaska fylld med radioaktivt nedfall från de trogger som hemsöker Gnomeregan.",kw={"full leaden collection phial","gnogaine","gnomeregan","bestrålad trogg","kharanos","uppsamlingsflaska av bly","lepragnom","ozzie togglevolt"},ang={["profession:Engineering"]="Blyhöljet visar på gängse gnomiska säkerhetsrutiner vid hantering av instabilt, giftigt nedfall för laboratorieprov.",["race:Gnome"]="För de förvisade gnomerna i Dun Morogh är det en dyster påminnelse om katastrofen som förgiftade deras förfäders hem att bära detta giftiga prov. Men det står också för ett desperat hopp om att återställa deras förvridna släktingar."},sec={{t="En giftig brygd",b="Blyfodret i uppsamlingsflaskan är nödvändigt för att skydda bäraren från det instabila gröna nedfall som genomsyrar Gnomeregan. Nedfallet uppstod när High Tinker Mekkatorques rådgivare fyllde de nedre korridorerna med giftig strålning för att stoppa de invaderande troggerna. Katastrofen förvred i stället både trogger och överlevande gnomer till vansinniga, bestrålade fasor. Genom att samla vätskerester direkt från Irradiated Invaders och Pillagers förser djärva äventyrare flyktingar bland uppfinnarna, som Ozzie Togglevolt och Razzle Sprysprocket i Kharanos, med råmaterial för deras försök att hitta botemedel."},{t="Botemedel eller brygd",b="Medan Gnoarn är helt inställd på att återta staden tar Ozzie Togglevolt sig an nedfallsproblemet med febriga gnomexperiment. Ozzie vill använda vätskan i flaskan för att behandla en instängd lepragnom – samtidigt som han hoppas att blandningen ska få tillbaka hans eget hår. Gränsen mellan ett mirakulöst motgift och en mycket instabil dryck är farligt tunn inom gnomisk laboratorievetenskap."}},faq={{q="Varför är flaskan gjord av bly?",a="Blyfodret hindrar det starkt radioaktiva nedfall som samlats från Gnomeregans förorenade trogger från att göra bäraren sjuk eller döda hen på vägen tillbaka till Kharanos.",al={"varför blyflaska","syftet med uppsamlingsflaskan av bly","syftet med den blyfärgade insamlingsflaskan"}},{q="Vem vill ha den här bestrålade vätskan?",a="Ozzie Togglevolt, en gnomisk forskare verksam i Kharanos, behöver det bestrålade nedfallet för att försöka hitta ett botemedel för gnomer som drabbats av lepra, med hjälp av Razzle Sprysprocket.",al={"vem behöver flaskan","ozzie togglevolts uppdrag","vem lämnar in gnogaine"}},{q="Varifrån kommer strålningen i flaskan?",a="De lysande gröna resterna samlas direkt från Irradiated Invaders och Irradiated Pillagers, trogger som strövar i de förgiftade korridorerna in mot Gnomeregan.",al={"hur fyller man flaskan","var finns bestrålade trogger","varifrån kommer det gröna skenet"}},{q="Botar Ozzie faktiskt lepragnomerna med det?",a="Ozzies experiment är kaotiska och osäkra. Hans brygd ska bota en tillfångatagen lepragnom och återställa hans eget hår, men gnomisk vetenskap kräver ofta upprepade försök och förfinade prover innan den ger säkra och tillförlitliga resultat.",al={"fungerar botemedlet","vad händer med gnogaine","blir lepragnomen botad"}}},fx={["32cc4509"]={q="Vad är Full Leaden Collection Phial?",a="Det är en tung, blyskärmad flaska fylld med glödande grönt radioaktivt avfall, utvunnet direkt från de förorenade troggs som hemsöker Gnomeregan. Det tjocka blyhöljet hindrar de farliga radioaktiva resterna från att förgifta den som bär flaskan.",al={"vad är blyflaskan","full blyflaska","vad är det här för flaska"}}},fp="28,178,12.513.0,18.353.1,30.179.0,32.168.0,48.154.0,50.226.0"}
P.entries["item:fungal-spores"] = {n="Fungal Spores",s="Runt Barrens oaser samlas Fungal Spores i svällda svampar. Vattnet får livet omkring dem att frodas, och Royal Apothecary Society söker sporerna för sin alkemi.",h="Runt Barrens oaser samlas Fungal Spores i svällda svampar.",kw={"apothecary helbrim","apotekarsällskapet","barrens","crossroads","the forgotten pools","fungal spores","späckad svamp","lushwater oasis","the stagnant oasis"},ang={["profession:Herbalism"]="Som örtletare kan du se hur det livgivande vattnet i Barrens oaser förändrar svamparna som växer i närheten.",["race:Undead"]="Som odöd vet du att Royal Apothecary Society värdesätter sällsynta regionala ingredienser till sin forskning. Kalimdors förändrade svampar erbjuder ett annat val än Lordaerons pestsmittade växter."},sec={{t="Oasernas livskraft",b="Barrens oaser ger de torra slätterna ett ovanligt rikt liv. Vid The Forgotten Pools, Lushwater Oasis och The Stagnant Oasis gör vattnet mer än att släcka törsten. Det får närliggande växter och djur att frodas och förändras. Svampar längs de fuktiga stränderna sväller av sporer som för med sig vattnets koncentrerade kraft och främjar tillväxt. Naturkunniga studerar förändringen, medan Royal Apothecary Society samlar svamparna för sin alkemi."},{t="De förkastades alkemi",b="Apotekare på andra håll samlar ovanliga lokala ingredienser till sina laboratorier och kollegor. Vid The Crossroads skickar Apothecary Helbrim sådana reagenser vidare, bland annat till Apothecary Zamah i Thunder Bluff. Sporerna är värdefulla för att brygga kraftfulla kemiska blandningar. Deras naturliga egenskaper har redan förändrats av de mystiska krafter som finns under Kalimdors jord, vilket gör dem användbara för Forsaken."}},faq={{q="Var hittar man sporerna?",a="Du hittar Fungal Spores i svällda svampar längs stränderna vid Barrens största oaser: The Forgotten Pools, Lushwater Oasis och The Stagnant Oasis.",al={"sporernas platser","var man hittar fungal spores","späckade svampars platser"}},{q="Varför är de förkastade intresserade av dem?",a="Oasernas vatten har förändrat sporerna med livfull livsenergi. Apothecary Helbrim använder dem i kraftfulla blandningar åt Royal Apothecary Society och sin kollega Apothecary Zamah i Thunder Bluff.",al={"varför helbrim vill ha sporer","apotekarens användning av sporer","vad sporer används till"}},{q="Varför växer svamparna kring oaserna sig så stora?",a="Vattnet vid Barrens oaser bär på ovanlig livsenergi som förändrar närliggande växter och djur. Svampar längs stränderna sväller av förändrade sporer.",al={"varför svamparna är muterade","oasvattnets effekt","oasernas mysterium"}},{q="Vem ber om sporerna?",a="Apothecary Helbrim, en alkemist av Forsaken vid The Crossroads i Barrens, ber äventyrare samla sporer åt hans forskning.",al={"vem som behöver fungal spores","uppdragsgivare för sporer","apothecary helbrim"}}},fx={["3c4c96db"]={q="Vad är det här för svampsporer?",a="Det här är potenta sporer som skördats från de frodiga svamparna som växer runt The Barrens oaser, till exempel The Forgotten Pools. Svamparna får näring av de märkliga, förändrade livsenergierna som flödar genom oasernas vatten och producerar sporer med ovanliga biologiska egenskaper som väcker alkemisternas intresse.",al={"vad är svampsporer","information om svampsporer","vad är sporerna"}},["02f1bc1b"]={q="Varför vill Apothecary Helbrim ha svampsporerna?",a="Apothecary Helbrim vid The Crossroads söker sporerna åt Royal Apothecary Society. Han har särskilt stor nytta av oassvamparnas förändrade egenskaper när han blandar en experimentell brygd, som han tänker leverera till sin kollega, Apothecary Zamah, i Thunder Bluff.",al={"varför vill helbrim ha sporer","varför vill någon ha svampsporer","vem behöver svampsporer"}}},fp="13,177,21.431.0,16.404.0,29.155.0,40.200.0,52.148.0,24.126.0"}
P.entries["item:furen-s-instructions"] = {n="Furen's Instructions",s="I Stormwind anger Furen's Instructions materialen som behövs för eldhärdad ringbrynja. Furen Longbeard ger pergamentet till allianskrigare som han har prövat.",h="I Stormwind anger Furen's Instructions materialen som behövs för eldhärdad ringbrynja.",kw={"charred horn","eldhärdad ringbrynja","furen longbeard","furen's instructions","galvanized horn","razorfen kraul","scorched spider fang","stonetalon","vial of phlogiston","wetlands"},ang={["class:Warrior"]="Som allianskrigare ställs du inför prövningar mot vildsinta bestar och quilboar för att förtjäna tung ringbrynjeutrustning.",["profession:Blacksmithing"]="Som smed kan du se hur Furens recept kombinerar reagenser från bestar med sällsynta alkemiska destillat för att härda rustningar utöver vad vanlig smideskonst klarar."},sec={{t="En mästersmeds krav",b="Furen Longbeard erbjuder sig att smida en tålig ringbrynja åt en krigare som har visat vad han går för genom enklare smidesarbete. Den dvärgiske rustningssmeden ber krigaren hämta de sällsynta beståndsdelarna själv. På pergamentet står vad som behövs, och krigaren får färdas mellan kontinenter för att samla ihop det."},{t="Exotiska beståndsdelar",b="Pergamentet kräver en farlig resa genom Eastern Kingdoms och Kalimdor. De härdade länkarna kräver dussintals förkolnade spindeltänder från fuktiga grottor i Wetlands, samt horn från eldspyende chimärer i Stonetalon Mountains klippiga berg. Listan kräver också ett galvaniserat horn från chimärernas matriark och en flaska flyktig flogiston som finns djupt inne i Razorfen Kraul, ett fäste för quilboar."}},faq={{q="Vad är Furen's Instructions?",a="Furen's Instructions är en skriven lista som Furen Longbeard ger till allianskrigare i Stormwind. Den anger vilka exotiska material som behövs för att tillverka eldhärdad ringbrynja.",al={"furens instruktioner","vad är furens instruktioner","furens lista"}},{q="Vem är Furen Longbeard?",a="Furen Longbeard är en dvärgisk mästarrustningssmed i Stormwinds Dwarven District. Han prövar erfarna krigare och tillverkar hållbar skyddsutrustning åt dem.",al={"vem är furen","furen longbeard","furen stormwind"}},{q="Varifrån kommer materialen på listan?",a="Listan kräver förkolnade spindeltänder från Wetlands, förbrända horn och ett galvaniserat horn från chimärer i Stonetalon Mountains samt en flaska flogiston från Roogug i Razorfen Kraul.",al={"var hittar jag föremålen","var finns furens material","material på furens lista"}},{q="Vad smider Furen av de här materialen?",a="Furen använder materialen och sina smideshemligheter för att smida ett särskilt stycke eldhärdad ringbrynja åt krigaren.",al={"vilken rustning smider furen","belöning i eldhärdad ringbrynja","furens smidesbelöning"}}},fx={["82702a01"]={q="Varifrån kommer Furen's Instructions, och vem skrev dem?",a="Furen Longbeard, en skicklig dvärgisk smed som arbetar i Stormwind, skrev dokumentet själv. Han känner till hemligheterna bakom att smida enastående ringbrynja och skrev den här detaljerade förteckningen över de sällsynta komponenter som behövs världen över, så att en ambitiös krigare vet precis vad han ska leta efter.",al={"vem skrev furens instruktioner","varifrån kommer furens instruktioner","furens instruktioners ursprung"}},["42eefba8"]={q="Varför är Furen's Instructions viktiga?",a="Instruktionerna vägleder dig genom en mödosam skattjakt i Kalimdor och Eastern Kingdoms. Furen kräver att du har dem med dig när du samlar in svedda huggtänder, chimärhorn och alkemiskt flogiston, så att du kommer tillbaka med exakt de reagenser han behöver för att smida eldhärdad rustning.",al={"varför behöver jag furens instruktioner","varför efterfrågas furens instruktioner","furens instruktioners syfte"}}},fp="20,156,24.290.0,17.417.0,29.159.0,23.147.0,45.191.0,43.117.0"}
P.entries["item:furen-s-notes"] = {n="Furen's Notes",s="Furen's Notes förmedlar hans upptäckter inom metallurgi och pansarsmide från Stormwind till alliansens hantverkare. Efter att ha smitt skyddsutrustning åt veteraner skickar Furen Longbeard kopior så att andra smeder kan förfina sitt arbete.",h="Furen's Notes förmedlar hans upptäckter inom metallurgi och pansarsmide från Stormwind till alliansens...",kw={"smedskonst","dwarven district","furen","furen longbeard","furen's notes","grimand elmore","klockmort spannerspan","mathiel"},ang={["class:Warrior"]="Som krigare leder dina rustningsprov i Stormwind direkt till dessa anteckningar. De dokumenterar praktiska idéer som formats av frontstridens behov.",["profession:Blacksmithing"]="Som smed får du se hur kunskap om specialiserat rustningshantverk utbyts mellan dvärgiska, alviska och gnomiska hantverkare över hela alliansen."},sec={{t="En mästares upptäckter",b="I Stormwinds Dwarven District smider Furen Longbeard specialanpassade vapen åt krigare och dokumenterar metoderna och upptäckterna han gör längs vägen. Dvärgarnas metallbearbetning förändras ständigt, så han gör flera kopior som andra smeder kan använda och bygga vidare på. Hans anteckningar beskriver praktiska sätt att härda, förstärka och forma rustningar så att de står emot dödliga slag."},{t="Spridda över alliansen",b="Furen skickar kopior till betrodda kontakter i alliansens nätverk av hantverkare. Grimand Elmore kanske hånskrattar åt en medsmid han påstår sig ha undervisat, men anteckningarna innehåller ändå användbara insikter. Kopior färdas över det Stora havet till nattalvernas hantverkare, däribland Mathiel på Darnassus Warrior's Terrace. Gemensamma behov i strid för deras olika traditioner samman."}},faq={{q="Vad innehåller Furen's Notes?",a="Furen's Notes innehåller beskrivningar av pansarsmidestekniker och metallurgiska upptäckter som Furen Longbeard utvecklade när han tillverkade specialrustningar åt erfarna krigare.",al={"vad är furen's notes","vad finns i furens anteckningar","innehållet i furen's notes"}},{q="Vem är Furen Longbeard?",a="Furen Longbeard är en mästersmed bland dvärgarna i Stormwinds Dwarven District. Han vägleder lovande krigare och tillverkar specialanpassad defensiv krigsutrustning.",al={"vem skrev detta","vem är furen","furen longbeard"}},{q="Varför blir Grimand Elmore arg över anteckningarna?",a="Grimand Elmore hävdar att han lärde Furen allt dvärgen kan och ogillar antydan om att hans före detta elev kan lära honom något nytt. Ändå medger Grimand att anteckningarna beskriver tekniker värda att pröva.",al={"varför är grimand arg","grimand elmores reaktion","grimand stolt"}},{q="Vem får kopior av Furen's Notes?",a="Furen skickar kopior till betrodda kollegor över hela alliansen, däribland vapensmeden Grimand Elmore i Stormwind, nattalvssmeden Mathiel i Darnassus och den gnomiska smeden Klockmort Spannerspan i Ironforge.",al={"vem får furens anteckningar","vart skickas anteckningarna","lämna över furens anteckningar"}},{q="Hur reagerar Mathiel på anteckningarna?",a="Mathiel, en nattalvssmed på Darnassus Warrior's Terrace, välkomnar Furens upptäckter med entusiasm. Han ser dem som en storslagen upptäckt och en ära att införliva i sitt eget arbete.",al={"mathiels reaktion","mathiel darnassus","vad tycker mathiel"}}},fx={["224f803f"]={q="Varför vill någon ha Furen's Notes?",a="Anteckningarna beskriver banbrytande smidestekniker som Furen Longbeard utvecklade när han smidde specialrustning åt krigare. Smeder i hela Alliansen, som Mathiel i Darnassus och Grimand Elmore i Stormwind, kan dra nytta av värdefulla metallurgiska insikter i dem. Även hantverkare som tvivlar på Furens skicklighet, som Elmore, ser nyskapande idéer där som de gärna vill pröva vid sina egna städ.",al={"varför vill smeder ha furens anteckningar","värdet av furens anteckningar","varför dela furens anteckningar"}}},fp="13,227,22.352.0,30.361.0,39.172.0,23.146.0,50.211.0,37.212.0,36.183.0"}
P.entries["item:furlbrow-s-deed"] = {n="Furlbrow's Deed",s="Familjen Furlbrow har strandat nära gränsen till Westfall, och deras lagfart är i Defias händer. På dokumentet står Theodore och Verna Furlbrows anspråk på familjens gård, medan paret väntar vid sin trasiga vagn.",h="Familjen Furlbrow har strandat nära gränsen till Westfall, och deras lagfart är i Defias händer.",kw={"lagfart","defias","gård","furlbrow","theodore","verna","vagn","westfall"},ang={["faction:Alliance"]="Som medlem av Alliance kan du ge lite tröst åt undersåtar som tvingats på flykt på grund av kungarikets brist på soldater.",["race:Human"]="Som människa kan du se hur Defias har skadat samhällsordningen i områdena intill Stormwind, till och med genom att stjäla enkla äganderättshandlingar."},sec={{t="Stulen mark och förfalskade anspråk",b="På lagfarten finns Theodore Furlbrows underskrift och även Vernas, som säkrar deras familjegård i Westfall. När Defias Brotherhood tog över regionen drev banditerna bort paret från deras hem och förde dokumentet till Elwynn Forest. Anteckningar på baksidan visar att de tänkte kopiera det när de förfalskade lagfarter för andra egendomar. Familjen Furlbrow förlorade sitt hem och sin försörjning och gav sig sedan ut på vägarna. Deras vagn gick sönder nära gränsen och lämnade dem strandsatta."}},faq={{q="Varför stal Defias lagfarten?",a="Anteckningar på pergamentet visar att Defias tänkte studera sigillet och underskrifterna och sedan förfalska lagfarter för att göra anspråk på beslagtagna gårdar runtom i Westfall.",al={"varför stjäla lagfarten","varför ville banditerna ha lagfarten","defias syfte med lagfarten"}},{q="Vem tillhör den här lagfarten?",a="Lagfarten tillhör Farmer Theodore Furlbrow och hans fru Verna, nybyggare i Westfall som laglösa drev bort från deras gård.",al={"vem äger familjen furlbrows lagfart","vem är furlbrow","vems lagfart är det här"}},{q="Var hittar man familjen Furlbrow?",a="Du hittar paret strax innanför Westfall, bredvid deras trasiga vagn på huvudvägen från Elwynn Forest.",al={"var finns familjen furlbrow","farmer furlbrows plats","var lämnar man tillbaka lagfarten"}},{q="Varför bryr sig familjen Furlbrow fortfarande om lagfarten om de har flytt?",a="Familjen Furlbrow vet att Westfall är alltför farligt för hederligt folk nu, men bevis på äganderätten ger dem hopp om att återta sin mark om freden återvänder.",al={"varför vill de ha tillbaka lagfarten","kommer familjen furlbrow att återvända"}}},fx={["4593623b"]={q="Varifrån kommer Furlbrow's Deed, och vem upprättade den?",a="Lagfarten ger officiell äganderätt till ett stort jordbruksområde i Westfall. Den är undertecknad av Theodore Furlbrow och bevittnad av hans hustru Verna. Den fastslog deras rättmätiga ägande av familjegården innan Defias-banditerna pressade dem på pengar och stal den rakt ur händerna på dem.",al={"furlbrows lagfarts ursprung","vem upprättade furlbrows lagfart","varifrån kom lagfarten"}}},fp="15,210,29.449.0,34.139.0,29.121.0,33.108.0,60.155.0"}
P.entries["item:furlbrow-s-pocket-watch"] = {n="Furlbrow's Pocket Watch",s="I Westfall har Farmer Furlbrow tappat ett minne från sin bröllopsdag. Fickuret var en gåva från Vernas far och lämnades kvar när Defias-banditer tog familjens pumpagård.",h="I Westfall har Farmer Furlbrow tappat ett minne från sin bröllopsdag.",kw={"benny blaanco","defias","farmer furlbrow","furlbrow's pocket watch","det bortglömda arvegodset","verna furlbrow","garderob","westfall"},ang={["faction:Alliance"]="När du hjälper familjen Furlbrow att återfå sitt arvegods ser du hur fullständigt Stormwinds krona har misslyckats med att skydda Westfalls hårt arbetande bönder från organiserad banditverksamhet."},sec={{t="Ett minne bland ruinerna",b="Farmer Furlbrow och Verna flydde hemmet i nattens mörker när Defias-banditer svärmade över Furlbrow Pumpkin Patch. I brådskan lämnade han kvar ett fickur från Vernas far. Uret ligger kvar i en garderob i det övertagna gårdshuset, där Benny Blaanco och hans banditer håller vakt. Det fördrivna paret slår nu läger längs vägen, och uret är en av få saker från deras tidigare liv som fredlösa inte har förstört."}},faq={{q="Varför är fickuret så viktigt för Farmer Furlbrow?",a="Vernas far gav Farmer Furlbrow uret på deras bröllopsdag. Efter att Defias Brotherhood tog deras mark, hem och försörjning är det parets sista ägodel med djupt känslomässigt värde.",al={"varför vill furlbrow ha sitt ur","varför furlbrows ur är viktigt","vem gav furlbrow uret"}},{q="Var förvaras fickuret?",a="Uret ligger i en garderob i Furlbrow-gårdshuset, bland pumpafälten väster om huvudvägen där familjen Furlbrow är strandsatt.",al={"var är fickuret","var furlbrows garderob finns","hur man hittar uret"}},{q="Vem vaktar uret?",a="Defias Brotherhood har tagit över gårdshuset. Benny Blaanco och hans kumpaner håller till nära garderoben.",al={"vem har furlbrows ur","vem vaktar uret i westfall","benny blaanco och uret"}},{q="Stal Defias uret direkt?",a="Nej. Familjen Furlbrow flydde i panik när banditerna gjorde en räd mot pumpagården, och Farmer Furlbrow glömde att packa ner uret. Det blev kvar i garderoben i deras sovrum när gården övertogs.",al={"plundrade defias uret","blev uret stulet"}}},fx={["42b91745"]={q="Vad är Furlbrow's Pocket Watch?",a="Det är ett kärt arvegods som tillhör Farmer Furlbrow. Hans hustru Vernas far gav honom klockan i bröllopsgåva. När Defias Brotherhood tog över deras pumpagård tvingades paret fly för sina liv mitt i natten och lämnade av misstag det dyrbara uret kvar i garderoben.",al={"vad är furlbrows fickur","furlbrows fickur","farmer furlbrows fickur"}},ba43cdcd={q="Varifrån kommer Furlbrow's Pocket Watch, och vem tillverkade den?",a="Klockan tillhörde ursprungligen Verna Furlbrows far, som gav den till Farmer Furlbrow på parets bröllopsdag. Det är okänt vem som tillverkade den eller i vilken stad, men för de fördrivna bönderna är den ett av få bestående minnen av familjen och deras tidigare liv, innan Defias drev bort dem från deras mark.",al={"vem tillverkade furlbrows fickur","var fick furlbrow klockan","furlbrows fickurs ursprung"}}},fp="23,194,23.421.0,56.197.0,31.138.0,26.107.0,40.185.0"}
P.entries["item:gaea-seed"] = {n="Gaea Seed",s="Gaea Seeds är tåliga frökärnor som hittas längs Mirkfallon Lakes strand i Stonetalon Mountains. Tauren-shamaner värdesätter dem, eftersom de är genomsyrade av elementära välsignelser som hjälper till att återställa områden som härjats av krig och industri.",h="Gaea Seeds är tåliga frökärnor som hittas längs Mirkfallon Lakes strand i Stonetalon Mountains.",kw={"the charred vale","återfödelsens kretslopp","jordmodern","gaea seed","mirkfallon lake","stonetalon","sun rock retreat","tammra windfield"},ang={["class:Shaman"]="Fröna visar hur man praktiskt kan återställa jorden och hur shamanistiska ritualer och Jordmoderns välsignelse kan påskynda naturlig tillväxt i skadade miljöer.",["race:Tauren"]="För tauren vid Sun Rock Retreat är odlingen av Gaea Seeds en helig plikt för att läka den balans i landet som rubbats av krig och skogsavverkning utifrån."},sec={{t="Kärl för förnyelse",b="Gaea Seeds hör hemma i Stonetalon Mountains och sköljs naturligt upp eller växer kring stränderna vid Mirkfallon Lake. De ser anspråkslösa ut och liknar små, trådiga kokosnötter, men har en medfödd tålighet. När industriell exploatering och konflikter sargar Stonetalon ser shamaner fröna som livsviktiga redskap för att läka den sårade jorden."},{t="Jordmoderns välsignelser",b="Vid Sun Rock Retreat samlar tauren-shamanen Tammra Windfield Gaea Seeds för att motverka förstörelsen som sprider sig över bergstopparna. Med traditionella sånger och elementära ritualer välsignar shamanerna de vilande skalen i Jordmoderns namn. Denna andliga kraft påskyndar deras naturliga tillväxt dramatiskt och förvandlar enkla frön till tåliga plantor som kan slå rot i förkolnad, karg mark som The Charred Vale."}},faq={{q="Var hittar man Gaea Seeds?",a="Gaea Seeds ligger utspridda längs Mirkfallon Lakes strand, i bergen norr om Sun Rock Retreat i Stonetalon.",al={"gaea seed plats","var hittar man gaea seeds","hur får man gaea seed"}},{q="Vad används Gaea Seeds till?",a="Tammra Windfield samlar dem vid Sun Rock Retreat för att utföra en elementär välsignelse. När fröna har genomsyrats av shamanistisk kraft används de för att återställa växtlivet i ödelagda områden som The Charred Vale.",al={"gaea seed användning","varför samla gaea seeds","vad gör tammra med gaea seeds"}},{q="Varför behöver shamaner välsigna fröna?",a="Marken i delar av Stonetalon har skadats svårt av eld, krig och skogsavverkning. Genom att kanalisera Jordmoderns kraft in i fröna påskyndar shamanerna groningen och gör dem tillräckligt starka för att växa i fientlig, förstörd jord.",al={"varför välsigna fröna","shamanmagi med gaea seed"}},{q="Hur ser Gaea Seeds ut?",a="De ligger nära vattenbrynet runt Mirkfallon Lake och ser ut som små, bruna, rundade skal eller kokosnötter som vilar på stranden.",al={"gaea seed utseende","hur känner man igen gaea seeds"}}},fx={["0f706426"]={q="Vad är ett Gaea Seed?",a="Ett Gaea Seed är en tålig, kokosliknande livskärna som hör hemma i Stonetalon Mountains. Fröna har en naturlig motståndskraft och stor växtkraft som tauren-schamaner utnyttjar med Earthmothers välsignelse för att återställa växtligheten i områden som skadats av industriell girighet och krig.",al={"vad är gaea seeds","information om gaea seed","vad är gaea seed"}},e9a7441d={q="Varifrån kommer ett Gaea Seed?",a="Gaea Seeds är naturliga botaniska underverk som bara finns vid Mirkfallon Lakes strand, högt uppe i Stonetalon Mountains norr om Sun Rock Retreat. De är inte skapade av dödliga händer, utan är naturliga gåvor från Earthmother som frodas längs sjöns stränder.",al={"vem skapade gaea seed","gaea seeds ursprung","varifrån kommer gaea seeds"}},["3509f4c5"]={q="Varför vill Tammra Windfield ha Gaea Seeds?",a="Tammra Windfield, en schaman i Sun Rock Retreat, söker Gaea Seeds för att läka den sargade vildmarken i Stonetalon. Oavbruten skogsavverkning och strider har ödelagt området, särskilt den svedda marken i The Charred Vale. När hon samlar in fröna kan hon kanalisera Earthmothers välsignelse och schamankraft till dem, så att de växer snabbare och återställer det förstörda landet.",al={"varför samla gaea seeds","vem vill ha gaea seeds","varför vill någon ha gaea seed"}}},fp="9,169,18.239.0,28.361.1,27.103.0,29.172.0,39.167.0,29.103.0"}
P.entries["item:gaffer-jack"] = {n="Gaffer Jack",s="En Gaffer Jack är en specialiserad ingenjörskomponent för finjustering av mekanismer, till exempel stintle pegs. Den excentriske gnomuppfinnaren Wizbang Cranktoggle tappade slarvigt en låda med dem i havet utanför Auberdine under sin sjöresa.",h="En Gaffer Jack är en specialiserad ingenjörskomponent för finjustering av mekanismer, till exempel stintle...",kw={"auberdine","darkshore","fiske","gaffer jack","ironforge","stintle pegs","wizbang cranktoggle"},ang={["profession:Engineering"]="Andra mekaniker känner igen frustrationen i att förlora specialdelar som gaffer jacks. Utan dem går det inte att kalibrera känsliga mekanismer som stintle pegs.",["race:Gnome"]="Att lämna Ironforges liv och rörelse för ett stillsamt liv i Auberdine kan verka ovanligt för en gnom. Men att efter för mycket dricka tappa en hel låda med viktiga delar överbord är helt i hans stil."},sec={{t="Förlorade till havs",b="Gnommekanikern Wizbang Cranktoggle ville ha lugn och ro, bort från smedjornas slamrande och värdshusens oväsen i Ironforge. Därför bokade han plats på ett skepp till Auberdine. Under sjöresan drack Wizbang lite för mycket och fumlade så att en hel behållare med gaffer jacks föll överbord. De små mekaniska fästanordningarna sjönk ner i Darkshores dimmiga kustvatten. Nu står han utan de viktiga delar som krävs för att finjustera sina stintle pegs."},{t="Bärgning från havet",b="Eftersom gaffer jacks spilldes ut i bränningarna längs stranden fastnar de ibland på krokarna hos tålmodiga fiskare som kastar ut i Darkshores kustvatten. När komponenterna bärgas kan Wizbang bygga ihop sina märkliga manicker. Att dra upp små metalldelar ur öppet hav kräver både enastående tålamod och ren tur."}},faq={{q="Vad används en Gaffer Jack till?",a="Enligt gnommekanikern Wizbang Cranktoggle är gaffer jacks viktiga ingenjörskomponenter som behövs för att finjustera stintle pegs i hans experimentella uppfinningar.",al={"gaffer jack syfte","vad gör en gaffer jack","gaffer jack användning"}},{q="Hur hamnade de här i havet vid Auberdine?",a="Wizbang Cranktoggle tog ett skepp från Eastern Kingdoms för att få lugn och ro, bort från Ironforge. Under resan drack han för mycket och råkade tappa sin låda med gaffer jacks överbord i Darkshores vatten.",al={"varför ligger gaffer jacks i vattnet","vem tappade gaffer jacks","gaffer jack förlorad"}},{q="Vem vill få tillbaka Gaffer Jacks?",a="Wizbang Cranktoggle, en excentrisk gnomuppfinnare som bor i hamnstaden Auberdine, behöver få tillbaka åtta stycken för att fortsätta bygga sina märkliga uppfinningar.",al={"vem behöver gaffer jacks","lämna in gaffer jacks","vem tar emot gaffer jacks"}},{q="Var kan man hitta Gaffer Jacks?",a="De ligger under vatten längs Darkshores kust på havsbotten, där sportfiskare ibland får upp dem när de fiskar i bränningarna.",al={"var hittar man gaffer jacks","hur hittar man gaffer jacks","gaffer jack plats"}}},fx={["1164a7e3"]={q="Vad är en Gaffer Jack?",a="En Gaffer Jack är en särskild ingenjörskomponent som används av uppfinnare som Wizbang Cranktoggle. Wizbang använder dem för att finjustera sina stintle-pinnar, vilket gör dem oumbärliga i hans verktygslåda för uppfinningar.",al={"vad är gaffer jack","gaffer jacks bakgrund","vad är gaffer jacks"}}},fp="11,138,11.355.0,14.256.0,31.95.0,51.210.0,33.152.0,32.111.0"}
P.entries["item:gallywix-s-head"] = {n="Gallywix's Head",s="I Orgrimmar visar Gallywix's Head att en förman från Venture Company avrättades. The Shattered Hand kräver trofén som bevis på dödandet.",h="I Orgrimmar visar Gallywix's Head att en förman från Venture Company avrättades.",kw={"the barrens","gallywix","orgrimmar","puzik","shattered hand","shenthul","the sludge fen","venture co"},ang={["class:Rogue"]="Som skurk bevisar du med hämtningen av Gallywix's Head din dödliga skicklighet i infiltration, smygande och riktat lönnmord åt The Shattered Hand.",["faction:Horde"]="Som medlem av The Horde hjälper du till att hejda Venture Company's exploaterande industriella intrång, som hotar gränserna till The Barrens och Durotar."},sec={{t="Ett bistert bevis på att målet undanröjts",b="Överförman Puzik Gallywix ledde Venture Company's arbete från dess torn norr om The Sludge Fen. När ryktet nådde dem att Venture Co. planerade något storskaligt skickade The Shattered Hand agenter för att montera ned anläggningen. Att ta Gallywix's Head till Shenthul i Orgrimmar bevisar att förmannen avrättades och befäster skurkens ställning i gillet."},{t="Infall vid The Sludge Fen",b="Ordern att ta Gallywix's Head kräver också att en stulen Cache of Zanzil's Altered Mixture hämtas och att tornets förgiftade personal slaktas. Agenter lönnmördar Gallywix högst upp på hans utkikspost och återför hans huvud till The Cleft of Shadow. Dådet bekräftar att Venture Company's storslagna plan i The Barrens har stoppats."}},faq={{q="Vems huvud är det här?",a="Huvudet tillhör Grand Foreman Puzik Gallywix, en goblinöverordnad som leder Venture Companys verksamhet vid The Sludge Fen i norra The Barrens.",al={"vem är gallywix","puzik gallywix","gallywix huvudets ursprung"}},{q="Vem vill ha Gallywix's Head?",a="Shenthul vill ha Gallywix's Head. Han är en skurk-tränare och agent för The Shattered Hand i The Cleft of Shadow i Orgrimmar.",al={"vem ska jag lämna huvudet till","lämna in gallywix huvud","shenthul huvud"}},{q="Varför vill Shattered Hand ha honom död?",a="Puzik Gallywix styrde Venture Company's torn norr om The Sludge Fen, där Venture Co. planerade något storskaligt. Han förvarade också den sista cachen med Zanzil's Altered Mixture i sitt kassaskrin. The Shattered Hand dömde honom till döden för att slå ut verksamheten och lägga beslag på blandningen.",al={"varför döda gallywix","orsak till mordet på gallywix"}},{q="Var finns Puzik Gallywix?",a="Puzik Gallywix finns högst upp i Venture Company's torn, strax norr om The Sludge Fen i norra The Barrens.",al={"var är gallywix","gallywix plats","tornboss vid sludge fen"}}},fx={["862bd188"]={q="Varifrån kommer Gallywix's Head?",a="Huvudet har skilts från Grand Foreman Puzik Gallywix, en goblinförman som övervakar verksamheten i Venture Companys torn norr om The Sludge Fen i The Barrens. En lönnmördare får i uppdrag av Shattered Hand att infiltrera fästet och döda dess invånare. Huvudet tas direkt från förmannens lik högst upp i tornet som bevis på att operationen har slagits ut grundligt.",al={"var får man gallywix huvud","gallywix huvuds ursprung","hur får man gallywix huvud"}}},fp="15,145,27.375.0,24.325.1,19.150.0,26.119.0,42.285.0,32.117.0"}
P.entries["item:galvanized-horn"] = {n="Galvanized Horn",s="I The Charred Vale bär chimaeramatriarker horn som rustningssmeder i Stormwind och Thunder Bluff söker efter. Dessa förhårdnade utväxter används i specialrustningar för krigare.",h="I The Charred Vale bär chimaeramatriarker horn som rustningssmeder i Stormwind och Thunder Bluff söker efter.",kw={"the charred vale","chimaeramatriark","eldhärdad ringbrynja","furen longbeard","galvanized horn","orm stonehoof","stonetalon mountains"},ang={["class:Warrior"]="Som krigare prövas din uthållighet och styrka när du fäller en matriark och tar hennes Galvanized Horn. Det bevisar ditt mod för mästersmeder i Stormwind eller Thunder Bluff.",["profession:Blacksmithing"]="Som smed visar hornet hur organiska material som härdats under extrema förhållanden kan mäta sig med eller överträffa bearbetade metaller i specialanpassad rustningsförstärkning."},sec={{t="Trofé från The Charred Vale",b="Chimaeramatriarker stryker omkring i The Charred Vale i Stonetalon Mountains. Deras horn blir ovanligt hårda av aska, eld och kampen för att överleva. Yngre chimaeror ger spröda, svärtade horn, men en matriarks horn är lika starkt som behandlad metall. Furen Longbeard i Stormwind och Orm Stonehoof i Thunder Bluff söker båda ett horn som prov på krigisk tapperhet och som en viktig ingrediens i utsökt ringbrynja."}},faq={{q="Varifrån kommer ett Galvanized Horn?",a="Ett Galvanized Horn kommer från en chimaeramatriark i The Charred Vale, i västra Stonetalon Mountains.",al={"var hittar man galvanized horn","hur får man galvanized horn","galvanized horn byte"}},{q="Varför vill smeder ha just det här hornet?",a="Mästersmeder värdesätter hornets täthet och värmetålighet. De använder det för att förstärka specialgjorda ringbrynjor och plåtrustningar.",al={"vad används galvanized horn till","användning av galvanized horn"}},{q="Vem tar emot Galvanized Horn?",a="Furen Longbeard i Stormwind söker hornet till eldhärdad rustning åt alliansens krigare. Orm Stonehoof i Thunder Bluff söker det som bevis på styrka och för att smida en krigarhjälm åt hordens krigare.",al={"vem behöver galvanized horn","lämna in galvanized horn"}},{q="Hur skiljer det sig från ett vanligt Charred Horn?",a="Vanliga Charred Horn kommer från yngre chimaeror. Ett Galvanized Horn kommer från en fullvuxen matriark och har en tätare, härdad struktur som passar för mästerligt smide.",al={"charred horn jämfört med galvanized horn","skiljer det sig från charred horn"}}},fx={["39b0e048"]={q="Vad är ett Galvanized Horn?",a="Ett Galvanized Horn är ett sällsynt, hårdnat horn från en chimärmatriark som lever i Stonetalon Mountains i Kalimdor. Till skillnad från vanliga chimärhorn har det härdats av den hårda, eldhärjade miljön i The Charred Vale, vilket gör det exceptionellt tåligt och eftertraktat av mästersmeder i både Alliansen och Horden.",al={"vad är galvanized horn","galvanized horns bakgrund"}}},fp="15,162,26.406.0,39.107.0,38.129.0,32.203.0,47.175.0"}
P.entries["item:gargantuan-tumor"] = {n="Gargantuan Tumor",s="Gargantuan Tumor är en massiv, sjuklig utväxt som slitits loss från den fördärvade timberlingen Oakenscowl i Teldrassil. Den är ett tydligt bevis på den onaturliga sjukdom som sprider sig bland varelserna vid Lake Al'Ameth.",h="Gargantuan Tumor är en massiv, sjuklig utväxt som slitits loss från den fördärvade timberlingen Oakenscowl i...",kw={"fördärvning","gargantuan tumor","lake al'ameth","oakenscowl","teldrassil","timberling"},ang={["class:Druid"]="För druider som strävar efter att vårda Teldrassils späda grenar är den groteska tumören en oroväckande påminnelse om att naturen bland grenarna är farligt sårbar för fördärvning.",["race:NightElf"]="Att se en aktad timberlingäldste förvandlad till ett vansinnigt, plågat monster understryker de växande miljöproblemen som möter kaldoreiernas nya hemland."},sec={{t="Plåga över sjön",b="Nära Lake Al'Ameths södra strand finns en grotta där Oakenscowl håller till, en gång en ädel timberlingäldste som fallit offer för en vidrig åkomma. Varelsen var synbart förgiftad av en enorm utväxt som förvrängde dess beteende och spred smitta till djurlivet omkring den. Att skära loss denna groteska tumör är avgörande, både för att få slut på bestens plågade framfart och för att låta lokala forskare undersöka plågan och förstå hur en sådan fasansfull sjukdom fick fäste i grenarna på det nyväxta världsträdet."}},faq={{q="Varifrån kommer Gargantuan Tumor?",a="Tumören hämtas från Oakenscowl, en stor fördärvad timberling som bor i en grotta vid Lake Al'Ameths södra strand i Teldrassil.",al={"tumörens ursprung","hur får man gargantuan tumor","oakenscowl byte"}},{q="Vad får tumören att växa på Oakenscowl?",a="Den är ett yttre symtom på den märkliga fördärvning som förgiftar timberlingarna och djurlivet kring Lake Al'Ameth. Oakenscowl var en gång en mäktig ledare för sitt folk, men dukade helt under för denna smittsamma utväxt.",al={"varför har oakenscowl en tumör","timberlingarnas sjukdom","fördärvning vid lake al'ameth"}},{q="Vem vill studera den här tumören?",a="Forskare i området behöver tumören för att undersöka den märkliga förruttnelse som drabbar traktens timberlingar och hoppas kunna ta reda på hur plågan kan behandlas eller hejdas.",al={"vem tar emot tumören","lämna in gargantuan tumor","lämna in oakenscowl-uppdraget"}}},fx={b9b4574c={q="Vad är Gargantuan Tumor?",a="Det är en enorm, grotesk utväxt som skurits loss från Oakenscowl, en förvriden timberlingäldste som lurar i en grotta längs södra stranden av Lake Al'Ameth. Tumören förgiftar tydligt varelsen och driver den till vansinne, vilket sprider onaturlig förruttnelse och sjukdom i vattnen och bland djurlivet i närheten.",al={"vad är gargantuan tumor","gargantuan tumor","oakenscowl-tumören"}}},fp="16,171,20.445.0,42.131.0,48.186.0,30.137.0"}
P.entries["item:garrick-s-head"] = {n="Garrick's Head",s="Vid Northshire Vineyards bevisar Garrick Padfoots avhuggna huvud att stråtrövaren är död. Myndigheterna vid Northshire Abbey kräver det för att betala ut belöningen.",h="Vid Northshire Vineyards bevisar Garrick Padfoots avhuggna huvud att stråtrövaren är död.",kw={"belöning","deputy willem","elwynn forest","garrick padfoot","garrick's head","northshire abbey","northshire valley"},ang={["class:Rogue"]="Som skurk visar du lokala busar att stråtröveri möts av dödliga, yrkesskickliga klingor.",["race:Human"]="Som människa blir Padfoots huvud ett tidigt slag mot laglösheten som sprider sig genom Elwynn Forest."},sec={{t="En stråtrövares slut",b="Garrick Padfoot och hans gäng trakasserade bönder och handelsmän i Northshire Valley i flera veckor. Stormwinds försvar var hårt ansträngt, så Garrick slog sig ned i en koja nära vingårdarna och plundrade förbipasserande handelsmän. De lokala vakterna var upptagna med kobolder och Defias-banditer, så Deputy Willem utlyste en belöning för laglösens död. Han sökte någon som var villig att döda Garrick och återvända med bevis."}},faq={{q="Vem var Garrick Padfoot?",a="Garrick Padfoot var en stråtrövare som terroriserade bönderna och vingårdsarbetarna i Northshire Valley samt handelsmän på resande fot. Han upprättade en utpost med sitt gäng öster om Northshire Abbey, på andra sidan floden.",al={"vem är garrick","garrick padfoots historia","vem var padfoot"}},{q="Varför behövs ett avhugget huvud för att få belöningen?",a="Deputy Willem och myndigheterna i Northshire kräver bevis på att Garrick är död innan de betalar ut belöningen.",al={"varför hans huvud","bevis på dödsfall","varför ta garricks huvud"}},{q="Var gömde sig Garrick Padfoot?",a="Padfoot gömde sig i en liten träkoja öster om Northshire Abbey, på andra sidan flodbron nära Northshire Vineyards.",al={"var är garrick","garricks koja plats","var hittar man garrick padfoot"}},{q="Vem betalar belöningen för Garricks huvud?",a="Deputy Willem utlyste belöningen och betalar ut den när han får Garricks huvud. Han är stationerad strax utanför ingången till Northshire Abbey.",al={"vem vill ha garricks huvud","lämna in garricks huvud","vem lämnade in garricks huvud"}}},fx={cb1a40d1={q="Vad är Garrick's Head?",a="Det avhuggna huvudet är ett fasansfullt bevis på att Garrick Padfoot, en ökänd mördare som har terroriserat bönder och handelsmän i Northshire Valley, har gått under. Om du tar den här trofén tillbaka till klostret bekräftar det att hans rövarband har förlorat sin ledare.",al={"vad är garricks huvud","föremålet garricks huvud","vem tillhör det här huvudet"}},["79b2de99"]={q="Varifrån kommer Garrick's Head?",a="Det tas direkt från Garrick Padfoot själv. Skurken slog läger i en liten stuga nära Northshire Vineyards, på andra sidan floden österut, omgiven av lojala busar som vaktade hans byte.",al={"var får man garricks huvud","vem släpper garricks huvud","garricks huvuds källa"}}},fp="14,153,14.393.0,24.197.0,51.103.0,33.116.0,39.134.0"}
P.entries["item:gazlowe-s-ledger"] = {n="Gazlowe's Ledger",s="I Ratchet jämför Gazlowe sina handelsböcker med hamnmanifestet när en leverans från Booty Bay försvinner.",h="I Ratchet jämför Gazlowe sina handelsböcker med hamnmanifestet när en leverans från Booty Bay försvinner.",kw={"booty bay","dizzywig","freebooters","gazlowe","liggare","ratchet","leverans","steamwheedle"},ang={["class:Rogue"]="Som rogue får du en inblick i flödet av smuggelgods, värdefull import och piratverksamhet längs The Barrens kust genom en goblinboss privata handelsliggare.",["faction:Horde"]="Som medlem av Horde kan du handla i Ratchet, en neutral hamn. När du hjälper Gazlowe att spåra stulna leveranser behåller du de lokala Steamwheedle-myndigheternas förtroende."},sec={{t="Ratchets handelsregister",b="Gazlowe bokför handelsvaror i Ratchet i en personlig liggare. Där noteras importerade lådor, utgående last och lagerförråd. När en leverans från Booty Bay saknas jämför Gazlowe sitt förväntade lager med kajregistren som Wharfmaster Dizzywig för."},{t="Avslöja stölden",b="Gazlowe och de andra goblinerna jämför liggaren med Dizzywigs hamnloggar och upptäcker att lasten aldrig nådde hamnlagret. Avvikelsen bekräftar Gazlowes misstanke om att lådorna stals innan de kom i land. Southsea Freebooters längs den närbelägna Merchant Coast bär skulden."}},faq={{q="Vad är Gazlowe's Ledger?",a="Gazlowe's Ledger förtecknar varor som väntas in och förvaras i Ratchet. Gazlowe skickar den till hamnen så att uppgifterna kan jämföras med kajregistren när en leverans saknas.",al={"gazlowes liggare","ratchets liggare","gazlowes lagerbok"}},{q="Vem behöver granska liggaren?",a="Wharfmaster Dizzywig granskar Gazlowe's Ledger mot sina fraktloggar. Han ansvarar för kajerna i Ratchet och kan avgöra om saknade varor hamnat fel eller aldrig lossats.",al={"vem ska jag lämna liggaren till","mottagare av liggaren","dizzywigs liggare"}},{q="Vilken last saknades enligt liggaren?",a="Gazlowe väntade på sin senaste leverans från Booty Bay. Dizzywig hittar inget avvikande i sina loggar, men säger att varor från Undermine väntar på att Gazlowe ska hämta dem.",al={"vad saknar gazlowe","saknat lastgods"}},{q="Vad händer efter att liggaren har kontrollerats?",a="Dizzywig kontrollerar om leveransen passerade genom hamnen. När han upptäcker att den inte gjorde det skickas liggaren tillbaka till Gazlowe, vilket bekräftar att Southsea Freebooters troligen lade beslag på lasten till sjöss.",al={"vad händer med liggaren","efter dizzywig har kontrollerat"}}},fx={d44950a4={q="Varifrån kommer Gazlowe's Ledger, och vem har den?",a="Förteckningen tillhör Gazlowe, goblinchefen som styr hamnstaden Ratchet. Den är hans personliga inventarielista och dokumenterar inkommande och utgående frakt som skeppas över Great Sea mellan Ratchet och andra gobliners handelsnav, som Booty Bay.",al={"vem skrev gazlowes förteckning","varifrån kommer gazlowes förteckning","gazlowes förtecknings ursprung"}},c4547cde={q="Varför behövs Gazlowe's Ledger just nu?",a="Gazlowe misstänker att en länge försenad leverans från Booty Bay har stulits av Southsea Freebooters. Innan han drar förhastade slutsatser behöver han att du tar hans förteckning till Wharfmaster Dizzywig vid hamnen, så att de kan jämföra inventarielistorna med hamnens loggböcker och utesluta ett skrivfel.",al={"varför vill någon ha gazlowes förteckning","varför behövs gazlowes förteckning","vad används gazlowes förteckning till"}}},fp="16,117,28.262.0,20.299.1,25.176.0,32.176.0,37.173.0,41.195.1"}
P.entries["item:gem-of-anacondra"] = {n="Gem of Anacondra",s="Gem of Anacondra är en av fyra drömgemmer som de korrumperade ormförrådarledarna håller i Wailing Caverns. Lady Anacondra bär den som ett påtagligt bevis på sitt nederlag och på att Mardrömmens spridning över The Barrens har hejdats.",h="Gem of Anacondra är en av fyra drömgemmer som de korrumperade ormförrådarledarna håller i Wailing Caverns.",kw={"drömgem","druids of the fang","gem of anacondra","lady anacondra","fangs ledare","nara wildmane","wailing caverns"},ang={["class:Druid"]="För Cenarion-druider är det en högtidlig plikt att hämta den här gemmen och fälla en syster som överlät sitt sinne och sina skepnader åt den korrumperande Emerald Nightmare.",["race:Tauren"]="Att återta gemmen hjälper Nara Wildmane i Thunder Bluff direkt och skingrar de mörka visioner som plågar Shu'halos slummer på Elder Rise."},sec={{t="Ett korrumperat fokus",b="När Naralex gick in i sin djupa slummer för att återföra vatten och liv till det torra The Barrens, trängde Emerald Nightmare in i hans tankar och förvrängde hans närmaste lärjungar. Lady Anacondra och hennes medkonspiratörer övergav sina traditionella seder och blev Druids of the Fang. De förvred sitt ädla, livgivande syfte till en giftig vanföreställning. Gem of Anacondra är en av de fyra drömgemmer som dessa ormlika ledare bär. Den fokuserar deras korrumperade band till The Emerald Dream och förankrar mardrömmen i grottsystemet."},{t="Att rena visionen",b="Nara Wildmane och Cenarion-druidernas krets i Thunder Bluff upptäckte att deras egen slummer plågades av visioner och onda ansikten från ledarna för Fang. De hävdar att Gem of Anacondra måste hämtas, tillsammans med stenarna från Cobrahn, Pythas och Serpentis, för att bekräfta att Lady Anacondra har fällts. Då kan den förtryckande mardrömmen lyftas från sinnena hos Kalimdors väktare av balansen."}},faq={{q="Vad är Gem of Anacondra?",a="Det är en drömgem som Lady Anacondra bär. Hon är en av de fyra ledarna för de förvridna Druids of the Fang som håller till i Wailing Caverns.",al={"vad är anacondras gem","anacondras gem","vad gör gem of anacondra"}},{q="Vem vill ha den här gemmen?",a="Nara Wildmane, en tauren-druid på Elder Rise i Thunder Bluff, söker efter gemmen och de tre andra drömgemmerna för att befria sitt sinne från mardrömmar och skydda The Barrens.",al={"vem tar emot gem of anacondra","var lämnar jag in anacondras gem","lämna in gem of anacondra"}},{q="Var finns Gem of Anacondra?",a="Lady Anacondra bär gemmen. Hon lurar i de slingrande underjordiska gångarna i Wailing Caverns, mitt i The Barrens.",al={"var droppar den","vem droppar gem of anacondra","lady anacondras plats"}},{q="Varför är drömgemmerna viktiga?",a="De fyra gemmerna hålls av de korrumperade ledarna för Druids of the Fang. När de samlas in bekräftas det att ledarna har undanröjts, och deras grepp om korruptionen i The Emerald Dream i området bryts.",al={"varför fyra gemmer","drömgemmernas syfte","fangs ledares gemmer"}}},fx={["2e0de493"]={q="Varifrån kommer Gem of Anacondra, och vem skapade den?",a="Lady Anacondra bär ädelstenen djupt inne i Wailing Caverns. Det är okänt vem som slipade eller förtrollade den, men den är en av drömädelstenarna som innehas av de fyra ledarna för Druids of the Fang. Dessa korrumperade nattalver tillhörde en gång en ädel krets som ägnade sig åt att hela The Barrens. Nu kanaliserar de sina förvridna visioner av The Emerald Dream genom dessa stenar.",al={"ursprung gem of anacondra","vem skapade gem of anacondra","var fick anacondra sin ädelsten"}}},fp="16,241,17.531.0,20.388.1,29.139.0,19.183.0,40.149.0,33.205.0"}
P.entries["item:gem-of-cobrahn"] = {n="Gem of Cobrahn",s="Gem of Cobrahn är en drömpärla som bärs av Lord Cobrahn, en av de korrumperade ledarna för Druids of the Fang i Wailing Caverns. Den fungerar både som fokus för hans förvridna drömmar och som fysiskt bevis som Nara Wildmane behöver för att bekräfta hans nederlag.",h="Gem of Cobrahn är en drömpärla som bärs av Lord Cobrahn, en av de korrumperade ledarna för Druids of the Fang...",kw={"drömpärla","druids of the fang","gem of cobrahn","fang-ledarna","lord cobrahn","nara wildmane","wailing caverns"},ang={["class:Druid"]="För Cenarion-druiderna innebär återtagandet av Gem of Cobrahn det tragiska men nödvändiga slutet för en fallen broder som övergav naturens harmoni för The Emerald Nightmare.",["race:Tauren"]="Druiderna i Thunder Bluff håller noga uppsikt över The Barrens. Att ta Cobrahns pärla skyddar slätterna och jaktmarkerna direkt från onaturlig förvanskning."},sec={{t="Ett fokus för korrumperade drömmar",b="När nattalven Naralex gick in i The Emerald Dream för att återställa Kalimdors karga slätter förvrängde hans mardröm både Wailing Caverns och hans lärjungar. En av dem var Cobrahn, som övergav Cenarion Circles fredliga seder och antog ormens skepnad. Lord Cobrahn bär en av de fyra drömpärlor som förankrar ledarnas grepp om de underjordiska vattenvägarna, och använder den för att kanalisera de förvridna drömmar som hotar att förvandla The Barrens till ett giftigt träsk."},{t="Återställa balansen",b="I Thunder Bluff plågas tauren-druiden Nara Wildmane av mardrömmar som skickas av de avfälliga Druids of the Fang. För att rena de underjordiska källorna och skydda Kalimdor från deras vision måste äventyrare utforska grottorna, döda Lord Cobrahn och hans tre medkonspiratörer och återta deras drömpärlor. När Cobrahns pärla återlämnas till Cenarion-druiderna upphör hans korrumperande inflytande över den sovande Naralex."}},faq={{q="Vad är Gem of Cobrahn?",a="Det är en drömpärla som innehas av Lord Cobrahn, en fallen druid som leder Druids of the Fang i Wailing Caverns. Den fungerar som en kanal för hans mardrömsförvridna krafter.",al={"gem of cobrahn","cobrahns pärla","vad är cobrahns pärla"}},{q="Vem vill ha Gem of Cobrahn?",a="Nara Wildmane, en tauren-druid på Elder Rise i Thunder Bluff, ber om pärlan tillsammans med tre andra för att sätta stopp för Druids of the Fang.",al={"vem behöver gem of cobrahn","lämna in cobrahns pärla","vem tar cobrahns pärla"}},{q="Hur många pärlor krävs för att slutföra uppdraget?",a="Fyra pärlor krävs: Gem of Cobrahn, Gem of Anacondra, Gem of Pythas och Gem of Serpentis. Var och en innehas av en av de fyra ormledarna i grottorna.",al={"hur många drömpärlor","fang-ledarnas pärlor","alla fang-pärlor"}},{q="Vem är Lord Cobrahn?",a="Lord Cobrahn var en gång lärjunge till Naralex. När Naralex vision förvandlades till en mardröm antog Cobrahn och flera andra druider ormens skepnad och bildade Druids of the Fang.",al={"vem är cobrahn","lord cobrahn bakgrund","cobrahn"}}},fp="14,256,27.491.0,17.430.1,27.170.0,29.155.0,47.171.0,20.192.0"}
P.entries["item:gem-of-pythas"] = {n="Gem of Pythas",s="Gem of Pythas är en av fyra fördärvade drömädelstenar som bärs av ledarna för Druids of the Fang i Wailing Caverns. Den hålls av Lord Pythas och ger näring åt mardrömmen som förvrider den underjordiska oasen och hotar The Barrens.",h="Gem of Pythas är en av fyra fördärvade drömädelstenar som bärs av ledarna för Druids of the Fang i Wailing...",kw={"the barrens","drömädelsten","druids of the fang","gem of pythas","lord pythas","nara wildmane","wailing caverns"},ang={["class:Druid"]="För Cenarion-druider är det en dyster plikt att återta ädelstenen, eftersom den står för hur Naralex innersta krets har förfallit fullständigt till ormlika fasor.",["race:Tauren"]="De förvridna ritualerna i grottorna hotar den bräckliga balansen i The Barrens, vilket gör det avgörande att återta ädelstenarna för att skydda schamanernas och druidernas hemland."},sec={{t="En behållare för mardrömmen",b="När Naralex trädde in i The Emerald Dream för att återställa det torra The Barrens förvrängdes hans ädla vision till en levande mardröm. Hans främsta följare föll med honom, kallade sig Druids of the Fang och sökte omvandla ytvärlden till en giftig djungel. Lord Pythas bär denna resonanta sten, en av fyra drömädelstenar som förankrar fördärvet i grottorna. Ädelstenen tjänar som en kanal för deras mörka plan och som bevis för druiderna i Thunder Bluff på att Pythas förvridna trans äntligen har brutits."}},faq={{q="Vad används Gem of Pythas till?",a="Ädelstenen förs till Nara Wildmane i Thunder Bluff tillsammans med ädelstenarna från Cobrahn, Anacondra och Serpentis. Tillsammans fullbordar de uppdraget att sätta stopp för de förrädiska ledarna för Druids of the Fang.",al={"gem of pythas användning","vad gör man med gem of pythas","pythas ädelstensuppdrag"}},{q="Vem bär den här ädelstenen?",a="Den hålls av Lord Pythas, en fallen Night Elf-druid som bor djupt inne i Wailing Caverns i The Barrens.",al={"vem släpper gem of pythas","pythas plats","var får man tag på gem of pythas"}},{q="Varför vill druiderna i Thunder Bluff ha ädelstenen?",a="Nara Wildmane och Cenarion-druiderna i Thunder Bluff hemsöks av fördärvet som strålar ut från Wailing Caverns. Genom att säkra ädelstenarna bevisar man att de fyra vanställda ledarna har dödats och hindrar mardrömmen från att sprida sig vidare in i The Barrens.",al={"varför vill nara ha ädelstenarna","nara wildmane pythas"}},{q="Finns det andra ädelstenar som den här?",a="Ja. Lord Pythas är en av fyra ledare. De andra, Lady Anacondra, Lord Cobrahn och Lord Serpentis, bär varsin drömädelsten djupt inne i grottan.",al={"andra drömädelstenar","fang-ädelstenar","ädelstenar i wailing caverns"}}},fx={["3d8d64d3"]={q="Vad är Gem of Pythas?",a="Gem of Pythas är en av fyra drömädelstenar som bärs av ledarna för Druids of the Fang i Wailing Caverns. Lord Pythas innehar reliken, som förkroppsligar det mörka, ormlika vansinne som korrumperade dessa en gång ädla nattalver. Den binder deras förvridna visioner av The Emerald Dream i fysisk form.",al={"gem of pythas","vad är gem of pythas","vad är den här ädelstenen"}}},fp="13,235,25.518.0,35.209.0,21.111.0,48.259.0,35.159.0"}
P.entries["item:gem-of-serpentis"] = {n="Gem of Serpentis",s="Gem of Serpentis är en drömädelsten som bärs av Lord Serpentis, en av de fyra ledarna för Druids of the Fang i Wailing Caverns. Den fungerar som en fokuserande kanal för den förvridna mardröm som omformar grottsystemet och hotar The Barrens.",h="Gem of Serpentis är en drömädelsten som bärs av Lord Serpentis, en av de fyra ledarna för Druids of the Fang...",kw={"druids of the fang","gem of serpentis","fangens ledare","lord serpentis","nara wildmane","the barrens","wailing caverns"},ang={["class:Druid"]="Drömädelstenarna som Serpentis och hans sekt bär på visar den fruktansvärda risken med att gå in i djup transgemenskap med drömmen utan vaksam andlig disciplin.",["race:Tauren"]="Att bryta Serpentis grepp om ädelstenen hjälper till att befria Thunder Bluffs schamaner och druider från de mörka syner som stör deras sömn i Mulgore."},sec={{t="Hjärtat i ormdrömmen",b="När Naralex sömn i Wailing Caverns föll offer för Emerald Nightmare förvandlades hans mest hängivna följare till de fanatiska Druids of the Fang. Lord Serpentis är en av sektens fyra ledare. Liksom de andra tre bär Serpentis en förtrollad drömädelsten som förankrar deras gemensamma vilja i den fördärvade visionen. Att återta ädelstenen bryter Serpentis grepp om grottans ekosystem och slår direkt mot ledarskapet bakom fördärvet som sprider sig över The Barrens."},{t="Bevis till Thunder Bluff",b="Taurendruiderna på Elder Rise i Thunder Bluff, särskilt Nara Wildmane, plågas av livfulla mardrömmar som orsakas av fördärvet under savannen. Att återta Gem of Serpentis tillsammans med ädelstenarna från Cobrahn, Anacondra och Pythas ger påtagliga bevis för att den avfälliga ordens ledare har fallit och lättar mardrömmens grepp om Cenarion Circle i Mulgore."}},faq={{q="Var kommer Gem of Serpentis ifrån?",a="Ädelstenen bärs av Lord Serpentis, en av de fyra ledarna för Druids of the Fang, som håller till djupt inne i Wailing Caverns vindlande vattenvägar.",al={"vem släpper gem of serpentis","var får man serpentis ädelsten","serpentis ädelstens plats"}},{q="Vad har ädelstenen för syfte?",a="Den är en av fyra fokusädelstenar som Druids of the Fang-ledarna använder för att kanalisera mardrömmen som förvrider den underjordiska oasen. Nara Wildmane i Thunder Bluff vill ha den som bevis för att Lord Serpentis har besegrats.",al={"varför behöver jag gem of serpentis","vad används gem of serpentis till"}},{q="Vem vill ha alla fyra drömädelstenarna?",a="Nara Wildmane, en druid på Elder Rise i Thunder Bluff, ber äventyrare att hämta ädelstenarna från Cobrahn, Anacondra, Pythas och Serpentis åt henne för att bryta mardrömmens grepp om regionen.",al={"vem tar emot ädelstenarna","lämna in serpentis ädelsten","lämna in till fang-ledarna"}},{q="Vem var Lord Serpentis innan han bar den här ädelstenen?",a="Han var ursprungligen en lärjunge till Naralex som gick in i grottorna för att återställa frodig växtlighet i The Barrens, men Emerald Nightmare förvrängde hans ädla ambitioner till en fanatisk önskan att omforma världen till en ormgestalt.",al={"lord serpentis berättelse","vem är serpentis"}}},fx={["58ca37b7"]={q="Vad är Gem of Serpentis?",a="Gem of Serpentis är en av fyra drömädelstenar som innehas av ledarna för Druids of the Fang i Wailing Caverns. Lord Serpentis bär den själv. Den är en symbol och ett redskap för de korrumperade druiderna, som vill förvrida The Barrens så att platsen motsvarar deras mörka visioner.",al={"gem of serpentis bakgrund","vad är serpentis ädelsten","lord serpentis ädelsten"}}},fp="16,245,29.501.0,23.375.1,42.158.0,31.226.0,30.199.0,48.227.0"}
P.entries["item:gerenzo-s-mechanical-arm"] = {n="Gerenzo's Mechanical Arm",s="Gerenzo's Mechanical Arm är den inopererade protesen som togs från den skurkaktige ingenjören Gerenzo Wrenchwhistle i Stonetalon Mountains. Den är ett obestridligt bevis på hans död för goblinagenter som vill röja undan konkurrensen.",h="Gerenzo's Mechanical Arm är den inopererade protesen som togs från den skurkaktige ingenjören Gerenzo...",kw={"arm","cragpool lake","gerenzo","mekanisk arm","sputtervalve","stonetalon","wrenchwhistle","ziz fizziks"},ang={["profession:Engineering"]="Armen visar hur olika de två ingenjörstraditionerna är: gnomer offrar gärna sin egen biologi för mekanisk precision, medan gobliner föredrar yttre tillägg och rå eldkraft.",["race:Gnome"]="Gerenzo är ett dystert exempel på gnomisk uppfinningsrikedom i sin ytterlighet, där mekaniska ersättningar går långt bortom vanliga medicinska proteser och blir sjuklig självförstärkning."},sec={{t="En bisarr uppfinning",b="Gerenzo Wrenchwhistle drev självmodifiering till en grotesk ytterlighet och fäste surrande kugghjul och metall direkt på sin sviktande kropp. Högt ovanför Cragpool Lake ersatte den avfälliga gnomens naturliga lemmar med avancerade maskiner. När goblintinkaren Ziz Fizziks vill röja Gerenzo ur vägen för att imponera på sina överordnade, är den här särskiljande mekaniska armen den enda trofé som är tillräckligt unik för att utgöra obestridliga bevis på ingenjörens död."},{t="Gnomisk filosofi, goblinsk kritik",b="För en goblin verkar det meningslöst att amputera en fullt fungerande arm bara för att sätta dit en mekanisk ersättare. Ziz Fizziks påpekade berömt att en riktig gobliningenjör helt enkelt skulle behålla båda sina biologiska armar och montera en mekanisk tredje arm i stället. Trots den filosofiska klyftan gör den avhuggna lemmen Sputtervalve nöjd och hjälper Ziz att ansöka om ett uppdrag i Gadgetzan eller Undermine."}},faq={{q="Var kommer Gerenzo's Mechanical Arm ifrån?",a="Den tas från Gerenzo Wrenchwhistle, som leder avverknings- och ingenjörsarbetet högt ovanför Cragpool Lake, nära vattenhjulet i Stonetalon Mountains.",al={"vem tappar gerenzo arm","gerenzo arm plats","var får man gerenzo mechanical arm"}},{q="Varför vill Ziz Fizziks ha armen?",a="Ziz behöver avgörande bevis till sin överordnade Sputtervalve för att visa att Gerenzo är död. Eftersom Gerenzo förändrade sin egen kropp så mycket går hans unika protesarm inte att förfalska eller förväxla med någon annans.",al={"varför vill ziz ha armen","lämna in armuppdrag","bevis på gerenzos död"}},{q="Varför ersatte Gerenzo sin egen arm?",a="Enligt Ziz Fizziks verkade Gerenzos kött ruttna bort. Av desperation eller genom gnomisk experimentlusta fäste Gerenzo maskiner vid kroppen och ersatte sina sviktande lemmar med mekaniska motsvarigheter.",al={"varför är gerenzo en cyborg","gerenzos ruttnande kött","varför mekanisk arm"}}},fx={["379afa91"]={q="Vad är Gerenzo's Mechanical Arm?",a="Det är en grov cybernetisk protes som ympats direkt på kroppen tillhörande Gerenzo Wrenchwhistle, en sjuklig gnomisk uppsyningsman som håller till nära vattenhjulet ovanför Cragpool Lake. I stället för att leva med naturligt kött och blod har Gerenzo förstärkt sin ruttnande kropp med urverkskugghjul och metallplattor. Denna avancerade mekaniska lem är hans mest igenkännliga kännetecken.",al={"vad är gerenzos arm","gerenzo arm föremål","gerenzos mekaniska arm"}}},fp="24,200,19.360.0,35.365.1,46.165.0,35.157.0,36.221.0"}
P.entries["item:ghost-hair-comb"] = {n="Ghost Hair Comb",s="Ghost Hair Comb är ett kusligt groomingredskap, sammanflätat med Blind Marys spöklika hårstrån. Madame Eva skickar kammen till spöket, och den blir ett redskap för en tragisk insikt innan det uppsamlade håret spinns till kuslig tråd.",h="Ghost Hair Comb är ett kusligt groomingredskap, sammanflätat med Blind Marys spöklika hårstrån.",kw={"blind mary","darkshire","duskwood","ghost hair comb","ghost hair thread","madame eva"},ang={["class:Priest"]="Marys förtvivlade reaktion på kammen speglar den kvardröjande dödliga fåfänga och djupa andliga plåga som är vanlig bland Duskwoods rastlösa döda.",["profession:Tailoring"]="De eteriska hårstråna som plockas från kammen blir ett kusligt tyg, skördat inte från får eller silkesmaskar, utan spunnet direkt ur spektral sorg."},sec={{t="Tragisk fåfänga",b="Madame Eva i Darkshire skickar kammen till spöket Blind Mary, som bor i ett ensligt, förfallet hus i utkanten av Duskwood. När kammen räcks fram ryggar spöket tillbaka i ren fasa och tvingas plötsligt inse den smärtsamma sanningen: hon är inte längre den vackra levande kvinna hon en gång var. I sin sorg och förtvivlan stöter Mary bort kammen, som blir kvar med hårstrån från hennes eget spöklika hår intrasslade i sig."},{t="Spunnen ur sorg",b="När kammen återlämnas till Madame Eva i Darkshire får håret som fastnat mellan kammens tänder ett långt mer esoteriskt syfte. Eva samlar de skira spektrala fibrerna och spinner dem till Ghost Hair Thread, ett magiskt hantverksmaterial som används för att sy ihop och binda ockulta skapelser i Duskwoods dunkla värld."}},faq={{q="Vad är Ghost Hair Comb?",a="Det är en kam som Madame Eva i Darkshire skickar till spöket Blind Mary. När Mary använder den eller kastar den åt sidan fastnar hårstrån från hennes spektrala hår i den, och Eva spinner sedan håret till Ghost Hair Thread.",al={"ghost hair comb","vad är det här för kam","evas kam"}},{q="Varför skriker Blind Mary och stöter bort kammen?",a="Kammen påminner Blind Mary om hennes förlorade dödliga skönhet. När hon får den tvingas hon möta sin sanna natur: ett skräckinjagande spektralt monster, inte den vackra kvinna hon minns från livet.",al={"varför skriker blind mary","blind marys reaktion på kammen","varför kastade mary bort kammen"}},{q="Vem vill ha tillbaka kammen?",a="Madame Eva, spåkvinnan och magikern som bor i staden Darkshire, ber att kammen ska lämnas tillbaka till henne så att hon kan ta till vara det fastnade spökhåret.",al={"vem vill ha kammen","var ska kammen lämnas","till vem ska kammen lämnas tillbaka"}},{q="Vad används spökhåret till?",a="Madame Eva spinner de spöklika hårstråna som samlats från kammen till Ghost Hair Thread, en ovanlig reagens som behövs för ockulta ritualer och hantverk i Duskwood.",al={"vad används spökhår till","vad är ghost hair thread","vad används ghost hair thread till"}}},fp="15,168,15.357.0,16.286.1,28.163.0,47.204.0,28.134.0,32.130.0"}
P.entries["item:ghost-hair-thread"] = {n="Ghost Hair Thread",s="Ghost Hair Thread är ett sällsynt, övernaturligt material som Madame Eva spinner i Darkshire. Det sägs vara laddat med starka ockulta krafter som kan binda andliga energier och till och med sy in liv i livlösa ting. Eremiten Abercrombie ber om det för att skydda sin förfallna hydda mot rastlösa spöken.",h="Ghost Hair Thread är ett sällsynt, övernaturligt material som Madame Eva spinner i Darkshire.",kw={"abercrombie","darkshire","duskwood","ghost hair thread","madame eva","raven hill","andar"},ang={["class:Warlock"]="Trådens förmåga att binda andliga väsen och ge liv åt livlös materia påminner om de mörka konsterna att manipulera själar och binda konstrukter.",["profession:Tailoring"]="Medan vanliga skräddare arbetar med ull, siden och magväv visar Madame Evas spöklika tråd att tyg kan spinnas direkt ur övernaturliga essenser och bära på förtrollningar."},sec={{t="Spunnet ur andevärlden",b="Ghost Hair Thread, som spinns av spåkvinnan Madame Eva i Darkshire, är mycket mer än vanligt material för sömnad. Enligt Eva har den spektrala tråden många ockulta egenskaper, från att binda illvilliga andar till att sy in liv i livlösa föremål. Dess eteriska natur gör den värdefull för ritualer och skyddsbesvärjelser i Duskwoods förbannade rike."},{t="Abercrombies skydd",b="Eremiten Abercrombie, som håller sig för sig själv i en fallfärdig hydda strax norr om Raven Hill Cemetery, ber resande att hämta tråden från Darkshire. Han säger att han desperat behöver spänna tråden över fönstren och dörrkarmen för att hindra de vandrande odöda från kyrkogården från att ta sig in i hans hem. Men med tanke på trådens märkliga förmåga att sy liv i livlösa ting förblir dess egentliga syfte ett oroande mysterium."}},faq={{q="Vad är Ghost Hair Thread?",a="Det är ett magiskt hantverksmaterial som Madame Eva spinner i Darkshire. Det har särskilda ockulta egenskaper och kan binda andar eller sy liv i livlösa ting.",al={"spökhår","vad är ghost hair thread","spöktråd"}},{q="Varför vill Abercrombie ha Ghost Hair Thread?",a="Abercrombie säger att han behöver tråden för att kanta sina fönster och dörröppning och skapa en skyddande barriär mot de rastlösa andar som strövar utanför nära Raven Hill Cemetery.",al={"abercrombies tråd","varför abercrombie vill ha tråden","abercrombies skydd"}},{q="Vem tillverkar tråden?",a="Madame Eva, Darkshires spåkvinna och sierska, tillverkar och tillhandahåller tråden på begäran.",al={"vem spinner ghost hair thread","madame evas tråd"}},{q="Kan spelare använda tråden för sömnad?",a="Nej. Trots sitt namn och sina magiska egenskaper är den ett särskilt föremål för ett uppdrag, avsett enbart att lämnas till Abercrombie. Den kan inte användas i vanliga hantverksrecept.",al={"ghost hair thread för sömnad","kan jag hantverka med ghost hair thread"}}},fp="17,211,24.234.0,18.290.1,26.121.0,44.129.0,21.86.0,41.96.0"}
P.entries["item:ghoul-fang"] = {n="Ghoul Fang",s="Ghoul Fangs är ohyggliga troféer som tas från de odöda som stryker omkring i Duskwoods fördärvade dungar och på dess kyrkogårdar. I Darkshire använder sierskan Madame Eva dem som viktiga ingredienser när hon tillverkar skyddande talismaner åt resenärer som möter det annalkande mörkret.",h="Ghoul Fangs är ohyggliga troféer som tas från de odöda som stryker omkring i Duskwoods fördärvade dungar och...",kw={"darkshire","duskwood","ghoul fang","ghouls","madame eva","totem of infliction","odöda"},ang={["faction:Alliance"]="För alliansens äventyrare som hjälper den hårt ansatta staden Darkshire blir dessa huggtänder ett sätt att förvandla Duskwoods fasor till redskap för överlevnad mot den annalkande plåga som liknar Scourge."},sec={{t="Troféer från The Restless Dead",b="Duskwoods skuggiga skog kryllar av glupska odöda, från köttätare som lurar nära gravarna till förruttnade lik som strövar omkring i skogen. Att ta en huggtand från dessa monstruösa varelser är både ett fasansfullt arbete och ett bevis på att man överlevt de glupska döda som hotar Darkshires gränser."},{t="Ockulta ingredienser",b="Madame Eva, Darkshires siare och mystiker, ser fruktansvärda omen virvla kring resenärer som vågar ta sig genom Duskwood. Hon binder den slumrande nekrotiska essensen i ghoulfangar samman med skelettfingrar och spindelgift för att förtrolla Totem of Infliction och förvandla skogens mörka krafter till en skyddande amulett mot våldsamma angrepp."}},faq={{q="Var hittar man Ghoul Fangs?",a="De samlas in från olika sorters ghouls i Duskwood, däribland Plague Spreaders, Brain Eaters, Bone Chewers, Fetid Corpses, Rotted Ones och Flesh Eaters, som hemsöker kyrkogårdar och ensliga stigar.",al={"var faller ghoul fangs","vem släpper ghoul fangs","ghoul fang plats"}},{q="Vem vill ha Ghoul Fangs?",a="Madame Eva, mystikern som bor i Darkshire, behöver dem som en del av en ritual för att skapa en skyddande amulett kallad Totem of Infliction.",al={"vem behöver ghoul fangs","lämna in ghoul fang","madame evas uppdrag"}},{q="Varför behöver Madame Eva dem?",a="Eva känner att faror hotar resenärerna och använder huggtänderna tillsammans med skelettfingrar och spindelgift för att förtrolla en skyddande totem som straffar dem som angriper bäraren.",al={"varför ghoul fangs","material till totem of infliction","vad gör madame eva med huggtänder"}}},fx={["7c703fef"]={q="Vad är en Ghoul Fang?",a="En Ghoul Fang är en vass tand som brutits loss från gapet på de odöda gastar som hemsöker Duskwood. Huggtänderna är besmittade av nekromantisk förruttnelse och hunger efter kött, och bär fortfarande spår av den mörka magi som ger de odöda liv. Därför är de kraftfulla ingredienser i skyddande amuletter och ockulta ritualer.",al={"vad är ghoul fang","ghoul fang bakgrund","om ghoul fang"}},["87f3f6fc"]={q="Varifrån kommer en Ghoul Fang?",a="Dessa huggtänder kommer från olika odöda gastar som strövar omkring i Duskwoods skuggor, till exempel Plague Spreaders, Brain Eaters, Bone Chewers och Flesh Eaters. De tillverkas inte för hand, utan samlas direkt från käftarna på de vandrande döda.",al={"ghoul fang ursprung","varifrån kommer ghoul fangs","vem släpper ghoul fangs"}}},fp="10,200,29.267.0,15.312.0,31.179.0,22.116.0,30.185.0"}
P.entries["item:ghoul-rib"] = {n="Ghoul Rib",s="Ghoul Rib samlas in från de odöda som stryker omkring i Duskwoods hemsökta dungar och gravplatser. Eremiten Abercrombie påstår att han behöver dem som material till en grotesk avbildning som ska hålla de människoätande fasorna nära hans skjul på avstånd.",h="Ghoul Rib samlas in från de odöda som stryker omkring i Duskwoods hemsökta dungar och gravplatser.",kw={"abercrombie","beggar's haunt","bone chewer","darkshire","duskwood","flesh eater","ghoul rib","gastavbildning","odöda"},ang={["class:Paladin"]="Att hantera de rastlösa dödas skändade ben är motbjudande arbete, men att hjälpa en isolerad eremit mot glupska vidunder går hand i hand med att skydda de levande från Duskwoods fasor.",["class:Priest"]="Den förvridna återuppväckelse som håller dessa ben samman speglar den djupa skugga som fallit över Duskwood och förvandlar stupade bybor till glupska asätare."},sec={{t="Ett makabert skydd",b="Duskwoods förbannade skog kryllar av våldsamma odöda, däribland glupska gastar som Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones och Plague Spreaders. Abercrombie, en excentrisk enstöring som bor isolerad i ett skjul norr om Raven Hill Cemetery, ber förbipasserande resenärer om dessa kraftiga, förruttnade ben. Han påstår att det gör honom sårbar att bo utanför Night Watchs beskydd i Darkshire, och att en skrämmande avbildning av gastrevben ska fungera som en fågelskrämma och skrämma bort kringströvande flockar av de döda."},{t="Misstankar kring skjulet",b="Att samla delar från dödade odöda är vanligt nog för att överleva i fientliga områden, men Abercrombies särskilda fascination för gastars anatomi väcker frågor. I stället för att söka skydd bakom Darkshires palissader eller förlita sig på vigda skyddsmärken envisas eremiten med att samla rått nekromantiskt inälvsmaterial för att förstärka sitt avskilda hem."}},faq={{q="Vilka varelser bär på Ghoul Rib?",a="De kan samlas in från olika sorters gastar i Duskwood, däribland Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones och Plague Spreaders. Dessa monster hemsöker gamla gravgårdar, vägkantsruiner och övergivna gårdar runt om i skogen.",al={"var får man ghoul rib","vilka gastar har revben","källor till ghoul rib"}},{q="Varför vill Abercrombie ha benen?",a="Abercrombie påstår att han bor för långt från Darkshire för att kunna förlita sig på Night Watchs beskydd. Han ber om revbenen för att bygga en enkel fågelskrämma eller avbildning som ska avskräcka kringströvande odöda från att banka på hans väggar.",al={"varför behöver abercrombie revben","syftet med gastavbildningen","vad gör abercrombie med revbenen"}},{q="Håller fågelskrämmor verkligen gastar borta?",a="Odöda saknar i allmänhet rädsla och drivs helt av tanklös hunger eller mörkt nekromantiskt tvång. Tanken att tanklösa gastar skulle fly från en fågelskrämma gjord av ben är ovanlig, men Abercrombie insisterar på att den ska hålla hans hem tryggt.",al={"fungerar avbildningen","kan avbildningar skrämma odöda","är gastar rädda för fågelskrämmor"}},{q="Var ligger Abercrombies skjul?",a="Abercrombie bor i ett förfallet skjul i västra Duskwood, strax norr om Raven Hill Cemetery.",al={"abercrombies plats","var finns eremiten","var lämnar man in ghoul rib"}}},fx={["3e8ffb18"]={q="Vad är en Ghoul Rib?",a="En Ghoul Rib är precis vad det låter som: ett ben från de ruttnade, återupplivade odöda som stryker omkring i Duskwood. Revbenen tas från odjur som Flesh Eaters, Brain Eaters och Bone Chewers. Dessa kvarlevor bär fortfarande spår av den vidriga magi som ger de vandrande döda liv i denna hemsökta skog.",al={"ghoul rib information","vad är ghoul ribs","ghoul ribs föremål"}},f2829c95={q="Varifrån kommer Ghoul Ribs?",a="Dessa revben kommer direkt från de olika gastar som hemsöker Duskwoods dystra vägar och gravhögar. De är naturliga skelettdelar, inte tillverkade reliker, och tas från odöda vidunder som Plague Spreaders och Rotted Ones. De strövar långt bortom den relativa tryggheten i Darkshire.",al={"ghoul rib källa","var får man ghoul ribs","vem skapade ghoul ribs"}}},fp="9,197,15.361.0,27.219.1,32.231.0,38.198.0,40.164.0,37.84.0"}
P.entries["item:giant-crocolisk-skin"] = {n="Giant Crocolisk Skin",s="Giant Crocolisk Skin är tjocka hudar från de enorma kräldjur som hör hemma i Wetlands träskmarker. De är eftertraktade av Menethil Harbors hantverkare för läderarbete, men jakten är farlig och har lemlästat mer än en oförsiktig jägare.",h="Giant Crocolisk Skin är tjocka hudar från de enorma kräldjur som hör hemma i Wetlands träskmarker.",kw={"lärlingens uppgifter","crocolisk","giant crocolisk skin","james halloran","menethil harbor","wetlands"},ang={["class:Hunter"]="Att spåra giant crocolisks längs den dimmiga kusten prövar jägarens förmåga att följa vattenlevande bestar och undvika att dras ner under träskvattnet."},sec={{t="En farlig handel",b="Träsken och vattenvägarna i Wetlands är hem åt enorma crocolisks, vars hudar är så täta att de står emot träskens fukt och röta. I Menethil Harbor är hantverkare som James Halloran beroende av jämna leveranser av skinn för att tillverka slitstarka lädervaror. Men att ta huden från en fullvuxen giant crocolisk kräver att man trotsar djupt vatten och överlistar våldsamma träskrovdjur, så varje fällt byte är vunnet med möda."},{t="Lärlingens dårskap",b="Att skörda de tjocka hudarna var ursprungligen den unge lärlingens uppgift hos Halloran. Pojken saknade stridsförmågan att fälla fullvuxna träskbestar och överfölls längs den norra kusten. Han blev svårt sönderriven av giant crocolisks och vårdas nu av en lokal barnmorska, som säger att han kanske klarar sig. Attacken tvingade Halloran att anlita erfarna äventyrare för att jaga rovdjuren och säkra skinnen som behövs."}},faq={{q="Vad används Giant Crocolisk Skin till?",a="James Halloran, en köpman i Menethil Harbor, skaffar skinnen och uppskattar de tjocka hudarna när han tillverkar tåliga lädervaror som klarar träskmarkernas fuktiga klimat.",al={"användning av crocolisk skin","varför samla giant crocolisk skin","hallorans användning av skinnen"}},{q="Var finns crocolisks som ger de här skinnen?",a="Giant Wetlands Crocolisks stryker längs kusten och i träskvattnen norr om Menethil Harbor, i de grunda vattnen bortom de lokala murloc-bosättningarna.",al={"var giant crocolisks finns","var hitta giant crocolisks","crocolisk på wetlands kust"}},{q="Vad hände med Hallorans lärling?",a="Halloran skickade ut sin lärling ensam i träsket för att skörda skinn. Giant crocolisks anföll lärlingen och slet honom så illa att han nu vårdas av en barnmorska i Menethil, som säger att han kanske klarar sig.",al={"lärling skadad","hallorans lärling","vem förlorade ett ben"}},{q="Hur skiljer sig de här skinnen från skinn från unga crocolisks?",a="Unga crocolisks ger tunnare och smidigare skinn. Fullvuxna giant crocolisks ger betydligt tjockare och tåligare hudar, men att döda en kräver stor stridsvana.",al={"skinn från unga och jättelika crocolisks","skillnad på crocoliskläder"}}},fx={["406c8fec"]={q="Vad är Giant Crocolisk Skin?",a="Det är ett tjockt och slitstarkt skinn från de jättelika krokoliskerna som strövar omkring i Wetlands träsk. Garvare och hantverkare värdesätter skinnet för dess styrka och storlek. Det är inte lätt att flå ett sådant skinn, eftersom dessa rovdjur hör till de mest våldsamma bestar som jagar i vattendragen.",al={"vad är giant crocolisk skin","jättelikt krokolisk-skinn","information om crocolisk skin"}},bd43ba97={q="Varifrån kommer Giant Crocolisk Skin, och vem har tillverkat det?",a="Skinnet tas på naturlig väg från jättelika krokolisker i Wetlands träsk, norrut längs kusten bortom murlocernas hyddor. Det tillverkas inte av någon hantverkare, utan måste flås direkt från kadavren efter dessa väldiga träskbestar.",al={"vem gjorde giant crocolisk skin","varifrån kommer giant crocolisk skins","källa till giant crocolisk skin"}},c37602c5={q="Varför vill James Halloran ha Giant Crocolisk Skins?",a="James Halloran är en hantverkare i Menethil Harbor och behöver skinnen i sitt yrke. Först skickade han sin unge lärling för att samla in dem, men pojken blev svårt sargad av de glupska bestarna och lämnades i en barnmorskas vård. Då vände sig Halloran till erfarna äventyrare för att få tag på materialet och hämnas sin skyddsling.",al={"varför vill halloran ha skinn","vem vill ha giant crocolisk skins","varför behövs giant crocolisk skins"}}},fp="20,178,17.361.0,22.369.1,40.149.0,56.139.0,39.175.0,52.154.0"}
P.entries["item:gloom-weed"] = {n="Gloom Weed",s="Gloom Weed är en sjuklig växt som hör hemma i Tirisfal Glades förgiftade jord och ofta växer på fälten mellan Deathknell och Brill. Den är mest känd som fel växt som Gordo samlar in. Gordo är en tungfotad styggelse från de Forsaken som misstar den för alkemireagensen doom weed.",h="Gloom Weed är en sjuklig växt som hör hemma i Tirisfal Glades förgiftade jord och ofta växer på fälten mellan...",kw={"styggelse","brill","doom weed","gloom weed","gordo","master holland","tirisfal glades"},ang={["profession:Herbalism"]="Örtkunniga kan känna av växten med Find Herbs, vilket gör den mycket lättare att upptäcka bland Tirisfals skuggiga snår.",["race:Undead"]="För nya Forsaken som lämnar Deathknell blir hämtningen av Gloom Weed en snabb lektion i bristerna hos styggelsearbetskraft och Undercitys alkemisters fräna temperament."},sec={{t="En felaktig skörd",b="Gloom Weed spirar bland skuggorna och förruttnelsen i Tirisfal Glades och trivs i den obrukade jorden väster om Brill och öster om Solliden Farmstead. Trots sitt dystra namn är växten relativt harmlös och saknar den kraftiga alkemiska effekt som Royal Apothecary Society uppskattar. Dess främsta ryktbarhet kommer från styggelsen Gordo, som strövar längs vägen och försöker dra upp ogräs med sina stora, klumpiga händer. Gordo har missförstått sin herres order och samlar därför ständigt Gloom Weed. Han ber lättlurade resenärer bära knippen av den till Master Holland på Brills kyrkogård, till alkemistens stora förtret."}},faq={{q="Vad används Gloom Weed till?",a="I praktiken inte till något som Forsaken-alkemister har nytta av. Den samlas enbart in för att styggelsen Gordo misstar den för örten doom weed, som hans herre faktiskt bad om.",al={"gloom weed användning","vad gör gloom weed","vem behöver gloom weed"}},{q="Var växer Gloom Weed?",a="Den växer utspridd över Tirisfal Glades fält mellan Brill och Deathknell, särskilt längs vägen och på ängarna öster om Solliden Farmstead.",al={"var hittar man gloom weed","gloom weed plats","gloom weed växtplatser"}},{q="Vem är Gordo och varför plockar han den?",a="Gordo är en styggelse som Master Holland skickat ut för att samla reagenser. Hans hopsydda händer är klumpiga och hans sinne enkelt, så han vandrar längs vägarna och drar upp fel växter medan han ber förbipasserande om hjälp.",al={"vem är gordo","varför plockar gordo ogräs","gordo styggelse"}},{q="Vad var det Master Holland egentligen ville ha?",a="Master Holland behöver doom weed till sina experiment på Brills kyrkogård. När han får Gloom Weed fnyser han åt misstaget och ber resenärer samla in det han verkligen behöver.",al={"master holland ogräs","vad behöver holland","doom weed eller gloom weed"}}},fx={bc1ac336={q="Vad är Gloom Weed?",a="Gloom Weed är en vanlig, sjukligt utseende vild växt som spirar i den förbannade jorden i Tirisfal Glades. Den finns främst längs vägarna och på öppna fält mellan Brill och Deathknell. Den har ingen magisk kraft eller värdefulla alkemiska egenskaper. I själva verket är den inte mycket mer än ett vanligt vägkantsogräs, Tirisfal Glades motsvarighet till en prästkrage, som råkar frodas trots att landsbygden är förhärjad.",al={"vad är gloom weed","gloom weed bakgrund","gloom weed växt"}},defb981c={q="Varför vill någon ha Gloom Weed?",a="I stort sett ingen vill egentligen ha Gloom Weed. Den enda anledningen till att någon samlar in den är att Gordo, en trögfattad styggelse som vandrar omkring på fälten nära Brill, missförstod sina instruktioner fullständigt. Hans mästare, Junior Apothecary Holland, skickade ut honom för att skörda värdefull doom weed till De övergivnas experiment. Men Gordos tröga hjärna blandade ihop namnen, så ovetande resenärer fick i stället plocka värdelös gloom weed.",al={"vem vill ha gloom weed","varför samla gloom weed","varför plocka gloom weed"}}},fp="10,174,18.443.0,28.137.0,27.153.0,38.172.0,38.180.0"}
P.entries["item:glowing-ember"] = {n="Glowing Ember",s="Vid Shrine of Eternal Flame tänder en Glowing Ember offerkaret inför en schamans prövning. Den kommer från en Minor Manifestation of Fire på Durotars klippor.",h="Vid Shrine of Eternal Flame tänder en Glowing Ember offerkaret inför en schamans prövning.",kw={"call of fire","fire sapta","glowing ember","mindre manifestation av eld","shrine of eternal flame","telf joolam","torch of the dormant flame"},ang={["class:Shaman"]="Som schaman prövar du din beslutsamhet mot levande eld i denna övergångsrit innan du börjar befalla din totem."},sec={{t="Eldens kärna",b="En blivande schaman dricker Fire Sapta för att se de eldiga andarna på höjden nära Telf Joolam. Där möter den invigde en Minor Manifestation of Fire. När elementaren faller återstår bara en glödande kolbit av dess fysiska gestalt. Rå elementär hetta pulserar fortfarande i den och bär på den levande gnista som behövs för att väcka det heliga offerkaret vid Shrine of Eternal Flame."},{t="Tända facklan",b="När Glowing Ember läggs i det kalla karet på bergets offerkar flammar en vitglödande eld upp. Offerkarens låga låter den invigde tända Torch of the Dormant Flame. Facklan binder eldens vilda väsen i ett kärl som den invigde kan bära nerför berget som bevis på sin makt över elementen."}},faq={{q="Var kommer Glowing Ember ifrån?",a="Du hämtar glöden från en besegrad Minor Manifestation of Fire på toppen ovanför Shrine of Eternal Flame i Durotar.",al={"hur får man tag på glowing ember","glowing ember byte","var hittar man glowing ember"}},{q="Vad används glöden till?",a="Du lägger glöden i metallofferkarret vid Shrine of Eternal Flame. Dess intensiva, rytmiska låga tänder den ceremoniella Torch of the Dormant Flame.",al={"vad gör glowing ember","användning av glowing ember","glöd i eldfatet"}},{q="Varför behöver schamaner Fire Sapta för att få tag på den?",a="De elementära andarna på bergets topp är osynliga för vanliga dödliga. När du dricker Fire Sapta stäms dina sinnen in på elementarplanet och avslöjar Minor Manifestation of Fire, så att du kan utmana den.",al={"varför behövs sapta","kan inte se eldelementaren","fire sapta och glöden"}},{q="Vem ber schamaner söka efter den här glöden?",a="Telf Joolam, en eremit bland Durotars klippor, brygger Fire Sapta och vägleder schamanlärlingar genom prövningen att besegra eldanden.",al={"vem ger uppdraget","telf joolam och glöden","uppdragsgivare för call of fire"}}},fx={["8d7073a8"]={q="Vad är Glowing Ember?",a="Glowing Ember är den glödande resten som samlas in från en Minor Manifestation of Fire på toppen med utsikt över Durotar. När anden har besegrats lämnar den efter sig en koncentrerad bit levande eld. Den har tillräckligt med inneboende elementarkraft för att tända de slumrande lågorna på bergets heliga altare.",al={"vad är glowing ember","glowing ember bakgrund","glowing ember föremål"}}},fp="13,153,17.363.0,18.301.1,39.125.0,27.150.0,49.206.0,39.144.0"}
P.entries["item:glowing-fruit"] = {n="Glowing Fruit",s="Glowing Fruit är ett exotiskt, självlysande exemplar som växer bland märkliga blad på Teldrassils grenar. Dess onaturliga sken och märkliga samspel med Världsträdets jord gör det till föremål för brådskande botaniska studier bland naturkunniga.",h="Glowing Fruit är ett exotiskt, självlysande exemplar som växer bland märkliga blad på Teldrassils grenar.",kw={"botanik","denalan","glowing fruit","lake al'ameth","växt","teldrassil","timberlings"},ang={["class:Druid"]="För druider som är lyhörda för Teldrassils bräckliga balans utgör främmande växtlighet som reagerar oberäkneligt med jorden ett möjligt hot mot det växande Världsträdet.",["profession:Herbalism"]="Örtkunniga lägger genast märke till att fruktens märkliga självlysande sken tyder på ett exotiskt och kraftfullt samspel mellan främmande frösorter och förtrollad jord."},sec={{t="Ett märkligt exemplar",b="Den här stora, runda frukten upptäcktes hängande under ovanliga blad på Teldrassil och strålar av ett omisskännligt ljus. Botanikern Denalan vid Lake Al'Ameth känner igen den som främmande för Världsträdet och tror att dess frön kom från avlägsna länder på andra sidan havet. Oavsett ursprung reagerar frukten märkligt på Teldrassils rika, förtrollade jord och visar hur sårbar den unga världsträdskronan är för främmande och oförutsägbar växtlighet."}},faq={{q="Vad är Glowing Fruit?",a="Det är en exotisk, rund frukt som upptäcktes växa under ovanliga blad på Teldrassil. Den avger ett eteriskt sken och verkar ha reagerat ovanligt med den lokala jorden.",al={"glödande frukt teldrassil","vad är det här för frukt","uppdrag med märklig frukt"}},{q="Var kommer frukten ifrån?",a="Enligt naturkännaren Denalan hör frukten inte hemma på Teldrassil. Han misstänker att fröna drev eller fördes hit från långt bortom havet, kanske från Azeroths Eastern Kingdoms, innan de slog rot i jorden.",al={"fruktens ursprung","varifrån kom fröna","hör den hemma här"}},{q="Vem vill undersöka Glowing Fruit?",a="Denalan, en forskare av Night Elf-folket som är stationerad vid Lake Al'Ameth, studerar Teldrassils grenar och ekosystem. Han är särskilt intresserad av främmande växtliv som har reagerat med Världsträdets jord.",al={"vem behöver frukten","var lämnar jag glödande frukt","denalans frukt"}}},fp="13,140,18.325.0,26.147.0,31.147.0,39.208.0"}
P.entries["item:glowing-gem"] = {n="Glowing Gem",s="Glowing Gem är en förtrollad sten som hämtats från murloclägren längs Ashenvales vatten. Den söktes först av den fallne spejaren Teronis och är en viktig del som behövs för att återskapa den magiska stav som Dartol skapade.",h="Glowing Gem är en förtrollad sten som hämtats från murloclägren längs Ashenvales vatten.",kw={"astranaar","reningsstav","dartol","glowing gem","iris lake","murloc","raene wolfrunner","shael'dryn","teronis"},ang={["class:Druid"]="Druiderna är intresserade av Teronis forskning om den spridande korruptionen och reliken som han hoppades kunna återställa.",["race:NightElf"]="Att återfinna ädelstenen och fullfölja Teronis uppdrag hjälper vaktposterna att hedra sin fallne spejare och skydda Ashenvale från den spridande korruptionen."},sec={{t="En förlorad relik från Dartol",b="Glowing Gem hittades hos de aggressiva murlocerna som bor nära Lake Falathim och är laddad med vilande magisk energi. Den unge Night Elf Teronis gav sig av från Astranaar för att spåra upp den och försöka hitta ett verktyg som kunde driva tillbaka korruptionen som spred sig genom Ashenvales skogar. Teronis mötte en för tidig död vid sjön, men stenen förblev oskadd bland strandens asätare."},{t="Att återställa staven",b="När stenen har återfunnits tillsammans med Teronis dagbok skickar vaktposternas ledare Raene Wolfrunner dess bärare nordost till Shael'dryn, en dryad som vakar vid en närbelägen månkällare. Dryaden besitter den urgamla kunskap som krävs för att binda samman Glowing Gem med stavens andra saknade delar, som Dartol skapade, så att den fallne spejarens arbete inte var förgäves."}},faq={{q="Varifrån kommer Glowing Gem?",a="Ädelstenen bärs av murlocer som stryker längs stränderna och det grunda vattnet kring helgedomen vid Lake Falathim i västra Ashenvale, där Teronis föll.",al={"glowing gem plats","vem släpper glowing gem","var får man glowing gem"}},{q="Varför letade Teronis efter den här ädelstenen?",a="Teronis undersökte sätt att rena den växande orenheten i Ashenvale. Enligt hans forskning är just den här ädelstenen en av de viktigaste delarna som behövs för att bygga upp en magisk stav som Dartol en gång skapade.",al={"teronis uppdrag","varför teronis ville ha ädelstenen","ädelstenens syfte"}},{q="Vem ska jag ta Glowing Gem till?",a="Visa stenen och Teronis dagbok för Raene Wolfrunner i Astranaar. Ta sedan Glowing Gem nordost till dryaden Shael'dryn vid månkällan öster om Iris Lake.",al={"vem behöver glowing gem","lämna in glowing gem","vad gör man med ädelstenen"}},{q="Vad är Dartols stav?",a="Det är ett magiskt redskap som Dartol skapade. Dess delar spreds över skogen, och Glowing Gem behövs för att återskapa det.",al={"dartols stav","vad skapade dartol"}}},fx={["464fc9d6"]={q="Vad är Glowing Gem?",a="Glowing Gem är en förtrollad sten som behövs för att återskapa staven som Dartol tillverkade. Teronis sökte efter den när han undersökte korruptionen i Ashenvale, och Raene Wolfrunner leder sökandet efter stavens återstående delar.",al={"vad är glowing gem","berätta om glowing gem","glowing gem bakgrund"}}},fp="11,141,22.307.0,17.292.1,37.142.0,37.166.0,37.166.0,26.138.0"}
P.entries["item:glowing-soul-gem"] = {n="Glowing Soul Gem",s="En Glowing Soul Gem är en mörk ritualartefakt som bärs av agenter från Cult of the Dark Strand i norra Ashenvale. Stenen är fylld med skuggmagi och fångar en ovetande persons ande för att ge näring åt kultens illvilliga verksamhet.",h="En Glowing Soul Gem är en mörk ritualartefakt som bärs av agenter från Cult of the Dark Strand i norra...",kw={"althalaxx","cult of the dark strand","dark strand","delgren the purifier","glowing soul gem","maestra's post","ordil'aran","soul gem"},ang={["class:Priest"]="Präster som betraktar själstenen kan känna den instängda andens plågor och förstår att artefakten måste renas snarast, så att själen kan finna ro.",["class:Warlock"]="Ingen förstår konsten att fånga andar i själstenar bättre än häxmästare. De ser Dark Strands ädelsten som en grövre, nekromantisk variant av andemanipulation."},sec={{t="Ett kärl för mörk magi",b="Nordost om Maestra's Post, i de skuggiga ruinerna av Ordil'Aran, utövar medlemmar av Cult of the Dark Strand mörk magi under sina skuggmästares vakande blick. Bland dem bär agenter Glowing Soul Gems, kärl som förtrollats för att fånga och plåga de dödas själar. Stenarna är mer än bara prydnadssaker; de fungerar som kanaler för magisk energi och binder andar till kultens mörka syften."},{t="Ordil'Arans hemligheter",b="Delgren the Purifier vid Maestra's Post försöker slå ut Dark Strands inflytande i norra Kalimdor och undersöker därför dessa artefakter. Den som tyder förtrollningarna i en Glowing Soul Gem upptäcker inte bara mörka magiska formler, utan också en själ som ropar inifrån ädelstenen. Det avslöjar de ondskefulla experimenten som knyter kultisterna i Ashenvale till deras fränder vid Tower of Althalaxx."}},faq={{q="Vad är en Glowing Soul Gem?",a="Det är en förtrollad själsten som används av Cult of the Dark Strand. Fylld med skuggmagi fångar den andar och utvinner deras essens för att ge näring åt kultens avskyvärda magi.",al={"vad är soul gem","soul gem darkshore","glowing soul gem bakgrund"}},{q="Var kommer den här själstenen ifrån?",a="Den bärs av medlemmar i Cult of the Dark Strand, däribland kultister, lönnmördare, hantlangare och adepter som verkar från ruinerna av Ordil'Aran i norra Ashenvale.",al={"vem släpper soul gem","glowing soul gem plats","ordil'aran-ädelsten"}},{q="Vem vill ha den här själstenen, och varför?",a="Delgren the Purifier, som är stationerad vid Maestra's Post, vill ha ädelstenen. Han tror att om han tyder dess förtrollningar kan han avslöja kultens hemliga kraftkälla och ta reda på vad de planerar.",al={"delgren soul gem","varför vill delgren ha soul gem","maestra's post soul gem"}},{q="Vad händer när själstenen tyds?",a="När förtrollningarna på ädelstenen löses upp frigörs spöket som fångats därinne. Den plågade själen blir fri, och Dark Strands förvridna metoder avslöjas.",al={"vad finns i soul gem","spöke i soul gem"}}},fp="16,179,24.309.0,25.353.1,29.170.0,35.168.0,32.160.0,45.143.1"}
P.entries["item:glutton-shackle"] = {n="Glutton Shackle",s="Glutton Shackles är förtrollade bojor som bärs av Moonrage Glutton-worgen i Silverpine Forest. De smiddes av den galne ärkemagikern Arugal, och banden kanaliserar magi som stärker hans annars bristfälliga trolldom och håller hans förbannade vargskapelser vid liv.",h="Glutton Shackles är förtrollade bojor som bärs av Moonrage Glutton-worgen i Silverpine Forest.",kw={"arugal","dalar dawnweaver","glutton shackle","moonrage glutton","the sepulcher","silverpine","worgen"},ang={["class:Mage"]="Magiker lär uppskatta Dalar Dawnweavers bitska kritik av Arugals usla teknik, eftersom det ses som ett tecken på medioker trollkonst att använda fysiska, förtrollade kryckor för att stabilisera enkla transmutations- och besvärjelser för att kalla fram varelser.",["race:Undead"]="Agenter från Forsaken ser insamlingen av bojorna som ett viktigt steg mot att neutralisera worgenhotet som tränger ända fram till The Sepulchers gränser."},sec={{t="En krycka för svag trolldom",b="För de tränade magikerna bland Forsaken är de vilda worgen som hemsöker Silverpine inte bara bestialiska vidunder – de vittnar om grov magisk inkompetens. Dalar Dawnweaver, en skicklig arkanist stationerad vid The Sepulcher, känner inget annat än förakt för ärkemagikern Arugal och anser honom vara en oduglig klåpare, ovärdig Kirin Tor. Dawnweaver upptäckte att Arugal förlitade sig på förtrollade reliker för att kompensera för sina bräckliga besvärjelser. Glutton Shackles, som bärs av de kraftiga Moonrage Gluttons som strövar omkring i norra Silverpine, fungerar som magiska ankare som förstärker förbannelsen som binder vidundren."},{t="Bränsle till motåtgärder för Forsaken",b="Eftersom Arugal band råa förtrollningar direkt i dessa tunga järnbojor behåller de en rest av magisk energi även efter att bärarna dödats. Dawnweaver kräver att agenter från Forsaken hämtar bojorna så att han kan studera deras konstruktion och suga åt sig deras magiska reserver. Genom att analysera de grova förtrollningarna i metallen hoppas Forsaken kunna avslöja worgenförbannelsens hemligheter och iscensätta fallet för bestmästaren som håller till i Shadowfang Keep."}},faq={{q="Vad är en Glutton Shackle?",a="En Glutton Shackle är en förtrollad järnboja som bärs av Moonrage Glutton-worgen i Silverpine Forest. Ärkemagikern Arugal skapade banden, som fyller bärarna med magisk förstärkning för att kompensera för hans bristfälliga besvärjelser.",al={"vad är glutton shackles","glutton shackle-lore","worgenbojor"}},{q="Varför vill Dalar Dawnweaver ha Glutton Shackles?",a="Dalar Dawnweaver behöver bojorna för att analysera Arugals grova förtrollningar och suga åt sig deras kvarvarande magiska energi. Genom att förstå föremålen Arugal använde för att stabilisera sina vidunder kan Forsaken bättre motverka hans magi.",al={"varför samla bojor","dalar dawnweavers uppdrag","bojor till the sepulcher"}},{q="Vem tillverkar bojorna?",a="De förtrollades av ärkemagikern Arugal, en tidigare trollkarl från Dalaran som kallade fram worgen för att bekämpa Scourge och så småningom förlorade förståndet. Han band sina skapelser till sin vilja med magiska prydnader.",al={"vem gjorde bojorna","arugals bojor","var kommer bojorna ifrån"}},{q="Var finns varelserna som bär bojorna?",a="Moonrage Gluttons strövar omkring i skogarna och på övergivna gårdar i mellersta och norra Silverpine Forest. De lurar ofta i flockar tillsammans med andra korrumperade Moonrage-worgen.",al={"var dyker gluttons upp","moonrage gluttons plats","silverpine worgenbojor"}}},fp="15,163,25.508.0,33.446.1,26.208.0,48.218.0,25.205.0,53.158.0"}
P.entries["item:glyph-of-azora"] = {n="Glyph of Azora",s="Från Tower of Azora använder Theocritus Glyphs of Azora för att hålla uppsikt över avlägsna hot. De ristade stenarna utökar räckvidden för Eye of Azora och låter honom läsa fienders tankar och planer.",h="Från Tower of Azora använder Theocritus Glyphs of Azora för att hålla uppsikt över avlägsna hot.",kw={"glyph of azora","morganth","redridge","kristallskådning","stonewatch keep","theocritus","tower of azora","tower of ilgalar"},ang={["class:Mage"]="Som magiker kan du använda magisk spådom för att utöka kristallskådning med riktad telepati och avlägsna sensoriska reläer.",["faction:Alliance"]="Som medlem av Alliansen kan du använda glyferna för att samla underrättelser om Morganth och Blackrock-orcherna vid Stonewatch Keep."},sec={{t="Ögon över gränsen",b="Theocritus håller uppsikt över fientliga makter från sitt torn i Elwynn Forest. Hans kristallrelik, Eye of Azora, låter honom se över stora avstånd, men inte nå in i sina motståndares tankar eller planer. Han placerar små fokus som kallas Glyphs of Azora på ytor långt borta för att föra sin magi längre. Varje glyf förankrar hans kraft och låter honom läsa fienders avsikter och projicera sin röst över flera mil för att tala med fältagenter."},{t="Spioneri i Redridge",b="I Redridge Mountains placerar Theocritus glyfer i fientligt territorium. Han fäster den första vid en uråldrig lejonstaty med utsikt över Tower of Ilgalar, där hans lömska rival, den mörke magikern Morganth, har sitt fäste. Genom glyfen tränger Theocritus in i Morganths sinne och upptäcker en tvist mellan den avfällige magikern och Blackrock-orcherna vid närbelägna Stonewatch Keep. För att ta reda på orsaken skickar han en andra glyf till höjderna i fästets intakta vakttorn, dold i en slängd spritburk."}},faq={{q="Vad är syftet med Glyph of Azora?",a="Theocritus använder en Glyph of Azora för att utöka räckvidden för Eye of Azora. Placerad på en avlägsen plats förankrar den hans magi, så att han kan läsa sina motståndares tankar och planer och tala med fältagenter över flera mil.",al={"vad gör glyph of azora","varför använda glyph of azora","glyph of azora syfte"}},{q="Vem skapade Glyph of Azora?",a="Theocritus skapade Glyph of Azora. Han bor i Tower of Azora vid den östra gränsen av Elwynn Forest.",al={"vem skapade glyfen","glyph of azora skapare","theocritus glyf"}},{q="Var placeras Glyphs of Azora?",a="En glyf är fäst vid en uråldrig lejonstaty med utsikt över Tower of Ilgalar. En andra är gömd i en slängd spritburk i det intakta vakttornet vid Stonewatch Keep.",al={"var ska jag placera glyfen","glyfens placeringar","var ska glyfen placeras"}},{q="Varför spionerar Theocritus på Tower of Ilgalar?",a="Tower of Ilgalar är Morganths fäste. Den lömske mörke magikern är Theocritus rival, och glyfen låter Theocritus läsa hans tankar och planer.",al={"varför spionera på morganth","theocritus ilgalar","morganths tvist"}},{q="Hur låter glyfen Theocritus tala med andra?",a="När glyfen har fästs vid en avlägsen yta förankrar den Theocritus magi och låter honom projicera sin röst över flera mil för att tala med fältagenter.",al={"talande glyf","theocritus röst i glyfen","kan glyfen prata"}}},fx={["16152ed3"]={q="Vad är Glyph of Azora?",a="Glyph of Azora är en förtrollad arkan markör som trollkarlen Theocritus skapade vid Tower of Azora. Tillsammans med hans skådande fokus, Eye of Azora, fungerar dessa ristade stenar som avlägsna avlyssningsposter. När en glyf fästs på en yta nära ett intressant område kan Theocritus tränga in i sina måls sinnen och tankar på långt håll. Han kan också projicera sin röst till alla som står bredvid den.",al={"vad är glyph of azora","glyph of azora föremål","berätta om glyph of azora"}},["7c5a9e02"]={q="Varför vill Theocritus att du placerar ut Glyph of Azora?",a="Theocritus använder dessa glyfer för att spionera på farliga motståndare i Redridge. Eye of Azora låter honom se platser på avstånd, men utan en ledare i närheten kan han inte tränga in i någons tankar. Om du placerar en glyf nära Tower of Ilgalar kan han utforska tankarna och framtidsplanerna hos sin rival, avfällingen Morganth. En annan glyf nära Stonewatch Keep hjälper honom att reda ut Morganths konflikt med Blackrock-orcerna.",al={"varför placera glyph of azora","varför vill theocritus placera ut glyfen","syftet med glyph of azora"}}},fp="14,182,22.424.0,21.503.1,42.206.0,31.107.0,37.168.0,49.150.0,55.141.0"}
P.entries["item:glyphic-letter"] = {n="Glyphic Letter",s="I Northshire Abbey kallar Glyphic Letter lovande noviser till studier i magi. Efter en första tjänstgöring i garnisonen kallas de upp till Khelden Bremen, klostrets magitränare.",h="I Northshire Abbey kallar Glyphic Letter lovande noviser till studier i magi.",kw={"magi","elwynn forest","glyphic letter","khelden bremen","magitränare","marshal mcbride","northshire abbey"},ang={["class:Mage"]="Som magiker kallar detta märkta brev dig uppför trapporna för att inleda formella studier i Alliansens magiska traditioner under Khelden Bremen.",["race:Human"]="Som människa inleder du din tjänst inom Stormwinds magiska discipliner med denna kallelse. Northshire Abbey har genom rikets historia gett magistudenter skydd."},sec={{t="En kallelse till magin",b="Khelden Bremen förseglar Glyphic Letter med sitt personliga sigill. Lärlingar i magi får det efter att ha visat sin disciplin i Northshire Valley. Kallelsen leder dem bort från grundläggande fälttjänst och till särskild magisk undervisning i klostret. Bremen prövar varje elevs beslutsamhet innan de tar sig an magin, med dess farliga krafter, obevekliga granskning och bördor."}},faq={{q="Vad är Glyphic Letter?",a="Khelden Bremen skriver och förseglar Glyphic Letter som en kallelse till undervisning. Det hänvisar blivande mänskliga magiker till honom i Northshire Abbeys övre rum för formella studier i magi.",al={"vad är det här brevet","föremålet glyphic letter","kheldens brev"}},{q="Vem skickar Glyphic Letter?",a="Khelden Bremen, magitränaren i Northshire Abbey, förseglar brevet med sitt sigill. Garnisonsledningen lämnar över det när en lärling har visat sitt värde mot närliggande skadedjur.",al={"vem skrev det","vem gav mig glyphic letter","brevets avsändare"}},{q="Vart ska jag ta Glyphic Letter?",a="Ta brevet in i Northshire Abbey. Gå in bakom Marshal McBride, följ den vänstra korridoren, gå uppför trapporna och leta efter det bakre rummet där Khelden Bremen undervisar i magi.",al={"vart ska jag gå","var är khelden bremen","kheldens plats"}},{q="Varför kallar Khelden på unga magiker?",a="Khelden vill pröva din beslutsamhet. Han varnar för att magi väcker både fruktan och respekt och innebär att utmana mäktiga krafter. Han måste veta att du har viljan att uthärda det ödet.",al={"varför vill khelden träffa mig","varför magitränaren","vad vill khelden"}}},fx={["4321b6bd"]={q="Varför vill Khelden Bremen att Glyphic Letter ska levereras till dig?",a="Brevet är en officiell kallelse och ett prov på beslutsamheten hos blivande magiker. Khelden Bremens meddelande är förseglat med hans personliga sigill och beskriver den farofyllda och krävande väg som magin innebär. Det varnar dig för rädslan och prövningarna som följer med sökandet efter förbjuden kunskap. Genom att lämna över brevet till dig försäkrar han sig om att du är villig att möta det ödet innan han inleder din formella utbildning.",al={"varför glyphic letter","varför fick jag glyphic letter","syftet med glyphic letter"}}},fp="14,189,23.393.0,27.189.0,29.183.0,35.185.0,38.199.0"}
P.entries["item:glyphic-memorandum"] = {n="Glyphic Memorandum",s="Glyphic Memorandum är ett skriftligt meddelande till nya magiker som anländer till Coldridge Valley. Det är skrivet på uppdrag av magitränaren Marryk Nurribit och uppmanar nyblivna trollkarlar att gå inomhus och börja sin formella undervisning i magi.",h="Glyphic Memorandum är ett skriftligt meddelande till nya magiker som anländer till Coldridge Valley.",kw={"anvilmar","coldridge valley","dun morogh","glyphic memorandum","magiker","marryk nurribit"},ang={["class:Mage"]="För blivande magiker på färd genom Dun Morogh markerar det här meddelandet början på deras formella utbildning i magi under Marryk Nurribit.",["race:Gnome"]="Gnomiska magiker som inleder sina resor i exil får en påminnelse från sin tränare om att fokusera på sina studier och hålla sig borta från sitt förlorade hemland Gnomeregan."},sec={{t="En kallelse till Anvilmar",b="Nya trollkarlar som ger sig ut i den bitande kylan i Coldridge Valley får detta korta meddelande efter att ha slutfört sina första uppgifter. Den lokala magitränaren Marryk Nurribit har skrivit memorandumet och kallar unga utövare till värmen i Anvilmar. I stället för sträng akademisk dogm är Marryks råd informellt och rakt på sak: lär dig dina besvärjelser, lägg undan mynt till träning och öl på värdshuset, och håll dig långt borta från de strålningsskadade ruinerna i Gnomeregan."}},faq={{q="Vad är Glyphic Memorandum?",a="Det är en kort skriftlig kallelse till nyanlända magiker i Coldridge Valley, där de uppmanas att söka upp den lokala magitränaren inne i Anvilmar.",al={"glyfiskt meddelande","magikernas meddelande","vad är glyphic memorandum"}},{q="Vem skrev memorandumet?",a="Meddelandet kommer från Marryk Nurribit, en magitränare av gnomernas folk som är stationerad i Anvilmars salar i Dun Morogh.",al={"vem skrev det","vem skickade glyphic memorandum","meddelandets författare"}},{q="Vilka råd ger tränaren när han svarar på memorandumet?",a="När novisen visar upp meddelandet påminner Marryk honom om att visa måttfullhet, spara pengar till besvärjelser och öl på värdshuset samt undvika de radioaktiva salarna i Gnomeregan helt och hållet.",al={"marryks råd","vad säger marryk"}}},fx={c67a7a55={q="Varför vill Marryk Nurribit att du tar med Glyphic Memorandum till honom?",a="Memorandumet är en inbjudan och kallelse för blivande magiker som börjar sin bana i Coldridge Valley. När du levererar det till Marryk Nurribit i Anvilmar får du kontakt med din lokala magitränare. Han passar på att ge dig råd som nybörjare, påminna dig om att hålla dig borta från det fallna Gnomeregan och erbjuda formell undervisning i magins konst när du har råd.",al={"varför ta med glyphic memorandum","varför vill marryk ha memorandumet","varför vill man ha glyphic memorandum"}}},fp="18,163,21.310.0,31.141.0,26.81.0,64.131.0"}
P.entries["item:glyphic-scroll"] = {n="Glyphic Scroll",s="Glyphic Scroll är en kallelse till nyväckta Forsaken-magiker i Deathknell. Med Isabella, den lokala tränarens, sigill kallar den nybörjande magiker till den vanhelgade kyrkan för att finslipa sin konst i undeath.",h="Glyphic Scroll är en kallelse till nyväckta Forsaken-magiker i Deathknell.",kw={"arkan","deathknell","glyphic scroll","isabella","magiker","rulle","tirisfal"},ang={["class:Mage"]="Rullen är den första formella kallelsen en Forsaken-magiker får. Den betonar att undeath inte befriar en magiker från det arkana magins fördärvande beroende.",["race:Undead"]="För Forsaken är återvunnen arkansk kunskap mer än lärda studier. Den är ett oumbärligt vapen för att säkra deras självständighet mot både Scourge och levande fiender."},sec={{t="En kallelse från kyrkan",b="När en nyväckt Forsaken-magiker återvänder efter att ha rensat Deathknells kyrkogård från tanklösa Scourge väntar detta förseglade brev. Rullen är skriven under Isabellas sigill; hon är byns magitränare. Den kallar mottagaren till den förfallna kyrkans helgedom. För nyuppståndna magiker är den en första introduktion till den arkana disciplinen under Forsakens fana. Den påminner dem om att döden kanske befriade dem från dödlig svaghet, men att magisk kraft fortfarande lockar till fördärv lika starkt som någonsin."}},faq={{q="Vad är Glyphic Scroll?",a="Det är ett introduktionsbrev till nyväckta Forsaken-magiker i Deathknell. Med magitränaren Isabellas personliga sigill uppmanar det nyblivna magiker att söka upp henne i stadens kyrka och påbörja sin magiska utbildning.",al={"vad är det här för föremål","användning av glyphic scroll","vad gör rullen"}},{q="Vem skickar Glyphic Scroll?",a="Rullen levereras på uppdrag av Isabella, magitränaren i den förfallna kyrkan i Deathknell. Hon hör av sig till alla nyuppståndna odöda med fallenhet för det arkana.",al={"vem skrev den","vem gav mig den","rullens avsändare"}},{q="Varför vill Isabella träna nya Forsaken-magiker?",a="Isabella söker själsfränder som delar smärtan efter döden och viljan att återta sitt stulna hemland och sina öden. Hon tränar dem att utveckla tillräcklig arkansk kraft för att förgöra alla som motsätter sig Forsaken, samtidigt som hon varnar dem för att falla för magiskt beroende och fördärv.",al={"isabellas motiv","varför träna magiker"}}},fp="14,198,25.380.0,27.180.0,29.146.0,51.257.0"}
P.entries["item:glyphic-tablet"] = {n="Glyphic Tablet",s="I Valley of Trials ger Gornek Glyphic Tablet till unga Darkspear-trollmagiker. Dess kallelse skickar dem till Mai'ah för undervisning i arkan magi.",h="I Valley of Trials ger Gornek Glyphic Tablet till unga Darkspear-trollmagiker.",kw={"arkansk magi","durotar","glyphic tablet","gornek","mai'ah","trollmagiker","valley of trials"},ang={["class:Mage"]="Som magiker inleder du din arkana undervisning hos Darkspear med Mai'ahs varning om att magins fördärvande lockelse är din största fara.",["race:Troll"]="Som Darkspear-troll får du denna tavla för att inleda din väg vid sidan av de traditionella shamanska och krigiska levnadssätten."},sec={{t="En magikers första kallelse",b="Nya Darkspear-rekryter med fallenhet för arkan kraft får Glyphic Tablet i Valley of Trials. Gornek lämnar den till unga rekryter medan de utför sina första uppgifter bland de röda kanjonerna. På tavlan bjuder Mai'ah, en erfaren trollmagiker utanför The Den, in dem att träffa henne. Darkspear följer arkana traditioner som skiljer sig från människornas och högalvernas lärda akademier. Mai'ah erbjuder undervisning och en allvarlig varning: rå magi fördärvar och bedrar, och dess faror för en magikers sinne överträffar dem från varje fiendesoldat."}},faq={{q="Vad är syftet med Glyphic Tablet?",a="Glyphic Tablet kallar en ung trollmagiker till Mai'ah i Valley of Trials för att få ordentlig träning i besvärjelsekonst.",al={"vad gör glyphic tablet","glyphic tablet användning","varför har jag glyphic tablet"}},{q="Vem skickar Glyphic Tablet?",a="Mai'ah skriver tavlan, och Gornek lämnar den till unga trollrekryter i Valley of Trials.",al={"vem skrev glyphic tablet","vem gav mig glyphic tablet"}},{q="Varför behöver trollmagiker en varning om magi?",a="Mai'ah varnar för att arkan magi fördärvar, göder högmod och kan få besvärjare att känna sig osårbara. Dess osynliga faror är dödligare än fysiska rivaler.",al={"vad säger mai'ah","är magi farligt"}},{q="Kan andra folkslag i Horde få den här plattan?",a="Trollmagiker får Glyphic Tablet i Valley of Trials. Orkmagiker får en Glyphic Parchment som kallar dem till Mai'ah.",al={"kan orcer få glyphic tablet","är glyphic tablet bara för troll"}}},fx={be25ec39={q="Vad är Glyphic Tablet?",a="Glyphic Tablet är ett ristat meddelande som skickas till trollmagiker som börjar sina prövningar i Valley of Trials. Gornek levererar det och kallar dig till ett möte med Mai'ah, den lokala magitränaren, så att du kan inleda din formella utbildning i magins konst.",al={"vad är glyphic tablet","glyphic tablet föremål","om glyphic tablet"}},["28b4f0b5"]={q="Varför vill någon ha Glyphic Tablet?",a="Tableten söks inte för makt eller rikedom, utan fungerar som en formell kallelse och introduktion. Den ser till att unga trollmagiker inställer sig hos Mai'ah, som använder mötet för att utfärda viktiga varningar om de fördärvande faror som följer med att utöva arkana magi.",al={"varför vill man ha glyphic tablet","vem behöver glyphic tablet","varför behålla glyphic tablet"}}},fp="14,155,22.526.0,42.114.0,29.94.0,46.154.0,42.127.0"}
P.entries["item:glyphs-of-summoning"] = {n="Glyphs of Summoning",s="I Orgrimmar använder lärlingar bland trollkarlarna Glyphs of Summoning för att kalla fram en voidwalker. Inskrifterna är avskrivna från den uråldriga Tablet of Verga och drar en voidwalker från Nether till en besvärjelsecirkel, där den binds till trollkarlens tjänst.",h="I Orgrimmar använder lärlingar bland trollkarlarna Glyphs of Summoning för att kalla fram en voidwalker.",kw={"cleft of shadow","gan'rul bloodeye","glyphs of summoning","neeru fireblade","orgrimmar","tablet of verga","bindningen","voidwalker"},ang={["class:Warlock"]="Som trollkarl i Horde står du inför en viktig övergångsrit. Glyferna låter dig bevisa din makt över Void och göra anspråk på en voidwalker som tjänare."},sec={{t="En pakt smidd i skugga",b="I Cleft of Shadow studerar trollkarlarna de mörka konsterna långt från krigshövdingens vakters nyfikna blickar. För en blivande trollkarl som lär sig av Gan'rul Bloodeye är förmågan att befalla en voidwalker ett viktigt steg. Glyphs of Summoning bygger på kunskap som finns inskriven på Tablet of Verga och överbryggar Azeroth och Nether. I Neeru Fireblades tält lägger trollkarlen ut dem i en besvärjelsecirkel. De öppnar en passage och drar en varelse från Void till de dödligas värld. Innan Gan'rul lär ut de sista metoderna för att binda den måste trollkarlen besegra den framkallade varelsen i strid."}},faq={{q="Vad används Glyphs of Summoning till?",a="Glyferna är rituella inskrifter som används i besvärjelsecirkeln inne i Neeru Fireblades tält i Orgrimmar. De kallar fram en fientlig voidwalker från Nether, som trollkarlen måste kuva för att bemästra framkallningen.",al={"vad gör glyphs of summoning","glyphs of summoning syfte","hur använder man glyphs of summoning"}},{q="Var kommer Glyphs of Summoning ifrån?",a="Gan'rul Bloodeye, trollkarlstränaren i Cleft of Shadow, ger dig dem. De bygger på kunskap som bevarats på Tablet of Verga.",al={"var får man glyphs of summoning","vem ger glyphs of summoning"}},{q="Var utförs åkanderitualen?",a="Ritualen äger rum inne i Neeru Fireblades tält, på andra sidan grottgolvet i Orgrimmars Cleft of Shadow.",al={"var åkallar jag en voidwalker","plats för åkandecirkel i orgrimmar","neeru fireblades cirkel"}},{q="Varför måste utövare av svartkonst besegra den åkallade varelsen?",a="En trollkarl måste visa sin dominans för att säkert kunna kontrollera en demon eller varelse från Void. Genom att besegra den framkallade varelsen visar trollkarlen sin beslutsamhet, så att Gan'rul Bloodeye kan lära ut hur man binder dess sort till sin vilja.",al={"varför slåss mot voidwalkern","kuva voidwalker"}}},fx={["094a8ca5"]={q="Vad är Glyphs of Summoning?",a="Glyphs of Summoning är arkana och demoniska inskrifter som kopierats direkt från Tablet of Verga. De anförtros åt blivande häxmästare av Gan'rul Bloodeye under Orgrimmar och innehåller de exakta besvärjelser som krävs för att slita upp slöjan och kalla fram en fientlig voidwalker från Nether för att binda den.",al={"vad är glyphs of summoning","glyphs of summoning i historien"}},fd669514={q="Varför vill Gan'rul Bloodeye ha tillbaka Glyphs of Summoning?",a="Gan'rul Bloodeye kräver att du återlämnar glyferna tillsammans med bevis på din seger så att han kan slutföra din träning. När du visar att du har styrkan att kalla fram och kuva en rasande voidwalker använder Gan'rul glyferna och din bevisade skicklighet för att lära dig hur du permanent binder sådana väsen till din tjänst.",al={"varför återlämna glyphs of summoning","varför vill gan'rul ha glyphs of summoning","varför vill man ha glyphs of summoning"}}},fp="19,235,23.586.0,42.206.0,43.133.0,40.109.0,53.218.0"}
P.entries["item:gnoam-sprecklesprocket"] = {n="Gnoam Sprecklesprocket",s="Gnoam Sprecklesprocket är en avancerad kraftkälla som bärgats från Sneed's Shredder djupt inne i The Deadmines. Gnomiska ingenjörer söker efter den här komponenten för att ge specialiserade borrmaskiner extra kraft i ett djärvt försök att återta sitt fallna hem Gnomeregan.",h="Gnoam Sprecklesprocket är en avancerad kraftkälla som bärgats från Sneed's Shredder djupt inne i The...",kw={"the deadmines","gnoam sprecklesprocket","gnomeregan","gyrodrillmatic","shoni the shilent","sneed","sneed's shredder","sprecklesprocket"},ang={["profession:Engineering"]="Kugghjulet är en intakt kraftkälla som kan driva maskinerna som behövs för att borra genom Gnomeregans bergiga underjordiska gränser.",["race:Gnome"]="Varje bärgad komponent för de landsförvisade gnomerna närmare att borra sig in i sitt förlorade hem och driva ut troggarna."},sec={{t="En livsviktig kraftkälla",b="Gnoam Sprecklesprocket hittades i en goblinstrimlare som användes i Defias fäste och är ett enastående exempel på kompakt mekanisk energi. Den här specialiserade kärnan satt djupt inne i den tungfotade maskinen som goblinernas arbetsledare Sneed körde och ger tillräckligt med uthållig energi för att driva tunga industriella stocknings- och skärblad. Dess stabilitet och kraftfulla uteffekt gör den till ett ovärderligt bärgningsfynd i Westfalls underjordiska tunnlar."},{t="In i Gnomeregan",b="I Stormwind City pekade den gnomiska uppfinnaren Shoni the Shilent ut strimlaren från The Deadmines som nyckeln till en större offensiv. Gnomiska styrkor vill återta Gnomeregan från troggarna som intog staden, men de förseglade underjordiska ingångarna utgör ett mäktigt hinder. Genom att utnyttja Sprecklesprocket tänker Shoni driva tunga gyrodrillmatic-utgrävare som kan borra rakt genom berggrunden runt den förlorade teknostaden och skapa en oväntad anfallsväg underifrån."}},faq={{q="Vad är Gnoam Sprecklesprocket?",a="Det är en intakt mekanisk kraftkälla med hög uteffekt, hämtad från en goblinstrimlare djupt inne i The Deadmines. Den har tillräcklig effekt för att driva tung underjordisk borrutrustning.",al={"sprecklesprocket","vad är det här kugghjulet","vad är föremålet"}},{q="Varifrån kommer Gnoam Sprecklesprocket?",a="Den bärgas från Sneed's Shredder, en industriell timmermaskin som goblinernas arbetsledare Sneed kör i timmerbruken i The Deadmines.",al={"vem släpper det","hur får man sprecklesprocket","byte från strimlare"}},{q="Varför behöver Shoni the Shilent den?",a="Shoni behöver dess uteffekt för att driva gyrodrillmatic-utgrävare. Maskinerna är byggda för att borra genom berggränserna under Gnomeregan, så att alliansvänliga gnomer kan anfalla troggarna.",al={"varför vill shoni ha den","shonis uppdragsföremål"}},{q="Är kugghjulet goblin- eller gnomteknik?",a="Det bärgas från en fungerande goblinstrimlare i The Deadmines, och Shoni tänker använda kraftkällan i gnomisk borrutrustning. Källan anger inte vem som ursprungligen konstruerade komponenten.",al={"är det goblinteknik","gnomisk eller goblinisk anordning"}}},fp="22,186,20.275.0,20.441.0,35.156.0,48.155.0,35.211.0,45.170.0"}
P.entries["item:gnoll-paw"] = {n="Gnoll Paw",s="Gnoll Paws når Sentinel Hill som bevis på en patrull mot Riverpaw-flockarna i Westfall. People's Militia erbjuder belöningar för att skydda lokala gårdar.",h="Gnoll Paws når Sentinel Hill som bevis på en patrull mot Riverpaw-flockarna i Westfall.",kw={"danuvin","gnoll paw","patrullera westfall","people's militia","riverpaw","sentinel hill","westfall"},ang={["class:Hunter"]="Som jägare kan du spåra Riverpaw-flockar över Westfalls öppna slätter och samtidigt hjälpa till att säkra utposter på landsbygden.",["faction:Alliance"]="För Alliansens hjältar hjälper belöningar från People's Militia till att skydda Stormwinds västra kornbod från kringströvande bestar och organiserade banditer."},sec={{t="Milisens belöning",b="People's Militia försvarar Westfall från Sentinel Hill. När kungens armé är frånvarande och kronan tycks blunda för landsbygdens problem får vanliga medborgare och frivilliga möta laglösa, kringströvande mekaniska varelser och Riverpaw-gnoller. Captain Danuvin erbjuder belöningar som bevis på att gnoller har dödats. När du tar med deras tassar visar det att patruller har sökt igenom buskmarkerna i stället för att vila under vakttornet."},{t="Ett samordnat hot",b="Riverpaw-gnoller i Westfall söker föda över slätterna, men milisens spanare har upptäckt tecken på nära samordning med Defias-tjuvar som håller till kring Deadmines. Flockarna terroriserar gårdar och ger sig på försörjningsvagnar, vilket hjälper till att skydda banditerna från lokalt motstånd. När du lämnar in gnolltassar hjälper du till att hålla landsvägarna mellan Sentinel Hill och Elwynn Forest öppna."}},faq={{q="Varför vill Captain Danuvin ha Gnoll Paws?",a="Captain Danuvin ber om Gnoll Paws som bevis på en lyckad patrull över Westfalls slätter. Med få resurser och utan hjälp från kronan betalar milisen belöningar när rekryter kommer med bevis på dödade gnoller.",al={"varför samla tassar","danuvin gnoll paws","vad används gnoll paws till"}},{q="Vilka gnoller släpper tassarna?",a="Tassarna kommer från Riverpaw-gnoller som strövar på Westfalls gräsmarker, kullar och övergivna gårdar.",al={"var hittar man gnoll paws","vilka gnoller har tassar","gnoll paw plats"}},{q="Agerar gnollerna ensamma i Westfall?",a="Nej. Captain Danuvin och milisen misstänker att Riverpaw-gnoller samarbetar med banditer och tjuvar kring Deadmines och hotar lokala gårdar.",al={"samarbetar gnoller med defias","gnoll deadmines samband","vem leder gnollerna"}},{q="Varför tar inte Stormwind hand om gnollhotet?",a="Stormwind har i stort sett lämnat Westfall åt sitt öde under inhemsk oro och politisk handlingsförlamning. Lokala bönder och People's Militia står för nästan hela arbetet med att försvara landsbygden.",al={"varför finns ingen stormwind-armé","var är armén","varför slåss milisen mot gnoller"}}},fx={aa4b645a={q="Vad är Gnoll Paw?",a="Gnoll Paw är en avhuggen hand från en Riverpaw-gnoll som strövar omkring på Westfalls slätter. För People's Militia, som är stationerad vid Sentinel Hill, är dessa makabra troféer obestridliga fysiska bevis på att en äventyrare aktivt har patrullerat området och decimerat de aggressiva gnollflockar som hotar traktens gårdar.",al={"vad är gnoll paw","föremålet gnoll paw","vad är gnoll paws"}},["96952327"]={q="Var kommer Gnoll Paws ifrån?",a="Dessa tassar kommer direkt från de vilda Riverpaw-gnollerna som är utspridda över Westfalls gräsmarker och övergivna gårdar. De förvildade gnollerna strövar omkring i området, jagar bönder och samarbetar med laglösa. Deras avhuggna tassar är därför en bister belöning som tagits direkt från stupade plundrare ute på fältet.",al={"var får man tag på gnoll paws","vem släpper gnoll paws","gnoll paws ursprung"}}},fp="9,159,21.406.0,20.372.1,41.213.0,29.98.0,40.147.1,50.195.0"}
P.entries["item:gnomeregan-gumdrop"] = {n="Gnomeregan Gumdrop",s="Under Hallow's End når Gnomeregan Gumdrop resenärer från de förvisade gnomerna. En sötsak hjälper sjuke Jesper att fira på barnhemmet i Stormwind.",h="Under Hallow's End når Gnomeregan Gumdrop resenärer från de förvisade gnomerna.",kw={"godis","gnomeregan gumdrop","hallow's end","ironforge","jesper","stormwind","talvash del kissel"},ang={["faction:Alliance"]="Du reser mellan mänskliga, dvärglika och gnomiska samhällen för att samla in sötsaken och dela Alliansens nära band under årstidens firande.",["race:Gnome"]="Även om gnomerna inte har återtagit någon egen stad, gör deras klassiska sötsak sällskap med godsakerna från Alliansens stora huvudstäder under Hallow's End."},sec={{t="Ett smakprov på gnomisk uppfinningsrikedom",b="I Mystic Ward i Ironforge delar Talvash del Kissel ut Gnomeregan Gumdrop till resenärer som spelar med i hans Hallow's End-trick. Värdshusvärdar i hela Alliansen erbjuder lokala godsaker, men de förvisade gnomerna har inget eget värdshus i någon huvudstad. Den radioaktiva katastrofen drev bort dem från deras underjordiska kungarike, men de delar fortfarande sina särpräglade sötsaker med Alliansen."},{t="En godsak till Jesper",b="Sjuke Jesper är hänvisad till barnhemmet i Stormwind på Cathedral Square och kan inte resa runt på kontinenterna för att gå bus eller godis. Resenärer samlar fyra regionala godsaker från Alliansens huvudstäder för att ta med till honom: Gnomeregan Gumdrop, Stormwind Nougat, Ironforge Mint och Darnassus Marzipan."}},faq={{q="Var kommer Gnomeregan Gumdrop ifrån?",a="Talvash del Kissel delar ut Gnomeregan Gumdrop i Mystic Ward i Ironforge när du spelar med i ett av hans Hallow's End-trick.",al={"vem delar ut gnomeregan gumdrop","hur får man gumdrop","gumdrop plats"}},{q="Varför delas det här godiset inte ut i Gnomeregan?",a="Troggs tog över och bestrålade Gnomeregan, vilket tvingade de överlevande gnomerna i exil. Många bor nu tillsammans med dvärgarna i Ironforge, däribland Talvash del Kissel.",al={"varför ironforge","varför är talvash i ironforge"}},{q="Vad används det här godiset till?",a="Du tar med sötsaken till Jesper, en sjuk föräldralös pojke på barnhemmet i Stormwind på Cathedral Square. Den är en av fyra festliga sötsaker som samlas in åt honom under Hallow's End.",al={"vad gör gumdrop","jespers godis"}},{q="Vilka andra godsaker samlas in tillsammans med den?",a="Jesper ber också om Stormwind Nougat, Ironforge Mint och Darnassus Marzipan. Du samlar in var och en i sin respektive huvudstad i Alliansen.",al={"andra godissorter","hallow's end-godsaker"}}},fx={["243db981"]={q="Vad är Gnomeregan Gumdrop?",a="Gnomeregan Gumdrop är ett festligt godis som representerar gnomfolket och delas ut under högtiden Hallow's End. Trots att det är uppkallat efter Gnomeregans förlorade tekniska underverk delas godiset ut av gnomer som sökt skydd i dvärgarnas huvudstad Ironforge, framför allt uppfinnaren Talvash del Kissel.",al={"vad är gnomeregan gumdrop","godiset gnomeregan gumdrop","gnomeregan gumdrop i historien"}}},fp="18,146,28.374.0,18.290.0,42.121.0,46.162.0,28.168.0,45.130.0"}
P.entries["item:gnomish-tools"] = {n="Gnomish Tools",s="Längs Durotars kust ligger Gnomish Tools bland vraken efter Proudmoores flotta. Horden söker efter de bärgade redskapen för att studera Alliansens ingenjörskonst och anpassa dess uppfinningar för sin överlevnad.",h="Längs Durotars kust ligger Gnomish Tools bland vraken efter Proudmoores flotta.",kw={"durotar","ingenjörskonst","gar'thok","gnomish tools","proudmoore","razor hill","scuttle coast","tiragarde keep"},ang={["faction:Horde"]="Som medlem av Horden kan du hjälpa till att bärga förlorad utrustning från Alliansen för studier. Kunskap om fiendens konstruktioner och främmande mekanismer kan hjälpa Horden att försvara sig mot framtida flottinvasioner.",["profession:Engineering"]="Som ingenjör kan du studera satserna och få inblick i Alliansens pillrares noggranna hantverk, urverksmekanismer och miniatyrisering."},sec={{t="Bärgning från djupet",b="Storamiral Daelin Proudmoores flotta förde med sig väldiga mängder modern utrustning till Durotar. Proudmoore ledde Kul Tiras och Alliansens styrkor till dess stränder, med avancerad utrustning från deras gnomiska allierade ombord. När flottan förstördes längs Scuttle Coast, öster om Tiragarde Keep, sjönk de ömtåliga mekaniska verktygssatserna under vågorna. Vattentäta verktygslådor ligger fortfarande bland ruttnande timmer och skeppsskrov täckta av havstulpaner på grunt vatten."},{t="Ögon i Orgrimmar",b="Gar'Thok, som håller uppsikt över Razor Hill, skickade ut hordespejare för att hämta verktyg ur Proudmoores flotta, som fått sin grav i vattnet. Orcherna vet att människor och gnomer är skickliga på ingenjörskonst, särskilt belägringsmaskiner, skeppsbygge och urverksmekanik. De skickar satserna med karavan till hantverkare och lärda i Orgrimmar. Där tänker Horden studera Alliansens konstruktioner, lära sig att stå emot fiendens krigsmaskiner och anpassa främmande uppfinningar för sin egen överlevnad."}},faq={{q="Varför ligger gnomiska verktyg utanför Durotars kust?",a="Storamiral Daelin Proudmoores flotta förde verktygen med sig när Kul Tiras anföll Durotar. När armadan krossades och sjönk längs Scuttle Coast, öster om Tiragarde Keep, hamnade flottans last på havsbotten.",al={"varför gnomiska verktyg här","gnomiska verktygens ursprung","hur hamnade verktygen i durotar"}},{q="Varför vill Horden ha de här verktygen?",a="Gar'Thok från Razor Hill vill att verktygen bärgas och skickas till Orgrimmar. Studier av Alliansens ingenjörers intrikata mekaniska kunnande kan hjälpa Horden att förstå fiendens maskiner och bygga bättre utrustning själv.",al={"varför vill gar'thok ha verktygen","hordens användning av gnomiska verktyg","vad används verktygen till"}},{q="Var finns verktygen?",a="Verktygen ligger i verktygslådor som är utspridda i och kring sjunkna vrak längs Durotars Scuttle Coast, strax öster om Tiragarde Keep. Många ligger under vatten eller på sönderslagna skrov som sticker upp till hälften ur vattnet.",al={"gnomiska verktygens plats","var hittar man gnomiska verktyg","gnomiska verktygslådors plats"}}},fx={bc7dc32b={q="Vad är det här för Gnomish Tools?",a="Det här är specialiserade mekaniska verktyg tillverkade av Alliansens gnomer. De är högt värderade för sin precision och sinnrika utformning och representerar några av Azeroths mest avancerade ingenjörskonst. De fanns ombord på storamiral Proudmoores krigsfartyg för att underhålla och reparera avancerad alliansutrustning, men spreds över havsbottnen utanför Durotars kust när hans flotta gick under.",al={"vad är gnomish tools","information om gnomish tools"}}},fp="13,187,14.449.0,17.453.0,53.223.0,36.216.0,26.186.0"}
P.entries["item:gold-dust"] = {n="Gold Dust",s="I Elwynn Forest samlar kobolder guldflisor och lägger dem på hög i gruvorna. Lokala köpare betalar för stoftet, medan gruvarbetare söker hela malmådror.",h="I Elwynn Forest samlar kobolder guldflisor och lägger dem på hög i gruvorna.",kw={"elwynn","fargodeep","gold dust","goldshire","goldtooth","jasperlode","kobold","remy two times"},ang={["class:Rogue"]="Som skurk kan du få veta hur underjorden förflyttar oraffinerat, ospårat damm genom skumma handlare som Remy \"Two Times\" och döljer obearbetade rikedomar för Stormwinds magistrater.",["profession:Mining"]="Gruvarbetare söker efter solida ådror av koppar och tenn med hacka och vaskpanna. Koboldernas damm antyder att Elwynns underjordiska gångar rymmer rikare malmådror än vanliga undersökningar visar."},sec={{t="En påse full av skrot",b="Kobolder gräver i Fargodeep Mine och Jasperlode Mine under Elwynn Forest. De sparar gulddammet de hittar i fickor och påsar i stället för att rena det. Lokala gårdfarihandlare och hälarna vill ha dessa småfynd och hoppas tjäna pengar utan att betala officiella smältningstullar."},{t="Goldshires svarta marknad",b="I Goldshire ber Remy \"Two Times\" resenärer att ta med återvunnet gulddamm till honom. Han säger att han erbjuder det bästa priset i staden och byter mynt och misstänkta polletter mot obearbetat damm på uppdrag av namnlösa medhjälpare. Resenärer hämtar guldet från kobolder, medan mäklarna säkrar rikedomar mitt framför näsan på Stormwinds vakter."}},faq={{q="Var kommer Gold Dust ifrån?",a="Kobolder i hela Elwynn Forest bär på Gold Dust. Gruvarbetare, tunnelgrävare, geomantiker och deras ledare Goldtooth samlar det och lägger det på hög medan de gräver sig genom kullarna.",al={"hur får man tag på gold dust","gold dust byte","var hittar man gold dust"}},{q="I vilka gruvor finns flest kobolder som bär på Gold Dust?",a="Kobolder med gulddamm svärmar i både Fargodeep Mine, söder om Goldshire, och Jasperlode Mine, i nordost.",al={"var finns gruvorna","bästa gruvan för gold dust","gruvornas platser"}},{q="Vem köper Gold Dust i Elwynn Forest?",a="Remy \"Two Times\", en skum handlare utanför Lion's Pride Inn i Goldshire, köper insamlade påsar med Gold Dust för pengar och polletter från sina medhjälpare.",al={"vem vill ha gold dust","remy two times gold dust","lämna in gold dust"}},{q="Varför bär kobolder på damm i stället för tackor?",a="Kobolder saknar disciplinen och infrastrukturen för att smälta malm ordentligt. När de gräver sig genom berget med grova hackor samlas löst gulddamm på deras tillhörigheter och i små påsar som de bär som glänsande prydnader.",al={"varför har kobolder damm","koboldguld"}}},fx={["38570104"]={q="Vad är Gold Dust?",a="Gold Dust består av fina, råa flingor av dyrbart guld som brutits av koboldhorderna under Elwynn Forest. Det är varken förädlad valuta eller gjutet guldtackeguld, utan råmaterial som kobolderna hackar loss direkt från rika ådror på platser som gruvorna Fargodeep och Jasperlode.",al={"vad är gold dust","föremålet gold dust","om gold dust"}},["4a74ebdb"]={q="Varför vill Remy Two Times ha Gold Dust?",a="Remy \"Two Times\" i Goldshire köper upp rått gulddamm för sin egen handel och sina skumraskbekanta. Kobolderna kan föga om att smälta tackor, så det finns gott om oredovisade mineraltillgångar på deras kroppar för den som är djärv nog att ta dem och sälja dem vidare.",al={"varför vill remy ha gold dust","varför vill man ha gold dust","varför vill remy two times ha gold dust"}}},fp="9,140,22.262.0,24.319.1,31.158.0,53.109.0,36.153.0,44.214.0"}
P.entries["item:golm-fragment"] = {n="Golm Fragment",s="Golm Fragment är en av fyra saknade bitar som huggits loss från Goaz Stone, en uråldrig relik som grävts fram vid utgrävningsplatsen i Wetlands. Äventyrare hämtar den medan de undviker våldsamma rovfåglar, och den hjälper dvärgarkeologer att sammanfoga mystiska titaninskrifter.",h="Golm Fragment är en av fyra saknade bitar som huggits loss från Goaz Stone, en uråldrig relik som grävts fram...",kw={"utgrävningsplats","goaz stone","golm fragment","uncovering the past","wetlands","whelgar"},ang={["faction:Alliance"]="När du hämtar fragmentet hjälper du Explorers' League att säkra ovärderlig uråldrig kunskap innan rovfåglarna tar över hela utgrävningsplatsen.",["race:Dwarf"]="För dvärgar är det viktigt att sammanfoga bitarna av Goaz Stone för att upptäcka deras titanursprung och den dolda historien som ligger begravd i Khaz Modan."},sec={{t="En bit av Goaz Stone",b="Golm Fragment upptäcktes vid utgrävningsplatsen i södra Wetlands och är en del av en monumental stenhäll som kallas Goaz Stone. Prospector Whelgar upptäckte stenen strax innan rovfåglar drev tillbaka Explorers' League, men fann att inskriften var avbruten på fyra viktiga ställen. Golm Fragment övergavs bland jord och omkullvälta lådor när utgrävningen blev överrumplad, och gömdes i en uråldrig relikask tills modiga utforskare kunde hämta den."},{t="Titanernas hemligheter",b="När Golm Fragment återförenas med fragmenten Ados, Modr och Neru blir den en kryptisk titantext som förutsäger en ”gudomlig plan” och en ”ödesdiger profetia”. När stenen sätts ihop kan Whelgar tyda rader som hänvisar till uråldriga väsen kedjade under jorden, vilket bekräftar att platsen rymmer kunskap som är långt äldre och farligare än ett enkelt dvärgarv."}},faq={{q="Vad används Golm Fragment till?",a="Det är en av fyra stenbitar som Prospector Whelgar behöver vid utgrävningsplatsen i Wetlands för att återställa Goaz Stone under uppdraget Uncovering the Past.",al={"golm fragment användning","varför behövs golm fragment","golm fragment uppdrag"}},{q="Var hittar man Golm Fragment?",a="Den finns bland uråldriga reliker och lös jord som ligger utspridda på utgrävningsplatsen i de södra kullarna i Wetlands, där det kryllar av rovfåglar.",al={"golm fragment plats","hitta golm fragment","var finns golm fragment"}},{q="Vad står det på Goaz Stone när den har satts ihop?",a="Whelgars första översättning talar om en gudomlig plan och en ödesdiger profetia. Han behöver alla fyra fragmenten för att fortsätta tyda den ofullständiga titantexten.",al={"goaz stone översättning","vad står det på stentavlan","whelgars översättning"}},{q="Vilka andra fragment behövs för att färdigställa stenen?",a="Förutom Golm måste du hämta fragmenten Ados, Modr och Neru för att sätta ihop hela stentavlan.",al={"andra fragment till stentavlan","goaz stone bitar","fyra fragment"}}},fx={["523a83d7"]={q="Vad är Golm Fragment?",a="Golm Fragment är en av fyra saknade bitar som brutits loss från Goaz Stone, en forntida relik som grävts fram vid utgrävningsplatsen i Wetlands. Den bär arkaiska inskrifter som passar in i den större tavlans gåtfulla berättelse.",al={"vad är golm fragment","golm fragment i historien","vad är golm-biten"}},["890266ad"]={q="Var kommer Golm Fragment ifrån, och vem skapade det?",a="Fragmentet var ursprungligen en del av Goaz Stone, som höggs ut i titanernas skrift för länge sedan. Det grävdes fram under dvärgarnas arkeologiska utgrävning i Wetlands, innan fientliga rovfåglar invaderade området och skingrade de sönderslagna bitarna.",al={"vem skapade golm fragment","golm fragments ursprung","varifrån kommer golm fragment"}},["6695e471"]={q="Varför vill Prospector Whelgar ha Golm Fragment?",a="Prospector Whelgar behöver Golm Fragment tillsammans med de andra bitarna för att sätta ihop hela Goaz Stone. Utan den bryts den översatta texten plötsligt av, och viktiga detaljer om en gudomlig plan och en ödesdiger profetia saknas.",al={"varför behöver whelgar golm fragment","vem vill ha golm fragment","varför leta efter golm fragment"}}},fp="13,266,25.462.0,21.363.1,35.155.0,37.137.0,44.157.1,52.98.0"}
P.entries["item:gordon-s-crate"] = {n="Gordon's Crate",s="Gordon's Crate är en tung vapensändning som packats i Undercity för Forsaken-styrkorna i Silverpine Forest. Den ska föras direkt till den avlägsna garnisonen vid The Sepulcher.",h="Gordon's Crate är en tung vapensändning som packats i Undercity för Forsaken-styrkorna i Silverpine Forest.",kw={"fladdermusförare","deathguard podrig","gordon's crate","gordons crate","karos razok","michael garrett","förnödenheter till silverpine","the sepulcher","undercity"},ang={["faction:Horde"]="Leveransen visar hur Forsakens flygrutter blir allt mer samordnade och snabbt för förnödenheter och kurirer över det omstridda Lordaeron.",["race:Undead"]="Varje sändning med klingor och utrustning från huvudstaden befäster Lady Sylvanas osäkra gränser i Silverpine Forest."},sec={{t="Förnödenheter till Silverpine",b="För att Forsaken ska behålla sitt grepp om Silverpine Forest krävs ett jämnt flöde av förnödenheter från Undercity. Gordon's Crate innehåller vapen som ska förstärka Deathguard Podrigs försvarare vid The Sepulcher, så att utpostens vakter inte överrumplas av worgen, vilddjur eller kvarvarande människor som lurar i skogen."},{t="Fladdermusförarens rutt",b="Eftersom landsvägarna ut från huvudstaden är farliga och långsamma förlitar sig värdefulla sändningar på Undercitys fladdermusförare. Lådan lämnas till Michael Garrett, fladdermästaren som håller till ovanför stadens Trade Quarter. Han ordnar färd med en tränad flygande fladdermus tillbaka till Karos Razoks näste vid The Sepulcher."}},faq={{q="Vad finns i Gordon's Crate?",a="Lådan innehåller vapen och viktiga stridsförnödenheter som rekvirerats från Undercity för att förstärka Deathguard-vakterna i Silverpine Forest.",al={"innehållet i gordons crate","vad innehåller lådan"}},{q="Vem ska ta emot Gordon's Crate?",a="Deathguard Podrig vid The Sepulcher tar emot lådan. För transporten måste du samordna med Undercitys fladdermusförare Michael Garrett för att ordna en direktflygning.",al={"vem får gordons crate","vart ska lådan"}},{q="Varför transporteras lådan med fladdermus i stället för av en kurir till fots?",a="Silverpine Forest är fortfarande omstritt och farligt. Tränade fladdermöss under uppsikt av förare som Michael Garrett och Karos Razok ger snabb transport genom luften och undviker hot längs markvägarna.",al={"varför flyga lådan","fladdermus och låda"}},{q="Varför kräver Michael Garrett att du besöker The Sepulcher först?",a="Forsaken-fladdermöss återvänder instinktivt till huvudstaden, men för att nå avlägsna baser som The Sepulcher på ett säkert sätt måste resenärer först knyta kontakt med den lokala föraren, Karos Razok, innan fladdermössen kan göra färden.",al={"varför behövs en flygrutt","krav för fladdermusflygning"}}},fx={df26763c={q="Vad är Gordon's Crate?",a="Gordon's Crate är en leverans med viktiga vapen och militära förnödenheter som packats i Undercity. Den har förberetts särskilt för att flygas med fladdermusförare till den avlägsna Försakade utposten vid The Sepulcher.",al={"gordon's crate","vad är det här för låda","gordons crate"}},e23fc119={q="Var kommer Gordon's Crate ifrån, och vem gjorde den?",a="Lådan kommer från Undercity, där Gordon packade garnisonens förnödenheter innan han ordnade leveransen till fladdermusförarna.",al={"varifrån kommer gordons crate","vem packade gordons crate","vem gjorde gordons crate"}},a5301c7a={q="Varför vill någon ha Gordon's Crate?",a="Deathguard Podrig och soldaterna som är stationerade vid The Sepulcher behöver verkligen leveransen. Lådan innehåller vapen som behövs för att se till att de lokala Deathguards som försvarar Silverpine Forest är välbeväpnade och inte blir överrumplade av sina fiender.",al={"varför behövs gordons crate","varför ta gordons crate till the sepulcher","vem behöver gordons crate"}}},fp="14,170,23.252.0,23.301.0,30.142.0,42.134.0,65.191.0,66.192.0"}
P.entries["item:grape-manifest"] = {n="Grape Manifest",s="På Northshire Abbey registrerar Grape Manifest druvor som bärgats från Milly Osworths vingård efter att banditer lagt beslag på skörden. Frukten är på väg till klostrets källare.",h="På Northshire Abbey registrerar Grape Manifest druvor som bärgats från Milly Osworths vingård efter att...",kw={"brother neals","elwynn","grape manifest","milly osworth","northshire abbey","vingård","vin"},ang={["profession:Cooking"]="För kockar visar förteckningen hur skördar från fälten förser klostrets förråd och hjälper till att mätta dess munkar.",["race:Human"]="Som människa kan du se de tidiga prövningarna i Stormwinds hjärtland: även klosterliv och enkla skördar behöver väpnat försvar mot kringströvande laglösa."},sec={{t="En förteckning över skörden",b="Milly Osworth sköter en vingård i Northshire Valley, där de lokala gårdarna hjälper till att försörja Northshire Abbey. Defias-banditer lade beslag på skörden, vilket hotade klostrets tillgång på färsk frukt och druvor för jäsning. Grape Manifest registrerar druvorna som återtagits från fälten och deras mängd, så att klostrets förrådsförvaltare kan hålla räkning på förråden och förbereda tunnor för jäsning."},{t="Klostrets källarmästare",b="Brother Neals ansvarar för mat och dryck på Northshire Abbey, och han tycker om att provsmaka dess vin i klocktornets stillhet. Förteckningen talar om för honom att druvorna är på väg och hjälper till att se till att munkar och rekryter på besök har något att dricka. För klostrets bröder är varje räddad skäppa en seger för förråden och en välsignelse från det Heliga Ljuset."}},faq={{q="Vad är Grape Manifest?",a="Grape Manifest är en förteckning skriven av Milly Osworth som registrerar skörden som bärgats från hennes överfallna vingård. Den håller reda på de färska druvorna som levereras till Northshire Abbey.",al={"vad är grape manifest","föremålet grape manifest"}},{q="Vem tar emot förteckningen?",a="Brother Neals tar emot förteckningen. Han ansvarar för klostrets mat- och vinförråd och provsmakar ofta årgångar i klocktornet på Northshire Abbey.",al={"vem får grape manifest","vem ska jag ge grape manifest till","vart ska grape manifest"}},{q="Varför var druvorna i fara?",a="Defias-banditer slog till i Northshire Valley och drev bort Milly Osworth från hennes vingård. Skörden hotades och klostret blev utan färsk frukt tills rekryterna ingrep.",al={"varför behövde druvorna räddas","banditer vid vingården","vad hände med millys skörd"}},{q="Vad gör Brother Neals med druvorna?",a="Brother Neals använder druvorna för att fylla på klostrets matförråd och jäsa färskt Northshire-vin åt brödraskapet som bor där och försvarare på besök.",al={"vad används druvor till","klostervin"}}},fx={a2f30a46={q="Var kommer Grape Manifest ifrån, och vem skrev det?",a="Milly Osworth, en bonde som arbetar i Northshire Valleys vingårdar, upprättar manifestet. När du har hjälpt henne att driva bort Defias-rövarna som intog hennes fält och återta den skördade druvan, sammanställer hon dokumentet för att redovisa den räddade skörden.",al={"vem skrev grape manifest","varifrån kommer grape manifest","grape manifests ursprung"}},cbb35726={q="Varför behövs Grape Manifest?",a="Brother Neals sköter mat- och dryckesförråden vid Northshire Abbey. Milly skickar manifestet för att meddela honom att hennes skörd har räddats från banditerna, så att klostrets vinmakare kan räkna med färska druvor till vintillverkningen.",al={"varför vill brother neals ha grape manifest","grape manifests syfte","varför behövs grape manifest"}}},fp="14,173,23.388.0,20.332.0,27.185.0,26.142.0,30.184.0,43.153.0"}
P.entries["item:gray-bear-tongue"] = {n="Gray Bear Tongue",s="En gråbjörnstunga är en rå ingrediens som skördas från vildbjörnarna i Hillsbrad Foothills. Royal Apothecary Society i Tarren Mill efterfrågar den som biologisk beståndsdel i sina experimentella gifter.",h="En gråbjörnstunga är en rå ingrediens som skördas från vildbjörnarna i Hillsbrad Foothills.",kw={"apothecary lydon","big samras","elixir of suffering","gray bear tongue","hillsbrad foothills","royal apothecary society","tarren mill"},ang={["race:Undead"]="Att skaffa organiska ingredienser från det lokala djurlivet hjälper Royal Apothecary Society direkt i dess uppdrag att skapa nya plågor mot de levande."},sec={{t="Apotekarstudier i Hillsbrad",b="Den otämjda vildmarken kring Tarren Mill är rik på inhemsk fauna, däribland flera sorters kraftiga gråbjörnar. Naturliga rovdjur utgör ett ständigt hot mot resande, men Forsaken ser dem som en skördekälla för råa alkemiska ingredienser. Apothecary Lydon studerar det lokala djurlivet för att isolera potenta organiska ämnen och använder den tjocka muskelvävnaden och vätskorna från gråbjörnstungor som basingredienser i dödliga brygder, såsom Elixir of Suffering."}},faq={{q="Vem vill ha gråbjörnstungor?",a="Apothecary Lydon, stationerad vid Forsaken-utposten Tarren Mill i Hillsbrad Foothills, söker tungorna för att brygga experimentella dödsmedel.",al={"vem behöver björntungor","apothecary lydon tungor","lämna in björntunga"}},{q="Vad ska apotekaren använda tungorna till?",a="Lydon utvecklar en dödlig brygd kallad Elixir of Suffering, avsedd att hjälpa till att hemsöka Hillsbrads levande människobefolkning med pest. Tungorna är ett av de viktigaste organiska ämnena, tillsammans med Creeper Ichor.",al={"varför vill lydon ha tungor","björntungans syfte","ingredienser i elixir of suffering"}},{q="Vilka varelser lämnar efter sig tungorna?",a="De kan skördas från alla lokala gråbjörnar i Hillsbrad Foothills, däribland vanliga gråbjörnar, äldre gråbjörnar, våldsamma gråbjörnar och det ökända odjuret Big Samras.",al={"var får man björntungor","vilka björnar har tungor","björnar i hillsbrad"}}},fx={["57051fe5"]={q="Vad är Gray Bear Tongue?",a="Det är precis vad det låter som: en färskt utskuren tunga från en av de vilda gråbjörnar som strövar omkring i Hillsbrad Foothills. De flesta resenärer tycker att det är motbjudande, men alkemister och forskare bland de Fördömda värdesätter djurvävnad för dess särskilda kemiska egenskaper när de blandar nya brygder.",al={"vad är gray bear tongue","föremålet gray bear tongue","vad är gray bear tongues"}},["4de594f1"]={q="Var kommer en Gray Bear Tongue ifrån?",a="Tungorna tas direkt från gråbjörnarna som strövar i skogarna och kullarna kring Tarren Mill i Hillsbrad Foothills. Jägare kan få dem från vanliga gråbjörnar, äldre exemplar, våldsamma varianter eller namnkunniga bestar som Big Samras.",al={"gray bear tongues ursprung","varifrån kommer gray bear tongues","vem släpper gray bear tongues"}}},fp="16,137,32.230.0,28.155.0,47.214.0,35.181.0"}
P.entries["item:gregor-s-remains"] = {n="Gregor's Remains",s="Gregor's Remains är de fysiska benen som återfanns efter Gregor Agamand, som Scourge hade gjort till sin slav. Hans kvarlevor söks av en före detta mjölnare som vill göra upp en gammal räkning från andra sidan graven.",h="Gregor's Remains är de fysiska benen som återfanns efter Gregor Agamand, som Scourge hade gjort till sin slav.",kw={"agamand","brill","coleman","dödsfall i familjen","farthing","gregor","kvarnar","kvarlevor","scourge"},ang={["faction:Horde"]="När du rensar Agamand Mills tillfogar du Scourges kvarvarande härdar ett direkt slag och skyddar Tirisfal Glades säkerhet.",["race:Undead"]="Agamand-familjens tragedi speglar många Forsakens öde: vanligt folk som förråddes av adelns stolthet och lämnades åt pestens fasor."},sec={{t="Ett arv av förödelse",b="Före det tredje kriget hade familjen Agamand enorma rikedomar och stora landområden i norra Tirisfal Glades. När Scourge invaderade Lordaeron valde familjens överhuvuden stolthet framför flykt. De befäste familjens kvarnar och övertalade sina trogna arbetare att göra ett desperat motstånd mot de odöda. Försvaret misslyckades fullständigt. Godset blev översvämmat av fiender, och de som stannade kvar slaktades och återuppväcktes som odöda. Gregor Agamand blev ännu en viljelös träl i Lich Kings tjänst och hemsökte kvarnarna som familjen en gång styrde."},{t="Hämndens pris",b="För överlevare som slet sig loss från Lich Kings grepp och anslöt sig till Forsaken är minnet av det ödesdigra försvaret fortfarande ett bittert sår. Coleman Farthing, en före detta mjölnare stationerad i Brill, anklagar familjen Agamands högmod för att ha fångat hans själ i evig förruttnelse. Om Farthing får samla in Gregor's Remains får han en personlig hämnd och kan sätta punkt för historien om en herre som ledde sitt hushåll rakt in i fördärvet."}},faq={{q="Vem var Gregor Agamand?",a="Gregor Agamand var en framstående medlem av dynastin Agamand, den rikaste jordägande familjen i Tirisfal Glades före det tredje kriget. När de odödas pest kom valde han och hans familj att befästa sitt gods i stället för att fly. Alla där inne slaktades och återuppväcktes.",al={"gregors historia","vem är gregor","gregor agamand"}},{q="Varför vill Coleman Farthing ha Gregor's Remains?",a="Coleman Farthing arbetade som mjölnare åt familjen Agamand när han levde. Han hyser djupt agg mot familjen för att de övertalade arbetarna att stanna och kämpa mot Scourge, ett ödesdigert misstag som dömde dem alla till att bli odöda. Att få Gregors kvarlevor överlämnade till sig blir en hämnd som länge fått vänta.",al={"varför coleman vill ha kvarlevorna","coleman farthings agg","varför samla gregors ben"}},{q="Var hittar man Gregor's Remains?",a="Kvarlevorna återfinns hos den återuppväckte Gregor Agamand vid Agamand Mills, i Tirisfal Glades norra kullar.",al={"var hittar man gregor","gregors plats","gregor vid agamand mills"}},{q="Tillhör familjen Agamand Forsaken?",a="Nej. Till skillnad från Forsaken, som slet sig fria under drottning Sylvanas, är Gregor Agamand och hans släkt fortfarande viljelösa tjänare, bundna till Scourges vilja.",al={"är gregor forsaken","är agamand en del av scourge","vem styr gregor"}}},fx={["6dd1de2a"]={q="Vad är Gregor's Remains?",a="De är de fysiska kvarlevorna efter Gregor Agamand, en av arvingarna till den framstående Agamand-dynastin. Efter att ha fallit offer för de odödas pest återuppstod Gregor som en viljelös hantlangare åt Scourge och hemsökte ruinerna av familjens en gång så blomstrande kvarnar tills han slutligen besegrades.",al={"vad är gregors remains","föremålet gregors remains"}},["45ae8d93"]={q="Var kommer Gregor's Remains ifrån?",a="De här kvarlevorna är det som återstår av Gregor Agamand efter att han fällts vid Agamand Mills i västra Tirisfal Glades. När Scourge svepte genom Lordaeron befäste hans familj sitt gods och uppmanade arbetarna att stanna och kämpa, men alla slaktades och återuppväcktes som odöda.",al={"ursprunget till gregor's remains","vem skapade gregor's remains","var kom gregor's remains ifrån"}}},fp="16,154,16.481.0,22.352.0,23.279.0,48.232.0,33.109.0,38.134.0"}
P.entries["item:grelin-s-report"] = {n="Grelin's Report",s="Grelin's Report är en rapport skriven av Grelin Whitebeard om Frostmane-trollens situation i Coldridge Valley. Den anförtros åt en äventyrare i stället för en novislärling och utgör den officiella länken mellan spejarna som vaktar Anvilmar och Senir Whitebeard, som är stationerad i Kharanos.",h="Grelin's Report är en rapport skriven av Grelin Whitebeard om Frostmane-trollens situation i Coldridge Valley.",kw={"coldridge valley","grelin whitebeard","grelin's report","ironforge-senaten","kharanos","mountaineer thalos","senir whitebeard"},ang={["race:Dwarf"]="Att bära rapporten är en dvärgs färd från Coldridges trygga övningsmarker till det vidare försvaret av Dun Moroghs kärnland och tjänsten hos Ironforge.",["race:Gnome"]="När du levererar Grelins meddelande får gnomiska flyktingar visa sitt mod för dvärgarnas bergsvakter medan de färdas genom de gemensamma bergspassen i Dun Morogh."},sec={{t="En rapport förbi troggarna",b="Efter att ha bevakat Frostmane-trollen i Coldridge Valley drar Grelin's Report slutsatsen att de inte utgör något större hot och kan hanteras av Mountaineers som redan är stationerade där och av legosoldater som betalas med medel från senaten. I stället för att anförtro sin fumlande lärling denna viktiga underrättelse tar Grelin hjälp av en kapabel resenär som kan föra dokumentet genom det trogginfekterade Coldridge Pass. Papperet fungerar som ett officiellt pass genom Mountaineer Thalos' vägspärr och bevisar att bäraren är på brådskande uppdrag i den vidsträckta snöiga vildmarken i Dun Morogh."},{t="Upprörda känslor i Kharanos",b="När rapporten överlämnas till Senir Whitebeard på Thunderbrew Distillery i Kharanos innehåller den viktiga fältrapporter som är avsedda för Ironforge. Senir konstaterar med road uppgivenhet att hans bror åberopade King Magni Bronzebeard flitigt i texten. Grelin hävdar att kungen har godkänt insatsen, och Senir räknar med att vädjan till kunglig auktoritet kommer att uppröra några i Ironforge-senaten."}},faq={{q="Vad är syftet med Grelin's Report?",a="Rapporten förmedlar Grelin Whitebeards bedömning av Frostmane-trollen från Coldridge Valley till hans bror Senir i Kharanos. Den försäkrar ledarna utanför dalen om att trollen inte utgör något större hot och kan hanteras av lokala Mountaineers och legosoldater som betalas av senaten.",al={"vad är grelins rapport","varför skicka rapporten","grelin rapport syfte"}},{q="Varför kan Grelin inte överlämna den själv?",a="Grelin är kvar i Coldridge Valley och bevakar trollen. Han övervägde först att skicka sin lärling, men den farliga färden genom den trogginfekterade tunneln fick honom att i stället anförtro de viktiga dokumenten åt en stridsvan äventyrare.",al={"varför inte överlämna den","varför anförtro den åt en äventyrare"}},{q="Varför låter Mountaineer Thalos dig passera med rapporten?",a="Mountaineer Thalos vaktar tunneln ut ur Coldridge Valley för att skydda civila från våldsamma troggar. Att du har Grelin's Report visar att du färdas i ett brådskande ärende som rör dvärgarnas försvar, och övertygar Thalos om att släppa igenom dig.",al={"varför släpper thalos igenom mig","vägspärr i tunneln","troggar i coldridge pass"}},{q="Varför är Ironforge-senaten irriterad på rapporten?",a="Senir Whitebeard påpekar att Grelin åberopade King Magni flitigt i dokumentet. Att kringgå vanlig diplomatisk finkänslighet för att kräva kunglig uppmärksamhet gör ofta byråkraterna i Ironforge-senaten arga, även om bröderna håller med om att politikerna behöver en väckarklocka.",al={"varför är senaten arg","upprörda känslor","senirs reaktion"}}},fx={cdcce173={q="Vad är Grelin's Report?",a="Det är en skriftlig rapport som Grelin Whitebeard skrev i Coldridge Valley, adresserad till hans bror Senir Whitebeard i Kharanos. Den beskriver lokala iakttagelser och angelägna frågor i dalen, men Grelin åberopade King Magni Bronzebeards namn så frikostigt i texten att det väckte kontrovers bland senatorerna i Ironforge.",al={"vad är grelin's report","grelin's report"}},["9a092709"]={q="Var kommer Grelin's Report ifrån, och vem skrev den?",a="Dokumentet skrevs av Grelin Whitebeard när han var stationerad i Coldridge Valley. I stället för att anförtro det åt sin lärling bestämde sig Grelin för att lägga det i händerna på en kapabel resenär, så att det säkert skulle färdas österut genom den troggangripna tunneln som leder vidare in i Dun Morogh.",al={"vem skrev grelin's report","var kom grelin's report ifrån","vem skapade grelin's report"}},["6be6ebf1"]={q="Varför vill någon ha Grelin's Report?",a="Hans bror, Senir Whitebeard, väntar på rapporten i Kharanos för att samordna deras fynd innan de skickar sina gemensamma rapporter till Ironforge. Dokumentet är också viktigt för dig personligen: bevis på officiella Whitebeard-ärenden är det enda som får Mountaineer Thalos att låta dig passera genom den farliga, troggdrabbade tunneln ut ur Coldridge Valley.",al={"varför behövs grelin's report","varför vill senir ha grelin's report"}}},fp="15,291,26.564.0,29.414.0,39.279.0,36.253.0,57.230.0,50.280.0"}
P.entries["item:grelin-whitebeard-s-journal"] = {n="Grelin Whitebeard's Journal",s="Grelin Whitebeard's Journal är en personlig fältjournal som dvärgspanaren Grelin Whitebeard förde i Coldridge Valley. Den innehåller viktiga anteckningar om de lokala Frostmane-trollens aktiviteter. Frostmane-besten Grik'nir the Cold stal journalen och släpade den till trollgrottan i Coldridge Valley.",h="Grelin Whitebeard's Journal är en personlig fältjournal som dvärgspanaren Grelin Whitebeard förde i Coldridge...",kw={"coldridge valley","dun morogh","frostmane hold","grelin whitebeard","grik'nir the cold","senir whitebeard","stulen journal"},ang={["race:Dwarf"]="När journalen återtas säkras viktiga underrättelser åt dvärgarna om hotet från Frostmane-trollen, som närmar sig själva portarna till Ironforges övningsområden."},sec={{t="En spanares journal",b="När Grelin Whitebeard iakttog Frostmane-trollens aggressiva rörelser nära Coldridge Valley antecknade han noggrant sina iakttagelser i den här läderbundna journalen. Dokumentet innehåller hans råa fältobservationer om de inhemska vintertrollens styrka, organisation och hotnivå. Under en konfrontation eller ett bakhåll ryckte dock Grik'nir the Cold, en kraftigt märkt trollbest, åt sig journalen. Grelin tvingades därför be äventyrare på genomresa att söka igenom trollgrottan och ta tillbaka den innan han kunde färdigställa sin rapport."},{t="Meddelande till Senir",b="När Grelin återfår anteckningarna ur Grik'nirs grepp ger de honom tillräcklig trygghet för att bedöma hotet från trollen i Coldridge Valley som tillfälligt under kontroll. Med hjälp av de återfunna anteckningarna färdigställer Grelin sitt skriftliga meddelande om Frostmane-upproret. Det förseglas sedan och anförtros åt kurirer på väg till hans bror Senir Whitebeard, som är stationerad längre bort i Dun Morogh."}},faq={{q="Vem stal Grelin Whitebeards journal?",a="Journalen togs av Grik'nir the Cold, en framstående och kraftigt märkt Frostmane-trollbest som håller till djupt inne i trollgrottan i Coldridge Valley.",al={"vem tog journalen","vem har grelins journal","tjuven som stal grelins journal"}},{q="Vad står det i journalen?",a="Journalen innehåller Grelin Whitebeards egna spaningsanteckningar om de lokala Frostmane-trollen, deras hotnivå och säkerhetsläget i Coldridge Valley.",al={"journalens innehåll","vad finns i journalen","grelin whitebeards anteckningar"}},{q="Vad händer när journalen återfås?",a="När Grelin har hämtat sin journal använder han anteckningarna för att skriva en färdig underrättelserapport om trollens situation. Sedan ber han en äventyrare att leverera den till hans bror Senir Whitebeard.",al={"vad gör grelin med journalen","efter den stulna journalen"}},{q="Varför är journalen så viktig för Grelin?",a="Utan journalen kan Grelin inte sammanställa en korrekt spaningsrapport om Frostmane-upproret åt dvärgarnas myndigheter och sin bror Senir. Då är försvaret av Coldridge Valley osäkert.",al={"varför vill grelin ha tillbaka den","journalens betydelse"}}},fx={["15978139"]={q="Vad är Grelin Whitebeard's Journal?",a="Det är en personlig anteckningsbok som förs av Grelin Whitebeard, en observatör stationerad i Coldridge Valley. Där antecknar Grelin sina iakttagelser om Frostmane-trollens aktiviteter i området och sammanställer fältrapporter om dalens försvarsläge.",al={"vad är grelin whitebeard's journal","grelin's journal","grelins anteckningsbok"}},["9ed18e74"]={q="Var kommer Grelin Whitebeard's Journal ifrån, och vem skrev den?",a="Journalen sammanställdes av dvärgen Grelin Whitebeard under hans bevakning av Coldridge Valley. Men den rycktes ifrån honom och bars djupt in i den närliggande trollgrottan av Frostmane-bjässen Grik'nir the Cold.",al={"vem skapade grelin's journal","var kom grelin's journal ifrån","grelin's journals ursprung"}}},fp="27,191,16.425.0,17.299.1,38.142.0,31.130.0,44.133.1,43.189.0"}
P.entries["item:grell-earring"] = {fx={f6dd1a4f={q="Vad är ett Grell Earring?",a="Ett Grell Earring är ett enkelt smycke som bärs av de vilda grells och vidriga sprites som hemsöker ruinerna vid Bashal'Aran i Darkshore. De här upphittade örhängena är vanliga prydnader i sig, men har absorberat svaga magiska utsöndringar från ruinerna och från reliker som varelserna har hanterat.",al={"vad är grell earrings","grell earring-lore","vad är grell earring"}}}}
P.entries["item:grenka-s-claw"] = {n="Grenka's Claw",s="Grenka's Claw är en fysisk trofé som tagits från den mäktiga harpyan Grenka Bloodscreech i djupet av Roguefeather Den. När den överlämnas till Dorn Plainstalker vid The Weathered Nook är den ett obestridligt bevis på att en blivande äventyrare har klarat ett utmattande fysiskt prov högt uppe i ravinen.",h="Grenka's Claw är en fysisk trofé som tagits från den mäktiga harpyan Grenka Bloodscreech i djupet av...",kw={"dorn plainstalker","grenka bloodscreech","grenka's claw","harpya","roguefeather den","screeching canyon","test of endurance","thousand needles","the weathered nook"},ang={["faction:Horde"]="Att rensa Roguefeather Dens djup och göra slut på Grenka Bloodscreech minskar hotet från harpyorna som ständigt trakasserar resenärer kring Freewind Post.",["race:Tauren"]="Äldste Dorn Plainstalker ser det som sin heliga plikt att härda unga hjordekämpar med taurenriternas visdom och uthållighet innan de möter den större, hårdare världen."},sec={{t="En uthållighetstrofé",b="I Roguefeather Dens slingrande grottor, väster om Freewind Post, gömmer harpyor undan mat och försvarar våldsamt sitt revir mot främlingar. För att pröva de unga kämparnas fysiska uthållighet ger Dorn Plainstalker dem i uppgift att tränga in i de djupa boplatserna och förstöra flockens matförråd. En sådan djärv provokation väcker oundvikligen Grenka Bloodscreechs vrede. Att hugga av hennes onda klo och återvända med den bevisar att en krigare kan stå emot våg efter våg av ursinniga harpyor och överleva deras matriarks våldsamma anfall."}},faq={{q="Vad används Grenka's Claw till?",a="Klon fungerar som ett segerbevis för Dorn Plainstalker, en taurenäldste som bor vid The Weathered Nook i Thousand Needles. När du lämnar den till honom slutför du Test of Endurance och visar att du har den fysiska uthållighet som krävs för att överleva utdragen strid.",al={"användning av grenka's claw","varför behöver jag grenka's claw","grenka's claw uppdrag"}},{q="Vem är Grenka Bloodscreech?",a="Grenka Bloodscreech är en mäktig harpy som håller till i Roguefeather Den, i Screeching Canyon längs Thousand Needles södra klippor. Hon visar sig bara när inkräktare hotar flocken genom att förstöra dess matförråd.",al={"vem är grenka","grenka bloodscreech i berättelsen","vad är grenka"}},{q="Vart ska jag ta klon när jag fått tag på den?",a="Ta klon tillbaka till Dorn Plainstalker vid The Weathered Nook, inbäddat bland klipporna i Thousand Needles. Han tar emot trofén som bevis på att du har klarat ditt prov i fysisk uthållighet.",al={"var lämnar man in grenka's claw","vem vill ha grenka's claw"}},{q="Varför kräver Dorn Plainstalker just den här trofén?",a="Dorn Plainstalker vägleder unga resenärer genom krävande prov för att säkerställa att de är mentalt, andligt och fysiskt rustade för större faror. Att döda Grenka och ta hennes klo bevisar att en krigare kan uthärda både en svärms bakhåll och en dödlig ledarinnas direkta anfall.",al={"varför vill dorn ha klon","klons syfte"}}},fx={cd538a11={q="Vad är Grenka's Claw?",a="Grenka's Claw är en fysisk trofé från Grenka Bloodscreech, en mäktig harpyja som håller till djupt inne i Roguefeather Den i Screeching Canyon. Klorna höggs av den våldsamma varelsen efter att någon provocerat hennes flock och överlevt dess vrede. De är ett obestridligt bevis på att en blivande äventyrare hade orken och stridsförmågan att klara ett brutalt stridsprov.",al={"grenka's claw","vad är grenka's claw","om grenka's claw"}}},fp="13,294,21.537.0,31.263.0,27.249.0,42.191.0,55.290.0"}
P.entries["item:grimtotem-satchel"] = {n="Grimtotem Satchel",s="Djupt under Orgrimmar håller Maur Grimtotem fortfarande Grimtotem Satchel i sitt grepp. Troggs dödade tauren i Ragefire Chasm, men han skyddade påsen när han dog. När den återlämnas till Thunder Bluff blir Magatha Grimtotems intresse tydligt.",h="Djupt under Orgrimmar håller Maur Grimtotem fortfarande Grimtotem Satchel i sitt grepp.",kw={"elder rise","grimtotem","magatha grimtotem","maur grimtotem","ragefire chasm","rahauro","väska","thunder bluff","trogg"},ang={["faction:Horde"]="En död Grimtotem-kurir låg djupt inne i tunnlarna under Thralls huvudstad. Ragefire Chasm rymmer faror bortom sina bestar.",["race:Tauren"]="En Grimtotem begav sig djupt under Orgrimmar, och sedan nådde bud om vad han hittat Magatha på Elder Rise. Klanens förehavanden inom de förenade taurenstammarna är lågmälda och oroliga."},sec={{t="Ett dödsgrepp",b="Maur Grimtotem föll för troggs djupt inne i Ragefire Chasm, under Orgrimmar. Tauren höll fortfarande den enkla läderväskan när hans kropp hittades. Han hade kämpat för att skydda den medan troggs omringade honom. Vad kunde den innehålla som fick honom att vakta den med sitt liv?"},{t="Elder Crones intresse",b="Rahauro på Elder Rise i Thunder Bluff tar emot väskan åt Magatha Grimtotem, Grimtotemklanens matriark. Maur tjänade Magatha, och hon hade fått höra att han hittat något märkligt i grottorna under Orgrimmar innan han dog. Hon ordnade en belöning för att väskan skulle återlämnas oskadd. Grimtotemklanens ledare hade ett tydligt intresse för vad Maur hittade."}},faq={{q="Var hittar man Grimtotem Satchel?",a="Grimtotem Satchel hittades under Maur Grimtotems kropp, djupt inne i Ragefire Chasm, den vulkaniska grottan under Orgrimmar. Hans armar höll fortfarande om den där troggs dödade honom.",al={"väskans plats","var finns väskan","hur hittar man väskan"}},{q="Vem tillhör väskan?",a="Väskan tillhörde Maur Grimtotem, en medlem av Grimtotemklanen som gick in i Ragefire Chasm. Han höll den nära när troggs anföll.",al={"vem äger väskan","maur väskans ägare"}},{q="Vem vill få tillbaka väskan?",a="Rahauro på Elder Rise i Thunder Bluff tar emot väskan åt Magatha Grimtotem. Magatha ordnade en belöning för att få tillbaka sin fallne klanfrändes tillhörigheter.",al={"vem får väskan","vem lämnar in väskan","vem vill ha grimtotem satchel"}},{q="Varför bar en Grimtotem detta under Orgrimmar?",a="Maur Grimtotem tjänade Magatha Grimtotem, som intresserade sig för Ragefire Chasm. Han gick dit för att tala med troggsen och hittade något märkligt, men dog innan han kunde visa det för henne.",al={"varför var maur i ragefire","vad gjorde grimtotem i orgrimmar"}},{q="Vad finns i väskan?",a="Påsens innehåll förblir förseglat när Rahauro tar emot den i Thunder Bluff. Magatha hoppas att den innehåller spår av det märkliga som Maur hittade i grottan.",al={"väskans innehåll","vad finns i väskan"}}},fp="17,236,12.269.0,26.360.1,37.179.0,31.135.0,31.165.0,50.190.0,27.155.0"}
P.entries["item:grizzled-bear-heart"] = {n="Grizzled Bear Heart",s="Ett Grizzled Bear Heart är ett biologiskt reagens som utvinns ur de kraftiga björnarna i Silverpine Forest. Det är en viktig beståndsdel i Royal Apothecary Societys mörka forskning om The New Plague.",h="Ett Grizzled Bear Heart är ett biologiskt reagens som utvinns ur de kraftiga björnarna i Silverpine Forest.",kw={"en dödsbrygd","apothecary renferrel","grizzled bear heart","master apothecary faranell","the new plague","old vicejaw","royal apothecary society","silverpine forest","skittering blood"},ang={["class:Hunter"]="Silverpine Forests väldiga björnar är farliga byten, och att spåra odjur som Old Vicejaw efter biologiska prover sätter jägarens tålamod och förmåga att ta till vara bytet på prov.",["race:Undead"]="För Forsaken hjälper insamlingen av dessa organ direkt Master Apothecary Faranell att skapa det ultimata vapnet mot både Arthas's Scourge och de levande dödliga som hotar Lordaeron."},sec={{t="Ett reagens till The New Plague",b="Royal Apothecary Society arbetar oavbrutet med att utveckla en framställd pest som kan utrota både Scourge och den levande mänskligheten. I Silverpine Forests skogar upptäckte Apothecary Renferrel att ett unikt gift från hjärtat hos en grizzled bear, blandat med spindelblod, ger en anmärkningsvärt dödlig brygd. Kurirer och lojala Forsaken jagar våldsamma grizzled bears, giant grizzled bears och det ökända odjuret Old Vicejaw för att skära ut organen och leverera dem direkt till Master Apothecary Faranell, djupt inne i Undercitys Apothecarium."}},faq={{q="Vad används ett Grizzled Bear Heart till?",a="Grizzled Bear Hearts samlas in som experimentella reagenser åt Royal Apothecary Society. Apothecary Renferrel upptäckte att gifter från dessa hjärtan kan destilleras till ett dödligt elixir som en del av Forsakens försök att brygga The New Plague.",al={"vad gör björnhjärtat","uppdrag med björnhjärta","reagens till dödsbrygd"}},{q="Vem vill ha björnhjärtana?",a="Apothecary Renferrel i Silverpine Forest ber resande att samla hjärtana tillsammans med Skittering Blood och leverera dem direkt till Master Apothecary Faranell i Undercitys Apothecarium.",al={"vem behöver björnhjärtat","faranell björnhjärta","vem ska jag ge björnhjärtat till"}},{q="Var kommer Grizzled Bear Hearts ifrån?",a="De skärs ut ur de olika grizzled bears som strövar omkring i Silverpine Forest, däribland ferocious grizzled bears, giant grizzled bears och det väldiga kringströvande odjuret Old Vicejaw.",al={"var hittar jag björnhjärtan","vilka björnar släpper hjärta","björnhjärtats plats"}},{q="Varför behöver Royal Apothecary Society naturliga djurgifter?",a="Sällskapet söker kraftfulla biologiska ämnen som kan smitta och förstöra både levande vävnad och odöd fysiologi. De unika kemiska egenskaperna i hjärtvävnaden hos Silverpine Forests kraftiga björnar ger en idealisk reaktiv bas när de blandas med virulent spindelblod.",al={"varför använder apotekare björngift","varför djurhjärtan till pest"}}},fx={["9ca08a87"]={q="Vad är ett Grizzled Bear Heart?",a="Det är ett färskt organ som tas från de våldsamma grizzled-björnarna som strövar omkring i Silverpine Forest. Hjärtat ser först ut som ett vanligt organ, men innehåller ett naturligt, motståndskraftigt biologiskt gift som gör det till en lockande ingrediens för alkemiska experiment.",al={"vad är grizzled bear heart","information om björnhjärtat","grizzled bear heart-lore"}}},fp="19,112,28.543.0,39.239.0,28.187.0,40.160.0,65.274.0"}
P.entries["item:grizzled-scalp"] = {n="Grizzled Scalp",s="En Grizzled Scalp är ett tjockt, pälsbeklätt skinn från grizzled thistle bears som strövar i Darkshores södra skogar. Trofén verkar märklig, men den excentriske gnommekanikern Wizbang Cranktoggle vill ha skinnen till sina dolda maskiner i vildmarken.",h="En Grizzled Scalp är ett tjockt, pälsbeklätt skinn från grizzled thistle bears som strövar i Darkshores södra...",kw={"auberdine","buzzbox 525","darkshore","grizzled scalp","grizzled thistle bear","thistle bear beer","wizbang cranktoggle"},ang={["profession:Engineering"]="Buzzbox-nätverket visar gnomernas talang för att kamouflera automatiska bryggpannor som kommunikationsutrustning för fältreparationer.",["race:NightElf"]="Night Elves skyddar Darkshores djurliv och ser med oblida ögon på både hänsynslös tjuvjakt och hemliga gnomiska destilleringsapparater som skräpar ner i vildmarken."},sec={{t="En märklig jäsning",b="Resenärer som jagar längs vägen söder om Auberdine stöter på de väderbitna grizzled thistle bears, kända för sina grova, tjocka skinn. Att flå farliga rovdjur är vardagsmat för vildmarksjägare, men när du lämnar fyra av deras skalper till Buzzbox 525 visar det sig att ändamålet är betydligt mindre ärofullt. Apparaten behöver inte björnpäls för tekniska reparationer eller vetenskapliga analyser. I stället använder gnommekanikern Wizbang Cranktoggle de dolda buzzboxarna som finns utspridda över Darkshore som hemliga destillerier. Eftersom de lokala Night Elves ogillar olovlig ölbryggning i sina bosättningar, förlitar sig Wizbang på godtrogna äventyrare som samlar björnskalper och andra märkliga ingredienser till hans älskade ”thistle bear beer”."}},faq={{q="Var hittar jag Grizzled Scalps?",a="Grizzled Scalps får du från grizzled thistle bears och deras matriark, Den Mother, i skogarna söder om Auberdine längs huvudleden i Darkshore.",al={"plats för grizzled scalp","vem släpper grizzled scalps","thistle bear-skalp"}},{q="Vad används Grizzled Scalps till?",a="De lämnas i Buzzbox 525, en automatisk mekanisk terminal gömd i buskarna längs vägen långt söder om Auberdine.",al={"användning av grizzled scalp","vad gör jag med grizzled scalps"}},{q="Varför behöver Buzzbox 525 björnskalper?",a="Wizbang Cranktoggle använder i hemlighet sitt buzzbox-nätverk för att destillera hembränt utom synhåll för vaksamma Night Elves. Grizzled Scalps är en ingrediens i hans hembryggda thistle bear beer.",al={"varför vill wizbang ha skalper","buzzbox 525:s syfte"}},{q="Varför gömmer Wizbang sin bryggning i Darkshores vildmark?",a="Night Elves som bor i Auberdine uppskattar inte en otillåten, högljudd alkoholförsäljning i sina heliga lundar. Wizbang gömde sina apparater i snåren längs vildmarksvägarna för att kunna driva sin hembräntsverksamhet oupptäckt.",al={"varför gömma buzzbox","wizbangs sprit i darkshore"}}},fx={["903811df"]={q="Vad är en Grizzled Scalp?",a="En Grizzled Scalp är den tjocka, pälsbeklädda hjässan från de tåliga björnar som strövar i Darkshores vildmarker. Dessa härdade bestar uthärdar det hårda nordliga klimatet och utvecklar stryktåliga, borstiga hudar som uppskattas av pälsjägare och nyfikna uppfinnare för sin unika täthet.",al={"vad är grizzled scalp","information om grizzled scalp","berätta om grizzled scalps"}},e940f924={q="Var kommer en Grizzled Scalp ifrån?",a="De här skalperna kommer från de fullvuxna tistelbjörnarna som hör hemma i Darkshore, främst Grizzled Thistle Bears och den våldsamma Den Mother. De är inga tillverkade varor, utan råa troféer som tas direkt från vilddjuren söder om Auberdine.",al={"var kommer grizzled scalps ifrån","grizzled scalps ursprung","vem släpper grizzled scalps"}}},fp="14,173,23.473.1,33.139.0,34.117.0,38.150.1,60.214.1"}
P.entries["item:gryshka-s-letter"] = {n="Gryshka's Letter",s="Innkeeper Gryshka skickar ett tack till Zargh vid The Crossroads efter att ha fått färskt kött. Brevet presenterar också unga Horde-kurirer för vindryttarnas flygnätverk.",h="Innkeeper Gryshka skickar ett tack till Zargh vid The Crossroads efter att ha fått färskt kött.",kw={"the barrens","the crossroads","doras","gryshka","gryshka's letter","kött","orgrimmar","vindryttare","zargh"},ang={["faction:Horde"]="När du lämnar Gryshka's Letter lär sig unga Horde-äventyrare om wyvernernas flygmästarnätverk som förbinder Durotar och The Barrens."},sec={{t="En tacksam värdinna",b="Innkeeper Gryshka tackar Zargh för biffarna han skickar från The Barrens till Orgrimmars centrala värdshus. Hon minns när han förlorade ett finger medan han styckade kött och retas med honom för att han ser stilig ut även när han är blodig efter arbetet."},{t="Bud längs flyglederna",b="För att lämna tillbaka Gryshka's Letter vid The Crossroads beger du dig till Doras, vindryttarmästaren högst uppe på Orgrimmars platå. Visa honom att du redan har anmält dig hos Devrak vid The Crossroads, så presenterar Doras unga kurirer för wyvernernas flygleder som förbinder bosättningar i Durotar och The Barrens."}},faq={{q="Vem skrev Gryshka's Letter?",a="Innkeeper Gryshka, som driver ett värdshus i Orgrimmars Valley of Strength, skrev brevet efter att ha fått färskt kött.",al={"vem skrev detta","författaren till gryshkas brev","avsändare"}},{q="Vem är brevet avsett för?",a="Brevet är adresserat till Zargh, en slaktare vid The Crossroads i The Barrens som försåg Gryshka med kött.",al={"mottagare","vem får gryshkas brev","vart ska brevet"}},{q="Vad står det i brevet?",a="Gryshka tackar Zargh för köttbitarna, minns olyckan då han förlorade ett finger medan han styckade kött och retas med honom för att han ser stilig ut även när han är blodig.",al={"brevets text","vad säger gryshka","brevets innehåll"}},{q="Varför behöver Doras se brevet?",a="Doras är Orgrimmars vindryttarmästare. Gryshka skickar dig för att visa att du har anmält dig hos Devrak vid The Crossroads, så att Doras kan presentera dig för wyvernernas flygleder.",al={"varför visa doras","doras vindryttarmästaren","flygmästare i orgrimmar"}}},fx={["950e527c"]={q="Vad är Gryshka's Letter?",a="Det är ett handskrivet tackbrev från Innkeeper Gryshka i Orgrimmar. Hon skrev det som svar på en särskild köttleverans till hennes värdshus, både för att tacka och för att uttrycka sin tillgivenhet på ett flirtigt sätt. Brevet ska föras tillbaka till The Barrens.",al={"vad är gryshka's letter","föremålet gryshka's letter","om gryshka's letter"}},["0c09fbc7"]={q="Varför vill någon ha Gryshka's Letter?",a="Slaktaren Zargh vid The Crossroads väntar ivrigt på att få veta hur hans förstklassiga kött togs emot. Gryshka vill att brevet levereras för att visa sin innerliga tacksamhet och besvara hans känslor, medan vindryttarmästaren Doras bara behöver bekräfta din destination för att ordna en flygtur tillbaka över The Barrens.",al={"varför ska gryshka's letter levereras","vem vill ha gryshka's letter","varför vill zargh ha gryshka's letter"}}},fp="16,177,20.230.0,30.298.0,27.119.0,31.108.0,34.153.0,38.176.0"}
P.entries["item:gunther-s-spellbook"] = {n="Gunther's Spellbook",s="Gunther's Spellbook är en personlig arkan handbok knuten till en mystisk magiker som bor i Tirisfal Glades. Boken är genomsyrad av en förtrollning från Bethor Iceshard och visar att andra magiutövare har lyckats bryta sig fria från Lich King's kontroll, men den sanna historien mellan dess ägare och Forsaken återstår att nysta upp.",h="Gunther's Spellbook är en personlig arkan handbok knuten till en mystisk magiker som bor i Tirisfal Glades.",kw={"arcanus","bethor","dalaran","gunther","iceshard","kirin tor","handbok","tirisfal"},ang={["class:Mage"]="För arkaniska magiutövare står handboken för de gemensamma rötterna i Dalaran som knyter Forsakens nuvarande magiska ledarskap till självständiga magiutövare i vildmarken.",["race:Undead"]="Den förtrollade boken lyfter fram Forsakens pågående försök att rekrytera mäktiga, självständiga odöda som på egen hand bröt sig fria från Lich King."},sec={{t="En symbol för forna band",b="Före det tredje kriget studerade Gunther Arcanus de arkaniska konsterna i Dalaran tillsammans med Bethor Iceshard och Thule Ravenclaw som medlemmar i Kirin Tor. När de odödas pest svepte över Lordaeron föll Gunther och återuppväcktes som odöd, men lyckades till slut slita sig loss från Scourges grepp om hans sinne. Han trodde att han var ensam och ständigt jagad av Lich King's agenter och förblev därför djupt fientlig mot främlingar. När handboken hade återfunnits lade Bethor Iceshard en arkanisk förtrollning över dess sidor, en avsiktlig magisk signatur som låter Gunther känna igen Bethors närvaro och inse att han inte är den enda magikern med fri vilja."}},faq={{q="Vems handbok är det här?",a="Den tillhör Gunther Arcanus, en mäktig odöd magiker som bor på en isolerad ö i Brightwater Lake i Tirisfal Glades.",al={"vem äger boken","gunthers bokägare","handbokens ägare"}},{q="Varför förtrollade Bethor handboken?",a="Bethor lade en personlig besvärjelse på handboken som ett otvetydigt bevis på att han överlevt i Lordaeron och är fri från Lich King's kontroll. Han hoppas kunna övertyga Gunther om att ingå en allians med Forsaken.",al={"varför förtrolla boken","bethors besvärjelse på boken","bokens magi"}},{q="Varför är Gunther misstänksam när boken återlämnas?",a="Gunther tror att alla som närmar sig hans tillflyktsort är agenter från Scourge som skickats för att åter förslava honom. Till en början tror han bara att The Adventurer är tjuven som tog hans handbok.",al={"varför är gunther arg","gunther arg","gunther fientlig"}},{q="Hur kände Gunther och Bethor varandra?",a="För länge sedan studerade Gunther, Bethor Iceshard och Thule Ravenclaw magi tillsammans som vänner och lärlingar i Kirin Tor i staden Dalaran, innan pesten tog dem.",al={"bethors och gunthers förflutna","koppling till kirin tor","vänner i dalaran"}}},fp="19,153,22.601.1,24.107.1,37.184.0,52.162.0,43.146.1"}
